--
-- Name: can_access_support_object(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_access_support_object(p_name text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'storage'
    AS $_$
declare
  v_folder text;
  v_conversation uuid;
begin
  v_folder := (storage.foldername(p_name))[1];
  if v_folder is null or v_folder !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then return false; end if;
  v_conversation := v_folder::uuid;
  return private.can_access_support_conversation(v_conversation);
exception when others then
  return false;
end;
$_$;


--
-- Name: can_read_support_object(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_read_support_object(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'storage'
    AS $$
  select private.can_access_support_object(p_name)
    and (
      exists(
        select 1 from public.profiles actor
        where actor.auth_id=(select auth.uid())::text
          and actor.role in ('staff','admin','creator')
          and not coalesce(actor.deleted,false)
          and not coalesce(actor.suspended,false)
          and not coalesce(actor.banned,false)
      )
      or not exists(
        select 1 from public.partner_support_messages message
        where message.visibility='internal' and p_name=any(coalesce(message.attachments,'{}'))
      )
    )
$$;


--
-- Name: hotel_booking_quote(integer, date, date, integer, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hotel_booking_quote(p_room_id integer, p_check_in date, p_check_out date, p_exclude_booking_id integer DEFAULT NULL::integer, p_include_live_holds boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_room public.hotel_rooms;
  v_day date;
  v_capacity integer;
  v_reserved integer;
  v_rate numeric;
  v_total numeric := 0;
begin
  if p_check_in is null or p_check_out is null or p_check_out <= p_check_in then
    raise exception 'Choose valid check-in and check-out dates';
  end if;

  select * into v_room
  from public.hotel_rooms
  where room_id = p_room_id
  for update;

  if v_room.room_id is null or coalesce(v_room.total_rooms, 0) < 1
     or coalesce(v_room.price_per_night, 0) <= 0 then
    raise exception 'Room type is not available for booking';
  end if;

  for v_day in
    select generate_series(p_check_in, p_check_out - 1, interval '1 day')::date
  loop
    select
      case when coalesce(i.closed, false) then 0
           else coalesce(i.available_quantity, v_room.total_rooms) end,
      coalesce(i.rate_override, v_room.price_per_night)
    into v_capacity, v_rate
    from (select 1) seed
    left join public.hotel_inventory_daily i
      on i.room_id = v_room.room_id and i.inventory_date = v_day;

    select count(*)::integer into v_reserved
    from public.hotel_bookings hb
    where hb.room_id = v_room.room_id
      and hb.booking_id is distinct from p_exclude_booking_id
      and hb.check_in <= v_day and hb.check_out > v_day
      and (
        hb.status in ('confirmed', 'checked_in')
        or (
          p_include_live_holds
          and hb.status = 'pending'
          and coalesce(hb.payment_expires_at, hb.created_at + interval '30 minutes') > now()
        )
      );

    if coalesce(v_capacity, 0) <= v_reserved then
      return jsonb_build_object(
        'available', false,
        'blocked_date', v_day,
        'capacity', coalesce(v_capacity, 0),
        'reserved', v_reserved
      );
    end if;
    v_total := v_total + v_rate;
  end loop;

  return jsonb_build_object(
    'available', true,
    'nights', p_check_out - p_check_in,
    'total_price', round(v_total, 2)
  );
end;
$$;


--
-- Name: hotel_booking_quote_v2(integer, integer, date, date, integer, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hotel_booking_quote_v2(p_room_id integer, p_rate_plan_id integer, p_check_in date, p_check_out date, p_exclude_booking_id integer DEFAULT NULL::integer, p_include_live_holds boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_room public.hotel_rooms;
  v_plan public.hotel_rate_plans;
  v_day date;
  v_capacity integer;
  v_operational_units integer;
  v_reserved integer;
  v_base_rate numeric;
  v_rate numeric;
  v_total numeric:=0;
begin
  if p_check_in is null or p_check_out is null or p_check_out<=p_check_in then
    raise exception 'Choose valid check-in and check-out dates';
  end if;
  select * into v_room from public.hotel_rooms where room_id=p_room_id for update;
  select * into v_plan from public.hotel_rate_plans
  where rate_plan_id=p_rate_plan_id and room_id=p_room_id and active;
  if v_room.room_id is null or coalesce(v_room.total_rooms,0)<1
     or v_plan.rate_plan_id is null or coalesce(v_plan.price_per_night,0)<=0 then
    raise exception 'Room package is not available for booking';
  end if;

  select count(*)::integer into v_operational_units
  from public.hotel_room_units unit
  where unit.room_id=v_room.room_id
    and unit.status not in ('maintenance','out_of_service');

  for v_day in
    select generate_series(p_check_in,p_check_out-1,interval '1 day')::date
  loop
    select
      least(
        case when coalesce(i.closed,false) then 0
          else coalesce(i.available_quantity,v_room.total_rooms)
        end,
        v_operational_units
      ),
      coalesce(i.rate_override,v_room.price_per_night)
    into v_capacity,v_base_rate
    from (select 1) seed
    left join public.hotel_inventory_daily i
      on i.room_id=v_room.room_id and i.inventory_date=v_day;

    select count(*)::integer into v_reserved
    from public.hotel_bookings hb
    where hb.room_id=v_room.room_id
      and hb.booking_id is distinct from p_exclude_booking_id
      and hb.check_in<=v_day and hb.check_out>v_day
      and (
        hb.status in ('confirmed','checked_in')
        or (
          p_include_live_holds and hb.status='pending'
          and coalesce(hb.payment_expires_at,hb.created_at+interval '30 minutes')>now()
        )
      );
    if coalesce(v_capacity,0)<=v_reserved then
      return jsonb_build_object(
        'available',false,
        'blocked_date',v_day,
        'capacity',coalesce(v_capacity,0),
        'reserved',v_reserved
      );
    end if;
    v_rate:=greatest(1,v_base_rate+(v_plan.price_per_night-v_room.price_per_night));
    v_total:=v_total+v_rate;
  end loop;
  return jsonb_build_object(
    'available',true,
    'nights',p_check_out-p_check_in,
    'total_price',round(v_total,2),
    'rate_plan_id',v_plan.rate_plan_id,
    'rate_plan_name',v_plan.name,
    'meal_plan',v_plan.meal_plan,
    'payment_timing',v_plan.payment_timing,
    'refundable',v_plan.refundable,
    'cancellation_hours',v_plan.cancellation_hours
  );
end;
$$;


