CREATE TABLE public.hotel_pms_providers (
    provider_key text NOT NULL,
    display_name text NOT NULL,
    adapter_version text,
    certification_status text DEFAULT 'candidate'::text NOT NULL,
    supported_domains text[] DEFAULT ARRAY[]::text[] NOT NULL,
    certification_evidence_uri text,
    contract_reviewed_at timestamp with time zone,
    security_reviewed_at timestamp with time zone,
    dpa_reviewed_at timestamp with time zone,
    mapping_reviewed_at timestamp with time zone,
    pilot_approved_at timestamp with time zone,
    certified_at timestamp with time zone,
    certified_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hotel_pms_providers_certification_status_check CHECK ((certification_status = ANY (ARRAY['candidate'::text, 'sandbox'::text, 'certified'::text, 'suspended'::text, 'retired'::text]))),
    CONSTRAINT hotel_pms_providers_check CHECK (((certification_status <> 'certified'::text) OR ((NULLIF(btrim(COALESCE(adapter_version, ''::text)), ''::text) IS NOT NULL) AND (NULLIF(btrim(COALESCE(certification_evidence_uri, ''::text)), ''::text) IS NOT NULL) AND (contract_reviewed_at IS NOT NULL) AND (security_reviewed_at IS NOT NULL) AND (dpa_reviewed_at IS NOT NULL) AND (mapping_reviewed_at IS NOT NULL) AND (pilot_approved_at IS NOT NULL) AND (certified_at IS NOT NULL)))),
    CONSTRAINT hotel_pms_providers_display_name_check CHECK ((NULLIF(btrim(display_name), ''::text) IS NOT NULL)),
    CONSTRAINT hotel_pms_providers_provider_key_check CHECK ((provider_key ~ '^[a-z0-9][a-z0-9_-]{1,63}$'::text)),
    CONSTRAINT hotel_pms_providers_supported_domains_check CHECK ((supported_domains <@ ARRAY['rooms'::text, 'rates'::text, 'inventory'::text, 'room_status'::text]))
);


--
-- Name: _certify_hotel_pms_provider(text, text, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._certify_hotel_pms_provider(p_provider_key text, p_display_name text, p_adapter_version text, p_supported_domains text[], p_evidence_uri text, p_certified_by text) RETURNS public.hotel_pms_providers
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_provider public.hotel_pms_providers; v_domains text[];
begin
  select coalesce(array_agg(distinct domain_value order by domain_value),array[]::text[])
    into v_domains from unnest(coalesce(p_supported_domains,array[]::text[])) domain_value;
  if not(v_domains<@array['rooms','rates','inventory','room_status']::text[]) then
    raise exception 'Unsupported PMS authority domain';
  end if;
  insert into public.hotel_pms_providers(
    provider_key,display_name,adapter_version,certification_status,
    supported_domains,certification_evidence_uri,contract_reviewed_at,
    security_reviewed_at,dpa_reviewed_at,mapping_reviewed_at,pilot_approved_at,
    certified_at,certified_by,updated_at
  ) values(
    lower(btrim(p_provider_key)),btrim(p_display_name),btrim(p_adapter_version),
    'certified',v_domains,btrim(p_evidence_uri),now(),now(),now(),now(),now(),
    now(),nullif(btrim(coalesce(p_certified_by,'')),''),now()
  ) on conflict(provider_key) do update set
    display_name=excluded.display_name,adapter_version=excluded.adapter_version,
    certification_status='certified',supported_domains=excluded.supported_domains,
    certification_evidence_uri=excluded.certification_evidence_uri,
    contract_reviewed_at=excluded.contract_reviewed_at,
    security_reviewed_at=excluded.security_reviewed_at,
    dpa_reviewed_at=excluded.dpa_reviewed_at,
    mapping_reviewed_at=excluded.mapping_reviewed_at,
    pilot_approved_at=excluded.pilot_approved_at,
    certified_at=excluded.certified_at,certified_by=excluded.certified_by,
    updated_at=now()
  returning * into v_provider;
  return v_provider;
end;
$$;


--
-- Name: _close_revoked_legal_launch_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._close_revoked_legal_launch_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_setting_key text;
begin
  if new.status='approved' and (new.expires_at is null or new.expires_at>now()) then return new; end if;
  v_setting_key:=case new.gate_key
    when 'worker_marketplace' then 'worker_marketplace_launch_enabled'
    when 'worker_identity_checks' then 'worker_identity_checks_enabled'
    when 'worker_pro_web_sales' then 'worker_pro_sales_enabled'
    when 'worker_pro_ios_sales' then 'worker_pro_ios_sales_enabled'
    when 'worker_pro_android_sales' then 'worker_pro_android_sales_enabled'
    when 'worker_featured_placement' then 'worker_featured_sales_enabled'
    else null
  end;
  if v_setting_key is not null then
    update public.platform_settings set value='false',updated_at=now()
    where key=v_setting_key and lower(btrim(value)) in('true','1','yes','on');
  end if;
  return new;
end;
$$;


--
-- Name: _conversation_route_allowed(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._conversation_route_allowed(p_conversation_id uuid, p_actor_user_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  conversation_row public.conversations;
  actor public.profiles;
  peer public.profiles;
  peer_user_id text;
begin
  select * into actor
  from public.profiles
  where user_id = p_actor_user_id;

  select * into conversation_row
  from public.conversations
  where id = p_conversation_id;

  if actor is null or conversation_row is null then return false; end if;
  if actor.user_id not in (conversation_row.participant_a, conversation_row.participant_b) then
    return false;
  end if;
  if coalesce(conversation_row.status, 'active') in ('archived', 'closed') then
    return false;
  end if;
  if conversation_row.conversation_type <> 'roommate' or actor.account_kind <> 'consumer' then
    return false;
  end if;
  if coalesce(actor.deleted, false)
     or coalesce(actor.suspended, false)
     or coalesce(actor.banned, false) then
    return false;
  end if;

  peer_user_id := case
    when conversation_row.participant_a = actor.user_id then conversation_row.participant_b
    else conversation_row.participant_a
  end;

  select * into peer
  from public.profiles
  where user_id = peer_user_id;

  if peer is null
     or peer.account_kind <> 'consumer'
     or coalesce(peer.deleted, false)
     or coalesce(peer.suspended, false)
     or coalesce(peer.banned, false) then
    return false;
  end if;

  return true;
end;
$$;


--
-- Name: _current_comm_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._current_comm_actor() RETURNS public.profiles
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p FROM public.profiles p
  WHERE p.auth_id=auth.uid()::text
    AND COALESCE(p.deleted,false)=false
    AND COALESCE(p.suspended,false)=false
    AND COALESCE(p.banned,false)=false
  LIMIT 1
$$;


--
-- Name: _ensure_verified_worker_wallet(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ensure_verified_worker_wallet() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if public.user_has_active_workspace(new.user_id,'worker')
     and new.worker_status='verified'
     and new.worker_verified is true then
    insert into public.wallets(
      owner_id,owner_type,available_balance,pending_balance,
      frozen_balance,total_withdrawn
    ) values(new.user_id,'worker',0,0,0,0)
    on conflict(owner_id,owner_type) do nothing;
  end if;
  return new;
end
$$;


--
-- Name: _guard_regulated_platform_launch_setting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._guard_regulated_platform_launch_setting() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_enabled boolean:=lower(btrim(coalesce(new.value,''))) in('true','1','yes','on');
  v_gate_key text;
begin
  v_gate_key:=case new.key
    when 'worker_marketplace_launch_enabled' then 'worker_marketplace'
    when 'worker_identity_checks_enabled' then 'worker_identity_checks'
    when 'worker_pro_sales_enabled' then 'worker_pro_web_sales'
    when 'worker_pro_ios_sales_enabled' then 'worker_pro_ios_sales'
    when 'worker_pro_android_sales_enabled' then 'worker_pro_android_sales'
    when 'worker_featured_sales_enabled' then 'worker_featured_placement'
    else null
  end;
  if v_gate_key is not null and v_enabled
     and not public._legal_launch_gate_is_approved(v_gate_key) then
    raise exception 'Regulated launch gate % has no current recorded approval',v_gate_key;
  end if;
  return new;
end;
$$;


--
-- Name: _guard_worker_profile_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._guard_worker_profile_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.user_has_active_workspace(new.user_id,'worker') then return new; end if;
  if new.worker_status='approved_for_verification' then
    new.worker_status:='profile_under_review';
  elsif new.worker_status='approved' then
    new.worker_status:='pending';
  elsif new.worker_status='declined' then
    new.worker_status:='rejected';
  end if;
  new.worker_verified:=new.worker_status='verified';
  if new.worker_status<>'verified'
     or coalesce(new.deleted,false)
     or coalesce(new.suspended,false)
     or coalesce(new.banned,false) then
    new.available:=false;
  end if;
  return new;
end;
$$;


--
-- Name: _legal_launch_gate_is_approved(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._legal_launch_gate_is_approved(p_gate_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1
    from public.legal_launch_approvals approval
    where approval.gate_key=p_gate_key
      and approval.status='approved'
      and approval.approved_at<=now()
      and (approval.expires_at is null or approval.expires_at>now())
  );
$$;


--
-- Name: _queue_hotel_pms_event(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._queue_hotel_pms_event(p_integration_id uuid, p_idempotency_key text, p_event_type text, p_external_reference text, p_details jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare v_event_id uuid;
begin
  if not public.hotel_integration_runtime_active(p_integration_id) then
    raise exception 'Certified active PMS integration required';
  end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null
     or nullif(btrim(coalesce(p_event_type,'')),'') is null then
    raise exception 'PMS event identity is required';
  end if;
  insert into public.hotel_integration_events(
    integration_id,idempotency_key,direction,event_type,external_reference,
    payload_hash,status,next_attempt_at,details
  ) values(
    p_integration_id,btrim(p_idempotency_key),'outbound',btrim(p_event_type),
    nullif(btrim(coalesce(p_external_reference,'')),''),
    encode(digest(coalesce(p_details,'{}'::jsonb)::text,'sha256'),'hex'),
    'pending',now(),coalesce(p_details,'{}'::jsonb)
  ) on conflict(integration_id,idempotency_key) do update set
    details=public.hotel_integration_events.details
  returning integration_event_id into v_event_id;
  return v_event_id;
end;
$$;


--
-- Name: _set_account_suspension(text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._set_account_suspension(p_actor_user_id text, p_target_user_id text, p_suspended boolean, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_target public.profiles;
begin
  select * into v_target from public.profiles
  where user_id=p_target_user_id for update;
  if v_target.user_id is null then raise exception 'Target account not found'; end if;
  if v_target.user_id=p_actor_user_id then raise exception 'Cannot change your own access'; end if;
  if v_target.role='creator' then raise exception 'Cannot modify Creator'; end if;
  if p_suspended then
    if coalesce(v_target.deleted,false) or coalesce(v_target.banned,false) then
      raise exception 'Deleted or banned accounts cannot be suspended'; end if;
    update public.profiles set suspended=true,suspended_at=now(),
      suspended_by=p_actor_user_id,
      suspended_reason=coalesce(nullif(btrim(p_reason),''),'Administrative suspension'),
      worker_status=case when role='worker' then 'suspended' else worker_status end,
      updated_by=p_actor_user_id,updated_at=now()
    where user_id=p_target_user_id;
  else
    if coalesce(v_target.deleted,false) or coalesce(v_target.banned,false) then
      raise exception 'Deleted or banned accounts cannot be reactivated'; end if;
    if not coalesce(v_target.suspended,false) then
      raise exception 'Account is not suspended'; end if;
    update public.profiles set suspended=false,suspended_at=null,
      suspended_by=null,suspended_reason=null,
      worker_status=case when role='worker' then 'pending' else worker_status end,
      updated_by=p_actor_user_id,updated_at=now()
    where user_id=p_target_user_id;
  end if;
  insert into public.audit_logs(
    action,target_type,target_id,details,admin_id
  ) values(case when p_suspended then 'SUSPEND' else 'REACTIVATE' end,
    'profiles',p_target_user_id,jsonb_build_object('reason',nullif(btrim(p_reason),''))::text,
    p_actor_user_id);
end
$$;


--
-- Name: _set_hotel_pms_integration_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._set_hotel_pms_integration_status(p_integration_id uuid, p_status text, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if p_status not in ('paused','error','revoked') then
    raise exception 'Only pause, error or revoke is allowed here';
  end if;
  update public.hotel_integrations set
    status=p_status,last_error=nullif(btrim(coalesce(p_reason,'')),''),
    revoked_at=case when p_status='revoked' then now() else revoked_at end,
    updated_at=now()
  where integration_id=p_integration_id;
  if not found then raise exception 'PMS integration not found'; end if;
  return true;
end;
$$;


--
-- Name: _sync_conversation_after_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._sync_conversation_after_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  c public.conversations;
  v_preview text;
  v_type text;
BEGIN
  SELECT * INTO c FROM public.conversations WHERE id=NEW.conversation_id FOR UPDATE;
  IF c IS NULL THEN RETURN NEW; END IF;

  IF NULLIF(BTRIM(COALESCE(NEW.content,'')),'') IS NOT NULL THEN
    v_preview:=BTRIM(NEW.content);
  ELSIF COALESCE(cardinality(NEW.attachments),0)>0 THEN
    v_type:=COALESCE(NEW.attachment_types[1],'');
    IF v_type LIKE 'image/%' THEN v_preview:='Photo';
    ELSIF v_type LIKE 'audio/%' THEN v_preview:='Voice message';
    ELSE v_preview:='Attachment';
    END IF;
  ELSIF NEW.file_name IS NOT NULL THEN
    v_preview:='Attachment · '||NEW.file_name;
  ELSE
    v_preview:='New message';
  END IF;

  UPDATE public.conversations
  SET last_message=v_preview,
      last_message_at=NEW.created_at,
      unread_a=CASE WHEN c.participant_a=NEW.sender_id THEN c.unread_a ELSE COALESCE(c.unread_a,0)+1 END,
      unread_b=CASE WHEN c.participant_b=NEW.sender_id THEN c.unread_b ELSE COALESCE(c.unread_b,0)+1 END
  WHERE id=NEW.conversation_id;
  RETURN NEW;
END;
$$;


--
-- Name: _valid_reaction(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._valid_reaction(p_emoji text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select char_length(btrim(p_emoji)) between 1 and 8
    and btrim(p_emoji) !~ '[[:alnum:][:space:]]';
$$;


--
-- Name: _worker_review_trust_payload(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._worker_review_trust_payload(p_worker_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_worker public.profiles;
  v_ver public.worker_verifications;
  v_identity public.worker_identity_checks;
  v_payment boolean:=false;
begin
  select * into v_worker from public.profiles
  where user_id=p_worker_id and public.user_has_active_workspace(user_id,'worker') limit 1;
  if v_worker.user_id is null then raise exception 'Worker not found'; end if;
  select * into v_ver from public.worker_verifications
  where worker_id=p_worker_id limit 1;
  select * into v_identity from public.worker_identity_checks
  where worker_id=p_worker_id;
  select exists(select 1 from public.booking_payments
    where user_id=p_worker_id and purpose='worker_verification'
      and status in('paid','completed')) into v_payment;
  return jsonb_build_object(
    'payment_confirmed',v_payment,
    'identity_status',case when public.worker_identity_is_current(p_worker_id)
      then 'passed' else coalesce(v_identity.status,'not_started') end,
    'identity_captured',coalesce(v_identity.status='passed',false),
    'identity_passed',public.worker_identity_is_current(p_worker_id),
    'face_match_score',v_identity.face_match_score,
    'liveness_score',v_identity.liveness_score,
    'anti_spoof_score',v_identity.anti_spoof_score,
    'readiness_passed',true,'readiness_percent',100,
    'evidence_saved',coalesce(nullif(btrim(coalesce(v_ver.verification_video_url,'')),'') is not null,false),
    'certificate_path',v_ver.certificate_path,
    'verification_video_url',v_ver.verification_video_url,
    'submitted',coalesce(v_ver.submitted_at is not null,false),
    'review_status',v_ver.status
  );
end
$$;


--
-- Name: accept_current_legal(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_current_legal(p_document text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user text:=public.current_profile_user_id();
  v_documents jsonb;
  v_policy_id uuid;
  v_version text;
begin
  if v_user is null then raise exception 'Authentication required'; end if;
  if p_document not in('privacy','terms') then
    raise exception 'Invalid legal document';
  end if;
  v_documents:=public.get_current_legal_documents();
  v_policy_id:=nullif(v_documents#>>array[p_document,'policy_version_id'],'')::uuid;
  if v_policy_id is null then raise exception 'Legal document is not published'; end if;
  insert into public.policy_acceptance_receipts(
    user_id,policy_version_id,presentation,locale,source
  ) values(
    v_user,v_policy_id,'full_document_checkbox',
    coalesce(v_documents#>>array[p_document,'locale'],'en-NG'),'account'
  ) on conflict do nothing;
  if p_document='privacy' then
    update public.profiles set privacy_accepted_at=now(),updated_at=now()
    where user_id=v_user;
  else
    update public.profiles set terms_accepted_at=now(),updated_at=now()
    where user_id=v_user;
  end if;
  if (public.get_my_legal_status()->>'privacy_accepted')::boolean
    and (public.get_my_legal_status()->>'terms_accepted')::boolean then
    v_version:='privacy:'||coalesce(v_documents#>>'{privacy,version}','-')
      ||'|terms:'||coalesce(v_documents#>>'{terms,version}','-');
    update public.profiles set legal_accepted_version=v_version,updated_at=now()
    where user_id=v_user;
  end if;
  return public.get_my_legal_status();
end
$$;


--
-- Name: accept_current_worker_pro_terms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_current_worker_pro_terms() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_worker_id text;
  v_terms_version text:='';
  v_terms_content text:='';
  v_terms_sha256 text;
  v_accepted_at timestamptz;
begin
  select profile.user_id into v_worker_id
  from public.profiles profile
  where profile.auth_id=(select auth.uid())::text
    and public.user_has_active_workspace(profile.user_id,'worker')
    and profile.worker_status='verified'
    and profile.worker_verified=true
    and not coalesce(profile.deleted,false)
    and not coalesce(profile.suspended,false)
    and not coalesce(profile.banned,false)
  limit 1;
  if v_worker_id is null then raise exception 'A WeHouse Reviewed Worker account is required'; end if;
  select coalesce(value,'') into v_terms_version from public.platform_settings where key='worker_pro_terms_version' and is_active=true limit 1;
  select coalesce(value,'') into v_terms_content from public.platform_settings where key='worker_pro_terms_content' and is_active=true limit 1;
  if nullif(btrim(v_terms_version),'') is null or length(btrim(v_terms_content))<100 then
    raise exception 'Paid Worker subscription terms are not published';
  end if;
  v_terms_sha256:=encode(extensions.digest(convert_to(v_terms_content,'UTF8'),'sha256'),'hex');
  insert into public.worker_pro_terms_acceptances(worker_id,terms_version,terms_sha256,accepted_at)
  values(v_worker_id,btrim(v_terms_version),v_terms_sha256,now())
  on conflict(worker_id,terms_version,terms_sha256) do nothing
  returning accepted_at into v_accepted_at;
  if v_accepted_at is null then
    select accepted_at into v_accepted_at from public.worker_pro_terms_acceptances
    where worker_id=v_worker_id and terms_version=btrim(v_terms_version)
      and terms_sha256=v_terms_sha256;
  end if;
  return jsonb_build_object(
    'success',true,'terms_version',btrim(v_terms_version),
    'terms_sha256',v_terms_sha256,'accepted_at',v_accepted_at
  );
end;
$$;


--
-- Name: accept_effective_policy(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_effective_policy(p_policy_version_id uuid, p_presentation text, p_locale text DEFAULT 'en-NG'::text, p_source text DEFAULT 'account'::text, p_subject_type text DEFAULT NULL::text, p_subject_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_user text:=public.current_profile_user_id(); v_id uuid;
begin
  if v_user is null then raise exception 'Authentication required'; end if;
  if not exists(
    select 1 from public.creator_policy_versions p
    where p.policy_version_id=p_policy_version_id
      and p.status='active' and p.effective_from<=now()
      and (p.effective_until is null or p.effective_until>now())
  ) then raise exception 'Policy version is not effective'; end if;
  insert into public.policy_acceptance_receipts(
    user_id,policy_version_id,lifecycle_subject_type,lifecycle_subject_id,
    presentation,locale,source
  ) values(
    v_user,p_policy_version_id,p_subject_type,p_subject_id,
    p_presentation,coalesce(nullif(p_locale,''),'en-NG'),p_source
  ) on conflict do nothing
  returning receipt_id into v_id;
  if v_id is null then
    select receipt_id into v_id from public.policy_acceptance_receipts
    where user_id=v_user and policy_version_id=p_policy_version_id
      and lifecycle_subject_type is not distinct from p_subject_type
      and lifecycle_subject_id is not distinct from p_subject_id
    order by accepted_at limit 1;
  end if;
  return v_id;
end
$$;


--
-- Name: account_identity_is_current(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_identity_is_current(p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1 from public.worker_identity_checks c
    where c.worker_id=p_user_id and c.status='passed' and c.captured_at is not null
      and c.captured_at + make_interval(days=>public.account_identity_recheck_days()) > now()
  )
$$;


--
-- Name: account_identity_recheck_days(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_identity_recheck_days() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ select 30 $$;


