    material_process_started_at timestamp with time zone,
    verified_handover_at timestamp with time zone,
    handover_confirmed_by_customer_at timestamp with time zone,
    checked_in_at timestamp with time zone,
    checked_out_at timestamp with time zone,
    year_one_rent_protection_id uuid,
    stay_payment_protection_id uuid,
    caution_payment_protection_id uuid,
    reservation_policy_version_id uuid,
    commission_policy_version_id uuid,
    occupant_count integer DEFAULT 1 NOT NULL,
    cancellation_stage text,
    cancellation_calculation jsonb,
    shared_payment_group_id uuid,
    arrival_issue_policy_version_id uuid,
    arrival_issue_window_hours integer,
    arrival_issue_deadline_at timestamp with time zone,
    CONSTRAINT reservations_arrival_issue_window_hours_check CHECK (((arrival_issue_window_hours IS NULL) OR ((arrival_issue_window_hours >= 2) AND (arrival_issue_window_hours <= 4)))),
    CONSTRAINT reservations_guest_count_check CHECK ((guest_count >= 1)),
    CONSTRAINT reservations_inspection_result_check CHECK ((inspection_result = ANY (ARRAY[NULL::text, 'passed'::text, 'failed'::text, 'customer_declined'::text]))),
    CONSTRAINT reservations_installment_count_check CHECK (((installment_count >= 0) AND (installment_count <= 64))),
    CONSTRAINT reservations_occupant_count_check CHECK ((occupant_count >= 1)),
    CONSTRAINT reservations_rent_payment_status_check CHECK ((rent_payment_status = ANY (ARRAY['not_started'::text, 'payment_pending'::text, 'upfront_paid'::text, 'paid'::text, 'refunded'::text]))),
    CONSTRAINT reservations_reservation_type_check CHECK ((reservation_type = ANY (ARRAY['apartment'::text, 'hotel'::text]))),
    CONSTRAINT reservations_security_deposit_status_check CHECK ((security_deposit_status = ANY (ARRAY['not_required'::text, 'pending'::text, 'held'::text, 'refund_due'::text, 'returned'::text, 'review'::text]))),
    CONSTRAINT reservations_short_stay_dates_check CHECK (((stay_type IS DISTINCT FROM 'short_let'::text) OR ((stay_check_in IS NOT NULL) AND (stay_check_out IS NOT NULL) AND (stay_check_out > stay_check_in) AND (stay_nights > 0)))),
    CONSTRAINT reservations_status_check CHECK ((status = ANY (ARRAY['payment_pending'::text, 'reserved'::text, 'inspection_pending'::text, 'ready_for_move_in'::text, 'occupied'::text, 'completed'::text, 'cancelled'::text, 'expired'::text, 'refunded'::text, 'payment_conflict'::text]))),
    CONSTRAINT reservations_stay_type_check CHECK (((stay_type IS NULL) OR (stay_type = ANY (ARRAY['short_let'::text, 'long_stay'::text]))))
);


--
-- Name: activate_apartment_tenancy(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_apartment_tenancy(p_reservation_id text, p_start_date date DEFAULT CURRENT_DATE) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_res public.reservations;
  v_listing public.listings;
  v_years integer;
  v_grace integer;
  v_end date;
  v_result public.reservations;
  v_rent_payment_id uuid;
  v_plan_id uuid;
  v_target_year integer;
  v_i integer;
  v_due date;
  v_base numeric;
  v_amount numeric;
  v_annual numeric;
BEGIN
  SELECT * INTO v_actor
  FROM public.profiles
  WHERE auth_id=auth.uid()::text
    AND role IN ('staff','admin','creator')
    AND COALESCE(deleted,false)=false
    AND COALESCE(suspended,false)=false
    AND COALESCE(banned,false)=false
  LIMIT 1;
  IF v_actor.user_id IS NULL THEN RAISE EXCEPTION 'Housing operations access required'; END IF;
  IF v_actor.role='staff' AND NOT public.current_staff_has_permission('operations') THEN RAISE EXCEPTION 'Operations permission required'; END IF;

  SELECT * INTO v_res FROM public.reservations WHERE id=p_reservation_id FOR UPDATE;
  IF v_res.id IS NULL THEN RAISE EXCEPTION 'Reservation not found'; END IF;
  SELECT * INTO v_listing FROM public.listings WHERE id::text=v_res.listing_id FOR UPDATE;
  IF v_listing.id IS NULL THEN RAISE EXCEPTION 'Listing not found'; END IF;
  IF COALESCE(v_listing.sub_type,'long_stay')<>'long_stay' THEN RAISE EXCEPTION 'Long-stay tenancy activation is not valid for Short Stay'; END IF;
  IF v_actor.role<>'creator' AND NOT public.current_actor_in_scope(v_listing.state,v_listing.city) THEN RAISE EXCEPTION 'Listing is outside your assigned State/LGA'; END IF;
  IF v_res.status<>'ready_for_move_in' THEN RAISE EXCEPTION 'Inspection must pass before move-in'; END IF;
  IF v_res.manual_payment_status NOT IN ('paid','completed') OR v_res.paid_at IS NULL THEN RAISE EXCEPTION 'Reservation fee is not confirmed'; END IF;
  IF v_res.rent_payment_status NOT IN ('paid','upfront_paid') OR v_res.rent_paid_at IS NULL THEN RAISE EXCEPTION 'Year 1 rent must be verified before move-in'; END IF;

  v_years:=COALESCE(v_res.rental_plan_years,1);
  IF v_years < 1 OR v_years > 5 THEN RAISE EXCEPTION 'Rental tenure must be between 1 and 5 years'; END IF;
  SELECT NULLIF(value,'')::integer INTO v_grace
  FROM public.platform_settings
  WHERE key='tenancy_grace_days' AND COALESCE(is_active,true)=true
  LIMIT 1;
  IF v_grace IS NULL OR v_grace<0 OR v_grace>30 THEN v_grace:=7; END IF;
  v_end:=(p_start_date+make_interval(years=>v_years))::date;

  UPDATE public.reservations
  SET status='occupied',tenancy_start_date=p_start_date,tenancy_end_date=v_end,
      move_out_grace_until=v_end+v_grace,occupancy_started_at=now(),updated_at=now()
  WHERE id=v_res.id
  RETURNING * INTO v_result;

  UPDATE public.listings
  SET status='occupied',availability_status='occupied',occupied_by=v_res.user_id,occupied_at=now(),tenancy_ends_at=v_end,
      reserved_by=NULL,reservation_expiry=NULL,current_reservation_id=v_res.id,updated_at=now()
  WHERE id=v_listing.id;

  UPDATE public.rent_plans
  SET tenancy_start_date=p_start_date,updated_at=now()
  WHERE reservation_id=v_res.id AND status='active';

  IF v_years>1 THEN
    SELECT id INTO v_plan_id
    FROM public.rent_plans
    WHERE reservation_id=v_res.id AND status='active'
    LIMIT 1;
    IF v_plan_id IS NULL THEN RAISE EXCEPTION 'Future-rent plan is missing'; END IF;

    v_annual:=round(COALESCE(v_res.annual_rent_snapshot,v_listing.price),2);
    v_base:=trunc(v_annual/8.0,2);

    FOR v_target_year IN 2..v_years LOOP
      FOR v_i IN 1..8 LOOP
        v_due:=(p_start_date+make_interval(years=>v_target_year-2,months=>4+v_i-1))::date;
        v_amount:=CASE WHEN v_i=8 THEN round(v_annual-(v_base*7),2) ELSE v_base END;
        INSERT INTO public.rent_plan_contributions(
          rent_plan_id,reservation_id,amount,status,target_year,installment_number,due_date,created_at,updated_at
        ) VALUES (
          v_plan_id,v_res.id,v_amount,'scheduled',v_target_year,v_i,v_due,now(),now()
        )
        ON CONFLICT (rent_plan_id,target_year,installment_number)
        DO UPDATE SET
          reservation_id=EXCLUDED.reservation_id,
          amount=CASE WHEN public.rent_plan_contributions.status IN ('paid','completed') THEN public.rent_plan_contributions.amount ELSE EXCLUDED.amount END,
          due_date=CASE WHEN public.rent_plan_contributions.status IN ('paid','completed') THEN public.rent_plan_contributions.due_date ELSE EXCLUDED.due_date END,
          updated_at=now();
      END LOOP;
    END LOOP;

    UPDATE public.rent_plans
    SET next_rent_due_date=(
          SELECT min(c.due_date) FROM public.rent_plan_contributions c
          WHERE c.rent_plan_id=v_plan_id AND c.status IN ('scheduled','payment_pending','pending')
        ),
        installment_count=8*(v_years-1),
        installment_balance=round(v_annual*(v_years-1),2),
        target_amount=round(v_annual*(v_years-1),2),
        updated_at=now()
    WHERE id=v_plan_id;
  END IF;

  SELECT id INTO v_rent_payment_id
  FROM public.booking_payments
  WHERE paystack_reference=v_res.rent_payment_reference
    AND purpose='apartment_rent'
    AND status IN ('paid','completed')
  LIMIT 1;
  IF v_rent_payment_id IS NOT NULL
     AND EXISTS(SELECT 1 FROM public.property_partner_earning_releases WHERE payment_id=v_rent_payment_id AND status='pending') THEN
    PERFORM public.release_property_partner_earning(v_rent_payment_id,'long_stay_move_in_confirmed');
  END IF;
  RETURN v_result;
END;
$$;


--
-- Name: activate_due_creator_policy_versions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_due_creator_policy_versions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_due public.creator_policy_versions; v_count integer:=0;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  for v_due in
    select * from public.creator_policy_versions
    where status='scheduled' and effective_from<=now()
    order by effective_from,created_at for update skip locked
  loop
    update public.creator_policy_versions
    set status='retired',effective_until=v_due.effective_from,retired_at=now()
    where policy_key=v_due.policy_key and scope_type=v_due.scope_type
      and scope_key=v_due.scope_key and status='active';
    update public.creator_policy_versions
    set status='active',published_at=coalesce(published_at,now())
    where policy_version_id=v_due.policy_version_id;
    v_count:=v_count+1;
  end loop;
  return v_count;
end
$$;


--
-- Name: activate_due_payout_account_change(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_due_payout_account_change(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_request public.payout_account_change_requests;
  v_account public.bank_accounts;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  select * into v_request from public.payout_account_change_requests
  where request_id=p_request_id for update;
  if v_request.request_id is null then raise exception 'Payout change not found'; end if;
  if v_request.status='active' then
    select * into v_account from public.bank_accounts
    where id=v_request.bank_account_id;
    return jsonb_build_object('status','active','account',to_jsonb(v_account));
  end if;
  if v_request.status not in ('cooling','activation_pending') then
    raise exception 'Payout change cannot be activated from %',v_request.status;
  end if;
  if now()<v_request.cooling_ends_at then
    return jsonb_build_object(
      'status','cooling','cooling_ends_at',v_request.cooling_ends_at
    );
  end if;
  if v_request.fresh_sign_in_verified_at is null
    or v_request.otp_verified_at is null
    or v_request.account_name_confirmed_at is null then
    raise exception 'Payout verification is incomplete';
  end if;

  perform 1 from public.bank_accounts
  where user_id=v_request.user_id and is_active for update;
  update public.bank_accounts
  set is_default=false,
      deactivated_at=case when id<>v_request.bank_account_id then now() else null end,
      updated_at=now()
  where user_id=v_request.user_id and is_active and is_default;
  update public.bank_accounts
  set is_default=true,is_active=true,activated_at=now(),
      deactivated_at=null,updated_at=now()
  where id=v_request.bank_account_id and user_id=v_request.user_id
  returning * into v_account;
  if v_account.id is null then raise exception 'Verified payout account not found'; end if;

  update public.wallets
  set bank_name=v_account.bank_name,
      bank_account_number=v_account.account_number,
      bank_account_name=v_account.account_name,
      paystack_recipient_code=v_account.paystack_recipient_code,
      updated_at=now()
  where owner_id=v_request.user_id;

  update public.payout_account_change_requests
  set status='active',activated_at=now(),updated_at=now()
  where request_id=p_request_id;

  insert into public.financial_audit_logs(
    event_type,user_id,target_user_id,reference_id,reference_type,
    description,metadata
  ) values(
    'bank_account_change',v_request.user_id,v_request.user_id,
    p_request_id::text,'payout_account_change',
    'Verified payout account activated after required controls',
    jsonb_build_object(
      'bank_account_id',v_account.id,
      'replacement',v_request.replacement,
      'cooling_ends_at',v_request.cooling_ends_at
    )
  );
  return jsonb_build_object('status','active','account',to_jsonb(v_account));
end
$$;


--
-- Name: activate_my_property_partner_workspace(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_my_property_partner_workspace() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_profile public.profiles;
  v_partner_code text;
begin
  select * into v_profile
  from public.profiles
  where auth_id=(select auth.uid())::text
    and account_kind='consumer'
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  for update;
  if v_profile.user_id is null then raise exception 'Active Personal account required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_profile.user_id,2));
  insert into public.workspace_role_assignments(
    user_id,workspace_role,scope_type,status,granted_at,created_at,updated_at
  ) values(v_profile.user_id,'property_partner','global','active',now(),now(),now())
  on conflict(user_id,workspace_role) where status='active' do nothing;
  update public.profiles
  set role=case when role='user' then 'property_partner' else role end,
      account_kind='consumer',updated_at=now()
  where user_id=v_profile.user_id;
  v_partner_code:='WHP-'||replace(v_profile.user_id,'WHU-','')||'-'||
    upper(substr(md5(v_profile.user_id||clock_timestamp()::text),1,4));
  insert into public.property_partners(
    profile_id,partner_code,status,commission_rate,total_earnings,
    total_paid_out,properties_count,created_at,updated_at
  ) values(
    v_profile.user_id,v_partner_code,'pending_verification',0,0,0,0,now(),now()
  ) on conflict(profile_id) do nothing;
  return jsonb_build_object('success',true,'workspace','property_partner');
end;
$$;


--
-- Name: activate_my_worker_workspace(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_my_worker_workspace() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_profile public.profiles;
begin
  select * into v_profile
  from public.profiles
  where auth_id=(select auth.uid())::text
    and account_kind='consumer'
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  for update;
  if v_profile.user_id is null then raise exception 'Active Personal account required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_profile.user_id,1));
  insert into public.workspace_role_assignments(
    user_id,workspace_role,scope_type,status,granted_at,created_at,updated_at
  ) values(v_profile.user_id,'worker','global','active',now(),now(),now())
  on conflict(user_id,workspace_role) where status='active' do nothing;
  update public.profiles
  set role=case when role='user' then 'worker' else role end,
      worker_status=coalesce(worker_status,'pending'),account_kind='consumer',updated_at=now()
  where user_id=v_profile.user_id;
  return jsonb_build_object('success',true,'workspace','worker','free',true);
end;
$$;


--
-- Name: activate_short_stay(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_short_stay(p_reservation_id text, p_actual_check_in date DEFAULT CURRENT_DATE) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_res public.reservations;
  v_listing public.listings;
  v_result public.reservations;
  v_protection public.payment_protection_transactions;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and role in ('staff','admin','creator')
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null then raise exception 'Housing Operations access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then
    raise exception 'Operations permission required';
  end if;
  select * into v_res from public.reservations
  where id=p_reservation_id and stay_type='short_let' for update;
  if v_res.id is null then raise exception 'Short Stay reservation not found'; end if;
  select * into v_listing from public.listings
  where id::text=v_res.listing_id or listing_id=v_res.listing_id for update;
  if v_listing.id is null or v_listing.sub_type<>'short_let' then
    raise exception 'Short Stay listing not found';
  end if;
  if v_actor.role<>'creator'
     and not public.current_actor_in_scope(v_listing.state,v_listing.city) then
    raise exception 'Listing is outside your assigned State/LGA';
  end if;
  if v_listing.status<>'available' or v_listing.availability_status<>'available' then
    raise exception 'This Short Stay is not currently open for guest stays';
  end if;
  if v_res.status<>'ready_for_move_in' or v_res.rent_payment_status<>'paid'
     or v_res.rent_paid_at is null then
    raise exception 'Short Stay payment must be verified before check-in';
  end if;
  if p_actual_check_in<v_res.stay_check_in or p_actual_check_in>=v_res.stay_check_out then
    raise exception 'Check-in must fall inside the reserved stay dates';
  end if;
  select * into v_protection from public.payment_protection_transactions
  where id=v_res.stay_payment_protection_id for update;
  if v_protection.id is null or v_protection.protection_state<>'protected' then
    raise exception 'Current Short Stay Payment Protection is required before check-in';
  end if;
  if exists(
    select 1 from public.reservations reservation
    where reservation.listing_id=v_res.listing_id and reservation.id<>v_res.id
      and reservation.stay_type='short_let' and reservation.status='occupied'
      and daterange(reservation.stay_check_in,reservation.stay_check_out,'[)')
        && daterange(v_res.stay_check_in,v_res.stay_check_out,'[)')
  ) then raise exception 'Those Short Stay dates are already occupied'; end if;

  update public.reservations
  set status='occupied',tenancy_start_date=p_actual_check_in,
      tenancy_end_date=v_res.stay_check_out,move_out_grace_until=v_res.stay_check_out,
      occupancy_started_at=now(),checked_in_at=now(),updated_at=now()
  where id=v_res.id returning * into v_result;

  insert into public.obligation_policy_snapshots(
    subject_type,subject_id,policy_version_id,calculated_value
  ) values(
    'short_let',v_res.id,v_result.arrival_issue_policy_version_id,
    jsonb_build_object('arrival_issue_window_hours',v_result.arrival_issue_window_hours,
      'arrival_issue_deadline_at',v_result.arrival_issue_deadline_at,
      'authorized_check_in_at',v_result.checked_in_at)
  ) on conflict(subject_type,subject_id,policy_version_id) do nothing;

  update public.listings set
    status='available',availability_status='available',reserved_by=null,
    reservation_expiry=null,occupied_by=null,occupied_at=null,tenancy_ends_at=null,
    current_reservation_id=null,updated_at=now()
  where id=v_listing.id and status in ('reserved','occupied');
  return v_result;
end
$$;


--
-- Name: active_obligation_visibility(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.active_obligation_visibility(p_actor_user_id text, p_other_user_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'worker_jobs',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',w.id,'status',coalesce(w.canonical_job_state,w.status),
        'payment_protection_id',w.payment_protection_id
      ))
      from public.worker_bookings w
      where p_actor_user_id in (w.user_id,w.worker_id)
        and p_other_user_id in (w.user_id,w.worker_id)
        and coalesce(w.canonical_job_state,w.status) not in (
          'completed','approved_released','cancelled','refunded'
        )
    ),'[]'::jsonb),
    'shared_payments',coalesce((
      select jsonb_agg(distinct jsonb_build_object(
        'id',g.shared_payment_group_id,'status',g.status,
        'reservation_id',g.reservation_id
      ))
      from public.shared_payment_groups g
      join public.shared_payment_members a
        on a.shared_payment_group_id=g.shared_payment_group_id
      join public.shared_payment_members b
        on b.shared_payment_group_id=g.shared_payment_group_id
      where a.user_id=p_actor_user_id and b.user_id=p_other_user_id
        and g.status not in ('expired','cancelled','refunded')
    ),'[]'::jsonb)
  )
$$;


--
-- Name: actor_can_open_case_for_subject(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.actor_can_open_case_for_subject(p_user_id text, p_subject_type text, p_subject_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select
    (p_subject_type='account' and p_subject_id=p_user_id)
    or (p_subject_type='page' and p_subject_id in(
      'explore','bookings','inbox','account','privacy','terms','security'
    ))
    or (p_subject_type='listing' and exists(
      select 1 from public.listings l
      where (l.id::text=p_subject_id or l.listing_id=p_subject_id)
        and l.deleted_at is null
        and (
          (l.status='available' and l.approved_at is not null)
          or p_user_id in(l.owner_id,l.partner_id)
        )
    ))
    or (p_subject_type in('long_let','short_let') and exists(
      select 1 from public.reservations r
      where r.id=p_subject_id and r.user_id=p_user_id
    ))
    or (p_subject_type='hotel' and exists(
      select 1 from public.hotel_bookings h
      where h.booking_id::text=p_subject_id and h.user_id=p_user_id
    ))
    or (p_subject_type='worker_job' and exists(
      select 1 from public.worker_bookings w
      where w.id::text=p_subject_id and p_user_id in(w.user_id,w.worker_id)
    ))
    or (p_subject_type='worker' and p_subject_id=p_user_id)
    or (p_subject_type='inspection' and (
      exists(select 1 from public.user_inspection_requests i
        where i.id::text=p_subject_id and i.user_id=p_user_id)
      or exists(select 1 from public.inspection_requests i
        where i.id::text=p_subject_id
          and p_user_id in(i.owner_id,i.partner_id::text))
    ))
    or (p_subject_type='conversation' and (
      exists(select 1 from public.conversations c
        where c.id::text=p_subject_id and p_user_id in(c.participant_a,c.participant_b))
      or exists(select 1 from public.booking_conversations c
        where c.id::text=p_subject_id and p_user_id in(c.user_id,c.worker_id))
      or exists(select 1 from public.hotel_booking_conversations c
        where c.id::text=p_subject_id and (
          c.guest_user_id=p_user_id or public.hotel_actor_has_capability(c.hotel_id,'stay.message')
        ))
    ))
    or (p_subject_type='shared_payment' and exists(
      select 1 from public.shared_payment_groups g
      left join public.shared_payment_members m
        on m.shared_payment_group_id=g.shared_payment_group_id
      where g.shared_payment_group_id::text=p_subject_id
        and p_user_id in(g.created_by,m.user_id)
    ))
    or (p_subject_type='payout' and (
      exists(select 1 from public.withdrawal_requests w
        where w.id::text=p_subject_id and w.user_id=p_user_id)
      or exists(select 1 from public.withdrawals w
        join public.wallets wallet on wallet.id=w.wallet_id
        where w.id::text=p_subject_id and wallet.owner_id=p_user_id)
      or exists(select 1 from public.payout_account_change_requests r
        where r.request_id::text=p_subject_id and r.user_id=p_user_id)
    ))
$$;


--
-- Name: add_conversation_action(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_conversation_action(p_conversation_id uuid, p_action_type text, p_content text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_msg_id UUID; v_conv partner_support_conversations%ROWTYPE; BEGIN SELECT * INTO v_conv FROM partner_support_conversations WHERE id = p_conversation_id; INSERT INTO partner_support_messages (conversation_id, sender_id, sender_role, content, action_type, action_metadata, created_at) VALUES (p_conversation_id, COALESCE(v_conv.assigned_staff_id, v_conv.partner_id), 'system', p_content, p_action_type, p_metadata, NOW()) RETURNING id INTO v_msg_id; CASE p_action_type WHEN 'field_officer_assigned' THEN UPDATE partner_support_conversations SET status = 'assigned', assigned_field_officer_id = p_metadata->>'officer_id', updated_at = NOW() WHERE id = p_conversation_id; WHEN 'inspection_scheduled' THEN UPDATE partner_support_conversations SET status = 'in_progress', updated_at = NOW() WHERE id = p_conversation_id; WHEN 'listing_created' THEN UPDATE partner_support_conversations SET listing_id = (p_metadata->>'listing_id')::UUID, updated_at = NOW() WHERE id = p_conversation_id; WHEN 'listing_published' THEN UPDATE partner_support_conversations SET status = 'resolved', updated_at = NOW() WHERE id = p_conversation_id; WHEN 'conversation_closed' THEN UPDATE partner_support_conversations SET status = 'closed', closed_at = NOW(), updated_at = NOW() WHERE id = p_conversation_id; ELSE UPDATE partner_support_conversations SET updated_at = NOW() WHERE id = p_conversation_id; END CASE; RETURN v_msg_id; END; $$;


--
-- Name: add_my_worker_showcase_comment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_my_worker_showcase_comment(p_post_id uuid, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_post public.worker_showcase_posts;
  v_id uuid;
  v_body text:=btrim(coalesce(p_body,''));
begin
  select * into v_actor
  from public.profiles
  where auth_id=auth.uid()::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then raise exception 'Sign in to comment'; end if;
  if char_length(v_body) not between 1 and 500 then
    raise exception 'Comment must be between 1 and 500 characters';
  end if;

  select * into v_post
  from public.worker_showcase_posts
  where id=p_post_id and deleted_at is null
    and hidden_at is null and (expires_at is null or expires_at>now());
  if v_post.id is null then raise exception 'Work post is not available'; end if;

  insert into public.worker_showcase_comments(post_id,user_id,body)
  values (p_post_id,v_actor.user_id,v_body)
  returning id into v_id;

  if v_post.worker_id is distinct from v_actor.user_id then
    insert into public.notifications(
      recipient_id,type,title,message,read,related_id,source_type,source_id,
      destination_route,destination_params,event_key,workspace_scope
    ) values (
      v_post.worker_id,'work_post_comment','New showcase comment',
      coalesce(nullif(btrim(v_actor.full_name),''),nullif(btrim(v_actor.username),''),'A WeHouse member')||' commented on your work.',
      false,p_post_id::text,'worker_showcase_comment',v_id::text,'worker_showcase',
      jsonb_build_object('work_post_id',p_post_id,'comment_id',v_id),
      'showcase-comment:'||v_id::text,'worker'
    );
  end if;
  return v_id;
end;
$$;


--
-- Name: admin_appoint_staff(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_appoint_staff(p_target_user_id text, p_module text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_target public.profiles;
  v_domain text:=public.canonical_staff_domain(p_module);
  v_limit integer:=0;
  v_used integer:=0;
  v_lga text;
begin
  if v_domain is null then raise exception 'A valid Staff work area is required'; end if;
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and role='admin'
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null then raise exception 'Admin access required'; end if;
  select * into v_target from public.profiles
  where user_id=p_target_user_id and not coalesce(deleted,false) for update;
  if v_target.user_id is null or v_target.role not in('user','staff') then
    raise exception 'Only a User or existing Staff account can be appointed';
  end if;
  if public.wehouse_state_key(v_target.state)
     <>public.wehouse_state_key(v_actor.assigned_state) then
    raise exception 'Admin can appoint only Users in the assigned State';
  end if;
  v_lga:=coalesce(nullif(btrim(v_target.local_government),''),
    nullif(btrim(v_target.city),''),nullif(btrim(v_actor.assigned_lga),''));
  if v_lga is null then raise exception 'The Staff LGA is required'; end if;
  if v_target.role<>'staff' then
    v_limit:=coalesce(public.get_admin_staff_limit_v2(),0);
    if v_limit>0 then
      select count(*)::integer into v_used from public.profiles p
      where p.role='staff' and not coalesce(p.deleted,false)
        and public.wehouse_state_key(p.assigned_state)
          =public.wehouse_state_key(v_actor.assigned_state);
      if v_used>=v_limit then raise exception 'State Staff appointment limit reached'; end if;
    end if;
    perform public.admin_update_role(p_target_user_id,'staff');
  end if;
  update public.profiles set assigned_state=v_actor.assigned_state,
    assigned_lga=v_lga,updated_by=v_actor.user_id,updated_at=now()
  where user_id=p_target_user_id;
  perform public.manage_staff_permission(p_target_user_id,v_domain,true);
  return true;
end
$$;


--
-- Name: admin_assign_field_officer(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_assign_field_officer(p_inspection_id uuid, p_field_officer_id text, p_scheduled_date date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_ir public.inspection_requests; v_officer public.profiles;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and role in('staff','admin','creator')
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null or (v_actor.role='staff'
    and not public.current_staff_has_permission('property_operations')) then
    raise exception 'Property Operations, Admin or Creator access required';
  end if;
  select * into v_ir from public.inspection_requests where id=p_inspection_id for update;
  if v_ir.id is null then raise exception 'Inspection request not found'; end if;
  if v_ir.access_evidence_status<>'verified' then
    raise exception 'Access evidence must be approved before assigning Field Operations';
  end if;
  if v_actor.role<>'creator'
     and not public.current_actor_in_scope(v_ir.property_state,v_ir.property_city) then
    raise exception 'Inspection is outside your assigned State';
  end if;
  select * into v_officer from public.profiles
  where user_id=p_field_officer_id and role='staff'
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false);
  if v_officer.user_id is null
    or public.wehouse_state_key(v_officer.assigned_state)
      <>public.wehouse_state_key(v_ir.property_state)
    or not exists(select 1 from public.staff_permissions sp
      where sp.staff_id=v_officer.user_id and sp.is_active=true
        and public.canonical_staff_domain(sp.permission)='field_operations') then
    raise exception 'Field Operations member must be active and assigned to the property State';
  end if;
  update public.inspection_requests set assigned_to=v_officer.user_id,
    field_officer_id=v_officer.user_id,assigned_field_officer_id=v_officer.user_id,
    assigned_at=now(),scheduled_date=p_scheduled_date,status='scheduled',updated_at=now()
  where id=p_inspection_id;
end
$$;


--
-- Name: admin_ban_user(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_ban_user(p_target_user_id text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_target public.profiles;
begin
  v_actor:=public._admin_dashboard_actor();
  if v_actor.role<>'admin' then
    raise exception 'Creator must use recent authenticated oversight'; end if;
  perform public._assert_admin_lga_scope(p_target_user_id);
  select * into v_target from public.profiles where user_id=p_target_user_id for update;
  if v_target.user_id is null or v_target.user_id=v_actor.user_id
     or v_target.role='creator' then raise exception 'Protected account'; end if;
  update public.profiles set banned=true,banned_at=now(),banned_by=v_actor.user_id,
    banned_reason=coalesce(nullif(btrim(p_reason),''),'Account permanently banned'),
    deleted=true,deleted_at=now(),
    worker_status=case when role='worker' then 'suspended' else worker_status end,
    updated_by=v_actor.user_id,updated_at=now() where user_id=p_target_user_id;
  insert into public.audit_logs(action,target_type,target_id,details,admin_id)
  values('BAN','profiles',p_target_user_id,
    jsonb_build_object('reason',coalesce(nullif(btrim(p_reason),''),'Account permanently banned'))::text,
    v_actor.user_id);
end
$$;


--
-- Name: admin_count_branch_announcement_recipients(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_count_branch_announcement_recipients(p_target_roles text[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_count bigint;
begin
  v_actor:=public._admin_dashboard_actor();
  if v_actor.role<>'admin' then raise exception 'Admin account required'; end if;
  select count(*) into v_count from public.profiles p
  where p.user_id<>v_actor.user_id and p.role=any(p_target_roles)
    and not coalesce(p.deleted,false) and not coalesce(p.suspended,false)
    and not coalesce(p.banned,false)
    and public.wehouse_state_key(case when p.role in('admin','staff')
      then p.assigned_state else p.state end)
      =public.wehouse_state_key(v_actor.assigned_state);
  return v_count;
end
$$;


--
-- Name: admin_create_hotel_from_inspection(uuid, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_create_hotel_from_inspection(p_inspection_id uuid, p_name text, p_description text DEFAULT NULL::text, p_images text[] DEFAULT ARRAY[]::text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_ir public.inspection_requests; v_id INTEGER;
BEGIN
 SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
 IF v_actor IS NULL OR v_actor.role NOT IN ('admin','creator','staff') THEN RAISE EXCEPTION 'WeHouse operations access required'; END IF;
 IF v_actor.role='staff' AND NOT public.current_staff_has_permission('operations') THEN RAISE EXCEPTION 'Operations permission required'; END IF;
 SELECT * INTO v_ir FROM public.inspection_requests WHERE id=p_inspection_id FOR UPDATE;
 IF v_ir IS NULL OR v_ir.property_type<>'hotel' OR v_ir.status NOT IN ('completed','approved') THEN RAISE EXCEPTION 'Completed hotel inspection required'; END IF;
 IF v_actor.role IN ('admin','staff') AND (v_ir.property_state IS DISTINCT FROM v_actor.assigned_state OR v_ir.property_city IS DISTINCT FROM v_actor.assigned_lga) THEN RAISE EXCEPTION 'Hotel is outside your assigned branch'; END IF;
 IF v_ir.draft_hotel_id IS NOT NULL THEN RAISE EXCEPTION 'A hotel has already been prepared from this inspection'; END IF;
 IF NULLIF(BTRIM(p_name),'') IS NULL THEN RAISE EXCEPTION 'Hotel name is required'; END IF;
 INSERT INTO public.hotels(name,description,state,city,address,images,amenities,owner_id,status,featured,gps_latitude,gps_longitude,inspection_request_id,created_at,updated_at)
 VALUES(BTRIM(p_name),NULLIF(BTRIM(p_description),''),v_ir.property_state,v_ir.property_city,v_ir.property_address,COALESCE(p_images,ARRAY[]::TEXT[]),ARRAY[]::TEXT[],v_ir.owner_id,'draft',false,v_ir.gps_latitude,v_ir.gps_longitude,v_ir.id,NOW(),NOW()) RETURNING hotel_id INTO v_id;
 UPDATE public.inspection_requests SET draft_hotel_id=v_id,updated_at=NOW() WHERE id=v_ir.id;
 RETURN v_id;
END $$;


--
-- Name: admin_get_all_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_all_users() RETURNS SETOF public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;
begin
  v_actor:=public._admin_dashboard_actor();
  return query
  select (jsonb_populate_record(
    null::public.profiles,
    to_jsonb(p)-array['auth_id','creator_auth_password','creator_auth_enabled',
      'worker_gov_id_url','maintenance_exempt','created_by','updated_by']::text[]
  )).*
  from public.profiles p
  where p.deleted_at is null and p.role<>'creator'
    and (v_actor.role='creator' or public.wehouse_state_key(
      case when p.role in('admin','staff') then p.assigned_state else p.state end
    )=public.wehouse_state_key(v_actor.assigned_state))
  order by p.created_at desc;
end
$$;


--
-- Name: admin_get_all_workers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_all_workers() RETURNS SETOF public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;
begin
  v_actor:=public._admin_dashboard_actor();
  return query
  select jsonb_populate_record(null::public.profiles,
    to_jsonb(p)-array['auth_id','creator_auth_password','creator_auth_enabled',
      'worker_gov_id_url','maintenance_exempt','created_by','updated_by']::text[])
  from public.profiles p
  where public.user_has_active_workspace(p.user_id,'worker') and p.deleted_at is null
    and (v_actor.role='creator' or public.wehouse_state_key(p.state)
      =public.wehouse_state_key(v_actor.assigned_state))
  order by p.created_at desc;
end
$$;


--
-- Name: admin_get_field_officers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_field_officers() RETURNS SETOF public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles;
BEGIN
  v_actor:=public._admin_dashboard_actor();
  RETURN QUERY
  SELECT jsonb_populate_record(NULL::public.profiles,
    to_jsonb(p)-ARRAY['auth_id','creator_auth_password','creator_auth_enabled','worker_gov_id_url','maintenance_exempt','created_by','updated_by']::text[])
  FROM public.profiles p
  WHERE p.role='staff' AND p.deleted_at IS NULL
    AND (v_actor.role='creator' OR (p.assigned_state=v_actor.assigned_state AND p.assigned_lga=v_actor.assigned_lga))
    AND EXISTS(SELECT 1 FROM public.staff_permissions sp WHERE sp.staff_id=p.user_id AND sp.permission='field_officer' AND sp.is_active=true)
  ORDER BY p.created_at DESC;
END; $$;


--
-- Name: admin_get_field_officers_for_inspection(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_field_officers_for_inspection(p_inspection_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_ir public.inspection_requests; v_result jsonb;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and role in('staff','admin','creator')
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null or (v_actor.role='staff'
    and not public.current_staff_has_permission('property_operations')) then
    raise exception 'Property Operations, Admin or Creator access required';
  end if;
  select * into v_ir from public.inspection_requests where id=p_inspection_id;
  if v_ir.id is null then raise exception 'Inspection request not found'; end if;
  if v_actor.role<>'creator'
     and not public.current_actor_in_scope(v_ir.property_state,v_ir.property_city) then
    raise exception 'Inspection is outside your assigned State';
  end if;
  select coalesce(jsonb_agg(x order by (x->>'distance_km')::numeric nulls last,
    (x->>'active_inspections')::int,coalesce(x->>'name','')),'[]'::jsonb)
  into v_result from (
    select jsonb_build_object(
      'user_id',p.user_id,'name',coalesce(p.full_name,p.username,p.email),
      'email',p.email,'assigned_state',p.assigned_state,'assigned_lga',p.assigned_lga,
      'active_inspections',(select count(*) from public.inspection_requests q
        where coalesce(q.assigned_field_officer_id,q.field_officer_id,q.assigned_to)=p.user_id
          and q.status in('scheduled','in_progress')),
      'location_captured_at',loc.captured_at,
      'distance_km',case when v_ir.gps_latitude is not null and v_ir.gps_longitude is not null
        and loc.latitude is not null and loc.longitude is not null
        and loc.captured_at>now()-interval '24 hours'
        then round((6371*2*asin(sqrt(
          power(sin(radians((loc.latitude-v_ir.gps_latitude)/2)),2)
          +cos(radians(v_ir.gps_latitude))*cos(radians(loc.latitude))
          *power(sin(radians((loc.longitude-v_ir.gps_longitude)/2)),2)
        )))::numeric,2) else null end
    ) x
    from public.profiles p
    join public.staff_permissions sp on sp.staff_id=p.user_id
      and public.canonical_staff_domain(sp.permission)='field_operations'
      and sp.is_active=true
    left join public.staff_location_presence loc on loc.staff_id=p.user_id
    where p.role='staff' and not coalesce(p.deleted,false)
      and not coalesce(p.suspended,false) and not coalesce(p.banned,false)
      and public.wehouse_state_key(p.assigned_state)=public.wehouse_state_key(v_ir.property_state)
  ) ranked;
  return v_result;
end
$$;


--
-- Name: admin_get_my_branch_listings(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_my_branch_listings(p_status text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_result jsonb;
BEGIN
 v_actor:=public._admin_dashboard_actor();
 SELECT COALESCE(jsonb_agg(to_jsonb(l) ORDER BY l.created_at DESC),'[]'::jsonb) INTO v_result FROM public.listings l
 WHERE l.deleted_at IS NULL AND l.inspection_request_id IS NOT NULL AND (p_status='all' OR l.status=p_status) AND (v_actor.role='creator' OR (l.state=v_actor.assigned_state AND l.city=v_actor.assigned_lga));
 RETURN v_result;
END $$;


--
-- Name: admin_get_my_branch_profiles(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_my_branch_profiles(p_role text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_result jsonb;
begin
  v_actor:=public._admin_dashboard_actor();
  if p_role is not null and p_role not in(
    'user','worker','property_partner','staff','admin'
  ) then raise exception 'Invalid role filter'; end if;
  select coalesce(jsonb_agg(
    to_jsonb(p)-array['auth_id','creator_auth_password','creator_auth_enabled',
      'worker_gov_id_url','maintenance_exempt','created_by','updated_by']::text[]
    order by p.created_at desc
  ),'[]'::jsonb) into v_result
  from public.profiles p
  where not coalesce(p.deleted,false) and p.role<>'creator'
    and (p_role is null or p.role=p_role)
    and (v_actor.role='creator' or public.wehouse_state_key(
      case when p.role in('admin','staff') then p.assigned_state else p.state end
    )=public.wehouse_state_key(v_actor.assigned_state));
  return v_result;
end
$$;


--
-- Name: admin_get_my_branch_reports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_my_branch_reports() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_result jsonb;
BEGIN
  v_actor := public._admin_dashboard_actor();
  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC),'[]'::jsonb)
  INTO v_result
  FROM public.listing_reports r
  LEFT JOIN public.listings l ON (r.listing_id=l.id::text OR r.listing_id=l.listing_id)
  WHERE v_actor.role='creator' OR (l.state=v_actor.assigned_state AND l.city=v_actor.assigned_lga);
  RETURN v_result;
END;
$$;


--
-- Name: admin_get_my_branch_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_my_branch_stats() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;
begin
  v_actor:=public._admin_dashboard_actor();
  return jsonb_build_object(
    'users',(select count(*) from public.profiles p where p.role='user'
      and p.deleted_at is null and not coalesce(p.deleted,false)
      and (v_actor.role='creator' or public.wehouse_state_key(p.state)=public.wehouse_state_key(v_actor.assigned_state))),
    'workers',(select count(*) from public.profiles p where public.user_has_active_workspace(p.user_id,'worker')
      and p.deleted_at is null and not coalesce(p.deleted,false)
      and (v_actor.role='creator' or public.wehouse_state_key(p.state)=public.wehouse_state_key(v_actor.assigned_state))),
    'partners',(select count(*) from public.profiles p where public.user_has_active_workspace(p.user_id,'property_partner')
      and p.deleted_at is null and not coalesce(p.deleted,false)
      and (v_actor.role='creator' or public.wehouse_state_key(p.state)=public.wehouse_state_key(v_actor.assigned_state))),
    'staff',(select count(*) from public.profiles p where p.role='staff'
      and p.deleted_at is null and not coalesce(p.deleted,false)
      and (v_actor.role='creator' or public.wehouse_state_key(p.assigned_state)=public.wehouse_state_key(v_actor.assigned_state))),
    'admins',(select count(*) from public.profiles p where p.role='admin'
      and p.deleted_at is null and not coalesce(p.deleted,false)
      and (v_actor.role='creator' or public.wehouse_state_key(p.assigned_state)=public.wehouse_state_key(v_actor.assigned_state))),
    'listings',(select count(*) from public.listings l where l.deleted_at is null
      and l.status='available' and (v_actor.role='creator' or public.wehouse_state_key(l.state)=public.wehouse_state_key(v_actor.assigned_state))),
    'pending_verifications',(select count(*) from public.profiles p
      where public.user_has_active_workspace(p.user_id,'worker') and p.worker_status in('verification_paid','profile_under_review')
      and p.deleted_at is null and not coalesce(p.deleted,false)
      and (v_actor.role='creator' or public.wehouse_state_key(p.state)=public.wehouse_state_key(v_actor.assigned_state)))
  );
end
$$;


--
-- Name: admin_get_my_branch_worker_booking_summaries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_my_branch_worker_booking_summaries() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_result jsonb;
begin
  v_actor:=public._admin_dashboard_actor();
  select coalesce(jsonb_agg(jsonb_build_object(
    'booking_code',wb.booking_code,'service_type',wb.service_type,
    'status',wb.status,'negotiated_amount',coalesce(wb.negotiated_amount,wb.agreed_amount,0),
    'scheduled_date',wb.scheduled_date,'created_at',wb.created_at,
    'updated_at',wb.updated_at,'worker_name',coalesce(w.full_name,w.username,'Worker'),
    'customer_name',coalesce(c.full_name,c.username,'Customer'),
    'needs_attention',(wb.status in('booking_requested','waiting_payment','completed_pending_approval','disputed')
      or exists(select 1 from public.booking_payments bp where bp.worker_booking_id=wb.id and bp.status='review_required')),
    'has_dispute',wb.status='disputed',
    'payment_review_required',exists(select 1 from public.booking_payments bp where bp.worker_booking_id=wb.id and bp.status='review_required')
  ) order by wb.updated_at desc),'[]'::jsonb) into v_result
  from public.worker_bookings wb
  join public.profiles w on w.user_id=wb.worker_id
  join public.profiles c on c.user_id=wb.user_id
  where v_actor.role='creator' or public.wehouse_state_key(w.state)
    =public.wehouse_state_key(v_actor.assigned_state);
  return v_result;
end
$$;


--
-- Name: admin_get_my_branch_worker_bookings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_my_branch_worker_bookings() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_result jsonb;
begin
  v_actor:=public._admin_dashboard_actor();
  select coalesce(jsonb_agg(to_jsonb(wb) order by wb.created_at desc),'[]'::jsonb)
  into v_result from public.worker_bookings wb
  join public.profiles w on w.user_id=wb.worker_id
  where v_actor.role='creator' or public.wehouse_state_key(w.state)
    =public.wehouse_state_key(v_actor.assigned_state);
  return v_result;
end
$$;


--
-- Name: admin_get_partner_inspections(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_partner_inspections() RETURNS TABLE(id uuid, request_code text, owner_id text, owner_email text, owner_phone text, property_address text, property_city text, property_state text, property_type text, bedrooms integer, bathrooms integer, expected_rent numeric, description text, status text, assigned_to text, field_officer_id text, scheduled_date date, rejection_reason text, notes text, photo_urls text[], created_at timestamp with time zone, updated_at timestamp with time zone, username text, full_name text, phone text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  SELECT ir.id, ir.request_code, ir.owner_id, ir.owner_email, ir.owner_phone,
    ir.property_address, ir.property_city, ir.property_state, ir.property_type,
    ir.bedrooms, ir.bathrooms, ir.expected_rent, ir.description,
    ir.status, ir.assigned_to, ir.field_officer_id, ir.scheduled_date,
    ir.rejection_reason, ir.notes, ir.photo_urls,
    ir.created_at, ir.updated_at, p.username, p.full_name, p.phone
  FROM public.inspection_requests ir
  LEFT JOIN public.profiles p ON p.user_id = ir.owner_id
  WHERE ir.status IN ('pending', 'scheduled', 'in_progress')
  ORDER BY ir.created_at DESC;
$$;


--
-- Name: admin_get_user_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_get_user_count() RETURNS TABLE(total bigint, today bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_actor public.profiles; BEGIN v_actor:=public._admin_dashboard_actor(); RETURN QUERY SELECT COUNT(*)::bigint,COUNT(*) FILTER (WHERE p.created_at>=date_trunc('day',now()))::bigint FROM public.profiles p WHERE p.deleted_at IS NULL AND p.role<>'creator' AND (v_actor.role='creator' OR CASE WHEN p.role IN ('admin','staff') THEN lower(trim(COALESCE(p.assigned_state,'')))=lower(trim(COALESCE(v_actor.assigned_state,''))) AND lower(trim(COALESCE(p.assigned_lga,'')))=lower(trim(COALESCE(v_actor.assigned_lga,''))) ELSE lower(trim(COALESCE(p.state,'')))=lower(trim(COALESCE(v_actor.assigned_state,''))) AND lower(trim(COALESCE(NULLIF(p.local_government,''),NULLIF(p.city,''),'')))=lower(trim(COALESCE(v_actor.assigned_lga,''))) END); END; $$;


