--
-- Name: inspection_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inspection_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_code text NOT NULL,
    owner_id text NOT NULL,
    owner_email text NOT NULL,
    owner_phone text,
    property_address text NOT NULL,
    property_city text NOT NULL,
    property_state text NOT NULL,
    property_type text,
    bedrooms integer,
    bathrooms integer,
    expected_rent numeric(12,2),
    description text,
    status text DEFAULT 'pending'::text,
    assigned_to text,
    scheduled_date date,
    completed_at timestamp with time zone,
    rejection_reason text,
    notes text,
    photo_urls text[] DEFAULT '{}'::text[],
    document_urls text[] DEFAULT '{}'::text[],
    gps_latitude numeric(10,8),
    gps_longitude numeric(11,8),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    partner_id uuid,
    field_officer_id text,
    amenities text[] DEFAULT '{}'::text[],
    assigned_field_officer_id text,
    assigned_at timestamp with time zone,
    inspection_started_at timestamp with time zone,
    inspection_completed_at timestamp with time zone,
    draft_listing_id uuid,
    approved_by text,
    approved_at timestamp with time zone,
    published_at timestamp with time zone,
    location_accuracy_m numeric,
    draft_hotel_id integer,
    submission_batch_id uuid,
    submission_batch_position integer,
    sub_type text,
    security_deposit_amount numeric,
    video_urls text[] DEFAULT ARRAY[]::text[] NOT NULL,
    authority_relationship text,
    access_challenge_code text,
    access_challenge_expires_at timestamp with time zone,
    access_evidence_status text DEFAULT 'required'::text NOT NULL,
    access_evidence_video_path text,
    access_evidence_submitted_at timestamp with time zone,
    access_evidence_verified_at timestamp with time zone,
    access_evidence_verified_by text,
    submission_schema_version integer DEFAULT 1 NOT NULL,
    hotel_program jsonb,
    lifecycle_stage text DEFAULT 'access_required'::text NOT NULL,
    field_photo_urls text[] DEFAULT ARRAY[]::text[] NOT NULL,
    field_video_urls text[] DEFAULT ARRAY[]::text[] NOT NULL,
    final_media_reviewed_at timestamp with time zone,
    final_media_reviewed_by text,
    final_media_sources text[],
    final_hotel_media_sources text[],
    final_room_media_sources jsonb,
    max_guests integer,
    access_evidence_duration_seconds integer,
    field_evidence_review_status text DEFAULT 'not_submitted'::text NOT NULL,
    field_evidence_reviewed_by text,
    field_evidence_reviewed_at timestamp with time zone,
    field_evidence_review_note text,
    property_display_name text,
    CONSTRAINT inspection_requests_access_evidence_status_check CHECK ((access_evidence_status = ANY (ARRAY['required'::text, 'submitted'::text, 'verified'::text, 'rejected'::text]))),
    CONSTRAINT inspection_requests_authority_relationship_check CHECK (((authority_relationship IS NULL) OR (authority_relationship = ANY (ARRAY['owner'::text, 'property_manager'::text, 'agent'::text, 'authorized_representative'::text])))),
    CONSTRAINT inspection_requests_field_evidence_review_status_check CHECK ((field_evidence_review_status = ANY (ARRAY['not_submitted'::text, 'pending'::text, 'accepted'::text, 'changes_requested'::text]))),
    CONSTRAINT inspection_requests_lifecycle_stage_check CHECK ((lifecycle_stage = ANY (ARRAY['access_required'::text, 'access_review'::text, 'inspection_ready'::text, 'inspection'::text, 'awaiting_review'::text, 'ready_to_prepare'::text, 'listing_prepared'::text, 'live'::text, 'changes_requested'::text, 'rejected'::text]))),
    CONSTRAINT inspection_requests_max_guests_check CHECK (((max_guests IS NULL) OR (max_guests >= 1))),
    CONSTRAINT inspection_requests_property_display_name_check CHECK (((property_display_name IS NULL) OR ((char_length(btrim(property_display_name)) >= 2) AND (char_length(btrim(property_display_name)) <= 100)))),
    CONSTRAINT inspection_requests_security_deposit_check CHECK (((security_deposit_amount IS NULL) OR (security_deposit_amount >= (0)::numeric))),
    CONSTRAINT inspection_requests_sub_type_check CHECK (((sub_type IS NULL) OR (sub_type = ANY (ARRAY['short_let'::text, 'long_stay'::text]))))
);


