--
-- Name: admin_publish_inspected_hotel(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_publish_inspected_hotel(p_hotel_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_h public.hotels;
  v_ir public.inspection_requests;
  v_rooms integer;
begin
  select * into v_actor from public.profiles where auth_id = auth.uid()::text limit 1;
  if v_actor is null or v_actor.role not in ('admin','creator') then raise exception 'Admin or Creator access required'; end if;
  select * into v_h from public.hotels where hotel_id = p_hotel_id for update;
  if v_h is null or v_h.inspection_request_id is null then raise exception 'Inspection-linked hotel required'; end if;
  select * into v_ir from public.inspection_requests where id = v_h.inspection_request_id for update;
  if v_actor.role = 'admin' and not public.current_actor_in_scope(v_ir.property_state, v_ir.property_city) then raise exception 'Hotel is outside your assigned branch'; end if;
  if v_ir.final_media_reviewed_at is null then raise exception 'Confirm the hotel and every room gallery before publication'; end if;
  select count(*) into v_rooms from public.hotel_rooms where hotel_id = p_hotel_id;
  if cardinality(coalesce(v_h.images, array[]::text[])) < 1 or v_rooms < 1 then raise exception 'At least one hotel image and one room type are required before publication'; end if;
  if exists (
    select 1 from public.hotel_rooms hr
    where hr.hotel_id = p_hotel_id
      and exists (
        select 1 from jsonb_array_elements(coalesce(v_ir.hotel_program->'room_types', '[]'::jsonb)) submitted_room
        where lower(btrim(submitted_room->>'name')) = lower(btrim(hr.room_type))
          and jsonb_array_length(coalesce(submitted_room->'media', '[]'::jsonb)) > 0
      )
      and cardinality(coalesce(hr.images, array[]::text[])) < 1
  ) then raise exception 'Every submitted room type needs a confirmed public gallery'; end if;
  update public.hotels set status = 'active', approved_by = v_actor.user_id, approved_at = now(), published_at = now(), updated_at = now() where hotel_id = p_hotel_id;
  update public.inspection_requests set status = 'approved', approved_by = v_actor.user_id, approved_at = now(), published_at = now(), updated_at = now() where id = v_ir.id;
end;
$$;


--
-- Name: admin_publish_inspected_listing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_publish_inspected_listing(p_listing_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_listing public.listings;
  v_ir public.inspection_requests;
begin
  select * into v_actor from public.profiles where auth_id = auth.uid()::text limit 1;
  if v_actor is null or v_actor.role not in ('admin','creator') then raise exception 'Admin or Creator access required'; end if;
  select * into v_listing from public.listings where id = p_listing_id and deleted_at is null for update;
  if v_listing is null or v_listing.inspection_request_id is null then raise exception 'Inspection-linked listing required'; end if;
  select * into v_ir from public.inspection_requests where id = v_listing.inspection_request_id for update;
  if v_ir.status not in ('completed','approved') then raise exception 'Inspection is not complete'; end if;
  if v_actor.role = 'admin' and not public.current_actor_in_scope(v_ir.property_state, v_ir.property_city) then raise exception 'Property is outside your assigned branch'; end if;
  if v_ir.final_media_reviewed_at is null then raise exception 'Confirm the final property gallery before publication'; end if;
  if nullif(btrim(v_listing.title),'') is null or coalesce(v_listing.price,0) <= 0 or cardinality(coalesce(v_listing.images,array[]::text[])) < 1 then
    raise exception 'Title, valid price and at least one image are required before publication';
  end if;
  if coalesce(v_listing.property_type,'apartment') = 'apartment' then
    if v_listing.sub_type not in ('short_let','long_stay') then raise exception 'Apartment must be classified as Short Stay or Long Stay before publication'; end if;
    if v_listing.sub_type = 'short_let' and coalesce(v_listing.security_deposit_amount,0) <= 0 then raise exception 'Short Stay requires a refundable security deposit'; end if;
    if v_listing.sub_type = 'short_let' and not ('Furnished' = any(coalesce(v_listing.amenities,array[]::text[]))) then raise exception 'Short Stay apartment must be furnished'; end if;
  end if;
  update public.listings set status = 'available', availability_status = 'available', approved_by = v_actor.user_id, approved_at = now(), rejection_reason = null, updated_at = now() where id = p_listing_id;
  update public.inspection_requests set status = 'approved', approved_by = v_actor.user_id, approved_at = now(), published_at = now(), updated_at = now() where id = v_ir.id;
end;
$$;


--
-- Name: admin_reactivate_user(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reactivate_user(p_target_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;
begin
  v_actor:=public._admin_dashboard_actor();
  if v_actor.role<>'admin' then
    raise exception 'Creator must use recent authenticated oversight'; end if;
  perform public._assert_admin_lga_scope(p_target_user_id);
  perform public._set_account_suspension(
    v_actor.user_id,p_target_user_id,false,null
  );
end
$$;


--
-- Name: admin_resolve_my_branch_report(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_resolve_my_branch_report(p_report_id text, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_report public.listing_reports; v_listing public.listings;
BEGIN
  v_actor := public._admin_dashboard_actor();
  SELECT * INTO v_report FROM public.listing_reports WHERE id=p_report_id FOR UPDATE;
  IF v_report IS NULL THEN RAISE EXCEPTION 'Report not found'; END IF;
  SELECT * INTO v_listing FROM public.listings WHERE id::text=v_report.listing_id OR listing_id=v_report.listing_id LIMIT 1;
  IF v_actor.role='admin' AND (v_listing IS NULL OR v_listing.state IS DISTINCT FROM v_actor.assigned_state OR v_listing.city IS DISTINCT FROM v_actor.assigned_lga) THEN RAISE EXCEPTION 'Report is outside your assigned branch'; END IF;
  IF p_action NOT IN ('resolved','dismissed') THEN RAISE EXCEPTION 'Action must be resolved or dismissed'; END IF;
  UPDATE public.listing_reports SET status=p_action,resolved_by=v_actor.user_id,resolved_at=now() WHERE id=p_report_id;
END;
$$;


--
-- Name: admin_review_my_branch_listing(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_review_my_branch_listing(p_listing_id uuid, p_decision text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_listing public.listings;
BEGIN
 v_actor:=public._admin_dashboard_actor();
 SELECT * INTO v_listing FROM public.listings WHERE id=p_listing_id AND deleted_at IS NULL FOR UPDATE;
 IF v_listing IS NULL OR v_listing.inspection_request_id IS NULL THEN RAISE EXCEPTION 'Only inspection-linked prepared listings can be reviewed'; END IF;
 IF v_actor.role='admin' AND (v_listing.state IS DISTINCT FROM v_actor.assigned_state OR v_listing.city IS DISTINCT FROM v_actor.assigned_lga) THEN RAISE EXCEPTION 'Listing is outside your assigned branch'; END IF;
 IF p_decision='approve' THEN PERFORM public.admin_publish_inspected_listing(p_listing_id);
 ELSIF p_decision='reject' THEN
   IF NULLIF(BTRIM(COALESCE(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Rejection reason is required'; END IF;
   UPDATE public.listings SET status='rejected',availability_status='rejected',rejection_reason=BTRIM(p_reason),updated_at=NOW() WHERE id=p_listing_id;
 ELSE RAISE EXCEPTION 'Decision must be approve or reject'; END IF;
END $$;


--
-- Name: admin_review_my_branch_worker(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_review_my_branch_worker(p_worker_id text, p_decision text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_worker public.profiles; v_ver public.worker_verifications;
begin
  v_actor:=public._admin_dashboard_actor();
  select * into v_worker from public.profiles
  where user_id=p_worker_id and public.user_has_active_workspace(user_id,'worker') and not coalesce(deleted,false)
  for update;
  if v_worker.user_id is null then raise exception 'Worker not found'; end if;
  if v_actor.role='admin' and public.wehouse_state_key(v_worker.state)
     <>public.wehouse_state_key(v_actor.assigned_state) then
    raise exception 'Worker is outside your assigned State';
  end if;
  if v_worker.worker_status<>'profile_under_review' then
    raise exception 'Worker is not in the review queue';
  end if;
  select * into v_ver from public.worker_verifications where worker_id=p_worker_id limit 1;
  if p_decision='approve' then
    if not public.worker_identity_is_current(p_worker_id) then
      raise exception 'The current private face check has not passed'; end if;
    if v_ver.id is null or nullif(btrim(coalesce(v_ver.verification_video_url,'')),'') is null then
      raise exception 'Professional work evidence is incomplete'; end if;
    update public.profiles set worker_status='verified',worker_verified=true,
      available=true,updated_at=now(),updated_by=v_actor.user_id where user_id=p_worker_id;
    update public.worker_verifications set status='verified',reviewed_by=v_actor.user_id,
      reviewed_at=now(),updated_at=now() where id=v_ver.id;
  elsif p_decision='reject' then
    if nullif(btrim(coalesce(p_reason,'')),'') is null then
      raise exception 'Rejection reason is required'; end if;
    update public.profiles set worker_status='rejected',worker_verified=false,
      available=false,updated_at=now(),updated_by=v_actor.user_id where user_id=p_worker_id;
    update public.worker_verifications set status='rejected',reviewed_by=v_actor.user_id,
      review_notes=btrim(p_reason),reviewed_at=now(),updated_at=now() where id=v_ver.id;
  else raise exception 'Decision must be approve or reject'; end if;
  insert into public.worker_verification_reviews(
    worker_id,reviewer_id,reviewer_role,action,rejection_reason
  ) values(p_worker_id,v_actor.user_id,v_actor.role,
    case when p_decision='approve' then 'approved' else 'rejected' end,
    case when p_decision='reject' then btrim(p_reason) end);
end
$$;


--
-- Name: admin_send_branch_announcement(text, text, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_send_branch_announcement(p_title text, p_content text, p_target_roles text[], p_recipient_ids text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor public.profiles;
  v_id integer;
  v_count integer;
  v_roles text[];
begin
  v_actor:=public._admin_dashboard_actor();
  if v_actor.role<>'admin' then raise exception 'Admin account required'; end if;
  if nullif(btrim(coalesce(p_title,'')),'') is null then raise exception 'Announcement title is required'; end if;
  if nullif(btrim(coalesce(p_content,'')),'') is null then raise exception 'Announcement content is required'; end if;
  select coalesce(array_agg(distinct role_name),'{}'::text[]) into v_roles
  from unnest(coalesce(p_target_roles,'{}'::text[])) role_name
  where role_name in ('user','worker','staff','property_partner');
  if coalesce(array_length(v_roles,1),0)=0 then raise exception 'Select at least one recipient type'; end if;

  insert into public.announcements(
    title,content,sender_id,sender_name,sender_role,target_type,target_state,target_lga,
    recipient_count,read_count,created_at
  ) values (
    btrim(p_title),btrim(p_content),v_actor.user_id,
    coalesce(nullif(v_actor.full_name,''),nullif(v_actor.username,''),'WeHouse'),'admin',
    case when p_recipient_ids is null then 'all_users' else 'specific_user' end,
    v_actor.assigned_state,v_actor.assigned_lga,0,0,now()
  ) returning id into v_id;

  insert into public.announcement_recipients(announcement_id,user_id,read_status,delivered_at)
  select v_id,p.user_id,false,now()
  from public.profiles p
  where p.user_id<>v_actor.user_id
    and p.role=any(v_roles)
    and coalesce(p.deleted,false)=false
    and coalesce(p.suspended,false)=false
    and coalesce(p.banned,false)=false
    and case when p.role='staff'
      then lower(btrim(coalesce(p.assigned_state,'')))=lower(btrim(v_actor.assigned_state))
        and lower(btrim(coalesce(p.assigned_lga,'')))=lower(btrim(v_actor.assigned_lga))
      else lower(btrim(coalesce(p.state,'')))=lower(btrim(v_actor.assigned_state))
        and lower(btrim(coalesce(nullif(p.local_government,''),p.city,'')))=lower(btrim(v_actor.assigned_lga))
    end
    and (p_recipient_ids is null or p.user_id=any(p_recipient_ids));
  get diagnostics v_count=row_count;
  if v_count=0 then
    delete from public.announcements where id=v_id;
    raise exception 'No users in your branch match the selected recipients';
  end if;
  update public.announcements set recipient_count=v_count where id=v_id;
  return jsonb_build_object('id',v_id,'recipient_count',v_count);
end;
$$;


--
-- Name: admin_set_inspected_hotel_media(uuid, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_inspected_hotel_media(p_inspection_id uuid, p_hotel_images text[], p_room_galleries jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
  v_room public.hotel_rooms;
  v_hotel_allowed text[];
  v_room_allowed text[];
  v_chosen text[];
  v_value jsonb;
begin
  select * into v_actor from public.profiles
  where auth_id = auth.uid()::text and role in ('admin', 'creator')
    and not coalesce(deleted, false) and not coalesce(suspended, false)
    and not coalesce(banned, false) limit 1;
  if v_actor is null then raise exception 'Final Admin or Creator review required'; end if;

  select * into v_request from public.inspection_requests where id = p_inspection_id for update;
  if v_request is null or v_request.property_type <> 'hotel' or v_request.draft_hotel_id is null then
    raise exception 'Prepared hotel inspection required';
  end if;
  if v_request.lifecycle_stage not in ('listing_prepared', 'live') then
    raise exception 'The hotel must be prepared before its media is selected';
  end if;
  if v_actor.role = 'admin' and not public.current_actor_in_scope(v_request.property_state, v_request.property_city) then
    raise exception 'Hotel is outside your assigned branch';
  end if;
  if jsonb_typeof(coalesce(p_room_galleries, '{}'::jsonb)) <> 'object' then
    raise exception 'Room galleries must be supplied by room';
  end if;

  v_hotel_allowed := array(
    select distinct image_url from unnest(
      coalesce(v_request.photo_urls, array[]::text[]) || coalesce(v_request.field_photo_urls, array[]::text[])
    ) image_url where nullif(btrim(image_url), '') is not null
  );
  if cardinality(coalesce(p_hotel_images, array[]::text[])) < 1 then raise exception 'Choose at least one hotel or field-visit image'; end if;
  if exists (select 1 from unnest(p_hotel_images) chosen where nullif(btrim(chosen), '') is null or not (chosen = any(v_hotel_allowed))) then
    raise exception 'Hotel gallery images must come from the hotel-level or Field Operations submission';
  end if;

  update public.hotels
  set images = array(select distinct image_url from unnest(p_hotel_images) image_url), updated_at = now()
  where hotel_id = v_request.draft_hotel_id;
  if not found then raise exception 'Prepared hotel not found'; end if;

  for v_room in select * from public.hotel_rooms where hotel_id = v_request.draft_hotel_id order by room_id
  loop
    v_value := p_room_galleries -> v_room.room_id::text;
    if v_value is null or jsonb_typeof(v_value) <> 'array' then
      raise exception 'Choose the final gallery for room type %', v_room.room_type;
    end if;
    select coalesce(array_agg(value), array[]::text[]) into v_chosen from jsonb_array_elements_text(v_value);
    select coalesce(array_agg(distinct media_url), array[]::text[]) into v_room_allowed
    from jsonb_array_elements(coalesce(v_request.hotel_program->'room_types', '[]'::jsonb)) submitted_room
    cross join lateral jsonb_array_elements_text(coalesce(submitted_room->'media', '[]'::jsonb)) media_url
    where lower(btrim(submitted_room->>'name')) = lower(btrim(v_room.room_type));

    if cardinality(v_room_allowed) > 0 and cardinality(v_chosen) < 1 then
      raise exception 'Choose at least one submitted image for room type %', v_room.room_type;
    end if;
    if exists (select 1 from unnest(v_chosen) chosen where nullif(btrim(chosen), '') is null or not (chosen = any(v_room_allowed))) then
      raise exception 'Room images for % must come from that submitted room type', v_room.room_type;
    end if;
    update public.hotel_rooms set images = v_chosen, updated_at = now() where room_id = v_room.room_id;
  end loop;

  update public.inspection_requests
  set final_media_reviewed_at = now(), final_media_reviewed_by = v_actor.user_id, updated_at = now()
  where id = v_request.id;
  return true;
end;
$$;


--
-- Name: admin_set_inspected_hotel_media_v2(uuid, text[], text[], jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_inspected_hotel_media_v2(p_inspection_id uuid, p_hotel_source_images text[], p_hotel_public_images text[], p_room_source_galleries jsonb, p_room_public_galleries jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
  v_room public.hotel_rooms;
  v_allowed text[];
  v_sources text[];
  v_public text[];
  v_value jsonb;
  v_index integer;
begin
  select * into v_actor from public.profiles where auth_id=auth.uid()::text and role in ('staff','admin','creator')
    and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor is null then raise exception 'Property Operations access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then raise exception 'Property Operations permission required'; end if;
  select * into v_request from public.inspection_requests where id=p_inspection_id for update;
  if v_request is null or v_request.property_type<>'hotel' or v_request.draft_hotel_id is null then raise exception 'Prepared hotel inspection required'; end if;
  if v_request.lifecycle_stage not in ('listing_prepared','live') then raise exception 'The hotel must be prepared before its media is selected'; end if;
  if v_actor.role='admin' and not public.current_actor_in_scope(v_request.property_state,v_request.property_city) then raise exception 'Hotel is outside your assigned branch'; end if;
  if jsonb_typeof(coalesce(p_room_source_galleries,'{}'::jsonb))<>'object' or jsonb_typeof(coalesce(p_room_public_galleries,'{}'::jsonb))<>'object' then raise exception 'Room galleries must be supplied by room'; end if;

  v_allowed := array(select distinct image_url from unnest(coalesce(v_request.photo_urls,array[]::text[]) || coalesce(v_request.field_photo_urls,array[]::text[])) image_url where nullif(btrim(image_url),'') is not null);
  if cardinality(coalesce(p_hotel_source_images,array[]::text[]))<1 then raise exception 'Choose at least one hotel or field-visit image'; end if;
  if cardinality(p_hotel_source_images)<>cardinality(coalesce(p_hotel_public_images,array[]::text[])) then raise exception 'Every selected hotel image needs one public copy'; end if;
  if exists(select 1 from unnest(p_hotel_source_images) source where nullif(btrim(source),'') is null or not(source=any(v_allowed))) then raise exception 'Hotel gallery images must come from the hotel-level or Field Operations submission'; end if;
  for v_index in 1..cardinality(p_hotel_source_images) loop
    if p_hotel_source_images[v_index] ~* '^https?://' then
      if p_hotel_public_images[v_index] is distinct from p_hotel_source_images[v_index] then raise exception 'Legacy public hotel source mapping is invalid'; end if;
    elsif not public.is_valid_inspection_public_image(p_inspection_id,p_hotel_public_images[v_index]) then raise exception 'A selected private hotel image was not copied into this inspection public gallery'; end if;
  end loop;

  update public.hotels set images=array(select distinct image_url from unnest(p_hotel_public_images) image_url),updated_at=now() where hotel_id=v_request.draft_hotel_id;
  if not found then raise exception 'Prepared hotel not found'; end if;

  for v_room in select * from public.hotel_rooms where hotel_id=v_request.draft_hotel_id order by room_id loop
    v_value:=p_room_source_galleries->v_room.room_id::text;
    if v_value is null or jsonb_typeof(v_value)<>'array' then raise exception 'Choose the final gallery for room type %',v_room.room_type; end if;
    select coalesce(array_agg(value),array[]::text[]) into v_sources from jsonb_array_elements_text(v_value);
    v_value:=p_room_public_galleries->v_room.room_id::text;
    if v_value is null or jsonb_typeof(v_value)<>'array' then raise exception 'Public room gallery is missing for room type %',v_room.room_type; end if;
    select coalesce(array_agg(value),array[]::text[]) into v_public from jsonb_array_elements_text(v_value);
    select coalesce(array_agg(distinct media_url),array[]::text[]) into v_allowed
      from jsonb_array_elements(coalesce(v_request.hotel_program->'room_types','[]'::jsonb)) submitted_room
      cross join lateral jsonb_array_elements_text(coalesce(submitted_room->'media','[]'::jsonb)) media_url
      where lower(btrim(submitted_room->>'name'))=lower(btrim(v_room.room_type));
    if cardinality(v_allowed)>0 and cardinality(v_sources)<1 then raise exception 'Choose at least one submitted image for room type %',v_room.room_type; end if;
    if cardinality(v_sources)<>cardinality(v_public) then raise exception 'Every selected room image needs one public copy for %',v_room.room_type; end if;
    if exists(select 1 from unnest(v_sources) source where nullif(btrim(source),'') is null or not(source=any(v_allowed))) then raise exception 'Room images for % must come from that submitted room type',v_room.room_type; end if;
    if cardinality(v_sources)>0 then
      for v_index in 1..cardinality(v_sources) loop
        if v_sources[v_index] ~* '^https?://' then
          if v_public[v_index] is distinct from v_sources[v_index] then raise exception 'Legacy public room source mapping is invalid'; end if;
        elsif not public.is_valid_inspection_public_image(p_inspection_id,v_public[v_index]) then raise exception 'A selected private room image was not copied into this inspection public gallery'; end if;
      end loop;
    end if;
    update public.hotel_rooms set images=v_public,updated_at=now() where room_id=v_room.room_id;
  end loop;

  update public.inspection_requests set final_hotel_media_sources=array(select distinct source from unnest(p_hotel_source_images) source),final_room_media_sources=p_room_source_galleries,final_media_reviewed_at=now(),final_media_reviewed_by=v_actor.user_id,updated_at=now() where id=v_request.id;
  return true;
end;
$$;


--
-- Name: admin_set_inspected_public_gallery(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_inspected_public_gallery(p_inspection_id uuid, p_images text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
  v_allowed text[];
begin
  select * into v_actor from public.profiles
  where auth_id = auth.uid()::text and role in ('admin', 'creator')
    and not coalesce(deleted, false) and not coalesce(suspended, false)
    and not coalesce(banned, false) limit 1;
  if v_actor is null then raise exception 'Final Admin or Creator review required'; end if;

  select * into v_request from public.inspection_requests where id = p_inspection_id for update;
  if v_request is null then raise exception 'Inspection not found'; end if;
  if v_request.property_type = 'hotel' then raise exception 'Use the hotel and room media review for a hotel'; end if;
  if v_request.lifecycle_stage not in ('listing_prepared', 'live') then
    raise exception 'The listing must be prepared before its public gallery is selected';
  end if;
  if v_actor.role = 'admin' and not public.current_actor_in_scope(v_request.property_state, v_request.property_city) then
    raise exception 'Property is outside your assigned branch';
  end if;

  v_allowed := array(
    select distinct image_url from unnest(
      coalesce(v_request.photo_urls, array[]::text[]) || coalesce(v_request.field_photo_urls, array[]::text[])
    ) image_url where nullif(btrim(image_url), '') is not null
  );
  if cardinality(coalesce(p_images, array[]::text[])) < 1 then raise exception 'Choose at least one submitted property image'; end if;
  if exists (select 1 from unnest(p_images) chosen where nullif(btrim(chosen), '') is null or not (chosen = any(v_allowed))) then
    raise exception 'Public gallery images must come from the Property Partner or Field Operations submission';
  end if;
  if v_request.draft_listing_id is null then raise exception 'Prepared listing not found'; end if;

  update public.listings set images = array(select distinct image_url from unnest(p_images) image_url), updated_at = now()
  where id = v_request.draft_listing_id and deleted_at is null;
  if not found then raise exception 'Prepared listing not found'; end if;

  update public.inspection_requests
  set final_media_reviewed_at = now(), final_media_reviewed_by = v_actor.user_id, updated_at = now()
  where id = v_request.id;
  return true;
end;
$$;


--
-- Name: admin_set_inspected_public_gallery_v2(uuid, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_inspected_public_gallery_v2(p_inspection_id uuid, p_source_images text[], p_public_images text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
  v_allowed text[];
  v_index integer;
begin
  select * into v_actor from public.profiles
  where auth_id=auth.uid()::text and role in ('staff','admin','creator')
    and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false)
  limit 1;
  if v_actor is null then raise exception 'Property Operations access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then raise exception 'Property Operations permission required'; end if;

  select * into v_request from public.inspection_requests where id=p_inspection_id for update;
  if v_request is null then raise exception 'Inspection not found'; end if;
  if v_request.property_type='hotel' then raise exception 'Use the hotel and room media review for a hotel'; end if;
  if v_request.lifecycle_stage not in ('listing_prepared','live') then raise exception 'The listing must be prepared before its public gallery is selected'; end if;
  if v_actor.role='admin' and not public.current_actor_in_scope(v_request.property_state,v_request.property_city) then raise exception 'Property is outside your assigned branch'; end if;
  if v_request.draft_listing_id is null then raise exception 'Prepared listing not found'; end if;

  v_allowed := array(
    select distinct image_url from unnest(coalesce(v_request.photo_urls,array[]::text[]) || coalesce(v_request.field_photo_urls,array[]::text[])) image_url
    where nullif(btrim(image_url),'') is not null
  );
  if cardinality(coalesce(p_source_images,array[]::text[])) < 1 then raise exception 'Choose at least one submitted property image'; end if;
  if cardinality(p_source_images) <> cardinality(coalesce(p_public_images,array[]::text[])) then raise exception 'Every selected source image needs one public copy'; end if;
  if exists(select 1 from unnest(p_source_images) source where nullif(btrim(source),'') is null or not(source=any(v_allowed))) then raise exception 'Public gallery images must come from the Property Partner or Field Operations submission'; end if;

  for v_index in 1..cardinality(p_source_images) loop
    if p_source_images[v_index] ~* '^https?://' then
      if p_public_images[v_index] is distinct from p_source_images[v_index] then raise exception 'Legacy public source mapping is invalid'; end if;
    elsif not public.is_valid_inspection_public_image(p_inspection_id,p_public_images[v_index]) then
      raise exception 'A selected private image was not copied into this inspection public gallery';
    end if;
  end loop;

  update public.listings set images=array(select distinct image_url from unnest(p_public_images) image_url),updated_at=now()
  where id=v_request.draft_listing_id and deleted_at is null;
  if not found then raise exception 'Prepared listing not found'; end if;
  update public.inspection_requests set final_media_sources=array(select distinct source from unnest(p_source_images) source),final_media_reviewed_at=now(),final_media_reviewed_by=v_actor.user_id,updated_at=now() where id=v_request.id;
  return true;
end;
$$;


--
-- Name: admin_suspend_user(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_suspend_user(p_target_user_id text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;
begin
  v_actor:=public._admin_dashboard_actor();
  if v_actor.role<>'admin' then
    raise exception 'Creator must use recent authenticated oversight'; end if;
  perform public._assert_admin_lga_scope(p_target_user_id);
  perform public._set_account_suspension(
    v_actor.user_id,p_target_user_id,true,p_reason
  );
end
$$;


--
-- Name: admin_toggle_exempt(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_toggle_exempt(target_user_id text, exempt boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ begin raise exception 'Recent Creator authentication required'; end $$;


--
-- Name: admin_update_role(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_role(p_target_user_id text, p_new_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_actor public.profiles; v_target public.profiles; BEGIN SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND NOT COALESCE(deleted,false) AND NOT COALESCE(suspended,false) AND NOT COALESCE(banned,false) LIMIT 1; IF v_actor IS NULL OR v_actor.role<>'admin' THEN RAISE EXCEPTION 'Admin access required. Creator must use Team management.'; END IF; SELECT * INTO v_target FROM public.profiles WHERE user_id=p_target_user_id FOR UPDATE; IF v_target IS NULL THEN RAISE EXCEPTION 'Target user not found'; END IF; IF v_target.auth_id=auth.uid()::text THEN RAISE EXCEPTION 'Cannot modify your own role'; END IF; IF v_target.role NOT IN ('user','staff') OR p_new_role NOT IN ('user','staff') THEN RAISE EXCEPTION 'Admin can manage only User and Staff roles'; END IF; PERFORM public._assert_admin_lga_scope(p_target_user_id); IF p_new_role='staff' THEN UPDATE public.profiles SET role='staff',assigned_state=v_actor.assigned_state,assigned_lga=v_actor.assigned_lga,scope='local',updated_by=v_actor.user_id,updated_at=now() WHERE user_id=p_target_user_id; ELSE UPDATE public.profiles SET role='user',assigned_state=NULL,assigned_lga=NULL,scope=NULL,updated_by=v_actor.user_id,updated_at=now() WHERE user_id=p_target_user_id; UPDATE public.staff_permissions SET is_active=false,revoked_at=now() WHERE staff_id=p_target_user_id AND is_active=true; END IF; INSERT INTO public.role_change_history(user_id,user_email,old_role,new_role,changed_by,changed_by_email) VALUES(p_target_user_id,v_target.email,v_target.role,p_new_role,v_actor.user_id,v_actor.email); INSERT INTO public.audit_logs(action,target_type,target_id,details,admin_id,admin_email) VALUES('ROLE_CHANGE','profiles',p_target_user_id,jsonb_build_object('old_role',v_target.role,'new_role',p_new_role,'state',v_actor.assigned_state,'lga',v_actor.assigned_lga)::text,v_actor.user_id,v_actor.email); END; $$;


--
-- Name: caution_claims; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.caution_claims (
    caution_claim_id uuid DEFAULT gen_random_uuid() NOT NULL,
    reservation_id text NOT NULL,
    payment_protection_id uuid,
    deposit_amount numeric(12,2) NOT NULL,
    claimed_amount numeric(12,2) NOT NULL,
    disputed_amount numeric(12,2) NOT NULL,
    undisputed_refund_amount numeric(12,2) NOT NULL,
    reason text NOT NULL,
    status text DEFAULT 'awaiting_guest_response'::text NOT NULL,
    partner_submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    guest_response_due_at timestamp with time zone NOT NULL,
    guest_response text,
    guest_responded_at timestamp with time zone,
    property_facts_reviewed_by text,
    property_facts_reviewed_at timestamp with time zone,
    finance_resolved_by text,
    finance_resolved_at timestamp with time zone,
    partner_award numeric(12,2),
    customer_refund numeric(12,2),
    refund_destination text DEFAULT 'original_payment'::text NOT NULL,
    appeal_due_at timestamp with time zone,
    appeal_reviewer_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    shared_payment_group_id uuid,
    CONSTRAINT caution_claims_check CHECK ((claimed_amount <= deposit_amount)),
    CONSTRAINT caution_claims_check1 CHECK (((disputed_amount + undisputed_refund_amount) = deposit_amount)),
    CONSTRAINT caution_claims_claimed_amount_check CHECK ((claimed_amount > (0)::numeric)),
    CONSTRAINT caution_claims_deposit_amount_check CHECK ((deposit_amount >= (0)::numeric)),
    CONSTRAINT caution_claims_disputed_amount_check CHECK ((disputed_amount >= (0)::numeric)),
    CONSTRAINT caution_claims_exactly_one_protection_source CHECK (((((payment_protection_id IS NOT NULL))::integer + ((shared_payment_group_id IS NOT NULL))::integer) = 1)),
    CONSTRAINT caution_claims_refund_destination_check CHECK ((refund_destination = 'original_payment'::text)),
    CONSTRAINT caution_claims_status_check CHECK ((status = ANY (ARRAY['awaiting_guest_response'::text, 'facts_review'::text, 'finance_review'::text, 'resolved'::text, 'appealed'::text, 'closed'::text]))),
    CONSTRAINT caution_claims_undisputed_refund_amount_check CHECK ((undisputed_refund_amount >= (0)::numeric))
);


--
-- Name: advance_silent_caution_claim_from_service(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_silent_caution_claim_from_service(p_caution_claim_id uuid) RETURNS public.caution_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_claim public.caution_claims;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  update public.caution_claims set
    guest_response='No response received; silence is not admission of liability.',
    status='facts_review',updated_at=now()
  where caution_claim_id=p_caution_claim_id
    and status='awaiting_guest_response' and guest_response_due_at<=now()
  returning * into v_claim;
  if v_claim.caution_claim_id is null then raise exception 'Claim is not due'; end if;
  return v_claim;
end
$$;


--
-- Name: appeal_caution_resolution(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.appeal_caution_resolution(p_caution_claim_id uuid, p_reason text, p_evidence_paths text[] DEFAULT '{}'::text[]) RETURNS public.caution_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id(); v_claim public.caution_claims; v_path text;
begin
  select c.* into v_claim
  from public.caution_claims c
  join public.reservations r on r.id=c.reservation_id
  join public.listings l on l.listing_id=r.listing_id or l.id::text=r.listing_id
  where c.caution_claim_id=p_caution_claim_id
    and v_actor in(r.user_id,l.owner_id,l.partner_id) for update of c;
  if v_claim.caution_claim_id is null then raise exception 'Caution claim not found'; end if;
  if v_claim.status<>'resolved' or v_claim.appeal_due_at is null
    or v_claim.appeal_due_at<now() then raise exception 'The 48-hour appeal window is closed'; end if;
  if nullif(btrim(coalesce(p_reason,'')),'') is null then raise exception 'Appeal reason required'; end if;
  foreach v_path in array coalesce(p_evidence_paths,'{}'::text[]) loop
    insert into public.caution_evidence(
      reservation_id,caution_claim_id,submitted_by,evidence_type,object_path,description
    ) values(v_claim.reservation_id,v_claim.caution_claim_id,v_actor,'appeal',v_path,btrim(p_reason));
  end loop;
  update public.financial_action_outbox set status='manual_review',
    metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
      'superseded_by_appeal',true,'superseded_amount',amount
    ),amount=0,last_error='Superseded by an in-window Caution appeal',updated_at=now()
  where subject_type='caution_claim' and subject_id=p_caution_claim_id::text
    and status='pending' and available_at>now();
  update public.caution_claims set status='appealed',updated_at=now()
  where caution_claim_id=p_caution_claim_id returning * into v_claim;
  return v_claim;
end
$$;


--
-- Name: listings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.listings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
