    title text NOT NULL,
    description text,
    price numeric DEFAULT 0 NOT NULL,
    currency text DEFAULT 'NGN'::text NOT NULL,
    state text,
    city text,
    address text,
    images text[] DEFAULT '{}'::text[],
    bedrooms integer DEFAULT 1,
    bathrooms integer DEFAULT 1,
    availability_status text DEFAULT 'available'::text NOT NULL,
    owner_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'available'::text,
    reserved_by text,
    reservation_expiry timestamp with time zone,
    reservation_fee_paid boolean DEFAULT false,
    chat_unlocked boolean DEFAULT false,
    videos text[] DEFAULT '{}'::text[],
    chat_agent_id text,
    property_type text,
    submitted_by_role text,
    approved_by text,
    approved_at timestamp with time zone,
    rejection_reason text,
    security_deposit_amount numeric(12,2) DEFAULT NULL::numeric,
    partner_id text,
    deleted_at timestamp with time zone,
    sub_type text,
    contact_phone text,
    amenities text[] DEFAULT '{}'::text[],
    inspection_request_id uuid,
    gps_latitude numeric,
    gps_longitude numeric,
    location_accuracy_m numeric,
    current_reservation_id text,
    occupied_by text,
    occupied_at timestamp with time zone,
    tenancy_ends_at date,
    max_guests integer,
    max_occupants integer,
    future_installments_allowed boolean DEFAULT false NOT NULL,
    arrival_issue_window_hours integer DEFAULT 2 NOT NULL,
    CONSTRAINT listings_arrival_issue_window_hours_check CHECK (((arrival_issue_window_hours >= 2) AND (arrival_issue_window_hours <= 4))),
    CONSTRAINT listings_availability_status_check CHECK ((availability_status = ANY (ARRAY['pending_approval'::text, 'available'::text, 'reserved'::text, 'occupied'::text, 'maintenance'::text, 'closed'::text, 'rejected'::text]))),
    CONSTRAINT listings_max_guests_check CHECK (((max_guests IS NULL) OR (max_guests >= 1))),
    CONSTRAINT listings_max_occupants_check CHECK (((max_occupants IS NULL) OR (max_occupants >= 1))),
    CONSTRAINT listings_status_check CHECK ((status = ANY (ARRAY['pending_approval'::text, 'available'::text, 'reserved'::text, 'occupied'::text, 'maintenance'::text, 'closed'::text, 'rejected'::text]))),
    CONSTRAINT listings_sub_type_check CHECK (((sub_type IS NULL) OR (sub_type = ANY (ARRAY['short_let'::text, 'long_stay'::text]))))
);


--
-- Name: approve_listing_internal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_listing_internal(p_listing_id uuid) RETURNS public.listings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ DECLARE v_actor public.profiles; v_listing public.listings; BEGIN SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND role IN ('admin','creator') AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1; IF v_actor IS NULL THEN RAISE EXCEPTION 'Admin or Creator approval required'; END IF; SELECT * INTO v_listing FROM public.listings WHERE id=p_listing_id AND deleted_at IS NULL FOR UPDATE; IF v_listing IS NULL THEN RAISE EXCEPTION 'Listing not found'; END IF; IF v_listing.status<>'pending_approval' THEN RAISE EXCEPTION 'Only pending listings can be approved'; END IF; IF v_actor.role='admin' THEN IF COALESCE(v_listing.submitted_by_role,'') NOT IN ('staff','property_partner') THEN RAISE EXCEPTION 'Admin cannot approve this submission type'; END IF; IF NOT public.current_actor_in_scope(v_listing.state,v_listing.city) THEN RAISE EXCEPTION 'Listing is outside your assigned branch'; END IF; END IF; UPDATE public.listings SET status='available',availability_status='available',approved_by=v_actor.user_id,approved_at=now(),rejection_reason=NULL WHERE id=p_listing_id RETURNING * INTO v_listing; RETURN v_listing; END; $$;


--
-- Name: assert_ledger_transaction_balanced(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_ledger_transaction_balanced() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_transaction_id uuid; v_total numeric; v_count integer;
begin
  v_transaction_id:=case
    when tg_op='DELETE' then old.ledger_transaction_id
    else new.ledger_transaction_id
  end;
  select coalesce(sum(amount),0),count(*)
  into v_total,v_count
  from public.ledger_entries
  where ledger_transaction_id=v_transaction_id;
  if v_count<2 or v_total<>0 then
    raise exception 'Ledger transaction % is not balanced: % entries total %',
      v_transaction_id,v_count,v_total;
  end if;
  return null;
end
$$;


--
-- Name: assign_field_officer(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_field_officer(p_conversation_id uuid, p_staff_id text, p_officer_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN UPDATE partner_support_conversations SET assigned_staff_id = p_staff_id, assigned_field_officer_id = p_officer_id, status = 'assigned', updated_at = NOW() WHERE id = p_conversation_id; INSERT INTO partner_support_messages (conversation_id, sender_id, sender_role, content, action_type, action_metadata, created_at) SELECT p_conversation_id, p_staff_id, 'system', 'Field officer assigned to inspect property', 'field_officer_assigned', jsonb_build_object('officer_id', p_officer_id), NOW(); RETURN FOUND; END; $$;


--
-- Name: assign_partner_inspection(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_partner_inspection(p_inspection_id uuid, p_field_officer_id text, p_scheduled_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_actor record; v_req record; v_officer record;
begin
 select user_id,role,assigned_state,assigned_lga,deleted,suspended,banned into v_actor from public.profiles where auth_id=auth.uid()::text limit 1;
 if v_actor is null or v_actor.role not in ('admin','creator') or coalesce(v_actor.deleted,false) or coalesce(v_actor.suspended,false) or coalesce(v_actor.banned,false) then raise exception 'Admin or Creator access required'; end if;
 select * into v_req from public.inspection_requests where id=p_inspection_id for update;
 if v_req is null then raise exception 'Inspection request not found'; end if;
 if v_req.status not in ('pending','scheduled') then raise exception 'Inspection cannot be assigned at this stage'; end if;
 if v_actor.role='admin' and (lower(coalesce(v_actor.assigned_state,''))<>lower(coalesce(v_req.property_state,'')) or lower(coalesce(v_actor.assigned_lga,''))<>lower(coalesce(v_req.property_city,''))) then raise exception 'Inspection is outside your assigned branch'; end if;
 select p.user_id,p.assigned_state,p.assigned_lga into v_officer from public.profiles p where p.user_id=p_field_officer_id and p.role='staff' and coalesce(p.deleted,false)=false and coalesce(p.suspended,false)=false and coalesce(p.banned,false)=false and exists(select 1 from public.staff_permissions sp where sp.staff_id=p.user_id and sp.permission='field_officer' and sp.is_active=true);
 if v_officer is null then raise exception 'Eligible Field Officer not found'; end if;
 if lower(coalesce(v_officer.assigned_state,''))<>lower(coalesce(v_req.property_state,'')) or lower(coalesce(v_officer.assigned_lga,''))<>lower(coalesce(v_req.property_city,'')) then raise exception 'Field Officer must belong to the property branch'; end if;
 update public.inspection_requests set assigned_to=p_field_officer_id,field_officer_id=p_field_officer_id,assigned_field_officer_id=p_field_officer_id,assigned_at=now(),scheduled_date=p_scheduled_date,status='scheduled',updated_at=now() where id=p_inspection_id;
end $$;


--
-- Name: assign_reservation_field_officer(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_reservation_field_officer(p_reservation_id text, p_field_officer_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_res public.reservations;
  v_listing public.listings;
  v_officer public.profiles;
  v_case public.partner_support_conversations;
begin
  select * into v_actor from public.profiles
  where auth_id=auth.uid()::text and role in ('staff','admin','creator')
    and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then raise exception 'Property Operations access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then
    raise exception 'Property Operations permission required';
  end if;

  select * into v_res from public.reservations where id=p_reservation_id for update;
  if v_res.id is null then raise exception 'Reservation not found'; end if;
  select * into v_listing from public.listings where id::text=v_res.listing_id or listing_id=v_res.listing_id limit 1;
  if v_listing.id is null then raise exception 'Property not found'; end if;
  if v_actor.role<>'creator' and not public.current_actor_in_scope(v_listing.state,v_listing.city) then
    raise exception 'Reservation is outside your assigned State/LGA';
  end if;

  select * into v_officer from public.profiles p
  where p.user_id=p_field_officer_id and p.role='staff'
    and not coalesce(p.deleted,false) and not coalesce(p.suspended,false) and not coalesce(p.banned,false)
    and lower(btrim(coalesce(p.assigned_state,'')))=lower(btrim(coalesce(v_listing.state,'')))
    and lower(btrim(coalesce(p.assigned_lga,'')))=lower(btrim(coalesce(v_listing.city,'')))
    and exists(select 1 from public.staff_permissions sp where sp.staff_id=p.user_id and sp.permission='field_officer' and sp.is_active=true)
  limit 1;
  if v_officer.user_id is null then raise exception 'Choose an active Field Operations officer for this branch'; end if;

  select * into v_case from public.partner_support_conversations c
  where c.context_type='apartment_reservation' and c.context_id=v_res.id
  order by c.updated_at desc limit 1 for update;
  if v_case.id is null then
    raise exception 'The Property Operations conversation is missing for this reservation';
  end if;

  update public.partner_support_conversations
  set assigned_field_officer_id=v_officer.user_id,
      assigned_staff_id=coalesce(assigned_staff_id,v_actor.user_id),
      status=case when status='open' then 'assigned' else status end,
      channel_kind='property_operations',updated_at=now()
  where id=v_case.id;

  update public.reservations
  set handover_field_officer_id=v_officer.user_id,
      handover_conversation_id=v_case.id,updated_at=now()
  where id=v_res.id;

  insert into public.partner_support_messages(
    conversation_id,sender_id,sender_role,content,action_type,action_metadata,created_at,is_read,visibility
  ) values (
    v_case.id,v_actor.user_id,'system',
    coalesce(nullif(btrim(v_officer.full_name),''),nullif(btrim(v_officer.username),''),v_officer.user_id)||
      ' joined as Field Operations for the move-in handover. Property Operations remains responsible for this case.',
    'field_officer_assigned',jsonb_build_object('officer_id',v_officer.user_id,'reservation_id',v_res.id),now(),false,'customer'
  );

  insert into public.notifications(
    recipient_id,type,title,message,read,related_id,source_type,source_id,
    destination_route,destination_params,event_key,workspace_scope
  ) values (
    v_officer.user_id,'reservation_handover_assigned','Move-in handover assigned',
    coalesce(v_listing.title,'Apartment')||' · '||coalesce(nullif(btrim(v_actor.full_name),''),'Property Operations')||' assigned you to the existing reservation conversation.',
    false,v_res.id,'apartment_reservation',v_res.id,'conversation',
    jsonb_build_object('conversation_id',v_case.id,'reservation_id',v_res.id,'listing_id',v_listing.id),
    'handover-assignment:'||v_res.id||':'||v_officer.user_id||':'||extract(epoch from now())::bigint,'staff'
  );

  return jsonb_build_object(
    'conversation_id',v_case.id,
    'assigned_field_officer_id',v_officer.user_id,
    'assigned_field_officer_name',coalesce(nullif(btrim(v_officer.full_name),''),nullif(btrim(v_officer.username),''),v_officer.user_id)
  );
end;
$$;


--
-- Name: attach_property_partner_to_inspection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_property_partner_to_inspection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.partner_id IS NULL AND NEW.owner_id IS NOT NULL THEN
    SELECT pp.id INTO NEW.partner_id
    FROM public.property_partners pp
    WHERE pp.profile_id=NEW.owner_id
    ORDER BY pp.created_at DESC
    LIMIT 1;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: begin_long_let_hold(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_long_let_hold(p_reservation_id text, p_provider_event_id uuid, p_event_key text) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_res public.reservations;
  v_listing public.listings;
  v_policy public.creator_policy_versions;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  select * into v_res from public.reservations
  where id=p_reservation_id and coalesce(stay_type,'long_stay')='long_stay'
  for update;
  if v_res.id is null then raise exception 'Long Let reservation not found'; end if;
  if not exists(
    select 1 from public.verified_provider_events
    where provider_event_id=p_provider_event_id and processed_at is not null
  ) then raise exception 'Verified provider event required'; end if;
  select * into v_listing from public.listings
  where listing_id=v_res.listing_id or id::text=v_res.listing_id for update;
  if v_listing.id is null or v_listing.sub_type<>'long_stay'
    or v_listing.deleted_at is not null then
    raise exception 'Long Let property not available';
  end if;
  if v_res.occupant_count>coalesce(v_listing.max_occupants,1) then
    raise exception 'Occupant capacity exceeded';
  end if;
  if exists(
    select 1 from public.reservations r
    where r.id<>v_res.id and r.listing_id=v_res.listing_id
      and coalesce(r.stay_type,'long_stay')='long_stay'
      and coalesce(r.canonical_state,r.status) in (
        'hold_active','inspection_requested','inspection_completed',
        'rent_pending','rent_protected','handover_pending',
        'handover_verified','active'
      )
      and coalesce(r.hold_expires_at,'infinity')>now()
  ) then raise exception 'Property already has an active Long Let obligation'; end if;
  select * into v_policy from public.creator_policy_versions
  where policy_key='long_let_reservation_hold' and scope_type='global'
    and scope_key='*' and status='active'
  order by effective_from desc limit 1;
  if v_policy.policy_version_id is null then raise exception 'Long Let hold policy missing'; end if;

  update public.reservations
  set canonical_state='hold_active',status='reserved',
      hold_expires_at=now()+interval '3 days',
      reservation_policy_version_id=v_policy.policy_version_id,
      paid_at=coalesce(paid_at,now()),updated_at=now()
  where id=v_res.id returning * into v_res;
  insert into public.long_let_reservation_transitions(
    reservation_id,from_state,to_state,event_type,event_key,actor_type,
    policy_version_id,metadata
  ) values(
    v_res.id,'reservation_fee_pending','hold_active','reservation_fee_confirmed',
    p_event_key,'system',v_policy.policy_version_id,
    jsonb_build_object(
      'provider_event_id',p_provider_event_id,
      'hold_expires_at',v_res.hold_expires_at,
      'full_refund_until',v_res.paid_at+interval '24 hours'
    )
  ) on conflict(event_key) do nothing;
  return v_res;
end
$$;


--
-- Name: payout_account_change_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payout_account_change_requests (
    request_id uuid NOT NULL,
    user_id text NOT NULL,
    bank_code text NOT NULL,
    bank_name text NOT NULL,
    account_number text NOT NULL,
    account_name text NOT NULL,
    recipient_code text,
    status text DEFAULT 'processing'::text NOT NULL,
    bank_account_id uuid,
    error_code text,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    idempotency_key text NOT NULL,
    auth_session_id text NOT NULL,
    replacement boolean NOT NULL,
    fresh_sign_in_verified_at timestamp with time zone,
    otp_verified_at timestamp with time zone,
    account_name_confirmed_at timestamp with time zone NOT NULL,
    cooling_ends_at timestamp with time zone NOT NULL,
    initiated_ip_hash text,
    activated_at timestamp with time zone,
    CONSTRAINT payout_account_change_requests_confirmation_order_check CHECK (((fresh_sign_in_verified_at IS NULL) OR (account_name_confirmed_at >= fresh_sign_in_verified_at))),
    CONSTRAINT payout_account_change_requests_cooling_order_check CHECK ((cooling_ends_at >= account_name_confirmed_at)),
    CONSTRAINT payout_account_change_requests_otp_order_check CHECK (((otp_verified_at IS NULL) OR (fresh_sign_in_verified_at IS NULL) OR (otp_verified_at >= fresh_sign_in_verified_at))),
    CONSTRAINT payout_account_change_requests_replacement_step_up_check CHECK (((NOT replacement) OR ((fresh_sign_in_verified_at IS NOT NULL) AND (otp_verified_at IS NOT NULL)))),
    CONSTRAINT payout_account_change_requests_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'uncertain'::text, 'cooling'::text, 'activation_pending'::text, 'active'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: begin_payout_account_change_from_service(uuid, text, text, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_payout_account_change_from_service(p_request_id uuid, p_idempotency_key text, p_user_id text, p_auth_session_id text, p_bank_code text, p_bank_name text, p_account_number text, p_account_name text, p_recipient_code text, p_fresh_sign_in_verified_at timestamp with time zone, p_otp_verified_at timestamp with time zone, p_account_name_confirmed_at timestamp with time zone, p_ip_hash text DEFAULT NULL::text) RETURNS public.payout_account_change_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_existing public.payout_account_change_requests;
  v_replacement boolean;
  v_account_id uuid;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  select * into v_existing from public.payout_account_change_requests
  where request_id=p_request_id or idempotency_key=p_idempotency_key;
  if v_existing.request_id is not null then
    if v_existing.user_id<>p_user_id
      or v_existing.bank_code<>p_bank_code
      or v_existing.account_number<>p_account_number then
      raise exception 'Idempotency key belongs to a different payout change';
    end if;
    if v_existing.bank_account_id is not null then return v_existing; end if;
    v_replacement:=v_existing.replacement;
  else
    select exists(
      select 1 from public.bank_accounts
      where user_id=p_user_id and is_active and is_default
    ) into v_replacement;
  end if;
  if v_replacement and (
    p_fresh_sign_in_verified_at is null
    or p_otp_verified_at is null
    or p_fresh_sign_in_verified_at<now()-interval '5 minutes'
    or p_otp_verified_at<now()-interval '5 minutes'
  ) then raise exception 'Fresh sign-in and OTP are required'; end if;
  if p_otp_verified_at is not null
    and p_account_name_confirmed_at<p_otp_verified_at then
    raise exception 'Account name must be confirmed after OTP';
  end if;

  insert into public.bank_accounts(
    user_id,account_number,bank_code,bank_name,account_name,
    paystack_recipient_code,is_default,verified_at,is_active,created_at,updated_at
  ) values(
    p_user_id,p_account_number,p_bank_code,p_bank_name,p_account_name,
    p_recipient_code,false,now(),true,now(),now()
  ) on conflict(user_id,bank_code,account_number) where is_active
  do update set
    bank_name=excluded.bank_name,
    account_name=excluded.account_name,
    paystack_recipient_code=coalesce(
      excluded.paystack_recipient_code,public.bank_accounts.paystack_recipient_code
    ),
    verified_at=now(),updated_at=now()
  returning id into v_account_id;

  if v_existing.request_id is null then
    insert into public.payout_account_change_requests(
      request_id,idempotency_key,user_id,auth_session_id,bank_code,bank_name,
      account_number,account_name,recipient_code,replacement,
      fresh_sign_in_verified_at,otp_verified_at,account_name_confirmed_at,
      cooling_ends_at,status,bank_account_id,initiated_ip_hash
    ) values(
      p_request_id,p_idempotency_key,p_user_id,p_auth_session_id,p_bank_code,p_bank_name,
      p_account_number,p_account_name,p_recipient_code,v_replacement,
      p_fresh_sign_in_verified_at,p_otp_verified_at,p_account_name_confirmed_at,
      case when v_replacement then now()+interval '24 hours' else now() end,
      case when v_replacement then 'cooling' else 'activation_pending' end,
      v_account_id,p_ip_hash
    ) returning * into v_existing;
  else
    update public.payout_account_change_requests
    set recipient_code=p_recipient_code,bank_account_id=v_account_id,
        status=case when replacement then 'cooling' else 'activation_pending' end,
        error_code=null,error_message=null,updated_at=now()
    where request_id=p_request_id
    returning * into v_existing;
  end if;
  return v_existing;
end
$$;


--
-- Name: bind_worker_booking_service(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_worker_booking_service() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare matched public.service_subcategories;
begin
  if new.service_subcategory_id is not null then
    select * into matched from public.service_subcategories where id=new.service_subcategory_id;
  elsif nullif(btrim(coalesce(new.service_type,'')),'') is not null then
    select * into matched from public.service_subcategories where lower(btrim(name))=lower(btrim(new.service_type)) order by is_active desc,created_at limit 1;
  end if;
  if matched is not null then new.service_subcategory_id:=matched.id;new.service_type:=matched.name;end if;
  return new;
end $$;


--
-- Name: block_legacy_legal_setting_writes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_legacy_legal_setting_writes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_key text:=case when tg_op='DELETE' then old.key else new.key end;
begin
  if v_key in('privacy_policy','terms_of_service','legal_version') then
    raise exception 'Use the versioned Creator legal document registry';
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end
$$;


--
-- Name: block_retired_worker_identity_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_retired_worker_identity_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NULLIF(BTRIM(COALESCE(NEW.gov_id_type,'')),'') IS NOT NULL
    OR NULLIF(BTRIM(COALESCE(NEW.gov_id_number,'')),'') IS NOT NULL
    OR NULLIF(BTRIM(COALESCE(NEW.gov_id_photo_url,'')),'') IS NOT NULL
    OR NULLIF(BTRIM(COALESCE(NEW.selfie_photo_url,'')),'') IS NOT NULL
    OR NULLIF(BTRIM(COALESCE(NEW.identity_provider,'')),'') IS NOT NULL
    OR NULLIF(BTRIM(COALESCE(NEW.identity_reference,'')),'') IS NOT NULL
    OR NEW.identity_checked_at IS NOT NULL
    OR NULLIF(BTRIM(COALESCE(NEW.identity_failure_reason,'')),'') IS NOT NULL
    OR COALESCE(NEW.identity_status,'not_started')<>'not_started'
  THEN RAISE EXCEPTION 'Government/external identity fields are retired from WeHouse Worker verification'; END IF;
  NEW.identity_status:='not_started';
  RETURN NEW;
END;
$$;


--
-- Name: bootstrap_first_creator_from_service(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bootstrap_first_creator_from_service(p_auth_user_id uuid, p_expected_email text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_auth_email text;
  v_auth_confirmed_at timestamptz;
  v_profile public.profiles;
begin
  if (select auth.role()) <> 'service_role' then
    raise exception 'service role required';
  end if;
  if p_auth_user_id is null or nullif(lower(btrim(p_expected_email)),'') is null then
    raise exception 'Exact Auth user ID and email are required';
  end if;
  if length(btrim(coalesce(p_reason,''))) < 12 then
    raise exception 'A specific bootstrap reason is required';
  end if;

  perform pg_advisory_xact_lock(hashtext('wehouse:first-creator-bootstrap'));

  select lower(btrim(u.email)),u.email_confirmed_at
  into v_auth_email,v_auth_confirmed_at
  from auth.users u where u.id=p_auth_user_id;
  if v_auth_email is null then raise exception 'Auth user not found'; end if;
  if v_auth_confirmed_at is null then
    raise exception 'Creator email must be confirmed first';
  end if;
  if v_auth_email<>lower(btrim(p_expected_email)) then
    raise exception 'Auth user ID and expected email do not match';
  end if;

  select * into v_profile from public.profiles p
  where p.auth_id=p_auth_user_id::text for update;
  if v_profile.user_id is null then
    raise exception 'Create the normal Personal profile before Creator bootstrap';
  end if;
  if lower(btrim(v_profile.email))<>v_auth_email then
    raise exception 'Personal profile and Auth email do not match';
  end if;
  if coalesce(v_profile.deleted,false) or coalesce(v_profile.suspended,false)
    or coalesce(v_profile.banned,false) then
    raise exception 'Creator bootstrap requires an active Personal profile';
  end if;
  if exists(
    select 1 from public.workspace_role_assignments w
    where w.user_id=v_profile.user_id and w.status='active'
      and w.workspace_role in('worker','property_partner')
  ) then
    raise exception 'Bootstrap a clean Personal account, not a marketplace professional account';
  end if;
  if exists(
    select 1 from public.workspace_role_assignments w
    where w.workspace_role='creator' and w.status='active'
      and w.user_id<>v_profile.user_id
  ) then
    raise exception 'A different active Creator is already configured';
  end if;

  update public.profiles
  set role='creator',account_kind='consumer',updated_at=now()
  where user_id=v_profile.user_id;

  insert into public.workspace_role_assignments(
    user_id,workspace_role,scope_type,scope_state,scope_lga,status,
    granted_by,granted_at,created_at,updated_at
  ) values(
    v_profile.user_id,'creator','global',null,null,'active',
    null,now(),now(),now()
  ) on conflict(user_id,workspace_role) where status='active'
  do update set scope_type='global',scope_state=null,scope_lga=null,
    updated_at=now();

  insert into public.admin_audit_log(
    admin_id,admin_email,action,target_type,target_id,details,created_at
  ) values(
    v_profile.user_id,v_auth_email,'FIRST_CREATOR_BOOTSTRAPPED',
    'creator_identity',v_profile.user_id,
    jsonb_build_object(
      'auth_user_id',p_auth_user_id,
      'reason',btrim(p_reason),
      'method','service_role_exact_identity'
    )::text,now()
  );

  return jsonb_build_object(
    'success',true,'user_id',v_profile.user_id,'email',v_auth_email,
    'workspace','creator','scope','global'
  );
end
$$;


--
-- Name: bump_legal_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bump_legal_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.key in ('privacy_policy','terms_of_service') and (tg_op='INSERT' or new.value is distinct from old.value) then
    insert into public.platform_settings(key,value,label,description,category,data_type,is_active,updated_at)
    values('legal_version',extract(epoch from clock_timestamp())::bigint::text,'Legal version','Automatically changes when Privacy Policy or Terms & Conditions change.','platform','text',true,now())
    on conflict (key) do update set value=excluded.value,updated_at=excluded.updated_at,is_active=true;
  end if;
  return new;
end $$;


--
-- Name: calculate_commission(numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_commission(p_amount numeric, p_type text DEFAULT 'worker'::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_percent numeric;
BEGIN
  IF p_amount IS NULL OR p_amount<0 THEN RAISE EXCEPTION 'Amount must be zero or greater'; END IF;
  SELECT NULLIF(btrim(value),'')::numeric INTO v_percent
  FROM public.platform_settings
  WHERE key=CASE
    WHEN p_type='worker' THEN 'worker_commission_rate'
    WHEN p_type='property' THEN 'commission_apartment'
    WHEN p_type='hotel' THEN 'commission_hotel'
    ELSE 'worker_commission_rate'
  END
  AND COALESCE(is_active,true)=true
  LIMIT 1;
  v_percent:=COALESCE(v_percent,10);
  IF v_percent<0 OR v_percent>50 THEN RAISE EXCEPTION 'Invalid commission rate'; END IF;
  RETURN round(p_amount*(v_percent/100),2);
END;
$$;


--
-- Name: calculate_reservation_refund(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_reservation_refund(p_reservation_id text, p_reason_category text) RETURNS TABLE(refund_amount numeric, wehouse_retained numeric, refund_percent numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_res public.reservations; v_actor public.profiles; v_percent numeric;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_res FROM public.reservations WHERE id=p_reservation_id;
  IF v_res IS NULL THEN RAISE EXCEPTION 'Reservation not found'; END IF;
  IF v_res.user_id<>v_actor.user_id THEN
    IF v_actor.role='staff' THEN
      IF NOT public.current_staff_has_permission('finance') OR NOT public.current_actor_can_access_listing_ref(v_res.listing_id) THEN RAISE EXCEPTION 'Finance branch access required'; END IF;
    ELSIF v_actor.role='admin' THEN
      IF NOT public.current_actor_can_access_listing_ref(v_res.listing_id) THEN RAISE EXCEPTION 'Reservation is outside your branch'; END IF;
    ELSIF v_actor.role<>'creator' THEN RAISE EXCEPTION 'Not authorized'; END IF;
  END IF;
  CASE p_reason_category
    WHEN 'expired_no_action' THEN v_percent:=0;
    WHEN 'customer_declined_inspection' THEN SELECT COALESCE(NULLIF(value,'')::numeric,50) INTO v_percent FROM public.platform_settings WHERE key='post_inspection_refund_percent';
    WHEN 'provider_failure','listing_mismatch' THEN v_percent:=100;
    ELSE RAISE EXCEPTION 'Invalid refund reason';
  END CASE;
  refund_amount:=round(v_res.amount*v_percent/100,2); wehouse_retained:=v_res.amount-refund_amount; refund_percent:=v_percent; RETURN NEXT;
END;
$$;


--
-- Name: can_access_hotel_booking_conversation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_hotel_booking_conversation(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  with actor as (select public.current_profile_user_id() as user_id)
  select exists(
    select 1 from public.hotel_booking_conversations conversation
    cross join actor
    where conversation.id=p_conversation_id
      and actor.user_id is not null
      and (conversation.guest_user_id=actor.user_id
        or public.hotel_actor_has_capability(conversation.hotel_id,'stay.message'))
  )
$$;


--
-- Name: can_access_my_conversation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_my_conversation(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT public._can_access_conversation(p_conversation_id);
$$;


--
-- Name: can_access_operational_conversation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_operational_conversation(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select exists(
  select 1 from public.partner_support_conversations c join public.profiles p on p.auth_id=auth.uid()::text
  where c.id=p_conversation_id and (
   p.user_id in (c.partner_id,c.assigned_staff_id,c.assigned_field_officer_id) or p.role in ('admin','creator') or
   (p.role='staff' and c.assigned_staff_id is null and public.current_staff_has_permission(case when c.channel_kind='reservation_operations' then 'operations' else 'support' end))
  )
 )
$$;


--
-- Name: can_current_actor_read_profile(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_current_actor_read_profile(p_target_user_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ DECLARE v_actor public.profiles; v_target public.profiles; BEGIN IF auth.uid() IS NULL OR p_target_user_id IS NULL THEN RETURN false; END IF; SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1; IF v_actor IS NULL THEN RETURN false; END IF; IF v_actor.user_id=p_target_user_id OR v_actor.role='creator' THEN RETURN true; END IF; IF v_actor.role NOT IN ('admin','staff') THEN RETURN false; END IF; SELECT * INTO v_target FROM public.profiles WHERE user_id=p_target_user_id LIMIT 1; IF v_target IS NULL THEN RETURN false; END IF; RETURN public.current_actor_in_scope(COALESCE(NULLIF(v_target.assigned_state,''),NULLIF(v_target.state,'')),COALESCE(NULLIF(v_target.assigned_lga,''),NULLIF(v_target.local_government,''),NULLIF(v_target.city,''))); END; $$;


--
-- Name: can_current_actor_read_profile_for(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_current_actor_read_profile_for(p_actor_id text, p_target_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;v_target public.profiles;
begin
  select * into v_actor from public.profiles where user_id=p_actor_id limit 1;
  select * into v_target from public.profiles where user_id=p_target_id limit 1;
  if v_actor.user_id is null or v_target.user_id is null then return false; end if;
  if v_actor.role='creator' then return true; end if;
  if v_actor.role not in ('admin','staff') then return false; end if;
  return public.wehouse_state_key(v_actor.assigned_state)=public.wehouse_state_key(v_target.state)
    and public.wehouse_lga_key(v_actor.assigned_lga)=public.wehouse_lga_key(coalesce(nullif(v_target.local_government,''),v_target.city));
end;
$$;


--
-- Name: cancel_booking(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_booking(p_booking_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_booking public.worker_bookings;
BEGIN
  SELECT * INTO v_actor
  FROM public.profiles
  WHERE auth_id=auth.uid()::text
    AND coalesce(deleted,false)=false
    AND coalesce(suspended,false)=false
    AND coalesce(banned,false)=false
  LIMIT 1;

  IF v_actor IS NULL OR v_actor.role NOT IN ('user','worker') THEN RAISE EXCEPTION 'Active booking participant required'; END IF;
  IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Cancellation reason is required'; END IF;

  SELECT * INTO v_booking FROM public.worker_bookings WHERE id=p_booking_id FOR UPDATE;
  IF v_booking IS NULL THEN RAISE EXCEPTION 'Booking not found'; END IF;
  IF v_actor.user_id NOT IN (v_booking.user_id,v_booking.worker_id) THEN RAISE EXCEPTION 'Not authorized to cancel this booking'; END IF;
  IF v_booking.status NOT IN ('booking_requested','negotiating','waiting_payment') THEN RAISE EXCEPTION 'Booking cannot be cancelled in current status: %',v_booking.status; END IF;

  IF EXISTS(
    SELECT 1
    FROM public.booking_payments bp
    WHERE bp.worker_booking_id=p_booking_id
      AND bp.status='review_required'
  ) THEN
    RAISE EXCEPTION 'This booking has a verified payment awaiting WeHouse review and cannot be cancelled yet';
  END IF;

  UPDATE public.worker_bookings
  SET status='cancelled',cancellation_reason=trim(p_reason),cancelled_by=v_actor.user_id,updated_at=now()
  WHERE id=p_booking_id;
  RETURN true;
END;
$$;


--
-- Name: cancel_my_apartment_reservation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_my_apartment_reservation(p_reservation_id text) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_user_id text; v_res public.reservations; v_result public.reservations;
begin
  select user_id into v_user_id from public.profiles where auth_id=auth.uid()::text limit 1;
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select * into v_res from public.reservations where id=p_reservation_id and user_id=v_user_id for update;
  if v_res is null then raise exception 'Reservation not found'; end if;
  if v_res.status not in ('payment_pending','reserved','inspection_pending','ready_for_move_in') then raise exception 'Reservation can no longer be cancelled here'; end if;
  if v_res.manual_payment_status in ('paid','completed') or v_res.paid_at is not null then raise exception 'Paid reservations must be handled by support'; end if;
  update public.reservations set status='cancelled',processed_at=now(),updated_at=now() where id=v_res.id returning * into v_result;
  update public.booking_payments set status='cancelled',updated_at=now() where paystack_reference=v_res.payment_reference and status='pending';
  if coalesce(v_res.stay_type,'long_stay')<>'short_let' then
    update public.listings
    set status='available',availability_status='available',reserved_by=null,reservation_expiry=null,reservation_fee_paid=false,chat_unlocked=false,current_reservation_id=null,updated_at=now()
    where id::text=v_res.listing_id and current_reservation_id=v_res.id;
  else
    update public.listings
    set reserved_by=null,reservation_expiry=null,occupied_by=null,occupied_at=null,tenancy_ends_at=null,current_reservation_id=null,updated_at=now()
    where id::text=v_res.listing_id and current_reservation_id=v_res.id;
  end if;
  return v_result;
end;
$$;


--
-- Name: cancel_my_hotel_booking(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_my_hotel_booking(p_booking_id integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id text:=public.current_profile_user_id();
  v_changed integer;
begin
  if v_user_id is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Active Personal account required';
  end if;
  update public.hotel_bookings
  set status='cancelled',
      payment_status=case when payment_status='paid'
        then payment_status else 'expired' end,
      updated_at=now()
  where booking_id=p_booking_id and user_id=v_user_id
    and status='pending' and payment_status<>'paid';
  get diagnostics v_changed=row_count;
  if v_changed=0 then
    raise exception 'Only your unpaid pending Hotel booking can be cancelled';
  end if;
  update public.booking_payments
  set status='cancelled',updated_at=now()
  where hotel_booking_id=p_booking_id and user_id=v_user_id
    and purpose='hotel_booking' and status='pending';
  return true;
end
$$;


--
-- Name: cancel_my_inspection_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_my_inspection_request(p_inspection_id uuid) RETURNS public.user_inspection_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user_id text; v_result public.user_inspection_requests;
BEGIN
  SELECT user_id INTO v_user_id FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  UPDATE public.user_inspection_requests SET status='cancelled',updated_at=now()
  WHERE id=p_inspection_id AND user_id=v_user_id AND status IN ('pending','scheduled')
  RETURNING * INTO v_result;
  IF v_result IS NULL THEN RAISE EXCEPTION 'Inspection request cannot be cancelled'; END IF;
  UPDATE public.reservations SET status='active',updated_at=now() WHERE id=v_result.reservation_id AND status='inspection_pending';
  RETURN v_result;
END;
$$;


--
-- Name: cancel_rent_plan(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_rent_plan(p_plan_id uuid, p_reason text DEFAULT NULL::text, p_reason_category text DEFAULT 'voluntary'::text) RETURNS TABLE(refund_amount numeric, fee_amount numeric, total_contributed numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_plan public.rent_plans%rowtype; v_actor text:=public.current_profile_user_id(); v_creator boolean:=public.is_current_creator(); v_fee_amount numeric; v_refund_amount numeric;
begin
 if v_actor is null then raise exception 'Authentication required'; end if;
 select * into v_plan from public.rent_plans where id=p_plan_id for update;
 if not found then raise exception 'Rent plan not found'; end if;
 if v_plan.user_id is distinct from v_actor and not v_creator then raise exception 'You cannot cancel this rent plan'; end if;
 if v_plan.status='cancelled' then raise exception 'Already cancelled'; end if;
 if not v_creator and coalesce(p_reason_category,'voluntary')<>'voluntary' then raise exception 'Only WeHouse can classify a provider failure'; end if;
 if p_reason_category='provider_failure' then v_fee_amount:=0; v_refund_amount:=v_plan.total_contributed;
 else v_fee_amount:=round(v_plan.total_contributed*v_plan.cancellation_fee_percent/100,2); v_refund_amount:=v_plan.total_contributed-v_fee_amount; end if;
 insert into public.rent_plan_cancellations(rent_plan_id,user_id,total_contributed,cancellation_fee_percent,cancellation_fee_amount,refund_amount,reason,reason_category)
 values(p_plan_id,v_plan.user_id,v_plan.total_contributed,v_plan.cancellation_fee_percent,v_fee_amount,v_refund_amount,p_reason,coalesce(p_reason_category,'voluntary'));
 update public.rent_plans set status='cancelled',total_paid_out=v_refund_amount,updated_at=now() where id=p_plan_id;
 refund_amount:=v_refund_amount; fee_amount:=v_fee_amount; total_contributed:=v_plan.total_contributed; return next;
end;$$;


--
-- Name: canonical_operational_domain(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_operational_domain(p_channel text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case p_channel
    when 'operations' then 'property_operations'
    when 'reservation_operations' then 'property_operations'
    when 'property_operations' then 'property_operations'
    when 'field_operations' then 'field_operations'
    when 'worker_operations' then 'worker_operations'
    when 'finance_operations' then 'finance_operations'
    when 'security_operations' then 'security_operations'
    when 'support_case' then 'support'
    when 'support' then 'support'
    else null
  end
$$;


--
-- Name: canonical_product_transition_allowed(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_product_transition_allowed(p_product text, p_from text, p_to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case p_product
    when 'long_let' then (p_from,p_to) in (
      ('reservation_fee_pending','hold_active'),
      ('hold_active','inspection_requested'),
      ('hold_active','rent_pending'),
      ('hold_active','cancelled'),
      ('hold_active','expired'),
      ('inspection_requested','inspection_completed'),
      ('inspection_requested','cancelled'),
      ('inspection_completed','rent_pending'),
      ('rent_pending','rent_protected'),
      ('rent_pending','cancelled'),
      ('rent_protected','handover_pending'),
      ('rent_protected','disputed'),
      ('handover_pending','handover_verified'),
      ('handover_pending','disputed'),
      ('handover_verified','active'),
      ('handover_verified','disputed'),
      ('active','renewal_offered'),
      ('active','ended'),
      ('renewal_offered','renewing'),
      ('renewal_offered','ended'),
      ('renewing','active'),
      ('disputed','rent_protected'),
      ('disputed','cancelled'),
      ('disputed','refunded')
    )
    when 'short_let' then (p_from,p_to) in (
      ('checkout_pending','confirmed'),
      ('checkout_pending','expired'),
      ('confirmed','check_in_ready'),
      ('confirmed','cancelled'),
      ('confirmed','disputed'),
      ('check_in_ready','checked_in'),
      ('checked_in','checked_out'),
      ('checked_in','disputed'),
      ('checked_out','completed'),
      ('checked_out','disputed'),
      ('disputed','confirmed'),
      ('disputed','completed'),
      ('disputed','refunded')
    )
    when 'hotel' then (p_from,p_to) in (
      ('checkout_pending','confirmed'),
      ('checkout_pending','expired'),
      ('confirmed','check_in_ready'),
      ('confirmed','cancelled'),
      ('confirmed','disputed'),
      ('check_in_ready','checked_in'),
      ('checked_in','checked_out'),
      ('checked_in','disputed'),
      ('checked_out','completed'),
      ('disputed','confirmed'),
      ('disputed','completed'),
      ('disputed','refunded')
    )
    when 'worker' then (p_from,p_to) in (
      ('requested','negotiating'),
      ('requested','cancelled'),
      ('negotiating','awaiting_payment'),
      ('negotiating','cancelled'),
      ('awaiting_payment','confirmed'),
      ('awaiting_payment','cancelled'),
      ('confirmed','in_progress'),
      ('confirmed','cancelled'),
      ('in_progress','completion_marked'),
      ('in_progress','disputed'),
      ('completion_marked','completed'),
      ('completion_marked','disputed'),
      ('disputed','in_progress'),
      ('disputed','completed'),
      ('disputed','refunded')
    )
    else false
  end
$$;


--
-- Name: canonical_saved_search_criteria(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_saved_search_criteria(p_value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_result jsonb;
begin
  if p_value is null then return '{}'::jsonb; end if;
  if jsonb_typeof(p_value)='object' then
    select coalesce(jsonb_object_agg(entry.key,public.canonical_saved_search_criteria(entry.value)),'{}'::jsonb)
    into v_result
    from jsonb_each(p_value) entry
    where entry.value<>'null'::jsonb and entry.value<>'""'::jsonb;
    return v_result;
  elsif jsonb_typeof(p_value)='array' then
    select coalesce(jsonb_agg(value order by value::text),'[]'::jsonb)
    into v_result
    from (
      select public.canonical_saved_search_criteria(entry.value) value
      from jsonb_array_elements(p_value) entry
    ) normalized;
    return v_result;
  end if;
  return p_value;
end;
$$;


--
-- Name: canonical_staff_domain(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_staff_domain(p_permission text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case lower(btrim(coalesce(p_permission,'')))
    when 'operations' then 'property_operations'
    when 'property_operations' then 'property_operations'
    when 'field_officer' then 'field_operations'
    when 'field_operation' then 'field_operations'
    when 'filed_officer' then 'field_operations'
    when 'filed_operation' then 'field_operations'
    when 'field_operations' then 'field_operations'
    when 'verification' then 'worker_operations'
    when 'worker_verification' then 'worker_operations'
    when 'worker_review' then 'worker_operations'
    when 'worker_operations' then 'worker_operations'
    when 'finance' then 'finance_operations'
    when 'finance_operations' then 'finance_operations'
    when 'security' then 'security_operations'
    when 'security_operations' then 'security_operations'
    when 'support' then 'support'
    else null
  end
$$;


--
-- Name: claim_financial_actions(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_financial_actions(p_worker_id text, p_limit integer DEFAULT 20) RETURNS TABLE(financial_action_id uuid, action_type text, subject_type text, subject_id text, payment_protection_id uuid, amount numeric, idempotency_key text, paystack_reference text, payee_user_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  if nullif(btrim(p_worker_id),'') is null then raise exception 'worker id required'; end if;
  return query
  with due as(
    select a.financial_action_id
    from public.financial_action_outbox a
    where a.status='pending' and a.available_at<=now()
      and not(
        a.action_type like 'refund_%' and exists(
          select 1 from public.financial_action_outbox active
          where active.payment_protection_id=a.payment_protection_id
            and active.financial_action_id<>a.financial_action_id
            and active.action_type like 'refund_%'
            and active.status in('processing','provider_pending','provider_attention')
        )
      )
    order by a.available_at,a.created_at
    for update skip locked
    limit least(greatest(coalesce(p_limit,20),1),50)
  ),claimed as(
    update public.financial_action_outbox a set
      status='processing',claimed_by=btrim(p_worker_id),claimed_at=now(),
      attempt_count=attempt_count+1,updated_at=now()
    from due where a.financial_action_id=due.financial_action_id
    returning a.*
  )
  select c.financial_action_id,c.action_type,c.subject_type,c.subject_id,
    c.payment_protection_id,c.amount,c.idempotency_key,
    p.paystack_reference,p.payee_user_id
  from claimed c join public.payment_protection_transactions p
    on p.id=c.payment_protection_id;
end
$$;


--
-- Name: claim_my_communication_case(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_my_communication_case(p_conversation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conversation public.partner_support_conversations;
  v_case public.operational_cases;
  v_domain text;
  v_handler_name text;
  v_has_case boolean;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then raise exception 'Active WeHouse team account required'; end if;

  select * into v_conversation
  from public.partner_support_conversations
  where id=p_conversation_id
  for update;
  if v_conversation.id is null then raise exception 'Conversation not found'; end if;
  if not public.current_actor_can_access_operational_conversation(
    p_conversation_id,false
  ) or v_actor.user_id=v_conversation.partner_id then
    raise exception 'Conversation is outside your work area';
  end if;

  if v_conversation.operational_case_id is not null then
    select * into v_case from public.operational_cases
    where operational_case_id=v_conversation.operational_case_id
    for update;
  end if;
  if (v_conversation.assigned_staff_id is not null
        and v_conversation.assigned_staff_id<>v_actor.user_id)
     or (v_conversation.assigned_field_officer_id is not null
        and v_conversation.assigned_field_officer_id<>v_actor.user_id)
     or (v_case.assigned_user_id is not null
        and v_case.assigned_user_id<>v_actor.user_id) then
    raise exception 'This work is already assigned to another team member';
  end if;

  v_domain:=coalesce(
    v_case.owning_domain,
    public.canonical_operational_domain(v_conversation.channel_kind)
  );
  v_has_case:=v_conversation.operational_case_id is not null
    or v_conversation.channel_kind in('support','support_case');
  v_handler_name:=coalesce(
    nullif(btrim(v_actor.full_name),''),
    nullif(btrim(v_actor.username),''),
    'A WeHouse team member'
  );

  update public.partner_support_conversations
  set assigned_staff_id=v_actor.user_id,
      assigned_field_officer_id=case when v_domain='field_operations'
        then v_actor.user_id else assigned_field_officer_id end,
      status=case when v_has_case and status='open' then 'assigned' else status end,
      updated_at=now()
  where id=p_conversation_id;

  if v_case.operational_case_id is not null then
    update public.operational_cases
    set assigned_user_id=v_actor.user_id,
        status=case when status in('open','triaged') then 'assigned' else status end,
        updated_at=now()
    where operational_case_id=v_case.operational_case_id;
  end if;

  if v_has_case and not exists(
    select 1 from public.support_case_events e
    where e.conversation_id=p_conversation_id
      and e.event_type='assigned' and e.actor_id=v_actor.user_id
  ) then
    insert into public.support_case_events(
      conversation_id,event_type,actor_id,from_status,to_status,note,metadata
    ) values(
      p_conversation_id,'assigned',v_actor.user_id,v_conversation.status,
      case when v_conversation.status='open' then 'assigned' else v_conversation.status end,
      v_handler_name||' is handling this request.',
      jsonb_build_object('handler_name',v_handler_name,'owning_domain',v_domain)
    );
    insert into public.partner_support_messages(
      conversation_id,sender_id,sender_role,content,action_type,
      action_metadata,visibility,created_at
    ) values(
      p_conversation_id,v_actor.user_id,
      case when v_actor.role in('admin','creator') then v_actor.role else 'staff' end,
      v_handler_name||' is handling this '
        ||replace(coalesce(v_domain,'WeHouse'),'_operations','')||' request.',
      'status_change',jsonb_build_object(
        'event_type','assigned','from_status',v_conversation.status,
        'to_status',case when v_conversation.status='open' then 'assigned'
          else v_conversation.status end,
        'actor_name',v_handler_name,'owning_domain',v_domain
      ),'customer',now()
    );
  end if;

  if v_case.operational_case_id is not null then
    insert into public.operational_case_events(
      operational_case_id,event_key,event_type,from_status,to_status,
      actor_user_id,public_note,metadata
    ) values(
      v_case.operational_case_id,
      'case_assigned:'||v_case.operational_case_id||':'||v_actor.user_id,
      'assigned',v_case.status,
      case when v_case.status in('open','triaged') then 'assigned' else v_case.status end,
      v_actor.user_id,v_handler_name||' is handling this request.',
      jsonb_build_object('owning_domain',v_domain)
    ) on conflict(event_key) do nothing;
  end if;
  return true;
end
$$;


--
-- Name: claim_withdrawal_for_payout(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_withdrawal_for_payout(p_withdrawal_id uuid, p_reviewer_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_reviewer public.profiles;
  v_withdrawal public.withdrawals;
  v_wallet public.wallets;
  v_reference text;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then
    raise exception 'Service role required';
  end if;
  if not public.finance_reviewer_is_authorized(p_reviewer_id) then
    raise exception 'Finance permission required';
  end if;
  select * into v_reviewer from public.profiles where user_id=p_reviewer_id;
  select * into v_withdrawal from public.withdrawals where id=p_withdrawal_id for update;
  if v_withdrawal.id is null then raise exception 'Withdrawal not found'; end if;
  select * into v_wallet from public.wallets where id=v_withdrawal.wallet_id for update;
  if v_wallet.id is null then raise exception 'Wallet not found'; end if;
  if v_wallet.owner_id=p_reviewer_id then raise exception 'You cannot review your own withdrawal'; end if;
  if v_reviewer.role in ('staff','admin')
     and not public.can_current_actor_read_profile_for(v_reviewer.user_id,v_wallet.owner_id) then
    raise exception 'Withdrawal is outside your branch';
  end if;
  if v_withdrawal.status='processing' and v_withdrawal.paystack_transfer_reference is not null then
    return jsonb_build_object(
      'success',true,'already_claimed',true,'withdrawal_id',v_withdrawal.id,
      'amount',v_withdrawal.amount,'recipient_code',v_withdrawal.payout_recipient_code,
      'reference',v_withdrawal.paystack_transfer_reference,'owner_type',v_wallet.owner_type
    );
  end if;
  if v_withdrawal.status<>'awaiting_review' then
    raise exception 'Withdrawal is not awaiting review';
  end if;
  if coalesce(v_wallet.frozen_balance,0)<v_withdrawal.amount then
    raise exception 'Reserved wallet balance is incomplete';
  end if;
  if nullif(btrim(coalesce(v_withdrawal.payout_recipient_code,'')),'') is null then
    raise exception 'Paystack recipient is missing';
  end if;
  v_reference:='WHP-'||replace(v_withdrawal.id::text,'-','');
  update public.withdrawals
  set status='processing',reviewed_by=p_reviewer_id,reviewed_at=now(),
      paystack_transfer_reference=v_reference,paystack_status='initiating',updated_at=now()
  where id=v_withdrawal.id;
  insert into public.financial_audit_logs(
    event_type,user_id,target_user_id,amount,reference_id,reference_type,description,metadata
  ) values(
    'withdrawal_processing',p_reviewer_id,v_wallet.owner_id,v_withdrawal.amount,
    v_withdrawal.id::text,'withdrawal','Withdrawal approved for Paystack transfer',
    jsonb_build_object('paystack_reference',v_reference,'owner_type',v_wallet.owner_type)
  );
  return jsonb_build_object(
    'success',true,'already_claimed',false,'withdrawal_id',v_withdrawal.id,
    'amount',v_withdrawal.amount,'recipient_code',v_withdrawal.payout_recipient_code,
    'reference',v_reference,'owner_type',v_wallet.owner_type
  );
end;
$$;


--
-- Name: classify_conversation_channel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classify_conversation_channel() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare source_type text:=coalesce(new.context_snapshot->>'source_type','');
begin
  new.channel_kind:=case
    when (new.context_type='property_inspection' or source_type='property_inspection')
      and nullif(btrim(coalesce(new.assigned_field_officer_id,'')),'') is not null then 'field_operations'
    when new.context_type in ('apartment_reservation','apartment_payment','reservation','hotel_booking','property_listing','property_inspection','hotel_property','hotel_operations') then 'property_operations'
    when source_type in ('apartment_reservation','apartment_payment','reservation','hotel_booking','property_listing','property_inspection','hotel_property','hotel_operations') then 'property_operations'
    else 'support_case'
  end;
  if new.case_number is null then new.case_number:='WHC-'||upper(substring(replace(gen_random_uuid()::text,'-','') from 1 for 10)); end if;
  if new.status='open' and (new.assigned_staff_id is not null or new.assigned_field_officer_id is not null) then new.status:='assigned'; end if;
  return new;
end;
$$;


--
-- Name: clear_consumed_property_access_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_consumed_property_access_code() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.access_evidence_status in ('submitted','verified')
     or new.access_evidence_video_path is not null
     or new.published_at is not null then
    new.access_challenge_code := null;
    new.access_challenge_expires_at := null;
  end if;
  return new;
end;
$$;


--
-- Name: complete_apartment_tenancy(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_apartment_tenancy(p_reservation_id text, p_next_status text DEFAULT 'maintenance'::text) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_res public.reservations;
  v_listing public.listings;
  v_result public.reservations;
BEGIN
  IF p_next_status NOT IN ('maintenance','available','closed') THEN RAISE EXCEPTION 'Invalid next property status'; END IF;
  SELECT * INTO v_actor
  FROM public.profiles
  WHERE auth_id=auth.uid()::text
    AND role IN ('staff','admin','creator')
    AND COALESCE(deleted,false)=false
    AND COALESCE(suspended,false)=false
    AND COALESCE(banned,false)=false
  LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Housing operations access required'; END IF;
  IF v_actor.role='staff' AND NOT public.current_staff_has_permission('operations') THEN RAISE EXCEPTION 'Operations permission required'; END IF;

  SELECT * INTO v_res
  FROM public.reservations
  WHERE id=p_reservation_id AND status='occupied'
  FOR UPDATE;
  IF v_res IS NULL THEN RAISE EXCEPTION 'Occupied reservation not found'; END IF;
  IF COALESCE(v_res.stay_type,'long_stay')<>'long_stay' THEN
    RAISE EXCEPTION 'Short Stay checkout uses the Short Stay operations workflow';
  END IF;

  SELECT * INTO v_listing FROM public.listings WHERE id::text=v_res.listing_id FOR UPDATE;
  IF v_listing IS NULL OR v_listing.sub_type<>'long_stay' THEN RAISE EXCEPTION 'Long Stay listing not found'; END IF;
  IF v_actor.role<>'creator' AND NOT public.current_actor_in_scope(v_listing.state,v_listing.city) THEN
    RAISE EXCEPTION 'Listing is outside your assigned State/LGA';
  END IF;

  UPDATE public.reservations
  SET status='completed',completed_at=now(),processed_by=v_actor.user_id,processed_at=now(),updated_at=now()
  WHERE id=v_res.id
  RETURNING * INTO v_result;

  UPDATE public.listings
  SET status=p_next_status,availability_status=p_next_status,occupied_by=NULL,occupied_at=NULL,tenancy_ends_at=NULL,
      reserved_by=NULL,reservation_expiry=NULL,reservation_fee_paid=false,chat_unlocked=false,current_reservation_id=NULL,updated_at=now()
  WHERE id=v_listing.id;
  RETURN v_result;
END;
$$;


--
-- Name: hotel_bookings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hotel_bookings (
    booking_id integer NOT NULL,
    hotel_id integer NOT NULL,
    room_id integer NOT NULL,
    user_id text NOT NULL,
    check_in date NOT NULL,
    check_out date NOT NULL,
    guest_count integer DEFAULT 1,
    total_nights integer NOT NULL,
    total_price integer NOT NULL,
    status text DEFAULT 'pending'::text,
    guest_name text,
    guest_phone text,
    special_requests text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    booking_code text,
    payment_status text DEFAULT 'unpaid'::text NOT NULL,
    payment_reference text,
    payment_expires_at timestamp with time zone,
    paid_at timestamp with time zone,
    confirmed_at timestamp with time zone,
    rate_plan_id integer,
    rate_plan_name text,
    rate_plan_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    assigned_room_unit_id bigint,
    checked_in_at timestamp with time zone,
    checked_out_at timestamp with time zone,
    completion_due_at timestamp with time zone,
    completed_at timestamp with time zone,
    completed_by text,
    completion_source text,
    integration_id uuid,
    pms_external_reservation_id text,
    pms_sync_status text DEFAULT 'not_connected'::text NOT NULL,
    pms_last_synced_at timestamp with time zone,
    canonical_state text,
    payment_protection_id uuid,
    policy_version_id uuid,
    arrival_issue_policy_version_id uuid,
    arrival_issue_window_hours integer,
    arrival_issue_deadline_at timestamp with time zone,
    CONSTRAINT hotel_bookings_arrival_issue_window_hours_check CHECK (((arrival_issue_window_hours IS NULL) OR ((arrival_issue_window_hours >= 2) AND (arrival_issue_window_hours <= 4)))),
    CONSTRAINT hotel_bookings_completion_source_check CHECK (((completion_source IS NULL) OR (completion_source = ANY (ARRAY['immediate'::text, 'hotel_manual'::text, 'auto_review'::text, 'manual_sla_fallback'::text, 'wehouse_review'::text])))),
    CONSTRAINT hotel_bookings_payment_status_check CHECK ((payment_status = ANY (ARRAY['unpaid'::text, 'payment_pending'::text, 'paid'::text, 'refunded'::text, 'failed'::text, 'expired'::text]))),
    CONSTRAINT hotel_bookings_pms_sync_status_check CHECK ((pms_sync_status = ANY (ARRAY['not_connected'::text, 'pending'::text, 'delivered'::text, 'acknowledged'::text, 'review_required'::text]))),
    CONSTRAINT hotel_bookings_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'checked_in'::text, 'checked_out'::text, 'cancelled'::text, 'completed'::text, 'refunded'::text, 'expired'::text, 'payment_conflict'::text])))
);


--
-- Name: complete_hotel_stay_internal(integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_hotel_stay_internal(p_booking_id integer, p_source text, p_actor_id text DEFAULT NULL::text) RETURNS public.hotel_bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.hotel_bookings;
begin
  select * into b from public.hotel_bookings where booking_id=p_booking_id for update;
  if b.booking_id is null then raise exception 'Hotel booking not found'; end if;
  if b.status='completed' then return b; end if;
  if b.status<>'checked_out' or b.payment_status<>'paid' then raise exception 'Only a paid checked-out stay can be completed'; end if;
  update public.hotel_bookings set status='completed',completed_at=now(),completed_by=p_actor_id,completion_source=p_source,completion_due_at=null,updated_at=now()
  where booking_id=b.booking_id returning * into b;
  return b;
end;
$$;


--
-- Name: complete_inspection_result(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_inspection_result(p_inspection_id uuid, p_result text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor public.profiles; v_req public.user_inspection_requests; v_res public.reservations;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND role IN ('staff','admin','creator')
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Field operations access required'; END IF;
  IF p_result NOT IN ('passed','failed','customer_declined') THEN RAISE EXCEPTION 'Invalid inspection result'; END IF;
  SELECT * INTO v_req FROM public.user_inspection_requests WHERE id=p_inspection_id FOR UPDATE;
  IF v_req IS NULL THEN RAISE EXCEPTION 'Inspection not found'; END IF;
  IF v_actor.role='staff' THEN
    IF v_req.field_officer_id<>v_actor.user_id OR NOT public.current_staff_has_permission('field_officer') THEN RAISE EXCEPTION 'Inspection is not assigned to this Field Officer'; END IF;
  ELSIF v_actor.role='admin' AND NOT public.current_actor_can_access_listing_ref(v_req.listing_id) THEN
    RAISE EXCEPTION 'Inspection is outside your assigned branch';
  END IF;
  SELECT * INTO v_res FROM public.reservations WHERE id=v_req.reservation_id FOR UPDATE;
  UPDATE public.user_inspection_requests SET status='completed',condition=p_result,updated_at=now() WHERE id=p_inspection_id;
  UPDATE public.reservations SET inspection_result=p_result,inspection_completed=true,inspection_completed_at=now(),updated_at=now() WHERE id=v_req.reservation_id;
  IF p_result='passed' THEN
    UPDATE public.reservations SET status='ready_for_move_in',updated_at=now() WHERE id=v_req.reservation_id;
  ELSIF p_result='customer_declined' THEN
    UPDATE public.reservations SET status='cancelled',processed_at=now(),updated_at=now() WHERE id=v_req.reservation_id;
    UPDATE public.listings SET status='available',availability_status='available',reserved_by=NULL,reservation_expiry=NULL,
      reservation_fee_paid=false,chat_unlocked=false,current_reservation_id=NULL,updated_at=now()
    WHERE id::text=v_req.listing_id AND current_reservation_id=v_req.reservation_id;
  ELSE
    UPDATE public.reservations SET status='cancelled',refund_reason='provider_failure',processed_at=now(),updated_at=now() WHERE id=v_req.reservation_id;
    UPDATE public.listings SET status='maintenance',availability_status='maintenance',reserved_by=NULL,reservation_expiry=NULL,
      chat_unlocked=false,current_reservation_id=NULL,updated_at=now()
    WHERE id::text=v_req.listing_id AND current_reservation_id=v_req.reservation_id;
  END IF;
  RETURN true;
END;
$$;


--
-- Name: complete_internal_release_action(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_internal_release_action(p_financial_action_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_action public.financial_action_outbox;
  v_protection public.payment_protection_transactions;
  v_commission numeric(12,2);
  v_payee_amount numeric(12,2);
  v_ledger uuid;
  v_entries jsonb;
  v_new_released numeric(12,2);
  v_new_refunded numeric(12,2);
  v_to_state text;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  select * into v_action from public.financial_action_outbox
  where financial_action_id=p_financial_action_id for update;
  if v_action.status='completed' then
    return jsonb_build_object('success',true,'already_completed',true); end if;
  if v_action.status<>'processing' or v_action.action_type not like 'release_%' then
    raise exception 'Release action is not processing'; end if;
  select * into v_protection from public.payment_protection_transactions
  where id=v_action.payment_protection_id for update;
  if v_protection.protection_state not in(
    'release_eligible','disputed','partially_released'
  ) then raise exception 'Payment Protection is not releasable'; end if;
  if v_action.amount<=0 or v_action.amount>
      v_protection.amount_total-v_protection.released_amount-v_protection.refunded_amount then
    raise exception 'Release exceeds the protected balance'; end if;
  v_commission:=least(
    v_protection.amount_commission-v_protection.commission_recognized_amount,
    round(v_action.amount*v_protection.commission_rate/100,2)
  );
  if v_action.amount=
      v_protection.amount_total-v_protection.released_amount-v_protection.refunded_amount then
    v_commission:=least(v_action.amount,
      v_protection.amount_commission-v_protection.commission_recognized_amount);
  end if;
  v_payee_amount:=v_action.amount-v_commission;
  v_entries:=jsonb_build_array(
    jsonb_build_object(
      'account_key','liability:payment_protection:'||v_protection.id::text,
      'account_class','liability','owner_type',v_protection.subject_type,
      'owner_id',v_protection.subject_id,'amount',v_action.amount,
      'memo','Payment Protection release'
    ),
    jsonb_build_object(
      'account_key','liability:payee_available:'||v_protection.payee_user_id,
      'account_class','liability','owner_type','profile',
      'owner_id',v_protection.payee_user_id,'amount',-v_payee_amount,
      'memo','Available for withdrawal'
    )
  );
  if v_commission>0 then
    v_entries:=v_entries||jsonb_build_array(jsonb_build_object(
      'account_key','revenue:wehouse_commission:'||v_protection.subject_type,
      'account_class','revenue','owner_type','wehouse','owner_id','platform',
      'amount',-v_commission,'memo','Creator-policy commission recognized'
    ));
  end if;
  v_ledger:=public.post_ledger_transaction(
    'financial-action:'||v_action.idempotency_key,'protected_release','NGN',
    v_action.subject_type,v_action.subject_id,null,
    jsonb_build_object(
      'financial_action_id',v_action.financial_action_id,
      'payment_protection_id',v_protection.id,
      'commission',v_commission,'payee_amount',v_payee_amount
    ),v_entries
  );
  update public.payment_protection_transactions set
    released_amount=released_amount+v_action.amount,
    commission_recognized_amount=commission_recognized_amount+v_commission,
    release_ledger_transaction_id=v_ledger,updated_at=now()
  where id=v_protection.id
  returning released_amount,refunded_amount into v_new_released,v_new_refunded;
  v_to_state:=case
    when v_new_released=v_protection.amount_total then 'released'
    else 'partially_released' end;
  perform public.transition_payment_protection(
    v_protection.id,v_to_state,'financial_release_completed',
    'financial-release-completed:'||v_action.financial_action_id,
    null,'finance_processor',null,v_ledger,
    jsonb_build_object('financial_action_id',v_action.financial_action_id)
  );
  update public.financial_action_outbox set
    status='completed',processed_at=now(),last_error=null,updated_at=now()
  where financial_action_id=v_action.financial_action_id;
  return jsonb_build_object(
    'success',true,'ledger_transaction_id',v_ledger,
    'payee_amount',v_payee_amount,'commission',v_commission
  );
end
$$;


--
-- Name: complete_my_account_identity_check(text, numeric, numeric, numeric, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_my_account_identity_check(p_photo_path text, p_face_match_score numeric, p_liveness_score numeric, p_anti_spoof_score numeric, p_challenge_result jsonb, p_consent boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'storage'
    AS $$
declare
  v_actor public.profiles;
  v_existing public.worker_identity_checks;
  v_renewal boolean;
  v_attempts integer;
  v_account_role text;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null then raise exception 'Active Personal account required'; end if;
  if public.current_actor_has_workspace('worker',null) then
    v_account_role:='worker';
  elsif public.current_actor_has_workspace('property_partner',null) then
    v_account_role:='property_partner';
  else
    raise exception 'Worker or Property Partner workspace required';
  end if;
  if not coalesce(p_consent,false) then
    raise exception 'Private face-check consent is required';
  end if;
  select * into v_existing
  from public.worker_identity_checks
  where worker_id=v_actor.user_id
  for update;
  v_renewal:=v_existing.worker_id is not null
    and nullif(btrim(coalesce(v_existing.enrollment_photo_path,'')),'') is not null;
  if nullif(btrim(coalesce(p_photo_path,'')),'') is null
     or split_part(p_photo_path,'/',1)<>v_actor.user_id then
    raise exception 'Invalid private identity path';
  end if;
  if v_renewal and p_photo_path<>v_existing.enrollment_photo_path then
    raise exception 'Renewal must reuse the original private identity reference';
  end if;
  if not exists(
    select 1 from storage.objects
    where bucket_id='worker-identity-private' and name=p_photo_path
  ) then raise exception 'Private identity reference was not found'; end if;
  if p_face_match_score not between 0 and 1
     or p_liveness_score not between 0 and 1
     or p_anti_spoof_score not between 0 and 1 then
    raise exception 'Invalid automatic face-check score';
  end if;
  if p_face_match_score<0.55 then
    raise exception 'Live face did not match the private identity reference closely enough';
  end if;
  if p_liveness_score<0.50 then raise exception 'Automatic liveness check did not pass'; end if;
  if p_anti_spoof_score<0.50 then raise exception 'Automatic anti-spoof check did not pass'; end if;
  if not coalesce((p_challenge_result->>'automatic')::boolean,false)
    or not coalesce((p_challenge_result->>'center_start')::boolean,false)
    or not coalesce((p_challenge_result->>'side_one')::boolean,false)
    or not coalesce((p_challenge_result->>'side_two')::boolean,false)
    or not coalesce((p_challenge_result->>'center_end')::boolean,false)
    or coalesce((p_challenge_result->>'recorded_video')::boolean,true) then
    raise exception 'Automatic head-movement challenge is incomplete';
  end if;
  v_attempts:=coalesce(v_existing.attempt_count,0)+1;
  insert into public.worker_identity_checks(
    worker_id,account_role,status,enrollment_photo_path,
    latest_reference_photo_path,latest_reference_at,challenge_version,
    face_match_score,liveness_score,anti_spoof_score,challenge_result,
    consent_at,captured_at,attempt_count,updated_at
  ) values(
    v_actor.user_id,v_account_role,'passed',p_photo_path,p_photo_path,now(),
    'human-3.3.6-head-turn-v4-shared',p_face_match_score,p_liveness_score,
    p_anti_spoof_score,p_challenge_result,now(),now(),v_attempts,now()
  ) on conflict(worker_id) do update set
    account_role=excluded.account_role,status='passed',
    enrollment_photo_path=coalesce(
      worker_identity_checks.enrollment_photo_path,
      excluded.enrollment_photo_path
    ),
    latest_reference_photo_path=excluded.latest_reference_photo_path,
    latest_reference_at=excluded.latest_reference_at,
    challenge_version=excluded.challenge_version,
    face_match_score=excluded.face_match_score,
    liveness_score=excluded.liveness_score,
    anti_spoof_score=excluded.anti_spoof_score,
    challenge_result=excluded.challenge_result,
    consent_at=excluded.consent_at,
    captured_at=excluded.captured_at,
    attempt_count=v_attempts,
    updated_at=now();
  insert into public.audit_logs(
    action,target_type,target_id,details,admin_id,admin_email
  ) values(
    case when v_renewal then 'ACCOUNT_IDENTITY_RECHECK_PASSED'
      else 'ACCOUNT_IDENTITY_ENROLLED' end,
    'profiles',v_actor.user_id,
    jsonb_build_object(
      'workspace',v_account_role,
      'challenge_version','human-3.3.6-head-turn-v4-shared'
    )::text,
    v_actor.user_id,v_actor.email
  );
  return jsonb_build_object(
    'success',true,'current',true,'renewal',v_renewal,
    'recheck_days',public.account_identity_recheck_days()
  );
end
$$;


--
-- Name: partner_support_conversations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.partner_support_conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    partner_id text NOT NULL,
    subject text NOT NULL,
    status text DEFAULT 'open'::text,
    property_name text,
    property_address text,
    property_city text,
    property_state text,
    property_type text,
    rental_mode text,
    inspection_id uuid,
    listing_id uuid,
    assigned_staff_id text,
    assigned_field_officer_id text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    resolved_at timestamp with time zone,
    closed_at timestamp with time zone,
    requester_role text,
    category text DEFAULT 'general'::text NOT NULL,
    context_type text DEFAULT 'general'::text NOT NULL,
    context_id text,
    context_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    priority text DEFAULT 'normal'::text NOT NULL,
    channel_kind text DEFAULT 'support_case'::text NOT NULL,
    case_number text,
    operational_case_id uuid,
    canonical_thread_id uuid,
    CONSTRAINT partner_support_conversations_channel_kind_check CHECK ((channel_kind = ANY (ARRAY['reservation_operations'::text, 'property_operations'::text, 'field_operations'::text, 'worker_operations'::text, 'finance_operations'::text, 'security_operations'::text, 'support'::text, 'support_case'::text]))),
    CONSTRAINT partner_support_conversations_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
    CONSTRAINT partner_support_conversations_requester_role_check CHECK (((requester_role IS NULL) OR (requester_role = ANY (ARRAY['user'::text, 'worker'::text, 'property_partner'::text, 'staff'::text, 'admin'::text, 'creator'::text, 'hotel_staff'::text])))),
    CONSTRAINT partner_support_conversations_status_check CHECK ((status = ANY (ARRAY['open'::text, 'assigned'::text, 'in_progress'::text, 'waiting_for_user'::text, 'escalated'::text, 'resolved'::text, 'closed'::text])))
);


--
-- Name: complete_my_support_case(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_my_support_case(p_conversation_id uuid) RETURNS public.partner_support_conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conversation public.partner_support_conversations;
  v_result public.partner_support_conversations;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  select * into v_conversation from public.partner_support_conversations
  where id=p_conversation_id for update;
  if v_actor.user_id is null or v_conversation.id is null
     or v_conversation.partner_id<>v_actor.user_id then raise exception 'Request not found'; end if;
  if v_conversation.status<>'resolved' then raise exception 'Only a resolved request can be confirmed as solved'; end if;
  update public.partner_support_conversations set status='closed',closed_at=now(),updated_at=now()
  where id=p_conversation_id returning * into v_result;
  update public.operational_cases set status='closed',closed_at=now(),updated_at=now()
  where operational_case_id=v_conversation.operational_case_id;
  insert into public.support_case_events(
    conversation_id,event_type,actor_id,from_status,to_status,note
  ) values(p_conversation_id,'resolution_accepted',v_actor.user_id,
    'resolved','closed','The requester confirmed this is solved.');
  insert into public.partner_support_messages(
    conversation_id,sender_id,sender_role,content,action_type,
    action_metadata,visibility,created_at
  ) values(p_conversation_id,v_actor.user_id,
    coalesce(v_conversation.requester_role,v_actor.role),'This solved my request.',
    'status_change',jsonb_build_object('event_type','resolution_accepted',
      'from_status','resolved','to_status','closed'),'customer',now());
  if v_conversation.canonical_thread_id is not null then
    update public.canonical_threads set state='closed',closed_at=now(),updated_at=now()
    where thread_id=v_conversation.canonical_thread_id;
  end if;
  return v_result;
end
$$;


--
-- Name: complete_my_worker_identity_check(text, numeric, numeric, numeric, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_my_worker_identity_check(p_photo_path text, p_face_match_score numeric, p_liveness_score numeric, p_anti_spoof_score numeric, p_challenge_result jsonb, p_consent boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_actor public.profiles;
  v_existing public.worker_identity_checks;
  v_attempts integer;
  v_is_renewal boolean:=false;
  v_anchor_similarity numeric;
  v_recent_similarity numeric;
  v_best_similarity numeric;
begin
  select * into v_actor
  from public.profiles
  where auth_id=auth.uid()::text
    and public.user_has_active_workspace(user_id,'worker')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null then raise exception 'Active Worker account required'; end if;
  if coalesce(p_consent,false)=false then raise exception 'Private face-check consent is required'; end if;

  select * into v_existing from public.worker_identity_checks where worker_id=v_actor.user_id;
  v_is_renewal:=v_existing.worker_id is not null and nullif(btrim(coalesce(v_existing.enrollment_photo_path,'')),'') is not null;

  if nullif(btrim(coalesce(p_photo_path,'')),'') is null or p_photo_path not like v_actor.user_id||'/%' then
    raise exception 'Invalid private face reference path';
  end if;
  if not exists(select 1 from storage.objects where bucket_id='worker-identity-private' and name=p_photo_path) then
    raise exception 'Private identity reference was not found';
  end if;

  if p_face_match_score is null or p_face_match_score<0 or p_face_match_score>1
     or p_liveness_score is null or p_liveness_score<0 or p_liveness_score>1
     or p_anti_spoof_score is null or p_anti_spoof_score<0 or p_anti_spoof_score>1 then
    raise exception 'Invalid automatic face-check score';
  end if;

  if coalesce((p_challenge_result->>'automatic')::boolean,false)=false
     or coalesce((p_challenge_result->>'center_start')::boolean,false)=false
     or coalesce((p_challenge_result->>'side_one')::boolean,false)=false
     or coalesce((p_challenge_result->>'side_two')::boolean,false)=false
     or coalesce((p_challenge_result->>'center_end')::boolean,false)=false
     or coalesce((p_challenge_result->>'recorded_video')::boolean,true)=true then
    raise exception 'Automatic head-movement challenge is incomplete';
  end if;

  v_anchor_similarity := case
    when coalesce(p_challenge_result->>'anchor_similarity','') ~ '^(0([.][0-9]+)?|1([.]0+)?)$'
      then (p_challenge_result->>'anchor_similarity')::numeric
    else null
  end;
  v_recent_similarity := case
    when coalesce(p_challenge_result->>'recent_similarity','') ~ '^(0([.][0-9]+)?|1([.]0+)?)$'
      then (p_challenge_result->>'recent_similarity')::numeric
    else null
  end;
  v_best_similarity := greatest(coalesce(v_anchor_similarity,0),coalesce(v_recent_similarity,0),p_face_match_score);

  if v_is_renewal then
    if v_anchor_similarity is null then raise exception 'Original identity anchor score is required'; end if;
    if v_anchor_similarity < 0.50 then raise exception 'Your current face changed too much from the original Worker identity. WeHouse review is required'; end if;
    if greatest(v_anchor_similarity,coalesce(v_recent_similarity,0)) < 0.55 then raise exception 'Your live face did not match the trusted Worker references closely enough'; end if;
  elsif p_face_match_score < 0.55 then
    raise exception 'Live face did not match the enrolled Worker closely enough';
  end if;

  if p_liveness_score<0.50 then raise exception 'Automatic liveness check did not pass'; end if;
  if p_anti_spoof_score<0.50 then raise exception 'Automatic anti-spoof check did not pass'; end if;

  v_attempts:=coalesce(v_existing.attempt_count,0)+1;

  insert into public.worker_identity_checks(
    worker_id,status,enrollment_photo_path,latest_reference_photo_path,latest_reference_at,
    challenge_version,face_match_score,liveness_score,anti_spoof_score,challenge_result,
    consent_at,captured_at,attempt_count,updated_at
  ) values(
    v_actor.user_id,'passed',p_photo_path,p_photo_path,now(),
    'human-3.3.6-head-turn-v3-adaptive',v_best_similarity,p_liveness_score,p_anti_spoof_score,p_challenge_result,
    now(),now(),v_attempts,now()
  )
  on conflict(worker_id) do update set
    status='passed',
    enrollment_photo_path=coalesce(worker_identity_checks.enrollment_photo_path,excluded.enrollment_photo_path),
    latest_reference_photo_path=excluded.latest_reference_photo_path,
    latest_reference_at=excluded.latest_reference_at,
    challenge_version=excluded.challenge_version,
    face_match_score=excluded.face_match_score,
    liveness_score=excluded.liveness_score,
    anti_spoof_score=excluded.anti_spoof_score,
    challenge_result=excluded.challenge_result,
    consent_at=excluded.consent_at,
    captured_at=excluded.captured_at,
    attempt_count=v_attempts,
    updated_at=now();

  insert into public.audit_logs(action,target_type,target_id,details,admin_id,admin_email)
  values(
    case when v_is_renewal then 'WORKER_ADAPTIVE_IDENTITY_RECHECK_PASSED' else 'WORKER_AUTOMATIC_FACE_CHECK_PASSED' end,
    'profiles',v_actor.user_id,
    jsonb_build_object(
      'challenge_version','human-3.3.6-head-turn-v3-adaptive',
      'face_match_score',v_best_similarity,
      'anchor_similarity',v_anchor_similarity,
      'recent_similarity',v_recent_similarity,
      'liveness_score',p_liveness_score,
      'anti_spoof_score',p_anti_spoof_score,
      'adaptive_reference',v_is_renewal,
      'original_anchor_preserved',v_is_renewal,
      'liveness_video_recorded',false,
      'private_selfie',true
    )::text,
    v_actor.user_id,v_actor.email
  );

  return jsonb_build_object(
    'status','passed',
    'captured_at',now(),
    'attempt_count',v_attempts,
    'adaptive_reference',v_is_renewal,
    'anchor_preserved',v_is_renewal
  );
end; $_$;


--
-- Name: complete_short_stay(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_short_stay(p_reservation_id text, p_next_status text DEFAULT 'available'::text) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_res public.reservations;
  v_listing public.listings;
  v_result public.reservations;
begin
  perform p_next_status;
  select * into v_actor
  from public.profiles
  where auth_id=auth.uid()::text
    and role in ('staff','admin','creator')
    and coalesce(deleted,false)=false
    and coalesce(suspended,false)=false
    and coalesce(banned,false)=false
  limit 1;
  if v_actor is null then raise exception 'Housing operations access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then raise exception 'Operations permission required'; end if;

  select * into v_res
  from public.reservations
  where id=p_reservation_id and stay_type='short_let' and status='occupied'
  for update;
  if v_res is null then raise exception 'Active Short Stay not found'; end if;

  select * into v_listing from public.listings where id::text=v_res.listing_id for update;
  if v_listing is null then raise exception 'Short Stay listing not found'; end if;
  if v_actor.role<>'creator' and not public.current_actor_in_scope(v_listing.state,v_listing.city) then raise exception 'Listing is outside your assigned State/LGA'; end if;

  update public.reservations
  set status='completed',
      completed_at=now(),
      processed_by=v_actor.user_id,
      processed_at=now(),
      security_deposit_status=case when coalesce(security_deposit_snapshot,0)>0 then 'refund_due' else 'not_required' end,
      updated_at=now()
  where id=v_res.id
  returning * into v_result;

  update public.listings
  set reserved_by=null,
      reservation_expiry=null,
      occupied_by=null,
      occupied_at=null,
      tenancy_ends_at=null,
      current_reservation_id=null,
      updated_at=now()
  where id=v_listing.id and current_reservation_id=v_res.id;

  return v_result;
end;
$$;


--
-- Name: confirm_apartment_handover(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_apartment_handover(p_booking_code text, p_start_date date DEFAULT CURRENT_DATE) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_verified jsonb;
  v_result public.reservations;
  v_res public.reservations;
begin
  v_verified:=public.verify_branch_booking_code(p_booking_code);
  if v_verified is null or v_verified->>'kind'<>'housing' then
    raise exception 'Enter a valid housing move-in code';
  end if;
  if coalesce((v_verified->>'can_handover')::boolean,false) is not true then
    raise exception 'Verified rent and a customer move-in time are required before handover';
  end if;
  if p_start_date<>((v_verified->>'requested_move_in_at')::timestamptz)::date then
    raise exception 'The tenancy start date must match the customer move-in request';
  end if;
  select * into v_res from public.reservations where id=v_verified->>'reservation_id';
  if v_res.handover_field_officer_id is null or v_res.handover_conversation_id is null then
    raise exception 'Assign Field Operations to the reservation conversation before handover';
  end if;
  select * into v_result from public.activate_apartment_tenancy(v_res.id,p_start_date);
  return v_result;
end;
$$;


--
-- Name: confirm_booking_payment(text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_booking_payment(p_reference text, p_transaction_id text DEFAULT NULL::text, p_verified_amount numeric DEFAULT NULL::numeric, p_verification_source text DEFAULT 'webhook'::text, p_purpose text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
                                                                                                                                                                                                                                                                                              DECLARE
                                                                                                                                                                                                                                                                                                v_payment RECORD;
                                                                                                                                                                                                                                                                                                  v_updated INTEGER;
                                                                                                                                                                                                                                                                                                    v_payment_user_id TEXT;
                                                                                                                                                                                                                                                                                                    BEGIN
                                                                                                                                                                                                                                                                                                      IF auth.uid() IS NOT NULL THEN
                                                                                                                                                                                                                                                                                                          RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
                                                                                                                                                                                                                                                                                                            END IF;

                                                                                                                                                                                                                                                                                                              IF p_verified_amount IS NULL THEN
                                                                                                                                                                                                                                                                                                                  RETURN jsonb_build_object('success', false, 'error', 'Verified amount required');
                                                                                                                                                                                                                                                                                                                    END IF;

                                                                                                                                                                                                                                                                                                                      SELECT * INTO v_payment FROM booking_payments
                                                                                                                                                                                                                                                                                                                        WHERE paystack_reference = p_reference
                                                                                                                                                                                                                                                                                                                          FOR UPDATE SKIP LOCKED;

                                                                                                                                                                                                                                                                                                                            IF v_payment IS NULL THEN
                                                                                                                                                                                                                                                                                                                                RETURN jsonb_build_object('success', false, 'error', 'Payment not found');
                                                                                                                                                                                                                                                                                                                                  END IF;

                                                                                                                                                                                                                                                                                                                                    IF EXISTS (SELECT 1 FROM verified_paystack_references WHERE paystack_reference = p_reference) THEN
                                                                                                                                                                                                                                                                                                                                        RETURN jsonb_build_object('success', true, 'already_processed', true);
                                                                                                                                                                                                                                                                                                                                          END IF;

                                                                                                                                                                                                                                                                                                                                            IF v_payment.status IN ('paid', 'completed') THEN
                                                                                                                                                                                                                                                                                                                                                RETURN jsonb_build_object('success', true, 'already_processed', true);
                                                                                                                                                                                                                                                                                                                                                  END IF;

                                                                                                                                                                                                                                                                                                                                                    IF COALESCE(v_payment.amount_total, v_payment.amount, 0) > 0
                                                                                                                                                                                                                                                                                                                                                         AND ABS(p_verified_amount - COALESCE(v_payment.amount_total, v_payment.amount)) > 1 THEN
                                                                                                                                                                                                                                                                                                                                                             RETURN jsonb_build_object('success', false, 'error', 'Amount mismatch',
                                                                                                                                                                                                                                                                                                                                                                   'expected', COALESCE(v_payment.amount_total, v_payment.amount),
                                                                                                                                                                                                                                                                                                                                                                         'verified', p_verified_amount);
                                                                                                                                                                                                                                                                                                                                                                           END IF;

                                                                                                                                                                                                                                                                                                                                                                             IF p_purpose IS NOT NULL AND v_payment.purpose IS NOT NULL AND p_purpose != v_payment.purpose THEN
                                                                                                                                                                                                                                                                                                                                                                                 RETURN jsonb_build_object('success', false, 'error', 'Purpose mismatch');
                                                                                                                                                                                                                                                                                                                                                                                   END IF;

                                                                                                                                                                                                                                                                                                                                                                                     v_payment_user_id := v_payment.user_id;

                                                                                                                                                                                                                                                                                                                                                                                       UPDATE booking_payments SET
                                                                                                                                                                                                                                                                                                                                                                                           status = 'paid',
                                                                                                                                                                                                                                                                                                                                                                                               paystack_transaction_id = COALESCE(p_transaction_id, paystack_transaction_id),
                                                                                                                                                                                                                                                                                                                                                                                                   verified_amount = p_verified_amount,
                                                                                                                                                                                                                                                                                                                                                                                                       verified_at = NOW(),
                                                                                                                                                                                                                                                                                                                                                                                                           verification_source = p_verification_source,
                                                                                                                                                                                                                                                                                                                                                                                                               paid_at = NOW(),
                                                                                                                                                                                                                                                                                                                                                                                                                   webhook_processed = TRUE,
                                                                                                                                                                                                                                                                                                                                                                                                                       updated_at = NOW()
                                                                                                                                                                                                                                                                                                                                                                                                                         WHERE id = v_payment.id;

                                                                                                                                                                                                                                                                                                                                                                                                                           INSERT INTO verified_paystack_references (
                                                                                                                                                                                                                                                                                                                                                                                                                               paystack_reference, booking_payment_id, verified_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                   verification_source, verified_by
                                                                                                                                                                                                                                                                                                                                                                                                                                     ) VALUES (p_reference, v_payment.id, p_verified_amount, p_verification_source, 'paystack-verify')
                                                                                                                                                                                                                                                                                                                                                                                                                                       ON CONFLICT (paystack_reference) DO NOTHING;

                                                                                                                                                                                                                                                                                                                                                                                                                                         IF v_payment.amount_commission IS NOT NULL AND v_payment.amount_commission > 0 THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                             INSERT INTO commission_ledger (
                                                                                                                                                                                                                                                                                                                                                                                                                                                   payment_id, booking_type, source_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                         commission_amount, commission_rate, gross_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                               description, paystack_reference
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ) VALUES (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                         v_payment.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                               COALESCE(v_payment.booking_type, v_payment.type, 'unknown'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     COALESCE(v_payment.payee_user_id, v_payment.user_id),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           v_payment.amount_commission,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 COALESCE(v_payment.commission_rate, 0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       COALESCE(v_payment.amount_total, v_payment.amount, 0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             format('Commission from %s (N%s)',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     COALESCE(v_payment.booking_type, v_payment.type, 'unknown'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             COALESCE(v_payment.amount_total, v_payment.amount, 0)::text),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   p_reference
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           IF v_payment.purpose = 'worker_verification' THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               UPDATE profiles SET
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     worker_status = 'approved_for_verification',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           updated_at = NOW()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               WHERE user_id = v_payment_user_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     AND worker_status = 'pending';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         GET DIAGNOSTICS v_updated = ROW_COUNT;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             IF v_updated = 0 THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   UPDATE profiles SET
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           worker_status = 'approved_for_verification',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   updated_at = NOW()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         WHERE user_id = v_payment_user_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 AND worker_status = 'rejected';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       GET DIAGNOSTICS v_updated = ROW_COUNT;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               INSERT INTO financial_audit_logs (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   event_type, user_id, amount, reference_id, reference_type, description
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ) VALUES (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         CASE WHEN v_payment.purpose = 'worker_verification'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  THEN 'worker_verification_payment'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           ELSE 'customer_payment' END,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               v_payment_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   p_verified_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       v_payment.id::text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           'booking_payment',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               format('Payment confirmed via %s: %s', p_verification_source, p_reference)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   RETURN jsonb_build_object('success', true, 'payment_id', v_payment.id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   $$;


--
-- Name: confirm_current_device_with_google(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_current_device_with_google(p_session_id uuid, p_device_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_auth_id text := (select auth.uid())::text;
  v_user_id text := public.current_profile_user_id();
  v_auth_session_id text := nullif((select auth.jwt() ->> 'session_id'), '');
  v_google_verified boolean := false;
  v_target public.user_sessions%rowtype;
begin
  select exists(
    select 1
    from jsonb_array_elements(coalesce((select auth.jwt() -> 'amr'), '[]'::jsonb)) as method
    where method ->> 'method' = 'oauth'
  ) into v_google_verified;

  if v_auth_id is null or v_user_id is null or v_auth_session_id is null then
    raise exception 'Authentication session is required';
  end if;
  if not v_google_verified then raise exception 'Continue with Google to confirm this login'; end if;

  select * into v_target
  from public.user_sessions
  where id = p_session_id
    and user_id = v_user_id
    and auth_id = v_auth_id
    and device_id = p_device_id
    and trust_status = 'pending'
  for update;
  if not found then raise exception 'Pending device confirmation not found'; end if;

  update public.user_sessions
  set trust_status = 'trusted',
      trust_reviewed_at = now(),
      auth_session_id = v_auth_session_id,
      is_active = true,
      is_current = true,
      last_seen = now()
  where id = v_target.id;

  update public.notifications
  set type = 'new_device_login',
      title = 'New login to your account',
      message = concat_ws(
        ' · ',
        v_target.device,
        v_target.os,
        v_target.browser,
        destination_params ->> 'location'
      ),
      read = false,
      read_at = null,
      destination_route = 'security',
      destination_params = coalesce(destination_params, '{}'::jsonb) || jsonb_build_object(
        'session_id', v_target.id,
        'device', v_target.device,
        'os', v_target.os,
        'browser', v_target.browser,
        'login_time', v_target.login_time,
        'decision', 'unreviewed'
      )
  where recipient_id = v_user_id
    and source_id = v_target.id::text
    and type in ('device_confirmation_pending', 'new_device_login');

  return jsonb_build_object('session_id', v_target.id, 'trust_status', 'trusted');
end;
$$;


--
-- Name: confirm_hotel_check_in_by_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_hotel_check_in_by_code(p_booking_code text) RETURNS public.hotel_bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_verified jsonb;
  v_booking public.hotel_bookings;
begin
  v_verified := public.verify_branch_booking_code(p_booking_code);
  if v_verified is null or v_verified->>'kind' <> 'hotel' then
    raise exception 'Hotel booking not found';
  end if;
  if coalesce((v_verified->>'can_check_in')::boolean, false) is not true then
    raise exception 'This code cannot check in a guest in its current payment, date or booking state';
  end if;

  update public.hotel_bookings
  set status = 'checked_in', updated_at = now()
  where booking_id = (v_verified->>'booking_id')::integer
    and booking_code = upper(btrim(p_booking_code))
    and status = 'confirmed'
    and payment_status = 'paid'
    and paid_at is not null
  returning * into v_booking;
  if v_booking.booking_id is null then
    raise exception 'Hotel booking changed before check-in; verify the code again';
  end if;
  return v_booking;
end;
$$;


--
-- Name: confirm_my_move_in(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_my_move_in(p_reservation_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_reservation public.reservations;
  v_start date:=current_date;
  v_end date;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text and role='user'
  limit 1;
  if v_actor is null or coalesce(v_actor.deleted,false) or coalesce(v_actor.suspended,false) or coalesce(v_actor.banned,false) then
    raise exception 'Active user account required';
  end if;

  select * into v_reservation
  from public.reservations
  where id=p_reservation_id and user_id=v_actor.user_id
  for update;
  if v_reservation.id is null then raise exception 'Reservation not found'; end if;
  if v_reservation.stay_type='short_let' then
    raise exception 'Short Let check-in is confirmed by Housing Operations with the booking code';
  end if;
  if v_reservation.status='occupied' then
    return jsonb_build_object('success',true,'already_confirmed',true,'status','occupied','tenancy_start_date',v_reservation.tenancy_start_date,'tenancy_end_date',v_reservation.tenancy_end_date);
  end if;
  if v_reservation.status<>'ready_for_move_in' then raise exception 'This home is not ready for move-in confirmation'; end if;
  if v_reservation.rent_payment_status not in ('paid','upfront_paid') then raise exception 'Rent payment must be confirmed first'; end if;

  v_end:=(v_start+make_interval(years=>greatest(1,coalesce(v_reservation.rental_plan_years,1))))::date;
  update public.reservations
  set status='occupied',tenancy_start_date=v_start,tenancy_end_date=v_end,occupancy_started_at=now(),updated_at=now()
  where id=v_reservation.id;

  update public.listings
  set status='occupied',availability_status='unavailable',occupied_by=v_actor.user_id,occupied_at=now(),tenancy_ends_at=v_end,reserved_by=null,reservation_expiry=null,updated_at=now()
  where id::text=v_reservation.listing_id;
  if not found then raise exception 'Reservation listing was not found'; end if;

  insert into public.audit_logs(action,target_type,target_id,details,admin_id,admin_email)
  values('USER_MOVE_IN_CONFIRMED','reservations',v_reservation.id,jsonb_build_object('booking_code',v_reservation.booking_code,'tenancy_start_date',v_start,'tenancy_end_date',v_end)::text,v_actor.user_id,v_actor.email);

  return jsonb_build_object('success',true,'status','occupied','tenancy_start_date',v_start,'tenancy_end_date',v_end);
end;
$$;


--
-- Name: confirm_shared_housing_payment(text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_shared_housing_payment(p_reference text, p_transaction_id text, p_verified_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_payment public.booking_payments;
  v_member public.shared_housing_members;
  v_group public.shared_housing_groups;
  v_listing public.listings;
  v_reservation public.reservations;
  v_reservation_id text;
  v_creator text;
begin
  select * into v_payment from public.booking_payments
  where paystack_reference=p_reference and purpose='shared_housing_share' for update;
  if v_payment.id is null then raise exception 'Shared payment not found'; end if;
  if v_payment.status in('paid','completed') then
    return jsonb_build_object('success',true,'already_processed',true); end if;
  if round(coalesce(v_payment.amount_total,v_payment.amount)*100)
    <>round(p_verified_amount*100) then raise exception 'Shared payment amount mismatch'; end if;
  select * into v_member from public.shared_housing_members
  where id=(v_payment.metadata->>'legacy_shared_member_id')::uuid for update;
  select * into v_group from public.shared_housing_groups
  where id=v_member.group_id for update;
  if v_member.id is null or v_group.id is null then raise exception 'Shared payment identity is missing'; end if;
  if v_payment.metadata->>'checkout_attempt'<>v_group.checkout_attempt::text then
    raise exception 'Shared payment belongs to an earlier checkout attempt'; end if;
  select * into v_listing from public.listings where id=v_group.listing_id for update;

  update public.booking_payments set
    status='paid',paystack_transaction_id=p_transaction_id,
    verified_amount=p_verified_amount,verified_at=now(),paid_at=now(),
    webhook_processed=true,verification_source='webhook',updated_at=now()
  where id=v_payment.id;
  update public.shared_housing_members set payment_status='paid',paid_at=now(),updated_at=now()
  where id=v_member.id;
  update public.shared_payment_members set payment_state='paid',paid_at=now(),updated_at=now()
  where shared_payment_member_id=v_member.canonical_member_id;

  -- The Long Let reservation charge is refundable if the coordinated checkout
  -- fails, so it receives a zero-commission protected balance for this attempt.
  if v_group.product_type='long_let' and v_group.payment_phase='reservation_fee' then
    select user_id into v_creator from public.profiles
    where role='creator' and not coalesce(deleted,false) order by created_at limit 1;
    if v_creator is null then raise exception 'Creator financial authority is unavailable'; end if;
    insert into public.payment_protection_transactions(
      booking_id,booking_type,payer_user_id,payee_user_id,amount_total,
      amount_commission,amount_payee,commission_rate,status,paystack_reference,
      protection_state,subject_type,subject_id
    ) values(
      null,'shared_reservation_fee',v_member.user_id,v_creator,v_member.share_amount,
      0,v_member.share_amount,0,'protected',p_reference,'awaiting_funds',
      'shared_housing_share',v_payment.metadata->>'shared_member_id'
    ) on conflict(subject_type,subject_id) do update
      set paystack_reference=excluded.paystack_reference,updated_at=now();
  end if;

  if not exists(
    select 1 from public.shared_housing_members
    where group_id=v_group.id and invitation_status='accepted' and payment_status<>'paid'
  ) then
    if now()>v_group.expires_at then
      update public.shared_housing_groups set status='refunding',updated_at=now()
      where id=v_group.id;
      update public.shared_payment_groups set status='refunding',updated_at=now()
      where shared_payment_group_id=v_group.canonical_group_id;
      return jsonb_build_object('success',true,'group_id',v_group.id,'refund_required',true);
    elsif v_group.product_type='long_let' and v_group.payment_phase='reservation_fee' then
      v_reservation_id:=gen_random_uuid()::text;
      insert into public.reservations(
        id,listing_id,user_id,listing_title,listing_price,listing_location,status,
        amount,currency,paid_at,manual_payment_status,reservation_type,stay_type,
        hold_expires_at,annual_rent_snapshot,contract_rent_total,
        upfront_rent_required,rent_payment_status,booking_code,occupant_count,
        canonical_state,shared_payment_group_id,created_at,updated_at
      ) values(
        v_reservation_id,v_listing.id::text,v_group.created_by,v_listing.title,
        v_listing.price,concat_ws(', ',v_listing.address,v_listing.city,v_listing.state),
        'reserved',v_group.reservation_fee_total,'NGN',now(),'paid','apartment','long_stay',
        now()+interval '3 days',v_listing.price,v_listing.price,
        v_listing.price+coalesce(v_listing.security_deposit_amount,0),'not_started',
        'WH-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),
        (select count(*) from public.shared_housing_members
          where group_id=v_group.id and invitation_status='accepted'),
        'hold_active',v_group.id,now(),now()
      );
      update public.listings set status='reserved',availability_status='reserved',
        current_reservation_id=v_reservation_id,reserved_by=v_group.created_by,
        reservation_fee_paid=true,updated_at=now()
      where id=v_listing.id;
      update public.shared_housing_groups set
        status='paid',reservation_id=v_reservation_id,updated_at=now()
      where id=v_group.id;
      update public.shared_payment_groups set
        status='fully_paid',reservation_id=v_reservation_id,updated_at=now()
      where shared_payment_group_id=v_group.canonical_group_id;
    elsif v_group.product_type='short_let' and v_group.payment_phase='short_stay' then
      perform pg_advisory_xact_lock(hashtextextended('short-let:'||v_listing.id::text,0));
      if exists(select 1 from public.reservations other
        where other.listing_id=v_listing.id::text and other.id<>v_group.reservation_id
          and other.stay_type='short_let'
          and other.status=any(array['reserved','ready_for_move_in','occupied']::text[])
          and daterange(other.stay_check_in,other.stay_check_out,'[)')
            && daterange(v_group.stay_check_in,v_group.stay_check_out,'[)')) then
        update public.shared_housing_groups set status='refunding',updated_at=now()
        where id=v_group.id;
        update public.shared_payment_groups set status='refunding',updated_at=now()
        where shared_payment_group_id=v_group.canonical_group_id;
        update public.reservations set status='payment_conflict',canonical_state='payment_conflict',updated_at=now()
        where id=v_group.reservation_id;
        return jsonb_build_object('success',true,'group_id',v_group.id,'refund_required',true,'conflict',true);
      end if;
      update public.reservations set
        status='reserved',manual_payment_status='paid',paid_at=now(),
        rent_payment_status='paid',rent_paid_at=now(),canonical_state='payment_confirmed',
        security_deposit_status=case when coalesce(security_deposit_snapshot,0)>0
          then 'held' else 'not_required' end,payment_expires_at=null,updated_at=now()
      where id=v_group.reservation_id returning * into v_reservation;
      insert into public.short_let_booking_transitions(
        reservation_id,from_state,to_state,event_type,event_key,actor_user_id,
        actor_type,metadata
      ) values(
        v_reservation.id,'checkout_pending','payment_confirmed','shared_checkout_paid',
        'short-let-shared-paid:'||v_group.id,v_group.created_by,'customer',
        jsonb_build_object('shared_payment_group_id',v_group.id,
          'guest_count',v_group.guest_count,'date_specific_availability',true)
      ) on conflict(event_key) do nothing;
      update public.shared_housing_groups set status='paid',payment_phase='complete',updated_at=now()
      where id=v_group.id;
      update public.shared_payment_groups set status='fully_paid',updated_at=now()
      where shared_payment_group_id=v_group.canonical_group_id;
    else
      update public.reservations set rent_payment_status='paid',rent_paid_at=now(),updated_at=now()
      where id=v_group.reservation_id;
      update public.shared_housing_groups set status='paid',payment_phase='complete',updated_at=now()
      where id=v_group.id;
      update public.shared_payment_groups set status='fully_paid',updated_at=now()
      where shared_payment_group_id=v_group.canonical_group_id;
    end if;
  end if;
  return jsonb_build_object('success',true,'group_id',v_group.id);
end
$$;


--
-- Name: confirm_short_stay_check_in_by_code(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_short_stay_check_in_by_code(p_booking_code text, p_check_in_date date DEFAULT CURRENT_DATE) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_verified jsonb; v_result public.reservations;
begin
  v_verified:=public.verify_branch_booking_code(p_booking_code);
  if v_verified is null
    or v_verified->>'kind'<>'housing'
    or v_verified->>'stay_type'<>'short_let'
  then
    raise exception 'Enter a valid Short Let booking code';
  end if;
  select public.activate_short_stay(v_verified->>'reservation_id',p_check_in_date)
  into v_result;
  return v_result;
end;
$$;


--
-- Name: confirm_worker_booking_payment(uuid, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_worker_booking_payment(p_booking_id uuid, p_paystack_reference text, p_amount_verified numeric, p_currency text DEFAULT 'NGN'::text, p_transaction_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_booking public.worker_bookings;
  v_payment public.booking_payments;
  v_worker public.profiles;
  v_blocker public.profiles;
  v_rate numeric;
  v_commission numeric;
  v_receives numeric;
  v_case_id uuid;
begin
  if nullif(btrim(p_paystack_reference),'') is null then
    return jsonb_build_object('success',false,'error','Paystack reference is required');
  end if;
  if p_amount_verified is null or p_amount_verified<=0 then
    return jsonb_build_object('success',false,'error','Verified amount must be positive');
  end if;
  if p_currency<>'NGN' then
    return jsonb_build_object('success',false,'error','Only NGN currency is supported');
  end if;

  select * into v_payment from public.booking_payments
  where paystack_reference=p_paystack_reference for update;
  if v_payment.id is null
     or v_payment.purpose is distinct from 'worker_booking'
     or v_payment.worker_booking_id is null
     or v_payment.worker_booking_id<>p_booking_id then
    return jsonb_build_object('success',false,'error','Payment record mismatch');
  end if;
  if exists(
    select 1 from public.verified_paystack_references reference
    where reference.paystack_reference=p_paystack_reference
  ) or v_payment.status in ('paid','completed','review_required') then
    return jsonb_build_object(
      'success',true,
      'already_processed',true,
      'requires_review',v_payment.status='review_required'
    );
  end if;

  select * into v_booking from public.worker_bookings where id=p_booking_id for update;
  if v_booking.id is null then
    return jsonb_build_object('success',false,'error','Booking not found');
  end if;
  if v_payment.payer_user_id<>v_booking.user_id then
    return jsonb_build_object('success',false,'error','Payment payer does not match booking customer');
  end if;
  if round(coalesce(v_payment.amount_total,v_payment.amount,0)::numeric,2)
       <>round(p_amount_verified,2)
     or round(coalesce(v_booking.negotiated_amount,v_booking.agreed_amount,0)::numeric,2)
       <>round(p_amount_verified,2) then
    return jsonb_build_object('success',false,'error','Amount mismatch');
  end if;

  select nullif(btrim(setting.value),'')::numeric into v_rate
  from public.platform_settings setting
  where setting.key='worker_commission_rate' and setting.is_active=true;
  if v_rate is null or v_rate<0 or v_rate>50 then
    return jsonb_build_object('success',false,'error','Invalid commission rate');
  end if;
  v_commission:=round((p_amount_verified*v_rate/100)::numeric,2);
  v_receives:=round(p_amount_verified,2)-v_commission;

  if v_booking.status<>'waiting_payment' then
    select blocker_profile.* into v_blocker
    from public.worker_user_blocks block_row
    join public.profiles blocker_profile on blocker_profile.user_id=block_row.blocker_user_id
    where (block_row.blocker_user_id=v_booking.user_id and block_row.blocked_user_id=v_booking.worker_id)
       or (block_row.blocker_user_id=v_booking.worker_id and block_row.blocked_user_id=v_booking.user_id)
    order by block_row.created_at desc
    limit 1;
    if v_blocker.user_id is null or v_booking.status not in ('cancelled','disputed') then
      return jsonb_build_object('success',false,'error','Booking is not awaiting payment');
    end if;

    update public.worker_bookings
    set status='disputed',paystack_reference=p_paystack_reference,
        paystack_transaction_id=p_transaction_id,
        agreed_amount=round(p_amount_verified,2),wehouse_fee=v_commission,
        worker_commission=v_commission,worker_receives=v_receives,
        dispute_reason=concat_ws(E'\n',nullif(dispute_reason,''),
          'Payment completed after contact was blocked; WeHouse review required.'),
        updated_at=now()
    where id=p_booking_id;

    insert into public.payment_protection_transactions(
      booking_id,booking_type,payer_user_id,payee_user_id,amount_total,
      amount_commission,amount_payee,commission_rate,status,paystack_reference,
      created_at,updated_at
    ) values(
      p_booking_id,'worker_booking',v_booking.user_id,v_booking.worker_id,
      round(p_amount_verified,2),v_commission,v_receives,v_rate,'protected',
      p_paystack_reference,now(),now()
    ) on conflict do nothing;

    update public.booking_payments
    set status='review_required',
        paystack_transaction_id=coalesce(p_transaction_id,paystack_transaction_id),
        verified_amount=round(p_amount_verified,2),verified_at=now(),
        verification_source='edge_function',paid_at=now(),
        webhook_processed=true,updated_at=now()
    where id=v_payment.id;
    insert into public.verified_paystack_references(
      paystack_reference,booking_payment_id,verified_amount,
      verification_source,verified_by
    ) values(
      p_paystack_reference,v_payment.id,round(p_amount_verified,2),
      'edge_function','paystack-verify'
    ) on conflict(paystack_reference) do nothing;

    select conversation.id into v_case_id
    from public.partner_support_conversations conversation
    where conversation.partner_id=v_blocker.user_id
      and conversation.context_type='worker_booking'
      and conversation.context_id=p_booking_id::text
    order by conversation.created_at desc limit 1;
    if v_case_id is null then
      insert into public.partner_support_conversations(
        partner_id,requester_role,subject,status,category,context_type,
        context_id,context_snapshot,priority,channel_kind,created_at,updated_at
      ) values(
        v_blocker.user_id,v_blocker.role,
        'Service booking payment review · '||coalesce(v_booking.booking_code,'Booking'),
        'open','payment','worker_booking',p_booking_id::text,
        jsonb_build_object(
          'source_type','worker_booking','booking_id',p_booking_id,
          'booking_code',v_booking.booking_code,'service_type',v_booking.service_type,
          'status','disputed','payment_status','review_required'
        ),
        'urgent','support_case',now(),now()
      ) returning id into v_case_id;
    else
      update public.partner_support_conversations
      set status=case when status in ('resolved','closed') then 'open' else status end,
          priority='urgent',
          context_snapshot=context_snapshot||jsonb_build_object(
            'status','disputed','payment_status','review_required'
          ),
          updated_at=now()
      where id=v_case_id;
    end if;
    insert into public.partner_support_messages(
      conversation_id,sender_id,sender_role,content,action_type,
      action_metadata,created_at
    ) values(
      v_case_id,v_blocker.user_id,v_blocker.role,
      'Paystack confirmed payment after contact was blocked. The money is protected and needs WeHouse review.',
      'status_change',jsonb_build_object('context_id',p_booking_id,'payment_status','review_required'),now()
    );
    return jsonb_build_object(
      'success',true,'requires_review',true,'payment_protected',true,
      'commission_rate',v_rate,'commission_amount',v_commission,
      'worker_receives',v_receives
    );
  end if;

  select * into v_worker from public.profiles
  where user_id=v_booking.worker_id and public.user_has_active_workspace(user_id,'worker');
  if v_worker.user_id is null or v_worker.worker_status<>'verified'
     or v_worker.worker_verified is distinct from true
     or coalesce(v_worker.deleted,false) or coalesce(v_worker.suspended,false)
     or coalesce(v_worker.banned,false) then
    return jsonb_build_object('success',false,'error','Worker is no longer eligible for payment');
  end if;
  if exists(
    select 1 from public.payment_protection_transactions protection
    where protection.booking_id=p_booking_id and protection.booking_type='worker_booking'
  ) then
    return jsonb_build_object('success',false,'error','Payment Protection already exists for this booking');
  end if;
  update public.worker_bookings
  set status='confirmed',paystack_reference=p_paystack_reference,
      paystack_transaction_id=p_transaction_id,
      agreed_amount=round(p_amount_verified,2),wehouse_fee=v_commission,
      worker_commission=v_commission,worker_receives=v_receives,updated_at=now()
  where id=p_booking_id;
  insert into public.payment_protection_transactions(
    booking_id,booking_type,payer_user_id,payee_user_id,amount_total,
    amount_commission,amount_payee,commission_rate,status,paystack_reference,
    created_at,updated_at
  ) values(
    p_booking_id,'worker_booking',v_booking.user_id,v_booking.worker_id,
    round(p_amount_verified,2),v_commission,v_receives,v_rate,'protected',
    p_paystack_reference,now(),now()
  );
  update public.booking_payments
  set status='paid',paystack_transaction_id=coalesce(p_transaction_id,paystack_transaction_id),
      verified_amount=round(p_amount_verified,2),verified_at=now(),
      verification_source='edge_function',paid_at=now(),
      webhook_processed=true,updated_at=now()
  where id=v_payment.id;
  insert into public.verified_paystack_references(
    paystack_reference,booking_payment_id,verified_amount,
    verification_source,verified_by
  ) values(
    p_paystack_reference,v_payment.id,round(p_amount_verified,2),
    'edge_function','paystack-verify'
  ) on conflict(paystack_reference) do nothing;
  return jsonb_build_object(
    'success',true,'commission_rate',v_rate,'commission_amount',v_commission,
    'worker_receives',v_receives
  );
end;
$$;


--
-- Name: confirm_worker_pro_paystack_charge(text, text, numeric, text, text, text, timestamp with time zone, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_worker_pro_paystack_charge(p_reference text, p_transaction_id text, p_verified_amount numeric, p_currency text, p_subscription_code text, p_event_id text, p_event_time timestamp with time zone, p_environment text, p_payload_sha256 text, p_safe_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_payment public.booking_payments;
  v_subscription public.worker_pro_subscriptions;
  v_result jsonb;
  v_period_start timestamptz:=coalesce(p_event_time,now());
  v_period_end timestamptz;
  v_billing_period text;
begin
  select * into v_payment from public.booking_payments
  where paystack_reference=p_reference and purpose='worker_pro_subscription'
  for update;
  if v_payment is null then return jsonb_build_object('success',false,'error','Paid plan payment not found'); end if;
  if v_payment.status in('paid','completed') then return jsonb_build_object('success',true,'already_processed',true); end if;
  if v_payment.status<>'pending' then return jsonb_build_object('success',false,'error','Paid plan payment is not pending'); end if;
  if upper(coalesce(p_currency,''))<>'NGN' then return jsonb_build_object('success',false,'error','Currency mismatch'); end if;
  if round(coalesce(v_payment.amount_total,v_payment.amount,0)*100)<>round(coalesce(p_verified_amount,0)*100) then return jsonb_build_object('success',false,'error','Amount mismatch'); end if;

  select * into v_subscription from public.worker_pro_subscriptions
  where worker_id=v_payment.user_id for update;
  if v_subscription.id is not null and v_subscription.provider<>'paystack'
     and v_subscription.status in('active','grace_period')
     and v_subscription.current_period_end>now() then
    update public.booking_payments set
      status='review_required',verified_amount=p_verified_amount,
      verified_at=now(),verification_source='webhook',updated_at=now(),
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'billing_conflict',true,'active_provider',v_subscription.provider,
        'incoming_provider','paystack','paystack_transaction_id',p_transaction_id
      )
    where id=v_payment.id;
    return jsonb_build_object(
      'success',false,'conflict',true,'active_provider',v_subscription.provider,
      'payment_id',v_payment.id
    );
  end if;

  v_billing_period:=coalesce(nullif(v_payment.metadata->>'billing_period',''),'monthly');
  if v_billing_period not in('monthly','yearly') then return jsonb_build_object('success',false,'error','Invalid billing period'); end if;
  v_period_end:=case when v_billing_period='yearly'
    then v_period_start+interval '1 year'
    else v_period_start+interval '1 month' end;

  update public.booking_payments set
    status='paid',paystack_transaction_id=nullif(btrim(coalesce(p_transaction_id,'')),''),
    verified_amount=p_verified_amount,verified_at=now(),verification_source='webhook',
    paid_at=v_period_start,webhook_processed=true,updated_at=now(),
    metadata=coalesce(metadata,'{}'::jsonb)
      ||jsonb_build_object('subscription_code',nullif(btrim(coalesce(p_subscription_code,'')),''))
      ||coalesce(p_safe_metadata,'{}'::jsonb)
  where id=v_payment.id;

  select public.record_worker_pro_subscription_event(
    v_payment.user_id,'paystack',v_payment.metadata->>'plan_code',p_subscription_code,
    p_event_id,'charge.success','active',v_period_start,v_period_start,v_period_end,
    false,true,p_verified_amount,'NGN',p_environment,p_payload_sha256,
    coalesce(p_safe_metadata,'{}'::jsonb)||jsonb_build_object('billing_period',v_billing_period)
  ) into v_result;
  return coalesce(v_result,'{}'::jsonb)||jsonb_build_object(
    'payment_id',v_payment.id,'billing_period',v_billing_period
  );
end;
$$;


--
-- Name: create_apartment_rent_payment(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_apartment_rent_payment(p_reservation_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_user_id text; v_res public.reservations; v_listing public.listings; v_reference text; v_pending public.booking_payments;
  v_annual numeric; v_total numeric; v_upfront numeric; v_balance numeric; v_count integer; v_years integer;
BEGIN
  SELECT user_id INTO v_user_id FROM public.profiles
  WHERE auth_id=auth.uid()::text AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_res FROM public.reservations WHERE id=p_reservation_id AND user_id=v_user_id FOR UPDATE;
  IF v_res.id IS NULL THEN RAISE EXCEPTION 'Reservation not found'; END IF;
  IF v_res.status='inspection_pending' THEN RAISE EXCEPTION 'Complete the requested inspection before paying Long Stay rent'; END IF;
  IF v_res.status NOT IN ('reserved','ready_for_move_in') THEN RAISE EXCEPTION 'Reservation is not ready for Long Stay rent payment'; END IF;
  IF v_res.manual_payment_status NOT IN ('paid','completed') OR v_res.paid_at IS NULL THEN RAISE EXCEPTION 'Reservation fee must be confirmed first'; END IF;
  IF v_res.rent_payment_status IN ('paid','upfront_paid') THEN RETURN jsonb_build_object('success',true,'already_paid',true,'status',v_res.rent_payment_status); END IF;
  SELECT * INTO v_listing FROM public.listings WHERE id::text=v_res.listing_id FOR SHARE;
  IF v_listing.id IS NULL THEN RAISE EXCEPTION 'Listing not found'; END IF;
  IF v_listing.sub_type<>'long_stay' THEN RAISE EXCEPTION 'Short Stay uses a date-based stay payment workflow'; END IF;

  v_years:=COALESCE(v_res.rental_plan_years,1);
  IF v_years<1 OR v_years>5 THEN RAISE EXCEPTION 'Reservation tenure must be between 1 and 5 years'; END IF;
  v_annual:=round(COALESCE(v_res.annual_rent_snapshot,v_listing.price),2);
  IF v_annual<=0 THEN RAISE EXCEPTION 'Required Year 1 rent is invalid'; END IF;
  v_total:=round(v_annual*v_years,2); v_upfront:=v_annual; v_balance:=round(v_annual*GREATEST(v_years-1,0),2); v_count:=8*GREATEST(v_years-1,0);

  SELECT * INTO v_pending FROM public.booking_payments
  WHERE user_id=v_user_id AND purpose='apartment_rent' AND status='pending' AND metadata->>'reservation_id'=v_res.id
    AND round(COALESCE(amount_total,amount),2)=round(v_upfront,2)
  ORDER BY created_at DESC LIMIT 1;
  IF v_pending.id IS NOT NULL THEN
    UPDATE public.reservations SET rent_payment_status='payment_pending',rent_payment_reference=v_pending.paystack_reference,updated_at=now() WHERE id=v_res.id;
    RETURN jsonb_build_object('success',true,'reference',v_pending.paystack_reference,'amount',COALESCE(v_pending.amount_total,v_pending.amount),'existing',true);
  END IF;

  v_reference:='WHRENT-'||upper(replace(gen_random_uuid()::text,'-',''));
  INSERT INTO public.booking_payments(payment_reference,user_id,payer_user_id,type,booking_type,listing_id,amount,amount_total,currency,status,purpose,payment_method,paystack_reference,metadata,created_at,updated_at)
  VALUES(v_reference,v_user_id,v_user_id,'apartment','apartment',v_listing.id::text,v_upfront,v_upfront,'NGN','pending','apartment_rent','paystack',v_reference,
    jsonb_build_object('reservation_id',v_res.id,'listing_id',v_listing.id::text,'tenure_years',v_years,'total_contract_rent',v_total,'year_one_upfront',v_upfront,'future_rent_balance',v_balance,'contribution_count',v_count,'contribution_months_per_year',8,'start_after_months',4,'payment_component','long_stay_rent','security_deposit_amount',0,'eligible_partner_amount',v_upfront),now(),now());
  UPDATE public.reservations
  SET stay_type='long_stay',annual_rent_snapshot=v_annual,contract_rent_total=v_total,upfront_rent_required=v_upfront,installment_balance=v_balance,installment_count=v_count,
      rent_payment_status='payment_pending',rent_payment_reference=v_reference,updated_at=now()
  WHERE id=v_res.id;
  RETURN jsonb_build_object('success',true,'reference',v_reference,'amount',v_upfront,'existing',false);
END;
$$;


--
-- Name: create_apartment_reservation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_apartment_reservation(p_listing_id text) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_profile public.profiles;
  v_listing public.listings;
  v_existing public.reservations;
  v_created public.reservations;
  v_fee numeric;
  v_checkout_minutes integer;
  v_checkout_expires timestamptz;
  v_reference text;
BEGIN
  SELECT * INTO v_profile FROM public.profiles
  WHERE auth_id=auth.uid()::text
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false
  LIMIT 1;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF v_profile.role NOT IN ('user','worker','property_partner') THEN RAISE EXCEPTION 'This account cannot create customer reservations'; END IF;

  SELECT * INTO v_listing FROM public.listings
  WHERE (id::text=p_listing_id OR listing_id=p_listing_id) AND deleted_at IS NULL
  LIMIT 1 FOR UPDATE;
  IF v_listing IS NULL THEN RAISE EXCEPTION 'Listing not found'; END IF;
  IF COALESCE(v_listing.sub_type,'')<>'long_stay' THEN
    RAISE EXCEPTION 'Short Stay requires check-in and check-out dates';
  END IF;

  SELECT * INTO v_existing FROM public.reservations
  WHERE listing_id=v_listing.id::text AND user_id=v_profile.user_id
    AND status = ANY (ARRAY['payment_pending','reserved','inspection_pending','ready_for_move_in','occupied']::text[])
  ORDER BY created_at DESC LIMIT 1;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

  IF v_listing.status<>'available' OR v_listing.availability_status<>'available' THEN RAISE EXCEPTION 'Listing is not available'; END IF;

  SELECT NULLIF(value,'')::numeric INTO v_fee FROM public.platform_settings WHERE key='reservation_fee' AND COALESCE(is_active,true)=true LIMIT 1;
  IF v_fee IS NULL OR v_fee<=0 THEN RAISE EXCEPTION 'Reservation fee is not configured'; END IF;
  SELECT NULLIF(value,'')::integer INTO v_checkout_minutes FROM public.platform_settings WHERE key='apartment_payment_hold_minutes' AND COALESCE(is_active,true)=true LIMIT 1;
  IF v_checkout_minutes IS NULL OR v_checkout_minutes<5 OR v_checkout_minutes>120 THEN v_checkout_minutes:=30; END IF;
  v_checkout_expires:=now()+make_interval(mins=>v_checkout_minutes);
  v_reference:='WHAPT-'||upper(replace(gen_random_uuid()::text,'-',''));

  INSERT INTO public.reservations(
    listing_id,user_id,user_email,user_phone,listing_title,listing_price,listing_location,
    status,manual_payment_status,payment_reference,amount,currency,reservation_type,stay_type,
    payment_expires_at,hold_expires_at,created_at,updated_at
  ) VALUES (
    v_listing.id::text,v_profile.user_id,v_profile.email,v_profile.phone,v_listing.title,v_listing.price,
    concat_ws(', ',v_listing.city,v_listing.state),'payment_pending','unpaid',v_reference,v_fee,'NGN','apartment','long_stay',
    v_checkout_expires,NULL,now(),now()
  ) RETURNING * INTO v_created;

  INSERT INTO public.booking_payments(
    payment_reference,user_id,payer_user_id,type,booking_type,listing_id,amount,amount_total,currency,status,purpose,payment_method,paystack_reference,metadata,created_at,updated_at
  ) VALUES (
    v_reference,v_profile.user_id,v_profile.user_id,'apartment','apartment',v_listing.id::text,v_fee,v_fee,'NGN','pending',
    'apartment_reservation','paystack',v_reference,jsonb_build_object('reservation_id',v_created.id,'listing_id',v_listing.id::text,'stay_type','long_stay','source','create_apartment_reservation'),now(),now()
  );

  UPDATE public.listings
  SET status='reserved',availability_status='reserved',reserved_by=v_profile.user_id,reservation_expiry=v_checkout_expires,
      reservation_fee_paid=false,chat_unlocked=false,current_reservation_id=v_created.id,updated_at=now()
  WHERE id=v_listing.id;
  RETURN v_created;
END;
$$;


--
-- Name: create_booking_request(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_booking_request(p_worker_id text, p_service_type text, p_description text, p_address text, p_scheduled_date text, p_customer_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_customer public.profiles;
  v_worker public.profiles;
  v_booking_id uuid;
  v_conversation_id uuid;
  v_code text;
  v_date date;
  v_service text:=trim(coalesce(p_service_type,''));
  v_service_ok boolean:=false;
  v_has_specific_services boolean:=false;
begin
  select * into v_customer from public.profiles
  where auth_id=(select auth.uid())::text limit 1;
  if v_customer is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Active Personal account required';
  end if;
  if coalesce(v_customer.deleted,false)
     or coalesce(v_customer.suspended,false)
     or coalesce(v_customer.banned,false) then
    raise exception 'Customer account is not active';
  end if;
  if v_service='' then raise exception 'Choose a service'; end if;
  if nullif(trim(coalesce(p_description,'')),'') is null then
    raise exception 'Describe the work you need';
  end if;
  if nullif(trim(coalesce(p_address,'')),'') is null then
    raise exception 'Job location is required';
  end if;
  if nullif(trim(coalesce(p_scheduled_date,'')),'') is not null then
    v_date:=p_scheduled_date::date;
    if v_date<current_date then raise exception 'Schedule date cannot be in the past'; end if;
  end if;
  select * into v_worker from public.profiles
  where user_id=p_worker_id limit 1;
  if v_worker is null
     or not public.user_has_active_workspace(p_worker_id,'worker') then
    raise exception 'Worker not found';
  end if;
  if v_worker.worker_status<>'verified'
     or v_worker.worker_verified is distinct from true then
    raise exception 'Worker is not verified';
  end if;
  if not public.worker_identity_is_current(v_worker.user_id) then
    raise exception 'This Worker is temporarily unavailable while identity is re-checked';
  end if;
  if v_worker.available is distinct from true then
    raise exception 'Worker is not accepting new bookings';
  end if;
  if coalesce(v_worker.deleted,false)
     or coalesce(v_worker.suspended,false)
     or coalesce(v_worker.banned,false) then
    raise exception 'Worker account is not active';
  end if;
  if v_customer.user_id=p_worker_id then raise exception 'Cannot book yourself'; end if;
  v_has_specific_services:=exists(
    select 1 from public.worker_services service
    where service.worker_id=v_worker.user_id
  ) or (
    jsonb_typeof(v_worker.worker_skills)='array'
    and jsonb_array_length(v_worker.worker_skills)>0
  );
  v_service_ok:=exists(
    select 1 from public.worker_services service
    where service.worker_id=v_worker.user_id
      and lower(trim(service.service_name))=lower(v_service)
  ) or exists(
    select 1
    from jsonb_array_elements_text(
      case when jsonb_typeof(v_worker.worker_skills)='array'
        then v_worker.worker_skills else '[]'::jsonb end
    ) skill(value)
    where lower(trim(skill.value))=lower(v_service)
  ) or (
    not v_has_specific_services
    and lower(trim(coalesce(v_worker.worker_occupation,'')))=lower(v_service)
  );
  if not v_service_ok then
    raise exception 'This Worker does not offer the selected service';
  end if;
  v_code:='WH-'||upper(substring(md5(gen_random_uuid()::text) from 1 for 8));
  insert into public.worker_bookings(
    booking_code,user_id,worker_id,service_type,description,address,
    scheduled_date,agreed_amount,wehouse_fee,worker_commission,
    worker_receives,status,customer_message,created_at,updated_at
  ) values(
    v_code,v_customer.user_id,v_worker.user_id,v_service,
    trim(p_description),trim(p_address),v_date,0,0,0,0,
    'booking_requested',nullif(trim(coalesce(p_customer_message,'')),''),
    now(),now()
  ) returning id into v_booking_id;
  insert into public.booking_conversations(
    booking_id,user_id,worker_id,status,created_at,updated_at
  ) values(
    v_booking_id,v_customer.user_id,v_worker.user_id,'active',now(),now()
  ) returning id into v_conversation_id;
  update public.worker_bookings
  set booking_conversation_id=v_conversation_id
  where id=v_booking_id;
  if nullif(trim(coalesce(p_customer_message,'')),'') is not null then
    insert into public.booking_messages(
      conversation_id,sender_id,content,created_at
    ) values(
      v_conversation_id,v_customer.user_id,trim(p_customer_message),now()
    );
  end if;
  return jsonb_build_object(
    'booking_id',v_booking_id,'conversation_id',v_conversation_id,
    'booking_code',v_code
  );
end
$$;


--
-- Name: create_booking_request_v2(text, text, text, text, text, text, text, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_booking_request_v2(p_worker_id text, p_service_type text, p_description text, p_address text, p_scheduled_date text, p_customer_message text DEFAULT NULL::text, p_location_source text DEFAULT 'manual'::text, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_accuracy_m numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_source text := lower(btrim(coalesce(p_location_source, 'manual')));
  v_result jsonb;
  v_booking_id uuid;
begin
  if v_source not in ('manual', 'current', 'saved') then
    raise exception 'Choose current location, saved location or enter an address';
  end if;
  if (p_latitude is null) <> (p_longitude is null) then
    raise exception 'Location coordinates are incomplete';
  end if;
  if p_latitude is not null and (p_latitude < -90 or p_latitude > 90) then
    raise exception 'Location latitude is invalid';
  end if;
  if p_longitude is not null and (p_longitude < -180 or p_longitude > 180) then
    raise exception 'Location longitude is invalid';
  end if;
  if p_accuracy_m is not null and p_accuracy_m < 0 then
    raise exception 'Location accuracy is invalid';
  end if;
  if v_source in ('current', 'saved')
     and (p_latitude is null or p_longitude is null) then
    raise exception 'This location choice requires coordinates';
  end if;

  -- Do not rely on a stale profile flag. A confirmed onboarding payment must
  -- exist in the ledger at the exact moment a professional is booked.
  if not exists (
    select 1
    from public.booking_payments payment
    where payment.user_id = p_worker_id
      and payment.purpose = 'worker_verification'
      and payment.status in ('paid', 'completed')
  ) then
    raise exception 'This Worker is not available for booking';
  end if;

  v_result := public.create_booking_request(
    p_worker_id,
    p_service_type,
    p_description,
    p_address,
    p_scheduled_date,
    p_customer_message
  );
  v_booking_id := nullif(v_result ->> 'booking_id', '')::uuid;

  update public.worker_bookings
  set service_latitude = p_latitude,
      service_longitude = p_longitude,
      service_location_accuracy_m = p_accuracy_m,
      service_location_source = v_source,
      updated_at = now()
  where id = v_booking_id;

  return v_result || jsonb_build_object('location_source', v_source);
end;
$$;


--
-- Name: create_hotel_booking_payment(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_hotel_booking_payment(p_booking_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id text:=public.current_profile_user_id();
  v_booking public.hotel_bookings;
  v_hotel public.hotels;
  v_reference text;
  v_pending public.booking_payments;
begin
  if v_user_id is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Active Personal account required';
  end if;
  select * into v_booking from public.hotel_bookings
  where booking_id=p_booking_id and user_id=v_user_id for update;
  if v_booking.booking_id is null then raise exception 'Hotel booking not found'; end if;
  if v_booking.status='confirmed' and v_booking.payment_status='paid' then
    return jsonb_build_object(
      'success',true,'already_paid',true,
      'booking_code',v_booking.booking_code
    );
  end if;
  if v_booking.status<>'pending' then
    raise exception 'Hotel booking is no longer awaiting payment';
  end if;
  if v_booking.payment_expires_at is null
     or v_booking.payment_expires_at<=now() then
    update public.hotel_bookings
    set status='expired',payment_status='expired',updated_at=now()
    where booking_id=v_booking.booking_id;
    raise exception 'Hotel checkout hold has expired. Choose the room again.';
  end if;
  if coalesce(v_booking.total_price,0)<=0 then
    raise exception 'Hotel booking amount is invalid';
  end if;
  select * into v_hotel from public.hotels
  where hotel_id=v_booking.hotel_id;
  if v_hotel.hotel_id is null then raise exception 'Hotel not found'; end if;
  select * into v_pending from public.booking_payments
  where user_id=v_user_id and purpose='hotel_booking'
    and hotel_booking_id=v_booking.booking_id and status='pending'
    and round(coalesce(amount_total,amount),2)=round(v_booking.total_price,2)
  order by created_at desc limit 1;
  if v_pending.id is not null then
    update public.hotel_bookings
    set payment_status='payment_pending',
        payment_reference=v_pending.paystack_reference,updated_at=now()
    where booking_id=v_booking.booking_id;
    return jsonb_build_object(
      'success',true,'reference',v_pending.paystack_reference,
      'amount',coalesce(v_pending.amount_total,v_pending.amount),
      'existing',true,'booking_code',v_booking.booking_code
    );
  end if;
  v_reference:='WHHOTEL-'||upper(replace(gen_random_uuid()::text,'-',''));
  insert into public.booking_payments(
    payment_reference,user_id,payer_user_id,type,booking_type,
    hotel_booking_id,amount,amount_total,currency,status,purpose,
    payment_method,paystack_reference,metadata,created_at,updated_at
  ) values(
    v_reference,v_user_id,v_user_id,'hotel','hotel',v_booking.booking_id,
    v_booking.total_price,v_booking.total_price,'NGN','pending',
    'hotel_booking','paystack',v_reference,jsonb_build_object(
      'hotel_booking_id',v_booking.booking_id,
      'hotel_id',v_booking.hotel_id,'hotel_name',v_hotel.name,
      'room_id',v_booking.room_id,'rate_plan_id',v_booking.rate_plan_id,
      'rate_plan_name',v_booking.rate_plan_name,
      'booking_code',v_booking.booking_code,
      'check_in',v_booking.check_in,'check_out',v_booking.check_out,
      'eligible_partner_amount',v_booking.total_price
    ),now(),now()
  );
  update public.hotel_bookings
  set payment_status='payment_pending',payment_reference=v_reference,
      updated_at=now()
  where booking_id=v_booking.booking_id;
  return jsonb_build_object(
    'success',true,'reference',v_reference,'amount',v_booking.total_price,
    'existing',false,'booking_code',v_booking.booking_code
  );
end
$$;


--
-- Name: create_internal_listing(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_internal_listing(p_data jsonb) RETURNS public.listings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ DECLARE v_actor public.profiles; v_initial_status text; v_listing public.listings; BEGIN SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND role IN ('property_partner','staff','admin','creator') AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1; IF v_actor IS NULL THEN RAISE EXCEPTION 'Listing submission is not allowed for this account'; END IF; IF NULLIF(BTRIM(p_data->>'title'),'') IS NULL THEN RAISE EXCEPTION 'Listing title is required'; END IF; IF COALESCE((p_data->>'price')::numeric,0)<=0 THEN RAISE EXCEPTION 'Listing price must be greater than zero'; END IF; IF NULLIF(BTRIM(p_data->>'state'),'') IS NULL OR NULLIF(BTRIM(p_data->>'city'),'') IS NULL THEN RAISE EXCEPTION 'Listing State and LGA are required'; END IF; IF v_actor.role IN ('admin','staff') AND NOT public.current_actor_in_scope(p_data->>'state',p_data->>'city') THEN RAISE EXCEPTION 'Listing is outside your assigned branch'; END IF; v_initial_status:=CASE WHEN v_actor.role='creator' THEN 'available' ELSE 'pending_approval' END; INSERT INTO public.listings(listing_id,title,description,price,currency,state,city,address,images,videos,property_type,sub_type,bedrooms,bathrooms,status,availability_status,owner_id,partner_id,chat_agent_id,submitted_by_role,reserved_by,reservation_expiry,reservation_fee_paid,chat_unlocked,security_deposit_amount,contact_phone,amenities) VALUES(gen_random_uuid()::text,BTRIM(p_data->>'title'),NULLIF(BTRIM(p_data->>'description'),''),(p_data->>'price')::numeric,COALESCE(NULLIF(BTRIM(p_data->>'currency'),''),'NGN'),BTRIM(p_data->>'state'),BTRIM(p_data->>'city'),NULLIF(BTRIM(p_data->>'address'),''),COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_data->'images','[]'::jsonb))),ARRAY[]::text[]),COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_data->'videos','[]'::jsonb))),ARRAY[]::text[]),NULLIF(BTRIM(p_data->>'property_type'),''),NULLIF(BTRIM(p_data->>'sub_type'),''),COALESCE((p_data->>'bedrooms')::int,1),COALESCE((p_data->>'bathrooms')::int,1),v_initial_status,v_initial_status,v_actor.user_id,NULL,CASE WHEN v_actor.role='staff' THEN v_actor.user_id ELSE NULL END,v_actor.role,NULL,NULL,false,false,NULLIF(p_data->>'security_deposit_amount','')::numeric,NULLIF(BTRIM(p_data->>'contact_phone'),''),COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(p_data->'amenities','[]'::jsonb))),ARRAY[]::text[])) RETURNING * INTO v_listing; RETURN v_listing; END; $$;


--
-- Name: create_my_hotel_booking(integer, integer, date, date, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_hotel_booking(p_hotel_id integer, p_room_id integer, p_check_in date, p_check_out date, p_guest_count integer, p_guest_name text, p_guest_phone text, p_special_requests text DEFAULT NULL::text) RETURNS public.hotel_bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_actor public.profiles;
  v_result public.hotel_bookings;
begin
  select * into v_actor from public.profiles
  where auth_id = auth.uid()::text and role = 'user'
    and not coalesce(deleted, false)
    and not coalesce(suspended, false)
    and not coalesce(banned, false)
  limit 1;
  if v_actor is null then raise exception 'Active User account required'; end if;

  insert into public.hotel_bookings(
    hotel_id, room_id, user_id, check_in, check_out, guest_count,
    guest_name, guest_phone, special_requests
  ) values (
    p_hotel_id, p_room_id, v_actor.user_id, p_check_in, p_check_out,
    p_guest_count, btrim(p_guest_name), btrim(p_guest_phone),
    nullif(btrim(p_special_requests), '')
  ) returning * into v_result;
  return v_result;
end;
$$;


--
-- Name: create_my_hotel_booking_with_rate(integer, integer, integer, date, date, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_hotel_booking_with_rate(p_hotel_id integer, p_room_id integer, p_rate_plan_id integer, p_check_in date, p_check_out date, p_guest_count integer, p_guest_name text, p_guest_phone text, p_special_requests text DEFAULT NULL::text) RETURNS public.hotel_bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_actor public.profiles;
  v_result public.hotel_bookings;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Active Personal account required';
  end if;
  insert into public.hotel_bookings(
    hotel_id,room_id,rate_plan_id,user_id,check_in,check_out,guest_count,
    guest_name,guest_phone,special_requests
  ) values(
    p_hotel_id,p_room_id,p_rate_plan_id,v_actor.user_id,p_check_in,p_check_out,
    p_guest_count,btrim(p_guest_name),btrim(p_guest_phone),
    nullif(btrim(p_special_requests),'')
  ) returning * into v_result;
  return v_result;
end
$$;


--
-- Name: create_my_profile(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_profile(p_email text, p_role text DEFAULT 'user'::text) RETURNS public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare
  v_profile public.profiles;
  v_auth_id text:=(select auth.uid())::text;
  v_email text:=lower(trim(coalesce((select auth.jwt()->>'email'),p_email)));
  v_requested_workspace text:=case when p_role in ('worker','property_partner') then p_role else 'user' end;
  v_user_id text;
  v_username text;
  v_partner_code text;
begin
  if (select auth.uid()) is null then raise exception 'Authentication required'; end if;
  if p_role not in ('user','worker','property_partner') then raise exception 'Invalid initial workspace'; end if;
  select * into v_profile from public.profiles where auth_id=v_auth_id;
  if v_profile.user_id is not null then return v_profile; end if;
  if v_email is null or v_email='' then raise exception 'Authenticated email is required'; end if;
  if exists(
    select 1 from public.profiles profile
    where lower(profile.email)=v_email and profile.auth_id<>v_auth_id
  ) then
    raise exception 'This email is already linked to another WeHouse identity. Contact WeHouse Support.';
  end if;

  v_user_id:='WHU-'||lpad(nextval('public.wehouse_user_id_seq')::text,8,'0');
  v_username:=regexp_replace(split_part(v_email,'@',1),'[^a-z0-9_]','','g');
  if length(v_username)<3 then v_username:='member'; end if;
  v_username:=left(v_username,15)||substr(v_user_id,length(v_user_id)-4);

  insert into public.profiles(
    auth_id,email,username,role,user_id,profile_complete,worker_status,account_kind
  ) values(
    v_auth_id,v_email,v_username,v_requested_workspace,v_user_id,false,
    case when v_requested_workspace='worker' then 'pending' else null end,
    'consumer'
  ) returning * into v_profile;

  if v_requested_workspace in ('worker','property_partner') then
    insert into public.workspace_role_assignments(
      user_id,workspace_role,scope_type,status,granted_at,created_at,updated_at
    ) values(
      v_profile.user_id,v_requested_workspace,'global','active',now(),now(),now()
    ) on conflict(user_id,workspace_role) where status='active' do nothing;
  end if;

  if v_requested_workspace='property_partner' then
    v_partner_code:='WHP-'||replace(v_profile.user_id,'WHU-','')||'-'||
      upper(substr(md5(v_profile.user_id||clock_timestamp()::text),1,4));
    insert into public.property_partners(
      profile_id,partner_code,status,commission_rate,total_earnings,
      total_paid_out,properties_count,created_at,updated_at
    ) values(
      v_profile.user_id,v_partner_code,'pending_verification',0,0,0,0,now(),now()
    ) on conflict(profile_id) do nothing;
  end if;
  return v_profile;
end;
$$;


--
-- Name: create_my_property_access_challenge(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_property_access_challenge() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare
  v_actor public.profiles;
  v_row public.property_access_challenges;
  v_code text;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null
     or not public.current_actor_has_workspace('property_partner',null) then
    raise exception 'Property Partner workspace required';
  end if;
  if not public.account_identity_is_current(v_actor.user_id) then
    raise exception 'Complete the private identity check before adding properties';
  end if;
  v_code:=lpad(((('x'||substr(
    encode(extensions.gen_random_bytes(4),'hex'),1,8
  ))::bit(32)::bigint%1000000))::text,6,'0');
  insert into public.property_access_challenges(partner_id,code,expires_at)
  values(v_actor.user_id,v_code,now()+interval '24 hours')
  returning * into v_row;
  return jsonb_build_object(
    'id',v_row.id,'code',v_row.code,'expires_at',v_row.expires_at
  );
end
$$;


--
-- Name: create_my_property_access_correction(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_property_access_correction(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
  v_challenge public.property_access_challenges;
  v_code text;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null
     or not public.current_actor_has_workspace('property_partner',null) then
    raise exception 'Property Partner workspace required';
  end if;
  select * into v_request
  from public.inspection_requests
  where id=p_request_id and owner_id=v_actor.user_id
  for update;
  if v_request.id is null then raise exception 'Property submission not found'; end if;
  if v_request.published_at is not null or v_request.lifecycle_stage='live' then
    raise exception 'A public property does not require new access evidence';
  end if;
  if v_request.lifecycle_stage='rejected'
     or lower(coalesce(v_request.status,''))='rejected' then
    raise exception 'This submission was stopped. Contact WeHouse from Inbox';
  end if;
  if v_request.access_evidence_status<>'rejected' then
    raise exception 'WeHouse has not requested replacement access evidence';
  end if;
  if coalesce(
    v_request.assigned_field_officer_id,
    v_request.field_officer_id,
    v_request.assigned_to
  ) is not null then
    raise exception 'Access evidence cannot be replaced after Field Operations is assigned';
  end if;
  update public.property_access_challenges set status='expired'
  where partner_id=v_actor.user_id and request_id=p_request_id
    and status='prepared';
  v_code:=lpad(((('x'||substr(
    encode(extensions.gen_random_bytes(4),'hex'),1,8
  ))::bit(32)::bigint%1000000))::text,6,'0');
  insert into public.property_access_challenges(
    partner_id,code,expires_at,request_id
  ) values(
    v_actor.user_id,v_code,now()+interval '24 hours',p_request_id
  ) returning * into v_challenge;
  return jsonb_build_object(
    'id',v_challenge.id,'code',v_challenge.code,
    'expires_at',v_challenge.expires_at
  );
end
$$;


--
-- Name: create_my_property_inspection_batch(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_property_inspection_batch(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_profile record;
  v_batch_id uuid := gen_random_uuid();
  v_item jsonb;
  v_position integer;
  v_request_id uuid;
  v_request_code text;
  v_results jsonb := '[]'::jsonb;
  v_photo_urls text[];
  v_amenities text[];
  v_lat numeric;
  v_lng numeric;
  v_accuracy numeric;
  v_address text;
  v_city text;
  v_state text;
  v_type text;
  v_sub_type text;
  v_deposit numeric;
BEGIN
  SELECT user_id,email,phone,role,deleted,suspended,banned
  INTO v_profile
  FROM public.profiles
  WHERE auth_id=auth.uid()::text
  LIMIT 1;

  IF v_profile IS NULL THEN RAISE EXCEPTION 'Profile not found'; END IF;
  IF not public.user_has_active_workspace(v_profile.user_id,'property_partner') THEN RAISE EXCEPTION 'Property Partner account required'; END IF;
  IF COALESCE(v_profile.deleted,false) OR COALESCE(v_profile.suspended,false) OR COALESCE(v_profile.banned,false) THEN
    RAISE EXCEPTION 'Account is not active';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN RAISE EXCEPTION 'Property batch must be an array'; END IF;
  IF jsonb_array_length(p_items) < 1 THEN RAISE EXCEPTION 'Add at least one property'; END IF;
  IF jsonb_array_length(p_items) > 25 THEN RAISE EXCEPTION 'A batch can contain at most 25 properties'; END IF;

  FOR v_item, v_position IN
    SELECT value, ordinality::integer
    FROM jsonb_array_elements(p_items) WITH ORDINALITY
  LOOP
    v_address := NULLIF(BTRIM(v_item->>'property_address'),'');
    v_city := NULLIF(BTRIM(v_item->>'property_city'),'');
    v_state := NULLIF(BTRIM(v_item->>'property_state'),'');
    v_type := NULLIF(BTRIM(v_item->>'property_type'),'');
    v_sub_type := NULLIF(BTRIM(v_item->>'sub_type'),'');
    v_deposit := NULLIF(v_item->>'security_deposit_amount','')::numeric;

    IF v_address IS NULL THEN RAISE EXCEPTION 'Property %: address is required', v_position; END IF;
    IF v_city IS NULL THEN RAISE EXCEPTION 'Property %: city/LGA is required', v_position; END IF;
    IF v_state IS NULL THEN RAISE EXCEPTION 'Property %: state is required', v_position; END IF;
    IF v_type NOT IN ('apartment','hotel') THEN RAISE EXCEPTION 'Property %: choose Apartment or Hotel', v_position; END IF;

    IF v_type='apartment' AND v_sub_type IS NOT NULL AND v_sub_type NOT IN ('short_let','long_stay') THEN
      RAISE EXCEPTION 'Property %: invalid apartment stay type', v_position;
    END IF;
    IF v_type='hotel' THEN
      v_sub_type := NULL;
      v_deposit := NULL;
    ELSIF v_sub_type='short_let' AND COALESCE(v_deposit,0)<=0 THEN
      RAISE EXCEPTION 'Property %: Short Stay requires a refundable security deposit', v_position;
    ELSIF v_sub_type='long_stay' THEN
      v_deposit := NULL;
    END IF;

    v_lat := NULLIF(v_item->>'gps_latitude','')::numeric;
    v_lng := NULLIF(v_item->>'gps_longitude','')::numeric;
    v_accuracy := NULLIF(v_item->>'location_accuracy_m','')::numeric;
    IF (v_lat IS NULL) <> (v_lng IS NULL) THEN RAISE EXCEPTION 'Property %: latitude and longitude must be supplied together', v_position; END IF;
    IF v_lat IS NOT NULL AND (v_lat NOT BETWEEN -90 AND 90 OR v_lng NOT BETWEEN -180 AND 180) THEN
      RAISE EXCEPTION 'Property %: invalid coordinates', v_position;
    END IF;

    SELECT COALESCE(array_agg(value), ARRAY[]::text[])
    INTO v_photo_urls
    FROM jsonb_array_elements_text(COALESCE(v_item->'photo_urls','[]'::jsonb));

    SELECT COALESCE(array_agg(DISTINCT value), ARRAY[]::text[])
    INTO v_amenities
    FROM jsonb_array_elements_text(COALESCE(v_item->'amenities','[]'::jsonb));

    IF v_sub_type='short_let' AND NOT ('Furnished'=ANY(COALESCE(v_amenities,ARRAY[]::text[]))) THEN
      v_amenities := array_append(COALESCE(v_amenities,ARRAY[]::text[]),'Furnished');
    END IF;

    v_request_code := 'WHIR-' || upper(substring(replace(gen_random_uuid()::text,'-','') from 1 for 10));

    INSERT INTO public.inspection_requests(
      request_code, owner_id, owner_email, owner_phone,
      property_address, property_city, property_state, property_type, sub_type,
      bedrooms, bathrooms, expected_rent, security_deposit_amount, amenities,
      description, photo_urls,
      gps_latitude, gps_longitude, location_accuracy_m,
      submission_batch_id, submission_batch_position,
      status, created_at, updated_at
    ) VALUES (
      v_request_code, v_profile.user_id, v_profile.email,
      COALESCE(NULLIF(BTRIM(v_item->>'owner_phone'),''),v_profile.phone),
      v_address, v_city, v_state, v_type, v_sub_type,
      NULLIF(v_item->>'bedrooms','')::integer,
      NULLIF(v_item->>'bathrooms','')::integer,
      NULLIF(v_item->>'expected_rent','')::numeric,
      v_deposit, v_amenities,
      NULLIF(BTRIM(v_item->>'description'),''),
      v_photo_urls,
      v_lat, v_lng,
      CASE WHEN v_accuracy IS NULL OR v_accuracy < 0 THEN NULL ELSE v_accuracy END,
      v_batch_id, v_position,
      'pending', now(), now()
    ) RETURNING id INTO v_request_id;

    v_results := v_results || jsonb_build_array(jsonb_build_object(
      'id', v_request_id,
      'request_code', v_request_code,
      'position', v_position
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'batch_id', v_batch_id,
    'count', jsonb_array_length(v_results),
    'requests', v_results
  );
END;
$$;


--
-- Name: create_my_property_inspection_batch_v2(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_property_inspection_batch_v2(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_result jsonb; v_request jsonb; v_relation text;
begin
  select * into v_actor from public.profiles where auth_id=auth.uid()::text and public.user_has_active_workspace(user_id,'property_partner')
    and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor is null then raise exception 'Active Property Partner account required'; end if;
  if not public.account_identity_is_current(v_actor.user_id) then raise exception 'Complete the private identity check before submitting properties'; end if;
  v_result:=public.create_my_property_inspection_batch(p_items);
  for v_request in select value from jsonb_array_elements(v_result->'requests') loop
    v_relation:=nullif(btrim(p_items->((v_request->>'position')::integer-1)->>'authority_relationship'),'');
    if v_relation not in ('owner','property_manager','agent','authorized_representative') then raise exception 'Choose your relationship to property %',v_request->>'position'; end if;
    update public.inspection_requests set authority_relationship=v_relation,
      access_challenge_code=upper(substring(replace(gen_random_uuid()::text,'-','') from 1 for 6)),
      access_challenge_expires_at=now()+interval '7 days',access_evidence_status='required',updated_at=now()
    where id=(v_request->>'id')::uuid and owner_id=v_actor.user_id;
  end loop;
  return v_result;
end $$;


--
-- Name: create_my_property_inspection_batch_v3(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_property_inspection_batch_v3(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_result jsonb; v_created jsonb; v_item jsonb;
  v_position integer; v_challenge_id uuid; v_challenge public.property_access_challenges; v_request_id uuid;
begin
  select * into v_actor from public.profiles where auth_id=auth.uid()::text and public.user_has_active_workspace(user_id,'property_partner')
    and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor is null then raise exception 'Active Property Partner account required'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)<1 then raise exception 'Add at least one property'; end if;
  for v_item,v_position in select value,ordinality::integer from jsonb_array_elements(p_items) with ordinality loop
    begin v_challenge_id:=(v_item->>'access_challenge_id')::uuid;
    exception when others then raise exception 'Property %: valid live access recording required',v_position; end;
    select * into v_challenge from public.property_access_challenges where id=v_challenge_id and partner_id=v_actor.user_id for update;
    if v_challenge.id is null or v_challenge.status<>'submitted' or v_challenge.video_path is null or v_challenge.submitted_at is null then raise exception 'Property %: complete the live access recording before submitting',v_position; end if;
    if v_challenge.submitted_at>v_challenge.expires_at then raise exception 'Property %: the access recording was submitted after its code expired. Record again',v_position; end if;
  end loop;
  v_result:=public.create_my_property_inspection_batch_v2(p_items);
  for v_created in select value from jsonb_array_elements(v_result->'requests') loop
    v_position:=(v_created->>'position')::integer; v_request_id:=(v_created->>'id')::uuid;
    v_challenge_id:=(p_items->(v_position-1)->>'access_challenge_id')::uuid;
    select * into v_challenge from public.property_access_challenges where id=v_challenge_id for update;
    update public.inspection_requests set access_challenge_code=v_challenge.code,access_challenge_expires_at=v_challenge.expires_at,
      access_evidence_video_path=v_challenge.video_path,access_evidence_status='submitted',access_evidence_submitted_at=v_challenge.submitted_at,updated_at=now()
    where id=v_request_id and owner_id=v_actor.user_id;
    update public.property_access_challenges set status='consumed',consumed_at=now(),request_id=v_request_id where id=v_challenge_id and partner_id=v_actor.user_id and status='submitted';
    if not found then raise exception 'Property %: access recording was already used',v_position; end if;
  end loop;
  return v_result;
end $$;


--
-- Name: create_my_property_inspection_batch_v4(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_property_inspection_batch_v4(p_batch_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_auth_id text:=(select auth.uid())::text;
  v_actor text:=public.current_profile_user_id();
  v_result jsonb;
  v_created jsonb;
  v_item jsonb;
  v_position integer;
  v_request_id uuid;
  v_max_guests integer;
  v_display_name text;
begin
  if v_actor is null
     or not public.current_actor_has_workspace('property_partner',null) then
    raise exception 'Property Partner workspace required';
  end if;
  if not public.account_identity_is_current(v_actor) then
    raise exception 'Complete the private identity check before submitting properties';
  end if;
  if not exists(
    select 1 from public.property_submission_batches batch
    where batch.id=p_batch_id
      and batch.partner_user_id=v_auth_id
      and batch.status in ('draft','submitting')
    for update
  ) then raise exception 'Property submission batch not found'; end if;
  update public.property_submission_batches
  set status='submitting',updated_at=now() where id=p_batch_id;
  v_result:=public.create_my_property_inspection_batch_v3(p_items);
  for v_created in
    select value from jsonb_array_elements(v_result->'requests')
  loop
    v_position:=(v_created->>'position')::integer;
    v_request_id:=(v_created->>'id')::uuid;
    v_item:=p_items->(v_position-1);
    v_max_guests:=nullif(v_item->>'max_guests','')::integer;
    v_display_name:=nullif(
      btrim(coalesce(v_item->>'property_display_name','')),''
    );
    if v_item->>'property_type'='apartment'
       and v_item->>'sub_type'='short_let'
       and coalesce(v_max_guests,0)<1 then
      raise exception 'Property %: Short Let guest capacity must be at least 1',
        v_position;
    end if;
    if v_item->>'property_type'='apartment'
       and v_item->>'sub_type'='short_let'
       and v_display_name is null then
      raise exception 'Property %: Short Let property or host name is required',
        v_position;
    end if;
    update public.inspection_requests set
      submission_schema_version=2,
      hotel_program=case when v_item->>'property_type'='hotel'
        then v_item->'hotel_program' else null end,
      max_guests=case
        when v_item->>'property_type'='apartment'
          and v_item->>'sub_type'='short_let'
        then v_max_guests else null end,
      property_display_name=case
        when v_item->>'property_type'='apartment'
          and v_item->>'sub_type'='short_let'
        then v_display_name else null end,
      submission_batch_id=p_batch_id,
      updated_at=now()
    where id=v_request_id and owner_id=v_actor;
    update public.property_submission_items
    set inspection_request_id=v_request_id,status='submitted',updated_at=now()
    where batch_id=p_batch_id and position=v_position-1;
  end loop;
  update public.property_submission_batches
  set status='submitted',submitted_at=now(),updated_at=now()
  where id=p_batch_id and partner_user_id=v_auth_id;
  return v_result||jsonb_build_object('batch_id',p_batch_id);
exception when others then
  update public.property_submission_batches
  set status='draft',updated_at=now()
  where id=p_batch_id and partner_user_id=v_auth_id;
  raise;
end
$$;


--
-- Name: create_my_property_inspection_request(text, text, text, text, integer, integer, numeric, text, text, text[], numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_property_inspection_request(p_property_address text, p_property_city text, p_property_state text, p_property_type text, p_bedrooms integer DEFAULT NULL::integer, p_bathrooms integer DEFAULT NULL::integer, p_expected_rent numeric DEFAULT NULL::numeric, p_description text DEFAULT NULL::text, p_owner_phone text DEFAULT NULL::text, p_photo_urls text[] DEFAULT ARRAY[]::text[], p_gps_latitude numeric DEFAULT NULL::numeric, p_gps_longitude numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_profile RECORD; v_request_id UUID; v_request_code TEXT;
BEGIN
  SELECT user_id,email,phone,role,deleted,suspended,banned INTO v_profile
  FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_profile IS NULL OR not public.user_has_active_workspace(v_profile.user_id,'property_partner') THEN RAISE EXCEPTION 'Property Partner account required'; END IF;
  IF COALESCE(v_profile.deleted,false) OR COALESCE(v_profile.suspended,false) OR COALESCE(v_profile.banned,false) THEN RAISE EXCEPTION 'Account is not active'; END IF;
  IF NULLIF(BTRIM(p_property_address),'') IS NULL OR NULLIF(BTRIM(p_property_city),'') IS NULL OR NULLIF(BTRIM(p_property_state),'') IS NULL THEN RAISE EXCEPTION 'Property address, state and LGA are required'; END IF;
  IF p_gps_latitude IS NOT NULL AND (p_gps_latitude < -90 OR p_gps_latitude > 90) THEN RAISE EXCEPTION 'Invalid latitude'; END IF;
  IF p_gps_longitude IS NOT NULL AND (p_gps_longitude < -180 OR p_gps_longitude > 180) THEN RAISE EXCEPTION 'Invalid longitude'; END IF;
  v_request_code := 'WHIR-'||UPPER(SUBSTRING(REPLACE(gen_random_uuid()::text,'-','') FROM 1 FOR 10));
  INSERT INTO public.inspection_requests(request_code,owner_id,owner_email,owner_phone,property_address,property_city,property_state,property_type,bedrooms,bathrooms,expected_rent,description,photo_urls,gps_latitude,gps_longitude,status,created_at,updated_at)
  VALUES(v_request_code,v_profile.user_id,v_profile.email,COALESCE(NULLIF(BTRIM(p_owner_phone),''),v_profile.phone),BTRIM(p_property_address),BTRIM(p_property_city),BTRIM(p_property_state),BTRIM(p_property_type),p_bedrooms,p_bathrooms,p_expected_rent,NULLIF(BTRIM(p_description),''),COALESCE(p_photo_urls,ARRAY[]::text[]),p_gps_latitude,p_gps_longitude,'pending',NOW(),NOW())
  RETURNING id INTO v_request_id;
  RETURN v_request_id;
END $$;


--
-- Name: create_my_property_inspection_request_v2(text, text, text, text, integer, integer, numeric, text, text, text[], numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_property_inspection_request_v2(p_property_address text, p_property_city text, p_property_state text, p_property_type text, p_bedrooms integer DEFAULT NULL::integer, p_bathrooms integer DEFAULT NULL::integer, p_expected_rent numeric DEFAULT NULL::numeric, p_description text DEFAULT NULL::text, p_owner_phone text DEFAULT NULL::text, p_photo_urls text[] DEFAULT ARRAY[]::text[], p_gps_latitude numeric DEFAULT NULL::numeric, p_gps_longitude numeric DEFAULT NULL::numeric, p_location_accuracy_m numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_profile record; v_request_id uuid; v_request_code text;
begin
 select user_id,email,phone,role,deleted,suspended,banned into v_profile from public.profiles where auth_id=auth.uid()::text limit 1;
 if v_profile is null then raise exception 'Profile not found'; end if;
 if not public.user_has_active_workspace(v_profile.user_id,'property_partner') then raise exception 'Property Partner account required'; end if;
 if coalesce(v_profile.deleted,false) or coalesce(v_profile.suspended,false) or coalesce(v_profile.banned,false) then raise exception 'Account is not active'; end if;
 if nullif(btrim(p_property_address),'') is null then raise exception 'Property address is required'; end if;
 if nullif(btrim(p_property_city),'') is null then raise exception 'Property city/LGA is required'; end if;
 if nullif(btrim(p_property_state),'') is null then raise exception 'Property state is required'; end if;
 if nullif(btrim(p_property_type),'') is null then raise exception 'Property type is required'; end if;
 if (p_gps_latitude is null) <> (p_gps_longitude is null) then raise exception 'Both latitude and longitude are required together'; end if;
 if p_gps_latitude is not null and (p_gps_latitude not between -90 and 90 or p_gps_longitude not between -180 and 180) then raise exception 'Invalid property coordinates'; end if;
 v_request_code:='WHIR-'||upper(substring(replace(gen_random_uuid()::text,'-','') from 1 for 10));
 insert into public.inspection_requests(request_code,owner_id,owner_email,owner_phone,property_address,property_city,property_state,property_type,bedrooms,bathrooms,expected_rent,description,photo_urls,gps_latitude,gps_longitude,location_accuracy_m,status,created_at,updated_at)
 values(v_request_code,v_profile.user_id,v_profile.email,coalesce(nullif(btrim(p_owner_phone),''),v_profile.phone),btrim(p_property_address),btrim(p_property_city),btrim(p_property_state),btrim(p_property_type),p_bedrooms,p_bathrooms,p_expected_rent,nullif(btrim(p_description),''),coalesce(p_photo_urls,array[]::text[]),p_gps_latitude,p_gps_longitude,case when p_location_accuracy_m is null or p_location_accuracy_m<0 then null else p_location_accuracy_m end,'pending',now(),now()) returning id into v_request_id;
 return v_request_id;
end $$;


--
-- Name: create_my_shared_housing_group(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_shared_housing_group(p_listing_id uuid, p_conversation_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select public.create_my_shared_housing_group_v2(
    p_listing_id,array[p_conversation_id]::uuid[],null,null,null
  )
$$;


--
-- Name: create_my_shared_housing_group_v2(uuid, uuid[], date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_shared_housing_group_v2(p_listing_id uuid, p_conversation_ids uuid[], p_check_in date DEFAULT NULL::date, p_check_out date DEFAULT NULL::date, p_guest_count integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_listing public.listings;
  v_conversation public.conversations;
  v_conversation_id uuid;
  v_peer text;
  v_peers text[]:='{}'::text[];
  v_people text[];
  v_capacity integer;
  v_member_count integer;
  v_total numeric(12,2);
  v_eligible numeric(12,2):=0;
  v_refundable numeric(12,2):=0;
  v_fee numeric(12,2);
  v_nights integer;
  v_min_nights integer;
  v_max_nights integer;
  v_reservation public.reservations;
  v_group_id uuid:=gen_random_uuid();
  v_member_id uuid;
  v_share numeric(12,2);
  v_eligible_share numeric(12,2);
  v_refundable_share numeric(12,2);
  v_assigned numeric(12,2):=0;
  v_eligible_assigned numeric(12,2):=0;
  v_refundable_assigned numeric(12,2):=0;
  v_index integer;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null or not public.current_actor_has_personal_workspace() then
    raise exception 'An active Personal account is required';
  end if;
  if coalesce(cardinality(p_conversation_ids),0)<1 then
    raise exception 'Choose at least one connected roommate';
  end if;

  select * into v_listing from public.listings
  where id=p_listing_id and deleted_at is null for update;
  if v_listing.id is null or v_listing.property_type<>'apartment'
    or v_listing.status<>'available' or v_listing.availability_status<>'available' then
    raise exception 'This property is unavailable';
  end if;
  if v_listing.sub_type not in('long_stay','short_let') then
    raise exception 'Shared payment is available only for Long Let or Short Let';
  end if;
  v_capacity:=case when v_listing.sub_type='short_let'
    then coalesce(v_listing.max_guests,0) else coalesce(v_listing.max_occupants,0) end;
  if v_capacity<2 then raise exception 'This property cannot accept two paying guests or occupants'; end if;

  foreach v_conversation_id in array p_conversation_ids loop
    select * into v_conversation from public.conversations
    where id=v_conversation_id and conversation_type='roommate'
      and coalesce(status,'active') in('active','accepted')
      and v_actor.user_id in(participant_a,participant_b);
    if v_conversation.id is null then
      raise exception 'Every person must have an accepted roommate conversation';
    end if;
    v_peer:=case when v_conversation.participant_a=v_actor.user_id
      then v_conversation.participant_b else v_conversation.participant_a end;
    if v_peer=any(v_peers) then raise exception 'Choose each roommate once'; end if;
    if exists(select 1 from public.roommate_user_blocks b
      where (b.blocker_user_id=v_actor.user_id and b.blocked_user_id=v_peer)
         or (b.blocker_user_id=v_peer and b.blocked_user_id=v_actor.user_id)) then
      raise exception 'A blocked roommate cannot join a shared payment';
    end if;
    v_peers:=array_append(v_peers,v_peer);
  end loop;
  v_people:=array_prepend(v_actor.user_id,v_peers);
  v_member_count:=cardinality(v_people);
  if v_member_count>v_capacity then
    raise exception 'This property accepts only % guests or occupants',v_capacity;
  end if;
  if v_member_count>12 then raise exception 'A shared payment supports up to 12 people'; end if;
  if exists(
    select 1 from public.shared_housing_groups g
    join public.shared_housing_members m on m.group_id=g.id
    where g.listing_id=v_listing.id and m.user_id=v_actor.user_id
      and g.status not in('cancelled','expired','refunded')
  ) then raise exception 'You already have an active shared payment for this property'; end if;

  if v_listing.sub_type='short_let' then
    if p_check_in is null or p_check_out is null or p_check_in<current_date
      or p_check_out<=p_check_in then raise exception 'Choose valid Short Let dates'; end if;
    select coalesce(nullif(value,'')::integer,1) into v_min_nights
    from public.platform_settings where key='short_stay_min_nights'
      and coalesce(is_active,true) limit 1;
    select coalesce(nullif(value,'')::integer,90) into v_max_nights
    from public.platform_settings where key='short_stay_max_nights'
      and coalesce(is_active,true) limit 1;
    v_min_nights:=greatest(coalesce(v_min_nights,1),1);
    v_max_nights:=greatest(coalesce(v_max_nights,90),v_min_nights);
    v_nights:=p_check_out-p_check_in;
    if v_nights<v_min_nights or v_nights>v_max_nights then
      raise exception 'Short Let must be between % and % nights',v_min_nights,v_max_nights;
    end if;
    if coalesce(p_guest_count,v_member_count)<v_member_count
      or coalesce(p_guest_count,v_member_count)>v_capacity then
      raise exception 'Guest count must include every paying roommate and fit the property';
    end if;
    select * into v_reservation from public.create_short_stay_reservation(
      v_listing.id::text,p_check_in,p_check_out,coalesce(p_guest_count,v_member_count)
    );
    update public.reservations set
      payment_expires_at=now()+interval '72 hours',
      shared_payment_group_id=v_group_id,updated_at=now()
    where id=v_reservation.id returning * into v_reservation;
    v_eligible:=round(v_reservation.stay_rent_total,2);
    v_refundable:=round(coalesce(v_reservation.security_deposit_snapshot,0),2);
    v_total:=v_eligible+v_refundable;
  else
    select coalesce(nullif(value,'')::numeric,10000) into v_fee
    from public.platform_settings where key='reservation_fee'
      and coalesce(is_active,true) limit 1;
    v_total:=round(coalesce(v_fee,10000),2);
    if v_total<=0 then raise exception 'Creator reservation fee is not configured'; end if;
    v_refundable:=v_total;
  end if;

  insert into public.shared_housing_groups(
    id,listing_id,created_by,status,member_limit,total_amount,conversation_id,
    payment_phase,reservation_fee_total,contract_total,expires_at,
    reservation_id,product_type,canonical_group_id,stay_check_in,stay_check_out,
    guest_count,checkout_attempt,created_at,updated_at
  ) values(
    v_group_id,v_listing.id,v_actor.user_id,'inviting',v_member_count,v_total,
    case when cardinality(p_conversation_ids)=1 then p_conversation_ids[1] else null end,
    case when v_listing.sub_type='short_let' then 'short_stay' else 'reservation_fee' end,
    case when v_listing.sub_type='long_stay' then v_total else 0 end,
    case when v_listing.sub_type='long_stay' then
      round(v_listing.price+coalesce(v_listing.security_deposit_amount,0),2)
      else v_total end,
    now()+interval '72 hours',v_reservation.id,
    case when v_listing.sub_type='short_let' then 'short_let' else 'long_let' end,
    v_group_id,p_check_in,p_check_out,coalesce(p_guest_count,v_member_count),1,now(),now()
  );
  insert into public.shared_payment_groups(
    shared_payment_group_id,product_type,listing_id,reservation_id,created_by,
    total_amount,capacity,status,checkout_expires_at,legacy_group_id,
    conversation_id,payment_phase,stay_check_in,stay_check_out,guest_count,
    checkout_attempt,created_at,updated_at
  ) values(
    v_group_id,case when v_listing.sub_type='short_let' then 'short_let' else 'long_let' end,
    v_listing.id::text,v_reservation.id,v_actor.user_id,v_total,v_capacity,
    'inviting',now()+interval '72 hours',v_group_id,
    case when cardinality(p_conversation_ids)=1 then p_conversation_ids[1] else null end,
    case when v_listing.sub_type='short_let' then 'short_stay' else 'reservation_fee' end,
    p_check_in,p_check_out,coalesce(p_guest_count,v_member_count),1,now(),now()
  );

  for v_index in 1..v_member_count loop
    v_member_id:=gen_random_uuid();
    v_share:=case when v_index=v_member_count then v_total-v_assigned
      else round(v_total/v_member_count,2) end;
    v_eligible_share:=case when v_index=v_member_count then v_eligible-v_eligible_assigned
      else round(v_eligible/v_member_count,2) end;
    v_refundable_share:=case when v_index=v_member_count then v_refundable-v_refundable_assigned
      else round(v_refundable/v_member_count,2) end;
    insert into public.shared_housing_members(
      id,group_id,user_id,invitation_status,share_amount,payment_status,
      canonical_member_id,eligible_partner_share,refundable_share,created_at,updated_at
    ) values(
      v_member_id,v_group_id,v_people[v_index],
      case when v_index=1 then 'accepted' else 'invited' end,
      v_share,'not_started',v_member_id,v_eligible_share,v_refundable_share,now(),now()
    );
    insert into public.shared_payment_members(
      shared_payment_member_id,shared_payment_group_id,user_id,share_amount,
      invitation_state,payment_state,legacy_member_id,eligible_partner_share,
      refundable_share,created_at,updated_at
    ) values(
      v_member_id,v_group_id,v_people[v_index],v_share,
      case when v_index=1 then 'accepted' else 'invited' end,
      'not_started',v_member_id,v_eligible_share,v_refundable_share,now(),now()
    );
    v_assigned:=v_assigned+v_share;
    v_eligible_assigned:=v_eligible_assigned+v_eligible_share;
    v_refundable_assigned:=v_refundable_assigned+v_refundable_share;
  end loop;
  return public.get_my_shared_housing_group(v_group_id);
end
$$;


--
-- Name: create_my_shared_housing_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_shared_housing_payment(p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_member public.shared_housing_members;
  v_group public.shared_housing_groups;
  v_reference text;
  v_subject_id text;
begin
  select * into v_group from public.shared_housing_groups where id=p_group_id for update;
  select * into v_member from public.shared_housing_members
  where group_id=p_group_id and user_id=v_actor for update;
  if v_group.id is null or v_member.id is null then raise exception 'Shared-payment access required'; end if;
  if v_group.status<>'payment_pending' or v_member.invitation_status<>'accepted'
    or exists(select 1 from public.shared_housing_members
      where group_id=p_group_id and invitation_status<>'accepted') then
    raise exception 'Every roommate must accept before payment';
  end if;
  if v_group.expires_at<=now() then raise exception 'This 30-minute shared checkout expired'; end if;
  if v_member.payment_status='paid' then return jsonb_build_object('already_paid',true); end if;
  v_reference:='WH-SH-'||upper(replace(gen_random_uuid()::text,'-',''));
  v_subject_id:=v_member.id::text||':'||v_group.payment_phase||':'||v_group.checkout_attempt;
  update public.shared_housing_members set
    payment_status='pending',payment_reference=v_reference,updated_at=now()
  where id=v_member.id;
  update public.shared_payment_members set
    payment_state='provider_pending',provider_reference=v_reference,updated_at=now()
  where shared_payment_member_id=v_member.canonical_member_id;
  insert into public.booking_payments(
    payment_reference,paystack_reference,user_id,payer_user_id,type,booking_type,
    listing_id,amount,amount_total,currency,status,purpose,metadata,created_at,updated_at
  ) values(
    v_reference,v_reference,v_actor,v_actor,'shared_housing','shared_housing',
    v_group.listing_id::text,v_member.share_amount,v_member.share_amount,'NGN',
    'pending','shared_housing_share',jsonb_build_object(
      'shared_group_id',p_group_id,
      'shared_member_id',v_subject_id,
      'legacy_shared_member_id',v_member.id,
      'canonical_shared_payment_group_id',v_group.canonical_group_id,
      'canonical_shared_payment_member_id',v_member.canonical_member_id,
      'canonical_product_type',v_group.product_type,
      'payment_phase',v_group.payment_phase,
      'checkout_attempt',v_group.checkout_attempt,
      'eligible_partner_amount',v_member.eligible_partner_share,
      'refundable_amount',v_member.refundable_share,
      'reservation_id',v_group.reservation_id
    ),now(),now()
  );
  return jsonb_build_object(
    'reference',v_reference,'amount',v_member.share_amount,
    'payment_phase',v_group.payment_phase,'expires_at',v_group.expires_at,
    'product_type',v_group.product_type
  );
end
$$;


--
-- Name: create_my_support_case(text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_support_case(p_subject text, p_category text DEFAULT 'general'::text, p_source_type text DEFAULT NULL::text, p_source_id text DEFAULT NULL::text, p_source_snapshot jsonb DEFAULT '{}'::jsonb, p_priority text DEFAULT 'normal'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_result_id uuid;
  v_subject text;
  v_category text:=lower(coalesce(nullif(btrim(p_category),''),'general'));
  v_priority text:='normal';
  v_basis text:='standard';
  v_pro boolean:=false;
begin
  select * into v_actor from public.profiles where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null then raise exception 'Active WeHouse account required'; end if;
  v_subject:=nullif(btrim(coalesce(p_subject,'')),'');
  if v_subject is null then raise exception 'Tell us what you need help with'; end if;
  if v_actor.role='worker' then v_pro:=public.worker_pro_is_active(v_actor.user_id); end if;
  if v_category~'(safety|security|fraud|harassment|emergency)' then
    v_priority:='urgent'; v_basis:='safety_risk';
  elsif v_category~'(payment|refund|dispute|chargeback|arrival|access)' then
    v_priority:='high'; v_basis:='protected_flow';
  elsif v_pro then
    v_priority:='high'; v_basis:='paid_plan_ordinary_support';
  end if;
  insert into public.partner_support_conversations(
    partner_id,requester_role,subject,status,category,context_type,context_id,
    context_snapshot,priority,channel_kind,case_number,created_at,updated_at
  ) values(
    v_actor.user_id,v_actor.role,v_subject,'open',v_category,
    'support_case',nullif(btrim(coalesce(p_source_id,'')),''),
    coalesce(p_source_snapshot,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
      'source_type',nullif(btrim(coalesce(p_source_type,'')),''),
      'source_id',nullif(btrim(coalesce(p_source_id,'')),''),
      'routing_basis',v_basis,
      'requested_priority_ignored',nullif(btrim(coalesce(p_priority,'')),'')
    )),v_priority,'support_case',
    'WHC-'||upper(substring(replace(gen_random_uuid()::text,'-','') from 1 for 10)),
    now(),now()
  ) returning id into v_result_id;
  return v_result_id;
end;
$$;


--
-- Name: hotel_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hotel_reviews (
    review_id integer NOT NULL,
    hotel_id integer NOT NULL,
    user_id text NOT NULL,
    rating integer NOT NULL,
    comment text,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT hotel_reviews_rating_check CHECK (((rating >= 1) AND (rating <= 5)))
);


--
-- Name: create_my_verified_hotel_review(integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_verified_hotel_review(p_hotel_id integer, p_rating integer, p_comment text DEFAULT NULL::text) RETURNS public.hotel_reviews
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user text:=public.current_profile_user_id();
  v_review public.hotel_reviews;
begin
  if v_user is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Active Personal account required';
  end if;
  if p_rating not between 1 and 5 then
    raise exception 'Rating must be between 1 and 5';
  end if;
  if not exists(
    select 1 from public.hotel_bookings
    where hotel_id=p_hotel_id and user_id=v_user and payment_status='paid'
      and status in ('checked_out','completed')
  ) then raise exception 'A completed paid stay is required before reviewing this Hotel'; end if;
  insert into public.hotel_reviews(hotel_id,user_id,rating,comment)
  values(p_hotel_id,v_user,p_rating,nullif(btrim(coalesce(p_comment,'')),''))
  on conflict(hotel_id,user_id) do update
  set rating=excluded.rating,comment=excluded.comment,created_at=now()
  returning * into v_review;
  update public.hotels hotel
  set rating=(
        select round(avg(review.rating)::numeric,1)
        from public.hotel_reviews review where review.hotel_id=p_hotel_id
      ),
      review_count=(
        select count(*) from public.hotel_reviews review
        where review.hotel_id=p_hotel_id
      ),
      updated_at=now()
  where hotel.hotel_id=p_hotel_id;
  return v_review;
end
$$;


--
-- Name: worker_showcase_posts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.worker_showcase_posts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    worker_id text NOT NULL,
    kind text NOT NULL,
    media_type text NOT NULL,
    storage_path text NOT NULL,
    caption text,
    booking_id uuid,
    verified_job boolean DEFAULT false NOT NULL,
    expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    job_confirmation_status text DEFAULT 'not_linked'::text NOT NULL,
    job_confirmed_by text,
    job_confirmed_at timestamp with time zone,
    hidden_at timestamp with time zone,
    CONSTRAINT worker_showcase_caption_length CHECK (((caption IS NULL) OR (length(caption) <= 300))),
    CONSTRAINT worker_showcase_job_confirmation_status_check CHECK ((job_confirmation_status = ANY (ARRAY['not_linked'::text, 'pending'::text, 'confirmed'::text, 'declined'::text]))),
    CONSTRAINT worker_showcase_posts_kind_check CHECK ((kind = 'work_post'::text)),
    CONSTRAINT worker_showcase_posts_media_type_check CHECK ((media_type = ANY (ARRAY['image'::text, 'video'::text]))),
    CONSTRAINT worker_showcase_story_expiry CHECK ((expires_at IS NULL))
);


--
-- Name: create_my_worker_showcase_post(text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_worker_showcase_post(p_kind text, p_media_type text, p_storage_path text, p_caption text DEFAULT NULL::text, p_booking_id uuid DEFAULT NULL::uuid) RETURNS public.worker_showcase_posts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'storage'
    AS $$
declare
  v_worker public.profiles;
  v_booking public.worker_bookings;
  v_post public.worker_showcase_posts;
begin
  select * into v_worker
  from public.profiles
  where auth_id=(select auth.uid())::text
    and worker_status='verified'
    and coalesce(worker_verified,false)
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_worker is null or not public.current_actor_has_workspace('worker',null) then
    raise exception 'Only an approved live Worker can publish Work Posts';
  end if;
  if not public.worker_identity_is_current(v_worker.user_id) then
    raise exception 'Repeat your WeHouse identity check before publishing new work';
  end if;
  if p_kind<>'work_post' then raise exception 'Only Work Posts are supported'; end if;
  if p_media_type not in ('image','video') then raise exception 'Invalid media type'; end if;
  if nullif(btrim(coalesce(p_storage_path,'')),'') is null
     or split_part(p_storage_path,'/',1)<>v_worker.user_id then
    raise exception 'Invalid Work Post storage path';
  end if;
  if length(coalesce(p_caption,''))>300 then raise exception 'Caption is too long'; end if;
  if not exists(
    select 1 from storage.objects object
    where object.bucket_id='worker-showcase' and object.name=p_storage_path
  ) then raise exception 'Work Post media upload was not found'; end if;
  if p_booking_id is not null then
    select * into v_booking
    from public.worker_bookings booking
    where booking.id=p_booking_id
      and booking.worker_id=v_worker.user_id
      and booking.status='approved_released';
    if v_booking is null then
      raise exception 'Only your completed WeHouse job can be linked';
    end if;
  end if;
  insert into public.worker_showcase_posts(
    worker_id,kind,media_type,storage_path,caption,booking_id,verified_job,
    expires_at,job_confirmation_status
  ) values(
    v_worker.user_id,'work_post',p_media_type,p_storage_path,
    nullif(btrim(coalesce(p_caption,'')),''),p_booking_id,false,null,
    case when p_booking_id is null then 'not_linked' else 'pending' end
  ) returning * into v_post;
  if p_booking_id is not null then
    insert into public.notifications(
      recipient_id,type,title,message,related_id,source_type,source_id,
      destination_route,destination_params,event_key
    ) values(
      v_booking.user_id,'work_post_confirmation_requested',
      'Confirm this work post',
      'The Worker linked a photo or video to your completed job. Review the media and confirm only if it shows the work completed for you.',
      v_post.id::text,'worker_work_post',v_post.id::text,'activity',
      jsonb_build_object(
        'work_post_id',v_post.id,'booking_id',v_booking.id
      ),
      'work-post-confirmation:'||v_post.id::text
    ) on conflict(recipient_id,event_key)
      where event_key is not null do nothing;
  end if;
  return v_post;
end
$$;


--
-- Name: create_rent_plan(text, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_rent_plan(p_user_id text, p_listing_id uuid, p_target_amount numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare v_plan_id uuid; v_start_months integer; v_cancel_percent numeric; v_actor text;
begin
  select user_id into v_actor from public.profiles where auth_id=auth.uid()::text and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor is null or v_actor<>p_user_id then raise exception 'Authenticated user mismatch'; end if;
  select coalesce(nullif(value,'')::integer,4) into v_start_months from public.platform_settings where key='rent_plan_start_after_months';
  select coalesce(nullif(value,'')::numeric,10) into v_cancel_percent from public.platform_settings where key='rent_plan_cancellation_fee_percent';
  insert into public.rent_plans(user_id,listing_id,target_amount,start_after_months,cancellation_fee_percent,accepted_terms,status,tenancy_start_date)
  values(p_user_id,p_listing_id,p_target_amount,v_start_months,v_cancel_percent,jsonb_build_object('start_after_months',v_start_months,'cancellation_fee_percent',v_cancel_percent,'snapshot_at',now())::text,'active',current_date)
  returning id into v_plan_id; return v_plan_id;
end $$;


--
-- Name: create_rent_plan_contribution_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_rent_plan_contribution_payment(p_contribution_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id text; v_contribution public.rent_plan_contributions;
  v_plan public.rent_plans; v_res public.reservations; v_listing public.listings;
  v_policy public.creator_policy_versions; v_reference text;
  v_pending public.booking_payments;
begin
  select user_id into v_user_id from public.profiles
  where auth_id=(select auth.uid())::text and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select * into v_contribution from public.rent_plan_contributions
    where id=p_contribution_id for update;
  if v_contribution.id is null then raise exception 'Rent contribution not found'; end if;
  select * into v_plan from public.rent_plans
    where id=v_contribution.rent_plan_id and user_id=v_user_id for update;
  if v_plan.id is null or v_plan.status<>'active' then raise exception 'Active rent plan not found'; end if;
  select * into v_res from public.reservations
    where id=v_plan.reservation_id and user_id=v_user_id for share;
  if v_res.id is null or v_res.status<>'occupied' then raise exception 'Active tenancy required'; end if;
  select * into v_listing from public.listings where id=v_plan.listing_id for share;
  if v_listing.id is null or not coalesce(v_listing.future_installments_allowed,false) then
    raise exception 'The Property Partner has not enabled installments';
  end if;
  select * into v_policy from public.creator_policy_versions
  where policy_key='future_long_let_installments' and scope_type='global'
    and scope_key='*' and status='active' and effective_from<=now()
    and (effective_until is null or effective_until>now())
  order by effective_from desc limit 1;
  if v_policy.policy_version_id is null or not coalesce((v_policy.value->>'enabled')::boolean,false)
    or coalesce((v_policy.value->>'payment_protection_hold')::boolean,true) then
    raise exception 'Future-year installments are unavailable';
  end if;
  if v_contribution.status in ('paid','completed') then
    return jsonb_build_object('success',true,'already_paid',true,'contribution_id',v_contribution.id);
  end if;
  if v_contribution.status not in ('scheduled','payment_pending','pending')
    or coalesce(v_contribution.amount,0)<=0 then raise exception 'This contribution cannot be paid'; end if;
  select * into v_pending from public.booking_payments
  where user_id=v_user_id and purpose='rent_plan_contribution' and status='pending'
    and metadata->>'contribution_id'=v_contribution.id::text
    and round(coalesce(amount_total,amount),2)=round(v_contribution.amount,2)
  order by created_at desc limit 1;
  if v_pending.id is not null then
    update public.rent_plan_contributions set status='payment_pending',
      payment_reference=v_pending.payment_reference,paystack_reference=v_pending.paystack_reference,
      updated_at=now() where id=v_contribution.id;
    return jsonb_build_object('success',true,'reference',v_pending.paystack_reference,
      'amount',coalesce(v_pending.amount_total,v_pending.amount),'existing',true);
  end if;
  v_reference:='WHNEXT-'||upper(replace(gen_random_uuid()::text,'-',''));
  insert into public.booking_payments(
    payment_reference,user_id,payer_user_id,type,booking_type,listing_id,
    amount,amount_total,currency,status,purpose,payment_method,paystack_reference,
    metadata,created_at,updated_at
  ) values(
    v_reference,v_user_id,v_user_id,'apartment','apartment',v_plan.listing_id::text,
    v_contribution.amount,v_contribution.amount,'NGN','pending',
    'rent_plan_contribution','paystack',v_reference,
    jsonb_build_object('reservation_id',v_res.id,'listing_id',v_plan.listing_id::text,
      'rent_plan_id',v_plan.id,'contribution_id',v_contribution.id,
      'target_year',v_contribution.target_year,'installment_number',v_contribution.installment_number,
      'due_date',v_contribution.due_date,'payment_component','rent_plan_contribution',
      'security_deposit_amount',0,'eligible_partner_amount',v_contribution.amount,
      'policy_version_id',v_policy.policy_version_id,'payment_protection_hold',false,
      'partner_opt_in',true),now(),now()
  );
  update public.rent_plan_contributions set status='payment_pending',
    payment_reference=v_reference,paystack_reference=v_reference,updated_at=now()
  where id=v_contribution.id;
  return jsonb_build_object('success',true,'reference',v_reference,
    'amount',v_contribution.amount,'existing',false);
end
$$;


--
-- Name: create_short_stay_payment(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_short_stay_payment(p_reservation_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id text;
  v_res public.reservations;
  v_listing public.listings;
  v_pending public.booking_payments;
  v_reference text;
  v_stay numeric(12,2);
  v_caution numeric(12,2);
  v_total numeric(12,2);
  v_checkout_minutes integer;
begin
  select user_id into v_user_id from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_user_id is null or not public.current_actor_has_personal_workspace() then
    raise exception 'An active Personal account is required';
  end if;
  select * into v_res from public.reservations
  where id=p_reservation_id and user_id=v_user_id for update;
  if v_res.id is null then raise exception 'Short Let checkout not found'; end if;
  if v_res.stay_type<>'short_let' then raise exception 'This is not a Short Let'; end if;
  if v_res.rent_payment_status='paid' then
    return jsonb_build_object('success',true,'already_paid',true,'status','paid');
  end if;
  if v_res.status not in ('payment_pending','reserved','ready_for_move_in') then
    raise exception 'This Short Let checkout cannot be paid';
  end if;
  if v_res.stay_check_out<=current_date then raise exception 'This Short Let has ended'; end if;

  select * into v_listing from public.listings
  where id::text=v_res.listing_id and deleted_at is null and sub_type='short_let'
  for share;
  if v_listing.id is null then raise exception 'Short Let not found'; end if;
  if coalesce(v_res.guest_count,1)>coalesce(v_listing.max_guests,0) then
    raise exception 'Guest count exceeds this Short Let capacity';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('short-let:'||v_listing.id::text,0));
  if exists(
    select 1 from public.reservations r
    where r.listing_id=v_res.listing_id and r.id<>v_res.id
      and r.stay_type='short_let'
      and r.status=any(array['reserved','ready_for_move_in','occupied']::text[])
      and daterange(r.stay_check_in,r.stay_check_out,'[)')
        && daterange(v_res.stay_check_in,v_res.stay_check_out,'[)')
  ) then raise exception 'Those Short Let dates are no longer available'; end if;

  v_stay:=round(coalesce(v_res.stay_rent_total,
    v_res.nightly_rate_snapshot*v_res.stay_nights),2);
  v_caution:=round(coalesce(v_res.security_deposit_snapshot,0),2);
  v_total:=v_stay+v_caution;
  if v_stay<=0 or v_caution<0 then raise exception 'Short Let checkout amount is invalid'; end if;

  select * into v_pending from public.booking_payments
  where user_id=v_user_id and purpose='apartment_rent' and status='pending'
    and metadata->>'reservation_id'=v_res.id
    and metadata->>'payment_component'='short_stay_rent'
    and round(coalesce(amount_total,amount),2)=v_total
  order by created_at desc limit 1;
  if v_pending.id is not null then
    update public.reservations set
      payment_reference=v_pending.paystack_reference,
      rent_payment_status='payment_pending',
      rent_payment_reference=v_pending.paystack_reference,updated_at=now()
    where id=v_res.id;
    return jsonb_build_object('success',true,'reference',v_pending.paystack_reference,
      'amount',v_total,'stay_price',v_stay,'caution_fee',v_caution,'existing',true);
  end if;

  v_reference:='WHSTAY-'||upper(replace(gen_random_uuid()::text,'-',''));
  insert into public.booking_payments(
    payment_reference,user_id,payer_user_id,type,booking_type,listing_id,
    amount,amount_total,currency,status,purpose,payment_method,paystack_reference,
    metadata,created_at,updated_at
  ) values(
    v_reference,v_user_id,v_user_id,'apartment','apartment',v_listing.id::text,
    v_total,v_total,'NGN','pending','apartment_rent','paystack',v_reference,
    jsonb_build_object('reservation_id',v_res.id,'listing_id',v_listing.id::text,
      'payment_component','short_stay_rent','check_in',v_res.stay_check_in,
      'check_out',v_res.stay_check_out,'nights',v_res.stay_nights,
      'guest_count',v_res.guest_count,'nightly_rate',v_res.nightly_rate_snapshot,
      'stay_rent_total',v_stay,'security_deposit_amount',v_caution,
      'eligible_partner_amount',v_stay,'separate_reservation_fee',false),
    now(),now()
  );
  select nullif(value,'')::integer into v_checkout_minutes
  from public.platform_settings where key='apartment_payment_hold_minutes'
    and coalesce(is_active,true) limit 1;
  if v_checkout_minutes is null or v_checkout_minutes<5 or v_checkout_minutes>120 then
    v_checkout_minutes:=30;
  end if;
  update public.reservations set
    amount=v_total,payment_reference=v_reference,manual_payment_status='unpaid',
    stay_rent_total=v_stay,security_deposit_snapshot=v_caution,
    security_deposit_status=case when v_caution=0 then 'not_required' else 'pending' end,
    rent_payment_status='payment_pending',rent_payment_reference=v_reference,
    payment_expires_at=now()+make_interval(mins=>v_checkout_minutes),updated_at=now()
  where id=v_res.id;
  return jsonb_build_object('success',true,'reference',v_reference,'amount',v_total,
    'stay_price',v_stay,'caution_fee',v_caution,'existing',false);
end
$$;


--
-- Name: create_short_stay_reservation(text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_short_stay_reservation(p_listing_id text, p_check_in date, p_check_out date) RETURNS public.reservations
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select public.create_short_stay_reservation(p_listing_id,p_check_in,p_check_out,1)
$$;


--
-- Name: create_short_stay_reservation(text, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_short_stay_reservation(p_listing_id text, p_check_in date, p_check_out date, p_guest_count integer) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_profile public.profiles;
  v_listing public.listings;
  v_created public.reservations;
  v_existing public.reservations;
  v_checkout_minutes integer;
  v_min_nights integer;
  v_max_nights integer;
  v_nights integer;
  v_rate numeric(12,2);
  v_stay numeric(12,2);
  v_caution numeric(12,2);
begin
  select * into v_profile from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_profile.user_id is null or not public.current_actor_has_personal_workspace() then
    raise exception 'An active Personal account is required';
  end if;

  select * into v_listing from public.listings
  where (id::text=p_listing_id or listing_id=p_listing_id)
    and deleted_at is null and sub_type='short_let'
  limit 1 for share;
  if v_listing.id is null then raise exception 'Short Let not found'; end if;
  if v_listing.status<>'available' or v_listing.availability_status<>'available' then
    raise exception 'This Short Let is not published';
  end if;
  if coalesce(v_listing.max_guests,0)<1 then
    raise exception 'Property Partner has not chosen the guest capacity';
  end if;
  if coalesce(p_guest_count,0)<1 or p_guest_count>v_listing.max_guests then
    raise exception 'Choose between 1 and % guests',v_listing.max_guests;
  end if;
  if p_check_in is null or p_check_out is null or p_check_in<current_date
    or p_check_out<=p_check_in then
    raise exception 'Choose valid future check-in and check-out dates';
  end if;

  select coalesce(nullif(value,'')::integer,1) into v_min_nights
  from public.platform_settings where key='short_stay_min_nights'
    and coalesce(is_active,true) limit 1;
  select coalesce(nullif(value,'')::integer,90) into v_max_nights
  from public.platform_settings where key='short_stay_max_nights'
    and coalesce(is_active,true) limit 1;
  v_min_nights:=greatest(coalesce(v_min_nights,1),1);
  v_max_nights:=greatest(coalesce(v_max_nights,90),v_min_nights);
  v_nights:=p_check_out-p_check_in;
  if v_nights<v_min_nights or v_nights>v_max_nights then
    raise exception 'Short Let must be between % and % nights',v_min_nights,v_max_nights;
  end if;

  -- Serialize availability checks only for the selected listing. Opening a
  -- checkout is provisional; an already paid/operational stay blocks it.
  perform pg_advisory_xact_lock(hashtextextended('short-let:'||v_listing.id::text,0));
  if exists(
    select 1 from public.reservations r
    where r.listing_id=v_listing.id::text
      and r.stay_type='short_let'
      and r.status=any(array['reserved','ready_for_move_in','occupied']::text[])
      and daterange(r.stay_check_in,r.stay_check_out,'[)')
        && daterange(p_check_in,p_check_out,'[)')
  ) then raise exception 'Those Short Let dates are no longer available'; end if;

  select * into v_existing from public.reservations r
  where r.user_id=v_profile.user_id and r.listing_id=v_listing.id::text
    and r.stay_type='short_let' and r.stay_check_in=p_check_in
    and r.stay_check_out=p_check_out and r.guest_count=p_guest_count
    and r.status='payment_pending'
    and coalesce(r.payment_expires_at,now()+interval '1 minute')>now()
  order by r.created_at desc limit 1;
  if v_existing.id is not null then return v_existing; end if;

  v_rate:=round(coalesce(v_listing.price,0),2);
  v_caution:=round(coalesce(v_listing.security_deposit_amount,0),2);
  if v_rate<=0 then raise exception 'Nightly rate is not configured'; end if;
  if v_caution<0 then raise exception 'Caution fee cannot be negative'; end if;
  v_stay:=round(v_rate*v_nights,2);
  select nullif(value,'')::integer into v_checkout_minutes
  from public.platform_settings where key='apartment_payment_hold_minutes'
    and coalesce(is_active,true) limit 1;
  if v_checkout_minutes is null or v_checkout_minutes<5 or v_checkout_minutes>120 then
    v_checkout_minutes:=30;
  end if;

  insert into public.reservations(
    listing_id,user_id,user_email,user_phone,listing_title,listing_price,
    listing_location,status,manual_payment_status,payment_reference,amount,
    currency,reservation_type,stay_type,stay_check_in,stay_check_out,stay_nights,
    nightly_rate_snapshot,stay_rent_total,security_deposit_snapshot,
    security_deposit_status,payment_expires_at,hold_expires_at,guest_count,
    occupant_count,canonical_state,created_at,updated_at
  ) values(
    v_listing.id::text,v_profile.user_id,v_profile.email,v_profile.phone,
    v_listing.title,v_listing.price,
    concat_ws(', ',nullif(v_listing.address,''),nullif(v_listing.city,''),nullif(v_listing.state,'')),
    'payment_pending','unpaid',null,v_stay+v_caution,'NGN','apartment','short_let',
    p_check_in,p_check_out,v_nights,v_rate,v_stay,v_caution,
    case when v_caution=0 then 'not_required' else 'pending' end,
    now()+make_interval(mins=>v_checkout_minutes),null,p_guest_count,
    p_guest_count,'checkout_pending',now(),now()
  ) returning * into v_created;

  insert into public.short_let_booking_transitions(
    reservation_id,from_state,to_state,event_type,event_key,actor_user_id,
    actor_type,metadata
  ) values(
    v_created.id,null,'checkout_pending','checkout_opened',
    'short-let-checkout:'||v_created.id,v_profile.user_id,'customer',
    jsonb_build_object('guest_count',p_guest_count,'check_in',p_check_in,
      'check_out',p_check_out,'stay_price',v_stay,'caution_fee',v_caution,
      'separate_reservation_fee',false)
  ) on conflict(event_key) do nothing;
  return v_created;
end
$$;


--
-- Name: create_support_conversation(text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_support_conversation(p_subject text, p_category text DEFAULT 'general'::text, p_context_type text DEFAULT 'general'::text, p_context_id text DEFAULT NULL::text, p_context_snapshot jsonb DEFAULT '{}'::jsonb, p_priority text DEFAULT 'normal'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor public.profiles;
  v_id uuid;
  v_context_type text:=coalesce(nullif(btrim(p_context_type),''),'general');
  v_context_id text:=nullif(btrim(p_context_id),'');
  v_subject text;
  v_field_officer_id text;
  v_channel_kind text:='support_case';
begin
  select * into v_actor from public.profiles where auth_id=auth.uid()::text limit 1;
  if v_actor.user_id is null then raise exception 'Authentication required'; end if;
  if v_actor.role not in ('user','worker','property_partner') then raise exception 'WeHouse Help is available to User, Worker and Property Partner accounts'; end if;
  if coalesce(v_actor.deleted,false) or coalesce(v_actor.suspended,false) or coalesce(v_actor.banned,false) then raise exception 'Account is not active'; end if;
  v_subject:=coalesce(nullif(btrim(p_subject),''),case when v_context_type in ('apartment_reservation','reservation','hotel_booking') then 'Reservation help' else 'WeHouse Help' end);
  if v_context_type='property_inspection' then
    if v_actor.role='user' then
      select field_officer_id into v_field_officer_id from public.user_inspection_requests
      where id::text=coalesce(v_context_id,nullif(p_context_snapshot->>'inspection_id','')) and user_id=v_actor.user_id limit 1;
    elsif v_actor.role='property_partner' then
      select coalesce(assigned_field_officer_id,field_officer_id,assigned_to) into v_field_officer_id
      from public.inspection_requests
      where id::text=coalesce(v_context_id,nullif(p_context_snapshot->>'inspection_id','')) and owner_id=v_actor.user_id limit 1;
    end if;
    if nullif(btrim(coalesce(v_field_officer_id,'')),'') is null then raise exception 'This inspection is not assigned to a Field Officer'; end if;
    v_channel_kind:='field_operations';
  end if;
  select id into v_id from public.partner_support_conversations
  where partner_id=v_actor.user_id and context_type=v_context_type and context_id is not distinct from v_context_id
  order by created_at desc limit 1;
  if v_id is null then
    insert into public.partner_support_conversations(
      partner_id,requester_role,subject,status,category,context_type,context_id,context_snapshot,priority,
      property_name,property_address,property_city,property_state,property_type,rental_mode,
      channel_kind,assigned_field_officer_id,created_at,updated_at
    ) values (
      v_actor.user_id,v_actor.role,v_subject,'open',coalesce(nullif(btrim(p_category),''),'general'),v_context_type,v_context_id,
      coalesce(p_context_snapshot,'{}'::jsonb),case when p_priority in ('low','normal','high','urgent') then p_priority else 'normal' end,
      nullif(p_context_snapshot->>'property_name',''),nullif(p_context_snapshot->>'property_address',''),
      coalesce(nullif(p_context_snapshot->>'city',''),nullif(v_actor.local_government,''),v_actor.city),v_actor.state,
      nullif(p_context_snapshot->>'property_type',''),nullif(p_context_snapshot->>'rental_mode',''),
      v_channel_kind,v_field_officer_id,now(),now()
    ) returning id into v_id;
  else
    update public.partner_support_conversations set
      requester_role=v_actor.role,status='open',subject=v_subject,
      category=coalesce(nullif(btrim(p_category),''),category,'general'),
      context_snapshot=case when coalesce(p_context_snapshot,'{}'::jsonb)<>'{}'::jsonb then p_context_snapshot else context_snapshot end,
      priority=case when p_priority in ('low','normal','high','urgent') then p_priority else priority end,
      channel_kind=v_channel_kind,assigned_field_officer_id=coalesce(v_field_officer_id,assigned_field_officer_id),
      updated_at=now(),resolved_at=null,closed_at=null
    where id=v_id;
  end if;
  return v_id;
end;
$$;


--
-- Name: create_user_inspection_request(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_user_inspection_request(p_reservation_id text, p_notes text DEFAULT NULL::text) RETURNS public.user_inspection_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id text;
  v_res public.reservations;
  v_existing public.user_inspection_requests;
  v_created public.user_inspection_requests;
  v_listing public.listings;
  v_field_officer_id text;
begin
  select user_id into v_user_id from public.profiles where auth_id=auth.uid()::text limit 1;
  if v_user_id is null then raise exception 'Authentication required'; end if;
  select * into v_res from public.reservations where id=p_reservation_id and user_id=v_user_id for update;
  if v_res is null then raise exception 'Reservation not found'; end if;
  if v_res.manual_payment_status not in ('paid','completed') or v_res.paid_at is null then raise exception 'Complete the reservation before requesting inspection'; end if;
  if v_res.status not in ('reserved','inspection_pending') then raise exception 'Reservation is not eligible for inspection'; end if;
  select * into v_existing from public.user_inspection_requests where reservation_id=p_reservation_id and status in ('pending','scheduled','in_progress') order by created_at desc limit 1;
  if v_existing is not null then return v_existing; end if;
  select * into v_listing from public.listings where listing_id=v_res.listing_id or id::text=v_res.listing_id order by updated_at desc limit 1;
  if v_listing.id is null or v_listing.inspection_request_id is null then raise exception 'This property is missing its verified inspection assignment'; end if;
  select coalesce(assigned_field_officer_id,field_officer_id,assigned_to) into v_field_officer_id
  from public.inspection_requests where id=v_listing.inspection_request_id;
  if nullif(btrim(coalesce(v_field_officer_id,'')),'') is null then raise exception 'A Field Officer must be assigned to this property before an inspection can be requested'; end if;
  insert into public.user_inspection_requests(reservation_id,listing_id,user_id,field_officer_id,notes,status,created_at,updated_at)
  values(v_res.id,v_res.listing_id,v_user_id,v_field_officer_id,nullif(btrim(p_notes),''),'pending',now(),now()) returning * into v_created;
  update public.reservations set status='inspection_pending',inspection_requested_at=now(),updated_at=now() where id=v_res.id;
  insert into public.notifications(recipient_id,type,title,message,related_id,source_type,source_id,destination_route,destination_params,event_key,workspace_scope,read,created_at)
  values(v_field_officer_id,'inspection_requested','Customer inspection requested',coalesce(v_res.listing_title,'Apartment')||' is ready for a customer visit',v_created.id::text,'user_inspection',v_created.id::text,'staff_inspections',jsonb_build_object('id',v_created.id::text),'user_inspection_requested:'||v_created.id::text,'staff',false,now());
  return v_created;
end;
$$;


--
-- Name: create_worker_booking_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_worker_booking_payment(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  customer public.profiles;
  b public.worker_bookings;
  w public.profiles;
  amt numeric;
  ref text;
  existing public.booking_payments;
BEGIN
  SELECT * INTO customer FROM public.profiles WHERE auth_id=auth.uid()::text;
  IF customer IS NULL OR COALESCE(customer.deleted,false) OR COALESCE(customer.suspended,false) OR COALESCE(customer.banned,false) THEN
    RETURN jsonb_build_object('success',false,'error','Active customer account required');
  END IF;

  SELECT * INTO b FROM public.worker_bookings WHERE id=p_booking_id FOR UPDATE;
  IF b IS NULL THEN RETURN jsonb_build_object('success',false,'error','Booking not found'); END IF;
  IF b.user_id<>customer.user_id THEN RETURN jsonb_build_object('success',false,'error','Not authorized'); END IF;
  IF b.status<>'waiting_payment' THEN RETURN jsonb_build_object('success',false,'error','Booking is not waiting for payment'); END IF;

  IF EXISTS(
    SELECT 1
    FROM public.booking_payments bp
    WHERE bp.worker_booking_id=p_booking_id
      AND bp.status='review_required'
  ) THEN
    RETURN jsonb_build_object(
      'success',false,
      'requires_review',true,
      'error','A verified payment for this booking needs WeHouse review. Do not pay again.'
    );
  END IF;

  SELECT * INTO w FROM public.profiles WHERE user_id=b.worker_id AND public.user_has_active_workspace(user_id,'worker');
  IF w IS NULL OR w.worker_status<>'verified' OR w.worker_verified IS DISTINCT FROM true OR COALESCE(w.deleted,false) OR COALESCE(w.suspended,false) OR COALESCE(w.banned,false) THEN
    RETURN jsonb_build_object('success',false,'error','Worker is no longer eligible for this booking');
  END IF;

  amt:=COALESCE(b.negotiated_amount,b.agreed_amount,0);
  IF amt<=0 THEN RETURN jsonb_build_object('success',false,'error','No agreed amount set'); END IF;

  SELECT * INTO existing
  FROM public.booking_payments
  WHERE worker_booking_id=p_booking_id AND status='pending'
  ORDER BY created_at DESC
  LIMIT 1;

  IF existing IS NOT NULL THEN
    IF round(existing.amount_total,2)=round(amt,2) AND existing.created_at>now()-interval '30 minutes' THEN
      RETURN jsonb_build_object('success',true,'reference',existing.paystack_reference,'amount',amt,'existing',true);
    END IF;
    UPDATE public.booking_payments SET status='expired',updated_at=now() WHERE id=existing.id;
  END IF;

  ref:='WHBK-'||gen_random_uuid()::text;
  INSERT INTO public.booking_payments(
    payment_reference,user_id,payer_user_id,payee_user_id,amount,amount_total,net_amount,
    amount_commission,currency,status,purpose,paystack_reference,worker_booking_id,metadata,created_at,updated_at
  ) VALUES(
    ref,customer.user_id,customer.user_id,b.worker_id,amt,amt,amt,0,'NGN','pending','worker_booking',ref,p_booking_id,
    jsonb_build_object('source','create_worker_booking_payment','booking_id',p_booking_id),now(),now()
  );
  RETURN jsonb_build_object('success',true,'reference',ref,'amount',amt);
END;
$$;


--
-- Name: create_worker_booking_v2(text, text, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_worker_booking_v2(p_user_id text, p_worker_id text, p_agreed_price numeric, p_service_type text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare v_booking_id uuid; v_commission_percent numeric; v_wehouse_fee numeric; v_actor text;
begin
  select user_id into v_actor from public.profiles where auth_id=auth.uid()::text and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor is null or v_actor<>p_user_id then raise exception 'Authenticated user mismatch'; end if;
  if p_agreed_price is null or p_agreed_price<=0 then raise exception 'Agreed price must be greater than zero'; end if;
  select coalesce(nullif(value,'')::numeric,15) into v_commission_percent from public.platform_settings where key='commission_worker';
  v_wehouse_fee:=round(p_agreed_price*v_commission_percent/100,2);
  insert into public.worker_bookings(user_id,worker_id,service_type,agreed_amount,worker_receives,status,address,notes)
  values(p_user_id,p_worker_id,p_service_type,p_agreed_price,p_agreed_price-v_wehouse_fee,'pending',p_address,p_notes) returning id into v_booking_id;
  return v_booking_id;
end $$;


--
-- Name: create_worker_pro_web_payment(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_worker_pro_web_payment(p_billing_period text DEFAULT 'monthly'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_worker public.profiles;
  v_period text:=lower(btrim(coalesce(p_billing_period,'')));
  v_sales_enabled boolean:=false;
  v_price numeric:=0;
  v_plan_code text:='';
  v_terms_version text:='';
  v_terms_content text:='';
  v_terms_sha256 text:='';
  v_terms_accepted boolean:=false;
  v_reference text;
  v_existing public.booking_payments;
  v_iso_period text;
begin
  if v_period not in('monthly','yearly') then
    return jsonb_build_object('success',false,'error','Choose monthly or yearly billing');
  end if;
  select profile.* into v_worker from public.profiles profile
  where profile.auth_id=(select auth.uid())::text
    and public.user_has_active_workspace(profile.user_id,'worker')
    and profile.worker_status='verified' and profile.worker_verified=true
    and not coalesce(profile.deleted,false)
    and not coalesce(profile.suspended,false)
    and not coalesce(profile.banned,false) limit 1;
  if v_worker is null then return jsonb_build_object('success',false,'error','A WeHouse Reviewed Worker account is required'); end if;
  if public.worker_pro_is_active(v_worker.user_id) then return jsonb_build_object('success',false,'error','A paid Worker plan is already active; manage or cancel it before changing providers'); end if;
  select coalesce(lower(value) in('true','1','yes','on'),false) into v_sales_enabled from public.platform_settings where key='worker_pro_sales_enabled' and is_active=true limit 1;
  if v_period='yearly' then
    select coalesce(nullif(value,'')::numeric,0) into v_price from public.platform_settings where key='worker_pro_yearly_price_ngn' and is_active=true limit 1;
    select coalesce(value,'') into v_plan_code from public.platform_settings where key='worker_pro_web_paystack_yearly_plan_code' and is_active=true limit 1;
    v_iso_period:='P1Y';
  else
    select coalesce(nullif(value,'')::numeric,0) into v_price from public.platform_settings where key='worker_pro_monthly_price_ngn' and is_active=true limit 1;
    select coalesce(value,'') into v_plan_code from public.platform_settings where key='worker_pro_web_paystack_plan_code' and is_active=true limit 1;
    v_iso_period:='P1M';
  end if;
  select coalesce(value,'') into v_terms_version from public.platform_settings where key='worker_pro_terms_version' and is_active=true limit 1;
  select coalesce(value,'') into v_terms_content from public.platform_settings where key='worker_pro_terms_content' and is_active=true limit 1;
  if not coalesce(v_sales_enabled,false) then return jsonb_build_object('success',false,'error','Paid Worker plan sales are not open'); end if;
  if not public._legal_launch_gate_is_approved('worker_pro_web_sales') then return jsonb_build_object('success',false,'error','Paid Worker plan web sales are awaiting launch approval'); end if;
  if v_price<=0 or nullif(btrim(v_plan_code),'') is null then return jsonb_build_object('success',false,'error',initcap(v_period)||' billing is not configured'); end if;
  if nullif(btrim(v_terms_version),'') is null or length(btrim(v_terms_content))<100 then return jsonb_build_object('success',false,'error','Paid plan subscription terms are not published'); end if;
  v_terms_sha256:=encode(extensions.digest(convert_to(v_terms_content,'UTF8'),'sha256'),'hex');
  select exists(
    select 1 from public.worker_pro_terms_acceptances acceptance
    where acceptance.worker_id=v_worker.user_id
      and acceptance.terms_version=v_terms_version
      and acceptance.terms_sha256=v_terms_sha256
  ) into v_terms_accepted;
  if not coalesce(v_terms_accepted,false) then return jsonb_build_object('success',false,'error','Accept the current paid plan subscription terms before purchase'); end if;

  update public.booking_payments set status='expired',updated_at=now()
  where user_id=v_worker.user_id and purpose='worker_pro_subscription'
    and status='pending' and created_at<now()-interval '30 minutes';
  select * into v_existing from public.booking_payments
  where user_id=v_worker.user_id and purpose='worker_pro_subscription'
    and status='pending' order by created_at desc limit 1;
  if v_existing.id is not null then
    if v_existing.amount_total=v_price
       and coalesce(v_existing.metadata->>'plan_code','')=v_plan_code
       and coalesce(v_existing.metadata->>'terms_version','')=v_terms_version
       and coalesce(v_existing.metadata->>'billing_period','monthly')=v_period then
      return jsonb_build_object(
        'success',true,'reference',v_existing.paystack_reference,
        'amount',v_price,'plan_code',v_plan_code,'billing_period',v_period,
        'period',v_iso_period,'existing',true
      );
    end if;
    update public.booking_payments set status='expired',updated_at=now()
    where id=v_existing.id;
  end if;

  v_reference:='WHP-'||gen_random_uuid()::text;
  insert into public.booking_payments(
    payment_reference,user_id,payer_user_id,type,booking_type,amount,amount_total,
    net_amount,amount_commission,currency,status,purpose,payment_method,
    paystack_reference,metadata,created_at,updated_at
  ) values(
    v_reference,v_worker.user_id,v_worker.user_id,'worker_subscription',
    'worker_subscription',v_price,v_price,v_price,0,'NGN','pending',
    'worker_pro_subscription','paystack',v_reference,jsonb_build_object(
      'source','create_worker_pro_web_payment',
      'plan','worker_pro','billing_period',v_period,
      'period',v_iso_period,'plan_code',v_plan_code,
      'terms_version',v_terms_version,'terms_sha256',v_terms_sha256,
      'price_snapshot_ngn',v_price
    ),now(),now()
  );
  return jsonb_build_object(
    'success',true,'reference',v_reference,'amount',v_price,
    'plan_code',v_plan_code,'billing_period',v_period,
    'period',v_iso_period,'existing',false
  );
exception when unique_violation then
  select * into v_existing from public.booking_payments
  where user_id=v_worker.user_id and purpose='worker_pro_subscription'
    and status='pending' order by created_at desc limit 1;
  if v_existing.id is not null then
    return jsonb_build_object(
      'success',true,'reference',v_existing.paystack_reference,
      'amount',v_existing.amount_total,
      'plan_code',v_existing.metadata->>'plan_code',
      'billing_period',v_existing.metadata->>'billing_period',
      'period',v_existing.metadata->>'period','existing',true
    );
  end if;
  return jsonb_build_object('success',false,'error','Subscription checkout is already starting');
end;
$$;


