--
-- Name: creator_ban_user(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_ban_user(p_target_user_id text, p_reason text, p_creator_elevation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id(); v_target public.profiles;
begin
  if not public.creator_has_elevation(
    p_creator_elevation_id,'all_sensitive'
  ) then raise exception 'Recent Creator authentication required'; end if;
  if nullif(btrim(coalesce(p_reason,'')),'') is null then
    raise exception 'Ban reason is required'; end if;
  select * into v_target from public.profiles where user_id=p_target_user_id for update;
  if v_target.user_id is null or v_target.user_id=v_actor
     or v_target.role='creator' then raise exception 'Protected account'; end if;
  update public.profiles set banned=true,banned_at=now(),banned_by=v_actor,
    banned_reason=btrim(p_reason),deleted=true,deleted_at=now(),
    worker_status=case when role='worker' then 'suspended' else worker_status end,
    updated_by=v_actor,updated_at=now() where user_id=p_target_user_id;
  insert into public.admin_audit_log(
    admin_id,action,target_type,target_id,details,created_at
  ) values(v_actor,'creator_account_ban','profile',p_target_user_id,
    jsonb_build_object('reason',btrim(p_reason),
      'creator_elevation_id',p_creator_elevation_id)::text,now());
end
$$;


--
-- Name: creator_delete_announcement(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_delete_announcement(p_announcement_id bigint, p_creator_elevation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id();
begin
  if not public.creator_has_elevation(
    p_creator_elevation_id,'all_sensitive'
  ) then raise exception 'Recent Creator authentication required'; end if;
  if not exists(select 1 from public.announcements where id=p_announcement_id) then
    raise exception 'Announcement not found'; end if;
  delete from public.announcements where id=p_announcement_id;
  insert into public.admin_audit_log(
    admin_id,action,target_type,target_id,details,created_at
  ) values(v_actor,'creator_announcement_delete','announcement',
    p_announcement_id::text,jsonb_build_object(
      'creator_elevation_id',p_creator_elevation_id)::text,now());
end
$$;


--
-- Name: creator_get_change_history(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_get_change_history(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 150) RETURNS TABLE(event_id text, actor_name text, actor_role text, action_label text, area_label text, subject_label text, occurred_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_limit integer := least(greatest(coalesce(p_limit,150),1),250);
BEGIN
  SELECT * INTO v_actor
  FROM public.profiles
  WHERE auth_id=(select auth.uid())::text
    AND role='creator'
    AND coalesce(deleted,false)=false
    AND coalesce(suspended,false)=false
    AND coalesce(banned,false)=false
  LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Creator access required'; END IF;

  RETURN QUERY
  WITH human_events AS (
    SELECT a.*, actor.full_name actor_full_name, actor.username actor_username,
           actor.role actor_profile_role, target_profile.full_name target_name,
           target_profile.username target_username, ps.label setting_label
    FROM public.audit_logs a
    JOIN LATERAL (
      SELECT p.full_name,p.username,p.role
      FROM public.profiles p
      WHERE p.user_id=a.admin_id OR p.auth_id=a.admin_id
         OR (a.admin_email IS NOT NULL AND lower(p.email)=lower(a.admin_email))
      ORDER BY CASE WHEN p.user_id=a.admin_id THEN 0 WHEN p.auth_id=a.admin_id THEN 1 ELSE 2 END
      LIMIT 1
    ) actor ON true
    LEFT JOIN public.platform_settings ps
      ON a.target_type='platform_settings' AND ps.key=a.target_id
    LEFT JOIN public.profiles target_profile
      ON a.target_type='profiles' AND target_profile.user_id=a.target_id
    WHERE actor.role IN ('creator','admin','staff')
      AND upper(coalesce(a.action,'')) NOT LIKE 'STAFF_TRUST%'
      AND (
        (a.target_type='platform_settings'
          AND upper(a.action)='UPDATE'
          AND actor.role='creator'
          AND coalesce(ps.editable,false)=true
          AND lower(coalesce(a.target_id,'')) NOT LIKE '%secret%'
          AND lower(coalesce(a.target_id,'')) NOT LIKE '%password%'
          AND lower(coalesce(a.target_id,'')) NOT LIKE '%token%')
        OR
        (a.target_type='profiles' AND upper(a.action) IN
          ('ROLE_CHANGE','REASSIGN','SUSPEND','RESTORE','BAN','UNBAN','DELETE','PROMOTE','DEMOTE'))
        OR
        (a.target_type IN ('worker_verifications','listings','inspection_requests','listing_reports','withdrawals','wallets','worker_bookings')
          AND upper(a.action) IN
          ('APPROVE','REJECT','SUSPEND','RESTORE','REASSIGN','RESOLVE','DISMISS','FREEZE','UNFREEZE','RELEASE','HOLD','REFUND','CANCEL','COMPLETE'))
      )
  ), projected AS (
    SELECT
      md5(coalesce(h.id,'')||':'||h.created_at::text) AS event_id,
      coalesce(h.actor_full_name,h.actor_username,'WeHouse team')::text AS actor_name,
      h.actor_profile_role::text AS actor_role,
      CASE upper(h.action)
        WHEN 'ROLE_CHANGE' THEN 'Changed role for'
        WHEN 'REASSIGN' THEN 'Reassigned'
        WHEN 'APPROVE' THEN 'Approved'
        WHEN 'REJECT' THEN 'Rejected'
        WHEN 'SUSPEND' THEN 'Suspended'
        WHEN 'RESTORE' THEN 'Restored'
        WHEN 'BAN' THEN 'Restricted'
        WHEN 'UNBAN' THEN 'Restored'
        WHEN 'RESOLVE' THEN 'Resolved'
        WHEN 'DISMISS' THEN 'Dismissed'
        WHEN 'FREEZE' THEN 'Paused'
        WHEN 'UNFREEZE' THEN 'Restored'
        WHEN 'RELEASE' THEN 'Released'
        WHEN 'HOLD' THEN 'Placed on hold'
        WHEN 'REFUND' THEN 'Refunded'
        WHEN 'CANCEL' THEN 'Cancelled'
        WHEN 'COMPLETE' THEN 'Completed'
        WHEN 'UPDATE' THEN 'Changed'
        ELSE initcap(replace(lower(h.action),'_',' '))
      END::text AS action_label,
      CASE lower(h.target_type)
        WHEN 'platform_settings' THEN 'Settings'
        WHEN 'profiles' THEN 'Team & accounts'
        WHEN 'worker_bookings' THEN 'Worker bookings'
        WHEN 'worker_verifications' THEN 'Workers'
        WHEN 'listings' THEN 'Properties'
        WHEN 'inspection_requests' THEN 'Properties'
        WHEN 'listing_reports' THEN 'Moderation'
        WHEN 'withdrawals' THEN 'Finance'
        WHEN 'wallets' THEN 'Finance'
        ELSE 'Operations'
      END::text AS area_label,
      CASE lower(h.target_type)
        WHEN 'platform_settings' THEN coalesce(h.setting_label,'Platform setting')
        WHEN 'profiles' THEN coalesce(h.target_name,h.target_username,'WeHouse account')
        WHEN 'worker_bookings' THEN 'Worker service booking'
        WHEN 'worker_verifications' THEN 'Worker review'
        WHEN 'listings' THEN 'Property listing'
        WHEN 'inspection_requests' THEN 'Property inspection'
        WHEN 'listing_reports' THEN 'Listing report'
        WHEN 'withdrawals' THEN 'Payout request'
        WHEN 'wallets' THEN 'Wallet'
        ELSE 'Operational record'
      END::text AS subject_label,
      h.created_at AS occurred_at
    FROM human_events h
  )
  SELECT p.event_id,p.actor_name,p.actor_role,p.action_label,p.area_label,p.subject_label,p.occurred_at
  FROM projected p
  WHERE nullif(trim(coalesce(p_search,'')),'') IS NULL
     OR lower(concat_ws(' ',p.actor_name,p.actor_role,p.action_label,p.area_label,p.subject_label))
        LIKE '%'||lower(trim(p_search))||'%'
  ORDER BY p.occurred_at DESC
  LIMIT v_limit;
END;
$$;


--
-- Name: creator_get_platform_analytics(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_get_platform_analytics(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_days integer := LEAST(90, GREATEST(7, COALESCE(p_days,30)));
  v_start date;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_actor.user_id IS NULL OR v_actor.role<>'creator' OR COALESCE(v_actor.deleted,false) OR COALESCE(v_actor.suspended,false) OR COALESCE(v_actor.banned,false) THEN
    RAISE EXCEPTION 'Creator access required';
  END IF;
  v_start := CURRENT_DATE-(v_days-1);

  RETURN jsonb_build_object(
    'days',v_days,
    'period_start',v_start,
    'period_end',CURRENT_DATE,
    'summary',jsonb_build_object(
      'new_users',(SELECT count(*) FROM public.profiles WHERE role='user' AND created_at>=v_start AND deleted_at IS NULL),
      'new_workers',(SELECT count(*) FROM public.profiles WHERE public.user_has_active_workspace(user_id,'worker') AND created_at>=v_start AND deleted_at IS NULL),
      'new_partners',(SELECT count(*) FROM public.profiles WHERE public.user_has_active_workspace(user_id,'property_partner') AND created_at>=v_start AND deleted_at IS NULL),
      'published_listings',(SELECT count(*) FROM public.listings WHERE deleted_at IS NULL AND approved_at>=v_start AND status IN ('available','reserved','closed')),
      'worker_bookings',(SELECT count(*) FROM public.worker_bookings WHERE created_at>=v_start),
      'verified_payments',(SELECT count(*) FROM public.booking_payments WHERE verified_at>=v_start),
      'verified_payment_volume',(SELECT COALESCE(sum(COALESCE(amount_total,amount,0)),0) FROM public.booking_payments WHERE verified_at>=v_start),
      'commission_earned',(SELECT COALESCE(sum(commission_amount),0) FROM public.commission_ledger WHERE created_at>=v_start)
    ),
    'daily',(
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'date',d::date,
        'signups',(SELECT count(*) FROM public.profiles p WHERE p.created_at>=d AND p.created_at<d+interval '1 day' AND p.deleted_at IS NULL),
        'published_listings',(SELECT count(*) FROM public.listings l WHERE l.approved_at>=d AND l.approved_at<d+interval '1 day' AND l.deleted_at IS NULL AND l.status IN ('available','reserved','closed')),
        'worker_bookings',(SELECT count(*) FROM public.worker_bookings w WHERE w.created_at>=d AND w.created_at<d+interval '1 day'),
        'verified_payments',(SELECT count(*) FROM public.booking_payments bp WHERE bp.verified_at>=d AND bp.verified_at<d+interval '1 day')
      ) ORDER BY d),'[]'::jsonb)
      FROM generate_series(v_start::timestamp,CURRENT_DATE::timestamp,interval '1 day') d
    ),
    'listing_pipeline',(
      SELECT COALESCE(jsonb_object_agg(status,cnt),'{}'::jsonb)
      FROM (SELECT COALESCE(status,'unknown') status,count(*) cnt FROM public.listings WHERE deleted_at IS NULL GROUP BY status) s
    ),
    'worker_pipeline',(
      SELECT COALESCE(jsonb_object_agg(worker_status,cnt),'{}'::jsonb)
      FROM (SELECT COALESCE(worker_status,'unknown') worker_status,count(*) cnt FROM public.profiles WHERE public.user_has_active_workspace(user_id,'worker') AND deleted_at IS NULL GROUP BY worker_status) s
    ),
    'top_markets',(
      SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.available_listings DESC,x.state,x.lga),'[]'::jsonb)
      FROM (
        SELECT COALESCE(state,'Unknown') state,COALESCE(city,'Unknown') lga,count(*) available_listings
        FROM public.listings
        WHERE deleted_at IS NULL AND status='available'
        GROUP BY state,city
        ORDER BY count(*) DESC,state,city
        LIMIT 8
      ) x
    ),
    'activity',(
      SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC),'[]'::jsonb)
      FROM (
        SELECT a.id,a.action,a.target_type,a.target_id,a.details,a.created_at,a.admin_id,p.username AS actor_username,p.role AS actor_role
        FROM public.audit_logs a
        LEFT JOIN public.profiles p ON p.user_id=a.admin_id
        ORDER BY a.created_at DESC
        LIMIT 40
      ) x
    )
  );
END;
$$;


--
-- Name: creator_get_worker_review_trust_status(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_get_worker_review_trust_status(p_worker_id text, p_creator_elevation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.creator_has_elevation(
    p_creator_elevation_id,'private_evidence'
  ) then raise exception 'Recent Creator authentication required'; end if;
  return public._worker_review_trust_payload(p_worker_id);
end
$$;


--
-- Name: creator_has_elevation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_has_elevation(p_creator_elevation_id uuid, p_action_class text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1
    from public.creator_elevation_grants g
    join public.profiles p on p.user_id=g.creator_user_id
    where g.creator_elevation_id=p_creator_elevation_id
      and g.auth_user_id=(select auth.uid())
      and g.auth_session_id=coalesce((select auth.jwt()->>'session_id'),'')
      and g.revoked_at is null
      and g.expires_at>now()
      and p.role='creator'
      and not coalesce(p.deleted,false)
      and not coalesce(p.suspended,false)
      and not coalesce(p.banned,false)
      and (
        p_action_class=any(g.action_classes)
        or 'all_sensitive'=any(g.action_classes)
      )
  )
$$;


--
-- Name: creator_policy_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.creator_policy_versions (
    policy_version_id uuid DEFAULT gen_random_uuid() NOT NULL,
    policy_key text NOT NULL,
    scope_type text DEFAULT 'global'::text NOT NULL,
    scope_key text DEFAULT '*'::text NOT NULL,
    version integer NOT NULL,
    value jsonb NOT NULL,
    value_schema jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_until timestamp with time zone,
    public_disclosure boolean DEFAULT false NOT NULL,
    disclosure_text text,
    legal_review_state text DEFAULT 'pending'::text NOT NULL,
    reason text NOT NULL,
    created_by text,
    approved_by text,
    supersedes uuid,
    checksum text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    published_at timestamp with time zone,
    retired_at timestamp with time zone,
    CONSTRAINT creator_policy_versions_check CHECK (((effective_until IS NULL) OR (effective_until > effective_from))),
    CONSTRAINT creator_policy_versions_check1 CHECK (((status = 'draft'::text) OR (approved_by IS NOT NULL) OR (created_by IS NULL))),
    CONSTRAINT creator_policy_versions_legal_review_state_check CHECK ((legal_review_state = ANY (ARRAY['pending'::text, 'reviewed'::text, 'not_required'::text]))),
    CONSTRAINT creator_policy_versions_scope_type_check CHECK ((scope_type = ANY (ARRAY['global'::text, 'country'::text, 'state'::text, 'product'::text, 'hotel'::text, 'worker_category'::text]))),
    CONSTRAINT creator_policy_versions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'scheduled'::text, 'active'::text, 'retired'::text]))),
    CONSTRAINT creator_policy_versions_version_check CHECK ((version > 0))
);


--
-- Name: creator_publish_legal_document(uuid, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_publish_legal_document(p_policy_version_id uuid, p_effective_from timestamp with time zone, p_review_reference text, p_creator_elevation_id uuid) RETURNS public.creator_policy_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_draft public.creator_policy_versions;
  v_result public.creator_policy_versions;
  v_status text;
  v_effective timestamptz:=coalesce(p_effective_from,now());
  v_value jsonb;
begin
  if not public.creator_has_elevation(p_creator_elevation_id,'policy_publish') then
    raise exception 'Recent Creator policy authentication required';
  end if;
  if char_length(btrim(coalesce(p_review_reference,'')))<3 then
    raise exception 'Record the legal review reference before publication';
  end if;
  select * into v_draft from public.creator_policy_versions
  where policy_version_id=p_policy_version_id
    and policy_key in('legal_privacy','legal_terms')
    and status='draft' for update;
  if v_draft.policy_version_id is null then
    raise exception 'Legal draft not found';
  end if;
  v_status:=case when v_effective>now() then 'scheduled' else 'active' end;
  v_value:=jsonb_set(v_draft.value,'{review_reference}',
    to_jsonb(btrim(p_review_reference)),true);
  update public.creator_policy_versions set status='retired',retired_at=now()
  where policy_key=v_draft.policy_key and scope_type='global' and scope_key='*'
    and status='scheduled';
  if v_status='active' then
    update public.creator_policy_versions
    set status='retired',effective_until=v_effective,retired_at=now()
    where policy_key=v_draft.policy_key and scope_type='global' and scope_key='*'
      and status='active';
  end if;
  update public.creator_policy_versions set
    value=v_value,status=v_status,effective_from=v_effective,
    legal_review_state='reviewed',approved_by=v_actor,published_at=now(),
    checksum=md5(v_value::text)
  where policy_version_id=v_draft.policy_version_id
  returning * into v_result;
  insert into public.admin_audit_log(
    admin_id,action,target_type,target_id,details,created_at
  ) values(
    v_actor,'creator_publish_legal_document','creator_policy_version',
    v_result.policy_version_id::text,
    jsonb_build_object('document',v_result.value->>'document_type',
      'version',v_result.version,'effective_from',v_result.effective_from,
      'review_reference',btrim(p_review_reference),
      'creator_elevation_id',p_creator_elevation_id)::text,now()
  );
  return v_result;
end
$$;


--
-- Name: creator_publish_policy(uuid, text, text, text, jsonb, jsonb, timestamp with time zone, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_publish_policy(p_creator_elevation_id uuid, p_policy_key text, p_scope_type text, p_scope_key text, p_value jsonb, p_value_schema jsonb, p_effective_from timestamp with time zone, p_public_disclosure boolean, p_disclosure_text text, p_legal_review_state text, p_reason text) RETURNS public.creator_policy_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_previous public.creator_policy_versions;
  v_result public.creator_policy_versions;
  v_version integer;
  v_status text;
begin
  if not public.creator_has_elevation(p_creator_elevation_id,'policy_publish') then
    raise exception 'Recent Creator policy authentication required';
  end if;
  select * into v_previous
  from public.creator_policy_versions
  where policy_key=p_policy_key and scope_type=p_scope_type
    and scope_key=p_scope_key and status='active'
  for update;
  select coalesce(max(version),0)+1 into v_version
  from public.creator_policy_versions
  where policy_key=p_policy_key and scope_type=p_scope_type and scope_key=p_scope_key;

  v_status:=case when p_effective_from>now() then 'scheduled' else 'active' end;
  update public.creator_policy_versions
  set status='retired',retired_at=now()
  where policy_key=p_policy_key and scope_type=p_scope_type
    and scope_key=p_scope_key and status='scheduled';
  if v_status='active' and v_previous.policy_version_id is not null then
    update public.creator_policy_versions
    set status='retired',effective_until=p_effective_from,retired_at=now()
    where policy_version_id=v_previous.policy_version_id;
  end if;

  insert into public.creator_policy_versions(
    policy_key,scope_type,scope_key,version,value,value_schema,status,
    effective_from,public_disclosure,disclosure_text,legal_review_state,
    reason,created_by,approved_by,supersedes,checksum,published_at
  ) values(
    p_policy_key,p_scope_type,p_scope_key,v_version,p_value,
    coalesce(p_value_schema,'{}'::jsonb),v_status,p_effective_from,
    p_public_disclosure,p_disclosure_text,p_legal_review_state,p_reason,
    v_actor,v_actor,v_previous.policy_version_id,
    md5(p_policy_key||p_scope_type||p_scope_key||v_version::text||p_value::text),
    now()
  ) returning * into v_result;
  return v_result;
end
$$;


--
-- Name: creator_reassign_branch(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_reassign_branch(p_target_user_id text, p_new_state text, p_new_lga text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  raise exception 'Recent Creator authentication required';
end
$$;


--
-- Name: creator_reassign_branch(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_reassign_branch(p_target_user_id text, p_new_state text, p_new_lga text, p_creator_elevation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_target public.profiles;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.role<>'creator'
     or not public.creator_has_elevation(p_creator_elevation_id,'staff_authority') then
    raise exception 'Recent Creator authentication required';
  end if;
  select * into v_target from public.profiles
  where user_id=p_target_user_id and role in('admin','staff') for update;
  if v_target.user_id is null then raise exception 'Admin or Staff account required'; end if;
  if nullif(btrim(coalesce(p_new_state,'')),'') is null
     or nullif(btrim(coalesce(p_new_lga,'')),'') is null then
    raise exception 'State and LGA are required';
  end if;
  update public.profiles set assigned_state=btrim(p_new_state),
    assigned_lga=btrim(p_new_lga),updated_by=v_actor.user_id,updated_at=now()
  where user_id=p_target_user_id;
  update public.workspace_role_assignments set
    scope_state=btrim(p_new_state),scope_lga=btrim(p_new_lga),updated_at=now()
  where user_id=p_target_user_id and status='active'
    and workspace_role in(
      'staff','admin','property_operations','field_operations',
      'worker_operations','finance_operations','security_operations','support'
    );
  insert into public.admin_audit_log(
    admin_id,action,target_type,target_id,details,created_at
  ) values(v_actor.user_id,'team_branch_reassigned','profiles',p_target_user_id,
    jsonb_build_object('old_state',v_target.assigned_state,
      'old_lga',v_target.assigned_lga,'new_state',btrim(p_new_state),
      'new_lga',btrim(p_new_lga))::text,now());
  return true;
end
$$;


--
-- Name: creator_reject_property_submission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_reject_property_submission(p_inspection_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ begin raise exception 'Recent Creator authentication required'; end $$;


--
-- Name: creator_reject_property_submission(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_reject_property_submission(p_inspection_id uuid, p_reason text, p_creator_elevation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_request public.inspection_requests;
begin
  if not public.creator_has_elevation(
    p_creator_elevation_id,'all_sensitive'
  ) then raise exception 'Recent Creator authentication required'; end if;
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and role='creator';
  if nullif(btrim(coalesce(p_reason,'')),'') is null then
    raise exception 'A rejection reason is required'; end if;
  select * into v_request from public.inspection_requests
  where id=p_inspection_id for update;
  if v_request.id is null then raise exception 'Property submission not found'; end if;
  if v_request.published_at is not null then
    raise exception 'A published property must be handled from Published listings'; end if;
  if v_request.draft_listing_id is not null and exists(
    select 1 from public.reservations r
    where r.listing_id=v_request.draft_listing_id::text
      and r.status in('payment_pending','reserved','inspection_pending','ready_for_move_in','occupied')
  ) then raise exception 'This draft has an active reservation and cannot be rejected'; end if;
  if v_request.draft_listing_id is not null then
    update public.listings set deleted_at=now(),status='closed',
      availability_status='unavailable',updated_at=now()
    where id=v_request.draft_listing_id and deleted_at is null;
  end if;
  if v_request.draft_hotel_id is not null then
    update public.hotels set status='rejected',updated_at=now()
    where hotel_id=v_request.draft_hotel_id;
  end if;
  update public.inspection_requests set status='rejected',
    rejection_reason=btrim(p_reason),assigned_to=null,
    assigned_field_officer_id=null,field_officer_id=null,
    scheduled_date=null,updated_at=now() where id=p_inspection_id;
  insert into public.audit_logs(
    action,target_type,target_id,details,admin_id,admin_email
  ) values('PROPERTY_SUBMISSION_REJECTED','inspection_requests',
    p_inspection_id::text,jsonb_build_object('reason',btrim(p_reason),
      'request_code',v_request.request_code,
      'creator_elevation_id',p_creator_elevation_id)::text,
    v_actor.user_id,v_actor.email);
  return true;
end
$$;


--
-- Name: creator_remove_listing(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_remove_listing(p_listing_id uuid, p_reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_row public.listings;
begin
  select * into v_actor from public.profiles where auth_id=auth.uid()::text limit 1;
  if v_actor is null or v_actor.role not in ('creator','admin') or coalesce(v_actor.deleted,false) or coalesce(v_actor.suspended,false) or coalesce(v_actor.banned,false) then
    raise exception 'Creator or Admin access required';
  end if;
  select * into v_row from public.listings where id=p_listing_id and deleted_at is null for update;
  if v_row.id is null then raise exception 'Listing not found'; end if;
  if exists(select 1 from public.reservations r where r.listing_id::text=p_listing_id::text and r.status in ('payment_pending','reserved','inspection_pending','ready_for_move_in','occupied')) then
    raise exception 'This property has an active reservation and cannot be removed. Resolve the reservation first.';
  end if;
  update public.listings set deleted_at=now(),status='closed',availability_status='unavailable',current_reservation_id=null,updated_at=now() where id=p_listing_id;
  return true;
end
$$;


--
-- Name: creator_review_worker(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_review_worker(p_worker_id text, p_decision text, p_reason text, p_creator_elevation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id(); v_worker public.profiles;
  v_ver public.worker_verifications;
begin
  if not public.creator_has_elevation(
    p_creator_elevation_id,'private_evidence'
  ) then raise exception 'Recent Creator authentication required'; end if;
  select * into v_worker from public.profiles
  where user_id=p_worker_id and public.user_has_active_workspace(user_id,'worker') and not coalesce(deleted,false)
  for update;
  if v_worker.user_id is null then raise exception 'Worker not found'; end if;
  if v_worker.worker_status<>'profile_under_review' then
    raise exception 'Worker is not in the review queue'; end if;
  select * into v_ver from public.worker_verifications
  where worker_id=p_worker_id limit 1;
  if p_decision='approve' then
    if not public.worker_identity_is_current(p_worker_id) then
      raise exception 'The current private face check has not passed'; end if;
    if v_ver.id is null or nullif(btrim(coalesce(v_ver.verification_video_url,'')),'') is null then
      raise exception 'Professional work evidence is incomplete'; end if;
    update public.profiles set worker_status='verified',worker_verified=true,
      available=true,updated_at=now(),updated_by=v_actor where user_id=p_worker_id;
    update public.worker_verifications set status='verified',reviewed_by=v_actor,
      reviewed_at=now(),updated_at=now() where id=v_ver.id;
  elsif p_decision='reject' then
    if nullif(btrim(coalesce(p_reason,'')),'') is null then
      raise exception 'Rejection reason is required'; end if;
    update public.profiles set worker_status='rejected',worker_verified=false,
      available=false,updated_at=now(),updated_by=v_actor where user_id=p_worker_id;
    update public.worker_verifications set status='rejected',reviewed_by=v_actor,
      review_notes=btrim(p_reason),reviewed_at=now(),updated_at=now()
    where id=v_ver.id;
  else raise exception 'Decision must be approve or reject'; end if;
  insert into public.worker_verification_reviews(
    worker_id,reviewer_id,reviewer_role,action,rejection_reason
  ) values(p_worker_id,v_actor,'creator',
    case when p_decision='approve' then 'approved' else 'rejected' end,
    case when p_decision='reject' then btrim(p_reason) end);
  insert into public.admin_audit_log(
    admin_id,action,target_type,target_id,details,created_at
  ) values(v_actor,'creator_worker_review','worker',p_worker_id,
    jsonb_build_object('decision',p_decision,
      'creator_elevation_id',p_creator_elevation_id)::text,now());
end
$$;


--
-- Name: creator_save_legal_draft(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_save_legal_draft(p_document text, p_title text, p_body text, p_locale text, p_reason text) RETURNS public.creator_policy_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_key text;
  v_version integer;
  v_value jsonb;
  v_result public.creator_policy_versions;
begin
  if not public.current_actor_has_workspace('creator',null) then
    raise exception 'Creator authority required';
  end if;
  if p_document not in('privacy','terms') then
    raise exception 'Document must be privacy or terms';
  end if;
  if char_length(btrim(coalesce(p_body,'')))<500 then
    raise exception 'Complete legal document body is required';
  end if;
  if char_length(btrim(coalesce(p_reason,'')))<5 then
    raise exception 'Draft reason is required';
  end if;
  v_key:=case when p_document='privacy' then 'legal_privacy' else 'legal_terms' end;
  perform pg_advisory_xact_lock(hashtext('legal-document:'||v_key||':'||coalesce(p_locale,'en-NG')));
  select coalesce(max(version),0)+1 into v_version
  from public.creator_policy_versions
  where policy_key=v_key and scope_type='global' and scope_key='*';
  v_value:=jsonb_build_object(
    'document_type',p_document,
    'title',btrim(coalesce(p_title,case when p_document='privacy'
      then 'Privacy Policy' else 'Terms & Conditions' end)),
    'body',btrim(p_body),
    'locale',coalesce(nullif(btrim(p_locale),''),'en-NG'),
    'review_reference',null
  );
  insert into public.creator_policy_versions(
    policy_key,scope_type,scope_key,version,value,value_schema,status,
    effective_from,public_disclosure,disclosure_text,legal_review_state,
    reason,created_by,checksum
  ) values(
    v_key,'global','*',v_version,v_value,
    '{"type":"legal_document","required":["document_type","title","body","locale","review_reference"]}'::jsonb,
    'draft',now(),true,'Published legal document','pending',btrim(p_reason),
    v_actor,md5(v_value::text)
  ) returning * into v_result;
  return v_result;
end
$$;


--
-- Name: creator_send_announcement(text, text, text[], text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_send_announcement(p_title text, p_content text, p_target_roles text[], p_recipient_ids text[] DEFAULT NULL::text[], p_scope_state text DEFAULT NULL::text, p_scope_lga text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor public.profiles;
  v_id integer;
  v_count integer;
  v_roles text[];
begin
  select * into v_actor from public.profiles where auth_id=auth.uid()::text limit 1;
  if v_actor.user_id is null or v_actor.role<>'creator' then raise exception 'Creator account required'; end if;
  if nullif(btrim(coalesce(p_title,'')),'') is null then raise exception 'Announcement title is required'; end if;
  if nullif(btrim(coalesce(p_content,'')),'') is null then raise exception 'Announcement content is required'; end if;
  select coalesce(array_agg(distinct role_name),'{}'::text[]) into v_roles
  from unnest(coalesce(p_target_roles,'{}'::text[])) role_name
  where role_name in ('user','worker','staff','property_partner','admin');
  if coalesce(array_length(v_roles,1),0)=0 then raise exception 'Select at least one recipient type'; end if;

  insert into public.announcements(
    title,content,sender_id,sender_name,sender_role,target_type,target_state,target_lga,
    recipient_count,read_count,created_at
  ) values (
    btrim(p_title),btrim(p_content),v_actor.user_id,
    coalesce(nullif(v_actor.full_name,''),nullif(v_actor.username,''),'WeHouse'),'creator',
    case when p_recipient_ids is null then 'all_users' else 'specific_user' end,
    nullif(btrim(coalesce(p_scope_state,'')),''),nullif(btrim(coalesce(p_scope_lga,'')),''),
    0,0,now()
  ) returning id into v_id;

  insert into public.announcement_recipients(announcement_id,user_id,read_status,delivered_at)
  select v_id,p.user_id,false,now()
  from public.profiles p
  where p.user_id<>v_actor.user_id
    and p.role=any(v_roles)
    and coalesce(p.deleted,false)=false
    and coalesce(p.suspended,false)=false
    and coalesce(p.banned,false)=false
    and (p_recipient_ids is null or p.user_id=any(p_recipient_ids))
    and (nullif(btrim(coalesce(p_scope_state,'')),'') is null
      or lower(btrim(coalesce(nullif(p.state,''),nullif(p.assigned_state,''),'')))=lower(btrim(p_scope_state)))
    and (nullif(btrim(coalesce(p_scope_lga,'')),'') is null
      or lower(btrim(coalesce(nullif(p.local_government,''),nullif(p.city,''),nullif(p.assigned_lga,''),'')))=lower(btrim(p_scope_lga)));
  get diagnostics v_count=row_count;
  if v_count=0 then
    delete from public.announcements where id=v_id;
    raise exception 'No users match the selected recipients';
  end if;
  update public.announcements set recipient_count=v_count where id=v_id;
  return jsonb_build_object('id',v_id,'recipient_count',v_count);
end;
$$;


--
-- Name: creator_set_account_suspension(text, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_set_account_suspension(p_target_user_id text, p_suspended boolean, p_reason text, p_creator_elevation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id();
begin
  if not public.creator_has_elevation(
    p_creator_elevation_id,'all_sensitive'
  ) then raise exception 'Recent Creator authentication required'; end if;
  perform public._set_account_suspension(
    v_actor,p_target_user_id,p_suspended,p_reason
  );
  insert into public.admin_audit_log(
    admin_id,action,target_type,target_id,details,created_at
  ) values(v_actor,'creator_account_access_change','profile',p_target_user_id,
    jsonb_build_object('suspended',p_suspended,
      'creator_elevation_id',p_creator_elevation_id)::text,now());
end
$$;


--
-- Name: creator_set_maintenance_exempt(text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_set_maintenance_exempt(p_target_user_id text, p_exempt boolean, p_creator_elevation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id();
begin
  if not public.creator_has_elevation(
    p_creator_elevation_id,'all_sensitive'
  ) then raise exception 'Recent Creator authentication required'; end if;
  if not exists(select 1 from public.profiles
    where user_id=p_target_user_id and role<>'creator') then
    raise exception 'Target account not found or protected'; end if;
  update public.profiles set maintenance_exempt=p_exempt,
    updated_by=v_actor,updated_at=now() where user_id=p_target_user_id;
  insert into public.admin_audit_log(
    admin_id,action,target_type,target_id,details,created_at
  ) values(v_actor,'creator_maintenance_exception','profile',p_target_user_id,
    jsonb_build_object('exempt',p_exempt,
      'creator_elevation_id',p_creator_elevation_id)::text,now());
end
$$;


