-- Name: creator_set_team_role(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_set_team_role(p_target_user_id text, p_new_role text, p_state text DEFAULT NULL::text, p_lga text DEFAULT NULL::text, p_module text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  raise exception 'Recent Creator authentication required';
end
$$;


--
-- Name: creator_set_team_role(text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_set_team_role(p_target_user_id text, p_new_role text, p_state text, p_lga text, p_module text, p_creator_elevation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_target public.profiles;
  v_state text:=nullif(btrim(coalesce(p_state,'')),'');
  v_lga text:=nullif(btrim(coalesce(p_lga,'')),'');
  v_domain text:=public.canonical_staff_domain(p_module);
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.role<>'creator'
     or not public.current_actor_has_workspace('creator',null) then
    raise exception 'Creator authority required';
  end if;
  if not public.creator_has_elevation(p_creator_elevation_id,'staff_authority') then
    raise exception 'Recent Creator authentication required';
  end if;
  select * into v_target from public.profiles
  where user_id=p_target_user_id for update;
  if v_target.user_id is null then raise exception 'Target account not found'; end if;
  if v_target.user_id=v_actor.user_id or v_target.role='creator' then
    raise exception 'Creator authority cannot be modified here';
  end if;
  if p_new_role not in('admin','staff','user') then raise exception 'Invalid team role'; end if;
  if p_new_role in('admin','staff') and (v_state is null or v_lga is null) then
    raise exception 'State and LGA are required';
  end if;
  if p_new_role='staff' and v_domain is null then
    raise exception 'A valid Staff work area is required';
  end if;

  update public.workspace_role_assignments
  set status='revoked',revoked_by=v_actor.user_id,revoked_at=now(),updated_at=now()
  where user_id=p_target_user_id and status='active'
    and workspace_role in(
      'staff','admin','property_operations','field_operations',
      'worker_operations','finance_operations','security_operations','support'
    );
  update public.staff_permissions set is_active=false,revoked_at=now()
  where staff_id=p_target_user_id and is_active;

  if p_new_role='user' then
    update public.profiles set role='user',assigned_state=null,assigned_lga=null,
      scope=null,updated_by=v_actor.user_id,updated_at=now()
    where user_id=p_target_user_id;
  else
    update public.profiles set role=p_new_role,assigned_state=v_state,
      assigned_lga=v_lga,scope='local',updated_by=v_actor.user_id,updated_at=now()
    where user_id=p_target_user_id;
    insert into public.workspace_role_assignments(
      user_id,workspace_role,scope_type,scope_state,scope_lga,status,
      granted_by,granted_at,created_at,updated_at
    ) values(
      p_target_user_id,p_new_role,'state',v_state,v_lga,'active',
      v_actor.user_id,now(),now(),now()
    ) on conflict(user_id,workspace_role) where status='active' do update set
      scope_type='state',scope_state=excluded.scope_state,
      scope_lga=excluded.scope_lga,granted_by=excluded.granted_by,
      granted_at=now(),updated_at=now();
    if p_new_role='staff' then
      perform public.manage_staff_permission(
        p_target_user_id,v_domain,true,p_creator_elevation_id
      );
    end if;
  end if;

  insert into public.audit_logs(
    action,target_type,target_id,details,admin_id,admin_email
  ) values(
    'ROLE_CHANGE','profiles',p_target_user_id,jsonb_build_object(
      'old_role',v_target.role,'new_role',p_new_role,'assigned_state',v_state,
      'assigned_lga',v_lga,'staff_work_area',case when p_new_role='staff'
        then v_domain else null end,'authority_model','creator_step_up'
    )::text,v_actor.user_id,v_actor.email
  );
  return true;
end
$$;


--
-- Name: creator_set_worker_pro_setting(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_set_worker_pro_setting(p_key text, p_value text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_actor public.profiles;
  v_value text:=btrim(coalesce(p_value,''));
  v_monthly_price numeric:=0;
  v_yearly_price numeric:=0;
  v_terms text:='';
  v_terms_content text:='';
  v_monthly_plan text:='';
  v_yearly_plan text:='';
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and role='creator'
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor is null then raise exception 'Creator access required'; end if;
  if p_key not in(
    'worker_pro_monthly_price_ngn','worker_pro_yearly_price_ngn',
    'worker_pro_sales_enabled','worker_pro_apple_product_id',
    'worker_pro_apple_yearly_product_id','worker_pro_google_product_id',
    'worker_pro_google_yearly_product_id','worker_pro_web_paystack_plan_code',
    'worker_pro_web_paystack_yearly_plan_code','worker_pro_terms_version',
    'worker_pro_terms_content','worker_pro_support_response_hours',
    'worker_pro_payment_grace_days','worker_pro_product_name',
    'worker_pro_product_tagline','worker_featured_sales_enabled',
    'worker_featured_slot_count'
  ) then raise exception 'This setting is not part of the paid Worker plan'; end if;

  if p_key in('worker_pro_monthly_price_ngn','worker_pro_yearly_price_ngn') then
    if v_value !~ '^\d+(\.\d{1,2})?$' or v_value::numeric<0 or v_value::numeric>10000000 then
      raise exception 'Plan price must be between 0 and 10,000,000 NGN';
    end if;
  elsif p_key='worker_pro_support_response_hours' then
    if v_value !~ '^\d+$' or v_value::integer<1 or v_value::integer>168 then
      raise exception 'Support response target must be between 1 and 168 hours';
    end if;
  elsif p_key='worker_pro_payment_grace_days' then
    if v_value !~ '^\d+$' or v_value::integer<0 or v_value::integer>14 then
      raise exception 'Failed-payment grace must be between 0 and 14 days';
    end if;
  elsif p_key='worker_featured_slot_count' then
    if v_value !~ '^\d+$' or v_value::integer<0 or v_value::integer>6 then
      raise exception 'Featured Worker slots must be between 0 and 6';
    end if;
  elsif p_key='worker_featured_sales_enabled' then
    if lower(v_value) not in('true','false') then raise exception 'Featured setting must be true or false'; end if;
    if lower(v_value)='true' then
      if not public._legal_launch_gate_is_approved('worker_featured_placement') then
        raise exception 'Sponsored Worker placement has no current legal launch approval';
      end if;
      if not exists(
        select 1 from public.platform_settings
        where key='worker_marketplace_launch_enabled' and is_active=true
          and lower(value) in('true','1','yes','on')
      ) then raise exception 'Open the legally approved Worker marketplace before Featured Workers'; end if;
    end if;
  elsif p_key='worker_pro_sales_enabled' then
    if lower(v_value) not in('true','false') then raise exception 'Sales setting must be true or false'; end if;
    if lower(v_value)='true' then
      if not public._legal_launch_gate_is_approved('worker_pro_web_sales') then
        raise exception 'Paid Worker plan web sales have no current legal launch approval';
      end if;
      select coalesce(nullif(value,'')::numeric,0) into v_monthly_price from public.platform_settings where key='worker_pro_monthly_price_ngn';
      select coalesce(nullif(value,'')::numeric,0) into v_yearly_price from public.platform_settings where key='worker_pro_yearly_price_ngn';
      select coalesce(value,'') into v_monthly_plan from public.platform_settings where key='worker_pro_web_paystack_plan_code';
      select coalesce(value,'') into v_yearly_plan from public.platform_settings where key='worker_pro_web_paystack_yearly_plan_code';
      select coalesce(value,'') into v_terms from public.platform_settings where key='worker_pro_terms_version';
      select coalesce(value,'') into v_terms_content from public.platform_settings where key='worker_pro_terms_content';
      if not(
        (v_monthly_price>0 and nullif(btrim(v_monthly_plan),'') is not null)
        or (v_yearly_price>0 and nullif(btrim(v_yearly_plan),'') is not null)
      ) then raise exception 'Configure and sync at least one web billing plan before enabling sales'; end if;
      if nullif(btrim(v_terms),'') is null then raise exception 'Publish a paid plan terms version before enabling sales'; end if;
      if length(btrim(v_terms_content))<100 then raise exception 'Publish complete paid plan subscription terms before enabling sales'; end if;
    end if;
  elsif p_key in(
    'worker_pro_apple_product_id','worker_pro_apple_yearly_product_id',
    'worker_pro_google_product_id','worker_pro_google_yearly_product_id',
    'worker_pro_web_paystack_plan_code','worker_pro_web_paystack_yearly_plan_code'
  ) then
    if v_value<>'' and v_value !~ '^[A-Za-z0-9._-]{3,160}$' then
      raise exception 'Invalid subscription product or plan identifier';
    end if;
  elsif p_key='worker_pro_terms_version' and length(v_value)>100 then
    raise exception 'Paid plan terms version is too long';
  elsif p_key='worker_pro_terms_content'
    and (v_value<>'' and (length(v_value)<100 or length(v_value)>50000)) then
      raise exception 'Paid plan subscription terms must be between 100 and 50,000 characters';
  elsif p_key='worker_pro_product_name' then
    if length(v_value)<3 or length(v_value)>40 then
      raise exception 'Paid Worker plan name must be between 3 and 40 characters';
    end if;
  elsif p_key='worker_pro_product_tagline' then
    if length(v_value)<10 or length(v_value)>140 then
      raise exception 'Paid Worker plan tagline must be between 10 and 140 characters';
    end if;
  end if;

  if p_key in('worker_pro_monthly_price_ngn','worker_pro_yearly_price_ngn') and exists(
    select 1 from public.platform_settings where key=p_key and value is distinct from v_value
  ) then
    update public.platform_settings set value='false',updated_at=now()
    where key='worker_pro_sales_enabled';
  end if;

  update public.platform_settings set value=v_value,updated_at=now()
  where key=p_key and category='worker_pro' and editable=true;
  if not found then raise exception 'Paid Worker plan setting is unavailable'; end if;

  if exists(
    select 1 from public.platform_settings
    where key='worker_pro_sales_enabled' and lower(value)='true' and is_active=true
  ) then
    select coalesce(nullif(value,'')::numeric,0) into v_monthly_price from public.platform_settings where key='worker_pro_monthly_price_ngn';
    select coalesce(nullif(value,'')::numeric,0) into v_yearly_price from public.platform_settings where key='worker_pro_yearly_price_ngn';
    select coalesce(value,'') into v_monthly_plan from public.platform_settings where key='worker_pro_web_paystack_plan_code';
    select coalesce(value,'') into v_yearly_plan from public.platform_settings where key='worker_pro_web_paystack_yearly_plan_code';
    select coalesce(value,'') into v_terms from public.platform_settings where key='worker_pro_terms_version';
    select coalesce(value,'') into v_terms_content from public.platform_settings where key='worker_pro_terms_content';
    if not public._legal_launch_gate_is_approved('worker_pro_web_sales')
       or not(
         (v_monthly_price>0 and nullif(btrim(v_monthly_plan),'') is not null)
         or (v_yearly_price>0 and nullif(btrim(v_yearly_plan),'') is not null)
       )
       or nullif(btrim(v_terms),'') is null
       or length(btrim(v_terms_content))<100 then
      raise exception 'Disable paid plan web sales before clearing its approval, terms or final enabled plan';
    end if;
  end if;
  return true;
end;
$_$;


--
-- Name: creator_update_listing(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_update_listing(p_listing_id uuid, p_changes jsonb) RETURNS public.listings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_row public.listings; v_images text[];
begin
  select * into v_actor from public.profiles where auth_id=auth.uid()::text limit 1;
  if v_actor is null or v_actor.role not in ('creator','admin') or coalesce(v_actor.deleted,false) or coalesce(v_actor.suspended,false) or coalesce(v_actor.banned,false) then
    raise exception 'Creator or Admin access required';
  end if;
  if p_changes ? 'images' then
    select coalesce(array_agg(value),array[]::text[]) into v_images
    from jsonb_array_elements_text(coalesce(p_changes->'images','[]'::jsonb));
  end if;
  update public.listings set
    title=case when p_changes ? 'title' then nullif(btrim(p_changes->>'title'),'') else title end,
    description=case when p_changes ? 'description' then nullif(btrim(p_changes->>'description'),'') else description end,
    price=case when p_changes ? 'price' then (p_changes->>'price')::numeric else price end,
    images=case when p_changes ? 'images' then v_images else images end,
    updated_at=now()
  where id=p_listing_id and deleted_at is null
  returning * into v_row;
  if v_row.id is null then raise exception 'Listing not found'; end if;
  if v_row.title is null or v_row.price<=0 then raise exception 'A title and valid price are required'; end if;
  return v_row;
end
$$;


--
-- Name: credit_wallet(uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.credit_wallet(p_wallet_id uuid, p_amount numeric, p_description text, p_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_wallet RECORD;
  v_caller TEXT;
  v_caller_role TEXT;
  v_new_balance NUMERIC;
BEGIN
  -- ── AUTH: Identify caller ──
  SELECT user_id, role INTO v_caller, v_caller_role
  FROM profiles WHERE auth_id = auth.uid()::text;

  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
  END IF;

  -- ── AUTHORIZATION: staff/admin/creator only ──
  IF v_caller_role NOT IN ('staff','admin','creator') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  SELECT * INTO v_wallet FROM wallets WHERE id = p_wallet_id FOR UPDATE;

  IF v_wallet IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Wallet not found');
  END IF;

  IF v_wallet.is_frozen THEN
    RETURN jsonb_build_object('success', false, 'error', 'Wallet is frozen');
  END IF;

  v_new_balance := v_wallet.available_balance + p_amount;

  UPDATE wallets SET
    available_balance = v_new_balance,
    updated_at = NOW()
  WHERE id = p_wallet_id;

  INSERT INTO wallet_transactions (
    user_id, transaction_type, amount, description,
    reference_id, reference_type, balance_after
  ) VALUES (
    v_wallet.owner_id, 'credit', p_amount, p_description,
    p_reference, 'wallet_credit', v_new_balance
  );

  RETURN jsonb_build_object('success', true, 'new_balance', v_new_balance);
END;
$$;


--
-- Name: current_accommodation_arrival_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_accommodation_arrival_policy() RETURNS TABLE(policy_version_id uuid, default_hours integer, minimum_hours integer, maximum_hours integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select policy.policy_version_id,
    (policy.value->>'default_hours')::integer,
    (policy.value->>'minimum_hours')::integer,
    (policy.value->>'maximum_hours')::integer
  from public.creator_policy_versions policy
  where policy.policy_key='accommodation_arrival_issue_window'
    and policy.scope_type='global' and policy.scope_key='*'
    and policy.status='active' and policy.effective_from<=now()
    and (policy.effective_until is null or policy.effective_until>now())
  order by policy.effective_from desc,policy.version desc
  limit 1
$$;


--
-- Name: current_actor_can_access_listing_ref(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_can_access_listing_ref(p_listing_ref text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor public.profiles; v_listing public.listings;
BEGIN
  SELECT * INTO v_actor FROM public.profiles
  WHERE auth_id=auth.uid()::text AND COALESCE(deleted,false)=false
    AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RETURN false; END IF;
  IF v_actor.role='creator' THEN RETURN true; END IF;
  IF v_actor.role NOT IN ('admin','staff') THEN RETURN false; END IF;
  SELECT * INTO v_listing FROM public.listings
  WHERE id::text=p_listing_ref OR listing_id=p_listing_ref LIMIT 1;
  IF v_listing IS NULL THEN RETURN false; END IF;
  RETURN public.current_actor_in_scope(v_listing.state,v_listing.city);
END;
$$;


--
-- Name: current_actor_can_access_operational_conversation(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_can_access_operational_conversation(p_conversation_id uuid, p_require_assignment boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conversation public.partner_support_conversations;
  v_case public.operational_cases;
  v_domain text;
  v_state text;
  v_assigned_user_id text;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then return false; end if;

  select * into v_conversation
  from public.partner_support_conversations
  where id=p_conversation_id;
  if v_conversation.id is null then return false; end if;

  if v_actor.user_id=v_conversation.partner_id then
    return not p_require_assignment;
  end if;

  if v_conversation.operational_case_id is not null then
    select * into v_case from public.operational_cases
    where operational_case_id=v_conversation.operational_case_id;
  end if;
  v_domain:=coalesce(
    v_case.owning_domain,
    public.canonical_operational_domain(v_conversation.channel_kind)
  );
  select coalesce(nullif(btrim(v_case.state_scope),''),nullif(btrim(p.state),''))
  into v_state
  from public.profiles p where p.user_id=v_conversation.partner_id;
  v_assigned_user_id:=coalesce(
    v_case.assigned_user_id,
    v_conversation.assigned_staff_id,
    v_conversation.assigned_field_officer_id
  );

  if p_require_assignment and v_assigned_user_id is distinct from v_actor.user_id then
    return false;
  end if;

  if public.current_actor_has_workspace('creator',null) then return true; end if;

  if v_actor.role='admin' then
    return nullif(btrim(coalesce(v_state,'')),'') is not null
      and public.current_actor_has_workspace('admin',v_state);
  end if;

  if v_actor.role='staff' then
    return v_domain is not null
      and nullif(btrim(coalesce(v_state,'')),'') is not null
      and public.current_actor_has_workspace(v_domain,v_state);
  end if;
  return false;
end
$$;


--
-- Name: current_actor_can_access_reservation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_can_access_reservation(p_reservation_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_listing_ref text;
BEGIN
  SELECT listing_id INTO v_listing_ref FROM public.reservations WHERE id=p_reservation_id LIMIT 1;
  IF v_listing_ref IS NULL THEN RETURN false; END IF;
  RETURN public.current_actor_can_access_listing_ref(v_listing_ref);
END;
$$;


--
-- Name: current_actor_can_access_worker_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_can_access_worker_booking(p_booking_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor public.profiles; v_worker public.profiles;
BEGIN
  SELECT * INTO v_actor FROM public.profiles
  WHERE auth_id=auth.uid()::text AND COALESCE(deleted,false)=false
    AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RETURN false; END IF;
  IF v_actor.role='creator' THEN RETURN true; END IF;
  IF v_actor.role NOT IN ('admin','staff') THEN RETURN false; END IF;
  SELECT w.* INTO v_worker FROM public.worker_bookings b
  JOIN public.profiles w ON w.user_id=b.worker_id WHERE b.id=p_booking_id LIMIT 1;
  IF v_worker IS NULL THEN RETURN false; END IF;
  RETURN public.current_actor_in_scope(v_worker.state,COALESCE(v_worker.local_government,v_worker.city));
END;
$$;


--
-- Name: current_actor_can_read_hotel_booking_record(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_can_read_hotel_booking_record(p_hotel_id integer, p_customer_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_hotel public.hotels;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then return false; end if;
  if p_customer_id=v_actor.user_id or v_actor.role='creator' then return true; end if;
  select * into v_hotel from public.hotels where hotel_id=p_hotel_id;
  if v_hotel.hotel_id is null then return false; end if;
  return public.hotel_actor_has_capability(p_hotel_id,'stay.read')
    or (((v_actor.role='admin')
      or (v_actor.role='staff' and public.current_staff_has_permission('operations')))
      and public.current_actor_in_scope(v_hotel.state,v_hotel.city));
end;
$$;


--
-- Name: current_actor_can_read_hotel_record(integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_can_read_hotel_record(p_hotel_id integer, p_owner_id text, p_state text, p_city text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then return false; end if;
  return p_owner_id=v_actor.user_id
    or v_actor.role='creator'
    or public.hotel_actor_has_any_capability(p_hotel_id)
    or (((v_actor.role='admin')
      or (v_actor.role='staff' and public.current_staff_has_permission('operations')))
      and public.current_actor_in_scope(p_state,p_city));
end;
$$;


--
-- Name: current_actor_has_hotel_capability(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_has_hotel_capability(p_hotel_id integer, p_capability text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(p_capability=any(public.current_actor_hotel_capabilities(p_hotel_id)),false);
$$;


--
-- Name: current_actor_has_personal_workspace(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_has_personal_workspace() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1
    from public.profiles profile
    where profile.auth_id=(select auth.uid())::text
      and profile.account_kind='consumer'
      and not coalesce(profile.deleted,false)
      and not coalesce(profile.suspended,false)
      and not coalesce(profile.banned,false)
  );
$$;


--
-- Name: current_actor_has_workspace(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_has_workspace(p_workspace text, p_state text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1
    from public.profiles profile
    where profile.auth_id=(select auth.uid())::text
      and not coalesce(profile.deleted,false)
      and not coalesce(profile.suspended,false)
      and not coalesce(profile.banned,false)
      and (
        profile.role=p_workspace
        or exists(
          select 1
          from public.workspace_role_assignments assignment
          where assignment.user_id=profile.user_id
            and assignment.workspace_role=p_workspace
            and assignment.status='active'
            and (
              p_state is null
              or assignment.scope_type='global'
              or public.wehouse_state_key(assignment.scope_state)=public.wehouse_state_key(p_state)
            )
        )
      )
  );
$$;


--
-- Name: current_actor_has_workspace_role(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_has_workspace_role(p_role text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select public.user_has_active_workspace(public.current_profile_user_id(),p_role);
$$;


--
-- Name: current_actor_hotel_capabilities(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_hotel_capabilities(p_hotel_id integer) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  with actor as (select public.current_profile_user_id() as user_id)
  select case
    when hotel.owner_id=actor.user_id then public.hotel_default_capabilities('owner')
    else coalesce(member.capabilities,array[]::text[])
  end
  from public.hotels hotel
  cross join actor
  left join public.hotel_team_members member
    on member.hotel_id=hotel.hotel_id
   and member.member_user_id=actor.user_id
   and member.status='active'
  where hotel.hotel_id=p_hotel_id
    and actor.user_id is not null
    and (hotel.owner_id=actor.user_id or member.id is not null)
  limit 1
$$;


--
-- Name: current_actor_hotel_role(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_hotel_role(p_hotel_id integer) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case when h.owner_id=p.user_id then 'owner' else tm.hotel_role end
  from public.profiles p join public.hotels h on h.hotel_id=p_hotel_id
  left join public.hotel_team_members tm on tm.hotel_id=h.hotel_id and tm.member_user_id=p.user_id and tm.status='active'
  where p.auth_id=auth.uid()::text and not coalesce(p.deleted,false) and not coalesce(p.suspended,false) and not coalesce(p.banned,false)
    and (h.owner_id=p.user_id or tm.id is not null) limit 1
$$;


--
-- Name: current_actor_in_scope(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_in_scope(p_state text, p_lga text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then return false; end if;
  if v_actor.role='creator' then return true; end if;
  if v_actor.role not in('admin','staff') then return false; end if;
  -- p_lga is retained for migration/RPC compatibility and dispatch UIs only.
  return nullif(public.wehouse_state_key(v_actor.assigned_state),'') is not null
    and public.wehouse_state_key(v_actor.assigned_state)
      =public.wehouse_state_key(p_state);
end
$$;


--
-- Name: current_oversight_can_review_worker(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_oversight_can_review_worker(p_worker_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_worker public.profiles;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and role in('creator','admin')
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null then return false; end if;
  select * into v_worker from public.profiles
  where user_id=p_worker_id and public.user_has_active_workspace(user_id,'worker') limit 1;
  if v_worker.user_id is null then return false; end if;
  return v_actor.role='creator' or public.wehouse_state_key(v_worker.state)
    =public.wehouse_state_key(v_actor.assigned_state);
end
$$;


--
-- Name: current_profile_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_profile_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ SELECT p.role FROM public.profiles p WHERE p.auth_id=auth.uid()::text AND COALESCE(p.deleted,false)=false AND COALESCE(p.suspended,false)=false AND COALESCE(p.banned,false)=false LIMIT 1 $$;


--
-- Name: current_profile_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_profile_user_id() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ SELECT p.user_id FROM public.profiles p WHERE p.auth_id=auth.uid()::text AND COALESCE(p.deleted,false)=false AND COALESCE(p.suspended,false)=false AND COALESCE(p.banned,false)=false LIMIT 1 $$;


--
-- Name: current_staff_can_review_worker(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_staff_can_review_worker(p_worker_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_worker public.profiles;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and role='staff'
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null
     or not public.current_staff_has_permission('worker_operations') then
    return false;
  end if;
  select * into v_worker from public.profiles
  where user_id=p_worker_id and public.user_has_active_workspace(user_id,'worker') limit 1;
  return v_worker.user_id is not null
    and public.wehouse_state_key(v_worker.state)
      =public.wehouse_state_key(v_actor.assigned_state);
end
$$;


--
-- Name: current_staff_has_permission(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_staff_has_permission(p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  with actor as (
    select p.* from public.profiles p
    where p.auth_id=(select auth.uid())::text
      and not coalesce(p.deleted,false)
      and not coalesce(p.suspended,false)
      and not coalesce(p.banned,false)
    limit 1
  ), requested as (
    select public.canonical_staff_domain(p_permission) domain
  )
  select exists(
    select 1 from actor a,requested r
    where a.role='staff' and r.domain is not null
      and nullif(btrim(coalesce(a.assigned_state,'')),'') is not null
      and nullif(btrim(coalesce(a.assigned_lga,'')),'') is not null
      and exists(
        select 1 from public.workspace_role_assignments w
        where w.user_id=a.user_id and w.workspace_role=r.domain
          and w.status='active'
      )
  ) or exists(
    select 1 from actor a
    where a.role in('admin','creator')
  )
$$;


--
-- Name: current_user_is_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_is_staff() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.auth_id=auth.uid()::text AND p.role IN ('staff','admin','creator') AND COALESCE(p.deleted,false)=false AND COALESCE(p.suspended,false)=false AND COALESCE(p.banned,false)=false) $$;


--
-- Name: customer_confirm_completion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_confirm_completion(p_booking_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles; v_booking public.worker_bookings;
  v_protection public.payment_protection_transactions; v_from text;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Active Personal account required';
  end if;
  select * into v_booking from public.worker_bookings where id=p_booking_id for update;
  if v_booking.id is null or v_booking.user_id<>v_actor.user_id then
    raise exception 'Job not found';
  end if;
  if v_booking.status='approved_released' then return true; end if;
  if v_booking.status<>'completed_pending_approval'
    or coalesce(v_booking.canonical_job_state,'')<>'completion_marked' then
    raise exception 'Worker has not marked this job complete';
  end if;
  if v_booking.risk_flag or v_booking.payment_conflict or v_booking.chargeback_open
    or exists(select 1 from public.worker_user_blocks b
      where (b.blocker_user_id=v_booking.user_id and b.blocked_user_id=v_booking.worker_id)
         or (b.blocker_user_id=v_booking.worker_id and b.blocked_user_id=v_booking.user_id))
    or exists(select 1 from public.operational_cases c
      where c.subject_type='worker_job' and c.subject_id=v_booking.id::text
        and c.status not in('resolved','closed')) then
    raise exception 'This job needs controlled WeHouse review before release';
  end if;
  select * into v_protection from public.payment_protection_transactions
  where id=v_booking.payment_protection_id for update;
  if v_protection.id is null or v_protection.protection_state not in('protected','release_eligible') then
    raise exception 'Worker Payment Protection is not releasable';
  end if;
  if v_protection.protection_state='protected' then
    insert into public.payment_protection_transitions(
      payment_protection_id,from_state,to_state,event_type,event_key,
      actor_user_id,actor_type,metadata
    ) values(v_protection.id,'protected','release_eligible',
      'customer_confirmed_completion','worker-customer-release-eligible:'||p_booking_id,
      v_actor.user_id,'customer',jsonb_build_object('worker_booking_id',p_booking_id))
    on conflict(event_key) do nothing;
    update public.payment_protection_transactions set protection_state='release_eligible',
      status='release_eligible',release_eligible_at=now(),updated_at=now()
    where id=v_protection.id and protection_state='protected';
  end if;
  v_from:=v_booking.canonical_job_state;
  update public.worker_bookings set canonical_job_state='completed',user_approved=true,
    completed_at=coalesce(completed_at,now()),
    help_until=coalesce(help_until,now()+interval '3 days'),
    review_edit_until=coalesce(review_edit_until,now()+interval '48 hours'),
    updated_at=now() where id=p_booking_id;
  insert into public.worker_job_transitions(
    worker_booking_id,from_state,to_state,event_type,event_key,actor_user_id,
    actor_type,policy_version_id,metadata
  ) values(p_booking_id,v_from,'completed','customer_confirmed_completion',
    'worker-customer-completed:'||p_booking_id,v_actor.user_id,'customer',
    v_booking.policy_version_id,jsonb_build_object('release_queued',true))
  on conflict(event_key) do nothing;
  insert into public.financial_action_outbox(
    action_type,subject_type,subject_id,payment_protection_id,amount,
    idempotency_key,metadata
  ) select 'release_worker_payment','worker_job',p_booking_id::text,v_protection.id,
    v_protection.amount_total-v_protection.released_amount-v_protection.refunded_amount,
    'release_worker_payment:'||p_booking_id,
    jsonb_build_object('trigger','customer_confirmed_completion','customer_id',v_actor.user_id)
  where v_protection.amount_total-v_protection.released_amount-v_protection.refunded_amount>0
  on conflict(idempotency_key) do nothing;
  return true;
end
$$;


--
-- Name: customer_confirm_payment(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_confirm_payment(p_booking_id uuid, p_user_id text, p_paystack_ref text, p_paystack_tx_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller TEXT;
  v_caller_role TEXT;
BEGIN
  SELECT user_id, role INTO v_caller, v_caller_role
  FROM profiles WHERE auth_id = auth.uid()::text;

  IF v_caller IS NULL THEN RETURN FALSE; END IF;

  IF v_caller != p_user_id AND v_caller_role NOT IN ('staff','admin','creator') THEN
    RETURN FALSE;
  END IF;

  -- Require server-verified payment reference
  IF NOT EXISTS (
    SELECT 1 FROM verified_paystack_references WHERE paystack_reference = p_paystack_ref
  ) THEN
    RETURN FALSE;
  END IF;

  UPDATE worker_bookings SET
    status = 'confirmed',
    paystack_reference = p_paystack_ref,
    paystack_transaction_id = p_paystack_tx_id,
    updated_at = NOW()
  WHERE id = p_booking_id AND user_id = p_user_id AND status = 'waiting_payment';

  RETURN FOUND;
END;
$$;


--
-- Name: customer_raise_dispute(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_raise_dispute(p_booking_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles; v_booking public.worker_bookings;
  v_protection public.payment_protection_transactions; v_from text; v_case jsonb;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Active Personal account required';
  end if;
  if length(btrim(coalesce(p_reason,'')))<5 then raise exception 'Explain what needs review'; end if;
  select * into v_booking from public.worker_bookings where id=p_booking_id for update;
  if v_booking.id is null or v_booking.user_id<>v_actor.user_id
    or v_booking.status not in('confirmed','in_progress','completed_pending_approval') then
    raise exception 'Job is not eligible for review';
  end if;
  select * into v_protection from public.payment_protection_transactions
  where id=v_booking.payment_protection_id for update;
  if v_protection.id is null or v_protection.protection_state not in('protected','release_eligible','disputed') then
    raise exception 'Worker Payment Protection is unavailable';
  end if;
  if v_protection.protection_state<>'disputed' then
    insert into public.payment_protection_transitions(
      payment_protection_id,from_state,to_state,event_type,event_key,
      actor_user_id,actor_type,reason,metadata
    ) values(v_protection.id,v_protection.protection_state,'disputed',
      'customer_requested_job_review','worker-disputed:'||p_booking_id,
      v_actor.user_id,'customer',btrim(p_reason),jsonb_build_object('worker_booking_id',p_booking_id))
    on conflict(event_key) do nothing;
    update public.payment_protection_transactions set protection_state='disputed',
      status='disputed',updated_at=now() where id=v_protection.id;
  end if;
  v_from:=coalesce(v_booking.canonical_job_state,
    case v_booking.status when 'confirmed' then 'confirmed' when 'in_progress' then 'in_progress'
      else 'completion_marked' end);
  update public.worker_bookings set status='disputed',canonical_job_state='disputed',
    dispute_reason=btrim(p_reason),updated_at=now() where id=p_booking_id;
  insert into public.worker_job_transitions(
    worker_booking_id,from_state,to_state,event_type,event_key,actor_user_id,
    actor_type,policy_version_id,metadata
  ) values(p_booking_id,v_from,'disputed','customer_requested_job_review',
    'worker-job-disputed:'||p_booking_id,v_actor.user_id,'customer',
    v_booking.policy_version_id,jsonb_build_object('reason',btrim(p_reason)))
  on conflict(event_key) do nothing;
  update public.escrow_transactions set status='disputed',updated_at=now()
  where booking_id=p_booking_id and booking_type='worker_booking'
    and status not in('released','refunded');
  v_case:=public.open_contextual_case_conversation(
    'worker_job_issue','worker_job',p_booking_id::text,btrim(p_reason),
    jsonb_build_object('booking_code',v_booking.booking_code,
      'service_type',v_booking.service_type,'worker_id',v_booking.worker_id,
      'payment_protection_id',v_protection.id)
  );
  return true;
end
$$;


--
-- Name: delete_conversation_message_for_me(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_conversation_message_for_me(p_kind text, p_message_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_conversation uuid;
begin
  v_actor:=public._current_comm_actor();
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_kind='roommate' then
    select conversation_id into v_conversation from public.messages where id=p_message_id;
    if v_conversation is null or not public._can_access_conversation(v_conversation) then raise exception 'Message unavailable'; end if;
    update public.messages set hidden_for=array_append(hidden_for,v_actor.user_id) where id=p_message_id and not(v_actor.user_id=any(hidden_for));
  elsif p_kind='worker' then
    select bm.conversation_id into v_conversation from public.booking_messages bm join public.booking_conversations bc on bc.id=bm.conversation_id where bm.id=p_message_id and v_actor.user_id in(bc.user_id,bc.worker_id);
    if v_conversation is null then raise exception 'Message unavailable'; end if;
    update public.booking_messages set hidden_for=array_append(hidden_for,v_actor.user_id) where id=p_message_id and not(v_actor.user_id=any(hidden_for));
  else raise exception 'Unsupported message type'; end if;
  return true;
end $$;


--
-- Name: delete_my_worker_showcase_post(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_my_worker_showcase_post(p_post_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_worker text:=public.current_profile_user_id();
  v_path text;
begin
  if v_worker is null or not public.current_actor_has_workspace('worker',null) then
    raise exception 'Worker workspace required';
  end if;
  update public.worker_showcase_posts
  set deleted_at=now()
  where id=p_post_id and worker_id=v_worker and deleted_at is null
  returning storage_path into v_path;
  if v_path is null then raise exception 'Work Post not found'; end if;
  return v_path;
end
$$;


