--
-- Name: end_private_call(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_private_call(p_call_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_me text:=public.current_profile_user_id(); v_call public.private_calls;
begin
 select * into v_call from public.private_calls where id=p_call_id for update;
 if v_call is null or v_me not in (v_call.caller_id,v_call.callee_id) then raise exception 'Call not found'; end if;
 if v_call.status in ('ringing','accepted') then update public.private_calls set status=case when v_call.status='ringing' then 'missed' else 'ended' end,ended_at=now() where id=p_call_id; end if;
 return public.get_private_call_details(p_call_id);
end; $$;


--
-- Name: enforce_apartment_reservation_payment_amount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_apartment_reservation_payment_amount() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_expected numeric; v_actual numeric;
begin
  if new.purpose<>'apartment_reservation' or new.status not in ('paid','completed') or old.status in ('paid','completed') then return new; end if;
  select r.amount into v_expected from public.reservations r where r.payment_reference=new.paystack_reference for share;
  if v_expected is null then raise exception 'Apartment reservation payment has no reservation'; end if;
  v_actual:=coalesce(new.verified_amount,new.amount_total,new.amount);
  if round(coalesce(v_actual,0),2)<>round(v_expected,2) then raise exception 'Apartment reservation payment amount mismatch'; end if;
  return new;
end; $$;


--
-- Name: enforce_audited_property_access_before_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_audited_property_access_before_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if (new.assigned_to is distinct from old.assigned_to
      or new.field_officer_id is distinct from old.field_officer_id
      or new.assigned_field_officer_id is distinct from old.assigned_field_officer_id)
     and coalesce(new.assigned_to,new.field_officer_id,new.assigned_field_officer_id) is not null
     and not exists (
       select 1
       from public.audit_logs a
       where a.target_type='inspection_requests'
         and a.target_id=new.id::text
         and a.admin_id=new.access_evidence_verified_by
         and a.action in ('PROPERTY_ACCESS_EVIDENCE_ACCEPTED','PROPERTY_ACCESS_EVIDENCE_OVERRIDDEN')
         and coalesce((a.details::jsonb)->>'decision','accept')='accept'
     ) then
    raise exception 'A matching access-evidence review audit is required before Field Operations assignment';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_chat_message_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_chat_message_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id text;
  v_window interval:=make_interval(mins=>public.message_edit_window_minutes());
begin
  if current_setting('request.jwt.claim.role',true)='service_role' then return new; end if;
  select user_id into v_user_id from public.profiles where auth_id=auth.uid()::text limit 1;
  if v_user_id is null then raise exception 'Authenticated profile required'; end if;

  if tg_table_name='messages' then
    if new.id is distinct from old.id or new.conversation_id is distinct from old.conversation_id or new.sender_id is distinct from old.sender_id or new.created_at is distinct from old.created_at or new.attachments is distinct from old.attachments or new.attachment_types is distinct from old.attachment_types or new.file_url is distinct from old.file_url or new.file_name is distinct from old.file_name or new.file_type is distinct from old.file_type then
      raise exception 'Message metadata cannot be changed';
    end if;
    if new.seen is distinct from old.seen then
      if old.sender_id=v_user_id then raise exception 'You cannot change the read receipt on your own sent message'; end if;
      if old.seen=true or new.seen<>true then raise exception 'Read receipts can only move from unread to read'; end if;
    end if;
    if new.content is distinct from old.content then
      if old.sender_id<>v_user_id then raise exception 'You can only edit your own messages'; end if;
      if now()>old.created_at+v_window then raise exception 'This message can no longer be edited'; end if;
      if nullif(btrim(coalesce(new.content,'')),'') is null and coalesce(array_length(old.attachments,1),0)=0 and nullif(btrim(coalesce(old.file_url,'')),'') is null then raise exception 'Message cannot be empty'; end if;
      new.content:=btrim(coalesce(new.content,''));
      new.edited_at:=now();
    else
      new.edited_at:=old.edited_at;
    end if;
    return new;
  end if;

  if tg_table_name='booking_messages' then
    if new.id is distinct from old.id or new.conversation_id is distinct from old.conversation_id or new.sender_id is distinct from old.sender_id or new.created_at is distinct from old.created_at or new.attachments is distinct from old.attachments then
      raise exception 'Message metadata cannot be changed';
    end if;
    if new.is_read is distinct from old.is_read then
      if old.sender_id=v_user_id then raise exception 'You cannot change the read receipt on your own sent message'; end if;
      if old.is_read=true or new.is_read<>true then raise exception 'Read receipts can only move from unread to read'; end if;
    end if;
    if new.content is distinct from old.content then
      if old.sender_id<>v_user_id then raise exception 'You can only edit your own messages'; end if;
      if now()>old.created_at+v_window then raise exception 'This message can no longer be edited'; end if;
      if nullif(btrim(coalesce(new.content,'')),'') is null and coalesce(array_length(old.attachments,1),0)=0 then raise exception 'Message cannot be empty'; end if;
      new.content:=btrim(coalesce(new.content,''));
      new.edited_at:=now();
    else
      new.edited_at:=old.edited_at;
    end if;
    return new;
  end if;

  return new;
end;
$$;


--
-- Name: enforce_conversation_context_ownership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_conversation_context_ownership() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if old.context_type is distinct from new.context_type
    or old.context_id is distinct from new.context_id then
    raise exception 'Conversation ownership cannot be reassigned';
  end if;

  if old.channel_kind is distinct from new.channel_kind
    and not (
      old.context_type = 'property_inspection'
      and old.channel_kind = 'property_operations'
      and new.channel_kind = 'field_operations'
      and nullif(btrim(coalesce(new.assigned_field_officer_id, '')), '') is not null
    ) then
    raise exception 'Conversation ownership cannot be reassigned';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_hotel_booking_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_hotel_booking_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_actor public.profiles;
  v_hotel public.hotels;
  v_room public.hotel_rooms;
  v_plan public.hotel_rate_plans;
  v_quote jsonb;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if tg_op='INSERT' then
    if v_actor.user_id is null or not public.current_actor_has_personal_workspace() then
      raise exception 'Active Personal account required';
    end if;
    new.user_id:=v_actor.user_id;
    new.status:='pending';
    new.payment_status:='unpaid';
    new.payment_expires_at:=coalesce(
      new.payment_expires_at,now()+interval '30 minutes'
    );
    if new.check_in is null or new.check_out is null
       or new.check_in<=current_date or new.check_out<=new.check_in then
      raise exception 'Choose valid future check-in and check-out dates';
    end if;
    if coalesce(new.guest_count,0)<1 then
      raise exception 'At least one guest is required';
    end if;
    if nullif(btrim(new.guest_name),'') is null
       or nullif(btrim(new.guest_phone),'') is null then
      raise exception 'Guest name and phone are required';
    end if;
    select * into v_hotel from public.hotels
    where hotel_id=new.hotel_id and status='active'
      and approved_at is not null and published_at is not null;
    if v_hotel.hotel_id is null then
      raise exception 'Hotel is not available for booking';
    end if;
    select * into v_room from public.hotel_rooms
    where room_id=new.room_id and hotel_id=new.hotel_id;
    if v_room.room_id is null then
      raise exception 'Room type not found for this hotel';
    end if;
    if new.guest_count>coalesce(v_room.max_guests,2) then
      raise exception 'Guest count exceeds this room type capacity';
    end if;
    if new.rate_plan_id is null then
      select * into v_plan from public.hotel_rate_plans
      where room_id=new.room_id and active
      order by (name='Room only') desc,price_per_night,rate_plan_id limit 1;
      new.rate_plan_id:=v_plan.rate_plan_id;
    else
      select * into v_plan from public.hotel_rate_plans
      where rate_plan_id=new.rate_plan_id and room_id=new.room_id
        and hotel_id=new.hotel_id and active;
    end if;
    if v_plan.rate_plan_id is null then
      raise exception 'Room package is not available';
    end if;
    v_quote:=private.hotel_booking_quote_v2(
      new.room_id,v_plan.rate_plan_id,new.check_in,new.check_out,null,true
    );
    if not coalesce((v_quote->>'available')::boolean,false) then
      raise exception 'This room type is unavailable on %',v_quote->>'blocked_date';
    end if;
    new.total_nights:=(v_quote->>'nights')::integer;
    new.total_price:=(v_quote->>'total_price')::numeric;
    new.rate_plan_name:=v_plan.name;
    new.rate_plan_snapshot:=jsonb_build_object(
      'rate_plan_id',v_plan.rate_plan_id,'name',v_plan.name,
      'description',v_plan.description,'meal_plan',v_plan.meal_plan,
      'payment_timing',v_plan.payment_timing,'refundable',v_plan.refundable,
      'cancellation_hours',v_plan.cancellation_hours,
      'price_per_night',v_plan.price_per_night,
      'included_features',v_plan.included_features
    );
    new.created_at:=coalesce(new.created_at,now());
    new.updated_at:=now();
    return new;
  end if;
  if tg_op='UPDATE' then
    if current_user not in ('anon','authenticated') then
      new.updated_at:=now();
      return new;
    end if;
    if v_actor.user_id is null then raise exception 'Authentication required'; end if;
    if v_actor.role='creator' then
      new.updated_at:=now();
      return new;
    end if;
    if not public.current_actor_has_personal_workspace()
       or old.user_id is distinct from v_actor.user_id then
      raise exception 'Booking owner access required';
    end if;
    if old.status<>'pending' or new.status<>'cancelled'
       or old.payment_status='paid' then
      raise exception 'Customers can only cancel their own unpaid pending booking';
    end if;
    new.hotel_id:=old.hotel_id;
    new.room_id:=old.room_id;
    new.rate_plan_id:=old.rate_plan_id;
    new.rate_plan_name:=old.rate_plan_name;
    new.rate_plan_snapshot:=old.rate_plan_snapshot;
    new.user_id:=old.user_id;
    new.check_in:=old.check_in;
    new.check_out:=old.check_out;
    new.guest_count:=old.guest_count;
    new.total_nights:=old.total_nights;
    new.total_price:=old.total_price;
    new.guest_name:=old.guest_name;
    new.guest_phone:=old.guest_phone;
    new.special_requests:=old.special_requests;
    new.payment_reference:=old.payment_reference;
    new.paid_at:=old.paid_at;
    new.confirmed_at:=old.confirmed_at;
    new.created_at:=old.created_at;
    new.updated_at:=now();
    return new;
  end if;
  return new;
end
$$;


--
-- Name: enforce_hotel_booking_payment_amount(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_hotel_booking_payment_amount() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_expected numeric;v_actual numeric;
begin
 if new.purpose<>'hotel_booking' or new.status not in('paid','completed') or old.status in('paid','completed') then return new;end if;
 select hb.total_price into v_expected from public.hotel_bookings hb where hb.booking_id=new.hotel_booking_id and hb.user_id=coalesce(new.payer_user_id,new.user_id) for share;
 if v_expected is null then raise exception 'Hotel payment has no matching booking';end if;
 v_actual:=coalesce(new.verified_amount,new.amount_total,new.amount);
 if round(coalesce(v_actual,0),2)<>round(v_expected,2) then raise exception 'Hotel payment amount mismatch';end if;
 return new;
end $$;


--
-- Name: enforce_hotel_team_consumer_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_hotel_team_consumer_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists(select 1 from public.profiles p where p.user_id=new.member_user_id and p.account_kind='consumer' and not coalesce(p.deleted,false) and not coalesce(p.suspended,false) and not coalesce(p.banned,false)) then
    raise exception 'Hotel Manager and Hotel Staff must use an active personal WeHouse account';
  end if;
  return new;
end $$;


--
-- Name: enforce_legal_document_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_legal_document_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_body text; v_title text; v_locale text; v_review text;
begin
  if new.policy_key not in('legal_privacy','legal_terms') then return new; end if;
  v_body:=btrim(coalesce(new.value->>'body',''));
  v_title:=btrim(coalesce(new.value->>'title',''));
  v_locale:=btrim(coalesce(new.value->>'locale',''));
  v_review:=btrim(coalesce(new.value->>'review_reference',''));
  if new.scope_type<>'global' or new.scope_key<>'*' then
    raise exception 'Launch legal documents must use global scope';
  end if;
  if not new.public_disclosure then
    raise exception 'Legal documents must be publicly readable';
  end if;
  if char_length(v_title)<3 or char_length(v_body)<500 or v_locale='' then
    raise exception 'Legal document title, locale and complete body are required';
  end if;
  if new.status in('active','scheduled') and (
    new.legal_review_state<>'reviewed' or v_review=''
  ) then
    raise exception 'A reviewed legal document and review reference are required for publication';
  end if;
  return new;
end
$$;


--
-- Name: enforce_listing_caution_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_listing_caution_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_policy jsonb; v_amount numeric:=coalesce(new.security_deposit_amount,0);
begin
  if v_amount<0 then raise exception 'Caution amount cannot be negative'; end if;
  if v_amount=0 then return new; end if;
  if new.sub_type<>'short_let' then
    raise exception 'Caution is available only for Short Let listings';
  end if;
  select p.value into v_policy from public.creator_policy_versions p
  where p.policy_key='short_let_caution_cap'
    and p.scope_type='global' and p.scope_key='*' and p.status='active'
    and p.effective_from<=now()
    and (p.effective_until is null or p.effective_until>now())
  order by p.effective_from desc limit 1;
  if not coalesce((v_policy->>'enabled')::boolean,false)
    or (v_policy->>'maximum_amount') is null
    or v_amount>(v_policy->>'maximum_amount')::numeric then
    raise exception 'Short Let Caution exceeds the active Creator policy';
  end if;
  return new;
end
$$;


--
-- Name: enforce_one_marketplace_workspace(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_one_marketplace_workspace() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.status='active' and new.workspace_role in('worker','property_partner')
    and exists(
      select 1 from public.workspace_role_assignments other
      where other.user_id=new.user_id and other.status='active'
        and other.workspace_role in('worker','property_partner')
        and other.workspace_role<>new.workspace_role
        and other.id<>new.id
    ) then
    raise exception 'Personal accounts may have one professional marketplace workspace at launch';
  end if;
  return new;
end
$$;


--
-- Name: enforce_private_message_encryption_and_block(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_private_message_encryption_and_block() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_peer text;
begin
  if nullif(new.ciphertext,'') is null or nullif(new.encryption_iv,'') is null or new.content <> '[Encrypted message]' then
    raise exception 'Update WeHouse to continue. Private messages must be end-to-end encrypted';
  end if;
  if tg_table_name='messages' then
    select case when c.participant_a=new.sender_id then c.participant_b else c.participant_a end into v_peer
    from public.conversations c where c.id=new.conversation_id and c.conversation_type='roommate' and new.sender_id in(c.participant_a,c.participant_b);
    if v_peer is not null and exists(select 1 from public.roommate_user_blocks b where (b.blocker_user_id=new.sender_id and b.blocked_user_id=v_peer) or (b.blocker_user_id=v_peer and b.blocked_user_id=new.sender_id))
    then raise exception 'This roommate connection is blocked'; end if;
  elsif tg_table_name='booking_messages' then
    select case when c.user_id=new.sender_id then c.worker_id else c.user_id end into v_peer
    from public.booking_conversations c where c.id=new.conversation_id and new.sender_id in(c.user_id,c.worker_id);
    if v_peer is not null and exists(select 1 from public.worker_user_blocks b where (b.blocker_user_id=new.sender_id and b.blocked_user_id=v_peer) or (b.blocker_user_id=v_peer and b.blocked_user_id=new.sender_id))
    then raise exception 'Messages and calls are blocked in this job conversation'; end if;
  end if;
  return new;
end; $$;


--
-- Name: enforce_property_access_before_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_property_access_before_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(new.assigned_field_officer_id,new.field_officer_id,new.assigned_to) is not null
  and (
    coalesce(new.assigned_field_officer_id,new.field_officer_id,new.assigned_to)
      is distinct from coalesce(old.assigned_field_officer_id,old.field_officer_id,old.assigned_to)
    or lower(coalesce(new.status,'')) in ('scheduled','in_progress')
       and lower(coalesce(old.status,'')) not in ('scheduled','in_progress')
  ) and new.access_evidence_status <> 'verified' then
    raise exception 'Operations Admin must approve the private access recording before assigning a Field Officer';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_property_partner_listing_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_property_partner_listing_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_partner_role TEXT;
BEGIN
  IF NEW.partner_id IS NOT NULL AND BTRIM(NEW.partner_id) <> '' THEN
    SELECT role INTO v_partner_role
    FROM public.profiles
    WHERE user_id = NEW.partner_id
    LIMIT 1;

    IF v_partner_role IS NULL THEN RAISE EXCEPTION 'Assigned Property Partner profile was not found'; END IF;
    IF v_partner_role <> 'property_partner' THEN RAISE EXCEPTION 'Assigned listing partner must have property_partner role'; END IF;
    NEW.owner_id := NEW.partner_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_roommate_call_not_blocked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_roommate_call_not_blocked() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user text;
  v_worker text;
begin
  if new.context_type='roommate' and exists(
    select 1 from public.roommate_user_blocks block_row
    where (block_row.blocker_user_id=new.caller_id and block_row.blocked_user_id=new.callee_id)
       or (block_row.blocker_user_id=new.callee_id and block_row.blocked_user_id=new.caller_id)
  ) then
    raise exception 'This roommate connection is blocked';
  elsif new.context_type='worker_booking' then
    select conversation.user_id,conversation.worker_id into v_user,v_worker
    from public.booking_conversations conversation
    where conversation.id=new.context_id;
    if v_user is null
       or not(new.caller_id in (v_user,v_worker) and new.callee_id in (v_user,v_worker)) then
      raise exception 'Worker call participants do not match the booking';
    end if;
    if exists(
      select 1 from public.worker_user_blocks block_row
      where (block_row.blocker_user_id=v_user and block_row.blocked_user_id=v_worker)
         or (block_row.blocker_user_id=v_worker and block_row.blocked_user_id=v_user)
    ) then raise exception 'This service conversation is blocked'; end if;
  end if;
  return new;
end;
$$;


--
-- Name: enforce_roommate_match_not_blocked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_roommate_match_not_blocked() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.roommate_user_blocks b
    where (b.blocker_user_id = new.searcher_id and b.blocked_user_id = new.matched_user_id)
       or (b.blocker_user_id = new.matched_user_id and b.blocked_user_id = new.searcher_id)
  ) then return null; end if;
  return new;
end $$;


--
-- Name: enforce_roommate_message_not_blocked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_roommate_message_not_blocked() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare peer text;
begin
  select case when c.participant_a = new.sender_id then c.participant_b else c.participant_a end
    into peer from public.conversations c
    where c.id = new.conversation_id and c.conversation_type = 'roommate'
      and new.sender_id in (c.participant_a,c.participant_b);
  if peer is not null and exists (
    select 1 from public.roommate_user_blocks b
    where (b.blocker_user_id = new.sender_id and b.blocked_user_id = peer)
       or (b.blocker_user_id = peer and b.blocked_user_id = new.sender_id)
  ) then raise exception 'This roommate connection is blocked'; end if;
  return new;
end $$;


--
-- Name: enqueue_due_canonical_financial_actions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_due_canonical_financial_actions(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_row record;
  v_count integer:=0;
  v_caution integer:=0;
  v_silent integer:=0;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  perform public.activate_due_creator_policy_versions();

  for v_row in
    select caution_claim_id from public.caution_claims
    where status='awaiting_guest_response' and guest_response_due_at<=now()
    order by guest_response_due_at for update skip locked
    limit least(greatest(coalesce(p_limit,100),1),500)
  loop
    perform public.advance_silent_caution_claim_from_service(v_row.caution_claim_id);
    v_silent:=v_silent+1;
  end loop;

  for v_row in
    select r.id from public.reservations r
    where r.stay_type='short_let' and r.caution_payment_protection_id is not null
      and r.completed_at is not null and r.completed_at+interval '24 hours'<=now()
      and not exists(select 1 from public.caution_claims c where c.reservation_id=r.id)
      and not exists(select 1 from public.financial_action_outbox a
        where a.idempotency_key='caution-unclaimed-refund:'||r.id)
    order by r.completed_at for update skip locked
    limit least(greatest(coalesce(p_limit,100),1),500)
  loop
    perform public.release_unclaimed_caution_from_service(v_row.id);
    v_caution:=v_caution+1;
  end loop;

  for v_row in
    select 'release_long_let_payment' action_type,'long_let' subject_type,
      r.id subject_id,r.year_one_rent_protection_id protection_id
    from public.reservations r
    join public.payment_protection_transactions p
      on p.id=r.year_one_rent_protection_id
    where r.stay_type<>'short_let' and r.verified_handover_at is not null
      and r.verified_handover_at+interval '24 hours'<=now()
      and p.protection_state in('protected','release_eligible')
      and not exists(select 1 from public.operational_cases c
        where c.subject_type='long_let' and c.subject_id=r.id
          and c.status not in('resolved','closed'))
    union all
    select 'release_short_let_stay','short_let',r.id,r.stay_payment_protection_id
    from public.reservations r
    join public.payment_protection_transactions p on p.id=r.stay_payment_protection_id
    where r.stay_type='short_let' and r.checked_in_at is not null
      and p.protection_state in('protected','release_eligible')
      and not exists(select 1 from public.operational_cases c
        where c.subject_type='short_let' and c.subject_id=r.id
          and c.status not in('resolved','closed'))
    union all
    select 'release_hotel_stay','hotel',h.booking_id::text,h.payment_protection_id
    from public.hotel_bookings h
    join public.payment_protection_transactions p on p.id=h.payment_protection_id
    where h.checked_in_at is not null
      and p.protection_state in('protected','release_eligible')
      and not exists(select 1 from public.operational_cases c
        where c.subject_type='hotel' and c.subject_id=h.booking_id::text
          and c.status not in('resolved','closed'))
    union all
    select 'release_worker_payment','worker_job',w.id::text,w.payment_protection_id
    from public.worker_bookings w
    join public.payment_protection_transactions p on p.id=w.payment_protection_id
    where w.canonical_job_state='completion_marked'
      and w.release_eligible_at<=now()
      and not w.risk_flag and not w.payment_conflict and not w.chargeback_open
      and p.protection_state in('protected','release_eligible')
      and not exists(select 1 from public.worker_user_blocks b
        where (b.blocker_user_id=w.user_id and b.blocked_user_id=w.worker_id)
           or (b.blocker_user_id=w.worker_id and b.blocked_user_id=w.user_id))
      and not exists(select 1 from public.operational_cases c
        where c.subject_type='worker_job' and c.subject_id=w.id::text
          and c.status not in('resolved','closed'))
    limit least(greatest(coalesce(p_limit,100),1),500)
  loop
    if (select protection_state from public.payment_protection_transactions
        where id=v_row.protection_id)='protected' then
      perform public.transition_payment_protection(
        v_row.protection_id,'release_eligible','lifecycle_release_gate_passed',
        'release-eligible:'||v_row.action_type||':'||v_row.subject_id,
        null,'system',null,null,'{}'::jsonb
      );
    end if;
    if v_row.action_type='release_worker_payment' then
      perform public.transition_worker_job(
        v_row.subject_id::uuid,'completed','controlled_release_window_elapsed',
        'worker-completed:'||v_row.subject_id,null,'system','{}'::jsonb
      );
    end if;
    insert into public.financial_action_outbox(
      action_type,subject_type,subject_id,payment_protection_id,amount,idempotency_key
    ) select
      v_row.action_type,v_row.subject_type,v_row.subject_id,p.id,
      p.amount_total-p.released_amount-p.refunded_amount,
      v_row.action_type||':'||v_row.subject_id
    from public.payment_protection_transactions p where p.id=v_row.protection_id
      and p.amount_total-p.released_amount-p.refunded_amount>0
    on conflict(idempotency_key) do nothing;
    v_count:=v_count+1;
  end loop;
  return jsonb_build_object(
    'release_actions',v_count,'unclaimed_caution_refunds',v_caution,
    'silent_claims_advanced',v_silent
  );
end
$$;


--
-- Name: enqueue_shared_caution_distribution(uuid, text, text, text, numeric, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_shared_caution_distribution(p_shared_payment_group_id uuid, p_action_type text, p_subject_type text, p_subject_id text, p_amount numeric, p_idempotency_prefix text, p_available_at timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_component record;
  v_total_available numeric(12,2);
  v_remaining numeric(12,2):=round(coalesce(p_amount,0),2);
  v_allocated numeric(12,2);
  v_count integer:=0;
  v_index integer:=0;
  v_component_count integer;
begin
  if p_action_type not in(
    'refund_caution_undisputed','refund_caution_balance',
    'release_caution_award','refund_unclaimed_caution'
  ) then raise exception 'Invalid shared Caution action'; end if;
  if v_remaining<=0 then return 0; end if;

  select round(coalesce(sum(available_amount),0),2),count(*)
  into v_total_available,v_component_count
  from(
    select greatest(protection.amount_total-protection.released_amount-
      protection.refunded_amount-coalesce((select sum(action.amount)
        from public.financial_action_outbox action
        where action.payment_protection_id=protection.id
          and action.status in('pending','processing','provider_pending','provider_attention')),0),0)
      available_amount
    from public.shared_payment_protection_components component
    join public.payment_protection_transactions protection
      on protection.id=component.payment_protection_id
    where component.shared_payment_group_id=p_shared_payment_group_id
      and component.component_type='short_let_caution'
  ) available where available_amount>0;
  if v_remaining>v_total_available then
    raise exception 'Shared Caution distribution exceeds the protected balance'; end if;

  for v_component in
    select component.payment_protection_id,component.shared_payment_member_id,
      greatest(protection.amount_total-protection.released_amount-
        protection.refunded_amount-coalesce((select sum(action.amount)
          from public.financial_action_outbox action
          where action.payment_protection_id=protection.id
            and action.status in('pending','processing','provider_pending','provider_attention')),0),0)
        available_amount
    from public.shared_payment_protection_components component
    join public.payment_protection_transactions protection
      on protection.id=component.payment_protection_id
    where component.shared_payment_group_id=p_shared_payment_group_id
      and component.component_type='short_let_caution'
    order by component.shared_payment_member_id
  loop
    continue when v_component.available_amount<=0 or v_remaining<=0;
    v_index:=v_index+1;
    v_allocated:=least(v_remaining,
      case when v_index=v_component_count then v_remaining
        else round(p_amount*v_component.available_amount/v_total_available,2) end,
      v_component.available_amount);
    if v_allocated<=0 then continue; end if;
    insert into public.financial_action_outbox(
      action_type,subject_type,subject_id,payment_protection_id,amount,
      idempotency_key,available_at,metadata
    ) values(
      p_action_type,p_subject_type,p_subject_id,v_component.payment_protection_id,
      v_allocated,p_idempotency_prefix||':'||v_component.payment_protection_id,
      coalesce(p_available_at,now()),jsonb_build_object(
        'shared_payment_group_id',p_shared_payment_group_id,
        'shared_payment_member_id',v_component.shared_payment_member_id,
        'refund_destination',case when p_action_type like 'refund_%'
          then 'original_payment' else null end
      )
    ) on conflict(idempotency_key) do nothing;
    if found then v_count:=v_count+1; end if;
    v_remaining:=v_remaining-v_allocated;
  end loop;
  if v_remaining<>0 then
    raise exception 'Shared Caution distribution did not allocate exactly'; end if;
  return v_count;
end
$$;


--
-- Name: ensure_my_property_partner_wallet(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_my_property_partner_wallet() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_user_id text:=public.current_profile_user_id(); v_wallet_id uuid;
begin
  if v_user_id is null or not public.current_actor_has_workspace('property_partner',null)
    then raise exception 'Property Partner workspace required'; end if;
  insert into public.wallets(
    owner_id,owner_type,available_balance,pending_balance,frozen_balance,total_withdrawn
  ) values(v_user_id,'property_partner',0,0,0,0)
  on conflict(owner_id,owner_type) do nothing;
  select id into v_wallet_id from public.wallets
  where owner_id=v_user_id and owner_type='property_partner';
  return v_wallet_id;
end
$$;


--
-- Name: ensure_my_roommate_conversation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_my_roommate_conversation(p_peer_user_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor public.profiles;
  v_conversation_id uuid;
  v_pair_key text;
begin
  v_actor := public._current_comm_actor();
  if v_actor is null or not public.current_actor_has_personal_workspace()
     or coalesce(v_actor.deleted, false) or coalesce(v_actor.suspended, false) or coalesce(v_actor.banned, false) then
    raise exception 'Active regular user required';
  end if;
  if nullif(btrim(p_peer_user_id), '') is null or p_peer_user_id = v_actor.user_id then
    raise exception 'Roommate connection unavailable';
  end if;
  if not exists (
    select 1
    from public.roommate_search_results mine
    join public.roommate_search_results theirs
      on theirs.searcher_id = mine.matched_user_id
     and theirs.matched_user_id = mine.searcher_id
     and theirs.status = 'accepted'
    where mine.searcher_id = v_actor.user_id
      and mine.matched_user_id = p_peer_user_id
      and mine.status = 'accepted'
  ) then
    raise exception 'Both people must accept before messaging';
  end if;
  if exists (
    select 1 from public.roommate_user_blocks block
    where (block.blocker_user_id = v_actor.user_id and block.blocked_user_id = p_peer_user_id)
       or (block.blocker_user_id = p_peer_user_id and block.blocked_user_id = v_actor.user_id)
  ) then
    raise exception 'This roommate connection is blocked';
  end if;

  v_pair_key := least(v_actor.user_id, p_peer_user_id) || '|' || greatest(v_actor.user_id, p_peer_user_id);
  perform pg_advisory_xact_lock(hashtextextended(v_pair_key, 0));

  select conversation.id into v_conversation_id
  from public.conversations conversation
  where conversation.conversation_type = 'roommate'
    and ((conversation.participant_a = v_actor.user_id and conversation.participant_b = p_peer_user_id)
      or (conversation.participant_b = v_actor.user_id and conversation.participant_a = p_peer_user_id))
  order by (conversation.status = 'active') desc, conversation.created_at
  limit 1;

  if v_conversation_id is null then
    insert into public.conversations(
      participant_a, participant_b, status, conversation_type, subject,
      created_at, last_message_at, unread_a, unread_b
    ) values (
      v_actor.user_id, p_peer_user_id, 'active', 'roommate', 'Roommate Match',
      now(), now(), 0, 0
    ) returning id into v_conversation_id;
  else
    update public.conversations
    set status = 'active'
    where id = v_conversation_id and status is distinct from 'active';
  end if;

  return v_conversation_id;
end;
$$;


--
-- Name: ensure_paid_hotel_stay_conversation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_paid_hotel_stay_conversation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.payment_status = 'paid' and new.status in ('confirmed','checked_in','checked_out','completed') then
    insert into public.hotel_booking_conversations(booking_id,hotel_id,guest_user_id,updated_at)
    values(new.booking_id,new.hotel_id,new.user_id,now())
    on conflict (booking_id) do update set hotel_id = excluded.hotel_id, guest_user_id = excluded.guest_user_id;
  end if;
  return new;
end;
$$;


--
-- Name: establish_private_conversation_key(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.establish_private_conversation_key(p_conversation_kind text, p_conversation_id uuid, p_envelopes jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor text := public.current_profile_user_id(); first_user text; second_user text; envelope_count integer;
begin
  if actor is null then raise exception 'Active WeHouse profile required'; end if;
  if p_conversation_kind='roommate' then
    select participant_a,participant_b into first_user,second_user from public.conversations where id=p_conversation_id and actor in(participant_a,participant_b);
  elsif p_conversation_kind='worker' then
    select user_id,worker_id into first_user,second_user from public.booking_conversations where id=p_conversation_id and actor in(user_id,worker_id);
  else raise exception 'Unsupported private conversation kind'; end if;
  if first_user is null or second_user is null then raise exception 'Conversation access denied'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_conversation_kind||':'||p_conversation_id::text,0));
  if exists(select 1 from public.conversation_key_envelopes where conversation_kind=p_conversation_kind and conversation_id=p_conversation_id) then return false; end if;
  select count(*) into envelope_count from jsonb_array_elements(coalesce(p_envelopes,'[]'::jsonb));
  if envelope_count<>2 then raise exception 'Exactly two participant envelopes are required'; end if;
  if not exists(select 1 from jsonb_array_elements(p_envelopes) e where e->>'recipient_user_id'=first_user)
     or not exists(select 1 from jsonb_array_elements(p_envelopes) e where e->>'recipient_user_id'=second_user)
     or exists(select 1 from jsonb_array_elements(p_envelopes) e where e->>'recipient_user_id' not in(first_user,second_user)) then raise exception 'Envelope recipients must be the conversation participants'; end if;
  insert into public.conversation_key_envelopes(conversation_kind,conversation_id,recipient_user_id,recipient_key_version,sender_ephemeral_public_key_jwk,wrapped_key,wrap_iv)
  select p_conversation_kind,p_conversation_id,e->>'recipient_user_id',(e->>'recipient_key_version')::integer,e->'sender_ephemeral_public_key_jwk',e->>'wrapped_key',e->>'wrap_iv'
  from jsonb_array_elements(p_envelopes) e join public.user_encryption_identities identity on identity.user_id=e->>'recipient_user_id' and identity.key_version=(e->>'recipient_key_version')::integer;
  if not found then raise exception 'Current participant encryption identities are required'; end if;
  if (select count(*) from public.conversation_key_envelopes where conversation_kind=p_conversation_kind and conversation_id=p_conversation_id)<>2 then raise exception 'Both current participant keys are required'; end if;
  return true;
end; $$;


--
-- Name: expire_old_searches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_old_searches() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
                      DECLARE
                        updated_count INTEGER;
                        BEGIN
                          UPDATE roommate_preferences
                            SET search_status = 'expired'
                              WHERE search_status = 'active'
                                  AND search_expires_at < NOW();
                                    GET DIAGNOSTICS updated_count = ROW_COUNT;
                                      RETURN updated_count;
                                      END;
                                      $$;


--
-- Name: expire_overdue_reservations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_overdue_reservations() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_role text;
  v_count integer:=0;
  v_row record;
begin
  if auth.uid() is not null then
    select role into v_role from public.profiles
    where auth_id=auth.uid()::text and coalesce(deleted,false)=false and coalesce(suspended,false)=false and coalesce(banned,false)=false limit 1;
    if v_role<>'creator' then raise exception 'Creator or service execution required'; end if;
  end if;
  for v_row in
    select r.id,r.listing_id,r.status,r.payment_reference,coalesce(r.stay_type,'long_stay') as stay_type
    from public.reservations r
    where coalesce(r.rent_payment_status,'not_started') not in ('paid','upfront_paid')
      and ((r.status='payment_pending' and r.payment_expires_at<now())
        or (r.status in ('reserved','inspection_pending','ready_for_move_in') and r.hold_expires_at<now()))
    for update
  loop
    if v_row.status='payment_pending' and exists(
      select 1 from public.booking_payments bp
      where bp.paystack_reference=v_row.payment_reference and bp.status in ('paid','completed')
    ) then continue; end if;
    update public.reservations
    set status='expired',refund_amount=0,refund_reason='Reservation hold expired',processed_at=now(),updated_at=now()
    where id=v_row.id and coalesce(rent_payment_status,'not_started') not in ('paid','upfront_paid');
    if not found then continue; end if;
    update public.booking_payments set status='expired',updated_at=now()
    where paystack_reference=v_row.payment_reference and status='pending';
    if v_row.stay_type<>'short_let' then
      update public.listings
      set status='available',availability_status='available',reserved_by=null,
          reservation_expiry=null,reservation_fee_paid=false,chat_unlocked=false,current_reservation_id=null,updated_at=now()
      where id::text=v_row.listing_id and current_reservation_id=v_row.id;
    else
      update public.listings
      set reserved_by=null,reservation_expiry=null,occupied_by=null,occupied_at=null,tenancy_ends_at=null,current_reservation_id=null,updated_at=now()
      where id::text=v_row.listing_id and current_reservation_id=v_row.id;
    end if;
    v_count:=v_count+1;
  end loop;
  return v_count;
end;
$$;


--
-- Name: expire_shared_payment_checkout_from_service(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_shared_payment_checkout_from_service(p_group_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_group public.shared_housing_groups; v_component record; v_queued integer:=0;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  select * into v_group from public.shared_housing_groups where id=p_group_id for update;
  if v_group.id is null or v_group.status not in('payment_pending','refunding')
    or v_group.expires_at>now() then return 0; end if;
  if not exists(select 1 from public.shared_housing_members
    where group_id=p_group_id and payment_status='paid') then
    update public.shared_housing_groups set status='expired',updated_at=now() where id=p_group_id;
    update public.shared_payment_groups set status='expired',updated_at=now()
    where shared_payment_group_id=v_group.canonical_group_id;
    update public.reservations set status='expired',canonical_state='expired',updated_at=now()
    where id=v_group.reservation_id and status='payment_pending';
    return 0;
  end if;
  update public.shared_housing_groups set status='refunding',updated_at=now() where id=p_group_id;
  update public.shared_payment_groups set status='refunding',updated_at=now()
  where shared_payment_group_id=v_group.canonical_group_id;
  for v_component in
    select protection.id,protection.amount_total,member.id member_id
    from public.shared_housing_members member
    join public.booking_payments payment on payment.metadata->>'legacy_shared_member_id'=member.id::text
      and payment.metadata->>'checkout_attempt'=v_group.checkout_attempt::text
      and payment.status in('paid','completed')
    join public.payment_protection_transactions protection
      on protection.paystack_reference=payment.paystack_reference
      and protection.protection_state not in('refunded','released','reversed')
    where member.group_id=p_group_id and member.payment_status='paid'
  loop
    insert into public.financial_action_outbox(
      action_type,subject_type,subject_id,payment_protection_id,amount,
      idempotency_key,metadata
    ) values(
      'refund_shared_checkout','shared_payment_member',v_component.member_id::text,
      v_component.id,v_component.amount_total,
      'shared-checkout-refund:'||v_component.id,
      jsonb_build_object('shared_payment_group_id',p_group_id,
        'refund_destination','original_payment','retry_allowed',true)
    ) on conflict(idempotency_key) do nothing;
    if found then v_queued:=v_queued+1; end if;
  end loop;
  return v_queued;
end
$$;


--
-- Name: expire_stale_hotel_booking_holds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_stale_hotel_booking_holds() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  WITH expired AS (
    UPDATE public.hotel_bookings hb
    SET status='expired',payment_status='expired',updated_at=now()
    WHERE hb.status='pending'
      AND hb.payment_status IN ('unpaid','payment_pending')
      AND hb.payment_expires_at IS NOT NULL
      AND hb.payment_expires_at<now()
      AND NOT EXISTS (
        SELECT 1 FROM public.booking_payments bp
        WHERE bp.hotel_booking_id=hb.booking_id AND bp.purpose='hotel_booking' AND bp.status IN ('paid','completed')
      )
    RETURNING hb.booking_id
  )
  SELECT count(*)::integer INTO v_count FROM expired;

  UPDATE public.booking_payments bp
  SET status='expired',updated_at=now()
  WHERE bp.purpose='hotel_booking' AND bp.status='pending'
    AND EXISTS (
      SELECT 1 FROM public.hotel_bookings hb
      WHERE hb.booking_id=bp.hotel_booking_id AND hb.status='expired'
    );
  RETURN COALESCE(v_count,0);
END;
$$;


--
-- Name: fail_withdrawal_before_transfer(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_withdrawal_before_transfer(p_withdrawal_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then raise exception 'Service role required'; end if;
  return public.return_reserved_withdrawal(p_withdrawal_id,'failed',p_reason,'paystack-rejected:'||p_withdrawal_id::text);
end;
$$;


--
-- Name: field_officer_add_inspection_media(uuid, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_officer_add_inspection_media(p_inspection_id uuid, p_photo_urls text[] DEFAULT ARRAY[]::text[], p_video_urls text[] DEFAULT ARRAY[]::text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_updated integer := 0;
begin
  select *
  into v_actor
  from public.profiles
  where auth_id = auth.uid()::text
    and role = 'staff'
    and not coalesce(deleted, false)
    and not coalesce(suspended, false)
    and not coalesce(banned, false)
    and exists (
      select 1
      from public.staff_permissions sp
      where sp.staff_id = profiles.user_id
        and sp.permission = 'field_officer'
        and sp.is_active
    )
  limit 1;

  if v_actor is null then
    raise exception 'Active Field Operations access required';
  end if;

  if cardinality(coalesce(p_photo_urls, array[]::text[]))
     + cardinality(coalesce(p_video_urls, array[]::text[])) > 12 then
    raise exception 'A maximum of 12 evidence files is allowed per upload';
  end if;

  update public.inspection_requests
  set field_photo_urls = array(
        select distinct unnest(
          coalesce(field_photo_urls, array[]::text[])
          || coalesce(p_photo_urls, array[]::text[])
        )
      ),
      field_video_urls = array(
        select distinct unnest(
          coalesce(field_video_urls, array[]::text[])
          || coalesce(p_video_urls, array[]::text[])
        )
      ),
      updated_at = now()
  where id = p_inspection_id
    and coalesce(assigned_field_officer_id, field_officer_id, assigned_to) = v_actor.user_id;
  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    update public.user_inspection_requests
    set photo_urls = array(
          select distinct unnest(
            coalesce(photo_urls, array[]::text[])
            || coalesce(p_photo_urls, array[]::text[])
          )
        ),
        video_urls = array(
          select distinct unnest(
            coalesce(video_urls, array[]::text[])
            || coalesce(p_video_urls, array[]::text[])
          )
        ),
        updated_at = now()
    where id = p_inspection_id
      and field_officer_id = v_actor.user_id;
    get diagnostics v_updated = row_count;
  end if;

  if v_updated = 0 then
    raise exception 'Inspection is not assigned to this Field Operations account';
  end if;

  return true;
end;
$$;


--
-- Name: field_officer_add_inspection_photos(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_officer_add_inspection_photos(p_inspection_id uuid, p_photo_urls text[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;
begin
  v_actor:=public._current_comm_actor();
  if v_actor is null or v_actor.role<>'staff' or not public.current_staff_has_permission('field_officer') then raise exception 'Field Officer access required'; end if;
  if coalesce(array_length(p_photo_urls,1),0)=0 then raise exception 'Inspection photos are required'; end if;
  update public.inspection_requests set photo_urls=array(select distinct unnest(coalesce(photo_urls,'{}'::text[])||p_photo_urls)),updated_at=now() where id=p_inspection_id and coalesce(assigned_field_officer_id,field_officer_id,assigned_to)=v_actor.user_id;
  if found then return true; end if;
  update public.user_inspection_requests set photo_urls=array(select distinct unnest(coalesce(photo_urls,'{}'::text[])||p_photo_urls)),updated_at=now() where id=p_inspection_id and field_officer_id=v_actor.user_id;
  if not found then raise exception 'Inspection is not assigned to this Field Officer'; end if;
  return true;
end $$;


--
-- Name: field_officer_update_inspection_location(uuid, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_officer_update_inspection_location(p_inspection_id uuid, p_latitude numeric, p_longitude numeric, p_accuracy_m numeric DEFAULT NULL::numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_ir public.inspection_requests;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_actor.user_id IS NULL OR v_actor.role<>'staff' OR NOT public.current_staff_has_permission('field_officer') THEN
    RAISE EXCEPTION 'Field Officer permission required';
  END IF;
  IF p_latitude NOT BETWEEN -90 AND 90 OR p_longitude NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Invalid coordinates'; END IF;
  IF p_accuracy_m IS NOT NULL AND p_accuracy_m<0 THEN RAISE EXCEPTION 'Invalid location accuracy'; END IF;

  SELECT * INTO v_ir FROM public.inspection_requests WHERE id=p_inspection_id FOR UPDATE;
  IF v_ir.id IS NULL THEN RAISE EXCEPTION 'Property inspection not found'; END IF;
  IF COALESCE(v_ir.assigned_field_officer_id,v_ir.field_officer_id,v_ir.assigned_to) IS DISTINCT FROM v_actor.user_id THEN
    RAISE EXCEPTION 'This inspection is not assigned to you';
  END IF;
  IF v_ir.published_at IS NOT NULL THEN RAISE EXCEPTION 'Published property location must be corrected by Property Operations'; END IF;

  UPDATE public.inspection_requests
  SET gps_latitude=p_latitude,gps_longitude=p_longitude,location_accuracy_m=p_accuracy_m,updated_at=NOW()
  WHERE id=p_inspection_id;

  IF v_ir.draft_listing_id IS NOT NULL THEN
    UPDATE public.listings
    SET gps_latitude=p_latitude,gps_longitude=p_longitude,updated_at=NOW()
    WHERE id=v_ir.draft_listing_id AND deleted_at IS NULL;
  END IF;
  RETURN true;
END $$;


--
-- Name: finance_reviewer_is_authorized(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_reviewer_is_authorized(p_reviewer_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1 from public.profiles p
    where p.user_id=p_reviewer_id
      and p.role in ('staff','admin','creator')
      and not coalesce(p.deleted,false)
      and not coalesce(p.suspended,false)
      and not coalesce(p.banned,false)
      and (
        p.role='creator'
        or exists(
          select 1 from public.staff_permissions sp
          where sp.staff_id=p.user_id and sp.permission='finance' and sp.is_active
        )
      )
  )
$$;


--
-- Name: freeze_wallet(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_wallet(p_wallet_id uuid, p_reason text, p_frozen_by text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_is_service boolean:=COALESCE(current_setting('request.jwt.claim.role',true),'')='service_role';
  v_actor_id text;
  v_wallet public.wallets;
BEGIN
  IF v_is_service THEN
    v_actor_id:='service_role';
  ELSE
    SELECT * INTO v_actor FROM public.profiles
    WHERE auth_id=auth.uid()::text
      AND NOT COALESCE(deleted,false)
      AND NOT COALESCE(suspended,false)
      AND NOT COALESCE(banned,false)
    LIMIT 1;
    IF v_actor IS NULL OR NOT (
      v_actor.role='creator' OR
      (v_actor.role='staff' AND EXISTS(
        SELECT 1 FROM public.staff_permissions sp
        WHERE sp.staff_id=v_actor.user_id AND sp.permission='finance' AND sp.is_active=true
      ))
    ) THEN
      RAISE EXCEPTION 'Finance authority required';
    END IF;
    v_actor_id:=v_actor.user_id;
  END IF;

  SELECT * INTO v_wallet FROM public.wallets WHERE id=p_wallet_id FOR UPDATE;
  IF v_wallet IS NULL THEN RETURN jsonb_build_object('success',false,'error','Wallet not found'); END IF;
  IF COALESCE(v_wallet.is_frozen,false) THEN RETURN jsonb_build_object('success',true,'already_frozen',true); END IF;

  UPDATE public.wallets
  SET is_frozen=true,
      frozen_reason=NULLIF(btrim(p_reason),''),
      frozen_by=v_actor_id,
      frozen_at=now(),
      frozen_balance=COALESCE(frozen_balance,0)+COALESCE(available_balance,0),
      available_balance=0,
      updated_at=now()
  WHERE id=p_wallet_id;

  INSERT INTO public.financial_audit_logs(event_type,user_id,amount,reference_id,reference_type,description,metadata)
  VALUES('wallet_frozen',v_wallet.owner_id,COALESCE(v_wallet.available_balance,0),p_wallet_id::text,'wallet',COALESCE(NULLIF(btrim(p_reason),''),'Wallet frozen'),jsonb_build_object('actor',v_actor_id));

  RETURN jsonb_build_object('success',true);
END;
$$;


--
-- Name: fulfill_apartment_rent_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfill_apartment_rent_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_res public.reservations;
  v_listing public.listings;
  v_start_months integer:=4;
  v_installment_amount numeric;
  v_upfront_percent numeric;
  v_expected numeric;
  v_conflict boolean:=false;
begin
  if new.purpose<>'apartment_rent' or new.status not in ('paid','completed') then return new; end if;
  if tg_op='UPDATE' and old.status in ('paid','completed') then return new; end if;
  select * into v_res from public.reservations
  where id=new.metadata->>'reservation_id'
    and user_id=coalesce(new.payer_user_id,new.user_id) for update;
  if v_res.id is null then raise exception 'Apartment payment has no matching reservation'; end if;
  select * into v_listing from public.listings where id::text=v_res.listing_id for share;
  if v_listing.id is null then raise exception 'Listing not found'; end if;
  if v_res.rent_payment_reference is distinct from new.paystack_reference then
    raise exception 'Apartment payment reference mismatch';
  end if;

  if coalesce(v_res.stay_type,v_listing.sub_type)='short_let' then
    if new.metadata->>'payment_component'<>'short_stay_rent' then
      raise exception 'Short Let payment component mismatch';
    end if;
    if v_res.status not in ('payment_pending','reserved','ready_for_move_in') then
      raise exception 'Short Let checkout is not payable';
    end if;
    v_expected:=round(coalesce(v_res.stay_rent_total,0)+coalesce(v_res.security_deposit_snapshot,0),2);
    if round(coalesce(new.verified_amount,new.amount_total,new.amount),2)<>v_expected then
      raise exception 'Short Let payment amount mismatch';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('short-let:'||v_listing.id::text,0));
    select exists(
      select 1 from public.reservations r
      where r.listing_id=v_res.listing_id and r.id<>v_res.id
        and r.stay_type='short_let'
        and r.status=any(array['reserved','ready_for_move_in','occupied']::text[])
        and daterange(r.stay_check_in,r.stay_check_out,'[)')
          && daterange(v_res.stay_check_in,v_res.stay_check_out,'[)')
    ) into v_conflict;
    update public.reservations set
      manual_payment_status='completed',paid_at=coalesce(paid_at,now()),
      rent_payment_status='paid',rent_paid_at=coalesce(rent_paid_at,now()),
      security_deposit_status=case when coalesce(security_deposit_snapshot,0)>0 then 'held' else 'not_required' end,
      status=case when v_conflict then 'payment_conflict' else 'ready_for_move_in' end,
      canonical_state=case when v_conflict then 'payment_conflict' else 'stay_paid' end,
      refund_reason=case when v_conflict then 'Verified payment completed after the dates became unavailable' else refund_reason end,
      payment_expires_at=null,updated_at=now()
    where id=v_res.id;
    insert into public.short_let_booking_transitions(
      reservation_id,from_state,to_state,event_type,event_key,actor_type,metadata
    ) values(
      v_res.id,coalesce(v_res.canonical_state,'checkout_pending'),
      case when v_conflict then 'payment_conflict' else 'stay_paid' end,
      case when v_conflict then 'verified_payment_conflict' else 'stay_payment_verified' end,
      'short-let-paid:'||new.paystack_reference,'paystack',
      jsonb_build_object('booking_payment_id',new.id,'date_conflict',v_conflict)
    ) on conflict(event_key) do nothing;
    return new;
  end if;

  if new.metadata->>'payment_component'<>'long_stay_rent' then
    raise exception 'Long Let payment component mismatch';
  end if;
  if v_res.status not in ('reserved','ready_for_move_in') then
    raise exception 'Long Let reservation is not ready for rent settlement';
  end if;
  if round(coalesce(new.verified_amount,new.amount_total,new.amount),2)
      <>round(coalesce(v_res.annual_rent_snapshot,v_res.upfront_rent_required,0),2) then
    raise exception 'Year 1 rent payment amount mismatch';
  end if;
  update public.reservations set
    rent_payment_status=case when installment_balance>0 then 'upfront_paid' else 'paid' end,
    rent_paid_at=coalesce(rent_paid_at,now()),
    status=case when status='reserved' then 'ready_for_move_in' else status end,
    updated_at=now()
  where id=v_res.id;

  if coalesce(v_res.installment_balance,0)>0 then
    select coalesce(nullif(value,'')::integer,4) into v_start_months
    from public.platform_settings where key='rent_plan_start_after_months'
      and coalesce(is_active,true) limit 1;
    if v_start_months is null or v_start_months<>4 then v_start_months:=4; end if;
    v_installment_amount:=round(coalesce(v_res.annual_rent_snapshot,0)/8.0,2);
    v_upfront_percent:=round(100.0/greatest(coalesce(v_res.rental_plan_years,1),1),2);
    insert into public.rent_plans(
      user_id,listing_id,reservation_id,target_amount,start_after_months,
      cancellation_fee_percent,accepted_terms,status,total_contract_rent,
      upfront_percent,upfront_amount,installment_count,installment_amount,
      installment_balance,paid_installments,created_at,updated_at
    ) values(
      v_res.user_id,v_res.listing_id::uuid,v_res.id,v_res.installment_balance,
      v_start_months,coalesce((select nullif(value,'')::numeric
        from public.platform_settings where key='rent_plan_cancellation_fee_percent' limit 1),10),
      jsonb_build_object('tenure_years',v_res.rental_plan_years,
        'annual_rent',v_res.annual_rent_snapshot,'year_one_paid_in_full',true,
        'future_rent_balance',v_res.installment_balance,'start_after_months',4,
        'contributions_per_future_year',8,'partner_opt_in',true,
        'payment_protection_hold',false,'snapshot_at',now())::text,
      'active',v_res.contract_rent_total,v_upfront_percent,v_res.upfront_rent_required,
      v_res.installment_count,v_installment_amount,v_res.installment_balance,0,now(),now()
    ) on conflict do nothing;
  end if;
  return new;
end
$$;


--
-- Name: fulfill_apartment_reservation_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfill_apartment_reservation_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_res public.reservations;
  v_listing public.listings;
  v_hold_days integer;
  v_hold_expires timestamptz;
  v_is_short boolean;
BEGIN
  IF NEW.purpose<>'apartment_reservation' OR NEW.status NOT IN ('paid','completed') THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND OLD.status IN ('paid','completed') THEN RETURN NEW; END IF;

  SELECT * INTO v_res
  FROM public.reservations
  WHERE payment_reference=NEW.paystack_reference
  LIMIT 1
  FOR UPDATE;
  IF v_res IS NULL THEN RAISE EXCEPTION 'Apartment reservation payment has no reservation'; END IF;
  IF v_res.user_id IS DISTINCT FROM COALESCE(NEW.payer_user_id,NEW.user_id) THEN
    RAISE EXCEPTION 'Apartment reservation payment owner mismatch';
  END IF;

  SELECT * INTO v_listing
  FROM public.listings
  WHERE id::text=v_res.listing_id
  LIMIT 1
  FOR UPDATE;
  IF v_listing IS NULL THEN RAISE EXCEPTION 'Apartment reservation listing not found'; END IF;
  v_is_short := COALESCE(v_res.stay_type,v_listing.sub_type,'long_stay')='short_let';

  IF v_is_short THEN
    IF EXISTS (
      SELECT 1
      FROM public.reservations r
      WHERE r.listing_id=v_res.listing_id
        AND r.id<>v_res.id
        AND r.status = ANY (ARRAY['payment_pending','reserved','inspection_pending','ready_for_move_in','occupied']::text[])
        AND (
          COALESCE(r.stay_type,'long_stay')<>'short_let'
          OR daterange(r.stay_check_in,r.stay_check_out,'[)') && daterange(v_res.stay_check_in,v_res.stay_check_out,'[)')
        )
    ) THEN
      UPDATE public.reservations
      SET status='payment_conflict',manual_payment_status='paid',paid_at=COALESCE(paid_at,now()),
          refund_reason='Payment completed after the selected dates became unavailable',processed_at=now(),updated_at=now()
      WHERE id=v_res.id;
      RETURN NEW;
    END IF;
  ELSE
    IF v_listing.current_reservation_id IS DISTINCT FROM v_res.id AND v_listing.status<>'available' THEN
      UPDATE public.reservations
      SET status='payment_conflict',manual_payment_status='paid',paid_at=COALESCE(paid_at,now()),
          refund_reason='Payment completed after the property was assigned elsewhere',processed_at=now(),updated_at=now()
      WHERE id=v_res.id;
      RETURN NEW;
    END IF;
  END IF;

  SELECT NULLIF(value,'')::integer INTO v_hold_days
  FROM public.platform_settings
  WHERE key='apartment_reservation_hold_days' AND COALESCE(is_active,true)=true
  LIMIT 1;
  IF v_hold_days IS NULL OR v_hold_days<1 OR v_hold_days>30 THEN v_hold_days:=3; END IF;
  v_hold_expires:=now()+make_interval(days=>v_hold_days);

  UPDATE public.reservations
  SET status=CASE WHEN status='payment_pending' THEN 'reserved' ELSE status END,
      manual_payment_status='paid',
      paid_at=COALESCE(paid_at,now()),
      payment_expires_at=NULL,
      hold_expires_at=CASE WHEN v_is_short THEN NULL ELSE v_hold_expires END,
      updated_at=now()
  WHERE id=v_res.id;

  IF NOT v_is_short THEN
    UPDATE public.listings
    SET status='reserved',availability_status='reserved',reserved_by=v_res.user_id,
        reservation_expiry=v_hold_expires,reservation_fee_paid=true,chat_unlocked=true,
        current_reservation_id=v_res.id,updated_at=now()
    WHERE id=v_listing.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fulfill_hotel_booking_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfill_hotel_booking_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare v_booking public.hotel_bookings; v_quote jsonb;
begin
  if new.purpose<>'hotel_booking' or new.status not in ('paid','completed') then return new; end if;
  if tg_op='UPDATE' and old.status in ('paid','completed') then return new; end if;
  select * into v_booking from public.hotel_bookings
  where booking_id=new.hotel_booking_id and user_id=coalesce(new.payer_user_id,new.user_id) for update;
  if v_booking.booking_id is null then raise exception 'Hotel payment has no matching booking'; end if;
  if v_booking.payment_reference is distinct from new.paystack_reference then raise exception 'Hotel payment reference mismatch'; end if;
  if round(v_booking.total_price,2)<>round(coalesce(new.amount_total,new.amount),2) then raise exception 'Hotel payment amount mismatch'; end if;
  if v_booking.status='confirmed' and v_booking.payment_status='paid' then return new; end if;
  v_quote:=private.hotel_booking_quote_v2(v_booking.room_id,v_booking.rate_plan_id,v_booking.check_in,v_booking.check_out,v_booking.booking_id,false);
  if not coalesce((v_quote->>'available')::boolean,false) then
    update public.hotel_bookings set status='payment_conflict',payment_status='paid',
      paid_at=coalesce(paid_at,now()),updated_at=now() where booking_id=v_booking.booking_id;
    return new;
  end if;
  update public.hotel_bookings set status='confirmed',payment_status='paid',
    paid_at=coalesce(paid_at,now()),confirmed_at=coalesce(confirmed_at,now()),updated_at=now()
  where booking_id=v_booking.booking_id;
  return new;
end;
$$;


--
-- Name: fulfill_rent_plan_contribution_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfill_rent_plan_contribution_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_contribution public.rent_plan_contributions;
  v_plan public.rent_plans;
  v_paid_total numeric;
  v_paid_count integer;
  v_remaining integer;
  v_next_due date;
BEGIN
  IF NEW.purpose<>'rent_plan_contribution' OR NEW.status NOT IN ('paid','completed') THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND OLD.status IN ('paid','completed') THEN RETURN NEW; END IF;

  SELECT * INTO v_contribution
  FROM public.rent_plan_contributions
  WHERE id=(NEW.metadata->>'contribution_id')::uuid
  FOR UPDATE;
  IF v_contribution.id IS NULL THEN RAISE EXCEPTION 'Rent contribution payment has no schedule row'; END IF;
  IF v_contribution.paystack_reference IS DISTINCT FROM NEW.paystack_reference THEN RAISE EXCEPTION 'Rent contribution reference mismatch'; END IF;
  IF round(v_contribution.amount,2)<>round(COALESCE(NEW.amount_total,NEW.amount),2) THEN RAISE EXCEPTION 'Rent contribution amount mismatch'; END IF;

  UPDATE public.rent_plan_contributions
  SET status='paid',paid_at=COALESCE(paid_at,now()),completed_at=COALESCE(completed_at,now()),updated_at=now()
  WHERE id=v_contribution.id;

  SELECT * INTO v_plan
  FROM public.rent_plans
  WHERE id=v_contribution.rent_plan_id
  FOR UPDATE;
  IF v_plan.id IS NULL THEN RAISE EXCEPTION 'Rent plan not found'; END IF;

  SELECT COALESCE(sum(amount),0),count(*)::integer
  INTO v_paid_total,v_paid_count
  FROM public.rent_plan_contributions
  WHERE rent_plan_id=v_plan.id AND status IN ('paid','completed');

  SELECT count(*)::integer,min(due_date)
  INTO v_remaining,v_next_due
  FROM public.rent_plan_contributions
  WHERE rent_plan_id=v_plan.id AND status IN ('scheduled','payment_pending','pending');

  UPDATE public.rent_plans
  SET total_contributed=v_paid_total,
      paid_installments=v_paid_count,
      installment_balance=GREATEST(COALESCE(target_amount,0)-v_paid_total,0),
      last_contribution_at=now(),
      next_rent_due_date=v_next_due,
      status=CASE WHEN v_remaining=0 THEN 'completed' ELSE 'active' END,
      updated_at=now()
  WHERE id=v_plan.id;

  IF v_remaining=0 THEN
    UPDATE public.reservations
    SET rent_payment_status='paid',updated_at=now()
    WHERE id=v_plan.reservation_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: generate_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_user_id() RETURNS character varying
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
                                                  DECLARE
                                                    current_year VARCHAR(4);
                                                      next_num INTEGER;
                                                        new_id VARCHAR(20);
                                                        BEGIN
                                                          current_year := TO_CHAR(NOW(), 'YYYY');
                                                            UPDATE user_ids SET last_number = last_number + 1, updated_at = NOW()
                                                              WHERE year = current_year RETURNING last_number INTO next_num;
                                                                IF next_num IS NULL THEN
                                                                    INSERT INTO user_ids (year, last_number) VALUES (current_year, 1)
                                                                        ON CONFLICT (year) DO UPDATE SET last_number = user_ids.last_number + 1
                                                                            RETURNING user_ids.last_number INTO next_num;
                                                                              END IF;
                                                                                new_id := 'WHU-' || current_year || '-' || LPAD(next_num::TEXT, 6, '0');
                                                                                  RETURN new_id;
                                                                                  END;
                                                                                  $$;


--
-- Name: generate_user_id_simple(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_user_id_simple() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$ DECLARE next_num INTEGER; BEGIN UPDATE user_id_counter SET last_number = last_number + 1 RETURNING last_number INTO next_num; RETURN 'WHU-' || LPAD(next_num::TEXT, 3, '0'); END; $$;


--
-- Name: get_admin_staff_limit_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_admin_staff_limit_v2() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  SELECT GREATEST(0,COALESCE(CASE WHEN value ~ '^\d+$' THEN value::integer ELSE 0 END,0))
  FROM public.platform_settings WHERE key='admin_staff_limit' AND is_active=true LIMIT 1;
$_$;


--
-- Name: get_all_settings_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_settings_v2() RETURNS TABLE(id integer, key text, value text, label text, description text, category text, data_type text, is_active boolean, updated_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT ps.id,ps.key,ps.value,ps.label,ps.description,ps.category,ps.data_type,ps.is_active,ps.updated_at
  FROM public.platform_settings ps
  WHERE ps.is_active=true
    AND ps.key NOT LIKE '%secret%'
    AND ps.key NOT LIKE '%api_key%'
    AND ps.key NOT LIKE '%private%'
    AND ps.key NOT LIKE '%password%'
    AND ps.key NOT LIKE '%token%'
    AND ps.key NOT IN (
      'commission_rate_worker','commission_worker','commission_rate_partner','partner_commission_rate',
      'property_commission','commission_rate_hotel','hotel_commission','minimum_withdrawal'
    )
  ORDER BY ps.category,ps.key;
$$;


--
-- Name: get_allowed_conversation_profile(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_allowed_conversation_profile(p_context_type text, p_context_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text;
  v_peer text;
  v_profile public.profiles;
  v_roommate public.roommate_profiles;
  v_actor_prefs public.roommate_preferences;
  v_peer_prefs public.roommate_preferences;
  v_school_visible boolean := false;
begin
  select user_id into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor is null then raise exception 'Authentication required'; end if;

  if p_context_type='roommate' then
    select case when participant_a=v_actor then participant_b else participant_a end into v_peer
    from public.conversations where id=p_context_id and conversation_type='roommate'
      and v_actor in (participant_a,participant_b);
  elsif p_context_type='worker_booking' then
    select case when user_id=v_actor then worker_id else user_id end into v_peer
    from public.worker_bookings where id=p_context_id and v_actor in (user_id,worker_id);
  else
    raise exception 'Unsupported conversation type';
  end if;
  if v_peer is null then raise exception 'Conversation access denied'; end if;

  select * into v_profile from public.profiles where user_id=v_peer limit 1;
  if v_profile.user_id is null then raise exception 'Profile unavailable'; end if;
  if p_context_type='roommate' then
    select * into v_roommate from public.roommate_profiles where user_id=v_peer limit 1;
    select * into v_actor_prefs from public.roommate_preferences where user_id=v_actor limit 1;
    select * into v_peer_prefs from public.roommate_preferences where user_id=v_peer limit 1;
    v_school_visible := coalesce(v_actor_prefs.school_match,false)
      and coalesce(v_peer_prefs.school_match,false)
      and lower(regexp_replace(btrim(coalesce(v_actor_prefs.school_name,'')),'\s+',' ','g'))
        = lower(regexp_replace(btrim(coalesce(v_peer_prefs.school_name,'')),'\s+',' ','g'));
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'user_id',v_profile.user_id,'role',v_profile.role,'full_name',v_profile.full_name,
    'username',v_profile.username,'avatar_url',v_profile.avatar_url,'bio',v_profile.bio,
    'school',case when v_school_visible then v_profile.school else null end,
    'gender',v_profile.gender,'state',v_profile.state,
    'lga',coalesce(v_profile.local_government,v_profile.city),
    'worker_occupation',v_profile.worker_occupation,'worker_bio',v_profile.worker_bio,
    'worker_skills',v_profile.worker_skills,'worker_verified',v_profile.worker_verified,
    'worker_price',v_profile.worker_price,'worker_experience',v_profile.worker_experience,
    'rating',v_profile.rating,'review_count',v_profile.review_count,
    'roommate',case when p_context_type='roommate' then jsonb_strip_nulls(jsonb_build_object(
      'age',v_roommate.age,'budget_min',v_roommate.budget_min,'budget_max',v_roommate.budget_max,
      'area',v_roommate.area,'city',v_roommate.city,'personality_type',v_roommate.personality_type,
      'stay_duration',v_roommate.stay_duration
    )) else null end
  ));
end;
$$;


--
-- Name: get_booking_details(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_booking_details(p_booking_id uuid) RETURNS TABLE(id uuid, booking_code text, user_id text, worker_id text, service_type text, description text, address text, scheduled_date date, agreed_amount numeric, wehouse_fee numeric, worker_commission numeric, worker_receives numeric, negotiated_amount numeric, paystack_reference text, status text, customer_message text, worker_approved boolean, user_approved boolean, dispute_reason text, dispute_resolution text, cancellation_reason text, started_at timestamp with time zone, marked_complete_at timestamp with time zone, completed_at timestamp with time zone, created_at timestamp with time zone, booking_conversation_id uuid, user_name text, worker_name text, user_phone text, worker_phone text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT wb.id, wb.booking_code, wb.user_id, wb.worker_id, wb.service_type, wb.description, wb.address, wb.scheduled_date, wb.agreed_amount, wb.wehouse_fee, wb.worker_commission, wb.worker_receives, wb.negotiated_amount, wb.paystack_reference, wb.status, wb.customer_message, wb.worker_approved, wb.user_approved, wb.dispute_reason, wb.dispute_resolution, wb.cancellation_reason, wb.started_at, wb.marked_complete_at, wb.completed_at, wb.created_at, wb.booking_conversation_id, u.full_name, w.full_name, u.phone, w.phone FROM worker_bookings wb INNER JOIN profiles u ON u.user_id = wb.user_id INNER JOIN profiles w ON w.user_id = wb.worker_id WHERE wb.id = p_booking_id; $$;


--
-- Name: get_booking_messages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_booking_messages(p_conversation_id uuid) RETURNS TABLE(id uuid, sender_id text, sender_name text, sender_role text, content text, attachments text[], is_read boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conv public.booking_conversations;
begin
  v_actor := public._current_comm_actor();
  if v_actor is null then raise exception 'Authentication required'; end if;

  select bc.*
  into v_conv
  from public.booking_conversations bc
  where bc.id = p_conversation_id;

  if v_conv is null or v_actor.user_id not in (v_conv.user_id, v_conv.worker_id) then
    raise exception 'Not authorized for this booking conversation';
  end if;

  return query
  select bm.id, bm.sender_id, p.full_name, p.role, bm.content, bm.attachments, bm.is_read, bm.created_at
  from public.booking_messages bm
  join public.profiles p on p.user_id = bm.sender_id
  where bm.conversation_id = p_conversation_id
    and not (v_actor.user_id = any(coalesce(bm.hidden_for, array[]::text[])))
  order by bm.created_at;
end
$$;


--
-- Name: get_chat_peer_presence(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_chat_peer_presence(p_peer_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_peer public.profiles;
  v_related boolean:=false;
  v_online boolean:=false;
BEGIN
  SELECT * INTO v_actor
  FROM public.profiles
  WHERE auth_id=auth.uid()::text
    AND COALESCE(deleted,false)=false
    AND COALESCE(suspended,false)=false
    AND COALESCE(banned,false)=false
  LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_peer_user_id IS NULL OR p_peer_user_id=v_actor.user_id THEN RAISE EXCEPTION 'Peer required'; END IF;

  SELECT EXISTS(
    SELECT 1
    FROM public.conversations c
    WHERE c.conversation_type='roommate'
      AND ((c.participant_a=v_actor.user_id AND c.participant_b=p_peer_user_id)
        OR (c.participant_b=v_actor.user_id AND c.participant_a=p_peer_user_id))
      AND public._can_access_conversation(c.id)
  ) OR EXISTS(
    SELECT 1
    FROM public.booking_conversations bc
    WHERE (bc.user_id=v_actor.user_id AND bc.worker_id=p_peer_user_id)
       OR (bc.worker_id=v_actor.user_id AND bc.user_id=p_peer_user_id)
  ) INTO v_related;

  IF NOT v_related THEN RAISE EXCEPTION 'Chat relationship required'; END IF;

  SELECT * INTO v_peer
  FROM public.profiles
  WHERE user_id=p_peer_user_id
    AND COALESCE(deleted,false)=false
    AND COALESCE(suspended,false)=false
    AND COALESCE(banned,false)=false
  LIMIT 1;

  IF v_peer IS NULL THEN
    RETURN jsonb_build_object('visible',false,'online',false,'last_seen',NULL);
  END IF;

  IF COALESCE(v_peer.privacy_activity_visible,true)=false THEN
    RETURN jsonb_build_object('visible',false,'online',false,'last_seen',NULL);
  END IF;

  v_online:=COALESCE(v_peer.is_online,false)
    AND v_peer.last_seen IS NOT NULL
    AND v_peer.last_seen >= now()-interval '90 seconds';

  RETURN jsonb_build_object(
    'visible',true,
    'online',v_online,
    'last_seen',v_peer.last_seen
  );
END;
$$;


--
-- Name: get_conversation_messages(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_conversation_messages(p_conversation_id text) RETURNS TABLE(id uuid, conversation_id uuid, sender_id text, content text, seen boolean, created_at timestamp with time zone, edited_at timestamp with time zone, file_url text, file_name text, file_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE cid uuid:=p_conversation_id::uuid;
BEGIN
  IF NOT public._can_access_conversation(cid) THEN RAISE EXCEPTION 'Not authorized for this conversation'; END IF;
  RETURN QUERY SELECT m.id,m.conversation_id,m.sender_id,m.content,m.seen,m.created_at,m.edited_at,m.file_url,m.file_name,m.file_type
  FROM public.messages m WHERE m.conversation_id=cid ORDER BY m.created_at ASC;
END;
$$;


--
-- Name: get_current_legal_documents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_current_legal_documents() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'privacy',(select jsonb_build_object(
      'policy_version_id',p.policy_version_id,'version',p.version,
      'title',p.value->>'title','body',p.value->>'body',
      'locale',p.value->>'locale','effective_from',p.effective_from,
      'checksum',p.checksum
    ) from public.creator_policy_versions p
      where p.policy_key='legal_privacy' and p.status='active'
        and p.legal_review_state='reviewed' and p.public_disclosure
        and p.effective_from<=now()
        and (p.effective_until is null or p.effective_until>now())
      order by p.effective_from desc limit 1),
    'terms',(select jsonb_build_object(
      'policy_version_id',p.policy_version_id,'version',p.version,
      'title',p.value->>'title','body',p.value->>'body',
      'locale',p.value->>'locale','effective_from',p.effective_from,
      'checksum',p.checksum
    ) from public.creator_policy_versions p
      where p.policy_key='legal_terms' and p.status='active'
        and p.legal_review_state='reviewed' and p.public_disclosure
        and p.effective_from<=now()
        and (p.effective_until is null or p.effective_until>now())
      order by p.effective_from desc limit 1)
  )
$$;


--
-- Name: get_discoverable_homes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_discoverable_homes() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(
    (to_jsonb(l)-'address'-'gps_latitude'-'gps_longitude'-'location_accuracy_m')
    || jsonb_build_object(
      'address',null,
      'gps_latitude',case when l.gps_latitude is null then null else round(l.gps_latitude,2) end,
      'gps_longitude',case when l.gps_longitude is null then null else round(l.gps_longitude,2) end,
      'location_exact',false
    ) order by l.created_at desc
  ),'[]'::jsonb)
  from public.listings l
  where l.deleted_at is null
    and coalesce(l.property_type,'apartment')<>'hotel'
    and (l.status='available' or (l.status='occupied' and l.sub_type='short_let'))
$$;


--
-- Name: get_discoverable_hotels(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_discoverable_hotels() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(
    (to_jsonb(h)-'address'-'gps_latitude'-'gps_longitude'-'owner_id'-'inspection_request_id'-'approved_by')
    || jsonb_build_object(
      'address',null,
      'gps_latitude',case when h.gps_latitude is null then null else round(h.gps_latitude,2) end,
      'gps_longitude',case when h.gps_longitude is null then null else round(h.gps_longitude,2) end,
      'location_exact',false,
      'hotel_rooms',coalesce((
        select jsonb_agg(jsonb_build_object(
          'room_id',r.room_id,'price_per_night',coalesce((select min(rp.price_per_night) from public.hotel_rate_plans rp where rp.room_id=r.room_id and rp.active),r.price_per_night),'room_type',r.room_type
        ) order by r.price_per_night) from public.hotel_rooms r where r.hotel_id=h.hotel_id
      ),'[]'::jsonb)
    ) order by h.featured desc,h.created_at desc
  ),'[]'::jsonb)
  from public.hotels h where h.status='active' and h.approved_at is not null and h.published_at is not null
$$;


--
-- Name: get_discoverable_listings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_discoverable_listings() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(
    (to_jsonb(l)-'address'-'gps_latitude'-'gps_longitude'-'location_accuracy_m'-'owner_id'-'partner_id'-'chat_agent_id'-'contact_phone'-'reserved_by'-'occupied_by'-'current_reservation_id'-'inspection_request_id')
    ||jsonb_build_object(
      'address',null,
      'gps_latitude',case when l.gps_latitude is null then null else round(l.gps_latitude,2) end,
      'gps_longitude',case when l.gps_longitude is null then null else round(l.gps_longitude,2) end,
      'location_exact',false,
      'partner_display_name',coalesce(nullif(btrim(p.full_name),''),nullif(btrim(p.username),''))
    ) order by l.created_at desc
  ),'[]'::jsonb)
  from public.listings l
  left join public.profiles p on p.user_id=coalesce(l.partner_id,l.owner_id)
  where l.deleted_at is null
    and l.inspection_request_id is not null
    and l.approved_at is not null
    and l.status='available'
    and l.availability_status='available'
$$;


--
-- Name: get_effective_policy(text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_policy(p_policy_key text, p_scope_type text DEFAULT 'global'::text, p_scope_key text DEFAULT '*'::text, p_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'policy_version_id',p.policy_version_id,
    'policy_key',p.policy_key,
    'scope_type',p.scope_type,
    'scope_key',p.scope_key,
    'version',p.version,
    'value',p.value,
    'disclosure_text',p.disclosure_text,
    'effective_from',p.effective_from,
    'legal_review_state',p.legal_review_state
  )
  from public.creator_policy_versions p
  where p.policy_key=p_policy_key
    and (
      (p.scope_type=p_scope_type and p.scope_key=p_scope_key)
      or (p.scope_type='global' and p.scope_key='*')
    )
    and p.status='active'
    and p.effective_from<=p_at
    and (p.effective_until is null or p.effective_until>p_at)
    and (
      p.public_disclosure
      or public.current_actor_has_personal_workspace()
    )
  order by case when p.scope_type=p_scope_type and p.scope_key=p_scope_key then 0 else 1 end,
    p.effective_from desc
  limit 1
$$;


--
-- Name: get_featured_workers(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_featured_workers(p_state text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 3) RETURNS TABLE(user_id text, full_name text, username text, avatar_url text, bio text, state text, city text, local_government text, area text, worker_occupation text, worker_skills jsonb, worker_price integer, worker_bio text, worker_experience text, rating numeric, review_count integer, is_online boolean, last_seen timestamp with time zone, services jsonb, coverage jsonb, pro_active boolean, featured_placement_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_enabled boolean:=false;
  v_marketplace_enabled boolean:=false;
  v_slots integer:=3;
  v_limit integer;
  v_context text;
begin
  if (select auth.uid()) is null or v_actor is null then
    raise exception 'Active signed-in account required';
  end if;
  select coalesce(lower(value) in('true','1','yes','on'),false)
    into v_enabled from public.platform_settings
  where key='worker_featured_sales_enabled' and is_active=true limit 1;
  select coalesce(lower(value) in('true','1','yes','on'),false)
    into v_marketplace_enabled from public.platform_settings
  where key='worker_marketplace_launch_enabled' and is_active=true limit 1;
  select greatest(0,least(6,coalesce(nullif(value,'')::integer,3)))
    into v_slots from public.platform_settings
  where key='worker_featured_slot_count' and is_active=true limit 1;
  v_limit:=greatest(0,least(coalesce(p_limit,3),coalesce(v_slots,3),6));
  if not coalesce(v_enabled,false) or not coalesce(v_marketplace_enabled,false)
     or v_limit=0
     or not public._legal_launch_gate_is_approved('worker_featured_placement')
     or not public._legal_launch_gate_is_approved('worker_marketplace') then
    return;
  end if;
  v_context:=md5(lower(concat_ws('|',btrim(coalesce(p_state,'')),
    btrim(coalesce(p_city,'')),btrim(coalesce(p_query,'')))));

  return query
  with candidates as materialized (
    select profile.user_id
    from public.profiles profile
    where profile.user_id<>v_actor
      and public.user_has_active_workspace(profile.user_id,'worker')
      and profile.worker_status='verified' and profile.worker_verified=true
      and profile.available=true
      and not coalesce(profile.deleted,false)
      and not coalesce(profile.suspended,false)
      and not coalesce(profile.banned,false)
      and public.worker_identity_is_current(profile.user_id)
      and public.worker_professional_profile_ready(profile.user_id)
      and public.worker_pro_is_active(profile.user_id)
      and (p_state is null or btrim(p_state)=''
        or public.wehouse_state_key(profile.state)=public.wehouse_state_key(p_state))
      and (p_city is null or btrim(p_city)='' or profile.city ilike p_city
        or profile.local_government ilike p_city)
      and (
        p_query is null or btrim(p_query)=''
        or concat_ws(' ',profile.full_name,profile.username,
          profile.worker_occupation,profile.worker_bio,profile.state,
          profile.city,profile.local_government) ilike '%'||btrim(p_query)||'%'
        or exists(select 1 from public.worker_services service
          where service.worker_id=profile.user_id
            and service.service_name ilike '%'||btrim(p_query)||'%')
        or exists(select 1 from jsonb_array_elements_text(
          case when jsonb_typeof(profile.worker_skills)='array'
            then profile.worker_skills else '[]'::jsonb end
        ) skill(value) where skill.value ilike '%'||btrim(p_query)||'%')
      )
      and not exists(
        select 1 from public.worker_user_blocks blocked_pair where
          (blocked_pair.blocker_user_id=v_actor
            and blocked_pair.blocked_user_id=profile.user_id)
          or (blocked_pair.blocker_user_id=profile.user_id
            and blocked_pair.blocked_user_id=v_actor)
      )
    order by (
      select max(placement.presented_at)
      from public.worker_featured_placements placement
      where placement.worker_id=profile.user_id
    ) asc nulls first,md5(current_date::text||profile.user_id)
    limit v_limit
  ), placed as (
    insert into public.worker_featured_placements(
      viewer_id,worker_id,context_key,impression_day,presented_at,updated_at
    )
    select v_actor,candidate.user_id,v_context,current_date,now(),now()
    from candidates candidate
    on conflict(viewer_id,worker_id,impression_day) do update
    set context_key=excluded.context_key,presented_at=excluded.presented_at,
      updated_at=now()
    returning id,worker_id
  )
  select
    profile.user_id,profile.full_name,profile.username,profile.avatar_url,
    profile.bio,profile.state,profile.city,profile.local_government,
    profile.area,profile.worker_occupation,profile.worker_skills,
    profile.worker_price,profile.worker_bio,profile.worker_experience,
    profile.rating,profile.review_count,profile.is_online,profile.last_seen,
    coalesce((select jsonb_agg(jsonb_build_object(
      'name',service.service_name,'price',service.price,
      'price_type',service.price_type))
      from public.worker_services service
      where service.worker_id=profile.user_id),'[]'::jsonb),
    coalesce((select jsonb_agg(jsonb_build_object(
      'state',coverage.state,'lga',coverage.lga,'areas',coverage.areas))
      from public.worker_service_coverage coverage
      where coverage.worker_id=profile.user_id),'[]'::jsonb),
    true,placed.id
  from placed join public.profiles profile on profile.user_id=placed.worker_id;
end;
$$;


--
-- Name: get_hotel_booking_messages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hotel_booking_messages(p_conversation_id uuid) RETURNS TABLE(id uuid, sender_id text, sender_name text, sender_role text, content text, attachments text[], attachment_types text[], reactions jsonb, is_read boolean, reply_to_id uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor_id text;
begin
  select user_id into actor_id from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false)
  limit 1;
  if actor_id is null or not public.can_access_hotel_booking_conversation(p_conversation_id) then
    raise exception 'Hotel conversation access denied';
  end if;
  return query
  select m.id,m.sender_id,coalesce(p.full_name,p.username,'Member'),
    case when m.sender_id=c.guest_user_id then 'guest' else 'hotel' end,
    m.content,m.attachments,m.attachment_types,m.reactions,m.is_read,m.reply_to_id,m.created_at
  from public.hotel_booking_messages m
  join public.hotel_booking_conversations c on c.id=m.conversation_id
  join public.profiles p on p.user_id=m.sender_id
  where m.conversation_id=p_conversation_id
    and not actor_id=any(coalesce(m.hidden_for,'{}'::text[]))
  order by m.created_at;
end;
$$;


--
-- Name: get_inspection_field_officer_candidates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inspection_field_officer_candidates(p_inspection_id uuid) RETURNS TABLE(user_id text, full_name text, username text, assigned_state text, assigned_lga text, active_inspections bigint, distance_km numeric, location_accuracy_m numeric, location_updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_actor record; v_req record;
begin
 select user_id,role,assigned_state,assigned_lga,deleted,suspended,banned into v_actor from public.profiles where auth_id=auth.uid()::text limit 1;
 if v_actor is null or v_actor.role not in ('admin','creator') or coalesce(v_actor.deleted,false) or coalesce(v_actor.suspended,false) or coalesce(v_actor.banned,false) then raise exception 'Admin or Creator access required'; end if;
 select id,property_state,property_city,gps_latitude,gps_longitude into v_req from public.inspection_requests where id=p_inspection_id;
 if v_req is null then raise exception 'Inspection request not found'; end if;
 if v_actor.role='admin' and (lower(coalesce(v_actor.assigned_state,''))<>lower(coalesce(v_req.property_state,'')) or lower(coalesce(v_actor.assigned_lga,''))<>lower(coalesce(v_req.property_city,''))) then raise exception 'Inspection is outside your assigned branch'; end if;
 return query select p.user_id,p.full_name,p.username,p.assigned_state,p.assigned_lga,
   (select count(*) from public.inspection_requests ir where coalesce(ir.assigned_field_officer_id,ir.field_officer_id,ir.assigned_to)=p.user_id and ir.status in ('scheduled','in_progress')),
   case when v_req.gps_latitude is not null and v_req.gps_longitude is not null and p.operational_latitude is not null and p.operational_longitude is not null then round((6371*2*asin(sqrt(power(sin(radians((p.operational_latitude-v_req.gps_latitude)/2)),2)+cos(radians(v_req.gps_latitude))*cos(radians(p.operational_latitude))*power(sin(radians((p.operational_longitude-v_req.gps_longitude)/2)),2))))::numeric,2) else null end,
   p.operational_location_accuracy_m,p.operational_location_updated_at
 from public.profiles p
 where p.role='staff' and coalesce(p.deleted,false)=false and coalesce(p.suspended,false)=false and coalesce(p.banned,false)=false
   and lower(coalesce(p.assigned_state,''))=lower(coalesce(v_req.property_state,'')) and lower(coalesce(p.assigned_lga,''))=lower(coalesce(v_req.property_city,''))
   and exists(select 1 from public.staff_permissions sp where sp.staff_id=p.user_id and sp.permission='field_officer' and sp.is_active=true)
 order by distance_km asc nulls last, active_inspections asc, coalesce(p.full_name,p.username,p.user_id);
end $$;


--
-- Name: get_inspection_media_for_review(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inspection_media_for_review(p_inspection_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
begin
  select * into v_actor
  from public.profiles
  where auth_id=auth.uid()::text
    and role in ('creator','admin','staff')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null then raise exception 'Operations review access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then
    raise exception 'Property Operations access required';
  end if;

  select * into v_request
  from public.inspection_requests
  where id=p_inspection_id;
  if v_request is null then raise exception 'Inspection not found'; end if;
  if v_actor.role<>'creator'
     and not public.current_actor_in_scope(v_request.property_state,v_request.property_city) then
    raise exception 'Inspection is outside your assigned branch';
  end if;

  return jsonb_build_object(
    'partner_photos',coalesce(to_jsonb(v_request.photo_urls),'[]'::jsonb),
    'partner_videos',coalesce(to_jsonb(v_request.video_urls),'[]'::jsonb),
    'field_photos',coalesce(to_jsonb(v_request.field_photo_urls),'[]'::jsonb),
    'field_videos',coalesce(to_jsonb(v_request.field_video_urls),'[]'::jsonb),
    -- Compatibility aliases are deliberately Field Operations evidence only.
    'photos',coalesce(to_jsonb(v_request.field_photo_urls),'[]'::jsonb),
    'videos',coalesce(to_jsonb(v_request.field_video_urls),'[]'::jsonb),
    'report',v_request.notes,
    'status',v_request.status
  );
end;
$$;


--
-- Name: get_my_accommodation_protection(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_accommodation_protection(p_subject_type text, p_subject_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_owner boolean:=false;
  v_protection_id uuid;
  v_deadline timestamptz;
  v_hours integer;
  v_checked_in_at timestamptz;
  v_policy_id uuid;
  v_protection public.payment_protection_transactions;
  v_case_id uuid;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_subject_type='short_let' then
    select reservation.user_id=v_actor,reservation.stay_payment_protection_id,
      reservation.arrival_issue_deadline_at,reservation.arrival_issue_window_hours,
      reservation.checked_in_at,reservation.arrival_issue_policy_version_id
    into v_owner,v_protection_id,v_deadline,v_hours,v_checked_in_at,v_policy_id
    from public.reservations reservation where reservation.id=p_subject_id;
  elsif p_subject_type='hotel' then
    select booking.user_id=v_actor,booking.payment_protection_id,
      booking.arrival_issue_deadline_at,booking.arrival_issue_window_hours,
      booking.checked_in_at,booking.arrival_issue_policy_version_id
    into v_owner,v_protection_id,v_deadline,v_hours,v_checked_in_at,v_policy_id
    from public.hotel_bookings booking where booking.booking_id::text=p_subject_id;
  else raise exception 'Unsupported accommodation subject'; end if;
  if not coalesce(v_owner,false) then raise exception 'Booking participant access required'; end if;
  select * into v_protection from public.payment_protection_transactions
  where id=v_protection_id;
  select case_row.operational_case_id into v_case_id
  from public.operational_cases case_row
  where case_row.reason_code='arrival_issue' and case_row.subject_type=p_subject_type
    and case_row.subject_id=p_subject_id and case_row.requester_user_id=v_actor
    and case_row.status not in ('resolved','closed')
  order by case_row.created_at desc limit 1;
  return jsonb_build_object(
    'subject_type',p_subject_type,'subject_id',p_subject_id,
    'protection_state',v_protection.protection_state,
    'amount_total',v_protection.amount_total,
    'checked_in_at',v_checked_in_at,'arrival_issue_window_hours',v_hours,
    'arrival_issue_deadline_at',v_deadline,'policy_version_id',v_policy_id,
    'can_report_arrival_issue',v_checked_in_at is not null and v_deadline is not null
      and now()<=v_deadline and v_case_id is null
      and v_protection.protection_state in ('protected','release_eligible'),
    'arrival_issue_case_id',v_case_id
  );
end
$$;


--
-- Name: get_my_account_identity_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_account_identity_reference() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_check public.worker_identity_checks;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null
     or not (
       public.current_actor_has_workspace('worker',null)
       or public.current_actor_has_workspace('property_partner',null)
     ) then
    raise exception 'Worker or Property Partner workspace required';
  end if;
  select * into v_check
  from public.worker_identity_checks
  where worker_id=v_actor.user_id;
  return jsonb_build_object(
    'has_reference',coalesce(
      nullif(btrim(coalesce(v_check.enrollment_photo_path,'')),'') is not null,
      false
    ),
    'anchor_photo_path',v_check.enrollment_photo_path,
    'recent_photo_path',coalesce(
      v_check.latest_reference_photo_path,
      v_check.enrollment_photo_path
    ),
    'captured_at',v_check.captured_at,
    'status',coalesce(v_check.status,'not_started')
  );
end
$$;


--
-- Name: get_my_account_identity_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_account_identity_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_check public.worker_identity_checks;
  v_days integer:=public.account_identity_recheck_days();
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null
     or not (
       public.current_actor_has_workspace('worker',null)
       or public.current_actor_has_workspace('property_partner',null)
     ) then
    raise exception 'Worker or Property Partner workspace required';
  end if;
  select * into v_check
  from public.worker_identity_checks
  where worker_id=v_actor.user_id;
  return jsonb_build_object(
    'current',public.account_identity_is_current(v_actor.user_id),
    'enrolled',coalesce(
      nullif(btrim(coalesce(v_check.enrollment_photo_path,'')),'') is not null,
      false
    ),
    'status',coalesce(v_check.status,'not_started'),
    'recheck_days',v_days,
    'captured_at',v_check.captured_at,
    'due_at',case when v_check.captured_at is null then null
      else v_check.captured_at+make_interval(days=>v_days) end
  );
end
$$;


--
-- Name: get_my_active_device_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_active_device_sessions() RETURNS TABLE(id uuid, device text, browser text, os text, ip_address text, is_current boolean, login_time timestamp with time zone, last_seen timestamp with time zone, trust_status text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select
    session.id,
    session.device,
    session.browser,
    session.os,
    session.ip_address,
    session.auth_session_id = nullif((select auth.jwt() ->> 'session_id'), '') as is_current,
    session.login_time,
    session.last_seen,
    session.trust_status
  from public.user_sessions as session
  where session.user_id = public.current_profile_user_id()
    and session.auth_id = (select auth.uid())::text
    and session.is_active = true
    and session.trust_status = 'trusted'
  order by
    (session.auth_session_id = nullif((select auth.jwt() ->> 'session_id'), '')) desc,
    coalesce(session.last_seen, session.login_time) desc;
$$;


--
-- Name: get_my_active_private_calls(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_active_private_calls() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_me text:=public.current_profile_user_id(); result jsonb;
begin
  if v_me is null then raise exception 'Authenticated profile required'; end if;
  update public.private_calls
  set status='missed',ended_at=now()
  where v_me in(caller_id,callee_id)
    and status='ringing'
    and created_at < now() - interval '45 seconds';
  select coalesce(jsonb_agg(public.get_private_call_details(c.id) order by c.created_at desc),'[]'::jsonb)
    into result
  from public.private_calls c
  where v_me in(c.caller_id,c.callee_id) and c.status in('ringing','accepted');
  return result;
end;
$$;


--
-- Name: get_my_admin_staff_capacity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_admin_staff_capacity() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_limit integer:=0;
  v_used integer:=0;
BEGIN
  SELECT * INTO v_actor
  FROM public.profiles
  WHERE auth_id=auth.uid()::text
    AND role IN ('admin','creator')
    AND NOT COALESCE(deleted,false)
    AND NOT COALESCE(suspended,false)
    AND NOT COALESCE(banned,false)
  LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Admin or Creator access required'; END IF;

  v_limit:=COALESCE(public.get_admin_staff_limit_v2(),0);
  IF v_actor.role='admin' THEN
    SELECT count(*)::integer INTO v_used
    FROM public.profiles p
    WHERE p.role='staff'
      AND NOT COALESCE(p.deleted,false)
      AND lower(COALESCE(p.assigned_state,''))=lower(COALESCE(v_actor.assigned_state,''))
      AND lower(COALESCE(p.assigned_lga,''))=lower(COALESCE(v_actor.assigned_lga,''));
  END IF;

  RETURN jsonb_build_object(
    'limit',v_limit,
    'used',v_used,
    'remaining',CASE WHEN v_limit=0 THEN NULL ELSE GREATEST(0,v_limit-v_used) END,
    'unlimited',(v_limit=0)
  );
END;
$$;


--
-- Name: get_my_announcement_inbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_announcement_inbox() RETURNS TABLE(id bigint, announcement_id bigint, read_status boolean, delivered_at timestamp with time zone, announcement jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select ar.id, ar.announcement_id, coalesce(ar.read_status, false), ar.delivered_at,
    jsonb_build_object('id', a.id, 'title', a.title, 'content', a.content, 'sender_id', a.sender_id,
      'sender_role', a.sender_role, 'target_type', a.target_type, 'created_at', a.created_at)
  from public.announcement_recipients ar
  join public.announcements a on a.id = ar.announcement_id
  where ar.user_id = public.current_profile_user_id()
    and ar.delivered_at >= now() - interval '90 days'
  order by ar.delivered_at desc, ar.id desc
  limit 100;
$$;


--
-- Name: get_my_assigned_inspection_location(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_assigned_inspection_location(p_inspection_id uuid) RETURNS TABLE(gps_latitude numeric, gps_longitude numeric, location_accuracy_m numeric, property_address text, property_city text, property_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_actor record;
begin
 select user_id,role into v_actor from public.profiles where auth_id=auth.uid()::text limit 1;
 if v_actor is null or v_actor.role not in ('staff','admin','creator') then raise exception 'WeHouse access required'; end if;
 return query select ir.gps_latitude,ir.gps_longitude,ir.location_accuracy_m,ir.property_address,ir.property_city,ir.property_state from public.inspection_requests ir where ir.id=p_inspection_id and (v_actor.role in ('admin','creator') or coalesce(ir.assigned_field_officer_id,ir.field_officer_id,ir.assigned_to)=v_actor.user_id);
end $$;


--
-- Name: get_my_available_ledger_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_available_ledger_balance() RETURNS TABLE(currency text, available_balance numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  with actor as(select public.current_profile_user_id() user_id)
  select a.currency,round(-coalesce(sum(e.amount),0),2) available_balance
  from public.ledger_accounts a
  join public.ledger_entries e on e.ledger_account_id=a.ledger_account_id
  cross join actor
  where a.account_key='liability:payee_available:'||actor.user_id
  group by a.currency
$$;


--
-- Name: get_my_booking_conversations(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_booking_conversations(p_user_id text) RETURNS TABLE(conversation_id uuid, booking_id uuid, booking_code text, booking_status text, other_person_id text, other_person_name text, service_type text, negotiated_amount numeric, last_message text, unread_count bigint, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.profiles;
BEGIN
  a:=public._current_comm_actor();
  IF a IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_user_id IS DISTINCT FROM a.user_id THEN RAISE EXCEPTION 'User identity mismatch'; END IF;
  RETURN QUERY SELECT bc.id,bc.booking_id,wb.booking_code,wb.status,
    CASE WHEN bc.user_id=a.user_id THEN bc.worker_id ELSE bc.user_id END,
    p.full_name,wb.service_type,wb.negotiated_amount,
    (SELECT bm.content FROM public.booking_messages bm WHERE bm.conversation_id=bc.id ORDER BY bm.created_at DESC LIMIT 1),
    (SELECT count(*) FROM public.booking_messages bm WHERE bm.conversation_id=bc.id AND COALESCE(bm.is_read,false)=false AND bm.sender_id<>a.user_id),bc.updated_at
  FROM public.booking_conversations bc
  JOIN public.worker_bookings wb ON wb.id=bc.booking_id
  JOIN public.profiles p ON p.user_id=CASE WHEN bc.user_id=a.user_id THEN bc.worker_id ELSE bc.user_id END
  WHERE bc.user_id=a.user_id OR bc.worker_id=a.user_id
  ORDER BY bc.updated_at DESC;
END;
$$;


--
-- Name: get_my_booking_conversations_v2(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_booking_conversations_v2(p_user_id text) RETURNS TABLE(conversation_id uuid, booking_id uuid, booking_code text, booking_status text, service_type text, negotiated_amount numeric, other_person_id text, other_person_name text, other_person_avatar text, last_message text, last_message_time timestamp with time zone, unread_count bigint, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE a public.profiles;
BEGIN
  a:=public._current_comm_actor();
  IF a IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_user_id IS DISTINCT FROM a.user_id THEN RAISE EXCEPTION 'User identity mismatch'; END IF;

  RETURN QUERY
  SELECT
    bc.id,
    bc.booking_id,
    wb.booking_code,
    wb.status,
    wb.service_type,
    wb.negotiated_amount,
    CASE WHEN bc.user_id=a.user_id THEN bc.worker_id ELSE bc.user_id END,
    COALESCE(p.full_name,p.username,'WeHouse member'),
    p.avatar_url,
    CASE
      WHEN NULLIF(BTRIM(COALESCE(lm.content,'')),'') IS NOT NULL THEN lm.content
      WHEN COALESCE(cardinality(lm.attachments),0)>0 AND lm.attachments[1] ~* '\.(webm|m4a|mp3|wav|ogg)(\?|$)' THEN 'Voice message'
      WHEN COALESCE(cardinality(lm.attachments),0)>0 AND lm.attachments[1] ~* '\.(jpg|jpeg|png|gif|webp)(\?|$)' THEN 'Photo'
      WHEN COALESCE(cardinality(lm.attachments),0)>0 THEN 'Attachment'
      ELSE NULL
    END,
    lm.created_at,
    COALESCE(unread.count,0),
    GREATEST(bc.updated_at,COALESCE(lm.created_at,bc.updated_at))
  FROM public.booking_conversations bc
  JOIN public.worker_bookings wb ON wb.id=bc.booking_id
  JOIN public.profiles p ON p.user_id=CASE WHEN bc.user_id=a.user_id THEN bc.worker_id ELSE bc.user_id END
  LEFT JOIN LATERAL (
    SELECT bm.content,bm.attachments,bm.created_at
    FROM public.booking_messages bm
    WHERE bm.conversation_id=bc.id
    ORDER BY bm.created_at DESC
    LIMIT 1
  ) lm ON true
  LEFT JOIN LATERAL (
    SELECT count(*)::bigint AS count
    FROM public.booking_messages bm
    WHERE bm.conversation_id=bc.id
      AND COALESCE(bm.is_read,false)=false
      AND bm.sender_id<>a.user_id
  ) unread ON true
  WHERE (bc.user_id=a.user_id OR bc.worker_id=a.user_id)
    AND (
      (bc.user_id=a.user_id AND (bc.hidden_at_user IS NULL OR lm.created_at>bc.hidden_at_user))
      OR
      (bc.worker_id=a.user_id AND (bc.hidden_at_worker IS NULL OR lm.created_at>bc.hidden_at_worker))
    )
  ORDER BY GREATEST(bc.updated_at,COALESCE(lm.created_at,bc.updated_at)) DESC;
END;
$_$;


--
-- Name: get_my_booking_conversations_v3(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_booking_conversations_v3(p_user_id text) RETURNS TABLE(conversation_id uuid, booking_id uuid, booking_code text, booking_status text, service_type text, negotiated_amount numeric, other_person_id text, other_person_name text, other_person_avatar text, last_message text, last_message_time timestamp with time zone, unread_count bigint, updated_at timestamp with time zone, payment_status text, protection_status text, payment_protected boolean, money_state text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_actor public.profiles;
begin
  select profile.* into v_actor
  from public.profiles profile
  where profile.auth_id=(select auth.uid())::text
    and not coalesce(profile.deleted,false)
    and not coalesce(profile.suspended,false)
    and not coalesce(profile.banned,false)
  limit 1;

  if v_actor.user_id is null then
    raise exception 'Authentication required';
  end if;
  if p_user_id is distinct from v_actor.user_id then
    raise exception 'User identity mismatch';
  end if;

  return query
  select
    conversation.id,
    conversation.booking_id,
    booking.booking_code,
    booking.status,
    booking.service_type,
    booking.negotiated_amount,
    case when conversation.user_id=v_actor.user_id then conversation.worker_id else conversation.user_id end,
    coalesce(other_profile.full_name,other_profile.username,'WeHouse member'),
    other_profile.avatar_url,
    case
      when nullif(btrim(coalesce(latest_message.content,'')),'') is not null then latest_message.content
      when coalesce(cardinality(latest_message.attachments),0)>0
        and latest_message.attachments[1] ~* '\.(webm|m4a|mp3|wav|ogg)(\?|$)' then 'Voice message'
      when coalesce(cardinality(latest_message.attachments),0)>0
        and latest_message.attachments[1] ~* '\.(jpg|jpeg|png|gif|webp)(\?|$)' then 'Photo'
      when coalesce(cardinality(latest_message.attachments),0)>0 then 'Attachment'
      else null
    end,
    latest_message.created_at,
    coalesce(unread.count,0),
    greatest(conversation.updated_at,coalesce(latest_message.created_at,conversation.updated_at)),
    coalesce(current_payment.status,'not_started'),
    current_protection.status,
    lower(coalesce(current_protection.status,'')) in ('protected','payment_protected','secured','held','holding'),
    public.worker_booking_money_state(current_payment.status,current_protection.status)
  from public.booking_conversations conversation
  join public.worker_bookings booking on booking.id=conversation.booking_id
  join public.profiles other_profile on other_profile.user_id=
    case when conversation.user_id=v_actor.user_id then conversation.worker_id else conversation.user_id end
  left join lateral (
    select message.content,message.attachments,message.created_at
    from public.booking_messages message
    where message.conversation_id=conversation.id
    order by message.created_at desc,message.id desc
    limit 1
  ) latest_message on true
  left join lateral (
    select count(*)::bigint as count
    from public.booking_messages message
    where message.conversation_id=conversation.id
      and coalesce(message.is_read,false)=false
      and message.sender_id<>v_actor.user_id
  ) unread on true
  left join lateral (
    select payment.status
    from public.booking_payments payment
    where payment.worker_booking_id=booking.id
      and payment.purpose='worker_booking'
    order by case payment.status
      when 'review_required' then 0
      when 'refunded' then 1
      when 'reversed' then 1
      when 'paid' then 2
      when 'completed' then 2
      when 'pending' then 3
      when 'processing' then 3
      else 4
    end,
    payment.updated_at desc nulls last,
    payment.created_at desc nulls last,
    payment.id desc
    limit 1
  ) current_payment on true
  left join lateral (
    select protection.status
    from public.payment_protection_transactions protection
    where protection.booking_id=booking.id
      and protection.booking_type='worker_booking'
    order by protection.updated_at desc,protection.created_at desc,protection.id desc
    limit 1
  ) current_protection on true
  where (conversation.user_id=v_actor.user_id or conversation.worker_id=v_actor.user_id)
    and (
      (conversation.user_id=v_actor.user_id
        and (conversation.hidden_at_user is null or latest_message.created_at>conversation.hidden_at_user))
      or
      (conversation.worker_id=v_actor.user_id
        and (conversation.hidden_at_worker is null or latest_message.created_at>conversation.hidden_at_worker))
    )
  order by greatest(conversation.updated_at,coalesce(latest_message.created_at,conversation.updated_at)) desc;
end;
$_$;


--
-- Name: get_my_canonical_activity(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_canonical_activity(p_workspace text DEFAULT 'personal'::text, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, type text, title text, message text, read boolean, created_at timestamp with time zone, source_type text, source_id text, destination_route text, destination_params jsonb, workspace text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_user text:=public.current_profile_user_id();
begin
  if v_user is null then raise exception 'Authentication required'; end if;
  if p_workspace not in(
    'personal','account','worker','partner','property_partner','hotel',
    'staff','admin','creator','property_operations','field_operations',
    'worker_operations','finance_operations','security_operations','support'
  ) then raise exception 'Invalid Activity workspace'; end if;
  return query
  select e.activity_event_id,e.event_type,e.title,e.summary,
    a.read_at is not null,e.occurred_at,e.subject_type,e.subject_id,
    e.route,e.route_params,a.workspace
  from public.activity_event_audiences a
  join public.activity_events e on e.activity_event_id=a.activity_event_id
  where a.recipient_user_id=v_user
    and (
      (p_workspace='personal' and a.workspace in('personal','account'))
      or (p_workspace='partner' and a.workspace in('partner','property_partner'))
      or (p_workspace='hotel' and a.workspace in('hotel','hotel_staff'))
      or (p_workspace in(
        'property_operations','field_operations','worker_operations',
        'finance_operations','security_operations','support'
      ) and a.workspace in(p_workspace,'staff'))
      or (p_workspace not in('personal','partner','hotel',
        'property_operations','field_operations','worker_operations',
        'finance_operations','security_operations','support')
        and a.workspace=p_workspace)
    )
  order by e.occurred_at desc
  limit greatest(1,least(coalesce(p_limit,100),200));
end
$$;


--
-- Name: get_my_hotel_booking_conversations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_hotel_booking_conversations() RETURNS TABLE(conversation_id uuid, booking_id integer, hotel_id integer, hotel_name text, hotel_image text, booking_code text, booking_status text, payment_status text, check_in date, check_out date, room_name text, guest_user_id text, guest_name text, other_party_label text, last_message text, last_message_time timestamp with time zone, unread_count bigint, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  actor_id text;
begin
  select user_id into actor_id
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;

  if actor_id is null then
    raise exception 'Active WeHouse account required';
  end if;

  return query
  select
    conversation.id,
    booking.booking_id,
    hotel.hotel_id,
    hotel.name,
    hotel.images[1],
    null::text,
    booking.status,
    booking.payment_status,
    booking.check_in,
    booking.check_out,
    room.room_type,
    booking.user_id,
    coalesce(booking.guest_name,guest.full_name,guest.username,'Guest'),
    case
      when booking.user_id=actor_id then hotel.name
      else coalesce(booking.guest_name,guest.full_name,guest.username,'Guest')
    end,
    last_message.content,
    last_message.created_at,
    (
      select count(*)
      from public.hotel_booking_messages message
      where message.conversation_id=conversation.id
        and not message.is_read
        and message.sender_id<>actor_id
        and not actor_id=any(coalesce(message.hidden_for,'{}'::text[]))
    ),
    conversation.updated_at
  from public.hotel_booking_conversations conversation
  join public.hotel_bookings booking on booking.booking_id=conversation.booking_id
  join public.hotels hotel on hotel.hotel_id=conversation.hotel_id
  join public.hotel_rooms room on room.room_id=booking.room_id
  join public.profiles guest on guest.user_id=booking.user_id
  left join lateral (
    select
      case
        when nullif(btrim(message.content),'') is not null then message.content
        else 'Attachment'
      end as content,
      message.created_at
    from public.hotel_booking_messages message
    where message.conversation_id=conversation.id
      and not actor_id=any(coalesce(message.hidden_for,'{}'::text[]))
    order by message.created_at desc
    limit 1
  ) last_message on true
  where public.can_access_hotel_booking_conversation(conversation.id)
  order by greatest(conversation.updated_at,coalesce(last_message.created_at,conversation.updated_at)) desc;
end;
$$;


--
-- Name: get_my_hotel_bookings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_hotel_bookings() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_user text:=public.current_profile_user_id();
begin
  if v_user is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Active Personal account required';
  end if;
  return coalesce((
    select jsonb_agg(
      to_jsonb(booking)||jsonb_build_object(
        'hotels',(
          to_jsonb(hotel)-'address'-'gps_latitude'-'gps_longitude'
            -'owner_id'-'inspection_request_id'-'approved_by'
        )||jsonb_build_object(
          'address',case when booking.payment_status='paid'
            and booking.status in ('confirmed','checked_in','checked_out','completed')
            then hotel.address else null end,
          'gps_latitude',case when hotel.gps_latitude is null then null
            when booking.payment_status='paid'
              and booking.status in ('confirmed','checked_in','checked_out','completed')
            then hotel.gps_latitude else round(hotel.gps_latitude,2) end,
          'gps_longitude',case when hotel.gps_longitude is null then null
            when booking.payment_status='paid'
              and booking.status in ('confirmed','checked_in','checked_out','completed')
            then hotel.gps_longitude else round(hotel.gps_longitude,2) end,
          'location_exact',booking.payment_status='paid'
            and booking.status in ('confirmed','checked_in','checked_out','completed')
        ),
        'hotel_rooms',to_jsonb(room),
        'hotel_rate_plans',to_jsonb(rate_plan)
      ) order by booking.created_at desc
    )
    from public.hotel_bookings booking
    join public.hotels hotel on hotel.hotel_id=booking.hotel_id
    join public.hotel_rooms room on room.room_id=booking.room_id
    left join public.hotel_rate_plans rate_plan
      on rate_plan.rate_plan_id=booking.rate_plan_id
    where booking.user_id=v_user
  ),'[]'::jsonb);
end
$$;


--
-- Name: get_my_hotel_capabilities(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_hotel_capabilities(p_hotel_id integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user text:=public.current_profile_user_id();
  v_role text;
  v_caps text[];
begin
  if v_user is null then raise exception 'Active Personal account required'; end if;
  if exists(select 1 from public.hotels where hotel_id=p_hotel_id and owner_id=v_user) then
    v_role:='owner';
    v_caps:=public.hotel_default_capabilities('owner');
  else
    select member.hotel_role,member.capabilities into v_role,v_caps
    from public.hotel_team_members member
    where member.hotel_id=p_hotel_id and member.member_user_id=v_user
      and member.status='active'
    limit 1;
  end if;
  if v_role is null then raise exception 'Hotel access required'; end if;
  return jsonb_build_object(
    'hotel_id',p_hotel_id,'role',v_role,
    'capabilities',to_jsonb(coalesce(v_caps,array[]::text[]))
  );
end;
$$;


--
-- Name: get_my_hotel_integrations(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_hotel_integrations(p_hotel_id integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id(); v_result jsonb;
begin
  if v_actor is null or not exists(
    select 1 from public.hotels where hotel_id=p_hotel_id and owner_id=v_actor
  ) then raise exception 'Hotel owner access required'; end if;
  select coalesce(jsonb_agg(
    (to_jsonb(integration)-'token_hash')
      ||jsonb_build_object(
        'provider_name',provider.display_name,
        'provider_certification_status',provider.certification_status,
        'runtime_active',public.hotel_integration_runtime_active(integration.integration_id)
      )
    order by integration.created_at desc
  ),'[]'::jsonb)
  into v_result
  from public.hotel_integrations integration
  join public.hotel_pms_providers provider
    on provider.provider_key=integration.provider
  where integration.hotel_id=p_hotel_id;
  return v_result;
end;
$$;


--
-- Name: get_my_hotel_operations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_hotel_operations() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'hotel_id',hotel.hotel_id,'name',hotel.name,'description',hotel.description,
    'state',hotel.state,'city',hotel.city,'area',hotel.area,'address',hotel.address,
    'images',hotel.images,'amenities',hotel.amenities,'owner_id',hotel.owner_id,
    'status',hotel.status,'rating',hotel.rating,'review_count',hotel.review_count,
    'featured',hotel.featured,'check_in_time',hotel.check_in_time,
    'check_out_time',hotel.check_out_time,'timezone',hotel.timezone,
    'created_at',hotel.created_at,'updated_at',hotel.updated_at,
    'access_role',case when hotel.owner_id=profile.user_id then 'owner' else member.hotel_role end,
    'capabilities',case when hotel.owner_id=profile.user_id
      then to_jsonb(public.hotel_default_capabilities('owner'))
      else to_jsonb(coalesce(member.capabilities,array[]::text[])) end
  ) order by hotel.updated_at desc),'[]'::jsonb)
  from public.profiles profile
  join public.hotels hotel on hotel.owner_id=profile.user_id or exists(
    select 1 from public.hotel_team_members assigned
    where assigned.hotel_id=hotel.hotel_id
      and assigned.member_user_id=profile.user_id and assigned.status='active'
  )
  left join public.hotel_team_members member
    on member.hotel_id=hotel.hotel_id and member.member_user_id=profile.user_id
   and member.status='active'
  where profile.auth_id=(select auth.uid())::text
    and not coalesce(profile.deleted,false)
    and not coalesce(profile.suspended,false)
    and not coalesce(profile.banned,false)
$$;


--
-- Name: get_my_hotel_team(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_hotel_team(p_hotel_id integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_result jsonb;
begin
  if not public.hotel_actor_has_capability(p_hotel_id,'hotel.team.manage') then
    raise exception 'Hotel team management access required';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',member.id,'member_user_id',member.member_user_id,
    'hotel_role',member.hotel_role,'status',member.status,
    'capabilities',member.capabilities,
    'name',coalesce(profile.full_name,profile.username,'Team member'),
    'username',profile.username,'updated_at',member.updated_at
  ) order by case when member.status='invited' then 0 else 1 end,member.created_at),'[]'::jsonb)
  into v_result
  from public.hotel_team_members member
  join public.profiles profile on profile.user_id=member.member_user_id
  where member.hotel_id=p_hotel_id and member.status in ('invited','active');
  return v_result;
end;
$$;


--
-- Name: get_my_hotel_team_invitations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_hotel_team_invitations() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',tm.id,'hotel_id',h.hotel_id,'hotel_name',h.name,'hotel_image',h.images[1],
    'hotel_role',tm.hotel_role,'inviter_name',coalesce(owner.full_name,owner.username,'Hotel owner'),
    'created_at',tm.created_at
  ) order by tm.created_at desc),'[]'::jsonb)
  from public.profiles me
  join public.hotel_team_members tm on tm.member_user_id=me.user_id and tm.status='invited'
  join public.hotels h on h.hotel_id=tm.hotel_id
  left join public.profiles owner on owner.user_id=tm.invited_by
  where me.auth_id=(select auth.uid())::text and not coalesce(me.deleted,false)
    and not coalesce(me.suspended,false) and not coalesce(me.banned,false);
$$;


--
-- Name: get_my_housing_operations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_housing_operations() RETURNS TABLE(listing_id text, listing_title text, listing_status text, property_type text, sub_type text, state text, lga text, address text, annual_rent numeric, current_reservation_id text, reservation_status text, customer_user_id text, customer_name text, customer_username text, reservation_fee_paid boolean, payment_status text, rental_plan_years integer, contract_rent_total numeric, upfront_rent_required numeric, installment_balance numeric, installment_count integer, rent_payment_status text, rent_paid_at timestamp with time zone, hold_expires_at timestamp with time zone, requested_move_in_at timestamp with time zone, move_in_requested_at timestamp with time zone, tenancy_start_date date, tenancy_end_date date, move_out_grace_until date, occupied_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;
begin
  select * into v_actor from public.profiles
  where auth_id = (select auth.uid())::text and role in ('staff','admin','creator')
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor is null then raise exception 'Housing operations access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then
    raise exception 'Operations permission required';
  end if;

  return query
  select
    l.id::text,l.title,l.status,l.property_type,l.sub_type,l.state,l.city,l.address,l.price,
    r.id,r.status,r.user_id,coalesce(p.full_name,p.username,p.email),p.username,
    (coalesce(r.manual_payment_status,'unpaid') in ('paid','completed') and r.paid_at is not null),
    r.manual_payment_status,r.rental_plan_years,r.contract_rent_total,r.upfront_rent_required,
    r.installment_balance,r.installment_count,r.rent_payment_status,r.rent_paid_at,
    r.hold_expires_at,r.requested_move_in_at,r.move_in_requested_at,
    r.tenancy_start_date,r.tenancy_end_date,r.move_out_grace_until,l.occupied_at
  from public.reservations r
  join public.listings l on l.id::text=r.listing_id or l.listing_id=r.listing_id
  left join public.profiles p on p.user_id=r.user_id
  where coalesce(r.stay_type,'long_stay')='long_stay'
    and r.status not in ('cancelled','expired')
    and (v_actor.role='creator' or public.current_actor_in_scope(l.state,l.city))
  order by
    case r.status
      when 'payment_conflict' then 1 when 'ready_for_move_in' then 2
      when 'inspection_pending' then 3 when 'reserved' then 4
      when 'payment_pending' then 5 when 'occupied' then 6 else 7
    end,
    r.updated_at desc;
end;
$$;


--
-- Name: get_my_inspections(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_inspections(p_field_officer_id text) RETURNS TABLE(id uuid, inspection_code text, property_address text, property_city text, property_state text, property_type text, status text, owner_id text, owner_name text, owner_email text, owner_phone text, notes text, field_officer_id text, partner_id text, scheduled_date timestamp with time zone, completed_at timestamp with time zone, created_at timestamp with time zone, photo_urls text[], document_urls text[], video_urls text[], _source text, gps_latitude numeric, gps_longitude numeric, location_accuracy_m numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
begin
  select *
  into v_actor
  from public.profiles
  where auth_id = auth.uid()::text
  limit 1;

  if v_actor is null
     or v_actor.role <> 'staff'
     or v_actor.user_id <> p_field_officer_id
     or not public.current_staff_has_permission('field_officer') then
    raise exception 'Field Operations access required';
  end if;

  return query
  select
    ir.id,
    ir.request_code,
    ir.property_address,
    ir.property_city,
    ir.property_state,
    ir.property_type,
    ir.status,
    ir.owner_id,
    coalesce(p.full_name, p.username, p.email),
    ir.owner_email,
    ir.owner_phone,
    ir.notes,
    coalesce(ir.assigned_field_officer_id, ir.field_officer_id, ir.assigned_to),
    ir.partner_id::text,
    ir.scheduled_date::timestamptz,
    ir.completed_at,
    ir.created_at,
    ir.field_photo_urls,
    ir.document_urls,
    ir.field_video_urls,
    'partner'::text,
    ir.gps_latitude,
    ir.gps_longitude,
    ir.location_accuracy_m
  from public.inspection_requests ir
  left join public.profiles p on p.user_id = ir.owner_id
  where coalesce(ir.assigned_field_officer_id, ir.field_officer_id, ir.assigned_to)
        = v_actor.user_id

  union all

  select
    ur.id,
    coalesce(ur.reservation_id, ur.id::text),
    coalesce(l.address, l.title, 'Reserved property'),
    l.city,
    l.state,
    l.property_type::text,
    ur.status,
    ur.user_id,
    coalesce(u.full_name, u.username, u.email),
    u.email,
    u.phone,
    ur.notes,
    ur.field_officer_id,
    null::text,
    ur.scheduled_date,
    null::timestamptz,
    ur.created_at,
    ur.photo_urls,
    array[]::text[],
    ur.video_urls,
    'user'::text,
    l.gps_latitude,
    l.gps_longitude,
    null::numeric
  from public.user_inspection_requests ur
  left join public.listings l
    on l.listing_id = ur.listing_id
    or l.id::text = ur.listing_id
  left join public.profiles u on u.user_id = ur.user_id
  where ur.field_officer_id = v_actor.user_id
  order by created_at desc;
end;
$$;


--
-- Name: get_my_ledger_statement(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_ledger_statement(p_limit integer DEFAULT 100, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE(ledger_transaction_id uuid, transaction_type text, reference_type text, reference_id text, amount numeric, currency text, posted_at timestamp with time zone, metadata jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  with actor as(select public.current_profile_user_id() user_id)
  select t.ledger_transaction_id,t.transaction_type,t.reference_type,
    t.reference_id,e.amount,t.currency,t.posted_at,t.metadata
  from public.ledger_entries e
  join public.ledger_accounts a on a.ledger_account_id=e.ledger_account_id
  join public.ledger_transactions t
    on t.ledger_transaction_id=e.ledger_transaction_id
  cross join actor
  where a.owner_id=actor.user_id
    and (p_before is null or t.posted_at<p_before)
  order by t.posted_at desc,t.ledger_transaction_id
  limit least(greatest(coalesce(p_limit,100),1),250)
$$;


--
-- Name: get_my_legal_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_legal_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user text:=public.current_profile_user_id();
  v_documents jsonb;
  v_privacy uuid;
  v_terms uuid;
begin
  if v_user is null then raise exception 'Authentication required'; end if;
  v_documents:=public.get_current_legal_documents();
  v_privacy:=nullif(v_documents#>>'{privacy,policy_version_id}','')::uuid;
  v_terms:=nullif(v_documents#>>'{terms,policy_version_id}','')::uuid;
  return jsonb_build_object(
    'privacy_accepted',v_privacy is not null and exists(
      select 1 from public.policy_acceptance_receipts
      where user_id=v_user and policy_version_id=v_privacy),
    'terms_accepted',v_terms is not null and exists(
      select 1 from public.policy_acceptance_receipts
      where user_id=v_user and policy_version_id=v_terms),
    'privacy_version_id',v_privacy,'terms_version_id',v_terms,
    'privacy_version',v_documents#>'{privacy,version}',
    'terms_version',v_documents#>'{terms,version}'
  );
end
$$;


--
-- Name: get_my_operations_inbox_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_operations_inbox_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_actor public.profiles;
  v_message_unread bigint := 0;
  v_event_unread bigint := 0;
  v_announcement_unread bigint := 0;
  v_latest_title text;
  v_latest_created_at timestamptz;
begin
  select * into v_actor from public.profiles
  where auth_id = auth.uid()::text
    and not coalesce(deleted, false)
    and not coalesce(suspended, false)
    and not coalesce(banned, false)
  limit 1;
  if v_actor is null or not (
    v_actor.role in ('creator', 'admin')
    or (v_actor.role = 'staff' and public.current_staff_has_permission('operations'))
  ) then raise exception 'Property Operations access required'; end if;

  select coalesce(sum(inbox.unread_count), 0) into v_message_unread
  from public.support_inbox('reservation_operations') inbox;

  select count(*) into v_event_unread
  from public.notifications n
  where n.recipient_id = v_actor.user_id and not n.read
    and n.created_at >= now() - case when n.type ~* '(security|device_login|payment|payout|earning|dispute|refund)' then interval '90 days' else interval '30 days' end
    and not (
      n.type = 'missed_call'
      or (
        n.type !~* '(price|payment|accepted|declined|cancel|complete|scheduled|security|verification|match|invite|reservation|booking|payout|earning|status)'
        and (
          n.type ~* '(^|_)(message|reply|replied|chat)(_|$)'
          or (n.destination_route = 'conversation' and coalesce(n.source_type, '') ~* '(conversation|message|chat)')
        )
      )
    );

  select count(*) into v_announcement_unread
  from public.announcement_recipients ar
  where ar.user_id = v_actor.user_id and not coalesce(ar.read_status, false)
    and ar.delivered_at >= now() - interval '90 days';

  select recent.title, recent.created_at into v_latest_title, v_latest_created_at
  from (
    select n.title, n.created_at
    from public.notifications n
    where n.recipient_id = v_actor.user_id
      and n.created_at >= now() - case when n.type ~* '(security|device_login|payment|payout|earning|dispute|refund)' then interval '90 days' else interval '30 days' end
      and not (
        n.type = 'missed_call'
        or (
          n.type !~* '(price|payment|accepted|declined|cancel|complete|scheduled|security|verification|match|invite|reservation|booking|payout|earning|status)'
          and (
            n.type ~* '(^|_)(message|reply|replied|chat)(_|$)'
            or (n.destination_route = 'conversation' and coalesce(n.source_type, '') ~* '(conversation|message|chat)')
          )
        )
      )
    union all
    select a.title, ar.delivered_at
    from public.announcement_recipients ar
    join public.announcements a on a.id = ar.announcement_id
    where ar.user_id = v_actor.user_id and ar.delivered_at >= now() - interval '90 days'
  ) recent
  order by recent.created_at desc
  limit 1;

  return jsonb_build_object(
    'message_unread', v_message_unread,
    'activity_unread', v_event_unread + v_announcement_unread,
    'latest_title', v_latest_title,
    'latest_created_at', v_latest_created_at
  );
end;
$_$;


--
-- Name: get_my_private_call_preferences(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_private_call_preferences() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_me text := public.current_profile_user_id(); v_pref public.private_call_preferences;
begin
  if v_me is null then raise exception 'Authenticated profile required'; end if;
  select * into v_pref from public.private_call_preferences where user_id = v_me;
  return jsonb_build_object(
    'allow_audio_calls', coalesce(v_pref.allow_audio_calls, true),
    'allow_video_calls', coalesce(v_pref.allow_video_calls, true)
  );
end;
$$;


--
-- Name: get_my_property_partner_finance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_property_partner_finance() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id text:=public.current_profile_user_id(); v_wallet public.wallets;
  v_min numeric:=5000; v_long numeric; v_short numeric; v_hotel numeric;
  v_total_earnings numeric:=0;
begin
  if v_user_id is null or not public.current_actor_has_workspace('property_partner',null)
    then raise exception 'Property Partner workspace required'; end if;
  perform public.ensure_my_property_partner_wallet();
  select * into v_wallet from public.wallets
  where owner_id=v_user_id and owner_type='property_partner';
  select coalesce(nullif(value,'')::numeric,5000) into v_min
  from public.platform_settings where key='min_withdrawal'
    and coalesce(is_active,true) limit 1;
  select (value->>'percent')::numeric into v_long
  from public.creator_policy_versions where policy_key='commission_long_let'
    and scope_type='global' and scope_key='*' and status='active'
    and effective_from<=now() and (effective_until is null or effective_until>now())
  order by effective_from desc limit 1;
  select (value->>'percent')::numeric into v_short
  from public.creator_policy_versions where policy_key='commission_short_let'
    and scope_type='global' and scope_key='*' and status='active'
    and effective_from<=now() and (effective_until is null or effective_until>now())
  order by effective_from desc limit 1;
  select (value->>'percent')::numeric into v_hotel
  from public.creator_policy_versions where policy_key='commission_hotel'
    and scope_type='global' and scope_key='*' and status='active'
    and effective_from<=now() and (effective_until is null or effective_until>now())
  order by effective_from desc limit 1;
  select coalesce(sum(amount),0) into v_total_earnings
  from public.wallet_transactions where user_id=v_user_id
    and transaction_type in('property_earning_pending','property_earning_released');
  return jsonb_build_object(
    'wallet_id',v_wallet.id,'available_balance',coalesce(v_wallet.available_balance,0),
    'pending_balance',coalesce(v_wallet.pending_balance,0),
    'frozen_balance',coalesce(v_wallet.frozen_balance,0),
    'total_withdrawn',coalesce(v_wallet.total_withdrawn,0),
    'is_frozen',coalesce(v_wallet.is_frozen,false),
    'long_let_commission_rate',v_long,'short_let_commission_rate',v_short,
    'hotel_commission_rate',v_hotel,'total_earnings',v_total_earnings,
    'minimum_withdrawal',coalesce(v_min,5000)
  );
end
$$;


--
-- Name: get_my_property_partner_stays(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_property_partner_stays(p_listing_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id(); v_result jsonb;
begin
  if v_actor is null or not public.current_actor_has_workspace('property_partner',null)
    then raise exception 'Property Partner workspace required'; end if;
  select coalesce(jsonb_agg(to_jsonb(stay) order by stay.created_at desc),'[]'::jsonb)
  into v_result from (
    select r.id reservation_id,r.booking_code,
      coalesce(r.stay_type,'long_stay') stay_type,r.status,
      r.rent_payment_status payment_status,r.rent_paid_at,
      r.stay_check_in check_in,r.stay_check_out check_out,r.stay_nights nights,
      coalesce(r.guest_count,1) guest_count,r.requested_move_in_at,
      r.move_in_requested_at,r.tenancy_start_date,r.tenancy_end_date,r.created_at,
      l.id::text listing_id,l.listing_id public_listing_code,l.title listing_title
    from public.reservations r join public.listings l on l.id::text=r.listing_id
    where (l.owner_id=v_actor or l.partner_id=v_actor)
      and (p_listing_id is null or l.id::text=p_listing_id or l.listing_id=p_listing_id)
      and ((coalesce(r.stay_type,'long_stay')='short_let'
        and ((r.rent_payment_status='paid' and r.rent_paid_at is not null)
          or r.status in('occupied','completed')))
        or (coalesce(r.stay_type,'long_stay')<>'short_let'
          and ((r.rent_payment_status in('paid','upfront_paid') and r.rent_paid_at is not null)
            or r.status in('occupied','completed'))))
    order by r.created_at desc limit 50
  ) stay;
  return v_result;
end
$$;


--
-- Name: get_my_property_pipeline(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_property_pipeline(p_stage text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_result jsonb;
begin
  select * into v_actor from public.profiles
  where auth_id = auth.uid()::text
    and not coalesce(deleted, false)
    and not coalesce(suspended, false)
    and not coalesce(banned, false)
  limit 1;
  if v_actor is null or v_actor.role not in ('admin', 'creator', 'staff') then
    raise exception 'WeHouse operations access required';
  end if;
  if v_actor.role = 'staff' and not public.current_staff_has_permission('operations') then
    raise exception 'Property Operations permission required';
  end if;
  if v_actor.role in ('admin', 'staff')
     and (v_actor.assigned_state is null or v_actor.assigned_lga is null) then
    raise exception 'Branch assignment required';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',ir.id,'request_code',ir.request_code,'owner_id',ir.owner_id,
    'owner_name',coalesce(owner.full_name,owner.username,owner.email),'owner_email',ir.owner_email,'owner_phone',ir.owner_phone,
    'property_address',ir.property_address,'property_city',ir.property_city,'property_state',ir.property_state,
    'property_type',ir.property_type,'sub_type',ir.sub_type,'bedrooms',ir.bedrooms,'bathrooms',ir.bathrooms,
    'expected_rent',ir.expected_rent,'security_deposit_amount',ir.security_deposit_amount,'amenities',ir.amenities,
    'description',ir.description,'status',ir.status,'scheduled_date',ir.scheduled_date,
    'assigned_field_officer_id',coalesce(ir.assigned_field_officer_id,ir.field_officer_id,ir.assigned_to),
    'field_officer_name',coalesce(officer.full_name,officer.username,officer.email),'notes',ir.notes,
    'photo_urls',ir.photo_urls,'video_urls',ir.video_urls,'document_urls',ir.document_urls,
    'gps_latitude',ir.gps_latitude,'gps_longitude',ir.gps_longitude,
    'draft_listing_id',ir.draft_listing_id,'draft_hotel_id',ir.draft_hotel_id,
    'approved_by',ir.approved_by,'approved_at',ir.approved_at,'published_at',ir.published_at,
    'listing',case when l.id is null then null else jsonb_build_object(
      'id',l.id,'listing_id',l.listing_id,'title',l.title,'price',l.price,'status',l.status,
      'availability_status',l.availability_status,'sub_type',l.sub_type,
      'security_deposit_amount',l.security_deposit_amount,'amenities',l.amenities,
      'images',l.images,'videos',l.videos,'created_at',l.created_at
    ) end,
    'hotel',case when h.hotel_id is null then null else jsonb_build_object(
      'hotel_id',h.hotel_id,'name',h.name,'status',h.status,'images',h.images,'created_at',h.created_at
    ) end,
    'created_at',ir.created_at
  ) order by ir.created_at desc),'[]'::jsonb) into v_result
  from public.inspection_requests ir
  left join public.profiles owner on owner.user_id = ir.owner_id
  left join public.profiles officer
    on officer.user_id = coalesce(ir.assigned_field_officer_id,ir.field_officer_id,ir.assigned_to)
  left join public.listings l on l.id = ir.draft_listing_id and l.deleted_at is null
  left join public.hotels h on h.hotel_id = ir.draft_hotel_id
  where (
    v_actor.role = 'creator'
    or (
      public.wehouse_state_key(ir.property_state) = public.wehouse_state_key(v_actor.assigned_state)
      and public.wehouse_lga_key(ir.property_city) = public.wehouse_lga_key(v_actor.assigned_lga)
    )
  )
  and (p_stage = 'all'
    or (p_stage = 'new' and ir.status = 'pending'
        and coalesce(ir.assigned_field_officer_id,ir.field_officer_id,ir.assigned_to) is null)
    or (p_stage = 'inspection' and ir.status in ('pending','scheduled','in_progress')
        and coalesce(ir.assigned_field_officer_id,ir.field_officer_id,ir.assigned_to) is not null)
    or (p_stage = 'ready' and ir.status in ('completed','approved')
        and ir.draft_listing_id is null and ir.draft_hotel_id is null)
    or (p_stage = 'preparing' and (ir.draft_listing_id is not null or ir.draft_hotel_id is not null)
        and ir.published_at is null)
    or (p_stage = 'published' and ir.published_at is not null)
    or (p_stage = 'rejected' and ir.status = 'rejected'));
  return v_result;
end;
$$;


--
-- Name: get_my_property_pipeline_v2(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_property_pipeline_v2(p_stage text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(
    item||jsonb_build_object(
      'property_display_name',ir.property_display_name,
      'submission_schema_version',ir.submission_schema_version,
      'submission_batch_id',ir.submission_batch_id,
      'hotel_program',coalesce(ir.hotel_program,'{}'::jsonb),
      'lifecycle_stage',ir.lifecycle_stage,
      'field_evidence_review_status',ir.field_evidence_review_status,
      'field_evidence_reviewed_by',ir.field_evidence_reviewed_by,
      'field_evidence_reviewed_at',ir.field_evidence_reviewed_at,
      'field_evidence_review_note',ir.field_evidence_review_note,
      'final_media_reviewed_at',ir.final_media_reviewed_at,
      'final_media_reviewed_by',ir.final_media_reviewed_by,
      'final_media_sources',ir.final_media_sources,
      'final_hotel_media_sources',ir.final_hotel_media_sources,
      'final_room_media_sources',ir.final_room_media_sources
    ) order by (item->>'created_at')::timestamptz desc
  ),'[]'::jsonb)
  from jsonb_array_elements(public.get_my_property_pipeline('all')) item
  join public.inspection_requests ir on ir.id=(item->>'id')::uuid
  where p_stage='all'
    or (p_stage='new' and ir.lifecycle_stage in ('access_required','access_review','inspection_ready'))
    or (p_stage='inspection' and ir.lifecycle_stage='inspection')
    or (p_stage='review' and ir.lifecycle_stage='awaiting_review')
    or (p_stage='ready' and ir.lifecycle_stage='ready_to_prepare')
    or (p_stage='preparing' and ir.lifecycle_stage='listing_prepared')
    or (p_stage='published' and ir.lifecycle_stage='live')
    or (p_stage='rejected' and ir.lifecycle_stage in ('changes_requested','rejected'));
$$;


--
-- Name: get_my_received_roommate_interests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_received_roommate_interests() RETURNS TABLE(interest_id uuid, sender_user_id text, match_score integer, sent_at timestamp with time zone, username text, full_name text, avatar_url text, city text, state text, school text, bio text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_actor_prefs public.roommate_preferences;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text limit 1;
  if v_actor is null or not public.current_actor_has_personal_workspace()
     or coalesce(v_actor.deleted,false)
     or coalesce(v_actor.suspended,false)
     or coalesce(v_actor.banned,false)
    then raise exception 'Active regular user required'; end if;
  select * into v_actor_prefs from public.roommate_preferences
  where user_id=v_actor.user_id limit 1;

  return query
  select
    incoming.id,incoming.searcher_id,incoming.match_score,incoming.updated_at,
    sender.username,sender.full_name,sender.avatar_url,sender.city,sender.state,
    case
      when coalesce(v_actor_prefs.school_match,false)
       and coalesce(sender_prefs.school_match,false)
       and lower(regexp_replace(btrim(coalesce(v_actor_prefs.school_name,v_actor.school,'')),'\s+',' ','g'))
         =lower(regexp_replace(btrim(coalesce(sender_prefs.school_name,sender.school,'')),'\s+',' ','g'))
      then nullif(btrim(coalesce(sender_prefs.school_name,sender.school,'')),'')
      else null
    end,
    sender.bio
  from public.roommate_search_results incoming
  join public.profiles sender on sender.user_id=incoming.searcher_id
  left join public.roommate_preferences sender_prefs
    on sender_prefs.user_id=sender.user_id
  left join public.roommate_search_results response
    on response.searcher_id=v_actor.user_id
   and response.matched_user_id=incoming.searcher_id
  where incoming.matched_user_id=v_actor.user_id
    and incoming.status='accepted'
    and coalesce(response.status,'new') not in('accepted','declined')
    and not coalesce(sender.deleted,false)
    and not coalesce(sender.suspended,false)
    and not coalesce(sender.banned,false)
    and coalesce(sender.privacy_profile_visible,true)
    and not exists(
      select 1 from public.roommate_user_blocks blocked_pair
      where (blocked_pair.blocker_user_id=v_actor.user_id
          and blocked_pair.blocked_user_id=sender.user_id)
        or (blocked_pair.blocker_user_id=sender.user_id
          and blocked_pair.blocked_user_id=v_actor.user_id)
    )
    and not exists(
      select 1 from public.conversations conversation
      where conversation.conversation_type='roommate'
        and conversation.status='active'
        and ((conversation.participant_a=v_actor.user_id
            and conversation.participant_b=incoming.searcher_id)
          or (conversation.participant_b=v_actor.user_id
            and conversation.participant_a=incoming.searcher_id))
    )
  order by incoming.updated_at desc;
end
$$;


--
-- Name: get_my_reservation_for_listing(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_reservation_for_listing(p_listing_id text) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user_id text; v_listing_id text; v_result public.reservations;
BEGIN
  SELECT user_id INTO v_user_id FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT id::text INTO v_listing_id FROM public.listings WHERE id::text=p_listing_id OR listing_id=p_listing_id LIMIT 1;
  IF v_listing_id IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_result FROM public.reservations
  WHERE listing_id=v_listing_id AND user_id=v_user_id
    AND status = ANY (ARRAY['payment_pending','reserved','inspection_pending','ready_for_move_in','occupied']::text[])
  ORDER BY created_at DESC LIMIT 1;
  RETURN v_result;
END;
$$;


--
-- Name: get_my_roommate_conversation_people(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_roommate_conversation_people() RETURNS TABLE(conversation_id uuid, user_id text, full_name text, username text, avatar_url text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  a public.profiles;
begin
  select * into a
  from public.profiles
  where auth_id = auth.uid()::text
  limit 1;

  if a is null or not public.current_actor_has_personal_workspace()
     or coalesce(a.deleted,false)
     or coalesce(a.suspended,false)
     or coalesce(a.banned,false) then
    raise exception 'Active regular user required';
  end if;

  return query
  select
    c.id,
    p.user_id,
    p.full_name,
    p.username,
    p.avatar_url
  from public.conversations c
  join public.profiles p
    on p.user_id = case when c.participant_a = a.user_id then c.participant_b else c.participant_a end
  where c.conversation_type = 'roommate'
    and coalesce(c.status,'active') = 'active'
    and a.user_id in (c.participant_a,c.participant_b)
    and coalesce(p.deleted,false)=false
    and coalesce(p.suspended,false)=false
    and coalesce(p.banned,false)=false
    and p.account_kind='consumer'
    and public._conversation_route_allowed(c.id,a.user_id)
  order by c.last_message_at desc nulls last, c.created_at desc;
end;
$$;


--
-- Name: get_my_roommate_matches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_roommate_matches() RETURNS TABLE(id uuid, matched_user_id text, match_score integer, status text, created_at timestamp with time zone, username text, full_name text, avatar_url text, gender text, city text, state text, bio text, school text, area_preference text, mutual_accepted boolean, conversation_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from public.get_my_roommate_matches_page(24,0);
$$;


--
-- Name: get_my_roommate_matches_page(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_roommate_matches_page(p_limit integer DEFAULT 24, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, matched_user_id text, match_score integer, status text, created_at timestamp with time zone, username text, full_name text, avatar_url text, gender text, city text, state text, bio text, school text, area_preference text, budget_score integer, location_score integer, cleanliness_score integer, noise_score integer, visitors_score integer, stay_score integer, mutual_accepted boolean, conversation_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles; v_prefs public.roommate_preferences; v_school text;
  v_state text; v_lga text;
  v_limit integer:=greatest(1,least(coalesce(p_limit,24),50));
  v_offset integer:=greatest(0,coalesce(p_offset,0));
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text limit 1;
  if v_actor is null or not public.current_actor_has_personal_workspace()
    then raise exception 'Regular user required'; end if;
  if coalesce(v_actor.deleted,false) or coalesce(v_actor.suspended,false)
     or coalesce(v_actor.banned,false)
    then raise exception 'Account is not active'; end if;
  select * into v_prefs from public.roommate_preferences
  where user_id=v_actor.user_id limit 1;
  if v_prefs is null then raise exception 'Roommate preferences required'; end if;
  v_school:=nullif(btrim(coalesce(v_prefs.school_name,v_actor.school,'')),'');
  v_state:=nullif(btrim(coalesce(v_actor.state,'')),'');
  v_lga:=nullif(btrim(coalesce(v_actor.local_government,v_actor.city,'')),'');
  if v_state is null or v_lga is null
    then raise exception 'State and LGA are required for roommate matching'; end if;

  return query with scored as (
    select
      result.id result_id,result.matched_user_id result_user_id,
      result.status result_status,result.created_at result_created_at,
      peer.username profile_username,peer.full_name profile_full_name,
      peer.avatar_url profile_avatar_url,peer.gender profile_gender,
      peer.city profile_city,peer.state profile_state,peer.bio profile_bio,
      case when coalesce(v_prefs.school_match,false)
        and coalesce(peer_prefs.school_match,false)
        then coalesce(peer_prefs.school_name,peer.school) else null end profile_school,
      peer_prefs.area_preference preference_area,
      round(30*(greatest(0,least(peer_prefs.budget_max,v_prefs.budget_max)
        -greatest(peer_prefs.budget_min,v_prefs.budget_min)+1)::numeric
        /greatest(1,least(peer_prefs.budget_max-peer_prefs.budget_min+1,
          v_prefs.budget_max-v_prefs.budget_min+1))))::integer budget_points,
      20::integer location_points,
      case when lower(coalesce(peer_prefs.cleanliness,''))=
        lower(coalesce(v_prefs.cleanliness,'')) then 15 else 0 end cleanliness_points,
      case when lower(coalesce(peer_prefs.noise_level,''))=
        lower(coalesce(v_prefs.noise_level,'')) then 15 else 0 end noise_points,
      case when lower(coalesce(peer_prefs.visitors,''))=
        lower(coalesce(v_prefs.visitors,'')) then 10 else 0 end visitors_points,
      case when lower(coalesce(peer_prefs.stay_duration,''))=
        lower(coalesce(v_prefs.stay_duration,'')) then 10 else 0 end stay_points
    from public.roommate_search_results result
    join public.profiles peer on peer.user_id=result.matched_user_id
    join public.roommate_preferences peer_prefs on peer_prefs.user_id=peer.user_id
    where result.searcher_id=v_actor.user_id and result.status<>'declined'
      and not coalesce(peer.deleted,false)
      and not coalesce(peer.suspended,false)
      and not coalesce(peer.banned,false)
      and lower(btrim(coalesce(peer.state,'')))=lower(v_state)
      and lower(btrim(coalesce(peer.local_government,peer.city,'')))=lower(v_lga)
      and (not coalesce(v_prefs.school_match,false)
        or lower(regexp_replace(btrim(coalesce(peer_prefs.school_name,peer.school,'')),'\s+',' ','g'))
          =lower(regexp_replace(v_school,'\s+',' ','g')))
      and (result.status='accepted' or (
        coalesce(peer.privacy_search_visible,true)
        and coalesce(peer.privacy_profile_visible,true)
        and coalesce(peer_prefs.active,false)
        and peer_prefs.search_status='active'))
      and not exists(
        select 1 from public.roommate_user_blocks blocked_pair
        where (blocked_pair.blocker_user_id=v_actor.user_id
            and blocked_pair.blocked_user_id=peer.user_id)
          or (blocked_pair.blocker_user_id=peer.user_id
            and blocked_pair.blocked_user_id=v_actor.user_id)
      )
  ), ranked as (
    select scored.*,
      least(100,budget_points+location_points+cleanliness_points
        +noise_points+visitors_points+stay_points)::integer current_score
    from scored
  )
  select
    ranked.result_id,ranked.result_user_id,ranked.current_score,
    ranked.result_status,ranked.result_created_at,ranked.profile_username,
    ranked.profile_full_name,ranked.profile_avatar_url,ranked.profile_gender,
    ranked.profile_city,ranked.profile_state,ranked.profile_bio,
    ranked.profile_school,ranked.preference_area,ranked.budget_points,
    ranked.location_points,ranked.cleanliness_points,ranked.noise_points,
    ranked.visitors_points,ranked.stay_points,
    exists(select 1 from public.roommate_search_results response
      where response.searcher_id=ranked.result_user_id
        and response.matched_user_id=v_actor.user_id
        and response.status='accepted'),
    (select conversation.id from public.conversations conversation
      where conversation.conversation_type='roommate'
        and conversation.status='active'
        and ((conversation.participant_a=v_actor.user_id
            and conversation.participant_b=ranked.result_user_id)
          or (conversation.participant_b=v_actor.user_id
            and conversation.participant_a=ranked.result_user_id)) limit 1)
  from ranked
  order by ranked.current_score desc,ranked.result_created_at desc,
    ranked.result_id limit v_limit offset v_offset;
end
$$;


--
-- Name: get_my_roommate_peer_details(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_roommate_peer_details() RETURNS TABLE(conversation_id uuid, user_id text, full_name text, username text, avatar_url text, bio text, city text, state text, school text, occupation text, is_student boolean, is_blocked boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  actor public.profiles;
  actor_prefs public.roommate_preferences;
begin
  actor := public._current_comm_actor();
  if actor is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Regular user account required';
  end if;

  select preferences.* into actor_prefs
  from public.roommate_preferences preferences
  where preferences.user_id=actor.user_id
  limit 1;

  return query
  select
    conversation.id,
    peer.user_id,
    peer.full_name,
    peer.username,
    peer.avatar_url,
    peer.bio,
    peer.city,
    peer.state,
    case
      when coalesce(actor_prefs.school_match,false)
       and coalesce(peer_prefs.school_match,false)
       and lower(regexp_replace(btrim(coalesce(actor_prefs.school_name,actor.school,'')),'\s+',' ','g'))
           = lower(regexp_replace(btrim(coalesce(peer_prefs.school_name,peer.school,'')),'\s+',' ','g'))
      then nullif(btrim(coalesce(peer_prefs.school_name,peer.school,'')),'')
      else null
    end,
    peer.occupation,
    peer.is_student,
    exists(
      select 1
      from public.roommate_user_blocks blocks
      where blocks.blocker_user_id=actor.user_id
        and blocks.blocked_user_id=peer.user_id
    )
  from public.conversations conversation
  join public.profiles peer
    on peer.user_id=case
      when conversation.participant_a=actor.user_id then conversation.participant_b
      else conversation.participant_a
    end
  left join public.roommate_preferences peer_prefs on peer_prefs.user_id=peer.user_id
  where conversation.conversation_type='roommate'
    and coalesce(conversation.status,'active')='active'
    and actor.user_id in (conversation.participant_a,conversation.participant_b)
    and coalesce(peer.deleted,false)=false
    and coalesce(peer.suspended,false)=false
    and coalesce(peer.banned,false)=false
    and peer.account_kind='consumer'
    and public._conversation_route_allowed(conversation.id,actor.user_id)
  order by conversation.last_message_at desc nulls last,conversation.created_at desc;
end
$$;


--
-- Name: roommate_preferences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.roommate_preferences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id text NOT NULL,
    auth_id text NOT NULL,
    gender text NOT NULL,
    gender_preference text DEFAULT 'no_preference'::text NOT NULL,
    budget_min integer DEFAULT 0,
    budget_max integer DEFAULT 500000,
    study_level text,
    noise_level text DEFAULT 'moderate'::text,
    cleanliness text DEFAULT 'moderate'::text,
    sleep_time text DEFAULT '11pm-12am'::text,
    visitors text DEFAULT 'sometimes'::text,
    stay_duration text DEFAULT '1_year'::text,
    area_preference text,
    bio text,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    search_status text DEFAULT 'idle'::text NOT NULL,
    search_started_at timestamp with time zone,
    search_expires_at timestamp with time zone,
    search_match_count integer DEFAULT 0 NOT NULL,
    campus text,
    school_name text,
    level text,
    department text,
    school_match boolean DEFAULT false NOT NULL,
    CONSTRAINT roommate_preferences_search_status_check CHECK ((search_status = ANY (ARRAY['idle'::text, 'active'::text, 'expired'::text, 'stopped'::text])))
);


--
-- Name: get_my_roommate_preferences(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_roommate_preferences() RETURNS SETOF public.roommate_preferences
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_actor IS NULL OR not public.current_actor_has_personal_workspace() OR COALESCE(v_actor.deleted,false) OR COALESCE(v_actor.suspended,false) OR COALESCE(v_actor.banned,false) THEN
    RETURN;
  END IF;
  RETURN QUERY SELECT rp.* FROM public.roommate_preferences rp WHERE rp.user_id=v_actor.user_id LIMIT 1;
END;
$$;


--
-- Name: get_my_shared_housing_group(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_shared_housing_group(p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id(); v_result jsonb;
begin
  if v_actor is null or not exists(select 1 from public.shared_housing_members
    where group_id=p_group_id and user_id=v_actor) then
    raise exception 'Shared-payment access required'; end if;
  select jsonb_build_object(
    'id',g.id,'created_by',g.created_by,'conversation_id',g.conversation_id,
    'listing_id',g.listing_id,'status',g.status,'product_type',g.product_type,
    'payment_phase',g.payment_phase,'expires_at',g.expires_at,
    'total_amount',g.total_amount,'reservation_fee_total',g.reservation_fee_total,
    'contract_total',g.contract_total,'reservation_id',g.reservation_id,
    'capacity',case when g.product_type='short_let' then l.max_guests else l.max_occupants end,
    'guest_count',g.guest_count,'stay_check_in',g.stay_check_in,'stay_check_out',g.stay_check_out,
    'listing',jsonb_build_object(
      'id',l.id,'title',l.title,'price',l.price,'image',l.images[1],
      'address',l.address,'city',l.city,'state',l.state,
      'available',l.deleted_at is null and l.status='available'
        and l.availability_status='available'
    ),
    'members',coalesce((select jsonb_agg(jsonb_build_object(
      'user_id',m.user_id,'name',coalesce(p.full_name,p.username,'Roommate'),
      'invitation_status',m.invitation_status,'share_amount',m.share_amount,
      'eligible_partner_share',m.eligible_partner_share,
      'refundable_share',m.refundable_share,
      'payment_status',m.payment_status,'paid_at',m.paid_at
    ) order by m.created_at,m.id)
    from public.shared_housing_members m left join public.profiles p on p.user_id=m.user_id
    where m.group_id=g.id),'[]'::jsonb)
  ) into v_result
  from public.shared_housing_groups g join public.listings l on l.id=g.listing_id
  where g.id=p_group_id;
  return v_result;
end
$$;


--
-- Name: get_my_shared_housing_groups(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_shared_housing_groups() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_agg(public.get_my_shared_housing_group(m.group_id)
    order by m.created_at desc),'[]'::jsonb)
  from public.shared_housing_members m
  where m.user_id=public.current_profile_user_id()
$$;


--
-- Name: get_my_short_stay_operations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_short_stay_operations() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor public.profiles; v_result jsonb;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND role IN ('staff','admin','creator')
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Housing operations access required'; END IF;
  IF v_actor.role='staff' AND NOT public.current_staff_has_permission('operations') THEN RAISE EXCEPTION 'Operations permission required'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'reservation_id',r.id,'booking_code',r.booking_code,'status',r.status,'payment_status',r.rent_payment_status,
    'check_in',r.stay_check_in,'check_out',r.stay_check_out,'nights',r.stay_nights,'nightly_rate',r.nightly_rate_snapshot,
    'stay_rent_total',r.stay_rent_total,'security_deposit',r.security_deposit_snapshot,'security_deposit_status',r.security_deposit_status,
    'customer_user_id',r.user_id,'customer_name',COALESCE(p.full_name,p.username,p.email),'customer_phone',p.phone,
    'listing_id',l.id,'listing_title',l.title,'state',l.state,'lga',l.city,'address',l.address,'listing_status',l.status
  ) ORDER BY r.stay_check_in ASC,r.created_at ASC),'[]'::jsonb) INTO v_result
  FROM public.reservations r
  JOIN public.listings l ON l.id::text=r.listing_id
  LEFT JOIN public.profiles p ON p.user_id=r.user_id
  WHERE r.stay_type='short_let'
    AND r.status IN ('payment_pending','reserved','inspection_pending','ready_for_move_in','occupied')
    AND (v_actor.role='creator' OR public.current_actor_in_scope(l.state,l.city));
  RETURN v_result;
END;
$$;


--
-- Name: get_my_short_stay_operations_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_short_stay_operations_v2() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_result jsonb;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and role in ('staff','admin','creator')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null then raise exception 'Housing operations access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then raise exception 'Operations permission required'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'reservation_id',r.id,
    'booking_code',r.booking_code,
    'status',r.status,
    'payment_status',r.rent_payment_status,
    'reservation_fee_paid',(r.manual_payment_status in ('paid','completed') and r.paid_at is not null),
    'check_in',r.stay_check_in,
    'check_out',r.stay_check_out,
    'nights',r.stay_nights,
    'guest_count',coalesce(r.guest_count,1),
    'nightly_rate',r.nightly_rate_snapshot,
    'stay_rent_total',r.stay_rent_total,
    'security_deposit',r.security_deposit_snapshot,
    'security_deposit_status',r.security_deposit_status,
    'customer_user_id',r.user_id,
    'customer_name',coalesce(p.full_name,p.username,p.email),
    'customer_phone',p.phone,
    'listing_id',l.id,
    'listing_title',l.title,
    'state',l.state,
    'lga',l.city,
    'address',l.address,
    'listing_status',case when r.status='occupied' then 'occupied' else l.status end,
    'publication_status',l.status
  ) order by r.stay_check_in asc,r.created_at asc),'[]'::jsonb)
  into v_result
  from public.reservations r
  join public.listings l on l.id::text=r.listing_id
  left join public.profiles p on p.user_id=r.user_id
  where r.stay_type='short_let'
    and r.status in ('payment_pending','reserved','inspection_pending','ready_for_move_in','occupied')
    and (v_actor.role='creator' or public.current_actor_in_scope(l.state,l.city));
  return v_result;
end;
$$;


--
-- Name: get_my_staff_finance_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_staff_finance_queue() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_payments jsonb;v_withdrawals jsonb;v_commissions jsonb;
  v_payment_protection jsonb;v_refunds jsonb;v_audit jsonb;
begin
  select * into v_actor from public.profiles where auth_id=(select auth.uid())::text
    and role in ('staff','admin','creator') and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null then raise exception 'Active finance account required'; end if;
  if v_actor.role in ('staff','admin') and not exists(
        select 1 from public.staff_permissions sp
        where sp.staff_id=v_actor.user_id and sp.permission='finance' and sp.is_active
      ) then raise exception 'Finance permission required'; end if;
  if v_actor.role in ('staff','admin') and (v_actor.assigned_state is null or v_actor.assigned_lga is null) then raise exception 'Branch assignment required'; end if;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_payments from (
    select bp.id,bp.payment_reference,bp.type,bp.booking_type,bp.amount,bp.amount_total,
      bp.amount_commission,bp.net_amount,bp.currency,bp.status,bp.purpose,bp.payment_method,
      bp.paystack_reference,bp.verified_at,bp.paid_at,bp.created_at
    from public.booking_payments bp
    where v_actor.role='creator' or public.can_current_actor_read_profile(bp.user_id)
      or public.can_current_actor_read_profile(bp.payer_user_id) or public.can_current_actor_read_profile(bp.payee_user_id)
      or (bp.listing_id is not null and public.current_actor_can_access_listing_ref(bp.listing_id))
    order by bp.created_at desc limit 100
  ) x;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_withdrawals from (
    select wd.id,wd.amount,wd.status,wd.snapshot_bank_name,wd.snapshot_bank_account_number,
      wd.snapshot_bank_account_name,wd.paystack_transfer_reference,wd.paystack_transfer_code,
      wd.paystack_status,wd.reviewed_by,wd.reviewed_at,wd.processed_at,wd.failed_reason,
      wd.finalized_at,wd.created_at,w.owner_id,w.owner_type,
      coalesce(p.full_name,p.username,p.email) owner_name
    from public.withdrawals wd join public.wallets w on w.id=wd.wallet_id
    left join public.profiles p on p.user_id=w.owner_id
    where v_actor.role='creator' or public.can_current_actor_read_profile(w.owner_id)
    order by wd.created_at desc limit 100
  ) x;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_commissions from (
    select c.id,c.booking_type,c.commission_amount,c.commission_rate,c.gross_amount,
      c.description,c.paystack_reference,c.status,c.created_at
    from public.commission_ledger c
    where v_actor.role='creator' or public.can_current_actor_read_profile(c.source_user_id)
    order by c.created_at desc limit 100
  ) x;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_payment_protection from (
    select t.id,t.booking_id,t.booking_type,t.amount_total,t.amount_commission,t.amount_payee,
      t.commission_rate,t.status,t.released_at,t.released_by,t.paystack_reference,t.created_at
    from public.payment_protection_transactions t
    where v_actor.role='creator' or public.can_current_actor_read_profile(t.payer_user_id)
      or public.can_current_actor_read_profile(t.payee_user_id)
    order by t.created_at desc limit 100
  ) x;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_refunds from (
    select bp.id,bp.payment_reference,bp.booking_type,bp.amount_total,bp.status,
      bp.refund_reason,bp.refund_processed_at,bp.refund_reference,bp.created_at
    from public.booking_payments bp
    where (bp.refund_reason is not null or bp.refund_processed_at is not null
      or bp.refund_reference is not null or lower(coalesce(bp.status,'')) like 'refund%')
      and (v_actor.role='creator' or public.can_current_actor_read_profile(bp.user_id)
        or public.can_current_actor_read_profile(bp.payer_user_id) or public.can_current_actor_read_profile(bp.payee_user_id)
        or (bp.listing_id is not null and public.current_actor_can_access_listing_ref(bp.listing_id)))
    order by bp.created_at desc limit 100
  ) x;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_audit from (
    select a.id,a.action,a.actor_role,a.target_type,a.target_id,a.amount,a.commission_amount,
      a.description,a.status_before,a.status_after,a.failure_reason,a.created_at
    from public.financial_audit_log a
    where v_actor.role='creator' or (a.target_user_id is not null and public.can_current_actor_read_profile(a.target_user_id))
    order by a.created_at desc limit 100
  ) x;
  return jsonb_build_object('payments',v_payments,'withdrawals',v_withdrawals,
    'commissions',v_commissions,'payment_protection',v_payment_protection,
    'refunds',v_refunds,'audit',v_audit);
end;
$$;


--
-- Name: get_my_staff_operations_listings(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_staff_operations_listings(p_status text DEFAULT NULL::text) RETURNS SETOF public.listings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor public.profiles;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text
    AND role IN ('staff','admin','creator') AND COALESCE(deleted,false)=false
    AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Active operations account required'; END IF;
  IF v_actor.role='staff' AND NOT public.current_staff_has_permission('operations') THEN RAISE EXCEPTION 'Operations permission required'; END IF;
  IF v_actor.role IN ('staff','admin') AND (v_actor.assigned_state IS NULL OR v_actor.assigned_lga IS NULL) THEN RAISE EXCEPTION 'Branch assignment required'; END IF;
  RETURN QUERY SELECT l.* FROM public.listings l
  WHERE l.deleted_at IS NULL AND (p_status IS NULL OR p_status='all' OR l.status=p_status)
    AND (v_actor.role='creator' OR (lower(COALESCE(l.state,''))=lower(v_actor.assigned_state)
      AND lower(COALESCE(l.city,''))=lower(v_actor.assigned_lga)))
  ORDER BY l.created_at DESC;
END;
$$;


--
-- Name: get_my_staff_security_monitor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_staff_security_monitor() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE v_actor public.profiles; v_result jsonb;
BEGIN
  SELECT * INTO v_actor FROM public.profiles p
  WHERE p.auth_id=auth.uid()::text AND p.role='staff' AND NOT COALESCE(p.deleted,false) AND NOT COALESCE(p.suspended,false) AND NOT COALESCE(p.banned,false) LIMIT 1;
  IF v_actor IS NULL OR NOT EXISTS(SELECT 1 FROM public.staff_permissions sp WHERE sp.staff_id=v_actor.user_id AND sp.permission='security' AND sp.is_active=true AND sp.revoked_at IS NULL) THEN RAISE EXCEPTION 'Security Staff permission required'; END IF;
  IF NULLIF(btrim(v_actor.assigned_state),'') IS NULL OR NULLIF(btrim(v_actor.assigned_lga),'') IS NULL THEN RAISE EXCEPTION 'Security Staff branch assignment is incomplete'; END IF;

  WITH scoped_profiles AS (
    SELECT p.* FROM public.profiles p WHERE lower(COALESCE(NULLIF(p.assigned_state,''),NULLIF(p.state,''),''))=lower(v_actor.assigned_state)
      AND lower(COALESCE(NULLIF(p.assigned_lga,''),NULLIF(p.local_government,''),NULLIF(p.city,''),''))=lower(v_actor.assigned_lga)
  ), recent_sessions AS (
    SELECT s.*,p.full_name,p.username,p.role FROM public.user_sessions s JOIN scoped_profiles p ON p.user_id=s.user_id WHERE s.login_time>=now()-interval '30 days'
  ), multi_ip AS (
    SELECT user_id,COALESCE(max(full_name),max(username),'Account') name,count(DISTINCT ip_address) locations FROM recent_sessions WHERE is_active=true AND NULLIF(ip_address,'') IS NOT NULL GROUP BY user_id HAVING count(DISTINCT ip_address)>=2
  ), bursts AS (
    SELECT user_id,COALESCE(max(full_name),max(username),'Account') name,count(*) attempts FROM recent_sessions WHERE login_time>=now()-interval '60 minutes' GROUP BY user_id HAVING count(*)>=5
  ), restricted AS (
    SELECT count(*)::integer total FROM scoped_profiles WHERE COALESCE(banned,false) OR COALESCE(suspended,false) OR COALESCE(deleted,false)
  ), alerts AS (
    SELECT jsonb_build_object('kind','multiple_locations','severity','high','title','Concurrent location pattern','detail',name||' has '||locations||' active network locations. Review the session trail and escalate if the user does not recognise them.') item FROM multi_ip
    UNION ALL
    SELECT jsonb_build_object('kind','login_burst','severity','high','title','Rapid sign-in pattern','detail',name||' recorded '||attempts||' session starts within the last hour. Confirm context before escalation.') FROM bursts
  ), auth_events AS (
    SELECT a.id,a.created_at,COALESCE(a.payload->>'action','authentication_event') action,COALESCE(p.full_name,p.username,'Branch account') name
    FROM auth.audit_log_entries a JOIN scoped_profiles p ON p.auth_id=COALESCE(a.payload->>'user_id',a.payload->>'actor_id')
    WHERE a.created_at>=now()-interval '30 days' ORDER BY a.created_at DESC LIMIT 50
  )
  SELECT jsonb_build_object(
    'stats',jsonb_build_object('active_sessions',(SELECT count(*) FROM recent_sessions WHERE is_active=true),'multi_ip_accounts',(SELECT count(*) FROM multi_ip),'login_bursts',(SELECT count(*) FROM bursts),'restricted_accounts',(SELECT total FROM restricted)),
    'alerts',COALESCE((SELECT jsonb_agg(item) FROM alerts),'[]'::jsonb),
    'sessions',COALESCE((SELECT jsonb_agg(x ORDER BY x.last_seen DESC) FROM (SELECT id session_id,COALESCE(full_name,username,'Branch account') name,role,device,browser,os,is_active,last_seen,login_time FROM recent_sessions ORDER BY last_seen DESC NULLS LAST LIMIT 50) x),'[]'::jsonb),
    'admin_actions',COALESCE((SELECT jsonb_agg(x ORDER BY x.created_at DESC) FROM (SELECT a.id,a.action,a.target_type,a.target_id,a.details,a.admin_id actor_id,a.admin_email actor_email,a.created_at FROM public.admin_audit_log a LEFT JOIN public.profiles actor ON actor.user_id=a.admin_id WHERE a.created_at>=now()-interval '30 days' AND lower(COALESCE(NULLIF(actor.assigned_state,''),v_actor.assigned_state))=lower(v_actor.assigned_state) AND lower(COALESCE(NULLIF(actor.assigned_lga,''),v_actor.assigned_lga))=lower(v_actor.assigned_lga) ORDER BY a.created_at DESC LIMIT 50) x),'[]'::jsonb),
    'auth_events',COALESCE((SELECT jsonb_agg(auth_events ORDER BY created_at DESC) FROM auth_events),'[]'::jsonb),
    'auth_audit_available',true
  ) INTO v_result;
  RETURN v_result;
END;
$$;


--
-- Name: get_my_staff_trust_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_staff_trust_status() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_staff public.profiles; v_trust public.staff_trust_profiles;
BEGIN
  SELECT * INTO v_staff FROM public.profiles
  WHERE auth_id=auth.uid()::text AND role='staff'
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false
  LIMIT 1;
  IF v_staff IS NULL THEN RAISE EXCEPTION 'Active Staff account required'; END IF;
  SELECT * INTO v_trust FROM public.staff_trust_profiles WHERE staff_id=v_staff.user_id;
  IF v_trust IS NULL THEN
    INSERT INTO public.staff_trust_profiles(staff_id,status,appointed_at,notes)
    VALUES(v_staff.user_id,'probation',now(),'Staff trust record created automatically') RETURNING * INTO v_trust;
  END IF;
  RETURN jsonb_build_object('status',v_trust.status,'notes',v_trust.notes,'appointed_at',v_trust.appointed_at,'trusted_at',v_trust.trusted_at);
END;
$$;


--
-- Name: get_my_staff_worker_review_detail(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_staff_worker_review_detail(p_worker_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ DECLARE v_ver jsonb; v_history jsonb; BEGIN IF NOT public.current_staff_can_review_worker(p_worker_id) THEN RAISE EXCEPTION 'Worker is outside your verification scope'; END IF; SELECT jsonb_build_object('certificate_path',v.certificate_path,'verification_video_url',v.verification_video_url,'years_of_experience',v.years_of_experience,'identity_status',COALESCE(v.identity_status,'not_started'),'identity_provider',v.identity_provider,'identity_reference',v.identity_reference,'identity_checked_at',v.identity_checked_at,'identity_failure_reason',v.identity_failure_reason) INTO v_ver FROM public.worker_verifications v WHERE v.worker_id=p_worker_id ORDER BY v.created_at DESC LIMIT 1; SELECT COALESCE(jsonb_agg(jsonb_build_object('id',r.id,'action',r.action,'rejection_reason',r.rejection_reason,'notes',r.notes,'reviewer_role',r.reviewer_role,'created_at',r.created_at) ORDER BY r.created_at DESC),'[]'::jsonb) INTO v_history FROM (SELECT * FROM public.worker_verification_reviews WHERE worker_id=p_worker_id ORDER BY created_at DESC LIMIT 12) r; RETURN jsonb_build_object('verification',COALESCE(v_ver,'{}'::jsonb),'history',COALESCE(v_history,'[]'::jsonb)); END; $$;


--
-- Name: get_my_staff_worker_review_queue(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_staff_worker_review_queue(p_status text DEFAULT 'profile_under_review'::text) RETURNS TABLE(user_id text, username text, full_name text, worker_occupation text, worker_experience text, worker_cert_url text, worker_video_url text, state text, local_government text, city text, worker_status text, avatar_url text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ DECLARE v_actor public.profiles; BEGIN SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND role='staff' AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1; IF v_actor IS NULL OR NOT public.current_staff_has_permission('verification') THEN RAISE EXCEPTION 'Verification Staff access required'; END IF; IF v_actor.assigned_state IS NULL OR v_actor.assigned_lga IS NULL THEN RAISE EXCEPTION 'Staff branch assignment required'; END IF; RETURN QUERY SELECT w.user_id,w.username,w.full_name,w.worker_occupation,w.worker_experience,w.worker_cert_url,w.worker_video_url,w.state,w.local_government,w.city,w.worker_status,w.avatar_url FROM public.profiles w WHERE w.role='worker' AND COALESCE(w.deleted,false)=false AND COALESCE(w.suspended,false)=false AND COALESCE(w.banned,false)=false AND (p_status IS NULL OR p_status='all' OR w.worker_status=p_status) AND lower(COALESCE(w.state,''))=lower(v_actor.assigned_state) AND lower(COALESCE(w.local_government,w.city,''))=lower(v_actor.assigned_lga) ORDER BY w.created_at DESC; END; $$;


--
-- Name: get_my_staff_worker_reviews(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_staff_worker_reviews(p_status text DEFAULT 'pending'::text) RETURNS SETOF public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_actor record; BEGIN SELECT user_id,role,assigned_state,assigned_lga,deleted,suspended,banned INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1; IF v_actor IS NULL OR COALESCE(v_actor.deleted,false) OR COALESCE(v_actor.suspended,false) OR COALESCE(v_actor.banned,false) THEN RAISE EXCEPTION 'Active staff account required'; END IF; IF v_actor.role='staff' AND NOT public.current_staff_has_permission('verification') THEN RAISE EXCEPTION 'Verification permission required'; END IF; IF v_actor.role NOT IN('staff','admin','creator') THEN RAISE EXCEPTION 'Staff access required'; END IF; RETURN QUERY SELECT w.* FROM public.profiles w WHERE w.role='worker' AND NOT COALESCE(w.deleted,false) AND (p_status IS NULL OR p_status='all' OR w.worker_status=p_status) AND (v_actor.role IN('admin','creator') OR (v_actor.assigned_state IS NOT NULL AND lower(w.state)=lower(v_actor.assigned_state) AND (v_actor.assigned_lga IS NULL OR lower(COALESCE(w.local_government,w.city))=lower(v_actor.assigned_lga)))) ORDER BY w.created_at DESC; END; $$;


--
-- Name: get_my_support_case_events(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_support_case_events(p_conversation_id uuid) RETURNS TABLE(id uuid, event_type text, actor_id text, actor_name text, actor_role text, from_status text, to_status text, note text, metadata jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.current_actor_can_access_operational_conversation(
    p_conversation_id,false
  ) then raise exception 'Not authorised'; end if;
  return query
  select e.id,e.event_type,e.actor_id,
    coalesce(p.full_name,p.username,e.metadata->>'actor_name','WeHouse'),p.role,
    e.from_status,e.to_status,e.note,coalesce(e.metadata,'{}'::jsonb),e.created_at
  from public.support_case_events e
  left join public.profiles p on p.user_id=e.actor_id
  where e.conversation_id=p_conversation_id
  order by e.created_at;
end
$$;


--
-- Name: get_my_support_conversations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_support_conversations() RETURNS TABLE(conversation_id uuid, subject text, status text, category text, context_type text, context_id text, context_snapshot jsonb, priority text, assigned_staff_name text, last_message text, last_message_time timestamp with time zone, unread_count bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles;
begin
  select * into v_actor
  from public.profiles
  where auth_id=auth.uid()::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null then raise exception 'Authentication required'; end if;
  return query
  select
    c.id,
    coalesce(nullif(btrim(c.subject),''),'WeHouse Help')::text,
    c.status,
    c.category,
    c.context_type,
    c.context_id,
    coalesce(c.context_snapshot,'{}'::jsonb)||jsonb_build_object('case_number',c.case_number),
    c.priority,
    coalesce(s.full_name,s.username),
    (select case
      when nullif(btrim(m.content),'') is not null then m.content
      when coalesce(cardinality(m.attachments),0)>0 then 'Attachment'
      else '' end
     from public.partner_support_messages m
     where m.conversation_id=c.id
     order by m.created_at desc limit 1),
    (select m.created_at from public.partner_support_messages m where m.conversation_id=c.id order by m.created_at desc limit 1),
    (select count(*) from public.partner_support_messages m where m.conversation_id=c.id and not coalesce(m.is_read,false) and m.sender_id<>v_actor.user_id),
    c.created_at
  from public.partner_support_conversations c
  left join public.profiles s on s.user_id=c.assigned_staff_id
  where c.partner_id=v_actor.user_id
    and exists(select 1 from public.partner_support_messages first_message where first_message.conversation_id=c.id)
  order by coalesce((select max(latest.created_at) from public.partner_support_messages latest where latest.conversation_id=c.id),c.created_at) desc;
end;
$$;


--
-- Name: get_my_worker_activation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_activation() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_profile public.profiles;
  v_ver public.worker_verifications;
  v_identity public.worker_identity_checks;
  v_profile_ready boolean:=false;
  v_identity_required boolean:=false;
  v_identity_current boolean:=true;
  v_marketplace_enabled boolean:=false;
  v_days integer:=public.worker_identity_recheck_days();
  v_due_at timestamptz;
  v_days_remaining integer;
  v_pro_active boolean:=false;
begin
  select * into v_profile from public.profiles
  where auth_id=(select auth.uid())::text and public.user_has_active_workspace(user_id,'worker') limit 1;
  if v_profile is null then raise exception 'Worker profile not found'; end if;
  select coalesce(lower(value) in ('true','1','yes','on'),false) into v_identity_required
  from public.platform_settings where key='worker_identity_checks_enabled' and is_active=true limit 1;
  select coalesce(lower(value) in ('true','1','yes','on'),false) into v_marketplace_enabled
  from public.platform_settings where key='worker_marketplace_launch_enabled' and is_active=true limit 1;
  v_profile_ready:=public.worker_professional_profile_ready(v_profile.user_id);
  select * into v_ver from public.worker_verifications where worker_id=v_profile.user_id order by created_at desc limit 1;
  select * into v_identity from public.worker_identity_checks where worker_id=v_profile.user_id;
  if coalesce(v_identity_required,false) then
    v_identity_current:=false;
    if v_identity.status='passed' and v_identity.captured_at is not null then
      v_due_at:=v_identity.captured_at+make_interval(days=>v_days);
      v_identity_current:=v_due_at>now();
      v_days_remaining:=greatest(0,ceil(extract(epoch from (v_due_at-now()))/86400.0)::integer);
    end if;
  end if;
  v_pro_active:=public.worker_pro_is_active(v_profile.user_id);
  return jsonb_build_object(
    'worker_status',coalesce(v_profile.worker_status,'pending'),
    'reviewed',coalesce(v_profile.worker_status='verified' and v_profile.worker_verified,false),
    'live',coalesce(v_profile.worker_status='verified' and v_profile.worker_verified and v_identity_current and v_marketplace_enabled,false),
    'marketplace_enabled',coalesce(v_marketplace_enabled,false),
    'profile_complete',v_profile_ready,
    'payment_status','not_required',
    'payment_required',false,
    'payment_confirmed',true,
    'fee_waived',true,
    'gold_badge',v_pro_active,
    'pro_active',v_pro_active,
    'identity_required',coalesce(v_identity_required,false),
    'identity_status',case
      when not coalesce(v_identity_required,false) then 'not_required'
      when v_identity.status='passed' and not v_identity_current then 'expired'
      else coalesce(v_identity.status,'not_started')
    end,
    'identity_captured',coalesce(v_identity.status='passed',false),
    'identity_passed',v_identity_current,
    'identity_current',v_identity_current,
    'identity_captured_at',v_identity.captured_at,
    'identity_due_at',v_due_at,
    'identity_recheck_days',v_days,
    'identity_days_remaining',v_days_remaining,
    'test_passed',true,'test_percent',100,'test_attempts_24h',0,
    'evidence_saved',coalesce(nullif(btrim(coalesce(v_ver.verification_video_url,'')),'') is not null,false),
    'submitted',coalesce(v_profile.worker_status='profile_under_review' and v_ver.submitted_at is not null,false),
    'review_status',v_ver.status,
    'rejection_reason',(select rejection_reason from public.worker_verification_reviews where worker_id=v_profile.user_id order by created_at desc limit 1)
  );
end;
$$;


--
-- Name: get_my_worker_block_state(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_block_state(p_user_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id();
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if not exists(select 1 from public.worker_bookings b where (b.user_id=v_actor and b.worker_id=p_user_id) or (b.user_id=p_user_id and b.worker_id=v_actor)) then raise exception 'Worker booking relationship required'; end if;
  return jsonb_build_object(
    'blocked_by_me',exists(select 1 from public.worker_user_blocks where blocker_user_id=v_actor and blocked_user_id=p_user_id),
    'blocked_me',exists(select 1 from public.worker_user_blocks where blocker_user_id=p_user_id and blocked_user_id=v_actor)
  );
end;
$$;


--
-- Name: get_my_worker_block_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_block_state(p_conversation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_me text := public.current_profile_user_id(); v_peer text;
begin
  if v_me is null then raise exception 'Authenticated profile required'; end if;
  select case when c.user_id=v_me then c.worker_id else c.user_id end into v_peer
  from public.booking_conversations c where c.id=p_conversation_id and v_me in (c.user_id,c.worker_id) limit 1;
  if v_peer is null then raise exception 'Worker conversation unavailable'; end if;
  return exists(select 1 from public.worker_user_blocks where blocker_user_id=v_me and blocked_user_id=v_peer);
end; $$;


--
-- Name: get_my_worker_booking_details(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_booking_details(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_booking public.worker_bookings;
  v_customer public.profiles;
  v_worker public.profiles;
  v_payment_status text;
  v_protection_status text;
begin
  select profile.* into v_actor
  from public.profiles profile
  where profile.auth_id=(select auth.uid())::text
    and not coalesce(profile.deleted,false)
    and not coalesce(profile.suspended,false)
    and not coalesce(profile.banned,false)
  limit 1;
  if v_actor.user_id is null then raise exception 'Authentication required'; end if;

  select * into v_booking from public.worker_bookings where id=p_booking_id;
  if v_booking.id is null then return null; end if;
  if v_actor.user_id is distinct from v_booking.user_id
     and v_actor.user_id is distinct from v_booking.worker_id then
    raise exception 'Booking participant access required';
  end if;

  select * into v_customer from public.profiles where user_id=v_booking.user_id limit 1;
  select * into v_worker from public.profiles where user_id=v_booking.worker_id limit 1;

  select payment.status into v_payment_status
  from public.booking_payments payment
  where payment.worker_booking_id=v_booking.id
    and payment.purpose='worker_booking'
  order by case payment.status
    when 'review_required' then 0
    when 'refunded' then 1
    when 'reversed' then 1
    when 'paid' then 2
    when 'completed' then 2
    when 'pending' then 3
    when 'processing' then 3
    else 4
  end,
  payment.updated_at desc nulls last,
  payment.created_at desc nulls last,
  payment.id desc
  limit 1;

  select protection.status into v_protection_status
  from public.payment_protection_transactions protection
  where protection.booking_id=v_booking.id
    and protection.booking_type='worker_booking'
  order by protection.updated_at desc,protection.created_at desc,protection.id desc
  limit 1;

  return jsonb_build_object(
    'id',v_booking.id,'booking_code',v_booking.booking_code,'status',v_booking.status,
    'service_type',v_booking.service_type,'description',v_booking.description,
    'customer_message',v_booking.customer_message,'request_attachments',v_booking.request_attachments,
    'address',v_booking.address,'service_latitude',v_booking.service_latitude,
    'service_longitude',v_booking.service_longitude,
    'service_location_accuracy_m',v_booking.service_location_accuracy_m,
    'service_location_source',v_booking.service_location_source,
    'scheduled_date',v_booking.scheduled_date,'negotiated_amount',v_booking.negotiated_amount,
    'agreed_amount',v_booking.agreed_amount,'wehouse_fee',v_booking.wehouse_fee,
    'worker_receives',v_booking.worker_receives,
    'payment_status',coalesce(v_payment_status,'not_started'),
    'protection_status',v_protection_status,
    'money_state',public.worker_booking_money_state(v_payment_status,v_protection_status),
    'payment_review_required',coalesce(v_payment_status='review_required',false),
    'payment_protected',lower(coalesce(v_protection_status,'')) in
      ('protected','payment_protected','secured','held','holding'),
    'blocked_by_me',exists(
      select 1 from public.worker_user_blocks block_row
      where block_row.blocker_user_id=v_actor.user_id
        and block_row.blocked_user_id=case
          when v_actor.user_id=v_booking.user_id then v_booking.worker_id else v_booking.user_id end
    ),
    'blocked_me',exists(
      select 1 from public.worker_user_blocks block_row
      where block_row.blocker_user_id=case
          when v_actor.user_id=v_booking.user_id then v_booking.worker_id else v_booking.user_id end
        and block_row.blocked_user_id=v_actor.user_id
    ),
    'created_at',v_booking.created_at,'updated_at',v_booking.updated_at,
    'user_id',v_booking.user_id,'worker_id',v_booking.worker_id,
    'user_name',coalesce(v_customer.full_name,v_customer.username,'Customer'),
    'customer_username',v_customer.username,'user_avatar',v_customer.avatar_url,
    'worker_name',coalesce(v_worker.full_name,v_worker.username,'Worker'),
    'worker_avatar',v_worker.avatar_url
  );
end;
$$;


--
-- Name: worker_booking_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.worker_booking_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    booking_id uuid NOT NULL,
    user_id text NOT NULL,
    worker_id text NOT NULL,
    rating smallint NOT NULL,
    comment text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT worker_booking_reviews_check CHECK ((user_id <> worker_id)),
    CONSTRAINT worker_booking_reviews_comment_check CHECK (((comment IS NULL) OR (char_length(comment) <= 1200))),
    CONSTRAINT worker_booking_reviews_rating_check CHECK (((rating >= 1) AND (rating <= 5)))
);


--
-- Name: get_my_worker_booking_review(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_booking_review(p_booking_id uuid) RETURNS public.worker_booking_reviews
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select r.* from public.worker_booking_reviews r join public.worker_bookings b on b.id=r.booking_id
 where r.booking_id=p_booking_id and public.current_profile_user_id() in(b.user_id,b.worker_id) limit 1
$$;


--
-- Name: get_my_worker_completion_actions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_completion_actions(p_booking_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_booking public.worker_bookings;
  v_protection public.payment_protection_transactions;
  v_action public.financial_action_outbox;
begin
  select * into v_booking from public.worker_bookings where id=p_booking_id;
  if v_actor is null or v_booking.id is null
    or v_actor not in(v_booking.user_id,v_booking.worker_id) then
    raise exception 'Worker job participant access required';
  end if;
  select * into v_protection from public.payment_protection_transactions
  where id=v_booking.payment_protection_id;
  select * into v_action from public.financial_action_outbox
  where idempotency_key='release_worker_payment:'||v_booking.id;
  return jsonb_build_object(
    'canonical_job_state',coalesce(v_booking.canonical_job_state,'requested'),
    'marked_complete_at',v_booking.marked_complete_at,
    'reminder_available',v_actor=v_booking.worker_id
      and v_booking.canonical_job_state='completion_marked'
      and v_booking.marked_complete_at+interval '12 hours'<=now()
      and v_booking.completion_reminder_sent_at is null,
    'reminder_sent_at',v_booking.completion_reminder_sent_at,
    'release_eligible_at',v_booking.release_eligible_at,
    'release_status',coalesce(v_action.status,
      case when v_protection.protection_state='released' then 'completed' else 'not_queued' end),
    'protection_state',coalesce(v_protection.protection_state,'unavailable'),
    'customer_confirmed',coalesce(v_booking.user_approved,false),
    'help_until',v_booking.help_until,
    'help_open',v_booking.help_until is not null and v_booking.help_until>=now(),
    'review_edit_until',v_booking.review_edit_until,
    'review_edit_open',v_booking.review_edit_until is not null
      and v_booking.review_edit_until>=now()
  );
end
$$;


--
-- Name: get_my_worker_identity_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_identity_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_check public.worker_identity_checks;
BEGIN
  SELECT * INTO v_actor FROM public.profiles
  WHERE auth_id=auth.uid()::text AND public.user_has_active_workspace(user_id,'worker') AND NOT COALESCE(deleted,false) AND NOT COALESCE(suspended,false) AND NOT COALESCE(banned,false) LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Active Worker account required'; END IF;
  SELECT * INTO v_check FROM public.worker_identity_checks WHERE worker_id=v_actor.user_id;
  RETURN jsonb_build_object('status',COALESCE(v_check.status,'not_started'),'has_private_selfie',COALESCE(NULLIF(BTRIM(COALESCE(v_check.enrollment_photo_path,'')),'') IS NOT NULL,false),'face_match_score',v_check.face_match_score,'liveness_score',v_check.liveness_score,'anti_spoof_score',v_check.anti_spoof_score,'challenge_version',v_check.challenge_version,'captured_at',v_check.captured_at,'attempt_count',COALESCE(v_check.attempt_count,0));
END; $$;


--
-- Name: get_my_worker_identity_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_identity_reference() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor public.profiles;
  v_identity public.worker_identity_checks;
begin
  select * into v_actor
  from public.profiles
  where auth_id=auth.uid()::text
    and public.user_has_active_workspace(user_id,'worker')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null then raise exception 'Active Worker account required'; end if;

  select * into v_identity from public.worker_identity_checks where worker_id=v_actor.user_id;

  return jsonb_build_object(
    'has_reference',coalesce(nullif(btrim(coalesce(v_identity.enrollment_photo_path,'')),'') is not null,false),
    'photo_path',v_identity.enrollment_photo_path,
    'anchor_photo_path',v_identity.enrollment_photo_path,
    'recent_photo_path',coalesce(v_identity.latest_reference_photo_path,v_identity.enrollment_photo_path),
    'recent_reference_at',v_identity.latest_reference_at,
    'captured_at',v_identity.captured_at,
    'status',coalesce(v_identity.status,'not_started')
  );
end; $$;


--
-- Name: get_my_worker_pro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_pro() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_worker_id text;
  v_subscription public.worker_pro_subscriptions;
  v_monthly_price numeric:=0;
  v_yearly_price numeric:=0;
  v_enabled boolean:=false;
  v_ios_enabled boolean:=false;
  v_android_enabled boolean:=false;
  v_apple_monthly text:='';
  v_apple_yearly text:='';
  v_google_monthly text:='';
  v_google_yearly text:='';
  v_web_monthly text:='';
  v_web_yearly text:='';
  v_terms_version text:='';
  v_terms_content text:='';
  v_terms_sha256 text:='';
  v_terms_accepted boolean:=false;
  v_support_hours integer:=24;
  v_grace_days integer:=0;
  v_product_name text:='WeHouse Works';
  v_product_tagline text:='Run your work with clearer numbers, documents and reach.';
  v_featured_enabled boolean:=false;
  v_yearly_saving numeric:=0;
  v_yearly_discount numeric:=0;
begin
  select profile.user_id into v_worker_id
  from public.profiles profile
  where profile.auth_id=(select auth.uid())::text
    and public.user_has_active_workspace(profile.user_id,'worker')
    and not coalesce(profile.deleted,false)
    and not coalesce(profile.suspended,false)
    and not coalesce(profile.banned,false)
  limit 1;
  if v_worker_id is null then raise exception 'Active Worker workspace required'; end if;

  select * into v_subscription
  from public.worker_pro_subscriptions
  where worker_id=v_worker_id limit 1;
  select coalesce(nullif(value,'')::numeric,0) into v_monthly_price from public.platform_settings where key='worker_pro_monthly_price_ngn' and is_active=true limit 1;
  select coalesce(nullif(value,'')::numeric,0) into v_yearly_price from public.platform_settings where key='worker_pro_yearly_price_ngn' and is_active=true limit 1;
  select coalesce(lower(value) in('true','1','yes','on'),false) into v_enabled from public.platform_settings where key='worker_pro_sales_enabled' and is_active=true limit 1;
  select coalesce(lower(value) in('true','1','yes','on'),false) into v_ios_enabled from public.platform_settings where key='worker_pro_ios_sales_enabled' and is_active=true limit 1;
  select coalesce(lower(value) in('true','1','yes','on'),false) into v_android_enabled from public.platform_settings where key='worker_pro_android_sales_enabled' and is_active=true limit 1;
  select coalesce(value,'') into v_apple_monthly from public.platform_settings where key='worker_pro_apple_product_id' and is_active=true limit 1;
  select coalesce(value,'') into v_apple_yearly from public.platform_settings where key='worker_pro_apple_yearly_product_id' and is_active=true limit 1;
  select coalesce(value,'') into v_google_monthly from public.platform_settings where key='worker_pro_google_product_id' and is_active=true limit 1;
  select coalesce(value,'') into v_google_yearly from public.platform_settings where key='worker_pro_google_yearly_product_id' and is_active=true limit 1;
  select coalesce(value,'') into v_web_monthly from public.platform_settings where key='worker_pro_web_paystack_plan_code' and is_active=true limit 1;
  select coalesce(value,'') into v_web_yearly from public.platform_settings where key='worker_pro_web_paystack_yearly_plan_code' and is_active=true limit 1;
  select coalesce(value,'') into v_terms_version from public.platform_settings where key='worker_pro_terms_version' and is_active=true limit 1;
  select coalesce(value,'') into v_terms_content from public.platform_settings where key='worker_pro_terms_content' and is_active=true limit 1;
  select coalesce(nullif(value,'')::integer,24) into v_support_hours from public.platform_settings where key='worker_pro_support_response_hours' and is_active=true limit 1;
  select coalesce(nullif(value,'')::integer,0) into v_grace_days from public.platform_settings where key='worker_pro_payment_grace_days' and is_active=true limit 1;
  select coalesce(nullif(btrim(value),''),'WeHouse Works') into v_product_name from public.platform_settings where key='worker_pro_product_name' and is_active=true limit 1;
  select coalesce(nullif(btrim(value),''),'Run your work with clearer numbers, documents and reach.') into v_product_tagline from public.platform_settings where key='worker_pro_product_tagline' and is_active=true limit 1;
  select coalesce(lower(value) in('true','1','yes','on'),false) into v_featured_enabled from public.platform_settings where key='worker_featured_sales_enabled' and is_active=true limit 1;

  if nullif(btrim(v_terms_content),'') is not null then
    v_terms_sha256:=encode(extensions.digest(convert_to(v_terms_content,'UTF8'),'sha256'),'hex');
    select exists(
      select 1 from public.worker_pro_terms_acceptances acceptance
      where acceptance.worker_id=v_worker_id
        and acceptance.terms_version=v_terms_version
        and acceptance.terms_sha256=v_terms_sha256
    ) into v_terms_accepted;
  end if;
  v_yearly_saving:=greatest(v_monthly_price*12-v_yearly_price,0);
  if v_monthly_price>0 and v_yearly_saving>0 then
    v_yearly_discount:=round((v_yearly_saving/(v_monthly_price*12))*100,1);
  end if;

  return jsonb_build_object(
    'product_name',v_product_name,
    'product_tagline',v_product_tagline,
    'plan','worker_pro',
    'sales_enabled',coalesce(v_enabled,false),
    'native_sales',jsonb_build_object(
      'ios_enabled',coalesce(v_ios_enabled,false),
      'android_enabled',coalesce(v_android_enabled,false)
    ),
    'monthly_price_ngn',coalesce(v_monthly_price,0),
    'yearly_price_ngn',coalesce(v_yearly_price,0),
    'apple_product_id',coalesce(v_apple_monthly,''),
    'google_product_id',coalesce(v_google_monthly,''),
    'web_paystack_plan_code',coalesce(v_web_monthly,''),
    'plans',jsonb_build_array(
      jsonb_build_object(
        'billing_period','monthly','period','P1M','label','Monthly',
        'price_ngn',coalesce(v_monthly_price,0),
        'web_plan_code',coalesce(v_web_monthly,''),
        'apple_product_id',coalesce(v_apple_monthly,''),
        'google_product_id',coalesce(v_google_monthly,''),
        'web_available',coalesce(v_enabled,false) and v_monthly_price>0 and nullif(btrim(v_web_monthly),'') is not null,
        'saving_ngn',0,'discount_percent',0
      ),
      jsonb_build_object(
        'billing_period','yearly','period','P1Y','label','Yearly',
        'price_ngn',coalesce(v_yearly_price,0),
        'web_plan_code',coalesce(v_web_yearly,''),
        'apple_product_id',coalesce(v_apple_yearly,''),
        'google_product_id',coalesce(v_google_yearly,''),
        'web_available',coalesce(v_enabled,false) and v_yearly_price>0 and nullif(btrim(v_web_yearly),'') is not null,
        'saving_ngn',v_yearly_saving,'discount_percent',v_yearly_discount
      )
    ),
    'terms_version',coalesce(v_terms_version,''),
    'terms_content',coalesce(v_terms_content,''),
    'terms_accepted',coalesce(v_terms_accepted,false),
    'support_response_hours',coalesce(v_support_hours,24),
    'payment_grace_days',coalesce(v_grace_days,0),
    'active',public.worker_pro_is_active(v_worker_id),
    'status',coalesce(v_subscription.status,'inactive'),
    'provider',v_subscription.provider,
    'product_id',v_subscription.product_id,
    'billing_period',coalesce(v_subscription.billing_period,'monthly'),
    'current_period_start',v_subscription.current_period_start,
    'current_period_end',v_subscription.current_period_end,
    'cancel_at_period_end',coalesce(v_subscription.cancel_at_period_end,false),
    'auto_renews',coalesce(v_subscription.auto_renews,false),
    'features',jsonb_build_array(
      'Work Insights from completed WeHouse records',
      'Quotes and invoices with clear payment labels',
      case when coalesce(v_featured_enabled,false)
        then 'Eligible Sponsored placement with fair rotation'
        else 'Sponsored placement when legally approved and enabled' end,
      'Priority for ordinary platform support'
    )
  );
end;
$$;


--
-- Name: get_my_worker_work_documents(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_work_documents(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_limit integer:=greatest(1,least(coalesce(p_limit,50),100));
begin
  if v_actor is null then raise exception 'Active signed-in account required'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',document.id,'document_number',document.document_number,
      'worker_id',document.worker_id,'customer_id',document.customer_id,
      'booking_id',document.booking_id,'booking_code',booking.booking_code,
      'service_type',booking.service_type,
      'document_type',document.document_type,'title',document.title,
      'items',document.items,'subtotal',document.subtotal,'total',document.total,
      'currency',document.currency,'document_status',document.document_status,
      'payment_status',case
        when document.document_type='invoice'
          and booking.status='approved_released'
          and document.total=coalesce(nullif(booking.negotiated_amount,0),booking.agreed_amount)
          then 'paid_through_wehouse'
        else document.payment_status end,
      'payment_label',case
        when document.document_type<>'invoice' then 'Not applicable'
        when booking.status='approved_released'
          and document.total=coalesce(nullif(booking.negotiated_amount,0),booking.agreed_amount)
          then 'Paid through WeHouse'
        when document.payment_status='marked_paid_by_worker'
          then 'Marked paid by Worker — not verified by WeHouse'
        else 'Unpaid' end,
      'note',document.note,'sent_at',document.sent_at,
      'responded_at',document.responded_at,
      'marked_paid_at',document.marked_paid_at,
      'created_at',document.created_at,'updated_at',document.updated_at
    ) order by document.created_at desc)
    from (
      select source.* from public.worker_work_documents source
      where source.worker_id=v_actor
        or (source.customer_id=v_actor and source.document_status<>'draft')
      order by source.created_at desc limit v_limit
    ) document
    join public.worker_bookings booking on booking.id=document.booking_id
  ),'[]'::jsonb);
end;
$$;


--
-- Name: get_my_worker_work_insights(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_worker_work_insights(p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_worker text;
  v_days integer:=case when p_days in(30,90,365) then p_days else 30 end;
  v_from timestamptz;
begin
  select profile.user_id into v_worker from public.profiles profile
  where profile.auth_id=(select auth.uid())::text
    and public.user_has_active_workspace(profile.user_id,'worker')
    and not coalesce(profile.deleted,false)
    and not coalesce(profile.suspended,false)
    and not coalesce(profile.banned,false) limit 1;
  if v_worker is null then raise exception 'Active Worker workspace required'; end if;
  if not public.worker_pro_is_active(v_worker) then
    raise exception 'An active paid Worker plan is required for Work Insights';
  end if;
  v_from:=now()-make_interval(days=>v_days);
  return jsonb_build_object(
    'range_days',v_days,'from',v_from,'generated_at',now(),
    'completed_jobs',(select count(*) from public.worker_bookings booking
      where booking.worker_id=v_worker and booking.status='approved_released'
        and coalesce(booking.completed_at,booking.updated_at)>=v_from),
    'released_earnings_ngn',(select coalesce(sum(booking.worker_receives),0)
      from public.worker_bookings booking where booking.worker_id=v_worker
        and booking.status='approved_released'
        and coalesce(booking.completed_at,booking.updated_at)>=v_from),
    'active_jobs',(select count(*) from public.worker_bookings booking
      where booking.worker_id=v_worker and booking.status in(
        'booking_requested','negotiating','waiting_payment','confirmed',
        'in_progress','completed_pending_approval','disputed')),
    'rating',coalesce((select round(avg(review.rating)::numeric,2)
      from public.worker_booking_reviews review
      join public.worker_bookings booking on booking.id=review.booking_id
      where review.worker_id=v_worker and booking.status='approved_released'
        and review.created_at>=v_from),0),
    'review_count',(select count(*) from public.worker_booking_reviews review
      join public.worker_bookings booking on booking.id=review.booking_id
      where review.worker_id=v_worker and booking.status='approved_released'
        and review.created_at>=v_from),
    'repeat_customers',(select count(*) from(
      select booking.user_id from public.worker_bookings booking
      where booking.worker_id=v_worker and booking.status='approved_released'
        and coalesce(booking.completed_at,booking.updated_at)>=v_from
      group by booking.user_id having count(*)>=2
    ) repeated),
    'worker_cancelled_jobs',(select count(*) from public.worker_bookings booking
      where booking.worker_id=v_worker and booking.status='cancelled'
        and booking.cancelled_by=v_worker and booking.updated_at>=v_from),
    'featured',jsonb_build_object(
      'signed_in_unique_impressions',(select count(*)
        from public.worker_featured_placements placement
        where placement.worker_id=v_worker and placement.created_at>=v_from),
      'unique_profile_opens',(select count(*)
        from public.worker_featured_placements placement
        where placement.worker_id=v_worker and placement.created_at>=v_from
          and placement.profile_opened_at is not null),
      'booking_requests',(select count(*)
        from public.worker_featured_placements placement
        join public.worker_bookings booking on booking.id=placement.booking_id
        where placement.worker_id=v_worker and booking.created_at>=v_from)
    ),
    'definitions',jsonb_build_object(
      'completed_jobs','Jobs with status Completed and earnings released.',
      'released_earnings_ngn','Worker amount on completed, released WeHouse jobs only.',
      'active_jobs','Current non-terminal Worker bookings, including disputes.',
      'rating','Average of verified reviews on completed WeHouse jobs in this period.',
      'repeat_customers','Customers with at least two completed jobs in this period.',
      'worker_cancelled_jobs','Jobs recorded as cancelled by this Worker.',
      'featured','Unique signed-in daily placements, profile opens and real booking requests linked to Sponsored cards.'
    )
  );
end;
$$;


--
-- Name: get_my_workspace_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_workspace_access() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'identity',jsonb_build_object(
      'user_id',profile.user_id,
      'account_kind','consumer',
      'compatibility_role',profile.role
    ),
    'personal_workspace',
      not coalesce(profile.deleted,false)
      and not coalesce(profile.suspended,false)
      and not coalesce(profile.banned,false),
    'privileged_workspaces',coalesce((
      select jsonb_agg(workspace.item order by workspace.item->>'role')
      from (
        select jsonb_build_object(
          'role',assignment.workspace_role,
          'scope_type',assignment.scope_type,
          'state',assignment.scope_state,
          'lga',assignment.scope_lga
        ) as item
        from public.workspace_role_assignments assignment
        where assignment.user_id=profile.user_id and assignment.status='active'
        union all
        select jsonb_build_object(
          'role','hotel','scope_type','hotel','state',null,'lga',null
        )
        where exists(
          select 1 from public.hotel_team_members team
          where team.member_user_id=profile.user_id and team.status='active'
        )
      ) workspace
    ),'[]'::jsonb)
  )
  from public.profiles profile
  where profile.auth_id=(select auth.uid())::text;
$$;


--
-- Name: property_partners; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.property_partners (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    profile_id text NOT NULL,
    partner_code text NOT NULL,
    status text DEFAULT 'pending_verification'::text NOT NULL,
    verification_notes text,
    commission_rate numeric DEFAULT 0,
    total_earnings numeric DEFAULT 0,
    total_paid_out numeric DEFAULT 0,
    properties_count integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: get_or_create_my_property_partner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_or_create_my_property_partner() RETURNS public.property_partners
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_profile public.profiles;
  v_partner public.property_partners;
  v_code text;
begin
  select * into v_profile
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_profile is null
     or not public.current_actor_has_workspace('property_partner',null) then
    raise exception 'Property Partner workspace required';
  end if;
  select * into v_partner
  from public.property_partners
  where profile_id=v_profile.user_id limit 1;
  if v_partner is not null then return v_partner; end if;
  v_code:='WHP-'||replace(v_profile.user_id,'WHU-','')||'-'
    ||upper(substr(md5(v_profile.user_id||clock_timestamp()::text),1,4));
  insert into public.property_partners(
    profile_id,partner_code,status,commission_rate,total_earnings,
    total_paid_out,properties_count,created_at,updated_at
  ) values(
    v_profile.user_id,v_code,'pending_verification',0,0,0,0,now(),now()
  ) on conflict(profile_id) do update
    set updated_at=public.property_partners.updated_at
  returning * into v_partner;
  return v_partner;
end
$$;


--
-- Name: get_payout_account_change_from_service(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_payout_account_change_from_service(p_request_id uuid, p_user_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object(
    'request_id',r.request_id,
    'status',r.status,
    'replacement',r.replacement,
    'cooling_ends_at',r.cooling_ends_at,
    'account_name',r.account_name,
    'bank_name',r.bank_name,
    'account_last4',right(r.account_number,4),
    'error_code',r.error_code,
    'error_message',r.error_message,
    'bank_account_id',r.bank_account_id
  )
  from public.payout_account_change_requests r
  where r.request_id=p_request_id and r.user_id=p_user_id
    and (select auth.role())='service_role'
$$;


--
-- Name: get_platform_setting(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_platform_setting(p_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE v_value TEXT; BEGIN SELECT ps.value INTO v_value FROM platform_settings ps WHERE ps.key = p_key; RETURN v_value; END;
$$;


--
-- Name: get_platform_settings(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_platform_settings(p_category text DEFAULT NULL::text) RETURNS TABLE(key text, value text, category text, label text, description text, data_type text, editable boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  IF p_category IS NOT NULL THEN
    RETURN QUERY SELECT ps.key::TEXT, ps.value::TEXT, ps.category::TEXT, ps.label::TEXT, ps.description::TEXT, ps.data_type::TEXT, ps.editable FROM platform_settings ps WHERE ps.category = p_category ORDER BY ps.category, ps.key;
  ELSE
    RETURN QUERY SELECT ps.key::TEXT, ps.value::TEXT, ps.category::TEXT, ps.label::TEXT, ps.description::TEXT, ps.data_type::TEXT, ps.editable FROM platform_settings ps ORDER BY ps.category, ps.key;
  END IF;
END;
$$;


--
-- Name: get_private_call_capabilities(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_private_call_capabilities(p_context_type text, p_context_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_me text:=public.current_profile_user_id();
  v_peer text;
  v_profile public.profiles;
  v_pref public.private_call_preferences;
begin
  if v_me is null then raise exception 'Authenticated profile required'; end if;
  if p_context_type='roommate' then
    select case when conversation.participant_a=v_me then conversation.participant_b else conversation.participant_a end
    into v_peer
    from public.conversations conversation
    where conversation.id=p_context_id
      and conversation.conversation_type='roommate'
      and coalesce(conversation.status,'active')='active'
      and v_me in (conversation.participant_a,conversation.participant_b)
    limit 1;
    if exists(
      select 1 from public.roommate_user_blocks block_row
      where (block_row.blocker_user_id=v_me and block_row.blocked_user_id=v_peer)
         or (block_row.blocker_user_id=v_peer and block_row.blocked_user_id=v_me)
    ) then raise exception 'This roommate connection is blocked'; end if;
  elsif p_context_type='worker_booking' then
    select case when conversation.user_id=v_me then conversation.worker_id else conversation.user_id end
    into v_peer
    from public.booking_conversations conversation
    join public.worker_bookings booking on booking.id=conversation.booking_id
    where conversation.id=p_context_id
      and v_me in (conversation.user_id,conversation.worker_id)
      and booking.status not in ('approved_released','cancelled','refunded')
    limit 1;
    if exists(
      select 1 from public.worker_user_blocks block_row
      where (block_row.blocker_user_id=v_me and block_row.blocked_user_id=v_peer)
         or (block_row.blocker_user_id=v_peer and block_row.blocked_user_id=v_me)
    ) then raise exception 'This service conversation is blocked'; end if;
  else
    raise exception 'Unsupported call context';
  end if;
  if v_peer is null then raise exception 'This job conversation is closed'; end if;
  select * into v_profile from public.profiles
  where user_id=v_peer and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false)
  limit 1;
  if v_profile is null or not(v_profile.account_kind='consumer' or v_profile.role='worker') then
    raise exception 'This person cannot receive private calls';
  end if;
  select * into v_pref from public.private_call_preferences where user_id=v_peer;
  return jsonb_build_object(
    'peer_id',v_peer,
    'peer_name',coalesce(v_profile.full_name,v_profile.username,'WeHouse member'),
    'peer_avatar',v_profile.avatar_url,
    'allow_audio_calls',coalesce(v_pref.allow_audio_calls,true),
    'allow_video_calls',coalesce(v_pref.allow_video_calls,true)
  );
end;
$$;


--
-- Name: get_private_call_details(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_private_call_details(p_call_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_me text:=public.current_profile_user_id(); v_call public.private_calls; v_peer text; v_profile public.profiles;
begin
 select * into v_call from public.private_calls where id=p_call_id and v_me in (caller_id,callee_id) limit 1;
 if v_call is null then raise exception 'Call not found'; end if;
 v_peer:=case when v_call.caller_id=v_me then v_call.callee_id else v_call.caller_id end;
 select * into v_profile from public.profiles where user_id=v_peer limit 1;
 return to_jsonb(v_call)||jsonb_build_object('peer_id',v_peer,'peer_name',coalesce(v_profile.full_name,v_profile.username,'WeHouse member'),'peer_avatar',v_profile.avatar_url,'incoming',v_call.callee_id=v_me);
end; $$;


--
-- Name: get_private_chat_peer_public_key(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_private_chat_peer_public_key(p_conversation_kind text, p_conversation_id uuid, p_peer_user_id text) RETURNS TABLE(user_id text, key_version integer, public_key_jwk jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare actor text:=public.current_profile_user_id(); begin if actor is null then raise exception 'Active WeHouse profile required'; end if;
if p_conversation_kind='roommate' then if not exists(select 1 from public.conversations c where c.id=p_conversation_id and actor in(c.participant_a,c.participant_b) and p_peer_user_id in(c.participant_a,c.participant_b)) then raise exception 'Conversation access denied'; end if;
elsif p_conversation_kind='worker' then if not exists(select 1 from public.booking_conversations c where c.id=p_conversation_id and actor in(c.user_id,c.worker_id) and p_peer_user_id in(c.user_id,c.worker_id)) then raise exception 'Conversation access denied'; end if;
else raise exception 'Unsupported private conversation kind'; end if;
return query select i.user_id,i.key_version,i.public_key_jwk from public.user_encryption_identities i where i.user_id=p_peer_user_id; end $$;


--
-- Name: get_private_encrypted_messages(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_private_encrypted_messages(p_conversation_kind text, p_conversation_id uuid) RETURNS TABLE(id uuid, sender_id text, ciphertext text, encryption_iv text, encryption_version integer, encrypted_attachments jsonb, created_at timestamp with time zone, legacy_content text, is_read boolean, reply_to_id uuid, reactions jsonb, legacy_attachments text[], legacy_attachment_types text[], item_type text, item_payload jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare actor text:=public.current_profile_user_id();
begin
  if actor is null then raise exception 'Active WeHouse profile required'; end if;
  if p_conversation_kind='roommate' then
    if not exists(
      select 1 from public.conversations c
      where c.id=p_conversation_id
        and actor in(c.participant_a,c.participant_b)
        and c.conversation_type='roommate'
        and coalesce(c.status,'active') in('active','accepted')
    ) then raise exception 'Conversation access denied'; end if;
    return query
    select m.id,m.sender_id,m.ciphertext,m.encryption_iv,m.encryption_version,
      coalesce(m.encrypted_attachments,'[]'::jsonb),m.created_at,
      case when m.ciphertext is null then m.content else null end,
      coalesce(m.seen,false),m.reply_to_id,coalesce(m.reactions,'{}'::jsonb),
      coalesce(m.attachments,'{}'::text[]),coalesce(m.attachment_types,'{}'::text[]),
      coalesce(m.item_type,'message'),
      case when m.item_type='property_share' then
        coalesce(m.item_payload,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
          'title',l.title,'image',l.images[1],'city',l.city,'state',l.state,
          'price',l.price,'currency','NGN',
          'product_type',case when l.sub_type='short_let' then 'short_let'
            when l.sub_type='long_stay' then 'long_let' else null end,
          'is_available',coalesce(l.deleted_at is null and l.status='available'
            and l.availability_status='available',false)
        )) else coalesce(m.item_payload,'{}'::jsonb) end
    from public.messages m
    left join public.listings l on m.item_type='property_share'
      and l.id::text=m.item_payload->>'listing_id'
    where m.conversation_id=p_conversation_id
      and not(actor=any(coalesce(m.hidden_for,'{}'::text[])))
    order by m.created_at,m.id;
  elsif p_conversation_kind='worker' then
    if not exists(
      select 1 from public.booking_conversations c
      where c.id=p_conversation_id and actor in(c.user_id,c.worker_id)
    ) then raise exception 'Conversation access denied'; end if;
    return query
    select m.id,m.sender_id,m.ciphertext,m.encryption_iv,m.encryption_version,
      coalesce(m.encrypted_attachments,'[]'::jsonb),m.created_at,
      case when m.ciphertext is null then m.content else null end,
      coalesce(m.is_read,false),m.reply_to_id,coalesce(m.reactions,'{}'::jsonb),
      coalesce(m.attachments,'{}'::text[]),'{}'::text[],'message'::text,'{}'::jsonb
    from public.booking_messages m
    where m.conversation_id=p_conversation_id
      and not(actor=any(coalesce(m.hidden_for,'{}'::text[])))
    order by m.created_at,m.id;
  else
    raise exception 'Unsupported private conversation kind';
  end if;
end
$$;


--
-- Name: get_property_access_review_details(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_property_access_review_details(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
  v_code text;
  v_review public.audit_logs;
  v_reviewer public.profiles;
begin
  select * into v_actor
  from public.profiles
  where auth_id=auth.uid()::text
    and role in ('staff','admin','creator')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;

  if v_actor is null or (v_actor.role='staff' and not public.current_staff_has_permission('operations')) then
    raise exception 'Operations Staff, Admin or Creator access required';
  end if;

  select * into v_request from public.inspection_requests where id=p_request_id;
  if v_request.id is null then raise exception 'Property request not found'; end if;
  if v_actor.role<>'creator' and not public.current_actor_in_scope(v_request.property_state,v_request.property_city) then
    raise exception 'Property is outside your assigned area';
  end if;

  select c.code into v_code
  from public.property_access_challenges c
  where c.request_id=v_request.id and c.status='consumed'
  order by c.consumed_at desc nulls last
  limit 1;

  if v_request.access_evidence_status='verified' then
    select a.* into v_review
    from public.audit_logs a
    where a.target_type='inspection_requests'
      and a.target_id=v_request.id::text
      and a.admin_id=v_request.access_evidence_verified_by
      and a.action in ('PROPERTY_ACCESS_EVIDENCE_ACCEPTED','PROPERTY_ACCESS_EVIDENCE_OVERRIDDEN')
      and coalesce((a.details::jsonb)->>'decision','accept')='accept'
    order by a.created_at desc
    limit 1;
    if v_review.id is not null then
      select * into v_reviewer from public.profiles where user_id=v_review.admin_id limit 1;
    end if;
  end if;

  return jsonb_build_object(
    'status',v_request.access_evidence_status,
    'video_path',v_request.access_evidence_video_path,
    'submitted_at',v_request.access_evidence_submitted_at,
    'code',v_code,
    'reviewed_at',v_request.access_evidence_verified_at,
    'reviewed_by',v_request.access_evidence_verified_by,
    'reviewer_role',coalesce(v_reviewer.role,(v_review.details::jsonb)->>'reviewer_role'),
    'reviewer_name',coalesce(nullif(v_reviewer.full_name,''),nullif(v_reviewer.username,''),v_reviewer.email),
    'audit_event_id',v_review.id,
    'audit_backed',v_request.access_evidence_status<>'verified' or (
      v_review.id is not null
      and v_request.access_evidence_verified_at is not null
      and v_request.access_evidence_verified_by is not null
    )
  );
end;
$$;


--
-- Name: get_property_pipeline_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_property_pipeline_requests() RETURNS TABLE(id uuid, request_code text, owner_id text, owner_name text, owner_email text, owner_phone text, property_address text, property_city text, property_state text, property_type text, bedrooms integer, bathrooms integer, expected_rent numeric, description text, status text, assigned_field_officer_id text, scheduled_date date, rejection_reason text, notes text, photo_urls text[], gps_latitude numeric, gps_longitude numeric, location_accuracy_m numeric, draft_listing_id text, published_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_actor record;
begin
 select user_id,role,assigned_state,assigned_lga,deleted,suspended,banned into v_actor from public.profiles where auth_id=auth.uid()::text limit 1;
 if v_actor is null or v_actor.role not in ('admin','creator') or coalesce(v_actor.deleted,false) or coalesce(v_actor.suspended,false) or coalesce(v_actor.banned,false) then raise exception 'Admin or Creator access required'; end if;
 return query
 select ir.id,ir.request_code,ir.owner_id,coalesce(p.full_name,p.username,p.email),ir.owner_email,ir.owner_phone,ir.property_address,ir.property_city,ir.property_state,ir.property_type,ir.bedrooms,ir.bathrooms,ir.expected_rent,ir.description,ir.status,coalesce(ir.assigned_field_officer_id,ir.field_officer_id,ir.assigned_to),ir.scheduled_date,ir.rejection_reason,ir.notes,ir.photo_urls,ir.gps_latitude,ir.gps_longitude,ir.location_accuracy_m,ir.draft_listing_id::text,ir.published_at,ir.created_at,ir.updated_at
 from public.inspection_requests ir left join public.profiles p on p.user_id=ir.owner_id
 where v_actor.role='creator' or (lower(coalesce(ir.property_state,''))=lower(coalesce(v_actor.assigned_state,'')) and lower(coalesce(ir.property_city,''))=lower(coalesce(v_actor.assigned_lga,'')))
 order by ir.created_at desc;
end $$;


--
-- Name: get_public_hotel_detail(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_hotel_detail(p_hotel_id integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_hotel public.hotels;
  v_actor public.profiles;
  v_internal boolean := false;
  v_current_paid_stay boolean := false;
  v_rooms jsonb;
  v_facilities jsonb;
begin
  select * into v_hotel from public.hotels where hotel_id = p_hotel_id;
  if v_hotel.hotel_id is null then return null; end if;

  select * into v_actor
  from public.profiles
  where auth_id = (select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;

  if v_actor.user_id is not null then
    v_internal := v_hotel.owner_id = v_actor.user_id
      or exists(
        select 1 from public.hotel_team_members member
        where member.hotel_id = v_hotel.hotel_id
          and member.member_user_id = v_actor.user_id
          and member.status = 'active'
      )
      or v_actor.role = 'creator'
      or (v_actor.role = 'admin' and public.current_actor_in_scope(v_hotel.state,v_hotel.city))
      or (v_actor.role = 'staff' and public.current_staff_has_permission('operations') and public.current_actor_in_scope(v_hotel.state,v_hotel.city));

    v_current_paid_stay := exists(
      select 1 from public.hotel_bookings booking
      where booking.hotel_id = v_hotel.hotel_id
        and booking.user_id = v_actor.user_id
        and booking.payment_status = 'paid'
        and booking.status in ('confirmed','checked_in')
    );
  end if;

  if v_hotel.status <> 'active' and not v_internal and not v_current_paid_stay then return null; end if;

  select coalesce(jsonb_agg(
    to_jsonb(room) || jsonb_build_object(
      'rate_plans', coalesce((
        select jsonb_agg(to_jsonb(plan) order by plan.price_per_night,plan.rate_plan_id)
        from public.hotel_rate_plans plan
        where plan.room_id = room.room_id
          and (plan.active or v_internal or v_current_paid_stay)
      ), '[]'::jsonb)
    ) order by room.price_per_night
  ), '[]'::jsonb)
  into v_rooms
  from public.hotel_rooms room
  where room.hotel_id = v_hotel.hotel_id;

  select coalesce(jsonb_agg(to_jsonb(venue) order by venue.kind,venue.name),'[]'::jsonb)
  into v_facilities
  from public.hotel_venues venue
  where venue.hotel_id = v_hotel.hotel_id
    and (venue.active or v_internal);

  if v_internal then
    return to_jsonb(v_hotel) || jsonb_build_object('hotel_rooms',v_rooms,'venues',v_facilities,'location_exact',true);
  end if;

  return (
    to_jsonb(v_hotel)
      - 'address' - 'gps_latitude' - 'gps_longitude' - 'owner_id' - 'inspection_request_id' - 'approved_by'
  ) || jsonb_build_object(
    'address', case when v_current_paid_stay then v_hotel.address else null end,
    'gps_latitude', case when v_hotel.gps_latitude is null then null when v_current_paid_stay then v_hotel.gps_latitude else round(v_hotel.gps_latitude,2) end,
    'gps_longitude', case when v_hotel.gps_longitude is null then null when v_current_paid_stay then v_hotel.gps_longitude else round(v_hotel.gps_longitude,2) end,
    'hotel_rooms',v_rooms,
    'venues',v_facilities,
    'location_exact',v_current_paid_stay
  );
end;
$$;


--
-- Name: get_public_listing_detail(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_listing_detail(p_listing_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_listing public.listings; v_actor public.profiles; v_partner_name text;
  v_internal boolean:=false; v_paid boolean:=false;
begin
  select * into v_listing from public.listings l
  where (l.id::text=p_listing_id or l.listing_id=p_listing_id) and l.deleted_at is null limit 1;
  if v_listing.id is null then return null; end if;
  select coalesce(nullif(btrim(p.full_name),''),nullif(btrim(p.username),'')) into v_partner_name
  from public.profiles p where p.user_id=coalesce(v_listing.partner_id,v_listing.owner_id);
  select * into v_actor from public.profiles where auth_id=auth.uid()::text
    and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor.user_id is not null then
    v_internal:=v_listing.owner_id=v_actor.user_id or v_listing.partner_id=v_actor.user_id or v_actor.role='creator'
      or (v_actor.role='admin' and public.current_actor_in_scope(v_listing.state,v_listing.city))
      or (v_actor.role='staff' and public.current_staff_has_permission('operations') and public.current_actor_in_scope(v_listing.state,v_listing.city));
    v_paid:=exists(select 1 from public.reservations r where r.user_id=v_actor.user_id
      and r.listing_id in (v_listing.id::text,v_listing.listing_id)
      and (r.paid_at is not null or r.manual_payment_status in ('paid','completed'))
      and r.status not in ('cancelled','expired'));
  end if;
  if not v_internal and not (v_listing.status='available' and v_listing.availability_status='available') then return null; end if;
  if v_internal then return to_jsonb(v_listing)||jsonb_build_object('location_exact',true,'partner_display_name',v_partner_name); end if;
  return (to_jsonb(v_listing)-'address'-'gps_latitude'-'gps_longitude'-'location_accuracy_m'-'owner_id'-'partner_id'-'chat_agent_id'-'contact_phone'-'reserved_by'-'occupied_by'-'current_reservation_id'-'inspection_request_id')
    ||jsonb_build_object(
      'address',case when v_paid then v_listing.address else null end,
      'gps_latitude',case when v_listing.gps_latitude is null then null when v_paid then v_listing.gps_latitude else round(v_listing.gps_latitude,2) end,
      'gps_longitude',case when v_listing.gps_longitude is null then null when v_paid then v_listing.gps_longitude else round(v_listing.gps_longitude,2) end,
      'location_accuracy_m',case when v_paid then v_listing.location_accuracy_m else null end,
      'location_exact',v_paid,'partner_display_name',v_partner_name
    );
end;
$$;


--
-- Name: get_public_worker_reviews(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_worker_reviews(p_worker_id text, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, rating smallint, comment text, created_at timestamp with time zone, reviewer_name text, service_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select r.id,r.rating,r.comment,r.created_at,
    case when r.user_id=(select actor.user_id from public.profiles actor where actor.auth_id=(select auth.uid())::text limit 1)
      then 'Your review' else 'Verified customer' end,
    coalesce(s.name,b.service_type,'Service job')
  from public.worker_booking_reviews r
  join public.worker_bookings b on b.id=r.booking_id
  left join public.service_subcategories s on s.id=b.service_subcategory_id
  where r.worker_id=p_worker_id and b.status='approved_released'
  order by r.created_at desc
  limit least(greatest(coalesce(p_limit,20),1),50)
$$;


--
-- Name: get_public_workers(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_workers(p_state text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_occupation text DEFAULT NULL::text) RETURNS TABLE(user_id text, full_name text, username text, avatar_url text, bio text, state text, city text, local_government text, area text, worker_occupation text, worker_skills jsonb, worker_price integer, worker_bio text, worker_experience text, rating numeric, review_count integer, is_online boolean, last_seen timestamp with time zone, services jsonb, coverage jsonb, pro_active boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_marketplace_enabled boolean:=false;
begin
  if (select auth.uid()) is null then raise exception 'Authentication required'; end if;
  select coalesce(lower(value) in('true','1','yes','on'),false)
    into v_marketplace_enabled from public.platform_settings
  where key='worker_marketplace_launch_enabled' and is_active=true limit 1;
  if not coalesce(v_marketplace_enabled,false) then return; end if;
  return query
  select
    profile.user_id,profile.full_name,profile.username,profile.avatar_url,
    profile.bio,profile.state,profile.city,profile.local_government,
    profile.area,profile.worker_occupation,profile.worker_skills,
    profile.worker_price,profile.worker_bio,profile.worker_experience,
    profile.rating,profile.review_count,profile.is_online,profile.last_seen,
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'name',service.service_name,'price',service.price,
        'price_type',service.price_type
      )) from public.worker_services service
      where service.worker_id=profile.user_id
    ),'[]'::jsonb),
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'state',coverage.state,'lga',coverage.lga,'areas',coverage.areas
      )) from public.worker_service_coverage coverage
      where coverage.worker_id=profile.user_id
    ),'[]'::jsonb),
    public.worker_pro_is_active(profile.user_id)
  from public.profiles profile
  where public.user_has_active_workspace(profile.user_id,'worker')
    and profile.worker_status='verified' and profile.worker_verified=true
    and profile.available=true
    and not coalesce(profile.deleted,false)
    and not coalesce(profile.suspended,false)
    and not coalesce(profile.banned,false)
    and (
      not coalesce((select lower(value) in('true','1','yes','on')
        from public.platform_settings where key='worker_identity_checks_enabled'
        and is_active=true limit 1),false)
      or public.worker_identity_is_current(profile.user_id)
    )
    and (p_state is null
      or public.wehouse_state_key(profile.state)=public.wehouse_state_key(p_state))
    and (p_city is null or profile.city ilike p_city
      or profile.local_government ilike p_city)
    and (p_occupation is null or profile.worker_occupation ilike p_occupation)
    and not exists(
      select 1 from public.worker_user_blocks blocked_pair
      where v_actor is not null and (
        (blocked_pair.blocker_user_id=v_actor
          and blocked_pair.blocked_user_id=profile.user_id)
        or (blocked_pair.blocker_user_id=profile.user_id
          and blocked_pair.blocked_user_id=v_actor)
      )
    )
  order by profile.rating desc nulls last,profile.review_count desc nulls last;
end;
$$;


--
-- Name: get_reservation_handover_assignment(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_reservation_handover_assignment(p_reservation_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_res public.reservations;
  v_listing public.listings;
  v_case public.partner_support_conversations;
  v_candidates jsonb;
begin
  select * into v_actor from public.profiles
  where auth_id=auth.uid()::text and role in ('staff','admin','creator')
    and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then raise exception 'Property Operations access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then
    raise exception 'Property Operations permission required';
  end if;

  select * into v_res from public.reservations where id=p_reservation_id;
  if v_res.id is null then raise exception 'Reservation not found'; end if;
  select * into v_listing from public.listings where id::text=v_res.listing_id or listing_id=v_res.listing_id limit 1;
  if v_listing.id is null then raise exception 'Property not found'; end if;
  if v_actor.role<>'creator' and not public.current_actor_in_scope(v_listing.state,v_listing.city) then
    raise exception 'Reservation is outside your assigned State/LGA';
  end if;

  select * into v_case from public.partner_support_conversations c
  where c.context_type='apartment_reservation' and c.context_id=v_res.id
  order by c.updated_at desc limit 1;

  select coalesce(jsonb_agg(jsonb_build_object(
    'user_id',p.user_id,
    'name',coalesce(nullif(btrim(p.full_name),''),nullif(btrim(p.username),''),p.user_id),
    'username',p.username
  ) order by coalesce(p.full_name,p.username,p.user_id)),'[]'::jsonb)
  into v_candidates
  from public.profiles p
  where p.role='staff'
    and not coalesce(p.deleted,false) and not coalesce(p.suspended,false) and not coalesce(p.banned,false)
    and exists(select 1 from public.staff_permissions sp where sp.staff_id=p.user_id and sp.permission='field_officer' and sp.is_active=true)
    and lower(btrim(coalesce(p.assigned_state,'')))=lower(btrim(coalesce(v_listing.state,'')))
    and lower(btrim(coalesce(p.assigned_lga,'')))=lower(btrim(coalesce(v_listing.city,'')));

  return jsonb_build_object(
    'conversation_id',v_case.id,
    'assigned_field_officer_id',coalesce(v_res.handover_field_officer_id,v_case.assigned_field_officer_id),
    'assigned_field_officer_name',(
      select coalesce(nullif(btrim(p.full_name),''),nullif(btrim(p.username),''),p.user_id)
      from public.profiles p
      where p.user_id=coalesce(v_res.handover_field_officer_id,v_case.assigned_field_officer_id)
    ),
    'candidates',v_candidates
  );
end;
$$;


--
-- Name: get_roommate_messages_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_roommate_messages_v2(p_conversation_id uuid) RETURNS TABLE(id uuid, conversation_id uuid, sender_id text, content text, seen boolean, created_at timestamp with time zone, edited_at timestamp with time zone, file_url text, file_name text, file_type text, attachments text[], attachment_types text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
begin
  v_actor := public._current_comm_actor();
  if v_actor is null or not public._can_access_conversation(p_conversation_id) then
    raise exception 'Not authorized for this conversation';
  end if;

  return query
  select m.id,m.conversation_id,m.sender_id,m.content,m.seen,m.created_at,m.edited_at,
         m.file_url,m.file_name,m.file_type,m.attachments,m.attachment_types
  from public.messages m
  where m.conversation_id = p_conversation_id
    and not (
      v_actor.user_id = any(coalesce(m.hidden_for, '{}'::text[]))
    )
  order by m.created_at;
end
$$;


--
-- Name: get_secret_v2(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_secret_v2(p_key text) RETURNS TABLE(key text, value text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ begin
  if not public.is_current_creator() then raise exception 'Creator account required'; end if;
  return query select s.key,s.value from public.secrets s where s.key=p_key;
end $$;


--
-- Name: get_setting_v2(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_setting_v2(p_key text) RETURNS TABLE(id integer, key text, value text, label text, description text, category text, data_type text, is_active boolean, updated_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
                                                                                                                                                SELECT 
                                                                                                                                                    ps.id,
                                                                                                                                                        ps.key,
                                                                                                                                                            ps.value,
                                                                                                                                                                ps.label,
                                                                                                                                                                    ps.description,
                                                                                                                                                                        ps.category,
                                                                                                                                                                            ps.data_type,
                                                                                                                                                                                ps.is_active,
                                                                                                                                                                                    ps.updated_at
                                                                                                                                                                                      FROM platform_settings ps
                                                                                                                                                                                        WHERE ps.key = p_key
                                                                                                                                                                                            AND ps.is_active = true
                                                                                                                                                                                                AND ps.key NOT LIKE '%secret%'
                                                                                                                                                                                                    AND ps.key NOT LIKE '%api_key%'
                                                                                                                                                                                                        AND ps.key NOT LIKE '%private%'
                                                                                                                                                                                                            AND ps.key NOT LIKE '%password%'
                                                                                                                                                                                                                AND ps.key NOT LIKE '%token%'
                                                                                                                                                                                                                  LIMIT 1;
                                                                                                                                                                                                                  $$;


--
-- Name: get_short_let_date_availability(text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_short_let_date_availability(p_listing_id text, p_check_in date, p_check_out date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_listing public.listings;
  v_min_nights integer:=1;
  v_max_nights integer:=90;
  v_advance_days integer:=365;
  v_nights integer;
  v_available boolean:=false;
  v_reason text;
begin
  select * into v_listing
  from public.listings l
  where (l.id::text=p_listing_id or l.listing_id=p_listing_id)
    and l.sub_type='short_let'
    and l.deleted_at is null
    and l.inspection_request_id is not null
    and l.approved_at is not null
  limit 1;

  if v_listing.id is null then
    return jsonb_build_object('available',false,'reason','not_found');
  end if;
  if v_listing.status<>'available' or v_listing.availability_status<>'available' then
    return jsonb_build_object('available',false,'reason','not_published');
  end if;

  select coalesce(nullif(value,'')::integer,1) into v_min_nights
  from public.platform_settings
  where key='short_stay_min_nights' and coalesce(is_active,true)
  limit 1;
  select coalesce(nullif(value,'')::integer,90) into v_max_nights
  from public.platform_settings
  where key='short_stay_max_nights' and coalesce(is_active,true)
  limit 1;
  select coalesce(nullif(value,'')::integer,365) into v_advance_days
  from public.platform_settings
  where key='short_stay_booking_advance_days' and coalesce(is_active,true)
  limit 1;

  v_min_nights:=greatest(coalesce(v_min_nights,1),1);
  v_max_nights:=greatest(coalesce(v_max_nights,90),v_min_nights);
  v_advance_days:=greatest(coalesce(v_advance_days,365),v_max_nights);

  if p_check_in is null or p_check_out is null or p_check_in<current_date
      or p_check_out<=p_check_in then
    v_reason:='invalid_dates';
  elsif p_check_in>current_date+v_advance_days
      or p_check_out>current_date+v_advance_days then
    v_reason:='outside_booking_window';
  else
    v_nights:=p_check_out-p_check_in;
    if v_nights<v_min_nights or v_nights>v_max_nights then
      v_reason:='invalid_length';
    elsif exists(
      select 1
      from public.reservations r
      where r.listing_id=v_listing.id::text
        and r.stay_type='short_let'
        and r.status=any(array['reserved','ready_for_move_in','occupied']::text[])
        and daterange(r.stay_check_in,r.stay_check_out,'[)')
          && daterange(p_check_in,p_check_out,'[)')
    ) then
      v_reason:='dates_unavailable';
    else
      v_available:=true;
      v_reason:='available';
    end if;
  end if;

  return jsonb_build_object(
    'available',v_available,
    'reason',v_reason,
    'nights',case when p_check_in is not null and p_check_out is not null
      then p_check_out-p_check_in else null end,
    'min_nights',v_min_nights,
    'max_nights',v_max_nights
  );
end
$$;


--
-- Name: get_short_stay_unavailable_listing_ids(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_short_stay_unavailable_listing_ids(p_check_in date, p_check_out date) RETURNS TABLE(listing_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if (select auth.uid()) is null then raise exception 'Authentication required'; end if;
  if p_check_in is null or p_check_out is null or p_check_out<=p_check_in then raise exception 'Valid dates required'; end if;

  return query
  select distinct r.listing_id
  from public.reservations r
  join public.listings l on l.id::text=r.listing_id
  where l.sub_type='short_let'
    and r.stay_type='short_let'
    and r.status=any(array['payment_pending','reserved','inspection_pending','ready_for_move_in','occupied']::text[])
    and (
      r.status<>'payment_pending'
      or r.payment_expires_at is null
      or r.payment_expires_at>now()
      or exists(
        select 1 from public.booking_payments bp
        where bp.paystack_reference=r.payment_reference
          and bp.status in ('paid','completed')
      )
    )
    and daterange(r.stay_check_in,r.stay_check_out,'[)') && daterange(p_check_in,p_check_out,'[)');
end;
$$;


--
-- Name: get_staff_rating(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_rating(p_staff_user_id text) RETURNS TABLE(avg_rating numeric, review_count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(AVG("Rating"), 0)::NUMERIC, COUNT(*)::BIGINT 
  FROM staff_reviews WHERE staff_id = p_staff_user_id;
$$;


--
-- Name: get_staff_worker_identity_check(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_worker_identity_check(p_worker_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_check public.worker_identity_checks;
BEGIN
  IF NOT public.current_staff_can_review_worker(p_worker_id) THEN RAISE EXCEPTION 'Worker is outside your verification scope'; END IF;
  SELECT * INTO v_check FROM public.worker_identity_checks WHERE worker_id=p_worker_id;
  RETURN jsonb_build_object('status',COALESCE(v_check.status,'not_started'),'face_match_score',v_check.face_match_score,'liveness_score',v_check.liveness_score,'anti_spoof_score',v_check.anti_spoof_score,'challenge_version',v_check.challenge_version,'captured_at',v_check.captured_at,'attempt_count',COALESCE(v_check.attempt_count,0));
END; $$;


--
-- Name: get_support_messages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_support_messages(p_conversation_id uuid) RETURNS TABLE(id uuid, sender_id text, sender_name text, sender_role text, content text, attachments text[], attachment_types text[], action_type text, action_metadata jsonb, visibility text, is_read boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conversation public.partner_support_conversations;
  v_team boolean;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then raise exception 'Authentication required'; end if;
  select * into v_conversation from public.partner_support_conversations
  where id=p_conversation_id;
  if v_conversation.id is null then raise exception 'Conversation not found'; end if;
  if not public.current_actor_can_access_operational_conversation(
    p_conversation_id,false
  ) then raise exception 'Not authorised'; end if;
  v_team:=v_actor.user_id<>v_conversation.partner_id;

  return query
  select m.id,m.sender_id,coalesce(p.full_name,p.username,'WeHouse'),
    m.sender_role,m.content,m.attachments,m.attachment_types,m.action_type,
    coalesce(m.action_metadata,'{}'::jsonb),m.visibility,m.is_read,m.created_at
  from public.partner_support_messages m
  left join public.profiles p on p.user_id=m.sender_id
  where m.conversation_id=p_conversation_id
    and (m.visibility='customer' or v_team)
  order by m.created_at;
end
$$;


--
-- Name: conversations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    participant_a text NOT NULL,
    participant_b text NOT NULL,
    listing_id text,
    last_message text,
    last_message_at timestamp with time zone DEFAULT now(),
    unread_a integer DEFAULT 0,
    unread_b integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now(),
    status text DEFAULT 'pending'::text,
    conversation_type text DEFAULT 'direct'::text,
    subject text,
    hidden_at_a timestamp with time zone,
    hidden_at_b timestamp with time zone
);


--
-- Name: get_user_conversations(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_conversations(p_user_id text) RETURNS SETOF public.conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  actor public.profiles;
begin
  actor := public._current_comm_actor();
  if actor is null then
    raise exception 'Authentication required';
  end if;
  if p_user_id is distinct from actor.user_id then
    raise exception 'User identity mismatch';
  end if;

  return query
    select conversation.*
    from public.conversations conversation
    where (conversation.participant_a = actor.user_id or conversation.participant_b = actor.user_id)
      and public._can_access_conversation(conversation.id)
      and public._conversation_route_allowed(conversation.id, actor.user_id)
      and exists (
        select 1
        from public.messages message
        where message.conversation_id = conversation.id
      )
      and (
        (conversation.participant_a = actor.user_id and (conversation.hidden_at_a is null or conversation.last_message_at > conversation.hidden_at_a))
        or
        (conversation.participant_b = actor.user_id and (conversation.hidden_at_b is null or conversation.last_message_at > conversation.hidden_at_b))
      )
    order by conversation.last_message_at desc nulls last, conversation.created_at desc;
end;
$$;


--
-- Name: get_withdrawal_payout_snapshot(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_withdrawal_payout_snapshot(p_withdrawal_id uuid, p_reviewer_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_reviewer public.profiles;v_withdrawal public.withdrawals;v_wallet public.wallets;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then raise exception 'Service role required'; end if;
  if not public.finance_reviewer_is_authorized(p_reviewer_id) then raise exception 'Finance permission required'; end if;
  select * into v_reviewer from public.profiles where user_id=p_reviewer_id;
  select * into v_withdrawal from public.withdrawals where id=p_withdrawal_id;
  select * into v_wallet from public.wallets where id=v_withdrawal.wallet_id;
  if v_reviewer.user_id is null or v_withdrawal.id is null or v_wallet.id is null then raise exception 'Payout record not found'; end if;
  if v_wallet.owner_id=p_reviewer_id then raise exception 'You cannot review your own withdrawal'; end if;
  if v_reviewer.role in ('staff','admin') and not public.can_current_actor_read_profile_for(v_reviewer.user_id,v_wallet.owner_id) then raise exception 'Withdrawal is outside your branch'; end if;
  return jsonb_build_object(
    'success',true,'withdrawal_id',v_withdrawal.id,'status',v_withdrawal.status,
    'amount',v_withdrawal.amount,'reference',v_withdrawal.paystack_transfer_reference,
    'transfer_code',v_withdrawal.paystack_transfer_code,'paystack_status',v_withdrawal.paystack_status
  );
end;
$$;


--
-- Name: get_worker_marketplace_trust(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_worker_marketplace_trust(p_worker_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_worker public.profiles; v_enabled boolean:=false; v_min_jobs integer:=5;
  v_min_rating numeric:=4.5; v_max_cancel numeric:=20; v_block_disputes boolean:=true;
  v_completed integer:=0; v_worker_cancelled integer:=0; v_open_disputes integer:=0;
  v_cancel_rate numeric:=0; v_trusted boolean:=false; v_pro boolean:=false;
begin
  if (select auth.uid()) is null then raise exception 'Authentication required'; end if;
  select * into v_worker from public.profiles where user_id=p_worker_id and public.user_has_active_workspace(user_id,'worker')
    and worker_status='verified' and worker_verified=true
    and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_worker is null then return jsonb_build_object('reviewed',false,'trusted',false,'pro_active',false); end if;
  select coalesce(lower(value) in('true','1','yes','on'),false) into v_enabled from public.platform_settings where key='worker_trust_enabled' and is_active=true limit 1;
  select coalesce(nullif(value,''),'5')::integer into v_min_jobs from public.platform_settings where key='worker_trusted_min_completed_jobs' and is_active=true limit 1;
  select coalesce(nullif(value,''),'4.5')::numeric into v_min_rating from public.platform_settings where key='worker_trusted_min_rating' and is_active=true limit 1;
  select coalesce(nullif(value,''),'20')::numeric into v_max_cancel from public.platform_settings where key='worker_trusted_max_cancel_rate' and is_active=true limit 1;
  select coalesce(lower(value) in('true','1','yes','on'),true) into v_block_disputes from public.platform_settings where key='worker_trusted_block_open_disputes' and is_active=true limit 1;
  select count(*) into v_completed from public.worker_bookings where worker_id=p_worker_id and status='approved_released';
  select count(*) into v_worker_cancelled from public.worker_bookings where worker_id=p_worker_id and status='cancelled' and cancelled_by=p_worker_id;
  select count(*) into v_open_disputes from public.worker_bookings where worker_id=p_worker_id and status='disputed';
  if v_completed+v_worker_cancelled>0 then v_cancel_rate:=round((v_worker_cancelled::numeric*100)/(v_completed+v_worker_cancelled),2); end if;
  v_trusted:=coalesce(v_enabled,false) and v_completed>=coalesce(v_min_jobs,5)
    and coalesce(v_worker.rating,0)>=coalesce(v_min_rating,4.5)
    and v_cancel_rate<=coalesce(v_max_cancel,20)
    and (not coalesce(v_block_disputes,true) or v_open_disputes=0);
  v_pro:=public.worker_pro_is_active(p_worker_id);
  return jsonb_build_object(
    'reviewed',true,'trusted',v_trusted,'trusted_enabled',coalesce(v_enabled,false),
    'pro_active',v_pro,'pro_label',case when v_pro then 'PRO' else null end,
    'completed_jobs',v_completed,'rating',coalesce(v_worker.rating,0),'review_count',coalesce(v_worker.review_count,0),
    'worker_cancel_rate',v_cancel_rate,'open_disputes',v_open_disputes,
    'label',case when v_trusted then 'WeHouse Trusted' else 'WeHouse Reviewed' end
  );
end;
$$;


--
-- Name: get_worker_showcase_post_comments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_worker_showcase_post_comments(p_post_id uuid) RETURNS TABLE(id uuid, user_id text, body text, created_at timestamp with time zone, display_name text, avatar_url text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
begin
  select * into v_actor
  from public.profiles
  where auth_id=auth.uid()::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then raise exception 'Sign in to view comments'; end if;

  if not exists (
    select 1 from public.worker_showcase_posts p
    where p.id=p_post_id
      and p.deleted_at is null
      and (
        p.worker_id=v_actor.user_id
        or (p.hidden_at is null and (p.expires_at is null or p.expires_at>now()))
      )
  ) then raise exception 'Work post is not available'; end if;

  return query
  select c.id,c.user_id,c.body,c.created_at,
    coalesce(nullif(btrim(p.full_name),''),nullif(btrim(p.username),''),'WeHouse member'),
    p.avatar_url
  from public.worker_showcase_comments c
  join public.profiles p on p.user_id=c.user_id
  where c.post_id=p_post_id and c.deleted_at is null
  order by c.created_at;
end;
$$;


--
-- Name: get_worker_showcase_reactions(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_worker_showcase_reactions(p_worker_id text) RETURNS TABLE(post_id uuid, emoji text, reaction_count bigint, mine boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  with actor as (
    select user_id from public.profiles where auth_id=(select auth.uid())::text limit 1
  )
  select r.post_id,r.emoji,count(*)::bigint,
    bool_or(r.user_id=(select user_id from actor))
  from public.worker_showcase_reactions r
  join public.worker_showcase_posts p on p.id=r.post_id
  where p.worker_id=p_worker_id and p.deleted_at is null and p.hidden_at is null
  group by r.post_id,r.emoji;
$$;


--
-- Name: get_worker_verification_chats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_worker_verification_chats() RETURNS TABLE(id uuid, participant_a text, participant_b text, status text, last_message text, last_message_at timestamp with time zone, unread_a integer, unread_b integer, created_at timestamp with time zone, conversation_type text, subject text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
  SELECT id, participant_a, participant_b, status, last_message,
    last_message_at, unread_a, unread_b, created_at,
    conversation_type, subject
  FROM public.conversations
  WHERE conversation_type = 'worker_verification'
  ORDER BY last_message_at DESC NULLS LAST;
$$;


--
-- Name: guard_accommodation_release_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_accommodation_release_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_deadline timestamptz;
  v_open_issue boolean;
  v_state text;
begin
  if new.action_type not in ('release_short_let_stay','release_hotel_stay') then
    return new;
  end if;
  if new.status not in ('pending','claimed') then return new; end if;
  if new.action_type='release_short_let_stay' then
    select reservation.arrival_issue_deadline_at,
      exists(select 1 from public.operational_cases case_row
        where case_row.subject_type='short_let' and case_row.subject_id=reservation.id
          and case_row.status not in ('resolved','closed'))
    into v_deadline,v_open_issue
    from public.reservations reservation where reservation.id=new.subject_id;
  else
    select booking.arrival_issue_deadline_at,
      exists(select 1 from public.operational_cases case_row
        where case_row.subject_type='hotel' and case_row.subject_id=booking.booking_id::text
          and case_row.status not in ('resolved','closed'))
    into v_deadline,v_open_issue
    from public.hotel_bookings booking where booking.booking_id::text=new.subject_id;
  end if;
  select protection_state into v_state from public.payment_protection_transactions
  where id=new.payment_protection_id;
  if v_deadline is null or now()<v_deadline or coalesce(v_open_issue,false)
     or v_state not in ('protected','release_eligible') then
    return null;
  end if;
  return new;
end
$$;


--
-- Name: guard_blocked_worker_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_blocked_worker_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_user text;v_worker text;
begin
  if tg_table_name='worker_bookings' then v_user:=new.user_id;v_worker:=new.worker_id;
  else
    select c.user_id,c.worker_id into v_user,v_worker from public.booking_conversations c where c.id=new.conversation_id;
  end if;
  if exists(select 1 from public.worker_user_blocks b where (b.blocker_user_id=v_user and b.blocked_user_id=v_worker) or (b.blocker_user_id=v_worker and b.blocked_user_id=v_user)) then
    raise exception 'This person is blocked. The Worker conversation cannot continue.';
  end if;
  return new;
end;
$$;


--
-- Name: guard_connected_hotel_domain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_connected_hotel_domain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_hotel_id integer:=case when tg_op='DELETE' then old.hotel_id else new.hotel_id end;
  v_domain text:=tg_argv[0];
begin
  if coalesce(auth.role(),'')<>'service_role'
     and public.hotel_integration_owns_domain(v_hotel_id,v_domain) then
    raise exception 'The certified PMS is the authority for hotel %',v_domain;
  end if;
  return case when tg_op='DELETE' then old else new end;
end;
$$;


--
-- Name: guard_inspected_public_hotel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_inspected_public_hotel() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NEW.status='active' AND (NEW.inspection_request_id IS NULL OR NEW.approved_by IS NULL OR NEW.approved_at IS NULL) THEN RAISE EXCEPTION 'Public hotels must come through the inspection publication workflow'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_inspected_public_listing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_inspected_public_listing() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_status TEXT;
BEGIN
  IF NEW.status='available' OR NEW.availability_status='available' THEN
    IF NEW.inspection_request_id IS NULL OR NEW.approved_by IS NULL OR NEW.approved_at IS NULL THEN RAISE EXCEPTION 'Public listings must come through the completed inspection publication workflow'; END IF;
    SELECT status INTO v_status FROM public.inspection_requests WHERE id=NEW.inspection_request_id;
    IF v_status NOT IN ('completed','approved') THEN RAISE EXCEPTION 'Linked inspection must be complete before publication'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_pms_owned_hotel_domain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_pms_owned_hotel_domain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_hotel_id integer; v_domain text;
begin
  if coalesce((select auth.role()),'')='service_role' then
    return coalesce(new,old); end if;
  if tg_table_name='hotel_rooms' then
    v_hotel_id:=coalesce(new.hotel_id,old.hotel_id);v_domain:='rooms';
  elsif tg_table_name='hotel_rate_plans' then
    v_hotel_id:=coalesce(new.hotel_id,old.hotel_id);v_domain:='rates';
  elsif tg_table_name='hotel_inventory_daily' then
    v_hotel_id:=coalesce(new.hotel_id,old.hotel_id);v_domain:='inventory';
  else return coalesce(new,old);
  end if;
  if public.hotel_integration_owns_domain(v_hotel_id,v_domain) then
    raise exception 'This hotel % domain is managed by its connected PMS',v_domain;
  end if;
  return coalesce(new,old);
end
$$;


--
-- Name: guard_retired_worker_identity_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_retired_worker_identity_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if nullif(btrim(coalesce(new.gov_id_type,'')),'') is not null
      or nullif(btrim(coalesce(new.gov_id_number,'')),'') is not null
      or nullif(btrim(coalesce(new.gov_id_photo_url,'')),'') is not null
      or nullif(btrim(coalesce(new.selfie_photo_url,'')),'') is not null
      or nullif(btrim(coalesce(new.identity_provider,'')),'') is not null
      or nullif(btrim(coalesce(new.identity_reference,'')),'') is not null
    then raise exception 'Government/external identity fields are retired. Use the private WeHouse automatic face check.';
    end if;
  elsif (new.gov_id_type,new.gov_id_number,new.gov_id_photo_url,new.selfie_photo_url,new.identity_provider,new.identity_reference)
        is distinct from
        (old.gov_id_type,old.gov_id_number,old.gov_id_photo_url,old.selfie_photo_url,old.identity_provider,old.identity_reference)
    and (
      nullif(btrim(coalesce(new.gov_id_type,'')),'') is not null
      or nullif(btrim(coalesce(new.gov_id_number,'')),'') is not null
      or nullif(btrim(coalesce(new.gov_id_photo_url,'')),'') is not null
      or nullif(btrim(coalesce(new.selfie_photo_url,'')),'') is not null
      or nullif(btrim(coalesce(new.identity_provider,'')),'') is not null
      or nullif(btrim(coalesce(new.identity_reference,'')),'') is not null
    )
  then raise exception 'Government/external identity fields are retired. Use the private WeHouse automatic face check.';
  end if;
  return new;
end;
$$;


--
-- Name: guard_reviewed_hotel_commercial_facts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_reviewed_hotel_commercial_facts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if old.inspection_request_id is not null
     and current_user not in ('postgres','service_role')
     and (
       new.name is distinct from old.name or new.state is distinct from old.state
       or new.city is distinct from old.city or new.area is distinct from old.area
       or new.address is distinct from old.address or new.amenities is distinct from old.amenities
       or new.owner_id is distinct from old.owner_id
       or new.gps_latitude is distinct from old.gps_latitude
       or new.gps_longitude is distinct from old.gps_longitude
       or new.inspection_request_id is distinct from old.inspection_request_id
     ) then
    raise exception 'Verified hotel facts are read-only. Return the hotel for correction.';
  end if;
  return new;
end;
$$;


