--
-- Name: hotel_allowed_capabilities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hotel_allowed_capabilities() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select array[
    'stay.read','stay.message','stay.assign_unit','stay.check_in','stay.check_out',
    'stay.modify_commercial','room.mark_ready','hotel.inventory.manage',
    'hotel.rate.manage','hotel.policy.manage','hotel.team.manage'
  ]::text[]
$$;


--
-- Name: hotel_capabilities_valid(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hotel_capabilities_valid(p_caps text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(p_caps,array[]::text[]) <@ public.hotel_allowed_capabilities()
$$;


--
-- Name: hotel_default_capabilities(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hotel_default_capabilities(p_role text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case p_role
    when 'owner' then public.hotel_allowed_capabilities()
    when 'manager' then array[
      'stay.read','stay.message','stay.assign_unit','stay.check_in','stay.check_out',
      'room.mark_ready','hotel.inventory.manage','hotel.rate.manage'
    ]::text[]
    when 'front_desk' then array[
      'stay.read','stay.message','stay.assign_unit','stay.check_in','stay.check_out',
      'room.mark_ready'
    ]::text[]
    when 'staff' then array[
      'stay.read','stay.message','stay.assign_unit','stay.check_in','stay.check_out',
      'room.mark_ready'
    ]::text[] -- compatibility input; stored role is front_desk
    else array[]::text[]
  end
$$;


--
-- Name: hotel_integration_owns_domain(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hotel_integration_owns_domain(p_hotel_id integer, p_domain text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1 from public.hotel_integrations integration
    where integration.hotel_id=p_hotel_id
      and p_domain=any(integration.authoritative_domains)
      and public.hotel_integration_runtime_active(integration.integration_id)
  )
$$;


--
-- Name: hotel_integration_runtime_active(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hotel_integration_runtime_active(p_integration_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1
    from public.hotel_integrations integration
    join public.hotel_pms_providers provider
      on provider.provider_key=integration.provider
    join public.hotels hotel on hotel.hotel_id=integration.hotel_id
    where integration.integration_id=p_integration_id
      and integration.status='active'
      and provider.certification_status='certified'
      and hotel.status='active'
      and public._legal_launch_gate_is_approved('hotel_marketplace')
      and public._legal_launch_gate_is_approved('hotel_pms_connected_mode')
  )
$$;


--
-- Name: hotel_payment_protection_is_current(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hotel_payment_protection_is_current(p_protection_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare v_result boolean:=false;
begin
  if p_protection_id is null then return false; end if;
  if exists(
    select 1 from information_schema.columns
    where table_schema='public' and table_name='payment_protection_transactions'
      and column_name='protection_state'
  ) then
    execute 'select exists(select 1 from public.payment_protection_transactions
      where id=$1 and protection_state in (''protected'',''release_eligible''))'
      into v_result using p_protection_id;
  else
    execute 'select exists(select 1 from public.payment_protection_transactions
      where id=$1 and status=''protected'')'
      into v_result using p_protection_id;
  end if;
  return coalesce(v_result,false);
end;
$_$;


