--
-- Name: infer_notification_workspace_scope(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.infer_notification_workspace_scope(p_recipient_id text, p_type text, p_source_type text, p_destination_route text, p_title text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_value text := lower(concat_ws(' ',p_type,p_source_type,p_destination_route));
  v_role text;
begin
  if v_value ~ '(security|new_device|device_confirmation|password|login)' then return 'account'; end if;
  if v_value ~ '(roommate|shared_home|reservation|work_post_confirmation|worker_replied)' then return 'personal'; end if;
  if v_value ~ '(system|audit|payment_conflict|escalat|rent_paid)' then return 'creator'; end if;
  if v_value ~ '(operations_issue|finance_issue|verification_issue|support_ticket|staff_)' then return 'staff'; end if;
  if v_value ~ '(worker_booking|worker_job|worker_profile|worker_verification|customer_message|new_booking|review_received)' then return 'worker'; end if;
  if v_value ~ '(property_partner|property_submission|listing_|inspection_assigned|booking_received|partner_)' then return 'partner'; end if;
  if v_value ~ '(booking_confirmed|payment_successful|refund_completed|hotel_booking)' then return 'personal'; end if;

  select p.role into v_role from public.profiles p where p.user_id=p_recipient_id limit 1;
  if v_role='property_partner' then return 'partner'; end if;
  if v_role='worker' then return 'worker'; end if;
  if v_role='staff' then return 'staff'; end if;
  if v_role='admin' then return 'admin'; end if;
  if v_role='creator' then return 'creator'; end if;
  return 'personal';
end;
$$;


--
-- Name: inherit_short_let_guest_capacity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inherit_short_let_guest_capacity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.sub_type='short_let' then
    if new.inspection_request_id is not null then
      select ir.max_guests
      into new.max_guests
      from public.inspection_requests ir
      where ir.id=new.inspection_request_id;
    end if;
    if new.max_guests is null or new.max_guests<1 then
      raise exception 'Property Partner must choose the Short Let guest capacity';
    end if;
  else
    new.max_guests := null;
  end if;
  return new;
end
$$;


--
-- Name: invalidate_inspection_media_review(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_inspection_media_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_inspection_id uuid;
begin
  if tg_table_name = 'listings' then
    v_inspection_id := case when tg_op = 'DELETE' then old.inspection_request_id else new.inspection_request_id end;
  elsif tg_table_name = 'hotels' then
    v_inspection_id := case when tg_op = 'DELETE' then old.inspection_request_id else new.inspection_request_id end;
  else
    select inspection_request_id into v_inspection_id from public.hotels
    where hotel_id = case when tg_op = 'DELETE' then old.hotel_id else new.hotel_id end;
  end if;
  if v_inspection_id is not null then
    update public.inspection_requests
    set final_media_reviewed_at = null, final_media_reviewed_by = null, updated_at = now()
    where id = v_inspection_id;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: is_current_announcement_recipient(bigint); Type: FUNCTION; Schema: public; Owner: -
--

