--
-- Name: is_current_creator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_current_creator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists(
    select 1 from public.profiles p
    where p.auth_id=auth.uid()::text
      and p.role='creator'
      and coalesce(p.deleted,false)=false
      and coalesce(p.suspended,false)=false
      and coalesce(p.banned,false)=false
  );
$$;


--
-- Name: is_staff_or_creator(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_staff_or_creator(uid text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.auth_id = uid
      AND p.role IN ('staff','admin','creator')
      AND COALESCE(p.deleted,false)=false
      AND COALESCE(p.suspended,false)=false
      AND COALESCE(p.banned,false)=false
  );
$$;


--
-- Name: is_username_available(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_username_available(p_username text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE
    WHEN auth.uid() IS NULL OR NULLIF(btrim(p_username),'') IS NULL THEN false
    ELSE NOT EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE lower(p.username)=lower(btrim(p_username))
        AND p.user_id<>COALESCE(public.current_profile_user_id(),'')
    )
  END;
$$;


--
-- Name: is_valid_inspection_public_image(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_valid_inspection_public_image(p_inspection_id uuid, p_public_url text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'storage'
    AS $$
  select position('/storage/v1/object/public/listing-images/' in coalesce(p_public_url,'')) > 0
     and exists (
       select 1 from storage.objects object
       where object.bucket_id = 'listing-images'
         and object.name = split_part(p_public_url,'/storage/v1/object/public/listing-images/',2)
         and (storage.foldername(object.name))[1] = 'listings'
         and (storage.foldername(object.name))[2] = 'final-' || p_inspection_id::text
     );
$$;


--
-- Name: issue_creator_elevation_from_service(uuid, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_creator_elevation_from_service(p_auth_user_id uuid, p_auth_session_id text, p_action_classes text[], p_verification_method text, p_ip_hash text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_creator public.profiles;
  v_id uuid;
  v_method text;
begin
  if (select auth.role())<>'service_role' then
    raise exception 'service role required';
  end if;
  if coalesce(cardinality(p_action_classes),0)=0 then
    raise exception 'At least one action class is required';
  end if;
  select * into v_creator
  from public.profiles p
  where p.auth_id=p_auth_user_id::text
    and p.role='creator'
    and exists(
      select 1 from public.workspace_role_assignments w
      where w.user_id=p.user_id and w.workspace_role='creator'
        and w.status='active' and w.scope_type='global'
    )
    and not coalesce(p.deleted,false)
    and not coalesce(p.suspended,false)
    and not coalesce(p.banned,false)
  limit 1;
  if v_creator.user_id is null then raise exception 'Creator authority required'; end if;

  v_method:=case when exists(
    select 1 from auth.mfa_factors f
    where f.user_id=p_auth_user_id and f.status='verified'
  ) then 'password_mfa' else 'password' end;
  if p_verification_method<>v_method then
    raise exception 'Creator MFA assurance does not match enrolled factors';
  end if;

  update public.creator_elevation_grants
  set revoked_at=now()
  where auth_user_id=p_auth_user_id
    and auth_session_id=p_auth_session_id
    and revoked_at is null;

  insert into public.creator_elevation_grants(
    creator_user_id,auth_user_id,auth_session_id,action_classes,
    issued_at,expires_at,verification_method,issued_ip_hash
  ) values(
    v_creator.user_id,p_auth_user_id,p_auth_session_id,
    array(select distinct unnest(p_action_classes)),
    now(),now()+interval '10 minutes',v_method,p_ip_hash
  ) returning creator_elevation_id into v_id;

  insert into public.admin_audit_log(
    admin_id,action,target_type,target_id,details,created_at
  ) values(
    v_creator.user_id,'creator_elevation_issued','creator_session',
    p_auth_session_id,jsonb_build_object(
      'creator_elevation_id',v_id,
      'action_classes',p_action_classes,
      'verification_method',v_method,
      'expires_at',now()+interval '10 minutes'
    )::text,now()
  );
  return v_id;
end
$$;


--
-- Name: lga_booking_prefix(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lga_booking_prefix(p_lga text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_letters text;
BEGIN
  v_letters := upper(regexp_replace(COALESCE(p_lga,''), '[^A-Za-z]', '', 'g'));
  IF length(v_letters) < 3 THEN v_letters := rpad(v_letters, 3, 'X'); END IF;
  IF v_letters = '' THEN v_letters := 'GEN'; END IF;
  RETURN substr(v_letters, 1, 3) || 'WH';
END; $$;


--
-- Name: lock_admin_staff_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_admin_staff_location() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.auth_id = auth.uid()::text AND OLD.role IN ('admin', 'staff') THEN
    IF NEW.assigned_state IS DISTINCT FROM OLD.assigned_state OR NEW.assigned_lga IS DISTINCT FROM OLD.assigned_lga OR NEW.scope IS DISTINCT FROM OLD.scope THEN
      RAISE EXCEPTION 'Operational assignment cannot be changed from Profile. Contact Creator for reassignment.';
    END IF;
  END IF;
  RETURN NEW;
END;$$;


--
-- Name: log_automatic_support_reopen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_automatic_support_reopen() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor_id text := public.current_profile_user_id();
begin
  if old.status in ('resolved','closed') and new.status='open' then
    insert into public.support_case_events(conversation_id,event_type,actor_id,from_status,to_status)
    values(new.id,'reopened',actor_id,old.status,new.status);
  end if;
  return new;
end
$$;


--
-- Name: log_settings_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_settings_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_key text;
  v_old jsonb;
  v_new jsonb;
  v_sensitive boolean;
  v_actor public.profiles;
BEGIN
  v_key := CASE WHEN TG_OP='DELETE' THEN OLD.key ELSE NEW.key END;
  v_old := CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  v_new := CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  v_sensitive := lower(coalesce(v_key,'')) ~ '(secret|password|private[_-]?key|access[_-]?token|refresh[_-]?token|service[_-]?role|webhook[_-]?secret|api[_-]?secret)';

  IF v_sensitive THEN
    IF v_old IS NOT NULL THEN v_old := v_old || jsonb_build_object('value','[REDACTED]'); END IF;
    IF v_new IS NOT NULL THEN v_new := v_new || jsonb_build_object('value','[REDACTED]'); END IF;
  END IF;

  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  BEGIN
    INSERT INTO public.audit_logs(action,target_type,target_id,details,admin_id,admin_email)
    VALUES(TG_OP,'platform_settings',v_key,jsonb_build_object('old_value',v_old,'new_value',v_new)::text,v_actor.user_id,v_actor.email);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'settings_audit_failed: action=%, key=%, error=%',TG_OP,v_key,SQLERRM;
  END;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: manage_staff_permission(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manage_staff_permission(p_staff_id text, p_permission text, p_enabled boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor_role text;
begin
  select role into v_actor_role from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor_role='creator' then
    raise exception 'Recent Creator authentication required';
  end if;
  perform public.manage_staff_permission(
    p_staff_id,p_permission,p_enabled,null::uuid
  );
end
$$;


--
-- Name: manage_staff_permission(text, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manage_staff_permission(p_staff_id text, p_permission text, p_enabled boolean, p_creator_elevation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_target public.profiles;
  v_domain text:=public.canonical_staff_domain(p_permission);
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  select * into v_target from public.profiles
  where user_id=p_staff_id and role='staff' and not coalesce(deleted,false)
  for update;
  if v_actor.role not in('creator','admin') then raise exception 'Not authorised'; end if;
  if v_target.user_id is null then raise exception 'Staff profile not found'; end if;
  if v_domain is null then raise exception 'Invalid Staff work area'; end if;
  if v_actor.role='creator'
     and not public.creator_has_elevation(p_creator_elevation_id,'staff_authority') then
    raise exception 'Recent Creator authentication required';
  end if;
  if v_actor.role='admin' and public.wehouse_state_key(v_actor.assigned_state)
     <>public.wehouse_state_key(v_target.assigned_state) then
    raise exception 'Admin can manage only Staff in the assigned State';
  end if;

  if p_enabled then
    update public.staff_permissions set is_active=false,revoked_at=now()
    where staff_id=p_staff_id and is_active and permission<>v_domain;
    update public.workspace_role_assignments
    set status='revoked',revoked_by=v_actor.user_id,revoked_at=now(),updated_at=now()
    where user_id=p_staff_id and status='active'
      and workspace_role in(
        'property_operations','field_operations','worker_operations',
        'finance_operations','security_operations','support'
      ) and workspace_role<>v_domain;
  end if;

  insert into public.staff_permissions(
    staff_id,permission,granted_by,granted_at,revoked_at,is_active
  ) values(
    p_staff_id,v_domain,v_actor.user_id,
    case when p_enabled then now() else null end,
    case when p_enabled then null else now() end,p_enabled
  ) on conflict(staff_id,permission) do update set
    granted_by=excluded.granted_by,
    granted_at=case when excluded.is_active then now()
      else staff_permissions.granted_at end,
    revoked_at=case when excluded.is_active then null else now() end,
    is_active=excluded.is_active;

  if p_enabled then
    insert into public.workspace_role_assignments(
      user_id,workspace_role,scope_type,scope_state,scope_lga,status,
      granted_by,granted_at,created_at,updated_at
    ) values(
      p_staff_id,v_domain,'state',v_target.assigned_state,v_target.assigned_lga,
      'active',v_actor.user_id,now(),now(),now()
    ) on conflict(user_id,workspace_role) where status='active' do update set
      scope_type='state',scope_state=excluded.scope_state,
      scope_lga=excluded.scope_lga,granted_by=excluded.granted_by,
      granted_at=now(),updated_at=now();
  else
    update public.workspace_role_assignments
    set status='revoked',revoked_by=v_actor.user_id,revoked_at=now(),updated_at=now()
    where user_id=p_staff_id and workspace_role=v_domain and status='active';
  end if;

  insert into public.admin_audit_log(
    admin_id,action,target_type,target_id,details,created_at
  ) values(
    v_actor.user_id,'staff_work_area_changed','profiles',p_staff_id,
    jsonb_build_object('work_area',v_domain,'enabled',p_enabled,
      'actor_role',v_actor.role,'state',v_target.assigned_state,
      'lga',v_target.assigned_lga)::text,now()
  );
end
$$;


--
-- Name: mark_all_my_canonical_activity_read(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_all_my_canonical_activity_read(p_workspace text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_user text:=public.current_profile_user_id(); v_count integer;
begin
  update public.activity_event_audiences set read_at=coalesce(read_at,now())
  where recipient_user_id=v_user and read_at is null
    and (
      workspace=p_workspace
      or (p_workspace='personal' and workspace='account')
      or (p_workspace='partner' and workspace='property_partner')
      or (p_workspace='hotel' and workspace='hotel_staff')
      or (p_workspace in(
        'property_operations','field_operations','worker_operations',
        'finance_operations','security_operations','support'
      ) and workspace='staff')
    );
  get diagnostics v_count=row_count;
  return v_count;
end
$$;


--
-- Name: mark_all_my_notifications_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_all_my_notifications_read() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare affected integer;
begin
  update public.notifications set read=true,read_at=coalesce(read_at,now())
  where recipient_id=public.current_profile_user_id() and not read;
  get diagnostics affected=row_count;
  return affected;
end $$;


--
-- Name: mark_caution_protection_disputed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_caution_protection_disputed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_protection public.payment_protection_transactions;
begin
  select * into v_protection from public.payment_protection_transactions
  where id=new.payment_protection_id for update;
  if v_protection.protection_state not in('protected','release_eligible','partially_released') then
    raise exception 'Caution Payment Protection is not claimable';
  end if;
  insert into public.payment_protection_transitions(
    payment_protection_id,from_state,to_state,event_type,event_key,
    actor_user_id,actor_type,metadata
  ) values(
    v_protection.id,v_protection.protection_state,'disputed',
    'caution_claim_opened','caution-claim-opened:'||new.caution_claim_id::text,
    new.property_facts_reviewed_by,'property_partner',
    jsonb_build_object('caution_claim_id',new.caution_claim_id)
  ) on conflict(event_key) do nothing;
  update public.payment_protection_transactions
  set protection_state='disputed',status='disputed',
      dispute_case_id=coalesce(dispute_case_id,null),updated_at=now()
  where id=v_protection.id;
  return new;
end
$$;


--
-- Name: financial_action_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.financial_action_outbox (
    financial_action_id uuid DEFAULT gen_random_uuid() NOT NULL,
    action_type text NOT NULL,
    subject_type text NOT NULL,
    subject_id text NOT NULL,
    payment_protection_id uuid NOT NULL,
    amount numeric(12,2) NOT NULL,
    idempotency_key text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    last_error text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_by text,
    claimed_at timestamp with time zone,
    provider_action_id text,
    provider_status text,
    provider_response_checksum text,
    provider_submitted_at timestamp with time zone,
    reconciliation_due_at timestamp with time zone,
    CONSTRAINT financial_action_outbox_action_type_check CHECK ((action_type = ANY (ARRAY['refund_caution_undisputed'::text, 'refund_caution_balance'::text, 'release_caution_award'::text, 'refund_unclaimed_caution'::text, 'refund_shared_checkout'::text, 'release_worker_payment'::text, 'release_long_let_payment'::text, 'release_short_let_stay'::text, 'release_hotel_stay'::text]))),
    CONSTRAINT financial_action_outbox_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT financial_action_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'provider_pending'::text, 'provider_attention'::text, 'completed'::text, 'failed'::text, 'manual_review'::text])))
);


--
-- Name: mark_financial_action_manual_review(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_financial_action_manual_review(p_financial_action_id uuid, p_reason text) RETURNS public.financial_action_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_action public.financial_action_outbox;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  update public.financial_action_outbox set status='manual_review',
    last_error=left(coalesce(nullif(btrim(p_reason),''),'Provider outcome uncertain'),500),
    updated_at=now()
  where financial_action_id=p_financial_action_id and status='processing'
  returning * into v_action;
  if v_action.financial_action_id is null then raise exception 'Action is not processing'; end if;
  return v_action;
end
$$;


--
-- Name: mark_hotel_booking_messages_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_hotel_booking_messages_read(p_conversation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor_id text;
begin
  select user_id into actor_id from public.profiles where auth_id=(select auth.uid())::text limit 1;
  if actor_id is null or not public.can_access_hotel_booking_conversation(p_conversation_id) then raise exception 'Hotel conversation access denied'; end if;
  update public.hotel_booking_messages set is_read=true
  where conversation_id=p_conversation_id and sender_id<>actor_id and not is_read;
end;
$$;


--
-- Name: mark_my_announcement_read(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_my_announcement_read(p_announcement_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_user_id text; BEGIN SELECT user_id INTO v_user_id FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1; IF v_user_id IS NULL THEN RAISE EXCEPTION 'Profile not found'; END IF; UPDATE public.announcement_recipients SET read_status=true WHERE announcement_id=p_announcement_id AND user_id=v_user_id AND COALESCE(read_status,false)=false; UPDATE public.announcements a SET read_count=(SELECT count(*) FROM public.announcement_recipients ar WHERE ar.announcement_id=a.id AND ar.read_status=true) WHERE a.id=p_announcement_id AND EXISTS(SELECT 1 FROM public.announcement_recipients ar WHERE ar.announcement_id=a.id AND ar.user_id=v_user_id); END; $$;


--
-- Name: mark_my_booking_messages_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_my_booking_messages_read(p_conversation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_conv public.booking_conversations;
BEGIN
  v_actor:=public._current_comm_actor();
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT * INTO v_conv
  FROM public.booking_conversations
  WHERE id=p_conversation_id;

  IF v_conv IS NULL OR v_actor.user_id NOT IN (v_conv.user_id,v_conv.worker_id) THEN
    RAISE EXCEPTION 'Not authorized for this booking conversation';
  END IF;

  UPDATE public.booking_messages
  SET is_read=true
  WHERE conversation_id=p_conversation_id
    AND sender_id<>v_actor.user_id
    AND COALESCE(is_read,false)=false;
END;
$$;


--
-- Name: mark_my_canonical_activity_read(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_my_canonical_activity_read(p_activity_event_id uuid, p_workspace text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_user text:=public.current_profile_user_id();
begin
  update public.activity_event_audiences set read_at=coalesce(read_at,now())
  where activity_event_id=p_activity_event_id and recipient_user_id=v_user
    and (
      workspace=p_workspace
      or (p_workspace='personal' and workspace='account')
      or (p_workspace='partner' and workspace='property_partner')
      or (p_workspace='hotel' and workspace='hotel_staff')
      or (p_workspace in(
        'property_operations','field_operations','worker_operations',
        'finance_operations','security_operations','support'
      ) and workspace='staff')
    );
  return found;
end
$$;


--
-- Name: mark_my_conversation_seen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_my_conversation_seen(p_conversation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.profiles; c public.conversations;
BEGIN
  SELECT * INTO a FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF a IS NULL OR NOT public._can_access_conversation(p_conversation_id) THEN
    RAISE EXCEPTION 'Not authorized for this conversation';
  END IF;

  SELECT * INTO c FROM public.conversations WHERE id=p_conversation_id FOR UPDATE;

  UPDATE public.messages
  SET seen=true
  WHERE conversation_id=p_conversation_id
    AND sender_id<>a.user_id
    AND COALESCE(seen,false)=false;

  IF c.participant_a=a.user_id AND COALESCE(c.unread_a,0)<>0 THEN
    UPDATE public.conversations SET unread_a=0 WHERE id=p_conversation_id;
  ELSIF c.participant_b=a.user_id AND COALESCE(c.unread_b,0)<>0 THEN
    UPDATE public.conversations SET unread_b=0 WHERE id=p_conversation_id;
  END IF;
END;
$$;


--
-- Name: mark_my_notification_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_my_notification_read(p_notification_id uuid) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  update public.notifications set read=true,read_at=coalesce(read_at,now())
  where id=p_notification_id and recipient_id=public.current_profile_user_id()
  returning true;
$$;


--
-- Name: mark_my_reservation_support_contacted(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_my_reservation_support_contacted(p_reservation_id text) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_user_id text; v_result public.reservations;
BEGIN
  SELECT user_id INTO v_user_id FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  UPDATE public.reservations SET support_contacted=true,updated_at=now()
  WHERE id=p_reservation_id AND user_id=v_user_id
  RETURNING * INTO v_result;
  IF v_result IS NULL THEN RAISE EXCEPTION 'Reservation not found'; END IF;
  RETURN v_result;
END;
$$;


--
-- Name: mark_my_worker_invoice_paid_offline(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_my_worker_invoice_paid_offline(p_document_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_worker text;
begin
  select profile.user_id into v_worker from public.profiles profile
  where profile.auth_id=(select auth.uid())::text
    and public.user_has_active_workspace(profile.user_id,'worker') limit 1;
  if v_worker is null or not public.worker_pro_is_active(v_worker) then
    raise exception 'An active paid Worker plan is required to update documents';
  end if;
  update public.worker_work_documents set payment_status='marked_paid_by_worker',
    marked_paid_at=now(),updated_at=now()
  where id=p_document_id and worker_id=v_worker and document_type='invoice'
    and document_status in('sent','accepted') and payment_status='unpaid';
  return found;
end;
$$;


--
-- Name: mark_support_messages_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_support_messages_read(p_conversation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conv public.partner_support_conversations;
  v_staff_ok boolean := false;
begin
  select p.* into v_actor from public.profiles p where p.auth_id=auth.uid()::text limit 1;
  select c.* into v_conv from public.partner_support_conversations c where c.id=p_conversation_id;
  if v_actor.user_id is null or v_conv.id is null then raise exception 'Conversation not found'; end if;
  if v_actor.role='staff' then
    select exists(select 1 from public.staff_permissions sp where sp.staff_id=v_actor.user_id and sp.permission='support' and coalesce(sp.is_active,true) and sp.revoked_at is null) into v_staff_ok;
  end if;
  if not (
    v_actor.user_id=v_conv.partner_id or v_actor.user_id=v_conv.assigned_staff_id
    or v_actor.user_id=v_conv.assigned_field_officer_id or v_actor.role in ('admin','creator')
    or (v_staff_ok and v_conv.assigned_staff_id is null)
  ) then raise exception 'Not authorised'; end if;
  update public.partner_support_messages m set is_read=true
  where m.conversation_id=p_conversation_id and m.sender_id<>v_actor.user_id and not coalesce(m.is_read,false);
end $$;


--
-- Name: message_edit_window_minutes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_edit_window_minutes() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  select greatest(1,least(60,coalesce((select case when trim(value) ~ '^[0-9]+$' then trim(value)::integer end from public.platform_settings where key='message_edit_window_minutes' and is_active=true limit 1),10)));
$_$;


--
-- Name: mirror_notification_to_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mirror_notification_to_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_event_id uuid;
  v_workspace text:=coalesce(nullif(btrim(new.workspace_scope),''),'personal');
  v_state text;
begin
  select coalesce(nullif(btrim(p.assigned_state),''),nullif(btrim(p.state),''))
  into v_state from public.profiles p where p.user_id=new.recipient_id;
  insert into public.activity_events(
    event_key,event_type,subject_type,subject_id,actor_user_id,title,summary,
    route,route_params,occurred_at,created_at
  ) values(
    'notification:'||new.id,new.type,
    coalesce(nullif(btrim(new.source_type),''),'notification'),
    coalesce(nullif(btrim(new.source_id),''),nullif(btrim(new.related_id),''),new.id::text),
    null,new.title,new.message,
    coalesce(nullif(btrim(new.destination_route),''),'activity'),
    coalesce(new.destination_params,'{}'::jsonb),new.created_at,new.created_at
  ) on conflict(event_key) do update set
    title=excluded.title,summary=excluded.summary,route=excluded.route,
    route_params=excluded.route_params
  returning activity_event_id into v_event_id;

  insert into public.activity_event_audiences(
    activity_event_id,recipient_user_id,workspace,domain,state_scope,read_at
  ) values(
    v_event_id,new.recipient_id,v_workspace,
    case when v_workspace in(
      'property_operations','field_operations','worker_operations',
      'finance_operations','security_operations','support'
    ) then v_workspace else null end,
    v_state,case when new.read then coalesce(new.read_at,now()) else null end
  ) on conflict(activity_event_id,recipient_user_id,workspace) do update set
    read_at=case when new.read then coalesce(new.read_at,now())
      else activity_event_audiences.read_at end;
  return new;
end
$$;


--
-- Name: mirror_operational_message_to_canonical_thread(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mirror_operational_message_to_canonical_thread() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_thread uuid;
begin
  if new.visibility='internal' then return new; end if;
  select c.canonical_thread_id into v_thread
  from public.partner_support_conversations c
  where c.id=new.conversation_id;
  if v_thread is null then return new; end if;
  insert into public.canonical_thread_items(
    thread_id,item_type,sender_user_id,body,payload,event_key,created_at
  ) values(
    v_thread,
    case when new.action_type is not null then 'case_action'
      when nullif(btrim(coalesce(new.content,'')),'') is not null then 'message'
      else 'attachment' end,
    new.sender_id,nullif(btrim(coalesce(new.content,'')),''),
    jsonb_build_object(
      'legacy_message_id',new.id,'attachments',coalesce(new.attachments,array[]::text[]),
      'attachment_types',coalesce(new.attachment_types,array[]::text[]),
      'action_type',new.action_type,'action_metadata',coalesce(new.action_metadata,'{}'::jsonb)
    ),'operational_message:'||new.id,new.created_at
  ) on conflict(event_key) do nothing;
  update public.canonical_threads set updated_at=new.created_at
  where thread_id=v_thread;
  return new;
end
$$;


--
-- Name: normalize_hotel_submission_program(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_hotel_submission_program() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare normalized_rooms jsonb;
begin
  if new.property_type <> 'hotel' or new.hotel_program is null then return new; end if;
  select coalesce(jsonb_agg(
    (room - 'rate' - 'max_guests') || jsonb_build_object(
      'nightly_rate', coalesce(room->'nightly_rate', room->'rate'),
      'guest_capacity', coalesce(room->'guest_capacity', room->'max_guests')
    ) order by ordinal
  ), '[]'::jsonb) into normalized_rooms
  from jsonb_array_elements(coalesce(new.hotel_program->'room_types', new.hotel_program->'rooms', '[]'::jsonb))
    with ordinality as submitted(room, ordinal);
  new.hotel_program := jsonb_set(new.hotel_program - 'rooms', '{room_types}', normalized_rooms, true);
  return new;
end $$;


--
-- Name: normalize_legacy_payment_protection_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_legacy_payment_protection_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  new.subject_type:=coalesce(nullif(btrim(new.subject_type),''),nullif(btrim(new.booking_type),''));
  new.subject_id:=coalesce(nullif(btrim(new.subject_id),''),new.booking_id::text);
  if new.subject_type is null or new.subject_id is null then
    raise exception 'Payment Protection subject is required';
  end if;
  new.protection_state:=coalesce(nullif(btrim(new.protection_state),''),'awaiting_funds');
  return new;
end
$$;


--
-- Name: normalize_notification_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_notification_context() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
if new.type='roommate_interest' then
new.source_type:=coalesce(new.source_type,'roommate_interest');
new.source_id:=coalesce(new.source_id,nullif(new.related_id,''));
new.destination_route:=coalesce(new.destination_route,'roommate');
new.destination_params:=coalesce(new.destination_params,'{}'::jsonb)||jsonb_build_object('interestId',new.related_id);
elsif new.type='roommate_match' then
new.source_type:=coalesce(new.source_type,'roommate_conversation');
new.source_id:=coalesce(new.source_id,nullif(new.related_id,''));
new.destination_route:=coalesce(new.destination_route,'messages');
new.destination_params:=coalesce(new.destination_params,'{}'::jsonb)||jsonb_build_object('conversationId',new.related_id);
elsif new.type in ('announcement','official_announcement') then
new.source_type:=coalesce(new.source_type,'announcement');
new.destination_route:=coalesce(new.destination_route,'notifications');
new.destination_params:=coalesce(new.destination_params,'{}'::jsonb)||jsonb_build_object('announcementId',new.related_id);
end if;
return new;
end;$$;


--
-- Name: normalize_support_case_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_support_case_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.case_number is null then new.case_number:=coalesce(old.case_number,'WHC-'||upper(substring(replace(gen_random_uuid()::text,'-','') from 1 for 10))); end if;
  if new.status='open' and (new.assigned_staff_id is not null or new.assigned_field_officer_id is not null) then new.status:='assigned'; end if;
  return new;
end;
$$;


--
-- Name: notify_hotel_booking_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_hotel_booking_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare hotel public.hotels; event_type text; event_title text; event_message text;
begin
  select * into hotel from public.hotels where hotel_id=new.hotel_id;
  if new.status='confirmed' and new.payment_status='paid'
    and (old.status is distinct from new.status or old.payment_status is distinct from new.payment_status) then
    insert into public.notifications(
      recipient_id,type,title,message,related_id,read,source_type,source_id,
      destination_route,destination_params,event_key,workspace_scope
    ) values (
      new.user_id,'hotel_stay_confirmed','Hotel stay confirmed',
      hotel.name||' is confirmed for '||to_char(new.check_in,'Mon DD')||' at '||to_char(hotel.check_in_time,'HH12:MI AM')||'.',
      new.booking_id::text,false,'hotel_booking',new.booking_id::text,'my_reservations',
      jsonb_build_object('bookingId',new.booking_id,'hotelId',new.hotel_id),
      'hotel_booking:'||new.booking_id||':confirmed:'||new.user_id,'personal'
    ) on conflict(recipient_id,event_key) where event_key is not null do nothing;
    if hotel.owner_id is not null then
      insert into public.notifications(
        recipient_id,type,title,message,related_id,read,source_type,source_id,
        destination_route,destination_params,event_key,workspace_scope
      ) values (
        hotel.owner_id,'hotel_reservation_paid','New paid hotel stay',
        coalesce(new.guest_name,'A guest')||' booked '||to_char(new.check_in,'Mon DD')||' to '||to_char(new.check_out,'Mon DD')||'.',
        new.booking_id::text,false,'hotel_booking',new.booking_id::text,'hotel_booking',
        jsonb_build_object('bookingId',new.booking_id,'hotelId',new.hotel_id),
        'hotel_booking:'||new.booking_id||':confirmed:'||hotel.owner_id,'partner'
      ) on conflict(recipient_id,event_key) where event_key is not null do nothing;
    end if;
  elsif new.status='checked_in' and old.status is distinct from new.status then
    event_type:='hotel_checked_in'; event_title:='Hotel check-in completed';
    event_message:='You are checked in at '||hotel.name||'. Checkout is by '||to_char(hotel.check_out_time,'HH12:MI AM')||' on '||to_char(new.check_out,'Mon DD')||'.';
  elsif new.status='checked_out' and old.status is distinct from new.status then
    event_type:='hotel_checked_out'; event_title:='Hotel checkout completed';
    event_message:='Your stay at '||hotel.name||' is complete.';
  else
    return new;
  end if;
  if event_type is not null then
    insert into public.notifications(
      recipient_id,type,title,message,related_id,read,source_type,source_id,
      destination_route,destination_params,event_key,workspace_scope
    ) values (
      new.user_id,event_type,event_title,event_message,new.booking_id::text,false,
      'hotel_booking',new.booking_id::text,'my_reservations',
      jsonb_build_object('bookingId',new.booking_id,'hotelId',new.hotel_id),
      'hotel_booking:'||new.booking_id||':'||new.status||':'||new.user_id,'personal'
    ) on conflict(recipient_id,event_key) where event_key is not null do nothing;
  end if;
  return new;
end;
$$;


--
-- Name: notify_matching_saved_home_searches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_matching_saved_home_searches() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.deleted_at is not null or new.status<>'available' or new.availability_status<>'available' then return new; end if;
  if tg_op='UPDATE' and old.status='available' and old.availability_status='available' then return new; end if;
  with matching as materialized (
    select search.id,search.user_id
    from public.saved_searches search
    where search.search_kind='homes' and search.notifications_enabled
      and (coalesce(search.criteria->>'state','')='' or public.wehouse_state_key(search.criteria->>'state')=public.wehouse_state_key(new.state))
      and (coalesce(search.criteria->>'city','')='' or public.wehouse_lga_key(search.criteria->>'city')=public.wehouse_lga_key(new.city))
      and coalesce((search.criteria->>'min_price')::numeric,0)<=new.price
      and (nullif(search.criteria->>'max_price','') is null or new.price<=(search.criteria->>'max_price')::numeric)
      and (nullif(search.criteria->>'bedrooms','') is null or new.bedrooms>=(search.criteria->>'bedrooms')::integer)
      and (nullif(search.criteria->>'bathrooms','') is null or new.bathrooms>=(search.criteria->>'bathrooms')::integer)
      and (coalesce(search.criteria->>'sub_type','')='' or search.criteria->>'sub_type'=coalesce(new.sub_type,''))
  ), inserted as (
    insert into public.notifications(
      recipient_id,type,title,message,related_id,source_type,source_id,
      destination_route,destination_params,event_key
    )
    select matching.user_id,'saved_search_match','A new home matches your search',
      new.title,new.id::text,'listing',new.id::text,'detail',
      jsonb_build_object('listingId',new.id,'listing_id',new.id),
      concat('saved-search:',matching.id,':listing:',new.id)
    from matching
    on conflict(recipient_id,event_key) where event_key is not null do nothing
    returning recipient_id,event_key
  )
  update public.saved_searches search
  set last_notified_at=now(),updated_at=now()
  from inserted
  where search.user_id=inserted.recipient_id
    and inserted.event_key=concat('saved-search:',search.id,':listing:',new.id);
  return new;
end;
$$;


--
-- Name: notify_matching_saved_hotel_searches(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_matching_saved_hotel_searches(p_hotel_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_hotel public.hotels;
begin
  select * into v_hotel from public.hotels where hotel_id=p_hotel_id;
  if v_hotel.hotel_id is null or v_hotel.status<>'active' or v_hotel.approved_at is null then return; end if;
  with matching as materialized (
    select search.id,search.user_id
    from public.saved_searches search
    where search.search_kind='hotels' and search.notifications_enabled
      and (coalesce(search.criteria->>'query','')='' or lower(v_hotel.name) like '%'||lower(search.criteria->>'query')||'%')
      and (coalesce(search.criteria->>'state','')='' or public.wehouse_state_key(search.criteria->>'state')=public.wehouse_state_key(v_hotel.state))
      and (coalesce(search.criteria->>'city','')='' or public.wehouse_lga_key(search.criteria->>'city')=public.wehouse_lga_key(v_hotel.city))
      and (
        coalesce(search.criteria->'amenities','[]'::jsonb)='[]'::jsonb
        or not exists(
          select 1 from jsonb_array_elements_text(search.criteria->'amenities') wanted
          where not exists(
            select 1 from unnest(coalesce(v_hotel.amenities,'{}'::text[])) available
            where lower(available)=lower(wanted.value)
          )
        )
      )
      and exists(
        select 1 from public.hotel_rooms room
        where room.hotel_id=v_hotel.hotel_id
          and (nullif(search.criteria->>'min_price','') is null or room.price_per_night>=(search.criteria->>'min_price')::numeric)
          and (nullif(search.criteria->>'max_price','') is null or room.price_per_night<=(search.criteria->>'max_price')::numeric)
      )
      and (
        nullif(search.criteria->>'radius_km','') is null
        or (
          v_hotel.gps_latitude is not null and v_hotel.gps_longitude is not null
          and nullif(search.criteria->>'latitude','') is not null
          and nullif(search.criteria->>'longitude','') is not null
          and 6371*acos(least(1,greatest(-1,
            cos(radians((search.criteria->>'latitude')::double precision))
            *cos(radians(v_hotel.gps_latitude::double precision))
            *cos(radians(v_hotel.gps_longitude::double precision)-radians((search.criteria->>'longitude')::double precision))
            +sin(radians((search.criteria->>'latitude')::double precision))
            *sin(radians(v_hotel.gps_latitude::double precision))
          )))<=(search.criteria->>'radius_km')::double precision
        )
      )
  ), inserted as (
    insert into public.notifications(
      recipient_id,type,title,message,related_id,source_type,source_id,
      destination_route,destination_params,event_key
    )
    select matching.user_id,'saved_search_match','A hotel matches your search',
      v_hotel.name,v_hotel.hotel_id::text,'hotel',v_hotel.hotel_id::text,
      'hotel_detail',jsonb_build_object('hotel_id',v_hotel.hotel_id),
      concat('saved-search:',matching.id,':hotel:',v_hotel.hotel_id)
    from matching
    on conflict(recipient_id,event_key) where event_key is not null do nothing
    returning recipient_id,event_key
  )
  update public.saved_searches search
  set last_notified_at=now(),updated_at=now()
  from inserted
  where search.user_id=inserted.recipient_id
    and inserted.event_key=concat('saved-search:',search.id,':hotel:',v_hotel.hotel_id);
end;
$$;


--
-- Name: notify_missed_private_call(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_missed_private_call() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'missed' and old.status is distinct from 'missed' then
    insert into public.notifications(
      recipient_id, type, title, message, related_id, read,
      source_type, source_id, destination_route, destination_params, event_key
    )
    select new.callee_id, 'missed_call',
      'Missed ' || new.call_type || ' call',
      'You missed a ' || new.call_type || ' call. Open the conversation to call back.',
      new.id::text, false, new.context_type, new.context_id,
      'messages', jsonb_build_object('contextType', new.context_type, 'contextId', new.context_id),
      'missed_call:' || new.id::text
    where not exists (
      select 1 from public.notifications n
      where n.recipient_id = new.callee_id and n.event_key = 'missed_call:' || new.id::text
    );
  end if;
  return new;
end;
$$;


--
-- Name: notify_property_operations_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_property_operations_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_stage text:=lower(coalesce(new.lifecycle_stage,''));
  v_title text;
  v_recipient text;
  v_role text;
begin
  if tg_op='INSERT'
     or (tg_op='UPDATE' and new.lifecycle_stage is not distinct from old.lifecycle_stage) then
    return new;
  end if;
  if v_stage not in ('access_review','inspection_ready','awaiting_review','listing_prepared') then
    return new;
  end if;
  v_title:=case v_stage
    when 'access_review' then 'Access evidence needs review'
    when 'inspection_ready' then 'Property needs a field assignment'
    when 'awaiting_review' then 'Field evidence needs review'
    else 'Listing is ready for publication review'
  end;

  if v_stage='listing_prepared' then
    select p.user_id into v_recipient from public.profiles p
    where p.role='admin' and not coalesce(p.deleted,false)
      and not coalesce(p.suspended,false) and not coalesce(p.banned,false)
      and lower(btrim(coalesce(p.assigned_state,'')))=lower(btrim(coalesce(new.property_state,'')))
      and lower(btrim(coalesce(p.assigned_lga,'')))=lower(btrim(coalesce(new.property_city,'')))
    order by p.user_id limit 1;
  else
    select c.assigned_staff_id into v_recipient
    from public.partner_support_conversations c
    where c.assigned_staff_id is not null and c.status not in ('resolved','closed')
      and (c.inspection_id=new.id or c.context_id=new.id::text)
    order by c.updated_at desc limit 1;
    if v_recipient is null then
      select p.user_id into v_recipient
      from public.profiles p join public.staff_permissions sp
        on sp.staff_id=p.user_id and sp.permission='operations' and sp.is_active
      where p.role='staff' and not coalesce(p.deleted,false)
        and not coalesce(p.suspended,false) and not coalesce(p.banned,false)
        and lower(btrim(coalesce(p.assigned_state,'')))=lower(btrim(coalesce(new.property_state,'')))
        and lower(btrim(coalesce(p.assigned_lga,'')))=lower(btrim(coalesce(new.property_city,'')))
      order by (
        select count(*) from public.partner_support_conversations c
        where c.assigned_staff_id=p.user_id and c.status not in ('resolved','closed')
      ),p.user_id limit 1;
    end if;
  end if;
  if v_recipient is null then
    select p.user_id into v_recipient from public.profiles p
    where p.role='creator' and not coalesce(p.deleted,false)
      and not coalesce(p.suspended,false) and not coalesce(p.banned,false)
    order by p.user_id limit 1;
  end if;
  if v_recipient is null then return new; end if;
  select role into v_role from public.profiles where user_id=v_recipient;
  insert into public.notifications(
    recipient_id,type,title,message,read,related_id,source_type,source_id,
    destination_route,destination_params,event_key,workspace_scope,created_at
  ) values(
    v_recipient,'property_'||v_stage,v_title,
    concat_ws(' · ',nullif(new.property_address,''),nullif(new.request_code,'')),false,
    new.id::text,'inspection_request',new.id::text,'operations_properties',
    jsonb_build_object('inspection_id',new.id,'request_code',new.request_code),
    'operations_property:'||new.id::text||':'||v_stage,
    case when v_role in ('staff','admin','creator') then v_role else 'personal' end,
    now()
  ) on conflict (recipient_id,event_key) where event_key is not null do nothing;
  return new;
end;
$$;


--
-- Name: notify_property_partner_reservation_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_property_partner_reservation_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_listing public.listings;
  v_partner_id text;
  v_stage text;
  v_title text;
  v_message text;
  v_short_let boolean:=coalesce(new.stay_type,'long_stay')='short_let';
begin
  select * into v_listing
  from public.listings
  where id::text=new.listing_id or listing_id=new.listing_id
  limit 1;
  if v_listing is null then return new; end if;
  v_partner_id:=coalesce(v_listing.partner_id,v_listing.owner_id);
  if v_partner_id is null then return new; end if;

  if v_short_let then
    if new.status='completed' and (tg_op='INSERT' or old.status is distinct from new.status) then
      v_stage:='checkout';
      v_title:='Guest checked out';
      v_message:=format('The guest left %s on %s. WeHouse is handling the final stay and deposit checks.',v_listing.title,to_char(new.stay_check_out,'DD Mon YYYY'));
    elsif new.status='occupied' and (tg_op='INSERT' or old.status is distinct from new.status) then
      v_stage:='checkin';
      v_title:='Guest checked in';
      v_message:=format('A guest entered %s on %s for the booked stay.',v_listing.title,to_char(new.stay_check_in,'DD Mon YYYY'));
    elsif new.rent_payment_status='paid' and new.rent_paid_at is not null
      and (tg_op='INSERT' or old.rent_payment_status is distinct from new.rent_payment_status or old.rent_paid_at is distinct from new.rent_paid_at) then
      v_stage:='reserved';
      v_title:='Short Let booked';
      v_message:=format('%s is booked from %s to %s. WeHouse is handling the guest arrival.',v_listing.title,to_char(new.stay_check_in,'DD Mon YYYY'),to_char(new.stay_check_out,'DD Mon YYYY'));
    else
      return new;
    end if;
  else
    if new.status='completed' and (tg_op='INSERT' or old.status is distinct from new.status) then
      v_stage:='completed';
      v_title:='Tenancy completed';
      v_message:=format('The tenancy at %s has ended.',v_listing.title);
    elsif new.status='occupied' and (tg_op='INSERT' or old.status is distinct from new.status) then
      v_stage:='occupied';
      v_title:='Tenant moved in';
      v_message:=format('WeHouse verified the handover for %s. The tenancy is now active.',v_listing.title);
    elsif new.status='ready_for_move_in'
      and new.rent_payment_status in ('paid','upfront_paid')
      and new.rent_paid_at is not null
      and new.requested_move_in_at is not null
      and (tg_op='INSERT' or old.requested_move_in_at is distinct from new.requested_move_in_at) then
      v_stage:='move_in_scheduled';
      v_title:='Move-in time selected';
      v_message:=format('The customer selected %s for %s. WeHouse will verify the code and hand over access at arrival.',to_char(new.requested_move_in_at,'DD Mon YYYY, HH12:MI AM'),v_listing.title);
    elsif new.rent_payment_status in ('paid','upfront_paid')
      and new.rent_paid_at is not null
      and (tg_op='INSERT' or old.rent_payment_status is distinct from new.rent_payment_status or old.rent_paid_at is distinct from new.rent_paid_at) then
      v_stage:='rent_confirmed';
      v_title:='Year 1 rent confirmed';
      v_message:=format('Rent is confirmed for %s. WeHouse is waiting for the customer to choose a move-in time; the tenancy has not started.',v_listing.title);
    else
      return new;
    end if;
  end if;

  insert into public.notifications(
    recipient_id,type,title,message,related_id,source_type,source_id,destination_route,
    destination_params,event_key,workspace_scope,read,created_at
  ) values (
    v_partner_id,'property_booking',v_title,v_message,v_listing.id::text,'property_booking',new.id,
    'property_detail',jsonb_build_object('listing_id',v_listing.id::text,'reservation_id',new.id),
    'property_partner_stay:'||new.id||':'||v_stage,'partner',false,now()
  ) on conflict (recipient_id,event_key) where event_key is not null do nothing;
  return new;
end;
$$;


--
-- Name: notify_reservation_operations_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_reservation_operations_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_listing public.listings;
  v_recipient text;
  v_type text;
  v_title text;
  v_message text;
  v_state_key text;
begin
  if tg_op = 'UPDATE'
     and old.status is not distinct from new.status
     and old.rent_payment_status is not distinct from new.rent_payment_status
     and old.rent_paid_at is not distinct from new.rent_paid_at then
    return new;
  end if;

  select * into v_listing
  from public.listings l
  where l.id::text = new.listing_id or l.listing_id = new.listing_id
  limit 1;
  if v_listing is null then return new; end if;

  if new.status = 'inspection_pending' then
    v_type := 'property_inspection_coordination_required';
    v_title := 'Inspection request needs coordination';
    v_message := format('%s · assign or continue the requested apartment visit.', v_listing.title);
    v_state_key := 'inspection_pending';
  elsif new.status = 'payment_conflict' then
    v_type := 'reservation_payment_conflict';
    v_title := 'Reservation payment needs review';
    v_message := format('%s · payment must be reviewed before this reservation can continue.', v_listing.title);
    v_state_key := 'payment_conflict';
  elsif new.status = 'ready_for_move_in'
    and new.rent_payment_status in ('paid', 'upfront_paid')
    and new.rent_paid_at is not null
    and new.requested_move_in_at is null then
    v_type := 'property_rent_confirmed';
    v_title := 'Year 1 rent confirmed';
    v_message := format('%s · waiting for the customer to choose a move-in time.', v_listing.title);
    v_state_key := 'rent_confirmed_waiting_customer';
  else
    -- Paid reservation fees, unpaid rent and completed transitions remain in
    -- the booking record. They are not operational actions by themselves.
    return new;
  end if;

  for v_recipient in
    select distinct p.user_id
    from public.profiles p
    where not coalesce(p.deleted, false)
      and not coalesce(p.suspended, false)
      and not coalesce(p.banned, false)
      and (
        (p.role = 'admin'
          and lower(btrim(coalesce(p.assigned_state, ''))) = lower(btrim(coalesce(v_listing.state, '')))
          and lower(btrim(coalesce(p.assigned_lga, ''))) = lower(btrim(coalesce(v_listing.city, ''))))
        or (p.role = 'staff'
          and lower(btrim(coalesce(p.assigned_state, ''))) = lower(btrim(coalesce(v_listing.state, '')))
          and lower(btrim(coalesce(p.assigned_lga, ''))) = lower(btrim(coalesce(v_listing.city, '')))
          and exists (
            select 1 from public.staff_permissions sp
            where sp.staff_id = p.user_id
              and sp.permission = 'operations'
              and sp.is_active
          ))
      )
  loop
    insert into public.notifications(
      recipient_id, type, title, message, read, related_id, source_type, source_id,
      destination_route, destination_params, event_key, created_at
    ) values (
      v_recipient, v_type, v_title, v_message, false, new.id::text,
      'reservation', new.id::text, 'operations_bookings',
      jsonb_build_object(
        'reservation_id', new.id,
        'listing_id', v_listing.id::text,
        'status', new.status,
        'workflow_state', v_state_key
      ),
      'operations_reservation:' || new.id::text || ':' || v_state_key,
      now()
    ) on conflict (recipient_id, event_key) where event_key is not null do nothing;
  end loop;
  return new;
end;
$$;


--
-- Name: notify_saved_hotel_searches_from_hotel(); Type: FUNCTION; Schema: public; Owner: -
