--
-- Name: notify_shared_housing_member_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_shared_housing_member_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  group_row public.shared_housing_groups;
  listing_title text;
  actor_name text;
begin
  select * into group_row from public.shared_housing_groups where id=new.group_id;
  select title into listing_title from public.listings where id=group_row.listing_id;
  select coalesce(full_name, username, 'Your roommate') into actor_name
    from public.profiles where user_id=coalesce(group_row.created_by,new.user_id);

  if tg_op='INSERT' and new.invitation_status='invited' then
    insert into public.notifications(
      recipient_id,type,title,message,related_id,read,source_type,source_id,
      destination_route,destination_params,event_key
    ) values (
      new.user_id,'shared_home_invite','Shared home invitation',
      actor_name||' invited you to share '||coalesce(listing_title,'a home')||'.',
      new.group_id::text,false,'shared_housing',new.group_id,'my_reservations',
      jsonb_build_object('sharedGroupId',new.group_id),
      'shared_home_invite:'||new.group_id::text||':'||new.user_id
    ) on conflict (recipient_id,event_key) where event_key is not null do nothing;
  elsif tg_op='UPDATE' and new.invitation_status is distinct from old.invitation_status
    and new.invitation_status in ('accepted','declined') then
    insert into public.notifications(
      recipient_id,type,title,message,related_id,read,source_type,source_id,
      destination_route,destination_params,event_key
    ) values (
      group_row.created_by,'shared_home_response',
      case when new.invitation_status='accepted' then 'Shared home accepted' else 'Shared home declined' end,
      case when new.invitation_status='accepted'
        then 'Your roommate accepted the invitation for '||coalesce(listing_title,'the selected home')||'.'
        else 'Your roommate declined the invitation for '||coalesce(listing_title,'the selected home')||'.' end,
      new.group_id::text,false,'shared_housing',new.group_id,'my_reservations',
      jsonb_build_object('sharedGroupId',new.group_id),
      'shared_home_response:'||new.group_id::text||':'||new.invitation_status
    ) on conflict (recipient_id,event_key) where event_key is not null do nothing;
  elsif tg_op='UPDATE' and new.payment_status='paid'
    and old.payment_status is distinct from 'paid' then
    insert into public.notifications(
      recipient_id,type,title,message,related_id,read,source_type,source_id,
      destination_route,destination_params,event_key
    )
    select member.user_id,'shared_home_payment','Roommate share updated',
      'A payment share for '||coalesce(listing_title,'your shared home')||' was confirmed.',
      new.group_id::text,false,'shared_housing',new.group_id,'my_reservations',
      jsonb_build_object('sharedGroupId',new.group_id),
      'shared_home_payment:'||new.group_id::text||':'||new.id::text
    from public.shared_housing_members member
    where member.group_id=new.group_id and member.user_id<>new.user_id
    on conflict (recipient_id,event_key) where event_key is not null do nothing;
  end if;
  return new;
end;
$$;


--
-- Name: notify_support_case_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_support_case_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_case public.partner_support_conversations;
  v_recipient text;
  v_sender_is_requester boolean;
  v_target_status text;
  v_title text;
  v_operational boolean;
begin
  select * into v_case from public.partner_support_conversations
  where id=new.conversation_id;
  if v_case.id is null then return new; end if;
  v_sender_is_requester:=new.sender_id=v_case.partner_id;
  v_operational:=v_case.channel_kind in ('property_operations','reservation_operations','field_operations');

  if new.visibility='internal' then
    v_recipient:=case
      when new.sender_id=v_case.assigned_field_officer_id then v_case.assigned_staff_id
      else v_case.assigned_field_officer_id
    end;
    v_title:='Internal work note';
  else
    v_target_status:=coalesce(new.action_metadata->>'to_status','');
    v_recipient:=case when v_sender_is_requester
      then coalesce(v_case.assigned_field_officer_id,v_case.assigned_staff_id)
      else v_case.partner_id end;
    v_title:=case
      when v_operational and v_sender_is_requester then 'New message on an active record'
      when v_operational then 'WeHouse updated your record conversation'
      when v_sender_is_requester and new.action_metadata->>'event_type'='resolution_accepted' then 'Requester confirmed this is solved'
      when v_sender_is_requester and new.action_metadata->>'event_type'='reopened' then 'Requester still needs help'
      when v_sender_is_requester then 'Help request reply needs attention'
      when new.action_type='status_change' and v_target_status='waiting_for_user' then 'WeHouse needs information from you'
      when new.action_type='status_change' and v_target_status='escalated' then 'Your help request was escalated'
      when new.action_type='status_change' and v_target_status='resolved' then 'WeHouse resolved your help request'
      else 'WeHouse replied to your help request'
    end;
  end if;

  if v_recipient is not null and v_recipient<>new.sender_id then
    insert into public.notifications(
      recipient_id,type,title,message,related_id,source_type,source_id,
      destination_route,destination_params,event_key
    ) values(
      v_recipient,
      case when new.visibility='internal' then 'internal_work_note' else 'support_case_message' end,
      v_title,coalesce(nullif(btrim(new.content),''),'New attachment'),v_case.id::text,
      case when new.visibility='internal' then 'internal_work_note' else 'wehouse_conversation' end,
      v_case.id::text,'conversation',
      jsonb_build_object('conversation_id',v_case.id,'context_type',v_case.context_type,'context_id',v_case.context_id),
      'support-message:'||new.id::text
    ) on conflict do nothing;
  end if;
  return new;
end;
$$;


--
-- Name: notify_worker_booking_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_worker_booking_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  conversation_id uuid;
  recipient text;
  event_type text;
  event_title text;
  event_message text;
  event_route text;
  event_scope text;
begin
  select id into conversation_id
  from public.booking_conversations
  where booking_id=new.id
  limit 1;

  if tg_op='INSERT' then
    recipient:=new.worker_id;
    event_type:='service_request_received';
    event_title:='New service request';
    event_message:='A customer requested '||coalesce(new.service_type,'your service')||'.';
    event_route:='worker_dashboard';
    event_scope:='worker';
  elsif new.status is distinct from old.status then
    if new.status='waiting_payment' then
      recipient:=new.user_id;
      event_type:='service_price_ready';
      event_title:='Price ready for approval';
      event_message:='The Worker entered an agreed price of ₦'||trim(to_char(new.negotiated_amount,'FM999,999,999,990'))||'.';
      event_route:='my_reservations';
      event_scope:='personal';
    elsif new.status='confirmed' then
      recipient:=new.worker_id;
      event_type:='service_payment_confirmed';
      event_title:='Service payment confirmed';
      event_message:='The customer secured payment for this job.';
      event_route:='worker_dashboard';
      event_scope:='worker';
    elsif new.status='in_progress' then
      recipient:=new.user_id;
      event_type:='service_work_started';
      event_title:='Work started';
      event_message:=coalesce(new.service_type,'Your service')||' is now in progress.';
      event_route:='my_reservations';
      event_scope:='personal';
    elsif new.status='completed_pending_approval' then
      recipient:=new.user_id;
      event_type:='service_completion_review_required';
      event_title:='Review completed work';
      event_message:='The Worker marked the job complete. Review it before releasing payment.';
      event_route:='my_reservations';
      event_scope:='personal';
    elsif new.status in ('approved_released','cancelled','refunded') then
      recipient:=new.user_id;
      event_type:='service_booking_updated';
      event_title:='Service booking updated';
      event_message:='Your '||coalesce(new.service_type,'service')||' booking is now '||replace(new.status,'_',' ')||'.';
      event_route:='my_reservations';
      event_scope:='personal';
    else
      return new;
    end if;
  else
    return new;
  end if;

  if recipient is null then return new; end if;

  insert into public.notifications(
    recipient_id,type,title,message,related_id,read,source_type,source_id,
    destination_route,destination_params,event_key,workspace_scope
  ) values (
    recipient,event_type,event_title,event_message,new.id::text,false,
    'worker_booking',new.id,event_route,
    jsonb_build_object('conversationId',conversation_id,'bookingId',new.id),
    'worker_booking:'||new.id::text||':'||new.status||':'||recipient,
    event_scope
  ) on conflict(recipient_id,event_key) where event_key is not null do nothing;
  return new;
end;
$$;


--
-- Name: open_contextual_case(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_contextual_case(p_reason_code text, p_subject_type text, p_subject_id text, p_summary text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user text:=public.current_profile_user_id();
  v_reason public.case_reason_registry;
  v_case public.operational_cases;
  v_state text;
begin
  if v_user is null then raise exception 'Authentication required'; end if;
  select * into v_reason from public.case_reason_registry
  where reason_code=p_reason_code and active;
  if v_reason.reason_code is null or not (p_subject_type=any(v_reason.allowed_subject_types))
    then raise exception 'Case reason does not apply to this subject'; end if;
  if not public.actor_can_open_case_for_subject(v_user,p_subject_type,p_subject_id)
    then raise exception 'Subject access required'; end if;

  select coalesce(l.state,h.state,p.state) into v_state
  from (select null::text state) z
  left join public.reservations r
    on p_subject_type in ('long_let','short_let') and r.id=p_subject_id
  left join public.listings l
    on l.listing_id=r.listing_id or l.id::text=r.listing_id
  left join public.hotel_bookings hb
    on p_subject_type='hotel' and hb.booking_id::text=p_subject_id
  left join public.hotels h on h.hotel_id=hb.hotel_id
  left join public.profiles p on p.user_id=v_user
  limit 1;

  insert into public.operational_cases(
    reason_code,owning_domain,subject_type,subject_id,requester_user_id,
    state_scope,status,priority,service_level_due_at
  ) values(
    v_reason.reason_code,v_reason.owning_domain,p_subject_type,p_subject_id,
    v_user,v_state,'open',
    case when v_reason.owning_domain='security_operations' then 'urgent' else 'normal' end,
    now()+case when v_reason.owning_domain='security_operations'
      then interval '1 hour' else interval '24 hours' end
  ) on conflict(
    reason_code,subject_type,subject_id,requester_user_id
  ) where status not in ('resolved','closed')
  do update set updated_at=now()
  returning * into v_case;

  insert into public.operational_case_events(
    operational_case_id,event_key,event_type,to_status,actor_user_id,public_note
  ) values(
    v_case.operational_case_id,'case_opened:'||v_case.operational_case_id,
    'case_opened','open',v_user,nullif(btrim(p_summary),'')
  ) on conflict(event_key) do nothing;
  return v_case.operational_case_id;
end
$$;


--
-- Name: open_contextual_case_conversation(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_contextual_case_conversation(p_reason_code text, p_subject_type text, p_subject_id text, p_summary text DEFAULT NULL::text, p_snapshot jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user text:=public.current_profile_user_id();
  v_profile public.profiles;
  v_case_id uuid;
  v_case public.operational_cases;
  v_reason public.case_reason_registry;
  v_conversation public.partner_support_conversations;
  v_thread public.canonical_threads;
  v_snapshot jsonb;
  v_title text;
begin
  if v_user is null then raise exception 'Authentication required'; end if;
  select * into v_profile from public.profiles where user_id=v_user;
  select * into v_reason from public.case_reason_registry
  where reason_code=p_reason_code and active;
  if v_reason.reason_code is null then raise exception 'Case reason is unavailable'; end if;

  v_case_id:=public.open_contextual_case(
    p_reason_code,p_subject_type,p_subject_id,p_summary
  );
  select * into v_case from public.operational_cases
  where operational_case_id=v_case_id;
  v_snapshot:=coalesce(p_snapshot,'{}'::jsonb)
    -'booking_code'-'check_in_code'-'access_code'-'verification_code'
    -'handover_code'-'recovery_code';
  v_snapshot:=v_snapshot||jsonb_build_object(
    'operational_case_id',v_case_id,'case_number',v_case.case_number,
    'reason_code',v_reason.reason_code,'reason_label',v_reason.label,
    'owning_domain',v_reason.owning_domain,'source_type',p_subject_type,
    'source_id',p_subject_id
  );
  v_title:=v_reason.label||coalesce(
    ' · '||nullif(btrim(coalesce(
      v_snapshot->>'listing_title',v_snapshot->>'hotel_name',
      v_snapshot->>'service_type',v_snapshot->>'property_name',''
    )),''),'');

  insert into public.canonical_threads(
    thread_type,thread_key,subject_type,subject_id,state,created_at,updated_at
  ) values(
    'case','operational_case:'||v_case_id,'operational_case',v_case_id::text,
    'open',now(),now()
  )
  on conflict(thread_type,thread_key) do update set
    state=case when canonical_threads.state='closed' then 'read_only'
      else canonical_threads.state end,
    updated_at=now()
  returning * into v_thread;
  insert into public.canonical_thread_participants(
    thread_id,user_id,participant_role,can_message,can_view_obligation
  ) values(v_thread.thread_id,v_user,'requester',true,true)
  on conflict(thread_id,user_id) do update set left_at=null,
    can_view_obligation=true;

  insert into public.partner_support_conversations(
    partner_id,requester_role,subject,status,category,context_type,context_id,
    context_snapshot,priority,channel_kind,case_number,
    operational_case_id,canonical_thread_id,created_at,updated_at
  ) values(
    v_user,v_profile.role,v_title,'open',v_reason.reason_code,
    'operational_case',p_subject_id,v_snapshot,v_case.priority,
    v_reason.owning_domain,'WHC-'||lpad(v_case.case_number::text,10,'0'),
    v_case_id,v_thread.thread_id,now(),now()
  ) on conflict(operational_case_id) where operational_case_id is not null
  do update set context_snapshot=excluded.context_snapshot,updated_at=now()
  returning * into v_conversation;

  insert into public.partner_support_messages(
    conversation_id,sender_id,sender_role,content,attachments,
    attachment_types,action_type,action_metadata,is_read,visibility,created_at
  ) select
    v_conversation.id,v_user,'system',
    'Request created and routed to '||replace(v_reason.owning_domain,'_',' ')||'.',
    array[]::text[],array[]::text[],'request_received',
    jsonb_build_object('operational_case_id',v_case_id,
      'reason_code',v_reason.reason_code,'owning_domain',v_reason.owning_domain),
    false,'customer',now()
  where not exists(
    select 1 from public.partner_support_messages m
    where m.conversation_id=v_conversation.id and m.sender_role='system'
      and m.action_type='request_received'
      and m.action_metadata->>'operational_case_id'=v_case_id::text
  );

  insert into public.canonical_thread_items(
    thread_id,item_type,sender_user_id,body,payload,event_key
  ) values(
    v_thread.thread_id,'case_action',v_user,nullif(btrim(p_summary),''),
    jsonb_build_object(
      'action','opened','case_id',v_case_id,'case_number',v_case.case_number,
      'reason_code',v_reason.reason_code,'owning_domain',v_reason.owning_domain
    ),'case_action:opened:'||v_case_id
  ) on conflict(event_key) do nothing;

  insert into public.activity_events(
    event_key,event_type,subject_type,subject_id,actor_user_id,
    title,summary,route,route_params,occurred_at
  ) values(
    'case_opened:'||v_case_id,'case_opened','operational_case',v_case_id::text,
    v_user,v_reason.label,'WeHouse received your request.','inbox',
    jsonb_build_object('thread_id',v_thread.thread_id,
      'conversation_id',v_conversation.id),now()
  ) on conflict(event_key) do nothing;
  insert into public.activity_event_audiences(
    activity_event_id,recipient_user_id,workspace,domain,state_scope
  ) select e.activity_event_id,v_user,'personal',v_reason.owning_domain,v_case.state_scope
  from public.activity_events e where e.event_key='case_opened:'||v_case_id
  on conflict do nothing;

  return jsonb_build_object(
    'operational_case_id',v_case_id,'conversation_id',v_conversation.id,
    'canonical_thread_id',v_thread.thread_id,'case_number',v_conversation.case_number,
    'owning_domain',v_reason.owning_domain
  );
end
$$;


--
-- Name: open_my_hotel_booking_conversation(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_my_hotel_booking_conversation(p_booking_id integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_booking public.hotel_bookings;
  v_conversation_id uuid;
begin
  if v_actor is null then raise exception 'Active Personal account required'; end if;
  select * into v_booking from public.hotel_bookings
  where booking_id=p_booking_id for share;
  if v_booking.booking_id is null then raise exception 'Hotel booking not found'; end if;
  if v_booking.user_id<>v_actor
     and not public.hotel_actor_has_capability(v_booking.hotel_id,'stay.message') then
    raise exception 'Hotel booking conversation access denied';
  end if;
  if v_booking.payment_status<>'paid'
     or v_booking.status not in ('confirmed','checked_in') then
    raise exception 'Hotel chat is available from confirmation until checkout';
  end if;
  insert into public.hotel_booking_conversations(booking_id,hotel_id,guest_user_id)
  values(v_booking.booking_id,v_booking.hotel_id,v_booking.user_id)
  on conflict(booking_id) do update
  set updated_at=public.hotel_booking_conversations.updated_at
  returning id into v_conversation_id;
  return v_conversation_id;
end;
$$;


--
-- Name: open_my_reservation_conversation(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_my_reservation_conversation(p_context_type text, p_context_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conversation public.partner_support_conversations;
  v_thread public.canonical_threads;
  v_snapshot jsonb;
  v_title text;
  v_context text;
  v_thread_type text;
  v_prior_subject_type text;
  v_prior_subject_id text;
  v_state text;
begin
  v_context:=case
    when p_context_type in('apartment_reservation','reservation','apartment_payment')
      then 'apartment_reservation'
    when p_context_type='hotel_booking' then 'hotel_booking'
    else null end;
  if v_context is null or nullif(btrim(coalesce(p_context_id,'')),'') is null then
    raise exception 'Reservation context is invalid'; end if;
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null then raise exception 'Active Personal account required'; end if;

  if v_context='apartment_reservation' then
    select
      (to_jsonb(r)-'booking_code'-'handover_code'-'access_code')
        ||jsonb_build_object(
          'reservation_id',r.id,'listing_title',coalesce(l.title,'Property'),
          'listing_city',l.city,'listing_state',l.state,
          'source_type',case when r.stay_type='short_let' then 'short_let' else 'long_let' end,
          'source_id',r.id,'owning_domain','property_operations'
        ),coalesce(l.title,case when r.stay_type='short_let'
          then 'Short Let' else 'Long Let' end),
      case when r.stay_type='short_let' then 'short_let' else 'long_let' end,
      'listing',r.listing_id,l.state
    into v_snapshot,v_title,v_thread_type,v_prior_subject_type,
      v_prior_subject_id,v_state
    from public.reservations r left join public.listings l
      on l.listing_id=r.listing_id or l.id::text=r.listing_id
    where r.id=p_context_id and r.user_id=v_actor.user_id limit 1;
  else
    select
      (to_jsonb(b)-'booking_code'-'check_in_code'-'access_code')
        ||jsonb_build_object(
          'hotel_name',h.name,'source_type','hotel','source_id',b.booking_id,
          'owning_domain','property_operations'
        ),coalesce(h.name,'Hotel stay'),'hotel','hotel_property',
      h.hotel_id::text,h.state
    into v_snapshot,v_title,v_thread_type,v_prior_subject_type,
      v_prior_subject_id,v_state
    from public.hotel_bookings b join public.hotels h on h.hotel_id=b.hotel_id
    where b.booking_id::text=p_context_id and b.user_id=v_actor.user_id limit 1;
  end if;
  if v_snapshot is null then raise exception 'Reservation was not found'; end if;

  select c.* into v_conversation
  from public.partner_support_conversations c
  where c.partner_id=v_actor.user_id and c.context_id=p_context_id
    and c.context_type=v_context
  order by c.created_at limit 1;
  if v_conversation.id is null then
    select c.* into v_conversation
    from public.partner_support_conversations c
    join public.canonical_threads t on t.thread_id=c.canonical_thread_id
    where c.partner_id=v_actor.user_id and t.thread_type='property_inquiry'
      and t.subject_type=v_prior_subject_type and t.subject_id=v_prior_subject_id
    order by c.created_at limit 1;
  end if;

  if v_conversation.id is not null and v_conversation.canonical_thread_id is not null then
    update public.canonical_threads set
      thread_type=v_thread_type,
      thread_key=v_thread_type||':'||p_context_id||':requester:'||v_actor.user_id,
      subject_type=v_thread_type,subject_id=p_context_id,state='open',updated_at=now()
    where thread_id=v_conversation.canonical_thread_id returning * into v_thread;
  else
    insert into public.canonical_threads(
      thread_type,thread_key,subject_type,subject_id,state,created_at,updated_at
    ) values(
      v_thread_type,v_thread_type||':'||p_context_id||':requester:'||v_actor.user_id,
      v_thread_type,p_context_id,'open',now(),now()
    ) on conflict(thread_type,thread_key) do update set state='open',updated_at=now()
    returning * into v_thread;
  end if;
  insert into public.canonical_thread_participants(
    thread_id,user_id,participant_role,can_message,can_view_obligation
  ) values(v_thread.thread_id,v_actor.user_id,'requester',true,true)
  on conflict(thread_id,user_id) do update set left_at=null,can_message=true,
    can_view_obligation=true;

  if v_conversation.id is null then
    insert into public.partner_support_conversations(
      partner_id,requester_role,subject,status,category,context_type,context_id,
      context_snapshot,priority,channel_kind,canonical_thread_id,
      created_at,updated_at
    ) values(
      v_actor.user_id,v_actor.role,v_title,'open','property_operations',
      v_context,p_context_id,v_snapshot,'normal','property_operations',
      v_thread.thread_id,now(),now()
    ) returning * into v_conversation;
  else
    update public.partner_support_conversations set
      subject=v_title,status=case when status='closed' then 'open' else status end,
      category='property_operations',context_type=v_context,context_id=p_context_id,
      context_snapshot=v_snapshot,channel_kind='property_operations',
      canonical_thread_id=v_thread.thread_id,updated_at=now()
    where id=v_conversation.id returning * into v_conversation;
  end if;

  insert into public.partner_support_messages(
    conversation_id,sender_id,sender_role,content,attachments,
    attachment_types,action_type,action_metadata,is_read,visibility,created_at
  ) select
    v_conversation.id,v_actor.user_id,'system',
    'Booking conversation linked to this record.',array[]::text[],
    array[]::text[],'request_received',jsonb_build_object(
      'thread_type',v_thread_type,'owning_domain','property_operations'
    ),false,'customer',now()
  where not exists(select 1 from public.partner_support_messages m
    where m.conversation_id=v_conversation.id);
  return v_conversation.id;
end
$$;


--
-- Name: open_property_operations_conversation(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_property_operations_conversation(p_subject_type text, p_subject_id text, p_snapshot jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_thread public.canonical_threads;
  v_conversation public.partner_support_conversations;
  v_snapshot jsonb;
  v_title text;
  v_state text;
  v_allowed boolean:=false;
begin
  if p_subject_type not in('listing','hotel_property')
    or nullif(btrim(coalesce(p_subject_id,'')),'') is null then
    raise exception 'Property conversation subject is invalid'; end if;
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null then raise exception 'Active Personal account required'; end if;

  if p_subject_type='listing' then
    select coalesce(l.title,'Property'),l.state,
      (l.deleted_at is null and (
        (l.status='available' and l.approved_at is not null)
        or v_actor.user_id in(l.owner_id,l.partner_id)
      ))
    into v_title,v_state,v_allowed
    from public.listings l
    where l.id::text=p_subject_id or l.listing_id=p_subject_id limit 1;
  else
    select coalesce(h.name,'Hotel'),h.state,
      (h.status='active' and h.approved_at is not null)
      or h.owner_id=v_actor.user_id
      or public.hotel_actor_has_capability(h.hotel_id,'stay.read')
    into v_title,v_state,v_allowed
    from public.hotels h where h.hotel_id::text=p_subject_id limit 1;
  end if;
  if not coalesce(v_allowed,false) then
    raise exception 'This property is not available to this account'; end if;

  v_snapshot:=coalesce(p_snapshot,'{}'::jsonb)
    -'booking_code'-'check_in_code'-'access_code'-'verification_code'
    -'handover_code'-'recovery_code';
  v_snapshot:=v_snapshot||jsonb_build_object(
    'source_type',p_subject_type,'source_id',p_subject_id,
    'owning_domain','property_operations','state_scope',v_state
  );

  insert into public.canonical_threads(
    thread_type,thread_key,subject_type,subject_id,state,created_at,updated_at
  ) values(
    'property_inquiry',p_subject_type||':'||p_subject_id||':requester:'||v_actor.user_id,
    p_subject_type,p_subject_id,'open',now(),now()
  ) on conflict(thread_type,thread_key) do update set
    state=case when canonical_threads.state='closed' then 'open'
      else canonical_threads.state end,updated_at=now()
  returning * into v_thread;
  insert into public.canonical_thread_participants(
    thread_id,user_id,participant_role,can_message,can_view_obligation
  ) values(v_thread.thread_id,v_actor.user_id,'requester',true,true)
  on conflict(thread_id,user_id) do update set
    left_at=null,can_message=true,can_view_obligation=true;

  insert into public.partner_support_conversations(
    partner_id,requester_role,subject,status,category,context_type,context_id,
    context_snapshot,priority,channel_kind,canonical_thread_id,
    created_at,updated_at
  ) values(
    v_actor.user_id,v_actor.role,v_title,'open','property_inquiry',
    case when p_subject_type='listing' then 'property_listing'
      else 'hotel_operations' end,
    p_subject_id,v_snapshot,'normal','property_operations',
    v_thread.thread_id,now(),now()
  ) on conflict(canonical_thread_id) where canonical_thread_id is not null
  do update set subject=excluded.subject,context_snapshot=excluded.context_snapshot,
    status=case when partner_support_conversations.status='closed'
      then 'open' else partner_support_conversations.status end,updated_at=now()
  returning * into v_conversation;

  insert into public.partner_support_messages(
    conversation_id,sender_id,sender_role,content,attachments,
    attachment_types,action_type,action_metadata,is_read,visibility,created_at
  ) select
    v_conversation.id,v_actor.user_id,'system',
    'Property conversation linked to this record.',array[]::text[],
    array[]::text[],'request_received',jsonb_build_object(
      'thread_type','property_inquiry','owning_domain','property_operations'
    ),false,'customer',now()
  where not exists(select 1 from public.partner_support_messages m
    where m.conversation_id=v_conversation.id);
  return jsonb_build_object(
    'conversation_id',v_conversation.id,'canonical_thread_id',v_thread.thread_id,
    'owning_domain','property_operations','case_started',false
  );
end
$$;


--
-- Name: shared_payment_groups; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.shared_payment_groups (
    shared_payment_group_id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_type text NOT NULL,
    listing_id text NOT NULL,
    reservation_id text,
    created_by text NOT NULL,
    total_amount numeric(12,2) NOT NULL,
    capacity integer NOT NULL,
    status text DEFAULT 'inviting'::text NOT NULL,
    checkout_expires_at timestamp with time zone,
    policy_version_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    legacy_group_id uuid,
    conversation_id uuid,
    payment_phase text,
    stay_check_in date,
    stay_check_out date,
    guest_count integer,
    checkout_attempt integer DEFAULT 1 NOT NULL,
    CONSTRAINT shared_payment_groups_capacity_check CHECK ((capacity >= 2)),
    CONSTRAINT shared_payment_groups_product_type_check CHECK ((product_type = ANY (ARRAY['long_let'::text, 'short_let'::text]))),
    CONSTRAINT shared_payment_groups_product_type_check1 CHECK ((product_type <> 'hotel'::text)),
    CONSTRAINT shared_payment_groups_status_check CHECK ((status = ANY (ARRAY['inviting'::text, 'ready'::text, 'checkout_open'::text, 'fully_paid'::text, 'expired'::text, 'cancelled'::text, 'refunding'::text, 'refunded'::text]))),
    CONSTRAINT shared_payment_groups_total_amount_check CHECK ((total_amount > (0)::numeric))
);


--
-- Name: open_shared_payment_checkout(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_shared_payment_checkout(p_group_id uuid, p_event_key text) RETURNS public.shared_payment_groups
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_group public.shared_payment_groups; v_member_count integer;
  v_accepted_count integer; v_share_total numeric;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  perform p_event_key;
  select * into v_group from public.shared_payment_groups
  where shared_payment_group_id=p_group_id for update;
  if v_group.shared_payment_group_id is null then raise exception 'Shared payment not found'; end if;
  if v_group.product_type not in('long_let','short_let') then
    raise exception 'Hotel shared payment is not allowed'; end if;
  select count(*),count(*) filter(where invitation_state='accepted'),
    coalesce(sum(share_amount) filter(where invitation_state='accepted'),0)
  into v_member_count,v_accepted_count,v_share_total
  from public.shared_payment_members where shared_payment_group_id=p_group_id;
  if v_member_count>v_group.capacity or v_accepted_count>v_group.capacity then
    raise exception 'Property capacity exceeded'; end if;
  if v_accepted_count<2 or v_share_total<>v_group.total_amount then
    raise exception 'Accepted share amounts must equal the checkout total'; end if;
  update public.shared_payment_groups set status='checkout_open',
    checkout_expires_at=now()+interval '30 minutes',updated_at=now()
  where shared_payment_group_id=p_group_id returning * into v_group;
  update public.shared_housing_groups set status='payment_pending',
    expires_at=v_group.checkout_expires_at,updated_at=now()
  where canonical_group_id=p_group_id;
  return v_group;
end
$$;


--
-- Name: owner_invite_hotel_team_member(integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owner_invite_hotel_team_member(p_hotel_id integer, p_identifier text, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_member public.profiles;
  v_membership public.hotel_team_members;
  v_identifier text;
  v_role text:=case when p_role='staff' then 'front_desk' else p_role end;
  v_owner text;
  v_actor_caps text[]:=array[]::text[];
  v_default_caps text[];
begin
  select * into v_actor from public.profiles
  where user_id=public.current_profile_user_id()
  limit 1;
  if v_actor.user_id is null then raise exception 'Active Personal account required'; end if;
  select owner_id into v_owner from public.hotels where hotel_id=p_hotel_id;
  if v_owner is null then raise exception 'Hotel not found'; end if;
  if v_owner<>v_actor.user_id then
    v_actor_caps:=public.current_actor_hotel_capabilities(p_hotel_id);
    if not coalesce('hotel.team.manage'=any(v_actor_caps),false) then
      raise exception 'Hotel team management access required';
    end if;
  end if;
  if v_role not in ('manager','front_desk') then
    raise exception 'Choose Manager or Front Desk';
  end if;
  v_default_caps:=public.hotel_default_capabilities(v_role);
  if v_owner<>v_actor.user_id and not(v_default_caps<@v_actor_caps) then
    raise exception 'You cannot grant permissions outside your own hotel access';
  end if;
  v_identifier:=btrim(regexp_replace(coalesce(p_identifier,''),'^@','','g'));
  if v_identifier='' then raise exception 'Enter a WeHouse username or user ID'; end if;
  select * into v_member from public.profiles
  where (lower(username)=lower(v_identifier) or user_id=v_identifier)
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false)
  order by case when user_id=v_identifier then 0 else 1 end
  limit 1;
  if v_member.user_id is null then
    raise exception 'No active Personal WeHouse account matches that username or user ID';
  end if;
  if v_member.user_id=v_actor.user_id then
    raise exception 'You cannot invite or change your own hotel access';
  end if;
  if exists(select 1 from public.hotel_team_members
    where hotel_id=p_hotel_id and member_user_id=v_member.user_id and status='active') then
    raise exception 'This person already has hotel access';
  end if;
  insert into public.hotel_team_members(
    hotel_id,member_user_id,hotel_role,status,invited_by,capabilities,
    updated_at,revoked_at,responded_at
  ) values(
    p_hotel_id,v_member.user_id,v_role,'invited',v_actor.user_id,v_default_caps,
    now(),null,null
  ) on conflict(hotel_id,member_user_id) do update set
    hotel_role=excluded.hotel_role,status='invited',invited_by=excluded.invited_by,
    capabilities=excluded.capabilities,updated_at=now(),revoked_at=null,responded_at=null
  returning * into v_membership;
  insert into public.notifications(
    recipient_id,type,title,message,related_id,source_type,source_id,
    destination_route,destination_params,event_key,workspace_scope
  ) select
    v_member.user_id,'hotel_team_invitation','Hotel team invitation',
    'You were invited to join '||hotel.name||' as '
      ||case when v_role='manager' then 'Manager' else 'Front Desk' end||'.',
    v_membership.id::text,'hotel_team_invitation',v_membership.id::text,
    'notifications',jsonb_build_object('membership_id',v_membership.id,'hotel_id',p_hotel_id),
    'hotel-team-invite:'||v_membership.id::text||':'
      ||extract(epoch from v_membership.updated_at)::bigint,'personal'
  from public.hotels hotel where hotel.hotel_id=p_hotel_id;
  return jsonb_build_object(
    'id',v_membership.id,'name',coalesce(v_member.full_name,v_member.username,'WeHouse member'),
    'username',v_member.username,'user_id',v_member.user_id,
    'hotel_role',v_membership.hotel_role,'status',v_membership.status,
    'capabilities',to_jsonb(v_membership.capabilities)
  );
end;
$$;


--
-- Name: owner_request_hotel_pms_connection(integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owner_request_hotel_pms_connection(p_hotel_id integer, p_provider text, p_connection_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_provider text:=lower(btrim(coalesce(p_provider,'')));
  v_row public.hotel_integrations;
begin
  if v_actor is null or not exists(
    select 1 from public.hotels
    where hotel_id=p_hotel_id and owner_id=v_actor
  ) then raise exception 'Hotel owner access required'; end if;
  if nullif(btrim(coalesce(p_connection_name,'')),'') is null then
    raise exception 'Connection name is required';
  end if;
  if not exists(
    select 1 from public.hotel_pms_providers
    where provider_key=v_provider
      and certification_status in ('candidate','sandbox','certified')
  ) then raise exception 'That named PMS adapter is not available for certification'; end if;
  if exists(
    select 1 from public.hotel_integrations
    where hotel_id=p_hotel_id and provider=v_provider
      and status not in ('revoked')
  ) then raise exception 'This hotel already has an open request for that PMS'; end if;
  insert into public.hotel_integrations(
    hotel_id,provider,connection_name,status,created_by,
    hotel_authorized_by,hotel_authorized_at
  ) values(
    p_hotel_id,v_provider,btrim(p_connection_name),'requested',v_actor,v_actor,now()
  ) returning * into v_row;
  insert into public.audit_logs(action,target_type,target_id,details,admin_id)
  values(
    'HOTEL_PMS_CONNECTION_REQUESTED','hotel_integration',v_row.integration_id::text,
    jsonb_build_object('hotel_id',p_hotel_id,'provider',v_provider)::text,v_actor
  );
  return jsonb_build_object(
    'integration_id',v_row.integration_id,'hotel_id',v_row.hotel_id,
    'provider',v_row.provider,'connection_name',v_row.connection_name,
    'status',v_row.status
  );
end;
$$;


--
-- Name: owner_revoke_hotel_team_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owner_revoke_hotel_team_member(p_membership_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_row public.hotel_team_members;
  v_owner text;
  v_actor_caps text[]:=array[]::text[];
begin
  if v_actor is null then raise exception 'Active Personal account required'; end if;
  select member.* into v_row
  from public.hotel_team_members member
  where member.id=p_membership_id
  for update of member;
  if v_row.id is null then raise exception 'Hotel membership not found'; end if;
  select owner_id into v_owner from public.hotels where hotel_id=v_row.hotel_id;
  if v_owner<>v_actor then
    v_actor_caps:=public.current_actor_hotel_capabilities(v_row.hotel_id);
    if not coalesce('hotel.team.manage'=any(v_actor_caps),false) then
      raise exception 'Hotel team management access required';
    end if;
    if v_row.member_user_id=v_actor then
      raise exception 'Delegated managers cannot revoke their own access';
    end if;
    if not(v_row.capabilities<@v_actor_caps) then
      raise exception 'You cannot revoke a membership above your own hotel access';
    end if;
  end if;
  update public.hotel_team_members
  set status='revoked',revoked_at=now(),updated_at=now()
  where id=v_row.id;
  return true;
end;
$$;


--
-- Name: owner_set_hotel_team_capabilities(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owner_set_hotel_team_capabilities(p_membership_id uuid, p_capabilities text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_row public.hotel_team_members;
  v_owner text;
  v_actor_caps text[]:=array[]::text[];
  v_caps text[];
begin
  if v_actor is null then raise exception 'Active Personal account required'; end if;
  select member.* into v_row
  from public.hotel_team_members member
  where member.id=p_membership_id
  for update of member;
  if v_row.id is null then raise exception 'Hotel membership not found'; end if;
  select owner_id into v_owner from public.hotels where hotel_id=v_row.hotel_id;
  select coalesce(array_agg(distinct cap order by cap),array[]::text[])
    into v_caps from unnest(coalesce(p_capabilities,array[]::text[])) cap;
  if not public.hotel_capabilities_valid(v_caps) then
    raise exception 'Unsupported hotel capability';
  end if;
  if v_owner<>v_actor then
    v_actor_caps:=public.current_actor_hotel_capabilities(v_row.hotel_id);
    if not coalesce('hotel.team.manage'=any(v_actor_caps),false) then
      raise exception 'Hotel team management access required';
    end if;
    if v_row.member_user_id=v_actor then
      raise exception 'Delegated managers cannot change their own permissions';
    end if;
    if not(v_row.capabilities<@v_actor_caps) or not(v_caps<@v_actor_caps) then
      raise exception 'You cannot manage permissions outside your own hotel access';
    end if;
  end if;
  update public.hotel_team_members
  set capabilities=v_caps,updated_at=now()
  where id=v_row.id returning * into v_row;
  insert into public.audit_logs(action,target_type,target_id,details,admin_id)
  values('HOTEL_TEAM_CAPABILITIES_UPDATED','hotel_team_member',v_row.id::text,
    jsonb_build_object('hotel_id',v_row.hotel_id,'member_user_id',v_row.member_user_id,
      'capabilities',v_caps)::text,v_actor);
  return jsonb_build_object(
    'id',v_row.id,'hotel_id',v_row.hotel_id,'member_user_id',v_row.member_user_id,
    'hotel_role',v_row.hotel_role,'status',v_row.status,
    'capabilities',to_jsonb(v_row.capabilities)
  );
end;
$$;


--
-- Name: owner_set_hotel_team_member(integer, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owner_set_hotel_team_member(p_hotel_id integer, p_email text, p_role text, p_enabled boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_owner text:=public.current_profile_user_id();
  v_member public.profiles;
  v_role text:=case when p_role='staff' then 'front_desk' else p_role end;
begin
  if not exists(
    select 1 from public.hotels
    where hotel_id=p_hotel_id and owner_id=v_owner
  ) then raise exception 'Hotel owner access required'; end if;
  if v_role not in ('manager','front_desk') then
    raise exception 'Choose Manager or Front Desk'; end if;
  select * into v_member from public.profiles
  where lower(email)=lower(btrim(p_email))
    and not coalesce(deleted,false) limit 1;
  if v_member.user_id is null then raise exception 'WeHouse account not found'; end if;
  if v_member.user_id=v_owner then raise exception 'Owner already has full hotel access'; end if;

  if p_enabled then
    insert into public.hotel_team_members(
      hotel_id,member_user_id,hotel_role,status,invited_by,capabilities,
      created_at,updated_at
    ) values(
      p_hotel_id,v_member.user_id,v_role,'active',v_owner,
      public.hotel_default_capabilities(v_role),now(),now()
    ) on conflict(hotel_id,member_user_id) do update
      set hotel_role=excluded.hotel_role,status='active',revoked_at=null,
        capabilities=public.hotel_default_capabilities(excluded.hotel_role),
        updated_at=now();
  else
    update public.hotel_team_members
    set status='revoked',revoked_at=now(),updated_at=now()
    where hotel_id=p_hotel_id and member_user_id=v_member.user_id;
  end if;
  return true;
end
$$;


--
-- Name: partner_complete_hotel_stay(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_complete_hotel_stay(p_booking_id integer) RETURNS public.hotel_bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.hotel_bookings; actor text;
begin
  select * into b from public.hotel_bookings where booking_id=p_booking_id;
  if b.booking_id is null then raise exception 'Hotel booking not found'; end if;
  if not public.current_actor_has_hotel_capability(b.hotel_id,'stay.complete') then raise exception 'Stay completion access required'; end if;
  select user_id into actor from public.profiles where auth_id=(select auth.uid())::text;
  return public.complete_hotel_stay_internal(p_booking_id,'hotel_manual',actor);
end;
$$;


