--
-- Name: partner_create_hotel_room(integer, text, text, integer, integer, text, integer, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_create_hotel_room(p_hotel_id integer, p_room_type text, p_description text, p_price_per_night integer, p_max_guests integer, p_bed_type text, p_total_rooms integer, p_amenities text[] DEFAULT '{}'::text[], p_images text[] DEFAULT '{}'::text[]) RETURNS public.hotel_rooms
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_room public.hotel_rooms; v_actor text:=public.current_profile_user_id();
begin
  if not public.hotel_actor_has_capability(p_hotel_id,'hotel.inventory.manage')
     or not public.hotel_actor_has_capability(p_hotel_id,'hotel.rate.manage') then
    raise exception 'Hotel inventory and rate capabilities are required';
  end if;
  if not exists(select 1 from public.hotels where hotel_id=p_hotel_id and status='draft') then
    raise exception 'A live hotel needs WeHouse review before a room type is added';
  end if;
  if nullif(btrim(p_room_type),'') is null or coalesce(p_price_per_night,0)<=0
     or coalesce(p_max_guests,0)<1 or coalesce(p_total_rooms,0)<1 then
    raise exception 'Valid room name, rate, capacity and inventory are required';
  end if;
  insert into public.hotel_rooms(
    hotel_id,room_type,description,price_per_night,max_guests,bed_type,
    total_rooms,amenities,images,source_system
  ) values(
    p_hotel_id,btrim(p_room_type),nullif(btrim(coalesce(p_description,'')),''),
    p_price_per_night,p_max_guests,nullif(btrim(coalesce(p_bed_type,'')),''),
    p_total_rooms,coalesce(p_amenities,array[]::text[]),
    coalesce(p_images,array[]::text[]),'wehouse'
  ) returning * into v_room;
  insert into public.hotel_rate_plans(
    hotel_id,room_id,name,description,meal_plan,payment_timing,refundable,
    price_per_night,included_features
  ) values(
    p_hotel_id,v_room.room_id,'Room only','Room without a meal package',
    'room_only','pay_now',false,p_price_per_night,array[]::text[]
  );
  insert into public.hotel_commercial_change_audit(
    hotel_id,actor_user_id,action,target_type,target_id,after_values
  ) values(
    p_hotel_id,v_actor,'draft_room_created','hotel_room',v_room.room_id::text,
    jsonb_build_object('price_per_night',p_price_per_night,'total_rooms',p_total_rooms)
  );
  return v_room;
end;
$$;


--
-- Name: partner_raise_caution_claim(text, numeric, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_raise_caution_claim(p_reservation_id text, p_claimed_amount numeric, p_reason text, p_evidence_paths text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_res public.reservations;
  v_listing public.listings;
  v_id uuid;
  v_path text;
  v_deposit numeric(12,2);
begin
  select * into v_res from public.reservations
  where id=p_reservation_id and stay_type='short_let'
    and canonical_state in('checked_out','completed') for update;
  if v_res.id is null then raise exception 'Completed Short Let required'; end if;
  select * into v_listing from public.listings
  where listing_id=v_res.listing_id or id::text=v_res.listing_id;
  if v_actor is null or v_actor not in(v_listing.owner_id,v_listing.partner_id) then
    raise exception 'Property Partner access required'; end if;
  if v_res.completed_at is null or now()>v_res.completed_at+interval '24 hours' then
    raise exception 'Caution claim window closed'; end if;
  if nullif(btrim(coalesce(p_reason,'')),'') is null then
    raise exception 'Explain the claimed damage'; end if;
  if coalesce(cardinality(p_evidence_paths),0)=0 then
    raise exception 'Damage evidence is required'; end if;

  if v_res.shared_payment_group_id is not null then
    select round(coalesce(sum(component.amount),0),2) into v_deposit
    from public.shared_payment_protection_components component
    where component.shared_payment_group_id=v_res.shared_payment_group_id
      and component.component_type='short_let_caution';
  else
    v_deposit:=round(coalesce(v_res.security_deposit_snapshot,0),2);
  end if;
  if v_deposit<=0 then raise exception 'This Short Let has no Caution fee'; end if;
  if coalesce(p_claimed_amount,0)<=0 or p_claimed_amount>v_deposit then
    raise exception 'Claim must be within the Caution fee'; end if;

  insert into public.caution_claims(
    reservation_id,payment_protection_id,shared_payment_group_id,
    deposit_amount,claimed_amount,disputed_amount,undisputed_refund_amount,
    reason,guest_response_due_at
  ) values(
    v_res.id,case when v_res.shared_payment_group_id is null
      then v_res.caution_payment_protection_id else null end,
    v_res.shared_payment_group_id,v_deposit,p_claimed_amount,p_claimed_amount,
    v_deposit-p_claimed_amount,btrim(p_reason),now()+interval '48 hours'
  ) returning caution_claim_id into v_id;
  foreach v_path in array p_evidence_paths loop
    insert into public.caution_evidence(
      reservation_id,caution_claim_id,submitted_by,evidence_type,object_path
    ) values(v_res.id,v_id,v_actor,'partner_damage_claim',v_path);
  end loop;
  if v_deposit-p_claimed_amount>0 then
    if v_res.shared_payment_group_id is not null then
      perform public.enqueue_shared_caution_distribution(
        v_res.shared_payment_group_id,'refund_caution_undisputed','caution_claim',
        v_id::text,v_deposit-p_claimed_amount,'caution-undisputed-refund:'||v_id,now()
      );
    else
      insert into public.financial_action_outbox(
        action_type,subject_type,subject_id,payment_protection_id,amount,
        idempotency_key,metadata
      ) values(
        'refund_caution_undisputed','caution_claim',v_id::text,
        v_res.caution_payment_protection_id,v_deposit-p_claimed_amount,
        'caution-undisputed-refund:'||v_id,
        jsonb_build_object('refund_destination','original_payment')
      );
    end if;
  end if;
  return v_id;
end
$$;


--
-- Name: hotel_rate_plans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hotel_rate_plans (
    rate_plan_id integer NOT NULL,
    hotel_id integer NOT NULL,
    room_id integer NOT NULL,
    name text NOT NULL,
    description text,
    meal_plan text DEFAULT 'room_only'::text NOT NULL,
    payment_timing text DEFAULT 'pay_now'::text NOT NULL,
    refundable boolean DEFAULT false NOT NULL,
    cancellation_hours integer,
    price_per_night integer NOT NULL,
    included_features text[] DEFAULT '{}'::text[] NOT NULL,
    active boolean DEFAULT true NOT NULL,
    source_system text DEFAULT 'wehouse'::text NOT NULL,
    external_reference text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    arrival_issue_window_hours integer,
    CONSTRAINT hotel_rate_plans_arrival_issue_window_hours_check CHECK (((arrival_issue_window_hours IS NULL) OR ((arrival_issue_window_hours >= 2) AND (arrival_issue_window_hours <= 4)))),
    CONSTRAINT hotel_rate_plans_cancellation_hours_check CHECK (((cancellation_hours IS NULL) OR (cancellation_hours >= 0))),
    CONSTRAINT hotel_rate_plans_meal_plan_check CHECK ((meal_plan = ANY (ARRAY['room_only'::text, 'breakfast'::text, 'half_board'::text, 'full_board'::text, 'all_inclusive'::text]))),
    CONSTRAINT hotel_rate_plans_payment_timing_check CHECK ((payment_timing = ANY (ARRAY['pay_now'::text, 'before_arrival'::text, 'at_property'::text]))),
    CONSTRAINT hotel_rate_plans_price_per_night_check CHECK ((price_per_night > 0))
);


--
-- Name: partner_save_hotel_rate_plan(integer, integer, text, text, text, text, boolean, integer, integer, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_save_hotel_rate_plan(p_rate_plan_id integer, p_room_id integer, p_name text, p_description text, p_meal_plan text, p_payment_timing text, p_refundable boolean, p_cancellation_hours integer, p_price_per_night integer, p_included_features text[], p_active boolean DEFAULT true) RETURNS public.hotel_rate_plans
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_room public.hotel_rooms;
  v_plan public.hotel_rate_plans;
  v_before jsonb:='{}'::jsonb;
  v_actor text:=public.current_profile_user_id();
begin
  select * into v_room from public.hotel_rooms where room_id=p_room_id;
  if v_room.room_id is null then raise exception 'Room type not found'; end if;
  if not public.hotel_actor_has_capability(v_room.hotel_id,'hotel.rate.manage') then
    raise exception 'Hotel rate capability required';
  end if;
  if nullif(btrim(p_name),'') is null or coalesce(p_price_per_night,0)<=0 then
    raise exception 'Package name and nightly price are required';
  end if;
  if p_meal_plan not in ('room_only','breakfast','half_board','full_board','all_inclusive') then
    raise exception 'Choose a valid meal plan';
  end if;
  if p_payment_timing<>'pay_now' then
    raise exception 'Current hotel packages require WeHouse secure payment';
  end if;
  if coalesce(p_refundable,false) and coalesce(p_cancellation_hours,0)<1 then
    raise exception 'Refundable packages need a positive cancellation window';
  end if;
  if p_rate_plan_id is not null and not coalesce(p_active,true) and not exists(
    select 1 from public.hotel_rate_plans plan
    where plan.room_id=v_room.room_id and plan.active
      and plan.rate_plan_id<>p_rate_plan_id
  ) then raise exception 'A room must keep at least one visible package'; end if;
  if p_rate_plan_id is null then
    insert into public.hotel_rate_plans(
      hotel_id,room_id,name,description,meal_plan,payment_timing,refundable,
      cancellation_hours,price_per_night,included_features,active
    ) values(
      v_room.hotel_id,v_room.room_id,btrim(p_name),
      nullif(btrim(coalesce(p_description,'')),''),p_meal_plan,'pay_now',
      coalesce(p_refundable,false),case when coalesce(p_refundable,false)
        then p_cancellation_hours else null end,p_price_per_night,
      coalesce(p_included_features,array[]::text[]),coalesce(p_active,true)
    ) returning * into v_plan;
  else
    select to_jsonb(plan) into v_before from public.hotel_rate_plans plan
    where plan.rate_plan_id=p_rate_plan_id and plan.room_id=v_room.room_id;
    update public.hotel_rate_plans set
      name=btrim(p_name),description=nullif(btrim(coalesce(p_description,'')),''),
      meal_plan=p_meal_plan,payment_timing='pay_now',refundable=coalesce(p_refundable,false),
      cancellation_hours=case when coalesce(p_refundable,false)
        then p_cancellation_hours else null end,
      price_per_night=p_price_per_night,
      included_features=coalesce(p_included_features,array[]::text[]),
      active=coalesce(p_active,true),updated_at=now()
    where rate_plan_id=p_rate_plan_id and room_id=v_room.room_id
    returning * into v_plan;
    if v_plan.rate_plan_id is null then raise exception 'Package not found for this room'; end if;
  end if;
  insert into public.hotel_commercial_change_audit(
    hotel_id,actor_user_id,action,target_type,target_id,before_values,after_values
  ) values(
    v_room.hotel_id,v_actor,
    case when p_rate_plan_id is null then 'future_rate_plan_created' else 'future_rate_plan_updated' end,
    'hotel_rate_plan',v_plan.rate_plan_id::text,coalesce(v_before,'{}'::jsonb),to_jsonb(v_plan)
  );
  return v_plan;
end;
$$;


--
-- Name: hotel_venues; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hotel_venues (
    venue_id integer NOT NULL,
    hotel_id integer NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    description text,
    opening_hours text,
    package_notes text,
    active boolean DEFAULT true NOT NULL,
    external_reference text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hotel_venues_kind_check CHECK ((kind = ANY (ARRAY['restaurant'::text, 'bar'::text, 'cafe'::text, 'spa'::text, 'lounge'::text, 'pool'::text, 'gym'::text, 'other'::text])))
);


--
-- Name: partner_save_hotel_venue(integer, integer, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_save_hotel_venue(p_venue_id integer, p_hotel_id integer, p_name text, p_kind text, p_description text, p_opening_hours text, p_package_notes text, p_active boolean DEFAULT true) RETURNS public.hotel_venues
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_venue public.hotel_venues;
  v_before public.hotel_venues;
  v_status text;
  v_actor text:=public.current_profile_user_id();
begin
  if not public.hotel_actor_has_capability(p_hotel_id,'hotel.policy.manage') then
    raise exception 'Hotel policy capability required';
  end if;
  if nullif(btrim(p_name),'') is null
     or p_kind not in ('restaurant','bar','cafe','spa','lounge','pool','gym','other') then
    raise exception 'Facility name and type are required';
  end if;
  select status into v_status from public.hotels where hotel_id=p_hotel_id;
  if v_status is null then raise exception 'Hotel not found'; end if;
  if p_venue_id is null then
    if v_status<>'draft' then
      raise exception 'A live hotel needs WeHouse review before a facility is added';
    end if;
    insert into public.hotel_venues(
      hotel_id,name,kind,description,opening_hours,package_notes,active
    ) values(
      p_hotel_id,btrim(p_name),p_kind,nullif(btrim(coalesce(p_description,'')),''),
      nullif(btrim(coalesce(p_opening_hours,'')),''),
      nullif(btrim(coalesce(p_package_notes,'')),''),coalesce(p_active,true)
    ) returning * into v_venue;
  else
    select * into v_before from public.hotel_venues
    where venue_id=p_venue_id and hotel_id=p_hotel_id for update;
    if v_before.venue_id is null then raise exception 'Hotel facility not found'; end if;
    if v_status='active' and (
      btrim(p_name) is distinct from v_before.name
      or p_kind is distinct from v_before.kind
      or nullif(btrim(coalesce(p_description,'')),'') is distinct from v_before.description
      or coalesce(p_active,true) is distinct from v_before.active
    ) then raise exception 'Verified facility facts need WeHouse review before publication'; end if;
    update public.hotel_venues set
      name=case when v_status='draft' then btrim(p_name) else name end,
      kind=case when v_status='draft' then p_kind else kind end,
      description=case when v_status='draft'
        then nullif(btrim(coalesce(p_description,'')),'') else description end,
      opening_hours=nullif(btrim(coalesce(p_opening_hours,'')),''),
      package_notes=nullif(btrim(coalesce(p_package_notes,'')),''),
      active=case when v_status='draft' then coalesce(p_active,true) else active end,
      updated_at=now()
    where venue_id=p_venue_id and hotel_id=p_hotel_id
    returning * into v_venue;
  end if;
  insert into public.hotel_commercial_change_audit(
    hotel_id,actor_user_id,action,target_type,target_id,before_values,after_values
  ) values(
    p_hotel_id,v_actor,
    case when p_venue_id is null then 'draft_facility_created' else 'facility_operations_updated' end,
    'hotel_venue',v_venue.venue_id::text,
    case when p_venue_id is null then '{}'::jsonb else to_jsonb(v_before) end,
    to_jsonb(v_venue)
  );
  return v_venue;
end;
$$;


--
-- Name: partner_set_hotel_inventory_range(integer, date, date, integer, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_set_hotel_inventory_range(p_room_id integer, p_start_date date, p_end_date date, p_available_quantity integer, p_closed boolean DEFAULT false, p_rate_override integer DEFAULT NULL::integer, p_note text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_room public.hotel_rooms;
  v_count integer;
  v_actor text:=public.current_profile_user_id();
begin
  select * into v_room from public.hotel_rooms where room_id=p_room_id;
  if v_room.room_id is null then raise exception 'Room type not found'; end if;
  if not public.hotel_actor_has_capability(v_room.hotel_id,'hotel.inventory.manage') then
    raise exception 'Hotel inventory capability required';
  end if;
  if p_start_date<current_date or p_end_date<p_start_date
     or p_end_date>p_start_date+366 then
    raise exception 'Choose a valid date range up to one year';
  end if;
  if p_available_quantity<0 or p_available_quantity>v_room.total_rooms then
    raise exception 'Availability must stay within verified room capacity';
  end if;
  if p_rate_override is not null and p_rate_override<=0 then
    raise exception 'Rate override must be positive';
  end if;
  insert into public.hotel_inventory_daily(
    hotel_id,room_id,inventory_date,available_quantity,rate_override,
    closed,note,updated_by,updated_at
  )
  select v_room.hotel_id,v_room.room_id,day_value::date,p_available_quantity,
    p_rate_override,coalesce(p_closed,false),nullif(btrim(coalesce(p_note,'')),''),
    v_actor,now()
  from generate_series(p_start_date,p_end_date,interval '1 day') day_value
  on conflict(room_id,inventory_date) do update set
    available_quantity=excluded.available_quantity,
    rate_override=excluded.rate_override,closed=excluded.closed,
    note=excluded.note,updated_by=excluded.updated_by,updated_at=now();
  get diagnostics v_count=row_count;
  insert into public.hotel_commercial_change_audit(
    hotel_id,actor_user_id,action,target_type,target_id,after_values
  ) values(
    v_room.hotel_id,v_actor,'dated_inventory_updated','hotel_room',v_room.room_id::text,
    jsonb_build_object('start_date',p_start_date,'end_date',p_end_date,
      'available_quantity',p_available_quantity,'closed',coalesce(p_closed,false),
      'rate_override',p_rate_override)
  );
  return v_count;
end;
$$;


--
-- Name: partner_transition_hotel_booking(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_transition_hotel_booking(p_booking_id integer, p_status text) RETURNS public.hotel_bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_booking public.hotel_bookings;
  v_hotel public.hotels;
  v_unit public.hotel_room_units;
  v_local_now timestamp;
  v_arrival timestamp;
  v_departure timestamp;
  v_from_state text;
  v_actor text:=public.current_profile_user_id();
begin
  select * into v_booking from public.hotel_bookings
  where booking_id=p_booking_id for update;
  if v_booking.booking_id is null then raise exception 'Hotel booking not found'; end if;
  select * into v_hotel from public.hotels where hotel_id=v_booking.hotel_id;
  v_local_now:=timezone(v_hotel.timezone,now());
  v_arrival:=v_booking.check_in::timestamp+v_hotel.check_in_time;
  v_departure:=v_booking.check_out::timestamp+v_hotel.check_out_time;
  v_from_state:=coalesce(v_booking.canonical_state,v_booking.status);
  if p_status='checked_in' then
    if not public.hotel_actor_has_capability(v_booking.hotel_id,'stay.check_in')
       or not public.hotel_actor_has_capability(v_booking.hotel_id,'stay.assign_unit') then
      raise exception 'Hotel check-in and room-assignment capabilities required';
    end if;
    if v_from_state not in ('confirmed','check_in_ready')
       or v_booking.payment_status<>'paid'
       or v_local_now<v_arrival or v_local_now>=v_departure then
      raise exception 'This protected stay is not ready for check-in';
    end if;
    if not public.hotel_payment_protection_is_current(v_booking.payment_protection_id) then
      raise exception 'Verified Hotel Payment Protection is required';
    end if;
    select * into v_unit from public.hotel_room_units
    where hotel_id=v_booking.hotel_id and room_id=v_booking.room_id
      and status='ready' and current_booking_id is null
    order by unit_label for update skip locked limit 1;
    if v_unit.unit_id is null then raise exception 'No ready room is available'; end if;
    update public.hotel_room_units
    set status='occupied',current_booking_id=v_booking.booking_id,updated_at=now()
    where unit_id=v_unit.unit_id;
    update public.hotel_bookings
    set status='checked_in',canonical_state='checked_in',
      assigned_room_unit_id=v_unit.unit_id,checked_in_at=now(),updated_at=now()
    where booking_id=v_booking.booking_id returning * into v_booking;
    insert into public.hotel_stay_transitions(
      hotel_booking_id,from_state,to_state,event_type,event_key,
      actor_user_id,actor_type,metadata
    ) values(
      v_booking.booking_id,v_from_state,'checked_in','hotel_checked_in',
      'hotel_checked_in:'||v_booking.booking_id,v_actor,'hotel_team',
      jsonb_build_object('assigned_room_unit_id',v_unit.unit_id,'timezone',v_hotel.timezone)
    ) on conflict(event_key) do nothing;
  elsif p_status='checked_out' then
    if not public.hotel_actor_has_capability(v_booking.hotel_id,'stay.check_out') then
      raise exception 'Hotel checkout capability required';
    end if;
    if v_from_state<>'checked_in' or v_booking.payment_status<>'paid' then
      raise exception 'Only a paid checked-in stay can check out';
    end if;
    update public.hotel_room_units
    set status='cleaning',current_booking_id=null,updated_at=now()
    where unit_id=v_booking.assigned_room_unit_id
      and hotel_id=v_booking.hotel_id;
    update public.hotel_bookings
    set status='checked_out',canonical_state='checked_out',
      checked_out_at=now(),updated_at=now()
    where booking_id=v_booking.booking_id returning * into v_booking;
    insert into public.hotel_stay_transitions(
      hotel_booking_id,from_state,to_state,event_type,event_key,
      actor_user_id,actor_type,metadata
    ) values(
      v_booking.booking_id,'checked_in','checked_out','hotel_checked_out',
      'hotel_checked_out:'||v_booking.booking_id,v_actor,'hotel_team',
      jsonb_build_object('released_room_unit_id',v_booking.assigned_room_unit_id,
        'timezone',v_hotel.timezone)
    ) on conflict(event_key) do nothing;
  else
    raise exception 'Unsupported hotel booking transition';
  end if;
  return v_booking;
end;
$$;


--
-- Name: partner_update_hotel_room(integer, text, text, integer, integer, text, integer, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_update_hotel_room(p_room_id integer, p_room_type text, p_description text, p_price_per_night integer, p_max_guests integer, p_bed_type text, p_total_rooms integer, p_amenities text[] DEFAULT NULL::text[], p_images text[] DEFAULT NULL::text[]) RETURNS public.hotel_rooms
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_room public.hotel_rooms;
  v_hotel_status text;
  v_actor text:=public.current_profile_user_id();
  v_before jsonb;
begin
  select * into v_room from public.hotel_rooms where room_id=p_room_id for update;
  if v_room.room_id is null then raise exception 'Room type not found'; end if;
  if not public.hotel_actor_has_capability(v_room.hotel_id,'hotel.rate.manage') then
    raise exception 'Hotel rate capability required';
  end if;
  if nullif(btrim(p_room_type),'') is null or coalesce(p_price_per_night,0)<=0
     or coalesce(p_max_guests,0)<1 or coalesce(p_total_rooms,0)<1 then
    raise exception 'Valid room name, rate, capacity and inventory are required';
  end if;
  select status into v_hotel_status from public.hotels where hotel_id=v_room.hotel_id;
  if v_hotel_status='active' and (
    btrim(p_room_type) is distinct from v_room.room_type
    or nullif(btrim(coalesce(p_description,'')),'') is distinct from v_room.description
    or p_max_guests is distinct from v_room.max_guests
    or nullif(btrim(coalesce(p_bed_type,'')),'') is distinct from v_room.bed_type
    or p_total_rooms is distinct from v_room.total_rooms
    or coalesce(p_amenities,v_room.amenities) is distinct from v_room.amenities
    or coalesce(p_images,v_room.images) is distinct from v_room.images
  ) then
    raise exception 'Verified room facts and public media need WeHouse review before publication';
  end if;
  if v_hotel_status='draft'
     and not public.hotel_actor_has_capability(v_room.hotel_id,'hotel.inventory.manage') then
    raise exception 'Hotel inventory capability required for draft room facts';
  end if;
  v_before:=jsonb_build_object(
    'room_type',v_room.room_type,'description',v_room.description,
    'price_per_night',v_room.price_per_night,'max_guests',v_room.max_guests,
    'bed_type',v_room.bed_type,'total_rooms',v_room.total_rooms,
    'amenities',v_room.amenities,'images',v_room.images
  );
  update public.hotel_rooms set
    room_type=case when v_hotel_status='draft' then btrim(p_room_type) else room_type end,
    description=case when v_hotel_status='draft'
      then nullif(btrim(coalesce(p_description,'')),'') else description end,
    price_per_night=p_price_per_night,
    max_guests=case when v_hotel_status='draft' then p_max_guests else max_guests end,
    bed_type=case when v_hotel_status='draft'
      then nullif(btrim(coalesce(p_bed_type,'')),'') else bed_type end,
    total_rooms=case when v_hotel_status='draft' then p_total_rooms else total_rooms end,
    amenities=case when v_hotel_status='draft' then coalesce(p_amenities,amenities) else amenities end,
    images=case when v_hotel_status='draft' then coalesce(p_images,images) else images end,
    updated_at=now()
  where room_id=p_room_id returning * into v_room;
  update public.hotel_rate_plans
  set price_per_night=p_price_per_night,updated_at=now()
  where room_id=p_room_id and name='Room only' and source_system='wehouse';
  insert into public.hotel_commercial_change_audit(
    hotel_id,actor_user_id,action,target_type,target_id,before_values,after_values
  ) values(
    v_room.hotel_id,v_actor,
    case when v_hotel_status='draft' then 'draft_room_updated' else 'future_room_rate_updated' end,
    'hotel_room',v_room.room_id::text,v_before,
    jsonb_build_object(
      'room_type',v_room.room_type,'description',v_room.description,
      'price_per_night',v_room.price_per_night,'max_guests',v_room.max_guests,
      'bed_type',v_room.bed_type,'total_rooms',v_room.total_rooms,
      'amenities',v_room.amenities,'images',v_room.images
    )
  );
  return v_room;
end;
$$;


--
-- Name: hotel_room_units; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hotel_room_units (
    unit_id bigint NOT NULL,
    hotel_id integer NOT NULL,
    room_id integer NOT NULL,
    unit_label text NOT NULL,
    floor_label text,
    status text DEFAULT 'ready'::text NOT NULL,
    current_booking_id integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    ready_after timestamp with time zone,
    source_system text DEFAULT 'wehouse'::text NOT NULL,
    external_reference text,
    CONSTRAINT hotel_room_units_check CHECK (((status = 'occupied'::text) = (current_booking_id IS NOT NULL))),
    CONSTRAINT hotel_room_units_status_check CHECK ((status = ANY (ARRAY['ready'::text, 'occupied'::text, 'cleaning'::text, 'maintenance'::text, 'out_of_service'::text]))),
    CONSTRAINT hotel_room_units_unit_label_check CHECK ((NULLIF(btrim(unit_label), ''::text) IS NOT NULL))
);


--
-- Name: partner_update_hotel_room_unit(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_update_hotel_room_unit(p_unit_id bigint, p_unit_label text, p_floor_label text, p_status text) RETURNS public.hotel_room_units
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_unit public.hotel_room_units;
  v_hotel_status text;
  v_actor text:=public.current_profile_user_id();
begin
  select * into v_unit from public.hotel_room_units where unit_id=p_unit_id for update;
  if v_unit.unit_id is null then raise exception 'Hotel room not found'; end if;
  if not public.hotel_actor_has_capability(v_unit.hotel_id,'room.mark_ready') then
    raise exception 'Room readiness capability required';
  end if;
  if nullif(btrim(coalesce(p_unit_label,'')),'') is null then
    raise exception 'Room number or label is required';
  end if;
  if p_status not in ('ready','cleaning','maintenance','out_of_service') then
    raise exception 'Choose ready, cleaning, maintenance or out of service';
  end if;
  if v_unit.current_booking_id is not null then
    raise exception 'An occupied room cannot be changed until checkout';
  end if;
  select status into v_hotel_status from public.hotels where hotel_id=v_unit.hotel_id;
  if v_hotel_status='active' and (
    btrim(p_unit_label) is distinct from v_unit.unit_label
    or nullif(btrim(coalesce(p_floor_label,'')),'') is distinct from v_unit.floor_label
  ) then raise exception 'Verified room identity needs WeHouse review before it changes'; end if;
  update public.hotel_room_units set
    unit_label=case when v_hotel_status='draft' then btrim(p_unit_label) else unit_label end,
    floor_label=case when v_hotel_status='draft'
      then nullif(btrim(coalesce(p_floor_label,'')),'') else floor_label end,
    status=p_status,updated_at=now()
  where unit_id=p_unit_id returning * into v_unit;
  insert into public.hotel_commercial_change_audit(
    hotel_id,actor_user_id,action,target_type,target_id,after_values
  ) values(
    v_unit.hotel_id,v_actor,'room_readiness_updated','hotel_room_unit',v_unit.unit_id::text,
    jsonb_build_object('status',v_unit.status)
  );
  return v_unit;
end;
$$;


--
-- Name: hotels; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hotels (
    hotel_id integer NOT NULL,
    name text NOT NULL,
    description text,
    state text NOT NULL,
    city text NOT NULL,
    area text,
    address text,
    images text[] DEFAULT '{}'::text[],
    amenities text[] DEFAULT '{}'::text[],
    owner_id text NOT NULL,
    status text DEFAULT 'active'::text,
    rating numeric(2,1) DEFAULT 0,
    review_count integer DEFAULT 0,
    featured boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    inspection_request_id uuid,
    gps_latitude numeric,
    gps_longitude numeric,
    approved_by text,
    approved_at timestamp with time zone,
    published_at timestamp with time zone,
    check_in_time time without time zone DEFAULT '14:00:00'::time without time zone NOT NULL,
    check_out_time time without time zone DEFAULT '12:00:00'::time without time zone NOT NULL,
    turnover_minutes integer DEFAULT 120 NOT NULL,
    completion_mode text DEFAULT 'auto'::text NOT NULL,
    completion_review_hours integer DEFAULT 24 NOT NULL,
    manual_completion_sla_hours integer DEFAULT 48 NOT NULL,
    timezone text DEFAULT 'Africa/Lagos'::text NOT NULL,
    arrival_issue_window_hours integer DEFAULT 2 NOT NULL,
    CONSTRAINT hotels_arrival_issue_window_hours_check CHECK (((arrival_issue_window_hours >= 2) AND (arrival_issue_window_hours <= 4))),
    CONSTRAINT hotels_completion_mode_check CHECK ((completion_mode = ANY (ARRAY['immediate'::text, 'auto'::text, 'manual'::text]))),
    CONSTRAINT hotels_completion_review_hours_check CHECK (((completion_review_hours >= 0) AND (completion_review_hours <= 168))),
    CONSTRAINT hotels_manual_completion_sla_hours_check CHECK (((manual_completion_sla_hours >= 1) AND (manual_completion_sla_hours <= 336))),
    CONSTRAINT hotels_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'inactive'::text]))),
    CONSTRAINT hotels_turnover_minutes_check CHECK (((turnover_minutes >= 0) AND (turnover_minutes <= 1440)))
);


--
-- Name: partner_update_hotel_stay_policy(integer, time without time zone, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_update_hotel_stay_policy(p_hotel_id integer, p_check_in_time time without time zone, p_check_out_time time without time zone) RETURNS public.hotels
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_result public.hotels;
  v_before public.hotels;
  v_actor text:=public.current_profile_user_id();
begin
  if not public.hotel_actor_has_capability(p_hotel_id,'hotel.policy.manage') then
    raise exception 'Hotel policy capability required';
  end if;
  if p_check_in_time is null or p_check_out_time is null then
    raise exception 'Check-in and checkout times are required';
  end if;
  select * into v_before from public.hotels where hotel_id=p_hotel_id for update;
  if v_before.hotel_id is null then raise exception 'Hotel not found'; end if;
  update public.hotels set
    check_in_time=p_check_in_time,check_out_time=p_check_out_time,updated_at=now()
  where hotel_id=p_hotel_id returning * into v_result;
  insert into public.hotel_commercial_change_audit(
    hotel_id,actor_user_id,action,target_type,target_id,before_values,after_values
  ) values(
    p_hotel_id,v_actor,'stay_policy_updated','hotel',p_hotel_id::text,
    jsonb_build_object('check_in_time',v_before.check_in_time,
      'check_out_time',v_before.check_out_time),
    jsonb_build_object('check_in_time',v_result.check_in_time,
      'check_out_time',v_result.check_out_time)
  );
  return v_result;
end;
$$;


--
-- Name: partner_update_hotel_stay_policy_v2(integer, time without time zone, time without time zone, integer, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_update_hotel_stay_policy_v2(p_hotel_id integer, p_check_in_time time without time zone, p_check_out_time time without time zone, p_turnover_minutes integer, p_completion_mode text, p_completion_review_hours integer, p_manual_completion_sla_hours integer) RETURNS public.hotels
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result public.hotels;
begin
  if not public.current_actor_has_hotel_capability(p_hotel_id,'hotel.policy.manage') then raise exception 'Hotel policy management access required'; end if;
  if p_check_in_time is null or p_check_out_time is null then raise exception 'Check-in and checkout times are required'; end if;
  if coalesce(p_turnover_minutes,-1) not between 0 and 1440 then raise exception 'Turnover must be between 0 and 1440 minutes'; end if;
  if p_completion_mode not in ('immediate','auto','manual') then raise exception 'Choose immediate, auto or manual completion'; end if;
  update public.hotels set check_in_time=p_check_in_time,check_out_time=p_check_out_time,turnover_minutes=p_turnover_minutes,completion_mode=p_completion_mode,
    completion_review_hours=greatest(0,least(coalesce(p_completion_review_hours,24),168)),manual_completion_sla_hours=greatest(1,least(coalesce(p_manual_completion_sla_hours,48),336)),updated_at=now()
  where hotel_id=p_hotel_id returning * into result;
  if result.hotel_id is null then raise exception 'Hotel not found'; end if;
  return result;
end;
$$;


--
-- Name: post_ledger_transaction(text, text, text, text, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_ledger_transaction(p_idempotency_key text, p_transaction_type text, p_currency text, p_reference_type text, p_reference_id text, p_provider_event_id uuid, p_metadata jsonb, p_entries jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_transaction_id uuid;
  v_existing public.ledger_transactions;
  v_payload_checksum text;
  v_total numeric;
  v_count integer;
  v_entry jsonb;
  v_account public.ledger_accounts;
  v_actor text;
begin
  if (select auth.role())<>'service_role' then
    raise exception 'service role required';
  end if;
  if coalesce(nullif(btrim(p_idempotency_key),''),'')='' then
    raise exception 'idempotency_key is required';
  end if;
  if jsonb_typeof(p_entries)<>'array' then
    raise exception 'entries must be a JSON array';
  end if;
  select count(*),coalesce(sum((x->>'amount')::numeric),0)
  into v_count,v_total from jsonb_array_elements(p_entries) x;
  if v_count<2 or v_total<>0 then
    raise exception 'Ledger debits and credits must be balanced';
  end if;
  if exists(
    select 1 from jsonb_array_elements(p_entries) x
    where coalesce((x->>'amount')::numeric,0)=0
      or nullif(btrim(x->>'account_key'),'') is null
      or (x->>'account_class') not in ('asset','liability','revenue','expense','equity')
  ) then raise exception 'Invalid ledger entry'; end if;

  v_payload_checksum:=md5(
    p_transaction_type||':'||upper(p_currency)||':'||p_reference_type||':'
    ||p_reference_id||':'||coalesce(p_metadata,'{}'::jsonb)::text||':'||p_entries::text
  );
  select * into v_existing from public.ledger_transactions
  where idempotency_key=p_idempotency_key;
  if v_existing.ledger_transaction_id is not null then
    if v_existing.payload_checksum<>v_payload_checksum then
      raise exception 'Idempotency key was reused with a different transaction';
    end if;
    return v_existing.ledger_transaction_id;
  end if;

  insert into public.ledger_transactions(
    idempotency_key,transaction_type,currency,reference_type,reference_id,
    provider_event_id,payload_checksum,metadata,created_by
  ) values(
    p_idempotency_key,p_transaction_type,upper(p_currency),p_reference_type,
    p_reference_id,p_provider_event_id,v_payload_checksum,
    coalesce(p_metadata,'{}'::jsonb),v_actor
  ) returning ledger_transaction_id into v_transaction_id;

  for v_entry in select * from jsonb_array_elements(p_entries)
  loop
    insert into public.ledger_accounts(
      account_key,account_class,owner_type,owner_id,currency
    ) values(
      v_entry->>'account_key',v_entry->>'account_class',
      nullif(v_entry->>'owner_type',''),nullif(v_entry->>'owner_id',''),
      upper(p_currency)
    ) on conflict(account_key) do update
      set account_key=excluded.account_key
    returning * into v_account;
    if v_account.currency<>upper(p_currency)
      or v_account.account_class<>(v_entry->>'account_class') then
      raise exception 'Ledger account definition conflict';
    end if;
    insert into public.ledger_entries(
      ledger_transaction_id,ledger_account_id,amount,memo
    ) values(
      v_transaction_id,v_account.ledger_account_id,
      (v_entry->>'amount')::numeric,nullif(v_entry->>'memo','')
    );
  end loop;
  return v_transaction_id;
end
$$;


--
-- Name: post_property_from_inspection(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_property_from_inspection(p_data jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_caller public.profiles;
  v_ir public.inspection_requests;
  v_partner public.profiles;
  v_listing_id uuid;
  v_code text;
  v_images text[];
  v_videos text[];
  v_amenities text[];
  v_sub_type text;
  v_deposit numeric;
begin
  select * into v_caller
  from public.profiles
  where auth_id=auth.uid()::text
    and role in ('staff','admin','creator')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_caller is null then raise exception 'WeHouse operations access required'; end if;
  if v_caller.role='staff' and not public.current_staff_has_permission('operations') then
    raise exception 'Operations permission required';
  end if;

  select * into v_ir
  from public.inspection_requests
  where id=(p_data->>'inspection_id')::uuid
  for update;
  if v_ir is null or v_ir.status not in ('completed','approved') then
    raise exception 'Inspection must be completed before listing preparation';
  end if;
  if v_caller.role in ('admin','staff') and not public.current_actor_in_scope(v_ir.property_state,v_ir.property_city) then
    raise exception 'Property is outside your assigned branch';
  end if;
  if v_ir.property_type='hotel' then raise exception 'Hotels use the hotel preparation workflow'; end if;

  if v_ir.draft_listing_id is not null then
    select id into v_listing_id
    from public.listings
    where id=v_ir.draft_listing_id
      and inspection_request_id=v_ir.id
      and deleted_at is null
    limit 1;
    if v_listing_id is not null then return v_listing_id; end if;
    update public.inspection_requests
    set draft_listing_id=null,updated_at=now()
    where id=v_ir.id;
  end if;

  select * into v_partner
  from public.profiles
  where user_id=v_ir.owner_id
    and public.user_has_active_workspace(user_id,'property_partner')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_partner is null then raise exception 'Valid Property Partner owner required'; end if;
  if nullif(btrim(p_data->>'title'),'') is null or coalesce((p_data->>'price')::numeric,0)<=0 then
    raise exception 'Listing title and valid price are required';
  end if;

  v_sub_type:=coalesce(nullif(btrim(p_data->>'sub_type'),''),v_ir.sub_type);
  if v_sub_type not in ('short_let','long_stay') then
    raise exception 'Choose Short Let or Long Let before preparing this apartment';
  end if;
  v_deposit:=coalesce(nullif(p_data->>'security_deposit_amount','')::numeric,v_ir.security_deposit_amount);
  if v_sub_type='short_let' and coalesce(v_deposit,0)<=0 then
    raise exception 'Short Let requires a refundable security deposit';
  end if;
  if v_sub_type='long_stay' then v_deposit:=null; end if;

  select coalesce(array_agg(value),array[]::text[]) into v_images
  from jsonb_array_elements_text(coalesce(p_data->'images','[]'::jsonb));
  select coalesce(array_agg(value),array[]::text[]) into v_videos
  from jsonb_array_elements_text(coalesce(p_data->'videos','[]'::jsonb));
  select coalesce(array_agg(distinct value),array[]::text[]) into v_amenities
  from jsonb_array_elements_text(coalesce(p_data->'amenities',to_jsonb(coalesce(v_ir.amenities,array[]::text[]))));
  if v_sub_type='short_let' and not ('Furnished'=any(coalesce(v_amenities,array[]::text[]))) then
    v_amenities:=array_append(coalesce(v_amenities,array[]::text[]),'Furnished');
  end if;

  v_code:='WHL-'||upper(substring(replace(gen_random_uuid()::text,'-','') from 1 for 12));
  insert into public.listings(
    listing_id,title,description,price,currency,state,city,address,images,videos,bedrooms,bathrooms,
    property_type,sub_type,security_deposit_amount,amenities,availability_status,owner_id,partner_id,
    chat_agent_id,status,submitted_by_role,reservation_fee_paid,chat_unlocked,gps_latitude,gps_longitude,
    inspection_request_id,created_at,updated_at
  ) values (
    v_code,btrim(p_data->>'title'),nullif(btrim(p_data->>'description'),''),(p_data->>'price')::numeric,'NGN',
    v_ir.property_state,v_ir.property_city,v_ir.property_address,v_images,v_videos,
    coalesce((p_data->>'bedrooms')::int,v_ir.bedrooms,1),coalesce((p_data->>'bathrooms')::int,v_ir.bathrooms,1),
    coalesce(nullif(btrim(p_data->>'property_type'),''),v_ir.property_type,'apartment'),v_sub_type,v_deposit,v_amenities,
    'pending_approval',v_partner.user_id,v_partner.user_id,v_caller.user_id,'pending_approval','property_partner',false,false,
    v_ir.gps_latitude,v_ir.gps_longitude,v_ir.id,now(),now()
  ) returning id into v_listing_id;

  update public.inspection_requests
  set draft_listing_id=v_listing_id,sub_type=v_sub_type,security_deposit_amount=v_deposit,amenities=v_amenities,updated_at=now()
  where id=v_ir.id;
  return v_listing_id;
end;
$$;


--
-- Name: post_property_from_inspection_v2(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_property_from_inspection_v2(p_data jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  return public.post_property_from_inspection(
    coalesce(p_data,'{}'::jsonb) || jsonb_build_object('images','[]'::jsonb,'videos','[]'::jsonb)
  );
end;
$$;


--
-- Name: prepare_hotel_listing(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_hotel_listing(p_inspection_id uuid, p_editorial_description text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
  v_program jsonb;
  v_rooms jsonb;
  v_room jsonb;
  v_hotel_id integer;
  v_name text;
  v_amenities text[];
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and role in ('staff','admin','creator')
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null then raise exception 'Property Operations access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then
    raise exception 'Property Operations permission required';
  end if;
  select * into v_request from public.inspection_requests
  where id=p_inspection_id for update;
  if v_request.id is null or v_request.property_type<>'hotel' then raise exception 'Accepted hotel inspection required'; end if;
  if v_actor.role in ('staff','admin') and not public.current_actor_in_scope(v_request.property_state,v_request.property_city) then
    raise exception 'Hotel is outside your assigned branch';
  end if;
  if v_request.draft_hotel_id is not null then return v_request.draft_hotel_id; end if;
  if v_request.lifecycle_stage<>'ready_to_prepare' or v_request.field_evidence_review_status<>'accepted' then
    raise exception 'Field evidence must be independently accepted before preparation';
  end if;
  v_program:=coalesce(v_request.hotel_program,'{}'::jsonb);
  v_rooms:=coalesce(v_program->'room_types','[]'::jsonb);
  v_name:=nullif(btrim(v_program->>'name'),'');
  if v_name is null then raise exception 'The Property Partner must supply the hotel name'; end if;
  if jsonb_typeof(v_rooms)<>'array' or jsonb_array_length(v_rooms)=0 then
    raise exception 'The Property Partner must submit at least one room type';
  end if;
  select coalesce(array_agg(value),array[]::text[]) into v_amenities
  from jsonb_array_elements_text(coalesce(v_program->'amenities','[]'::jsonb));
  insert into public.hotels(
    name,description,state,city,address,images,amenities,owner_id,status,featured,
    gps_latitude,gps_longitude,inspection_request_id,created_at,updated_at
  ) values(
    v_name,coalesce(nullif(btrim(coalesce(p_editorial_description,'')),''),v_request.description),
    v_request.property_state,v_request.property_city,v_request.property_address,
    array[]::text[],v_amenities,v_request.owner_id,'draft',false,
    v_request.gps_latitude,v_request.gps_longitude,v_request.id,now(),now()
  ) returning hotel_id into v_hotel_id;
  for v_room in select value from jsonb_array_elements(v_rooms) loop
    if nullif(btrim(v_room->>'name'),'') is null
       or coalesce((v_room->>'nightly_rate')::integer,0)<=0 then
      raise exception 'Every submitted room needs a name and nightly rate';
    end if;
    insert into public.hotel_rooms(
      hotel_id,room_type,description,price_per_night,max_guests,bed_type,
      images,amenities,total_rooms,created_at,updated_at
    ) values(
      v_hotel_id,btrim(v_room->>'name'),nullif(btrim(v_room->>'description'),''),
      (v_room->>'nightly_rate')::integer,greatest(coalesce((v_room->>'guest_capacity')::integer,2),1),
      nullif(btrim(v_room->>'bed_type'),''),array[]::text[],
      coalesce(array(select jsonb_array_elements_text(coalesce(v_room->'amenities','[]'::jsonb))),array[]::text[]),
      greatest(coalesce((v_room->>'inventory')::integer,1),1),now(),now()
    );
  end loop;
  update public.inspection_requests set draft_hotel_id=v_hotel_id,updated_at=now()
  where id=v_request.id;
  return v_hotel_id;
end;
$$;


--
-- Name: prepare_inspected_hotel_media(uuid, text[], text[], jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_inspected_hotel_media(p_inspection_id uuid, p_hotel_source_images text[], p_hotel_public_images text[], p_room_source_galleries jsonb, p_room_public_galleries jsonb) RETURNS boolean
