--
-- Name: prevent_privileged_self_review(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_privileged_self_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor text:=public.current_profile_user_id(); v_new jsonb:=to_jsonb(new); v_old jsonb:=to_jsonb(old);
begin
  if actor is null then return new; end if;
  if tg_table_name='listings'
     and (v_new->>'approved_by' is distinct from v_old->>'approved_by' or (v_old->>'status' is distinct from v_new->>'status' and v_new->>'status' in('available','rejected')))
     and actor in(coalesce(v_new->>'owner_id',''),coalesce(v_new->>'partner_id','')) then
    raise exception 'Another authorized person must review your listing';
  elsif tg_table_name='profiles'
     and (v_new->>'worker_status' in('verified','rejected') or coalesce((v_new->>'worker_verified')::boolean,false))
     and (v_new->>'worker_status' is distinct from v_old->>'worker_status' or v_new->>'worker_verified' is distinct from v_old->>'worker_verified')
     and actor=v_new->>'user_id' then
    raise exception 'Another authorized person must review your Worker verification';
  elsif tg_table_name='reservations'
     and v_new->>'status'='refunded' and v_old->>'status' is distinct from v_new->>'status' and actor=v_new->>'user_id' then
    raise exception 'Another authorized person must process your refund';
  elsif tg_table_name='inspection_requests'
     and v_new->>'access_evidence_status' in('verified','rejected')
     and v_old->>'access_evidence_status' is distinct from v_new->>'access_evidence_status'
     and actor=v_new->>'owner_id' then
    raise exception 'Another authorized person must review your property evidence';
  end if;
  return new;
end $$;


--
-- Name: prevent_published_policy_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_published_policy_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if old.status<>'draft' then
    if old.status in ('active','scheduled') and new.status='retired'
      and new.policy_version_id=old.policy_version_id
      and new.policy_key=old.policy_key
      and new.scope_type=old.scope_type
      and new.scope_key=old.scope_key
      and new.version=old.version
      and new.value=old.value
      and new.value_schema=old.value_schema
      and new.effective_from=old.effective_from
      and new.public_disclosure=old.public_disclosure
      and new.disclosure_text is not distinct from old.disclosure_text
      and new.legal_review_state=old.legal_review_state
      and new.reason=old.reason
      and new.created_by is not distinct from old.created_by
      and new.approved_by is not distinct from old.approved_by
      and new.supersedes is not distinct from old.supersedes
      and new.checksum=old.checksum
      and new.created_at=old.created_at
      and new.published_at is not distinct from old.published_at
    then
      return new;
    end if;
    if old.status='scheduled' and new.status='active'
      and (select auth.role())='service_role'
      and new.policy_version_id=old.policy_version_id
      and new.policy_key=old.policy_key
      and new.scope_type=old.scope_type
      and new.scope_key=old.scope_key
      and new.version=old.version
      and new.value=old.value
      and new.value_schema=old.value_schema
      and new.effective_from=old.effective_from
      and new.public_disclosure=old.public_disclosure
      and new.disclosure_text is not distinct from old.disclosure_text
      and new.legal_review_state=old.legal_review_state
      and new.reason=old.reason
      and new.created_by is not distinct from old.created_by
      and new.approved_by is not distinct from old.approved_by
      and new.supersedes is not distinct from old.supersedes
      and new.checksum=old.checksum
      and new.created_at=old.created_at
    then return new; end if;
    raise exception 'Published policy versions are immutable except retirement';
  end if;
  return new;
end
$$;


--
-- Name: process_booking_payment(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_booking_payment(p_booking_id uuid, p_paystack_reference text, p_amount numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_booking RECORD; v_wallet RECORD;
BEGIN
  SELECT * INTO v_booking FROM worker_bookings WHERE id = p_booking_id;
  IF NOT FOUND THEN RETURN FALSE; END IF;
  UPDATE worker_bookings SET status = 'paid', paystack_reference = p_paystack_reference,
    paystack_status = 'success', paid_at = NOW(),
    dispute_period_ends_at = NOW() + INTERVAL '48 hours', updated_at = NOW() WHERE id = p_booking_id;
  INSERT INTO booking_status_history (booking_id, old_status, new_status, changed_by, notes)
  VALUES (p_booking_id, v_booking.status, 'paid', 'system', 'Paystack: ' || p_paystack_reference);
  SELECT * INTO v_wallet FROM wallets WHERE owner_id = v_booking.worker_id;
  IF v_wallet.id IS NULL THEN
    INSERT INTO wallets (owner_id, owner_type, pending_balance) VALUES (v_booking.worker_id, 'worker', p_amount);
  ELSE
    UPDATE wallets SET pending_balance = COALESCE(pending_balance, 0) + p_amount, updated_at = NOW() WHERE id = v_wallet.id;
  END IF;
  RETURN TRUE;
END;
$$;


--
-- Name: process_due_hotel_stay_completions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_due_hotel_stay_completions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare r record; n integer:=0; source text;
begin
  update public.hotel_room_units set status='ready',ready_after=null,updated_at=now()
  where status='cleaning' and current_booking_id is null and ready_after is not null and ready_after<=now();
  for r in
    select b.booking_id,h.completion_mode from public.hotel_bookings b join public.hotels h on h.hotel_id=b.hotel_id
    where b.status='checked_out' and b.payment_status='paid' and b.completion_due_at is not null and b.completion_due_at<=now()
    for update of b skip locked
  loop
    source:=case when r.completion_mode='manual' then 'manual_sla_fallback' else 'auto_review' end;
    perform public.complete_hotel_stay_internal(r.booking_id,source,null); n:=n+1;
  end loop;
  return n;
end;
$$;


--
-- Name: process_reservation_refund(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_reservation_refund(p_reservation_id text, p_reason_category text, p_reason_detail text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_res public.reservations; v_calc record; v_actor public.profiles;
begin
  select * into v_actor from public.profiles where auth_id=auth.uid()::text and role in ('admin','creator')
    and coalesce(deleted,false)=false and coalesce(suspended,false)=false and coalesce(banned,false)=false limit 1;
  if v_actor is null then raise exception 'Admin or Creator refund authority required'; end if;
  select * into v_res from public.reservations where id=p_reservation_id for update;
  if v_res is null then raise exception 'Reservation not found'; end if;
  if v_actor.role='admin' and not public.current_actor_can_access_listing_ref(v_res.listing_id) then raise exception 'Reservation is outside your assigned branch'; end if;
  if v_res.status='refunded' then return true; end if;
  select * into v_calc from public.calculate_reservation_refund(p_reservation_id,p_reason_category);
  insert into public.reservation_refunds(reservation_id,user_id,original_amount,refund_percent,refund_amount,wehouse_retained,reason_category,reason_detail,processed_by)
  values(v_res.id,v_res.user_id,v_res.amount,v_calc.refund_percent,v_calc.refund_amount,v_calc.wehouse_retained,p_reason_category,nullif(btrim(coalesce(p_reason_detail,'')),''),v_actor.user_id);
  update public.reservations set status='refunded',refund_amount=v_calc.refund_amount,refund_reason=p_reason_category,processed_by=v_actor.user_id,processed_at=now(),updated_at=now() where id=v_res.id;
  if coalesce(v_res.stay_type,'long_stay')<>'short_let' then
    update public.listings set availability_status='available',status='available',reserved_by=null,reservation_expiry=null,updated_at=now()
    where id::text=v_res.listing_id or listing_id=v_res.listing_id;
  else
    update public.listings set reserved_by=null,reservation_expiry=null,occupied_by=null,occupied_at=null,tenancy_ends_at=null,current_reservation_id=null,updated_at=now()
    where (id::text=v_res.listing_id or listing_id=v_res.listing_id) and current_reservation_id=v_res.id;
  end if;
  return true;
end;
$$;


--
-- Name: process_verified_paystack_charge(text, text, text, text, timestamp with time zone, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_verified_paystack_charge(p_provider_event_key text, p_event_type text, p_provider_reference text, p_payload_sha256 text, p_signature_verified_at timestamp with time zone, p_amount_minor bigint, p_currency text, p_transaction_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_event public.verified_provider_events;
  v_payment public.booking_payments;
  v_result jsonb;
  v_amount numeric(18,2);
  v_payer text;
  v_payee text;
  v_subject_type text;
  v_subject_id text;
  v_component text;
  v_rate numeric:=0;
  v_policy_id uuid;
  v_protection public.payment_protection_transactions;
  v_stay_protection public.payment_protection_transactions;
  v_caution_protection public.payment_protection_transactions;
  v_reservation public.reservations;
  v_listing public.listings;
  v_hotel_booking public.hotel_bookings;
  v_group public.shared_housing_groups;
  v_stay_amount numeric(18,2):=0;
  v_caution_amount numeric(18,2):=0;
  v_entries jsonb;
  v_liability_total numeric(18,2):=0;
  v_ledger_transaction_id uuid;
  v_error text;
begin
  if (select auth.role())<>'service_role' then
    raise exception 'service role required';
  end if;
  if p_event_type<>'charge.success'
    or nullif(btrim(p_provider_event_key),'') is null
    or nullif(btrim(p_provider_reference),'') is null
    or p_payload_sha256 !~ '^[0-9a-f]{64}$'
    or p_signature_verified_at is null
    or p_amount_minor<=0
    or upper(p_currency)<>'NGN'
  then raise exception 'Invalid verified Paystack charge'; end if;
  v_amount:=round((p_amount_minor::numeric/100)::numeric,2);

  insert into public.verified_provider_events(
    provider,provider_event_key,event_type,provider_reference,payload_sha256,
    signature_verified_at,processing_status
  ) values(
    'paystack',p_provider_event_key,p_event_type,p_provider_reference,
    lower(p_payload_sha256),p_signature_verified_at,'received'
  ) on conflict do nothing;

  select * into v_event
  from public.verified_provider_events
  where provider='paystack'
    and event_type=p_event_type
    and provider_reference=p_provider_reference
  for update;
  if v_event.provider_event_id is null then
    raise exception 'Provider event could not be registered';
  end if;
  if v_event.provider_event_key<>p_provider_event_key
    or v_event.payload_sha256<>lower(p_payload_sha256) then
    raise exception 'Provider event replay does not match the verified receipt';
  end if;
  if v_event.processing_status='processed' then
    return jsonb_build_object(
      'success',true,'already_processed',true,
      'provider_event_id',v_event.provider_event_id
    );
  end if;

  select * into v_payment from public.booking_payments
  where paystack_reference=p_provider_reference for update;
  if v_payment.id is null then
    update public.verified_provider_events
    set processing_status='ignored',processed_at=now(),
        processing_error='No matching WeHouse payment reference'
    where provider_event_id=v_event.provider_event_id;
    return jsonb_build_object('success',true,'ignored',true);
  end if;
  if round(coalesce(v_payment.amount_total,v_payment.amount,0)::numeric*100)
      <>p_amount_minor then
    update public.verified_provider_events
    set processing_status='failed',processed_at=now(),
        processing_error='Verified amount does not match the payment request'
    where provider_event_id=v_event.provider_event_id;
    return jsonb_build_object('success',false,'error','Amount mismatch');
  end if;
  if upper(coalesce(v_payment.currency,'NGN'))<>'NGN' then
    update public.verified_provider_events
    set processing_status='failed',processed_at=now(),
        processing_error='Verified currency does not match the payment request'
    where provider_event_id=v_event.provider_event_id;
    return jsonb_build_object('success',false,'error','Currency mismatch');
  end if;

  if v_payment.purpose='worker_booking' then
    select (p.value->>'percent')::numeric,p.policy_version_id
    into v_rate,v_policy_id from public.creator_policy_versions p
    where p.policy_key='commission_worker' and p.scope_type='global'
      and p.scope_key='*' and p.status='active'
      and p.effective_from<=now()
      and (p.effective_until is null or p.effective_until>now())
    order by p.effective_from desc limit 1;
    if v_rate is null or v_rate<0 or v_rate>50 then
      raise exception 'Active Creator Worker commission is required';
    end if;
    update public.platform_settings
    set value=v_rate::text,editable=false,is_active=true,updated_at=now()
    where key='worker_commission_rate';
  end if;

  begin
    if v_payment.purpose='worker_booking' then
      if v_payment.worker_booking_id is null then
        raise exception 'Worker booking link is missing';
      end if;
      v_result:=public.confirm_worker_booking_payment(
        v_payment.worker_booking_id,p_provider_reference,v_amount,'NGN',p_transaction_id
      );
    elsif v_payment.purpose='shared_housing_share' then
      v_result:=public.confirm_shared_housing_payment(
        p_provider_reference,p_transaction_id,v_amount
      );
    elsif v_payment.purpose in(
      'apartment_reservation','apartment_rent','rent_plan_contribution',
      'hotel_booking','worker_verification'
    ) then
      v_result:=public.confirm_booking_payment(
        p_provider_reference,p_transaction_id,v_amount,'webhook',v_payment.purpose
      );
    else
      raise exception 'Unsupported payment purpose: %',coalesce(v_payment.purpose,'missing');
    end if;
    if not coalesce((v_result->>'success')::boolean,false) then
      raise exception '%',coalesce(v_result->>'error','Lifecycle payment confirmation failed');
    end if;

    v_payer:=coalesce(v_payment.payer_user_id,v_payment.user_id);
    v_payee:=v_payment.payee_user_id;
    v_component:=coalesce(v_payment.metadata->>'payment_component','');

    if v_payment.listing_id is not null then
      select * into v_listing from public.listings
      where id::text=v_payment.listing_id limit 1;
      v_payee:=coalesce(v_payee,v_listing.partner_id,v_listing.owner_id);
    end if;

    if v_payment.purpose='worker_booking' then
      select * into v_protection
      from public.payment_protection_transactions
      where booking_type='worker_booking'
        and booking_id=v_payment.worker_booking_id
      for update;
      if v_protection.id is null then
        raise exception 'Worker payment did not create Payment Protection';
      end if;
      update public.payment_protection_transactions
      set subject_type='worker_booking',subject_id=v_payment.worker_booking_id::text,
          amount_commission=round(v_amount*v_rate/100,2),
          amount_payee=v_amount-round(v_amount*v_rate/100,2),
          commission_rate=v_rate,updated_at=now()
      where id=v_protection.id returning * into v_protection;
      update public.worker_bookings
      set payment_protection_id=v_protection.id,policy_version_id=v_policy_id,
          wehouse_fee=v_protection.amount_commission,
          worker_commission=v_protection.amount_commission,
          worker_receives=v_protection.amount_payee,updated_at=now()
      where id=v_payment.worker_booking_id;

    elsif v_payment.purpose='apartment_rent' then
      select * into v_reservation from public.reservations
      where id=v_payment.metadata->>'reservation_id' for update;
      if v_reservation.id is null then raise exception 'Reservation link is missing'; end if;
      if v_listing.id is null then
        select * into v_listing from public.listings
        where id::text=v_reservation.listing_id limit 1;
        v_payee:=coalesce(v_payee,v_listing.partner_id,v_listing.owner_id);
      end if;
      if v_payee is null then raise exception 'Property payee is missing'; end if;

      if v_component='short_stay_rent' or v_reservation.stay_type='short_let' then
        select (p.value->>'percent')::numeric,p.policy_version_id
        into v_rate,v_policy_id from public.creator_policy_versions p
        where p.policy_key='commission_short_let' and p.scope_type='global'
          and p.scope_key='*' and p.status='active'
          and p.effective_from<=now()
          and (p.effective_until is null or p.effective_until>now())
        order by p.effective_from desc limit 1;
        if v_rate is null or v_rate<0 or v_rate>50 then
          raise exception 'Active Creator Short Let commission is required';
        end if;
        v_stay_amount:=round(coalesce(v_reservation.stay_rent_total,
          (v_payment.metadata->>'stay_rent_total')::numeric,0),2);
        v_caution_amount:=round(coalesce(v_reservation.security_deposit_snapshot,
          (v_payment.metadata->>'security_deposit_amount')::numeric,0),2);
        if v_stay_amount<=0 or v_stay_amount+v_caution_amount<>v_amount then
          raise exception 'Short Let stay and Caution split does not match verified money';
        end if;
        insert into public.payment_protection_transactions(
          booking_id,booking_type,payer_user_id,payee_user_id,amount_total,
          amount_commission,amount_payee,commission_rate,status,
          paystack_reference,protection_state,subject_type,subject_id
        ) values(
          null,'short_let_stay',v_payer,v_payee,v_stay_amount,
          round(v_stay_amount*v_rate/100,2),
          v_stay_amount-round(v_stay_amount*v_rate/100,2),v_rate,
          'protected',p_provider_reference,'awaiting_funds',
          'short_let_stay',v_reservation.id
        ) on conflict(subject_type,subject_id) do update
          set paystack_reference=excluded.paystack_reference,updated_at=now()
        returning * into v_stay_protection;
        if v_caution_amount>0 then
          insert into public.payment_protection_transactions(
            booking_id,booking_type,payer_user_id,payee_user_id,amount_total,
            amount_commission,amount_payee,commission_rate,status,
            paystack_reference,protection_state,subject_type,subject_id
          ) values(
            null,'short_let_caution',v_payer,v_payee,v_caution_amount,
            0,v_caution_amount,0,'protected',p_provider_reference,
            'awaiting_funds','short_let_caution',v_reservation.id
          ) on conflict(subject_type,subject_id) do update
            set paystack_reference=excluded.paystack_reference,updated_at=now()
          returning * into v_caution_protection;
        end if;
        update public.reservations
        set stay_payment_protection_id=v_stay_protection.id,
            caution_payment_protection_id=v_caution_protection.id,
            commission_policy_version_id=v_policy_id,updated_at=now()
        where id=v_reservation.id;
      else
        select (p.value->>'percent')::numeric,p.policy_version_id
        into v_rate,v_policy_id from public.creator_policy_versions p
        where p.policy_key='commission_long_let' and p.scope_type='global'
          and p.scope_key='*' and p.status='active'
          and p.effective_from<=now()
          and (p.effective_until is null or p.effective_until>now())
        order by p.effective_from desc limit 1;
        if v_rate is null or v_rate<0 or v_rate>50 then
          raise exception 'Active Creator Long Let commission is required';
        end if;
        insert into public.payment_protection_transactions(
          booking_id,booking_type,payer_user_id,payee_user_id,amount_total,
          amount_commission,amount_payee,commission_rate,status,
          paystack_reference,protection_state,subject_type,subject_id
        ) values(
          null,'long_let_year_one',v_payer,v_payee,v_amount,
          round(v_amount*v_rate/100,2),v_amount-round(v_amount*v_rate/100,2),
          v_rate,'protected',p_provider_reference,'awaiting_funds',
          'long_let_year_one',v_reservation.id
        ) on conflict(subject_type,subject_id) do update
          set paystack_reference=excluded.paystack_reference,updated_at=now()
        returning * into v_protection;
        update public.reservations
        set year_one_rent_protection_id=v_protection.id,
            commission_policy_version_id=v_policy_id,updated_at=now()
        where id=v_reservation.id;
      end if;

    elsif v_payment.purpose='hotel_booking' then
      select * into v_hotel_booking from public.hotel_bookings
      where booking_id=v_payment.hotel_booking_id for update;
      if v_hotel_booking.booking_id is null then raise exception 'Hotel booking is missing'; end if;
      select h.owner_id into v_payee from public.hotels h
      where h.hotel_id=v_hotel_booking.hotel_id;
      if v_payee is null then raise exception 'Hotel payee is missing'; end if;
      select (p.value->>'percent')::numeric,p.policy_version_id
      into v_rate,v_policy_id from public.creator_policy_versions p
      where p.policy_key='commission_hotel' and p.scope_type='global'
        and p.scope_key='*' and p.status='active'
        and p.effective_from<=now()
        and (p.effective_until is null or p.effective_until>now())
      order by p.effective_from desc limit 1;
      if v_rate is null or v_rate<0 or v_rate>50 then
        raise exception 'Active Creator Hotel commission is required';
      end if;
      insert into public.payment_protection_transactions(
        booking_id,booking_type,payer_user_id,payee_user_id,amount_total,
        amount_commission,amount_payee,commission_rate,status,
        paystack_reference,protection_state,subject_type,subject_id
      ) values(
        null,'hotel_stay',v_payer,v_payee,v_amount,
        round(v_amount*v_rate/100,2),v_amount-round(v_amount*v_rate/100,2),
        v_rate,'protected',p_provider_reference,'awaiting_funds',
        'hotel_stay',v_hotel_booking.booking_id::text
      ) on conflict(subject_type,subject_id) do update
        set paystack_reference=excluded.paystack_reference,updated_at=now()
      returning * into v_protection;
      update public.hotel_bookings
      set payment_protection_id=v_protection.id,policy_version_id=v_policy_id,
          updated_at=now()
      where booking_id=v_hotel_booking.booking_id;

    elsif v_payment.purpose='shared_housing_share'
      and coalesce(v_payment.metadata->>'payment_phase','')<>'reservation_fee' then
      select g.* into v_group from public.shared_housing_groups g
      where g.id=(v_payment.metadata->>'shared_group_id')::uuid;
      if v_group.id is null then raise exception 'Shared payment group is missing'; end if;
      select * into v_listing from public.listings where id=v_group.listing_id;
      v_payee:=coalesce(v_listing.partner_id,v_listing.owner_id);
      if v_payee is null then raise exception 'Shared payment payee is missing'; end if;
      if v_listing.sub_type='short_let' then
        select (p.value->>'percent')::numeric,p.policy_version_id
        into v_rate,v_policy_id from public.creator_policy_versions p
        where p.policy_key='commission_short_let' and p.scope_type='global'
          and p.scope_key='*' and p.status='active'
          and p.effective_from<=now()
          and (p.effective_until is null or p.effective_until>now())
        order by p.effective_from desc limit 1;
        if v_rate is null or v_rate<0 or v_rate>50 then
          raise exception 'Active Creator Short Let commission is required';
        end if;
      else
        select (p.value->>'percent')::numeric,p.policy_version_id
        into v_rate,v_policy_id from public.creator_policy_versions p
        where p.policy_key='commission_long_let' and p.scope_type='global'
          and p.scope_key='*' and p.status='active'
          and p.effective_from<=now()
          and (p.effective_until is null or p.effective_until>now())
        order by p.effective_from desc limit 1;
        if v_rate is null or v_rate<0 or v_rate>50 then
          raise exception 'Active Creator Long Let commission is required';
        end if;
      end if;
      insert into public.payment_protection_transactions(
        booking_id,booking_type,payer_user_id,payee_user_id,amount_total,
        amount_commission,amount_payee,commission_rate,status,
        paystack_reference,protection_state,subject_type,subject_id
      ) values(
        null,'shared_housing_share',v_payer,v_payee,v_amount,
        round(v_amount*v_rate/100,2),v_amount-round(v_amount*v_rate/100,2),
        v_rate,'protected',p_provider_reference,'awaiting_funds',
        'shared_housing_share',v_payment.metadata->>'shared_member_id'
      ) on conflict(subject_type,subject_id) do update
        set paystack_reference=excluded.paystack_reference,updated_at=now()
      returning * into v_protection;
    end if;

    v_entries:=jsonb_build_array(jsonb_build_object(
      'account_key','asset:paystack_clearing:NGN','account_class','asset',
      'amount',v_amount,'memo','Paystack verified charge'
    ));
    for v_protection in
      select p.* from public.payment_protection_transactions p
      where p.paystack_reference=p_provider_reference
        and p.subject_type in(
          'worker_booking','long_let_year_one','short_let_stay',
          'short_let_caution','hotel_stay','shared_housing_share'
        )
      order by p.subject_type,p.id
    loop
      v_entries:=v_entries||jsonb_build_array(jsonb_build_object(
        'account_key','liability:payment_protection:'||v_protection.id::text,
        'account_class','liability','owner_type',v_protection.subject_type,
        'owner_id',v_protection.subject_id,'amount',-v_protection.amount_total,
        'memo','Protected customer funds'
      ));
      v_liability_total:=v_liability_total+v_protection.amount_total;
    end loop;
    if v_liability_total>v_amount then
      raise exception 'Payment Protection allocation exceeds verified money';
    end if;
    if v_liability_total<v_amount then
      v_entries:=v_entries||jsonb_build_array(jsonb_build_object(
        'account_key',case
          when v_payment.purpose='apartment_reservation'
            or (v_payment.purpose='shared_housing_share'
              and v_payment.metadata->>'payment_phase'='reservation_fee')
            then 'liability:unearned_reservation_fee:'||v_payment.id::text
          when v_payment.purpose='rent_plan_contribution'
            then 'liability:partner_payable:'||coalesce(v_payee,'unresolved')
          else 'liability:customer_funds:'||v_payment.id::text end,
        'account_class','liability','owner_type','booking_payment',
        'owner_id',v_payment.id::text,'amount',-(v_amount-v_liability_total),
        'memo','Unreleased customer funds'
      ));
    end if;

    v_ledger_transaction_id:=public.post_ledger_transaction(
      'paystack-charge:'||p_provider_reference,'provider_charge','NGN',
      'booking_payment',v_payment.id::text,v_event.provider_event_id,
      jsonb_build_object(
        'provider','paystack','provider_reference',p_provider_reference,
        'purpose',v_payment.purpose,'payer_user_id',v_payer
      ),v_entries
    );

    for v_protection in
      select p.* from public.payment_protection_transactions p
      where p.paystack_reference=p_provider_reference
        and p.subject_type in(
          'worker_booking','long_let_year_one','short_let_stay',
          'short_let_caution','hotel_stay','shared_housing_share'
        )
      order by p.subject_type,p.id
    loop
      update public.payment_protection_transactions
      set protected_ledger_transaction_id=v_ledger_transaction_id,updated_at=now()
      where id=v_protection.id;
      if v_protection.protection_state='awaiting_funds' then
        perform public.transition_payment_protection(
          v_protection.id,'protected','provider_charge_verified',
          'paystack-protected:'||p_provider_reference||':'||v_protection.id::text,
          null,'paystack',null,v_ledger_transaction_id,
          jsonb_build_object('provider_event_id',v_event.provider_event_id)
        );
      elsif v_protection.protection_state<>'protected' then
        raise exception 'Existing Payment Protection is not awaiting funds';
      end if;
    end loop;

    update public.verified_provider_events
    set processing_status='processed',processed_at=now(),processing_error=null
    where provider_event_id=v_event.provider_event_id;
    return jsonb_build_object(
      'success',true,'provider_event_id',v_event.provider_event_id,
      'ledger_transaction_id',v_ledger_transaction_id,
      'lifecycle_result',v_result
    );
  exception when others then
    get stacked diagnostics v_error=message_text;
    update public.verified_provider_events
    set processing_status='failed',processed_at=now(),
        processing_error=left(v_error,500)
    where provider_event_id=v_event.provider_event_id;
    return jsonb_build_object('success',false,'error','Verified payment requires retry or Finance review');
  end;
end
$_$;


--
-- Name: process_verified_paystack_refund_event(text, text, text, text, text, text, timestamp with time zone, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_verified_paystack_refund_event(p_provider_event_key text, p_event_type text, p_original_reference text, p_refund_reference text, p_provider_refund_id text, p_payload_sha256 text, p_signature_verified_at timestamp with time zone, p_amount_minor bigint, p_currency text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_event public.verified_provider_events;
  v_action public.financial_action_outbox;
  v_protection public.payment_protection_transactions;
  v_amount numeric(12,2);
  v_match_count integer;
  v_ledger uuid;
  v_new_released numeric(12,2);
  v_new_refunded numeric(12,2);
  v_to_state text;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  if p_event_type not in(
    'refund.pending','refund.processing','refund.needs-attention',
    'refund.failed','refund.processed'
  ) or nullif(btrim(p_provider_event_key),'') is null
    or nullif(btrim(p_original_reference),'') is null
    or p_payload_sha256 !~ '^[0-9a-f]{64}$'
    or p_amount_minor<=0 or upper(p_currency)<>'NGN' then
    raise exception 'Invalid verified Paystack refund event'; end if;
  v_amount:=round(p_amount_minor::numeric/100,2);
  insert into public.verified_provider_events(
    provider,provider_event_key,event_type,provider_reference,payload_sha256,
    signature_verified_at,processing_status
  ) values(
    'paystack',p_provider_event_key,p_event_type,
    coalesce(nullif(btrim(p_refund_reference),''),p_provider_event_key),
    lower(p_payload_sha256),p_signature_verified_at,'received'
  ) on conflict do nothing;
  select * into v_event from public.verified_provider_events
  where provider='paystack' and provider_event_key=p_provider_event_key for update;
  if v_event.provider_event_id is null then raise exception 'Refund event was not registered'; end if;
  if v_event.payload_sha256<>lower(p_payload_sha256) then
    raise exception 'Refund event replay checksum mismatch'; end if;
  if v_event.processing_status='processed' then
    return jsonb_build_object('success',true,'already_processed',true); end if;

  select count(*) into v_match_count
  from public.financial_action_outbox a
  join public.payment_protection_transactions p on p.id=a.payment_protection_id
  where a.action_type like 'refund_%'
    and a.status in('provider_pending','provider_attention')
    and p.paystack_reference=p_original_reference
    and a.amount=v_amount
    and (nullif(btrim(p_provider_refund_id),'') is null
      or a.provider_action_id is null
      or a.provider_action_id=p_provider_refund_id);
  if v_match_count=0 then
    update public.verified_provider_events set processing_status='ignored',
      processed_at=now(),processing_error='No matching pending refund action'
    where provider_event_id=v_event.provider_event_id;
    return jsonb_build_object('success',true,'ignored',true);
  end if;
  if v_match_count<>1 then
    update public.verified_provider_events set processing_status='failed',
      processed_at=now(),processing_error='Refund event matched multiple actions'
    where provider_event_id=v_event.provider_event_id;
    return jsonb_build_object('success',false,'error','Refund matching requires Finance review');
  end if;
  select a.* into v_action
  from public.financial_action_outbox a
  join public.payment_protection_transactions p on p.id=a.payment_protection_id
  where a.action_type like 'refund_%'
    and a.status in('provider_pending','provider_attention')
    and p.paystack_reference=p_original_reference and a.amount=v_amount
    and (nullif(btrim(p_provider_refund_id),'') is null
      or a.provider_action_id is null or a.provider_action_id=p_provider_refund_id)
  for update of a;
  update public.financial_action_outbox set
    provider_action_id=coalesce(provider_action_id,nullif(btrim(p_provider_refund_id),'')),
    provider_status=replace(p_event_type,'refund.',''),updated_at=now()
  where financial_action_id=v_action.financial_action_id;

  if p_event_type='refund.needs-attention' then
    update public.financial_action_outbox set status='provider_attention'
    where financial_action_id=v_action.financial_action_id;
  elsif p_event_type='refund.failed' then
    update public.financial_action_outbox set status='manual_review',
      last_error='Paystack reported that the refund failed',updated_at=now()
    where financial_action_id=v_action.financial_action_id;
  elsif p_event_type='refund.processed' then
    select * into v_protection from public.payment_protection_transactions
    where id=v_action.payment_protection_id for update;
    if v_action.amount>
        v_protection.amount_total-v_protection.released_amount-v_protection.refunded_amount then
      raise exception 'Refund exceeds the protected balance'; end if;
    v_ledger:=public.post_ledger_transaction(
      'paystack-refund:'||p_provider_event_key,'provider_refund','NGN',
      v_action.subject_type,v_action.subject_id,v_event.provider_event_id,
      jsonb_build_object(
        'financial_action_id',v_action.financial_action_id,
        'original_reference',p_original_reference,
        'refund_reference',p_refund_reference
      ),jsonb_build_array(
        jsonb_build_object(
          'account_key','liability:payment_protection:'||v_protection.id::text,
          'account_class','liability','owner_type',v_protection.subject_type,
          'owner_id',v_protection.subject_id,'amount',v_action.amount,
          'memo','Original-payment refund'
        ),
        jsonb_build_object(
          'account_key','asset:paystack_clearing:NGN','account_class','asset',
          'amount',-v_action.amount,'memo','Paystack processed refund'
        )
      )
    );
    update public.payment_protection_transactions set
      refunded_amount=refunded_amount+v_action.amount,
      refund_ledger_transaction_id=v_ledger,updated_at=now()
    where id=v_protection.id
    returning released_amount,refunded_amount into v_new_released,v_new_refunded;
    v_to_state:=case
      when v_new_refunded=v_protection.amount_total then 'refunded'
      else 'partially_released' end;
    perform public.transition_payment_protection(
      v_protection.id,v_to_state,'provider_refund_processed',
      'provider-refund-processed:'||p_provider_event_key,
      null,'paystack',null,v_ledger,
      jsonb_build_object('financial_action_id',v_action.financial_action_id)
    );
    update public.financial_action_outbox set status='completed',processed_at=now(),
      last_error=null,updated_at=now()
    where financial_action_id=v_action.financial_action_id;
  end if;
  update public.verified_provider_events set processing_status='processed',
    processed_at=now(),processing_error=null
  where provider_event_id=v_event.provider_event_id;
  return jsonb_build_object('success',true,'financial_action_id',v_action.financial_action_id);
end
$_$;


--
-- Name: project_completed_release_to_wallet(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_completed_release_to_wallet() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_protection public.payment_protection_transactions;
  v_ledger public.ledger_transactions;
  v_wallet public.wallets;
  v_wallet_type text;
  v_payee_amount numeric(12,2);
  v_commission numeric(12,2);
  v_balance numeric(12,2);
  v_wallet_tx uuid;
  v_payment public.booking_payments;
begin
  if new.status<>'completed' or old.status='completed'
    or new.action_type not like 'release_%' then return new; end if;
  if (select auth.role())<>'service_role' then
    raise exception 'Canonical wallet projection requires service role';
  end if;
  if exists(select 1 from public.canonical_wallet_release_receipts
    where financial_action_id=new.financial_action_id) then return new; end if;
  select * into v_protection from public.payment_protection_transactions
  where id=new.payment_protection_id for share;
  if v_protection.id is null then raise exception 'Release protection is missing'; end if;
  select * into v_ledger from public.ledger_transactions
  where idempotency_key='financial-action:'||new.idempotency_key;
  if v_ledger.ledger_transaction_id is null then
    raise exception 'Canonical release ledger transaction is missing';
  end if;
  v_payee_amount:=round(coalesce((v_ledger.metadata->>'payee_amount')::numeric,0),2);
  v_commission:=round(coalesce((v_ledger.metadata->>'commission')::numeric,0),2);
  if v_payee_amount<0 or v_commission<0 or v_payee_amount+v_commission<>new.amount then
    raise exception 'Canonical release split is invalid';
  end if;
  v_wallet_type:=case when v_protection.subject_type='worker_booking'
    then 'worker' else 'property_partner' end;
  insert into public.wallets(
    owner_id,owner_type,available_balance,pending_balance,frozen_balance,total_withdrawn
  ) values(v_protection.payee_user_id,v_wallet_type,0,0,0,0)
  on conflict(owner_id,owner_type) do nothing;
  select * into v_wallet from public.wallets
  where owner_id=v_protection.payee_user_id and owner_type=v_wallet_type for update;
  update public.wallets set available_balance=coalesce(available_balance,0)+v_payee_amount,
    updated_at=now() where id=v_wallet.id returning available_balance into v_balance;
  insert into public.wallet_transactions(
    user_id,transaction_type,amount,balance_after,reference_id,reference_type,
    description,metadata,created_at
  ) values(
    v_protection.payee_user_id,'canonical_protected_release',v_payee_amount,v_balance,
    new.financial_action_id::text,'financial_action',
    'Available earnings from a completed Payment Protection release',
    jsonb_build_object('wallet_bucket','available','payment_protection_id',v_protection.id,
      'ledger_transaction_id',v_ledger.ledger_transaction_id,
      'commission_amount',v_commission),now()
  ) returning id into v_wallet_tx;
  insert into public.canonical_wallet_release_receipts(
    financial_action_id,payment_protection_id,ledger_transaction_id,payee_user_id,
    wallet_id,wallet_transaction_id,payee_amount,commission_amount
  ) values(new.financial_action_id,v_protection.id,v_ledger.ledger_transaction_id,
    v_protection.payee_user_id,v_wallet.id,v_wallet_tx,v_payee_amount,v_commission);

  select * into v_payment from public.booking_payments
  where paystack_reference=v_protection.paystack_reference order by created_at desc limit 1;
  if v_payment.id is not null then
    update public.booking_payments set payee_user_id=v_protection.payee_user_id,
      commission_rate=v_protection.commission_rate,
      amount_commission=coalesce(amount_commission,0)+v_commission,
      net_amount=coalesce(net_amount,0)+v_payee_amount,updated_at=now()
    where id=v_payment.id;
    if v_commission>0 then
      insert into public.commission_ledger(
        payment_id,booking_type,source_user_id,commission_amount,commission_rate,
        gross_amount,description,paystack_reference,status,created_at,updated_at
      ) values(
        v_payment.id,
        case
          when v_protection.subject_type='worker_booking' then 'worker'
          when v_protection.subject_type='hotel_stay' then 'hotel'
          else 'apartment' end,
        v_protection.payee_user_id,v_commission,v_protection.commission_rate,
        new.amount,'Commission recognized by canonical Payment Protection release',
        v_protection.paystack_reference,'collected',now(),now()
      ) on conflict(paystack_reference) where paystack_reference is not null
      do update set
        commission_amount=public.commission_ledger.commission_amount+excluded.commission_amount,
        gross_amount=public.commission_ledger.gross_amount+excluded.gross_amount,
        updated_at=now();
    end if;
    if v_wallet_type='property_partner' and v_payee_amount>0 then
      insert into public.property_partner_earning_releases(
        payment_id,partner_id,earning_type,status,net_amount,release_event,
        released_by,released_at,created_at,updated_at
      ) values(
        v_payment.id,v_protection.payee_user_id,
        case
          when v_protection.subject_type='hotel_stay' then 'hotel_payment'
          when v_protection.subject_type='short_let_stay' then 'short_stay_rent'
          when v_protection.subject_type='long_let_year_one' then 'long_stay_rent'
          else 'long_stay_rent' end,
        'available',v_payee_amount,'canonical_payment_protection_release',
        'finance_processor',now(),now(),now()
      ) on conflict(payment_id) do update set
        status='available',
        net_amount=public.property_partner_earning_releases.net_amount+excluded.net_amount,
        release_event=excluded.release_event,released_by=excluded.released_by,
        released_at=excluded.released_at,updated_at=now();
    end if;
  end if;
  return new;
end
$$;


--
-- Name: protect_privileged_profile_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_privileged_profile_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF current_user IN ('anon','authenticated') AND OLD.auth_id = auth.uid()::text THEN
    IF NEW.id IS DISTINCT FROM OLD.id
      OR NEW.auth_id IS DISTINCT FROM OLD.auth_id
      OR NEW.user_id IS DISTINCT FROM OLD.user_id
      OR NEW.email IS DISTINCT FROM OLD.email
      OR NEW.role IS DISTINCT FROM OLD.role
      OR NEW.created_at IS DISTINCT FROM OLD.created_at
      OR NEW.email_verified IS DISTINCT FROM OLD.email_verified
      OR NEW.phone_verified IS DISTINCT FROM OLD.phone_verified
      OR NEW.id_verified IS DISTINCT FROM OLD.id_verified
      OR NEW.assigned_state IS DISTINCT FROM OLD.assigned_state
      OR NEW.assigned_lga IS DISTINCT FROM OLD.assigned_lga
      OR NEW.scope IS DISTINCT FROM OLD.scope
      OR NEW.created_by IS DISTINCT FROM OLD.created_by
      OR NEW.updated_by IS DISTINCT FROM OLD.updated_by
      OR NEW.maintenance_exempt IS DISTINCT FROM OLD.maintenance_exempt
      OR NEW.is_premium IS DISTINCT FROM OLD.is_premium
      OR NEW.premium_expires_at IS DISTINCT FROM OLD.premium_expires_at
      OR NEW.worker_verified IS DISTINCT FROM OLD.worker_verified
      OR NEW.worker_status IS DISTINCT FROM OLD.worker_status
      OR NEW.deleted IS DISTINCT FROM OLD.deleted
      OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
      OR NEW.suspended IS DISTINCT FROM OLD.suspended
      OR NEW.suspended_at IS DISTINCT FROM OLD.suspended_at
      OR NEW.suspended_by IS DISTINCT FROM OLD.suspended_by
      OR NEW.suspended_reason IS DISTINCT FROM OLD.suspended_reason
      OR NEW.banned IS DISTINCT FROM OLD.banned
      OR NEW.banned_at IS DISTINCT FROM OLD.banned_at
      OR NEW.banned_by IS DISTINCT FROM OLD.banned_by
      OR NEW.banned_reason IS DISTINCT FROM OLD.banned_reason
      OR NEW.rating IS DISTINCT FROM OLD.rating
      OR NEW.review_count IS DISTINCT FROM OLD.review_count
      OR NEW.creator_auth_password IS DISTINCT FROM OLD.creator_auth_password
      OR NEW.creator_auth_enabled IS DISTINCT FROM OLD.creator_auth_enabled
      OR NEW.terms_accepted_at IS DISTINCT FROM OLD.terms_accepted_at
      OR NEW.privacy_accepted_at IS DISTINCT FROM OLD.privacy_accepted_at
      OR NEW.legal_accepted_version IS DISTINCT FROM OLD.legal_accepted_version
    THEN
      RAISE EXCEPTION 'This field cannot be changed from Profile.';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prune_my_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_my_activity() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_recipient text := public.current_profile_user_id();
  v_deleted integer := 0;
  v_step integer := 0;
begin
  if v_recipient is null then raise exception 'Authenticated profile required'; end if;

  delete from public.notifications n
  where n.recipient_id = v_recipient
    and (
      (n.type ~* '(^|_)(message|reply|replied|chat)(_|$)'
        and ((n.read and n.created_at < now() - interval '1 day') or n.created_at < now() - interval '30 days'))
      or (n.type ~* '(action_required|payment_conflict|dispute|changes_requested|escalat|verification_required|refund_due|failed)'
        and n.created_at < now() - interval '180 days')
      or (n.type !~* '(action_required|payment_conflict|dispute|changes_requested|escalat|verification_required|refund_due|failed)'
        and n.type ~* '(payment|payout|earning|refund)'
        and ((n.read and n.created_at < now() - interval '90 days') or n.created_at < now() - interval '180 days'))
      or (n.type !~* '(action_required|payment_conflict|dispute|changes_requested|escalat|verification_required|refund_due|failed)'
        and n.type ~* '(roommate|match|invite|interest)'
        and ((n.read and n.created_at < now() - interval '14 days') or n.created_at < now() - interval '30 days'))
      or (n.type !~* '(action_required|payment_conflict|dispute|changes_requested|escalat|verification_required|refund_due|failed)'
        and n.type ~* '(booking|reservation|inspection|visit|listing|property|hotel|job|worker)'
        and ((n.read and n.created_at < now() - interval '30 days') or n.created_at < now() - interval '90 days'))
      or (n.type !~* '(action_required|payment_conflict|dispute|changes_requested|escalat|verification_required|refund_due|failed)'
        and n.type ~* '(verification|password|security)'
        and ((n.read and n.created_at < now() - interval '30 days') or n.created_at < now() - interval '90 days'))
      or (n.type !~* '(action_required|payment_conflict|dispute|changes_requested|escalat|verification_required|refund_due|failed|payment|payout|earning|refund|roommate|match|invite|interest|booking|reservation|inspection|visit|listing|property|hotel|job|worker|verification|password|security|message|reply|replied|chat)'
        and ((n.read and n.created_at < now() - interval '14 days') or n.created_at < now() - interval '30 days'))
    );
  get diagnostics v_deleted = row_count;

  delete from public.notifications older
  using public.notifications newer
  where older.recipient_id = v_recipient
    and newer.recipient_id = older.recipient_id
    and nullif(older.source_type, '') is not null
    and nullif(older.source_id, '') is not null
    and newer.source_type = older.source_type
    and newer.source_id = older.source_id
    and (newer.created_at, newer.id) > (older.created_at, older.id)
    and older.type !~* '(action_required|payment_conflict|dispute|changes_requested|escalat|verification_required|refund_due|failed)'
    and older.type ~* '(payment|payout|earning|refund|roommate|match|invite|interest|booking|reservation|inspection|visit|listing|property|hotel|job|worker|verification|status)'
    and (case
      when older.type ~* '(payment|payout|earning|refund|dispute)' then 'finance'
      when older.type ~* '(inspection|visit|access_evidence)' then 'inspection'
      when older.type ~* 'hotel' then 'hotel'
      when older.type ~* '(reservation|booking|tenancy|move_in|handover|property|listing)' then 'housing'
      when older.type ~* '(worker|job|service)' then 'worker'
      when older.type ~* '(roommate|match|invite|interest)' then 'roommate'
      when older.type ~* '(verification|password|security)' then 'account'
      else 'general' end)
      = (case
      when newer.type ~* '(payment|payout|earning|refund|dispute)' then 'finance'
      when newer.type ~* '(inspection|visit|access_evidence)' then 'inspection'
      when newer.type ~* 'hotel' then 'hotel'
      when newer.type ~* '(reservation|booking|tenancy|move_in|handover|property|listing)' then 'housing'
      when newer.type ~* '(worker|job|service)' then 'worker'
      when newer.type ~* '(roommate|match|invite|interest)' then 'roommate'
      when newer.type ~* '(verification|password|security)' then 'account'
      else 'general' end);
  get diagnostics v_step = row_count;
  return v_deleted + v_step;
end;
$_$;


--
-- Name: queue_hotel_booking_for_pms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_hotel_booking_for_pms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_integration uuid;
begin
  if new.payment_status='paid'
    and new.status in ('confirmed','checked_in','checked_out','completed') then
    select i.integration_id into v_integration
    from public.hotel_integrations i
    where i.hotel_id=new.hotel_id and i.status='active'
      and 'reservations.read'=any(i.scopes)
    order by i.created_at limit 1;
    if v_integration is not null then
      new.integration_id:=coalesce(new.integration_id,v_integration);
      if new.pms_external_reservation_id is null then
        new.pms_sync_status:='pending';
      end if;
    end if;
  end if;
  return new;
end
$$;


--
-- Name: queue_paid_hotel_booking_for_pms(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_paid_hotel_booking_for_pms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_integration public.hotel_integrations; v_event_id uuid;
begin
  if new.payment_status<>'paid' or new.status<>'confirmed'
     or (old.payment_status='paid' and old.status='confirmed') then
    return new;
  end if;
  select integration.* into v_integration
  from public.hotel_integrations integration
  where integration.hotel_id=new.hotel_id
    and 'reservations.receive'=any(integration.scopes)
    and public.hotel_integration_runtime_active(integration.integration_id)
  order by integration.activated_at desc,integration.integration_id
  limit 1;
  if v_integration.integration_id is null then return new; end if;
  v_event_id:=public._queue_hotel_pms_event(
    v_integration.integration_id,
    'hotel-booking:'||new.booking_id||':paid-confirmed:v1',
    'reservation.paid_confirmed',new.booking_id::text,
    jsonb_build_object(
      'booking_id',new.booking_id,'hotel_id',new.hotel_id,'room_id',new.room_id,
      'rate_plan_id',new.rate_plan_id,'check_in',new.check_in,
      'check_out',new.check_out,'guest_count',new.guest_count,
      'guest_name',new.guest_name,'guest_phone',new.guest_phone,
      'total_price',new.total_price,'booking_status',new.status,
      'payment_status',new.payment_status
    )
  );
  update public.hotel_bookings set
    integration_id=v_integration.integration_id,pms_sync_status='pending',
    pms_last_synced_at=null,updated_at=now()
  where booking_id=new.booking_id;
  return new;
end;
$$;


--
-- Name: quote_hotel_room(integer, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quote_hotel_room(p_hotel_id integer, p_room_id integer, p_check_in date, p_check_out date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_quote jsonb;
begin
  if p_check_in is null or p_check_out is null
     or p_check_in <= current_date or p_check_out <= p_check_in then
    raise exception 'Choose valid future check-in and check-out dates';
  end if;
  if not exists (
    select 1 from public.hotels h
    join public.hotel_rooms r on r.hotel_id = h.hotel_id
    where h.hotel_id = p_hotel_id and r.room_id = p_room_id
      and h.status = 'active' and h.approved_at is not null and h.published_at is not null
  ) then
    raise exception 'Hotel room is not available';
  end if;
  v_quote := private.hotel_booking_quote(p_room_id, p_check_in, p_check_out, null, true);
  return v_quote;
end;
$$;


--
-- Name: quote_hotel_room_rate(integer, integer, integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quote_hotel_room_rate(p_hotel_id integer, p_room_id integer, p_rate_plan_id integer, p_check_in date, p_check_out date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
begin
  if p_check_in is null or p_check_out is null or p_check_in <= current_date or p_check_out <= p_check_in then
    raise exception 'Choose valid future check-in and check-out dates';
  end if;
  if not exists (
    select 1 from public.hotels h
    join public.hotel_rooms r on r.hotel_id=h.hotel_id
    join public.hotel_rate_plans rp on rp.room_id=r.room_id and rp.hotel_id=h.hotel_id
    where h.hotel_id=p_hotel_id and r.room_id=p_room_id and rp.rate_plan_id=p_rate_plan_id
      and rp.active and h.status='active' and h.approved_at is not null and h.published_at is not null
  ) then raise exception 'Hotel room package is not available'; end if;
  return private.hotel_booking_quote_v2(p_room_id,p_rate_plan_id,p_check_in,p_check_out,null,true);
end;
$$;


--
-- Name: reauthenticate_creator_action(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reauthenticate_creator_action(p_creator_elevation_id uuid, p_action_class text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.creator_has_elevation(
    p_creator_elevation_id,p_action_class
  ) then
    raise exception 'Recent Creator authentication required';
  end if;
  return true;
end
$$;


--
-- Name: record_bank_account_change(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_bank_account_change(p_user_id text, p_bank_name text, p_bank_code text, p_bank_account_number text, p_bank_account_name text, p_verified_account_name text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_changed_by TEXT;
  v_changed_by_role TEXT;
BEGIN
  -- ── AUTH ──
  SELECT user_id, role INTO v_changed_by, v_changed_by_role
  FROM profiles WHERE auth_id = auth.uid()::text;

  -- Self or staff only
  IF v_changed_by != p_user_id AND v_changed_by_role NOT IN ('staff','admin','creator') THEN
    RETURN FALSE;
  END IF;

  -- ── This function ONLY inserts into bank_account_history ──
  -- It does NOT modify wallets, withdrawals, or withdrawal_requests.
  -- Changing the bank account on a pending withdrawal requires
  -- a separate workflow (cancel + re-create, or admin override).

  INSERT INTO bank_account_history (
    user_id, bank_name, bank_code, bank_account_number,
    bank_account_name, verified_account_name,
    is_verified, changed_by
  ) VALUES (
    p_user_id, p_bank_name, p_bank_code, p_bank_account_number,
    p_bank_account_name, p_verified_account_name,
    p_verified_account_name IS NOT NULL, v_changed_by
  );

  INSERT INTO financial_audit_logs (
    event_type, user_id, reference_id, reference_type, description
  ) VALUES (
    'bank_account_change', p_user_id, p_user_id, 'profile',
    'Bank changed to: ' || p_bank_name || ' / ' || p_bank_account_number
  );

  RETURN TRUE;
END;
$$;


--
-- Name: record_caution_property_finding(uuid, numeric, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_caution_property_finding(p_caution_claim_id uuid, p_supported_amount numeric, p_finding text, p_evidence_paths text[] DEFAULT '{}'::text[]) RETURNS public.caution_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_claim public.caution_claims;
  v_state text;
  v_path text;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  select c.* into v_claim
  from public.caution_claims c
  join public.reservations r on r.id=c.reservation_id
  join public.listings l on l.listing_id=r.listing_id or l.id::text=r.listing_id
  where c.caution_claim_id=p_caution_claim_id for update of c;
  if v_claim.caution_claim_id is null then raise exception 'Caution claim not found'; end if;
  select listing.state into v_state
  from public.reservations reservation
  join public.listings listing
    on listing.listing_id=reservation.listing_id
    or listing.id::text=reservation.listing_id
  where reservation.id=v_claim.reservation_id
  limit 1;
  if not (
    v_actor.role='creator'
    or (v_actor.role='admin' and lower(btrim(v_actor.assigned_state))=lower(btrim(v_state)))
    or public.current_actor_has_workspace('property_operations',v_state)
  ) then raise exception 'Property Operations access required'; end if;
  if v_claim.status<>'facts_review' then raise exception 'Claim is not in facts review'; end if;
  if p_supported_amount<0 or p_supported_amount>v_claim.claimed_amount then
    raise exception 'Supported amount must remain within the Partner claim'; end if;
  foreach v_path in array coalesce(p_evidence_paths,'{}'::text[]) loop
    insert into public.caution_evidence(
      reservation_id,caution_claim_id,submitted_by,evidence_type,object_path,description
    ) values(v_claim.reservation_id,v_claim.caution_claim_id,v_actor.user_id,
      'operations_finding',v_path,btrim(p_finding));
  end loop;
  update public.caution_claims set
    disputed_amount=p_supported_amount,
    property_facts_reviewed_by=v_actor.user_id,property_facts_reviewed_at=now(),
    status='finance_review',updated_at=now()
  where caution_claim_id=p_caution_claim_id returning * into v_claim;
  return v_claim;
end
$$;


--
-- Name: record_my_featured_booking_request(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_my_featured_booking_request(p_placement_id uuid, p_booking_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_booking public.worker_bookings;
  v_placement public.worker_featured_placements;
begin
  if v_actor is null then raise exception 'Active signed-in account required'; end if;
  select * into v_booking from public.worker_bookings
  where id=p_booking_id and user_id=v_actor limit 1;
  select * into v_placement from public.worker_featured_placements
  where id=p_placement_id and viewer_id=v_actor limit 1;
  if v_booking.id is null or v_placement.id is null
     or v_booking.worker_id<>v_placement.worker_id then
    raise exception 'Featured booking does not match this placement';
  end if;
  update public.worker_featured_placements
  set booking_id=p_booking_id,updated_at=now()
  where id=p_placement_id and booking_id is null;
  return found;
end;
$$;


--
-- Name: record_my_featured_profile_open(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_my_featured_profile_open(p_placement_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id();
begin
  if v_actor is null then raise exception 'Active signed-in account required'; end if;
  update public.worker_featured_placements
  set profile_opened_at=coalesce(profile_opened_at,now()),updated_at=now()
  where id=p_placement_id and viewer_id=v_actor;
  return found;
end;
$$;


--
-- Name: record_my_user_activity(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_my_user_activity(p_action_type text, p_details jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_auth_id uuid := auth.uid();
  v_user_id text;
  v_activity_id uuid := gen_random_uuid();
begin
  if v_auth_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if p_action_type not in ('session_start', 'session_end', 'password_change') then
    raise exception 'Unsupported activity type' using errcode = '22023';
  end if;

  select profile.user_id
    into v_user_id
  from public.profiles as profile
  where profile.auth_id = v_auth_id::text
    and coalesce(profile.deleted, false) = false
  limit 1;

  if v_user_id is null then
    raise exception 'Active profile not found' using errcode = '42501';
  end if;

  insert into public.user_activity (id, user_id, auth_id, action_type, details)
  values (
    v_activity_id,
    v_user_id,
    v_auth_id::text,
    p_action_type,
    coalesce(p_details, '{}'::jsonb)
  );

  return v_activity_id;
end;
$$;


--
-- Name: record_refund_provider_submission(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_refund_provider_submission(p_financial_action_id uuid, p_provider_action_id text, p_provider_status text, p_response_checksum text) RETURNS public.financial_action_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare v_action public.financial_action_outbox; v_next text;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  if p_provider_status not in('pending','processing','needs-attention') then
    raise exception 'Unexpected Paystack refund status'; end if;
  if p_response_checksum !~ '^[0-9a-f]{64}$' then raise exception 'Invalid response checksum'; end if;
  v_next:=case when p_provider_status='needs-attention'
    then 'provider_attention' else 'provider_pending' end;
  update public.financial_action_outbox set
    provider_action_id=nullif(btrim(p_provider_action_id),''),
    provider_status=p_provider_status,
    provider_response_checksum=lower(p_response_checksum),
    provider_submitted_at=now(),reconciliation_due_at=now()+interval '1 hour',
    status=v_next,updated_at=now()
  where financial_action_id=p_financial_action_id
    and status='processing' and action_type like 'refund_%'
  returning * into v_action;
  if v_action.financial_action_id is null then raise exception 'Refund action is not processing'; end if;
  return v_action;
end
$_$;


--
-- Name: record_withdrawal_transfer_response(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_withdrawal_transfer_response(p_withdrawal_id uuid, p_transfer_code text, p_paystack_status text, p_response jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then raise exception 'Service role required'; end if;
  update public.withdrawals set
    paystack_transfer_code=coalesce(nullif(btrim(coalesce(p_transfer_code,'')),''),paystack_transfer_code),
    paystack_status=case
      when status in ('paid','failed','reversed') then paystack_status
      else nullif(lower(btrim(coalesce(p_paystack_status,''))),'')
    end,
    transfer_response=case
      when status in ('paid','failed','reversed') then transfer_response
      else coalesce(p_response,'{}'::jsonb)
    end,
    updated_at=now()
  where id=p_withdrawal_id and status in ('processing','paid','failed','reversed');
  if not found then raise exception 'Withdrawal transfer record not found'; end if;
  return true;
end;
$$;


--
-- Name: record_worker_pro_subscription_event(text, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, boolean, boolean, numeric, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_worker_pro_subscription_event(p_worker_id text, p_provider text, p_product_id text, p_provider_subscription_id text, p_provider_event_id text, p_event_type text, p_status text, p_event_time timestamp with time zone, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_cancel_at_period_end boolean, p_auto_renews boolean, p_price_amount numeric, p_currency text, p_environment text, p_payload_sha256 text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_subscription public.worker_pro_subscriptions;
  v_event_id uuid;
  v_billing_period text;
  v_locked_worker_id text;
begin
  if p_provider not in('apple','google','paystack') then raise exception 'Unsupported subscription provider'; end if;
  if p_status not in('pending','active','grace_period','paused','cancelled','expired','revoked') then raise exception 'Unsupported subscription status'; end if;
  if p_environment not in('sandbox','production') then raise exception 'Unsupported subscription environment'; end if;
  if nullif(btrim(coalesce(p_worker_id,'')),'') is null
     or nullif(btrim(coalesce(p_product_id,'')),'') is null
     or nullif(btrim(coalesce(p_provider_event_id,'')),'') is null
     or nullif(btrim(coalesce(p_event_type,'')),'') is null then
    raise exception 'Complete provider event identity is required';
  end if;
  if p_payload_sha256 !~ '^[a-f0-9]{64}$' then raise exception 'A lowercase SHA-256 payload hash is required'; end if;
  if p_price_amount<0 or upper(coalesce(p_currency,'')) !~ '^[A-Z]{3}$' then raise exception 'Invalid subscription price'; end if;
  if p_period_end is not null and p_period_start is not null and p_period_end<=p_period_start then raise exception 'Invalid subscription period'; end if;
  if p_status in('active','grace_period') and (p_period_end is null or p_period_end<=p_event_time) then raise exception 'An active entitlement requires a future period end'; end if;

  -- Serialize every provider event for this Worker, including the first event.
  -- Without this profile-row lock, two first-time provider callbacks could both
  -- observe no subscription and the later upsert could replace the winner.
  select profile.user_id into v_locked_worker_id
  from public.profiles profile
  where profile.user_id=p_worker_id
  for update;
  if v_locked_worker_id is null then raise exception 'Worker account was not found'; end if;

  insert into public.worker_pro_subscription_events(
    worker_id,provider,provider_event_id,event_type,event_time,valid_until,
    payload_sha256,result,metadata
  ) values(
    p_worker_id,p_provider,btrim(p_provider_event_id),btrim(p_event_type),p_event_time,
    p_period_end,p_payload_sha256,'accepted',coalesce(p_metadata,'{}'::jsonb)
  ) on conflict(provider,provider_event_id) do nothing
  returning id into v_event_id;

  select * into v_subscription
  from public.worker_pro_subscriptions
  where worker_id=p_worker_id
  for update;

  if v_event_id is null then
    return jsonb_build_object(
      'success',true,'duplicate',true,'subscription_id',v_subscription.id,
      'status',v_subscription.status
    );
  end if;

  -- A later event from another provider must never silently replace a paid
  -- entitlement. Record the conflict for support/refund handling and leave the
  -- existing provider authoritative until it ends.
  if v_subscription.id is not null
     and v_subscription.provider<>p_provider
     and v_subscription.status in('active','grace_period')
     and v_subscription.current_period_end>now() then
    update public.worker_pro_subscription_events
    set subscription_id=v_subscription.id,
        result='conflict',
        metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
          'conflict_reason','active_subscription_on_another_provider',
          'active_provider',v_subscription.provider,
          'incoming_provider',p_provider
        )
    where id=v_event_id;
    return jsonb_build_object(
      'success',false,'conflict',true,'active_provider',v_subscription.provider,
      'incoming_provider',p_provider,'status',v_subscription.status,
      'subscription_id',v_subscription.id
    );
  end if;

  if v_subscription.id is not null and p_event_time<v_subscription.last_provider_event_at then
    update public.worker_pro_subscription_events
    set subscription_id=v_subscription.id,result='ignored'
    where id=v_event_id;
    return jsonb_build_object(
      'success',true,'duplicate',false,'ignored',true,
      'subscription_id',v_subscription.id,'status',v_subscription.status
    );
  end if;

  v_billing_period:=coalesce(
    public.worker_pro_billing_period_for_product(p_provider,p_product_id),
    nullif(coalesce(p_metadata,'{}'::jsonb)->>'billing_period',''),
    v_subscription.billing_period,
    'monthly'
  );
  if v_billing_period not in('monthly','yearly') then
    raise exception 'Unsupported subscription billing period';
  end if;

  insert into public.worker_pro_subscriptions(
    worker_id,provider,product_id,provider_subscription_id,status,billing_period,
    current_period_start,current_period_end,cancel_at_period_end,auto_renews,
    price_amount,currency,environment,last_verified_at,last_provider_event_at,
    last_provider_event_id,created_at,updated_at
  ) values(
    p_worker_id,p_provider,btrim(p_product_id),
    nullif(btrim(coalesce(p_provider_subscription_id,'')),''),p_status,v_billing_period,
    p_period_start,p_period_end,coalesce(p_cancel_at_period_end,false),
    coalesce(p_auto_renews,false),p_price_amount,upper(p_currency),p_environment,
    now(),p_event_time,btrim(p_provider_event_id),now(),now()
  ) on conflict(worker_id) do update set
    provider=excluded.provider,
    product_id=excluded.product_id,
    provider_subscription_id=coalesce(
      excluded.provider_subscription_id,
      public.worker_pro_subscriptions.provider_subscription_id
    ),
    status=excluded.status,
    billing_period=excluded.billing_period,
    current_period_start=excluded.current_period_start,
    current_period_end=excluded.current_period_end,
    cancel_at_period_end=excluded.cancel_at_period_end,
    auto_renews=excluded.auto_renews,
    price_amount=excluded.price_amount,
    currency=excluded.currency,
    environment=excluded.environment,
    last_verified_at=now(),
    last_provider_event_at=excluded.last_provider_event_at,
    last_provider_event_id=excluded.last_provider_event_id,
    updated_at=now()
  returning * into v_subscription;

  update public.worker_pro_subscription_events
  set subscription_id=v_subscription.id
  where id=v_event_id;
  return jsonb_build_object(
    'success',true,'duplicate',false,'subscription_id',v_subscription.id,
    'status',v_subscription.status,'billing_period',v_subscription.billing_period
  );
end;
$_$;


--
-- Name: record_worker_verification_payment(text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_worker_verification_payment(p_user_id text, p_reference text, p_amount numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller TEXT;
  v_caller_role TEXT;
  v_expected_amount NUMERIC;
  v_payment_id UUID;
  v_verified_ref RECORD;
BEGIN
  -- ── AUTH: Identify caller ──
  SELECT user_id, role INTO v_caller, v_caller_role
  FROM profiles WHERE auth_id = auth.uid()::text;

  IF v_caller IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Only the user themselves or staff can record
  IF v_caller != p_user_id AND v_caller_role NOT IN ('staff','admin','creator') THEN
    RETURN FALSE;
  END IF;

  IF p_reference IS NULL OR p_reference = '' THEN
    RETURN FALSE;
  END IF;

  -- ── REQUIRE: reference must have been independently server-verified ──
  -- This function CONSUMES verification state, never creates it.
  SELECT * INTO v_verified_ref
  FROM verified_paystack_references
  WHERE paystack_reference = p_reference;

  IF v_verified_ref IS NULL THEN
    RETURN FALSE; -- Reference was never server-verified
  END IF;

  -- ── Ownership: verified reference must belong to this user ──
  SELECT bp.user_id INTO v_payment_id FROM booking_payments bp
  WHERE bp.id = v_verified_ref.booking_payment_id;

  -- Note: booking_payments row must exist with correct payer_user_id
  IF NOT EXISTS (
    SELECT 1 FROM booking_payments
    WHERE id = v_verified_ref.booking_payment_id
    AND (payer_user_id = p_user_id OR user_id = p_user_id)
  ) THEN
    RETURN FALSE; -- Verified reference belongs to another user
  END IF;

  -- ── Derive expected amount from settings (NOT browser) ──
  SELECT COALESCE(NULLIF(value, '')::NUMERIC, 0) INTO v_expected_amount
  FROM platform_settings WHERE key = 'worker_verification_fee';

  IF v_expected_amount <= 0 THEN
    RETURN FALSE;
  END IF;

  -- ── Idempotency: already recorded? ──
  IF EXISTS (
    SELECT 1 FROM booking_payments
    WHERE paystack_reference = p_reference AND purpose = 'worker_verification'
  ) THEN
    RETURN TRUE;
  END IF;

  -- ── Record payment in booking_payments ──
  INSERT INTO booking_payments (
    payment_reference, user_id, type,
    payer_user_id, payee_user_id,
    amount, amount_total, commission_amount, net_amount,
    currency, status, purpose,
    paystack_reference,
    paid_at, webhook_processed,
    metadata
  ) VALUES (
    'WHWV_' || p_reference, p_user_id, 'worker_subscription',
    p_user_id, p_user_id,
    v_expected_amount, v_expected_amount, 0, v_expected_amount,
    'NGN', 'completed', 'worker_verification',
    p_reference,
    NOW(), TRUE,
    jsonb_build_object('recorded_by', v_caller, 'expected_amount', v_expected_amount, 'submitted_amount', p_amount, 'verified_by', v_verified_ref.verified_by, 'verified_at', v_verified_ref.verified_at)
  )
  RETURNING id INTO v_payment_id;

  -- ── Audit log ──
  INSERT INTO financial_audit_logs (
    event_type, user_id, amount, reference_id, reference_type, description
  ) VALUES (
    'worker_verification_payment', p_user_id, v_expected_amount,
    v_payment_id::text, 'booking_payment',
    'Worker verification payment recorded (post-verify): ' || p_reference
  );

  RETURN TRUE;
END;
$$;


--
-- Name: refresh_my_property_access_challenge(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_my_property_access_challenge(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_code text;
  v_expires_at timestamptz:=now()+interval '7 days';
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null
     or not public.current_actor_has_workspace('property_partner',null) then
    raise exception 'Property Partner workspace required';
  end if;
  v_code:=upper(substring(replace(gen_random_uuid()::text,'-','') from 1 for 6));
  update public.inspection_requests
  set access_challenge_code=v_code,access_challenge_expires_at=v_expires_at,
      access_evidence_status='required',updated_at=now()
  where id=p_request_id and owner_id=v_actor.user_id and published_at is null;
  if not found then raise exception 'Property request not found'; end if;
  return jsonb_build_object('code',v_code,'expires_at',v_expires_at);
end
$$;


--
-- Name: refresh_my_roommate_search(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_my_roommate_search() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor public.profiles;
  v_prefs public.roommate_preferences;
  v_count integer := 0;
  v_school text;
begin
  select * into v_actor
  from public.profiles
  where auth_id = auth.uid()::text
  limit 1;

  if v_actor is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Regular user required';
  end if;
  if coalesce(v_actor.deleted,false) or coalesce(v_actor.suspended,false) or coalesce(v_actor.banned,false) then
    raise exception 'Account is not active';
  end if;
  if not coalesce(v_actor.profile_complete,false) then
    raise exception 'Complete your profile first';
  end if;
  if coalesce(v_actor.privacy_search_visible,true)=false or coalesce(v_actor.privacy_profile_visible,true)=false then
    raise exception 'Enable Roommate discovery and profile visibility first';
  end if;

  select * into v_prefs
  from public.roommate_preferences
  where user_id = v_actor.user_id
  for update;

  if v_prefs is null or v_prefs.search_status <> 'active' or coalesce(v_prefs.active,false)=false then
    raise exception 'Roommate matching is paused';
  end if;

  v_school := nullif(btrim(coalesce(v_prefs.school_name,v_actor.school,'')),'');
  if coalesce(v_prefs.school_match,false) and v_school is null then
    raise exception 'Enter your school before using same-school matching';
  end if;

  delete from public.roommate_search_results
  where searcher_id = v_actor.user_id
    and status in ('new','viewed');

  with ranked_candidates as (
    select
      c.user_id,
      least(100,
        round(30 * (
          greatest(0, least(cp.budget_max,v_prefs.budget_max) - greatest(cp.budget_min,v_prefs.budget_min) + 1)::numeric
          / greatest(1, least(cp.budget_max-cp.budget_min+1, v_prefs.budget_max-v_prefs.budget_min+1))
        ))::integer
        + case when nullif(btrim(coalesce(v_actor.local_government,v_actor.city,'')),'') is not null
            and lower(coalesce(nullif(c.local_government,''),c.city,'')) = lower(coalesce(nullif(v_actor.local_government,''),v_actor.city,'')) then 20 else 0 end
        + case when lower(coalesce(cp.cleanliness,'')) = lower(coalesce(v_prefs.cleanliness,'')) then 15 else 0 end
        + case when lower(coalesce(cp.noise_level,'')) = lower(coalesce(v_prefs.noise_level,'')) then 15 else 0 end
        + case when lower(coalesce(cp.visitors,'')) = lower(coalesce(v_prefs.visitors,'')) then 10 else 0 end
        + case when lower(coalesce(cp.stay_duration,'')) = lower(coalesce(v_prefs.stay_duration,'')) then 10 else 0 end
      )::integer as score
    from public.profiles c
    join public.roommate_preferences cp on cp.user_id = c.user_id
    where c.user_id <> v_actor.user_id
      and c.account_kind = 'consumer'
      and coalesce(c.profile_complete,false)=true
      and coalesce(c.deleted,false)=false
      and coalesce(c.suspended,false)=false
      and coalesce(c.banned,false)=false
      and coalesce(c.privacy_search_visible,true)=true
      and coalesce(c.privacy_profile_visible,true)=true
      and cp.active=true
      and cp.search_status='active'
      and lower(coalesce(c.state,'')) = lower(coalesce(v_actor.state,''))
      and coalesce(cp.budget_max,0) >= v_prefs.budget_min
      and coalesce(cp.budget_min,999999999) <= v_prefs.budget_max
      and (v_prefs.gender_preference='no_preference' or lower(coalesce(c.gender,''))=lower(v_prefs.gender_preference))
      and (cp.gender_preference='no_preference' or lower(coalesce(v_actor.gender,''))=lower(cp.gender_preference))
      and (not coalesce(v_prefs.school_match,false)
        or lower(regexp_replace(btrim(coalesce(cp.school_name,c.school,'')),'\s+',' ','g')) = lower(regexp_replace(btrim(v_school),'\s+',' ','g')))
      and (not coalesce(cp.school_match,false)
        or lower(regexp_replace(btrim(coalesce(v_prefs.school_name,v_actor.school,'')),'\s+',' ','g')) = lower(regexp_replace(btrim(coalesce(cp.school_name,c.school,'')),'\s+',' ','g')))
      and not exists (
        select 1
        from public.roommate_search_results existing
        where existing.searcher_id = v_actor.user_id
          and existing.matched_user_id = c.user_id
          and existing.status in ('accepted','declined')
      )
      and not exists (
        select 1
        from public.conversations existing_conv
        where existing_conv.conversation_type='roommate'
          and coalesce(existing_conv.status,'active')='active'
          and ((existing_conv.participant_a=v_actor.user_id and existing_conv.participant_b=c.user_id)
            or (existing_conv.participant_b=v_actor.user_id and existing_conv.participant_a=c.user_id))
      )
    order by score desc, c.user_id
    limit 120
  )
  insert into public.roommate_search_results(searcher_id,matched_user_id,match_score,status,created_at,updated_at)
  select v_actor.user_id, rc.user_id, rc.score, 'new', now(), now()
  from ranked_candidates rc
  on conflict(searcher_id,matched_user_id) do update
    set match_score = excluded.match_score,
        updated_at = now();

  select count(*) into v_count
  from public.roommate_search_results
  where searcher_id = v_actor.user_id
    and status <> 'declined';

  update public.roommate_preferences
  set search_match_count = v_count,
      active = true,
      search_status = 'active',
      search_expires_at = null,
      updated_at = now()
  where user_id = v_actor.user_id;

  return v_count;
end;
$$;


--
-- Name: refresh_worker_review_summary(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_worker_review_summary(p_worker_id text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.profiles p
  set rating = coalesce(summary.average_rating, 0),
      review_count = summary.review_total,
      updated_at = now()
  from (
    select round(avg(r.rating)::numeric, 2) as average_rating,
           count(*)::integer as review_total
    from public.worker_booking_reviews r
    join public.worker_bookings b on b.id = r.booking_id
    where r.worker_id = p_worker_id
      and b.worker_id = p_worker_id
      and b.status = 'approved_released'
  ) summary
  where p.user_id = p_worker_id;
$$;


--
-- Name: refund_payment_protection(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_payment_protection(p_payment_protection_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payment_protection RECORD;
  v_caller TEXT;
  v_caller_role TEXT;
BEGIN
  -- ── AUTH: Identify caller ──
  SELECT user_id, role INTO v_caller, v_caller_role
  FROM profiles WHERE auth_id = auth.uid()::text;

  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
  END IF;

  -- ── AUTHORIZATION: staff/admin/creator only ──
  IF v_caller_role NOT IN ('staff','admin','creator') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  SELECT * INTO v_payment_protection FROM payment_protection_transactions WHERE id = p_payment_protection_id FOR UPDATE;

  IF v_payment_protection IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment Protection not found');
  END IF;

  IF v_payment_protection.status NOT IN ('protected', 'disputed') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment Protection cannot be refunded');
  END IF;

  UPDATE payment_protection_transactions SET
    status = 'refunded',
    updated_at = NOW()
  WHERE id = p_payment_protection_id;

  RETURN jsonb_build_object('success', true, 'amount_refunded', v_payment_protection.amount_total);
END;
$$;


--
-- Name: register_current_device(text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_current_device(p_device_id text, p_device text, p_os text, p_browser text, p_existing_session_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_auth_id text := (select auth.uid())::text;
  v_user_id text;
  v_auth_session_id text := nullif((select auth.jwt() ->> 'session_id'), '');
  v_row public.user_sessions%rowtype;
  v_has_trusted_device boolean := false;
  v_has_any_trusted_device boolean := false;
  v_status text;
  v_new_device boolean;
begin
  if v_auth_id is null or v_auth_session_id is null then
    raise exception 'Authentication session is required';
  end if;
  if p_device_id is null or length(trim(p_device_id)) < 16 or length(p_device_id) > 128 then
    raise exception 'A valid device identifier is required';
  end if;

  v_user_id := public.current_profile_user_id();
  if v_user_id is null then raise exception 'WeHouse profile not found'; end if;

  select * into v_row
  from public.user_sessions
  where auth_session_id = v_auth_session_id
    and user_id = v_user_id
    and auth_id = v_auth_id
  limit 1;

  if found then
    update public.user_sessions
    set last_seen = now(),
        device_id = p_device_id,
        device = left(coalesce(nullif(trim(p_device), ''), 'Device'), 120),
        os = left(coalesce(nullif(trim(p_os), ''), 'Unknown'), 120),
        browser = left(coalesce(nullif(trim(p_browser), ''), 'Unknown'), 120)
    where id = v_row.id
    returning * into v_row;
    return jsonb_build_object(
      'session_id', v_row.id,
      'trust_status', v_row.trust_status,
      'new_device', false
    );
  end if;

  if p_existing_session_id is not null then
    select * into v_row
    from public.user_sessions
    where id = p_existing_session_id
      and user_id = v_user_id
      and auth_id = v_auth_id
      and is_active = true
      and auth_session_id is null
    limit 1;

    if found then
      update public.user_sessions
      set auth_session_id = v_auth_session_id,
          device_id = p_device_id,
          trust_status = 'trusted',
          last_seen = now(),
          device = left(coalesce(nullif(trim(p_device), ''), 'Device'), 120),
          os = left(coalesce(nullif(trim(p_os), ''), 'Unknown'), 120),
          browser = left(coalesce(nullif(trim(p_browser), ''), 'Unknown'), 120)
      where id = v_row.id
      returning * into v_row;
      return jsonb_build_object(
        'session_id', v_row.id,
        'trust_status', 'trusted',
        'new_device', false
      );
    end if;
  end if;

  select exists(
    select 1 from public.user_sessions
    where user_id = v_user_id
      and device_id = p_device_id
      and trust_status = 'trusted'
  ) into v_has_trusted_device;

  select exists(
    select 1 from public.user_sessions
    where user_id = v_user_id
      and trust_status = 'trusted'
  ) into v_has_any_trusted_device;

  v_new_device := v_has_any_trusted_device and not v_has_trusted_device;
  v_status := case when v_new_device then 'pending' else 'trusted' end;

  insert into public.user_sessions(
    user_id, auth_id, device_id, auth_session_id, device, os, browser,
    is_active, is_current, last_seen, trust_status
  ) values (
    v_user_id, v_auth_id, p_device_id, v_auth_session_id,
    left(coalesce(nullif(trim(p_device), ''), 'Device'), 120),
    left(coalesce(nullif(trim(p_os), ''), 'Unknown'), 120),
    left(coalesce(nullif(trim(p_browser), ''), 'Unknown'), 120),
    true, true, now(), v_status
  ) returning * into v_row;

  if v_status = 'pending' then
    insert into public.notifications(
      recipient_id, type, title, message, related_id, source_type, source_id,
      destination_route, destination_params, event_key
    )
    select
      v_user_id,
      'new_device_login',
      'New device signed in',
      concat_ws(' · ', v_row.device, v_row.os, v_row.browser),
      v_row.id::text,
      'security',
      v_row.id::text,
      'security',
      jsonb_build_object(
        'session_id', v_row.id,
        'device', v_row.device,
        'os', v_row.os,
        'browser', v_row.browser,
        'login_time', v_row.login_time
      ),
      'new_device_login:' || v_row.id::text
    where not exists (
      select 1 from public.notifications
      where event_key = 'new_device_login:' || v_row.id::text
    );
  end if;

  return jsonb_build_object(
    'session_id', v_row.id,
    'trust_status', v_status,
    'new_device', v_new_device
  );
end;
$$;


--
-- Name: register_current_device_v2(text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_current_device_v2(p_device_id text, p_device text, p_os text, p_browser text, p_location text DEFAULT NULL::text, p_existing_session_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
  v_session_id uuid;
  v_location text := left(coalesce(nullif(btrim(p_location), ''), 'Location unavailable'), 120);
begin
  v_result := public.register_current_device(p_device_id, p_device, p_os, p_browser, p_existing_session_id);
  v_session_id := nullif(v_result ->> 'session_id', '')::uuid;

  if coalesce((v_result ->> 'new_device')::boolean, false) and v_session_id is not null then
    update public.notifications
    set type = 'device_confirmation_pending',
        title = 'New device confirmation in progress',
        message = null,
        read = true,
        read_at = coalesce(read_at, now()),
        destination_route = 'security',
        destination_params = coalesce(destination_params, '{}'::jsonb) || jsonb_build_object(
          'location', v_location,
          'decision', 'awaiting_google'
        )
    where source_id = v_session_id::text
      and recipient_id = public.current_profile_user_id()
      and type = 'new_device_login';
  end if;

  return v_result || jsonb_build_object('location', v_location);
end;
$$;


--
-- Name: register_pending_property_partner_earning(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_pending_property_partner_earning() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_type TEXT;
BEGIN
  IF NEW.status NOT IN ('paid','completed') THEN RETURN NEW; END IF;
  IF NEW.purpose NOT IN ('apartment_rent','rent_plan_contribution','hotel_booking') THEN RETURN NEW; END IF;
  IF NEW.payee_user_id IS NULL OR COALESCE(NEW.net_amount,0)<=0 THEN RETURN NEW; END IF;
  v_type:=CASE
    WHEN NEW.purpose='hotel_booking' THEN 'hotel_payment'
    WHEN NEW.purpose='rent_plan_contribution' THEN 'rent_plan_contribution'
    ELSE COALESCE(NEW.metadata->>'payment_component','')
  END;
  IF v_type NOT IN ('long_stay_rent','short_stay_rent','rent_plan_contribution','hotel_payment') THEN
    RAISE EXCEPTION 'Unsupported property earning type';
  END IF;
  INSERT INTO public.property_partner_earning_releases(payment_id,partner_id,earning_type,status,net_amount)
  VALUES(NEW.id,NEW.payee_user_id,v_type,'pending',NEW.net_amount)
  ON CONFLICT(payment_id) DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: reject_listing_internal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_listing_internal(p_listing_id uuid, p_reason text) RETURNS public.listings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ DECLARE v_actor public.profiles; v_listing public.listings; BEGIN SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND role IN ('admin','creator') AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1; IF v_actor IS NULL THEN RAISE EXCEPTION 'Admin or Creator rejection authority required'; END IF; IF NULLIF(BTRIM(COALESCE(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Rejection reason is required'; END IF; SELECT * INTO v_listing FROM public.listings WHERE id=p_listing_id AND deleted_at IS NULL FOR UPDATE; IF v_listing IS NULL THEN RAISE EXCEPTION 'Listing not found'; END IF; IF v_listing.status<>'pending_approval' THEN RAISE EXCEPTION 'Only pending listings can be rejected'; END IF; IF v_actor.role='admin' THEN IF COALESCE(v_listing.submitted_by_role,'') NOT IN ('staff','property_partner') THEN RAISE EXCEPTION 'Admin cannot reject this submission type'; END IF; IF NOT public.current_actor_in_scope(v_listing.state,v_listing.city) THEN RAISE EXCEPTION 'Listing is outside your assigned branch'; END IF; END IF; UPDATE public.listings SET status='rejected',availability_status='rejected',approved_by=v_actor.user_id,approved_at=now(),rejection_reason=BTRIM(p_reason) WHERE id=p_listing_id RETURNING * INTO v_listing; RETURN v_listing; END; $$;


--
-- Name: reject_withdrawal_for_payout(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_withdrawal_for_payout(p_withdrawal_id uuid, p_reviewer_id text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_reviewer public.profiles;v_withdrawal public.withdrawals;v_wallet public.wallets;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then raise exception 'Service role required'; end if;
  if not public.finance_reviewer_is_authorized(p_reviewer_id) then raise exception 'Finance permission required'; end if;
  select * into v_reviewer from public.profiles where user_id=p_reviewer_id;
  select * into v_withdrawal from public.withdrawals where id=p_withdrawal_id for update;
  select * into v_wallet from public.wallets where id=v_withdrawal.wallet_id;
  if v_reviewer.user_id is null or v_withdrawal.id is null or v_wallet.id is null then raise exception 'Payout record not found'; end if;
  if v_wallet.owner_id=p_reviewer_id then raise exception 'You cannot review your own withdrawal'; end if;
  if v_reviewer.role in ('staff','admin') and not public.can_current_actor_read_profile_for(v_reviewer.user_id,v_wallet.owner_id) then raise exception 'Withdrawal is outside your branch'; end if;
  if v_withdrawal.status<>'awaiting_review' then raise exception 'Only a withdrawal awaiting review can be rejected'; end if;
  if nullif(btrim(coalesce(p_reason,'')),'') is null then raise exception 'A rejection reason is required'; end if;
  update public.withdrawals set reviewed_by=p_reviewer_id,reviewed_at=now() where id=p_withdrawal_id;
  return public.return_reserved_withdrawal(p_withdrawal_id,'rejected',p_reason,'review-rejected:'||p_withdrawal_id::text);
end;
$$;


--
-- Name: release_completed_hotel_partner_earning(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_completed_hotel_partner_earning() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare bp public.booking_payments; e public.property_partner_earning_releases; w public.wallets; new_pending numeric; new_available numeric;
begin
  if new.status<>'completed' or old.status='completed' or new.payment_status<>'paid' then return new; end if;
  select * into bp from public.booking_payments where hotel_booking_id=new.booking_id and purpose='hotel_booking' and status in ('paid','completed') order by created_at desc limit 1;
  if bp.id is null then
    insert into public.financial_audit_logs(event_type,user_id,amount,reference_id,reference_type,description,metadata)
    values('hotel_completion_payout_review',new.user_id,new.total_price,new.booking_id::text,'hotel_booking','Completed hotel stay has no verified booking payment',jsonb_build_object('hotel_id',new.hotel_id));
    return new;
  end if;
  select * into e from public.property_partner_earning_releases where payment_id=bp.id for update;
  if e.id is null or e.status='available' then return new; end if;
  if e.status<>'pending' or e.earning_type<>'hotel_payment' then return new; end if;
  select * into w from public.wallets where owner_id=e.partner_id and owner_type='property_partner' for update;
  if w.id is null or coalesce(w.is_frozen,false) or coalesce(w.pending_balance,0)<e.net_amount then
    insert into public.financial_audit_logs(event_type,user_id,target_user_id,amount,reference_id,reference_type,description,metadata)
    values('hotel_completion_payout_review',new.user_id,e.partner_id,e.net_amount,bp.id::text,'booking_payment','Completed hotel earning requires Finance review',jsonb_build_object('booking_id',new.booking_id,'earning_status',e.status));
    return new;
  end if;
  new_pending:=w.pending_balance-e.net_amount; new_available:=coalesce(w.available_balance,0)+e.net_amount;
  update public.wallets set pending_balance=new_pending,available_balance=new_available,updated_at=now() where id=w.id;
  update public.property_partner_earning_releases set status='available',release_event='hotel_stay_completed',released_by=null,released_at=now(),updated_at=now() where id=e.id and status='pending';
  update public.commission_ledger set status='settled',updated_at=now() where payment_id=bp.id and status='collected';
  update public.property_partners set total_earnings=coalesce(total_earnings,0)+e.net_amount,updated_at=now() where profile_id=e.partner_id;
  insert into public.wallet_transactions(user_id,transaction_type,amount,balance_after,reference_id,reference_type,description,metadata,created_at)
  values(e.partner_id,'property_earning_released',e.net_amount,new_available,bp.id::text,'booking_payment','Hotel stay earnings released after completion',jsonb_build_object('release_event','hotel_stay_completed','hotel_booking_id',new.booking_id,'pending_balance_after',new_pending,'available_balance_after',new_available),now());
  insert into public.financial_audit_logs(event_type,user_id,target_user_id,amount,reference_id,reference_type,description,metadata)
  values('payment_protection_credit_wallet',new.user_id,e.partner_id,e.net_amount,bp.id::text,'booking_payment','Hotel stay completed; protected earnings released',jsonb_build_object('hotel_booking_id',new.booking_id,'release_event','hotel_stay_completed'));
  return new;
end;
$$;


