--
-- Name: release_payment_protection(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_payment_protection(p_booking_id uuid, p_released_by text DEFAULT 'system'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payment_protection RECORD;
  v_wallet RECORD;
  v_caller TEXT;
  v_caller_role TEXT;
  v_new_balance NUMERIC;
BEGIN
  -- ── AUTH: Identify caller ──
  SELECT user_id, role INTO v_caller, v_caller_role
  FROM profiles WHERE auth_id = auth.uid()::text;

  IF v_caller IS NULL THEN
    RETURN FALSE;
  END IF;

  -- ── AUTHORIZATION: staff/admin/creator only ──
  IF v_caller_role NOT IN ('staff','admin','creator') THEN
    RETURN FALSE;
  END IF;

  SELECT * INTO v_payment_protection
  FROM payment_protection_transactions
  WHERE booking_id = p_booking_id AND status = 'protected'
  FOR UPDATE;

  IF v_payment_protection IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT * INTO v_wallet
  FROM wallets
  WHERE owner_id = v_payment_protection.payee_user_id
  FOR UPDATE;

  IF v_wallet IS NULL THEN
    RETURN FALSE;
  END IF;

  IF v_wallet.is_frozen THEN
    RETURN FALSE;
  END IF;

  -- Amount derived server-side from payment_protection.amount_payee
  v_new_balance := v_wallet.available_balance + v_payment_protection.amount_payee;

  UPDATE wallets SET
    available_balance = v_new_balance,
    updated_at = NOW()
  WHERE id = v_wallet.id;

  UPDATE payment_protection_transactions SET
    status = 'released',
    released_at = NOW(),
    released_by = COALESCE(p_released_by, v_caller),
    updated_at = NOW()
  WHERE id = v_payment_protection.id;

  INSERT INTO wallet_transactions (
    user_id, transaction_type, amount, description,
    reference_id, reference_type, balance_after
  ) VALUES (
    v_wallet.owner_id, 'payment_protection_release', v_payment_protection.amount_payee,
    'Payment Protection released for booking ' || p_booking_id::text,
    v_payment_protection.id::text, 'payment_protection', v_new_balance
  );

  RETURN TRUE;
END;
$$;


