--
-- Name: rename_service_subcategory(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_service_subcategory(p_subcategory_id uuid, p_name text) RETURNS public.service_subcategories
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor public.profiles;old_name text;result public.service_subcategories;
begin
  select * into actor from public.profiles where auth_id=auth.uid()::text limit 1;
  if actor is null or not public.is_current_creator() then raise exception 'Creator authorization required';end if;
  if nullif(btrim(p_name),'') is null then raise exception 'Service name is required';end if;
  select name into old_name from public.service_subcategories where id=p_subcategory_id for update;
  if old_name is null then raise exception 'Service not found';end if;
  update public.service_subcategories set name=btrim(p_name),updated_at=now() where id=p_subcategory_id returning * into result;
  update public.worker_bookings set service_type=result.name where service_subcategory_id=p_subcategory_id or(service_subcategory_id is null and lower(btrim(coalesce(service_type,'')))=lower(btrim(old_name)));
  update public.profiles p set worker_skills=(select coalesce(jsonb_agg(case when lower(btrim(skill))=lower(btrim(old_name)) then result.name else skill end),'[]'::jsonb) from jsonb_array_elements_text(coalesce(p.worker_skills,'[]'::jsonb)) skill),updated_at=now()
  where exists(select 1 from jsonb_array_elements_text(coalesce(p.worker_skills,'[]'::jsonb)) skill where lower(btrim(skill))=lower(btrim(old_name)));
  return result;
end $$;


--
-- Name: reopen_my_support_case(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_my_support_case(p_conversation_id uuid, p_note text DEFAULT NULL::text) RETURNS public.partner_support_conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conversation public.partner_support_conversations;
  v_result public.partner_support_conversations;
  v_next_status text;
  v_case_status text;
  v_note text:=coalesce(nullif(btrim(coalesce(p_note,'')),''),
    'I still need help with this request.');
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  select * into v_conversation from public.partner_support_conversations
  where id=p_conversation_id for update;
  if v_actor.user_id is null or v_conversation.id is null
     or v_conversation.partner_id<>v_actor.user_id then raise exception 'Request not found'; end if;
  if v_conversation.status not in('resolved','closed') then raise exception 'This request is already active'; end if;
  v_next_status:=case when coalesce(v_conversation.assigned_staff_id,
    v_conversation.assigned_field_officer_id) is null then 'open' else 'in_progress' end;
  v_case_status:=case when v_next_status='open' then 'open' else 'investigating' end;
  update public.partner_support_conversations set status=v_next_status,
    resolved_at=null,closed_at=null,updated_at=now()
  where id=p_conversation_id returning * into v_result;
  update public.operational_cases set status=v_case_status,resolved_at=null,
    closed_at=null,updated_at=now()
  where operational_case_id=v_conversation.operational_case_id;
  insert into public.support_case_events(
    conversation_id,event_type,actor_id,from_status,to_status,note
  ) values(p_conversation_id,'reopened',v_actor.user_id,
    v_conversation.status,v_next_status,v_note);
  insert into public.partner_support_messages(
    conversation_id,sender_id,sender_role,content,action_type,
    action_metadata,visibility,created_at
  ) values(p_conversation_id,v_actor.user_id,
    coalesce(v_conversation.requester_role,v_actor.role),v_note,
    'status_change',jsonb_build_object('event_type','reopened',
      'from_status',v_conversation.status,'to_status',v_next_status),
    'customer',now());
  if v_conversation.canonical_thread_id is not null then
    update public.canonical_threads set state='open',closed_at=null,updated_at=now()
    where thread_id=v_conversation.canonical_thread_id;
  end if;
  return v_result;
end
$$;


--
-- Name: replace_active_device_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_active_device_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.is_active and new.device_id is not null then
    update public.user_sessions
    set is_active = false,
        is_current = false,
        logout_time = coalesce(logout_time, now())
    where user_id = new.user_id
      and device_id = new.device_id
      and is_active = true
      and id <> new.id;

    update public.notifications
    set read = true,
        read_at = coalesce(read_at, now()),
        destination_params = coalesce(destination_params, '{}'::jsonb)
          || jsonb_build_object('decision', 'replaced_by_new_session')
    where recipient_id = new.user_id
      and type = 'new_device_login'
      and read = false
      and source_id in (
        select id::text
        from public.user_sessions
        where user_id = new.user_id
          and device_id = new.device_id
          and is_active = false
          and id <> new.id
      );
  end if;
  return new;
end;
$$;


--
-- Name: report_my_accommodation_arrival_issue(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_my_accommodation_arrival_issue(p_subject_type text, p_subject_id text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_protection_id uuid;
  v_deadline timestamptz;
  v_protection public.payment_protection_transactions;
  v_case_id uuid;
  v_from_state text;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_subject_type not in ('short_let','hotel') then
    raise exception 'Arrival issues apply only to Hotel or Short Let stays';
  end if;
  if nullif(btrim(coalesce(p_reason,'')),'') is null then
    raise exception 'Explain the arrival issue';
  end if;
  if p_subject_type='short_let' then
    select reservation.stay_payment_protection_id,reservation.arrival_issue_deadline_at
    into v_protection_id,v_deadline
    from public.reservations reservation
    where reservation.id=p_subject_id and reservation.user_id=v_actor
      and reservation.stay_type='short_let' and reservation.checked_in_at is not null
      and reservation.status in ('occupied','completed');
  else
    select booking.payment_protection_id,booking.arrival_issue_deadline_at
    into v_protection_id,v_deadline
    from public.hotel_bookings booking
    where booking.booking_id::text=p_subject_id and booking.user_id=v_actor
      and booking.checked_in_at is not null
      and coalesce(booking.canonical_state,booking.status) in ('checked_in','checked_out','completed');
  end if;
  if v_protection_id is null or v_deadline is null then
    raise exception 'This stay is not eligible for an arrival issue';
  end if;
  if now()>v_deadline then raise exception 'The arrival-issue window is closed'; end if;
  select * into v_protection from public.payment_protection_transactions
  where id=v_protection_id for update;
  if v_protection.id is null
     or v_protection.protection_state not in ('protected','release_eligible','disputed') then
    raise exception 'Accommodation money is no longer eligible for an arrival issue';
  end if;
  v_case_id:=public.open_contextual_case(
    'arrival_issue',p_subject_type,p_subject_id,btrim(p_reason)
  );
  if v_protection.protection_state<>'disputed' then
    v_from_state:=v_protection.protection_state;
    insert into public.payment_protection_transitions(
      payment_protection_id,from_state,to_state,event_type,event_key,
      actor_user_id,actor_type,reason,metadata
    ) values(
      v_protection.id,v_from_state,'disputed','arrival_issue_reported',
      'arrival-issue:'||v_case_id::text,v_actor,'customer',btrim(p_reason),
      jsonb_build_object('operational_case_id',v_case_id,'deadline_at',v_deadline)
    ) on conflict(event_key) do nothing;
    update public.payment_protection_transactions set
      protection_state='disputed',status='disputed',risk_held_at=now(),
      dispute_case_id=v_case_id,updated_at=now()
    where id=v_protection.id;
    update public.property_partner_earning_releases earning
    set status='held',held_at=now(),hold_reason='Arrival issue '||v_case_id::text,
        updated_at=now()
    from public.booking_payments payment
    where payment.id=earning.payment_id
      and payment.paystack_reference=v_protection.paystack_reference
      and earning.status='pending';
    update public.financial_action_outbox set
      status='manual_review',claimed_by=null,claimed_at=null,
      last_error='Frozen by timely arrival issue '||v_case_id::text,
      metadata=metadata||jsonb_build_object('arrival_issue_case_id',v_case_id),
      updated_at=now()
    where payment_protection_id=v_protection.id
      and action_type in ('release_short_let_stay','release_hotel_stay')
      and status in ('pending','claimed');
  end if;
  return v_case_id;
end
$$;


