--
-- Name: request_my_apartment_move_in(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_my_apartment_move_in(p_reservation_id text, p_requested_at timestamp with time zone) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_res public.reservations;
  v_listing public.listings;
  v_result public.reservations;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Active Personal account required';
  end if;
  select * into v_res from public.reservations
  where id=p_reservation_id and user_id=v_actor.user_id for update;
  if v_res is null then raise exception 'Apartment reservation not found'; end if;
  if coalesce(v_res.stay_type,'long_stay')<>'long_stay' then
    raise exception 'Use the reserved check-in time for a Short Let';
  end if;
  if v_res.status<>'ready_for_move_in'
     or v_res.rent_payment_status not in ('paid','upfront_paid')
     or v_res.rent_paid_at is null then
    raise exception 'Verified Year 1 rent is required before choosing move-in';
  end if;
  if p_requested_at is null
     or p_requested_at<now()-interval '15 minutes'
     or p_requested_at>now()+interval '3 days' then
    raise exception 'Choose a move-in time within the next 3 days';
  end if;
  select * into v_listing from public.listings
  where id::text=v_res.listing_id or listing_id=v_res.listing_id limit 1;
  if v_listing is null then raise exception 'Apartment listing not found'; end if;
  update public.reservations
  set requested_move_in_at=p_requested_at,move_in_requested_at=now(),
      updated_at=now()
  where id=v_res.id returning * into v_result;
  insert into public.notifications(
    recipient_id,type,title,message,read,source_type,source_id,
    destination_route,destination_params,workspace_scope
  ) values(
    v_actor.user_id,'move_in_request_saved','Move-in time sent',
    'Property Operations received your preferred arrival time. Your tenancy has not started yet.',
    false,'apartment_reservation',v_res.id,'my_reservations',
    jsonb_build_object('reservation_id',v_res.id),'personal'
  );
  insert into public.notifications(
    recipient_id,type,title,message,read,source_type,source_id,
    destination_route,destination_params,workspace_scope
  )
  select staff.user_id,'property_move_in_requested','Move-in time requested',
    coalesce(
      nullif(v_actor.full_name,''),nullif(v_actor.username,''),'A customer'
    )||' chose an arrival time for '
      ||coalesce(v_listing.title,'an apartment')||'.',
    false,'apartment_reservation',v_res.id,'operations_bookings',
    jsonb_build_object(
      'reservation_id',v_res.id,'listing_id',v_res.listing_id
    ),
    case staff.role when 'creator' then 'creator'
      when 'admin' then 'admin' else 'staff' end
  from public.profiles staff
  where staff.role in ('staff','admin','creator')
    and not coalesce(staff.deleted,false)
    and not coalesce(staff.suspended,false)
    and not coalesce(staff.banned,false)
    and (
      staff.role in ('admin','creator')
      or (
        lower(btrim(coalesce(staff.state,'')))
          =lower(btrim(coalesce(v_listing.state,'')))
        and lower(btrim(coalesce(
          staff.local_government,staff.city,''
        )))=lower(btrim(coalesce(v_listing.city,'')))
      )
    );
  return v_result;
end
$$;


--
-- Name: request_my_property_partner_withdrawal(numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_my_property_partner_withdrawal(p_amount numeric, p_bank_account_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id text:=public.current_profile_user_id(); v_wallet public.wallets;
  v_bank public.bank_accounts; v_withdrawal_id uuid; v_min numeric:=5000;
  v_new_balance numeric;
begin
  if v_user_id is null or not public.current_actor_has_workspace('property_partner',null)
    then raise exception 'Property Partner workspace required'; end if;
  if p_amount is null or p_amount<=0 then raise exception 'Amount must be greater than 0'; end if;
  select * into v_bank from public.bank_accounts
  where id=p_bank_account_id and user_id=v_user_id and verified_at is not null limit 1;
  if v_bank.id is null or nullif(btrim(coalesce(v_bank.paystack_recipient_code,'')),'') is null
    then raise exception 'Choose a Paystack-verified payout account'; end if;
  select nullif(trim(value),'')::numeric into v_min from public.platform_settings
  where key in('wallet_minimum_withdrawal','min_withdrawal') and coalesce(is_active,true)
  order by case key when 'wallet_minimum_withdrawal' then 0 else 1 end limit 1;
  v_min:=coalesce(v_min,5000);
  if p_amount<v_min then raise exception 'Minimum withdrawal is ₦%',v_min; end if;
  select * into v_wallet from public.wallets
  where owner_id=v_user_id and owner_type='property_partner' for update;
  if v_wallet.id is null then raise exception 'Wallet not found'; end if;
  if coalesce(v_wallet.is_frozen,false) then raise exception 'Wallet is frozen'; end if;
  if p_amount>coalesce(v_wallet.available_balance,0)
    then raise exception 'Insufficient available balance'; end if;
  v_new_balance:=v_wallet.available_balance-p_amount;
  update public.wallets set available_balance=v_new_balance,
    frozen_balance=coalesce(frozen_balance,0)+p_amount,updated_at=now()
  where id=v_wallet.id;
  insert into public.withdrawals(
    wallet_id,amount,status,bank_name,bank_account_number,bank_account_name,
    bank_account_id,payout_recipient_code,snapshot_bank_name,
    snapshot_bank_account_number,snapshot_bank_account_name,snapshot_bank_code,
    created_at,updated_at
  ) values(
    v_wallet.id,p_amount,'awaiting_review',v_bank.bank_name,v_bank.account_number,
    v_bank.account_name,v_bank.id,v_bank.paystack_recipient_code,v_bank.bank_name,
    v_bank.account_number,v_bank.account_name,v_bank.bank_code,now(),now()
  ) returning id into v_withdrawal_id;
  insert into public.wallet_transactions(
    user_id,transaction_type,amount,balance_after,reference_id,reference_type,
    description,metadata
  ) values(v_user_id,'withdrawal',-p_amount,v_new_balance,v_withdrawal_id::text,
    'withdrawal','Withdrawal awaiting Finance Operations review',
    jsonb_build_object('status','awaiting_review','bank_account_id',v_bank.id));
  insert into public.financial_audit_logs(
    event_type,user_id,target_user_id,amount,reference_id,reference_type,
    description,metadata
  ) values('withdrawal_requested',v_user_id,v_user_id,p_amount,
    v_withdrawal_id::text,'withdrawal','Withdrawal requested; amount reserved',
    jsonb_build_object('owner_type','property_partner','bank_account_id',v_bank.id));
  return v_withdrawal_id;
end
$$;


--
-- Name: request_withdrawal(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_withdrawal(p_user_id text, p_amount numeric) RETURNS TABLE(withdrawal_id uuid, paystack_kobo integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_wallet RECORD; v_bank RECORD;
BEGIN
  SELECT * INTO v_wallet FROM wallets WHERE owner_id = p_user_id;
  IF NOT FOUND OR COALESCE(v_wallet.available_balance, 0) < p_amount THEN RETURN; END IF;
  SELECT * INTO v_bank FROM bank_accounts WHERE user_id = p_user_id ORDER BY is_default DESC, created_at DESC LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;
  UPDATE wallets SET available_balance = COALESCE(available_balance, 0) - p_amount,
    total_withdrawn = COALESCE(total_withdrawn, 0) + p_amount, updated_at = NOW() WHERE id = v_wallet.id;
  RETURN QUERY INSERT INTO withdrawal_requests (wallet_id, user_id, amount, bank_account_number, bank_code, bank_name, account_name)
  VALUES (v_wallet.id, p_user_id, p_amount, v_bank.account_number, v_bank.bank_code, v_bank.bank_name, v_bank.account_name)
  RETURNING id, (p_amount * 100)::INT;
END;
$$;


--
-- Name: request_withdrawal_v2(uuid, numeric, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_withdrawal_v2(p_wallet_id uuid, p_amount numeric, p_bank_account_number text, p_bank_code text, p_bank_name text, p_account_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE v_wallet RECORD; v_withdrawal_id UUID; v_min_withdrawal NUMERIC;
BEGIN
  SELECT COALESCE(NULLIF(value, '')::NUMERIC, 5000) INTO v_min_withdrawal FROM platform_settings WHERE key = 'min_withdrawal';
  SELECT * INTO v_wallet FROM wallets WHERE id = p_wallet_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Wallet not found'; END IF;
  IF p_amount <= 0 THEN RAISE EXCEPTION 'Amount must be greater than 0'; END IF;
  IF p_amount < v_min_withdrawal THEN RAISE EXCEPTION 'Minimum withdrawal is N%', v_min_withdrawal; END IF;
  IF p_amount > v_wallet.available_balance THEN RAISE EXCEPTION 'Insufficient balance. Available: N%', v_wallet.available_balance; END IF;
  UPDATE wallets SET available_balance = available_balance - p_amount, frozen_balance = frozen_balance + p_amount, updated_at = NOW() WHERE id = p_wallet_id;
  INSERT INTO withdrawals (wallet_id, amount, bank_account_number, bank_code, bank_name, account_name, status)
  VALUES (p_wallet_id, p_amount, p_bank_account_number, p_bank_code, p_bank_name, p_account_name, 'pending') RETURNING id INTO v_withdrawal_id;
  RETURN v_withdrawal_id;
END;
$$;


--
-- Name: request_worker_withdrawal(numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_worker_withdrawal(p_amount numeric, p_bank_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id text:=public.current_profile_user_id();
  v_wallet public.wallets;
  v_bank public.bank_accounts;
  v_min numeric;
  v_request_id uuid;
  v_new_balance numeric;
begin
  if v_user_id is null or not public.current_actor_has_workspace('worker',null) then
    return jsonb_build_object(
      'success',false,'error','Worker workspace required'
    );
  end if;
  if p_amount is null or p_amount<=0 then
    return jsonb_build_object('success',false,'error','Amount must be positive');
  end if;
  if p_bank_account_id is not null then
    select * into v_bank from public.bank_accounts
    where id=p_bank_account_id and user_id=v_user_id
      and verified_at is not null;
  else
    select * into v_bank from public.bank_accounts
    where user_id=v_user_id and verified_at is not null
    order by is_default desc,created_at limit 1;
  end if;
  if v_bank.id is null
     or nullif(btrim(coalesce(v_bank.paystack_recipient_code,'')),'') is null then
    return jsonb_build_object(
      'success',false,'error','Choose a Paystack-verified payout account'
    );
  end if;
  select * into v_wallet from public.wallets
  where owner_id=v_user_id and owner_type='worker' for update;
  if v_wallet.id is null then
    return jsonb_build_object('success',false,'error','Wallet not found');
  end if;
  if coalesce(v_wallet.is_frozen,false) then
    return jsonb_build_object('success',false,'error','Wallet is frozen');
  end if;
  select nullif(trim(value),'')::numeric into v_min
  from public.platform_settings
  where key in ('wallet_minimum_withdrawal','min_withdrawal')
    and coalesce(is_active,true)
  order by case key when 'wallet_minimum_withdrawal' then 0 else 1 end
  limit 1;
  if v_min is null then
    return jsonb_build_object(
      'success',false,'error','Minimum withdrawal setting is missing'
    );
  end if;
  if p_amount<v_min then
    return jsonb_build_object(
      'success',false,'error',format('Minimum withdrawal is ₦%s',v_min)
    );
  end if;
  if p_amount>coalesce(v_wallet.available_balance,0) then
    return jsonb_build_object(
      'success',false,'error','Insufficient available balance'
    );
  end if;
  v_new_balance:=v_wallet.available_balance-p_amount;
  update public.wallets
  set available_balance=v_new_balance,
      frozen_balance=coalesce(frozen_balance,0)+p_amount,
      updated_at=now()
  where id=v_wallet.id;
  insert into public.withdrawals(
    wallet_id,amount,status,bank_name,bank_account_number,bank_account_name,
    bank_account_id,payout_recipient_code,snapshot_bank_name,
    snapshot_bank_account_number,snapshot_bank_account_name,
    snapshot_bank_code,created_at,updated_at
  ) values(
    v_wallet.id,p_amount,'awaiting_review',v_bank.bank_name,
    v_bank.account_number,v_bank.account_name,v_bank.id,
    v_bank.paystack_recipient_code,v_bank.bank_name,v_bank.account_number,
    v_bank.account_name,v_bank.bank_code,now(),now()
  ) returning id into v_request_id;
  insert into public.wallet_transactions(
    user_id,transaction_type,amount,balance_after,reference_id,
    reference_type,description,metadata,created_at
  ) values(
    v_user_id,'withdrawal',-p_amount,v_new_balance,v_request_id::text,
    'withdrawal','Withdrawal awaiting Finance Operations review',
    jsonb_build_object(
      'wallet_id',v_wallet.id,'status','awaiting_review',
      'bank_account_id',v_bank.id
    ),now()
  );
  insert into public.financial_audit_logs(
    event_type,user_id,target_user_id,amount,reference_id,reference_type,
    description,metadata
  ) values(
    'withdrawal_requested',v_user_id,v_user_id,p_amount,
    v_request_id::text,'withdrawal',
    'Withdrawal requested; amount reserved from available balance',
    jsonb_build_object('owner_type','worker','bank_account_id',v_bank.id)
  );
  return jsonb_build_object(
    'success',true,'request_id',v_request_id,
    'amount',p_amount,'status','awaiting_review'
  );
end
$$;


--
-- Name: require_independent_field_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_independent_field_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.status in ('completed', 'approved')
     and old.status is distinct from new.status
     and cardinality(coalesce(new.field_photo_urls, array[]::text[])) < 4 then
    raise exception 'At least 4 independent Field Operations photos are required';
  end if;
  return new;
end;
$$;


--
-- Name: reserve_lga_booking_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_lga_booking_code(p_lga text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_prefix text := public.lga_booking_prefix(p_lga); v_code text; v_attempt integer := 0;
BEGIN
  LOOP
    v_attempt := v_attempt + 1;
    IF v_attempt > 100 THEN RAISE EXCEPTION 'Could not allocate a unique booking code'; END IF;
    v_code := v_prefix || lpad(floor(random() * 100000)::integer::text, 5, '0');
    INSERT INTO public.booking_code_registry(code) VALUES (v_code) ON CONFLICT DO NOTHING;
    IF FOUND THEN RETURN v_code; END IF;
  END LOOP;
END; $$;


--
-- Name: reserve_listing_on_activation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_listing_on_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.status = 'active' AND OLD.status != 'active' THEN
    UPDATE listings SET availability_status = 'reserved', reserved_by = NEW.user_id, reserved_at = NOW()
    WHERE id = NEW.listing_id AND availability_status = 'available';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: resolve_caution_finance(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_caution_finance(p_caution_claim_id uuid, p_partner_award numeric, p_resolution text) RETURNS public.caution_claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_claim public.caution_claims;
  v_refund numeric(12,2);
  v_refund_balance numeric(12,2);
  v_available_at timestamptz;
  v_final_appeal boolean;
  v_suffix text;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if not(v_actor.role='creator' or public.current_actor_has_workspace('finance_operations',null)) then
    raise exception 'Finance Operations access required'; end if;
  select * into v_claim from public.caution_claims
  where caution_claim_id=p_caution_claim_id for update;
  if v_claim.caution_claim_id is null or v_claim.status not in('finance_review','appealed') then
    raise exception 'Claim is not ready for Finance Operations'; end if;
  if nullif(btrim(coalesce(p_resolution,'')),'') is null then
    raise exception 'A written Finance resolution is required'; end if;
  if p_partner_award<0 or p_partner_award>v_claim.disputed_amount then
    raise exception 'Award cannot exceed the Property Operations supported amount'; end if;
  v_final_appeal:=v_claim.status='appealed';
  v_available_at:=case when v_final_appeal then now() else now()+interval '48 hours' end;
  v_suffix:=case when v_final_appeal then ':appeal-final' else ':initial' end;
  v_refund:=v_claim.deposit_amount-p_partner_award;
  v_refund_balance:=greatest(v_refund-v_claim.undisputed_refund_amount,0);
  update public.caution_claims set
    partner_award=p_partner_award,customer_refund=v_refund,
    finance_resolved_by=v_actor.user_id,finance_resolved_at=now(),
    guest_response=concat_ws(E'\n',guest_response,
      case when v_final_appeal then 'Final appeal decision: ' else 'Finance resolution: ' end||btrim(p_resolution)),
    appeal_due_at=case when v_final_appeal then null else v_available_at end,
    status='resolved',updated_at=now()
  where caution_claim_id=p_caution_claim_id returning * into v_claim;

  if v_claim.shared_payment_group_id is not null then
    if p_partner_award>0 then perform public.enqueue_shared_caution_distribution(
      v_claim.shared_payment_group_id,'release_caution_award','caution_claim',
      p_caution_claim_id::text,p_partner_award,
      'caution-award:'||p_caution_claim_id||v_suffix,v_available_at); end if;
    if v_refund_balance>0 then perform public.enqueue_shared_caution_distribution(
      v_claim.shared_payment_group_id,'refund_caution_balance','caution_claim',
      p_caution_claim_id::text,v_refund_balance,
      'caution-balance-refund:'||p_caution_claim_id||v_suffix,v_available_at); end if;
  else
    if p_partner_award>0 then
      insert into public.financial_action_outbox(
        action_type,subject_type,subject_id,payment_protection_id,amount,
        idempotency_key,available_at
      ) values(
        'release_caution_award','caution_claim',p_caution_claim_id::text,
        v_claim.payment_protection_id,p_partner_award,
        'caution-award:'||p_caution_claim_id||v_suffix,v_available_at
      );
    end if;
    if v_refund_balance>0 then
      insert into public.financial_action_outbox(
        action_type,subject_type,subject_id,payment_protection_id,amount,
        idempotency_key,available_at,metadata
      ) values(
        'refund_caution_balance','caution_claim',p_caution_claim_id::text,
        v_claim.payment_protection_id,v_refund_balance,
        'caution-balance-refund:'||p_caution_claim_id||v_suffix,v_available_at,
        jsonb_build_object('refund_destination','original_payment')
      );
    end if;
  end if;
  return v_claim;
end
$$;


--
-- Name: resolve_roommate_interest_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_roommate_interest_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_interest public.roommate_search_results;
begin
  if new.status not in ('accepted', 'declined') then return new; end if;

  select * into v_interest
  from public.roommate_search_results r
  where r.searcher_id = new.matched_user_id
    and r.matched_user_id = new.searcher_id
    and r.status = 'accepted'
  limit 1;
  if v_interest is null then return new; end if;

  update public.notifications
  set type = 'roommate_interest_resolved',
      title = case when new.status = 'accepted'
        then 'Roommate request accepted'
        else 'Roommate request passed'
      end,
      message = case when new.status = 'accepted'
        then 'You accepted this request. The mutual match is ready in Roommates.'
        else 'You passed this request privately. No conversation was created.'
      end,
      read = true,
      read_at = coalesce(read_at, now()),
      source_type = 'roommate_match',
      source_id = v_interest.id::text,
      destination_route = 'roommate',
      destination_params = jsonb_build_object('interest_id', v_interest.id)
  where recipient_id = new.searcher_id
    and type = 'roommate_interest'
    and coalesce(source_id, related_id) = v_interest.id::text;

  return new;
end;
$$;


--
-- Name: respond_private_call(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_private_call(p_call_id uuid, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_me text:=public.current_profile_user_id(); v_call public.private_calls;
begin
 select * into v_call from public.private_calls where id=p_call_id for update;
 if v_call is null or v_call.callee_id<>v_me then raise exception 'Incoming call not found'; end if;
 if v_call.status<>'ringing' then return public.get_private_call_details(p_call_id); end if;
 update public.private_calls set status=case when p_accept then 'accepted' else 'declined' end,answered_at=case when p_accept then now() else null end,ended_at=case when p_accept then null else now() end where id=p_call_id;
 return public.get_private_call_details(p_call_id);
end; $$;


--
-- Name: respond_to_device_login(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_to_device_login(p_session_id uuid, p_approved boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_auth_id text := (select auth.uid())::text;
  v_user_id text;
  v_current_auth_session_id text := nullif((select auth.jwt() ->> 'session_id'), '');
  v_current public.user_sessions%rowtype;
  v_target public.user_sessions%rowtype;
  v_status text := case when p_approved then 'trusted' else 'rejected' end;
begin
  if v_auth_id is null or v_current_auth_session_id is null then
    raise exception 'Authentication session is required';
  end if;
  v_user_id := public.current_profile_user_id();

  select * into v_current
  from public.user_sessions
  where user_id = v_user_id
    and auth_id = v_auth_id
    and auth_session_id = v_current_auth_session_id
    and is_active = true
    and trust_status = 'trusted'
  limit 1;
  if not found then
    raise exception 'Use another trusted device to review this login';
  end if;

  select * into v_target
  from public.user_sessions
  where id = p_session_id
    and user_id = v_user_id
    and auth_id = v_auth_id
  for update;
  if not found then raise exception 'Device login not found'; end if;
  if v_target.id = v_current.id or v_target.auth_session_id = v_current_auth_session_id then
    raise exception 'A new device cannot approve itself';
  end if;
  if v_target.trust_status <> 'pending' then
    return jsonb_build_object('session_id', v_target.id, 'trust_status', v_target.trust_status);
  end if;

  update public.user_sessions
  set trust_status = v_status,
      trust_reviewed_at = now(),
      trust_reviewed_by_session_id = v_current.id,
      is_active = case when p_approved then is_active else false end,
      is_current = case when p_approved then is_current else false end,
      logout_time = case when p_approved then logout_time else now() end
  where id = v_target.id;

  update public.notifications
  set read = true, read_at = coalesce(read_at, now())
  where recipient_id = v_user_id
    and type = 'new_device_login'
    and source_id = v_target.id::text;

  return jsonb_build_object('session_id', v_target.id, 'trust_status', v_status);
end;
$$;


--
-- Name: respond_to_hotel_team_invitation(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_to_hotel_team_invitation(p_membership_id uuid, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_row public.hotel_team_members;
  v_hotel public.hotels;
begin
  select * into v_actor from public.profiles
  where user_id=public.current_profile_user_id()
  limit 1;
  if v_actor.user_id is null then raise exception 'Active Personal account required'; end if;
  select * into v_row from public.hotel_team_members
  where id=p_membership_id and member_user_id=v_actor.user_id
  for update;
  if v_row.id is null then raise exception 'Hotel invitation not found'; end if;
  if v_row.status<>'invited' then raise exception 'This hotel invitation is no longer pending'; end if;
  update public.hotel_team_members
  set status=case when p_accept then 'active' else 'declined' end,
    responded_at=now(),updated_at=now(),revoked_at=null
  where id=v_row.id returning * into v_row;
  select * into v_hotel from public.hotels where hotel_id=v_row.hotel_id;
  insert into public.notifications(
    recipient_id,type,title,message,related_id,source_type,source_id,
    destination_route,destination_params,event_key,workspace_scope
  ) values(
    v_row.invited_by,'hotel_team_invitation_response',
    case when p_accept then 'Hotel invitation accepted' else 'Hotel invitation declined' end,
    coalesce(v_actor.full_name,v_actor.username,'A WeHouse member')
      ||case when p_accept then ' accepted ' else ' declined ' end
      ||coalesce(v_hotel.name,'the hotel')||'.',
    v_row.id::text,'hotel_team_member',v_row.id::text,'property-owner',
    jsonb_build_object('hotel_id',v_row.hotel_id),
    'hotel-team-response:'||v_row.id::text||':'
      ||case when p_accept then 'accepted' else 'declined' end,'property_partner'
  );
  return jsonb_build_object(
    'id',v_row.id,'accepted',p_accept,'hotel_id',v_row.hotel_id,
    'hotel_role',v_row.hotel_role,'capabilities',to_jsonb(v_row.capabilities)
  );
end;
$$;


--
-- Name: respond_to_my_roommate_interest(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_to_my_roommate_interest(p_interest_id uuid, p_response text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor public.profiles;
  v_interest public.roommate_search_results;
  v_conversation_id uuid;
begin
  if p_response not in ('accepted', 'declined') then raise exception 'Response must be accepted or declined'; end if;
  select * into v_actor from public.profiles where auth_id = auth.uid()::text limit 1;
  if v_actor is null or not public.current_actor_has_personal_workspace()
     or coalesce(v_actor.deleted, false) or coalesce(v_actor.suspended, false) or coalesce(v_actor.banned, false) then
    raise exception 'Active regular user required';
  end if;
  select * into v_interest from public.roommate_search_results
  where id = p_interest_id and matched_user_id = v_actor.user_id and status = 'accepted'
  for update;
  if v_interest is null then raise exception 'Roommate interest not found'; end if;

  insert into public.roommate_search_results(searcher_id, matched_user_id, match_score, status, created_at, updated_at)
  values(v_actor.user_id, v_interest.searcher_id, v_interest.match_score, p_response, now(), now())
  on conflict(searcher_id, matched_user_id) do update
  set status = excluded.status, updated_at = now();

  update public.notifications set read = true
  where recipient_id = v_actor.user_id and type = 'roommate_interest' and related_id = v_interest.id::text;

  if p_response = 'accepted' then
    select conversation.id into v_conversation_id
    from public.conversations conversation
    where conversation.conversation_type = 'roommate'
      and ((conversation.participant_a = v_actor.user_id and conversation.participant_b = v_interest.searcher_id)
        or (conversation.participant_b = v_actor.user_id and conversation.participant_a = v_interest.searcher_id))
    order by (conversation.status = 'active') desc, conversation.created_at
    limit 1;

    insert into public.notifications(recipient_id, type, title, message, related_id, read, destination_route)
    select v_interest.searcher_id, 'roommate_match', 'Roommate interest accepted',
      coalesce(nullif(v_actor.full_name, ''), nullif(v_actor.username, ''), 'Your match') ||
        ' accepted your interest. Open Roommates when you want to start a conversation.',
      coalesce(v_conversation_id::text, v_interest.id::text), false, 'roommate'
    where not exists (
      select 1 from public.notifications notification
      where notification.recipient_id = v_interest.searcher_id
        and notification.type = 'roommate_match'
        and notification.related_id = coalesce(v_conversation_id::text, v_interest.id::text)
    );
  end if;
  return v_conversation_id;
end;
$$;


--
-- Name: respond_to_my_worker_quote(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_to_my_worker_quote(p_document_id uuid, p_accept boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_customer text:=public.current_profile_user_id();
begin
  if v_customer is null then raise exception 'Active signed-in account required'; end if;
  update public.worker_work_documents set
    document_status=case when coalesce(p_accept,false) then 'accepted' else 'declined' end,
    responded_at=now(),updated_at=now()
  where id=p_document_id and customer_id=v_customer
    and document_type='quote' and document_status='sent';
  return found;
end;
$$;


--
-- Name: respond_to_shared_housing_invite(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_to_shared_housing_invite(p_group_id uuid, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id(); v_group public.shared_housing_groups;
begin
  select * into v_group from public.shared_housing_groups where id=p_group_id for update;
  if v_group.id is null or v_group.status<>'inviting' or v_group.expires_at<=now() then
    raise exception 'Pending shared-payment invitation not found';
  end if;
  update public.shared_housing_members set
    invitation_status=case when p_accept then 'accepted' else 'declined' end,
    updated_at=now()
  where group_id=p_group_id and user_id=v_actor and invitation_status='invited';
  if not found then raise exception 'Pending shared-payment invitation not found'; end if;
  update public.shared_payment_members set
    invitation_state=case when p_accept then 'accepted' else 'declined' end,
    updated_at=now()
  where shared_payment_group_id=p_group_id and user_id=v_actor;
  if not p_accept then
    update public.shared_housing_groups set status='cancelled',updated_at=now()
    where id=p_group_id;
    update public.shared_payment_groups set status='cancelled',updated_at=now()
    where shared_payment_group_id=p_group_id;
    update public.reservations set status='cancelled',canonical_state='cancelled',updated_at=now()
    where id=v_group.reservation_id and status='payment_pending';
  elsif not exists(
    select 1 from public.shared_housing_members
    where group_id=p_group_id and invitation_status<>'accepted'
  ) then
    update public.shared_housing_groups set
      status='payment_pending',expires_at=now()+interval '30 minutes',updated_at=now()
    where id=p_group_id;
    update public.shared_payment_groups set
      status='checkout_open',checkout_expires_at=now()+interval '30 minutes',updated_at=now()
    where shared_payment_group_id=p_group_id;
    update public.reservations set payment_expires_at=now()+interval '30 minutes',updated_at=now()
    where id=v_group.reservation_id and status='payment_pending';
  end if;
  return public.get_my_shared_housing_group(p_group_id);
end
$$;


--
-- Name: respond_to_worker_work_post_confirmation(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_to_worker_work_post_confirmation(p_post_id uuid, p_confirm boolean) RETURNS public.worker_showcase_posts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor public.profiles;
  v_post public.worker_showcase_posts;
  v_booking public.worker_bookings;
begin
  select * into v_actor from public.profiles where auth_id=auth.uid()::text limit 1;
  if v_actor is null then raise exception 'Profile not found'; end if;
  select * into v_post from public.worker_showcase_posts
    where id=p_post_id and deleted_at is null and booking_id is not null for update;
  if v_post is null then raise exception 'Linked Work Post not found'; end if;
  select * into v_booking from public.worker_bookings where id=v_post.booking_id;
  if v_booking is null or v_booking.user_id<>v_actor.user_id or v_booking.worker_id<>v_post.worker_id or v_booking.status<>'approved_released' then
    raise exception 'Only the customer from this completed job can confirm this Work Post';
  end if;
  if v_post.job_confirmation_status<>'pending' then raise exception 'This Work Post confirmation has already been answered'; end if;

  update public.worker_showcase_posts set
    job_confirmation_status=case when p_confirm then 'confirmed' else 'declined' end,
    verified_job=p_confirm,
    job_confirmed_by=v_actor.user_id,
    job_confirmed_at=now()
  where id=v_post.id returning * into v_post;

  update public.notifications set read=true,read_at=coalesce(read_at,now())
    where recipient_id=v_actor.user_id and event_key='work-post-confirmation:'||v_post.id::text;
  insert into public.notifications(
    recipient_id,type,title,message,related_id,source_type,source_id,
    destination_route,destination_params,event_key
  ) values(
    v_post.worker_id,
    case when p_confirm then 'work_post_confirmed' else 'work_post_declined' end,
    case when p_confirm then 'Customer confirmed your work post' else 'Customer did not confirm your work post' end,
    case when p_confirm then 'This post can now show Completed through WeHouse.' else 'The post remains public as an ordinary Work Post without a WeHouse job badge.' end,
    v_post.id::text,'worker_work_post',v_post.id::text,'worker-dashboard',
    jsonb_build_object('work_post_id',v_post.id,'booking_id',v_booking.id),
    'work-post-response:'||v_post.id::text
  ) on conflict(recipient_id,event_key) where event_key is not null do nothing;
  return v_post;
end;
$$;


--
-- Name: retry_my_shared_payment_checkout(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_my_shared_payment_checkout(p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id(); v_group public.shared_housing_groups;
begin
  select * into v_group from public.shared_housing_groups where id=p_group_id for update;
  if v_group.id is null or v_group.created_by<>v_actor or v_group.status not in('expired','refunded') then
    raise exception 'This shared checkout cannot be retried'; end if;
  if exists(select 1 from public.shared_housing_members where group_id=p_group_id
    and payment_status not in('not_started','refunded','failed')) then
    raise exception 'Refund reconciliation must finish before retry'; end if;
  if v_group.product_type='short_let' then
    perform pg_advisory_xact_lock(hashtextextended('short-let:'||v_group.listing_id::text,0));
    if exists(select 1 from public.reservations other
      where other.listing_id=v_group.listing_id::text and other.id<>v_group.reservation_id
        and other.stay_type='short_let'
        and other.status=any(array['reserved','ready_for_move_in','occupied']::text[])
        and daterange(other.stay_check_in,other.stay_check_out,'[)')
          && daterange(v_group.stay_check_in,v_group.stay_check_out,'[)')) then
      raise exception 'Those Short Let dates are no longer available'; end if;
    update public.reservations set status='payment_pending',canonical_state='checkout_pending',
      payment_expires_at=now()+interval '30 minutes',updated_at=now()
    where id=v_group.reservation_id;
  end if;
  update public.shared_housing_groups set status='payment_pending',
    expires_at=now()+interval '30 minutes',checkout_attempt=checkout_attempt+1,updated_at=now()
  where id=p_group_id returning * into v_group;
  update public.shared_payment_groups set status='checkout_open',
    checkout_expires_at=v_group.expires_at,checkout_attempt=v_group.checkout_attempt,updated_at=now()
  where shared_payment_group_id=v_group.canonical_group_id;
  update public.shared_housing_members set payment_status='not_started',
    payment_reference=null,paid_at=null,updated_at=now() where group_id=p_group_id;
  update public.shared_payment_members set payment_state='not_started',
    provider_reference=null,paid_at=null,updated_at=now()
  where shared_payment_group_id=v_group.canonical_group_id;
  return public.get_my_shared_housing_group(p_group_id);
end
$$;


--
-- Name: return_reserved_withdrawal(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_reserved_withdrawal(p_withdrawal_id uuid, p_status text, p_reason text, p_event_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_withdrawal public.withdrawals;
  v_wallet public.wallets;
  v_event text;
  v_was_paid boolean:=false;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then raise exception 'Service role required'; end if;
  if p_status not in ('rejected','failed','reversed') then raise exception 'Invalid terminal payout status'; end if;
  select * into v_withdrawal from public.withdrawals where id=p_withdrawal_id for update;
  if v_withdrawal.id is null then raise exception 'Withdrawal not found'; end if;
  if v_withdrawal.status='paid' and p_status='reversed' then
    v_was_paid:=true;
  elsif v_withdrawal.status in ('paid','rejected','failed','reversed') then
    return jsonb_build_object('success',true,'already_finalized',true,'status',v_withdrawal.status);
  end if;

  select * into v_wallet from public.wallets where id=v_withdrawal.wallet_id for update;
  if v_wallet.id is null then raise exception 'Wallet not found'; end if;
  if not v_was_paid and coalesce(v_wallet.frozen_balance,0)<v_withdrawal.amount then
    raise exception 'Reserved wallet balance is incomplete';
  end if;
  if v_was_paid then
    update public.wallets set
      available_balance=coalesce(available_balance,0)+v_withdrawal.amount,
      total_withdrawn=greatest(0,coalesce(total_withdrawn,0)-v_withdrawal.amount),
      updated_at=now()
    where id=v_wallet.id returning * into v_wallet;
  else
    update public.wallets set
      available_balance=coalesce(available_balance,0)+v_withdrawal.amount,
      frozen_balance=frozen_balance-v_withdrawal.amount,updated_at=now()
    where id=v_wallet.id returning * into v_wallet;
  end if;
  update public.withdrawals set
    status=p_status,failed_reason=nullif(btrim(coalesce(p_reason,'')),''),
    paystack_status=case when p_status='reversed' then 'reversed' else paystack_status end,
    reversed_at=case when p_status='reversed' then now() else reversed_at end,
    finalized_at=now(),settlement_event_key=p_event_key,updated_at=now()
  where id=v_withdrawal.id;
  insert into public.wallet_transactions(
    user_id,transaction_type,amount,balance_after,reference_id,reference_type,description,metadata,created_at
  ) values(
    v_wallet.owner_id,'withdrawal_reversal',v_withdrawal.amount,v_wallet.available_balance,
    v_withdrawal.id::text,'withdrawal','Withdrawal funds returned to available balance',
    jsonb_build_object('status',p_status,'was_paid',v_was_paid,'reason',nullif(btrim(coalesce(p_reason,'')),''),'event_key',p_event_key),now()
  );
  v_event:=case p_status when 'rejected' then 'withdrawal_rejected' when 'reversed' then 'withdrawal_reversed' else 'withdrawal_failed' end;
  insert into public.financial_audit_logs(
    event_type,user_id,target_user_id,amount,reference_id,reference_type,description,metadata
  ) values(
    v_event,null,v_wallet.owner_id,v_withdrawal.amount,v_withdrawal.id::text,'withdrawal',
    'Withdrawal did not complete; funds returned',
    jsonb_build_object('status',p_status,'was_paid',v_was_paid,'reason',nullif(btrim(coalesce(p_reason,'')),''),'event_key',p_event_key)
  );
  insert into public.notifications(
    recipient_id,type,title,message,related_id,source_type,source_id,destination_route,destination_params,event_key,workspace_scope
  ) values(
    v_wallet.owner_id,'withdrawal_'||p_status,
    case when p_status='rejected' then 'Withdrawal not approved' when p_status='reversed' then 'Withdrawal reversed' else 'Withdrawal failed' end,
    coalesce(nullif(btrim(coalesce(p_reason,'')),''),'The amount is available in your wallet again.'),
    v_withdrawal.id::text,'withdrawal',v_withdrawal.id::text,
    case when v_wallet.owner_type='worker' then 'worker_wallet' else 'partner_finance' end,
    jsonb_build_object('withdrawal_id',v_withdrawal.id),
    'withdrawal-final:'||v_withdrawal.id::text||':'||p_status,
    case when v_wallet.owner_type='worker' then 'worker' else 'property_partner' end
  ) on conflict do nothing;
  return jsonb_build_object('success',true,'status',p_status,'amount_returned',v_withdrawal.amount,'recovered_after_payment',v_was_paid);
end;
$$;


--
-- Name: reverse_payment(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_payment(p_payment_id uuid, p_reversal_type text, p_reason text DEFAULT NULL::text, p_reversal_reference text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payment RECORD;
  v_processed_by TEXT;
  v_processed_by_role TEXT;
  v_net NUMERIC;
BEGIN
  -- ── AUTH ──
  SELECT user_id, role INTO v_processed_by, v_processed_by_role
  FROM profiles WHERE auth_id = auth.uid()::text;

  -- Staff/admin/creator only
  IF v_processed_by_role NOT IN ('staff','admin','creator') THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT * INTO v_payment FROM booking_payments WHERE id = p_payment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment not found'; END IF;
  IF v_payment.status IN ('refunded', 'disputed') THEN RAISE EXCEPTION 'Already reversed'; END IF;

  v_net := 0;

  INSERT INTO payment_reversals (
    original_payment_id, original_reference, reversal_type,
    original_amount, reversal_amount, net_after_reversal,
    reason, processed_by, reversal_reference
  ) VALUES (
    p_payment_id, v_payment.paystack_reference, p_reversal_type,
    COALESCE(v_payment.amount_total, v_payment.amount, 0),
    COALESCE(v_payment.amount_total, v_payment.amount, 0),
    v_net, p_reason, v_processed_by, p_reversal_reference
  );

  UPDATE booking_payments
  SET status = 'refunded', updated_at = NOW()
  WHERE id = p_payment_id;

  UPDATE commission_ledger
  SET status = 'refunded', updated_at = NOW()
  WHERE payment_id = p_payment_id;

  RETURN TRUE;
END;
$$;


--
-- Name: reverse_pending_property_partner_earning(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_pending_property_partner_earning(p_payment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor public.profiles; v_e record; v_wallet record; v_new_pending numeric;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND role IN ('admin','creator')
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Admin or Creator finance authority required'; END IF;
  IF NULLIF(BTRIM(COALESCE(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Reversal reason is required'; END IF;
  SELECT * INTO v_e FROM public.property_partner_earning_releases WHERE payment_id=p_payment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Property Partner earning not found'; END IF;
  IF v_actor.role='admin' AND NOT public.can_current_actor_read_profile(v_e.partner_id) THEN RAISE EXCEPTION 'Partner is outside your assigned branch'; END IF;
  IF v_e.status='reversed' THEN RETURN jsonb_build_object('success',true,'already_reversed',true); END IF;
  IF v_e.status<>'pending' THEN RAISE EXCEPTION 'Only pending earnings can be reversed'; END IF;
  SELECT * INTO v_wallet FROM public.wallets WHERE owner_id=v_e.partner_id AND owner_type='property_partner' FOR UPDATE;
  IF NOT FOUND OR COALESCE(v_wallet.pending_balance,0)<v_e.net_amount THEN RAISE EXCEPTION 'Pending wallet balance is inconsistent'; END IF;
  v_new_pending:=v_wallet.pending_balance-v_e.net_amount;
  UPDATE public.wallets SET pending_balance=v_new_pending,updated_at=now() WHERE id=v_wallet.id;
  UPDATE public.property_partner_earning_releases SET status='reversed',reversed_by=v_actor.user_id,reversed_at=now(),reversal_reason=BTRIM(p_reason),updated_at=now() WHERE id=v_e.id;
  UPDATE public.commission_ledger SET status='refunded',updated_at=now() WHERE payment_id=p_payment_id;
  INSERT INTO public.wallet_transactions(user_id,transaction_type,amount,balance_after,reference_id,reference_type,description,metadata) VALUES(v_e.partner_id,'property_earning_reversed',-v_e.net_amount,v_new_pending,p_payment_id::text,'booking_payment','Pending property earnings reversed',jsonb_build_object('reason',BTRIM(p_reason),'wallet_bucket','pending'));
  INSERT INTO public.financial_audit_logs(event_type,user_id,target_user_id,amount,reference_id,reference_type,description,metadata) VALUES('payment_reversed',v_actor.user_id,v_e.partner_id,v_e.net_amount,p_payment_id::text,'booking_payment','Pending Property Partner earning reversed',jsonb_build_object('reason',BTRIM(p_reason)));
  RETURN jsonb_build_object('success',true,'status','reversed','pending_balance',v_new_pending);
END;
$$;


--
-- Name: review_field_inspection_evidence(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_field_inspection_evidence(p_inspection_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
  v_note text:=nullif(btrim(coalesce(p_note,'')),'');
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and role in ('staff','admin','creator')
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null then raise exception 'Property review access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then
    raise exception 'Property Operations permission required';
  end if;
  select * into v_request from public.inspection_requests
  where id=p_inspection_id for update;
  if v_request.id is null then raise exception 'Inspection not found'; end if;
  if v_actor.user_id=coalesce(v_request.assigned_field_officer_id,v_request.field_officer_id,v_request.assigned_to) then
    raise exception 'The Field Officer who submitted evidence cannot approve it';
  end if;
  if v_actor.role in ('staff','admin') and not public.current_actor_in_scope(v_request.property_state,v_request.property_city) then
    raise exception 'Property is outside your assigned branch';
  end if;
  if v_request.field_evidence_review_status<>'pending' then
    raise exception 'This Field Operations evidence is not awaiting review';
  end if;
  if p_decision='accept' then
    if cardinality(coalesce(v_request.field_photo_urls,'{}'))<4 then
      raise exception 'Four Field Operations photos are required before acceptance';
    end if;
    if nullif(btrim(coalesce(v_request.notes,'')),'') is null then
      raise exception 'A Field Operations report is required before acceptance';
    end if;
    update public.inspection_requests
    set field_evidence_review_status='accepted',field_evidence_reviewed_by=v_actor.user_id,
        field_evidence_reviewed_at=now(),field_evidence_review_note=v_note,
        rejection_reason=null,updated_at=now()
    where id=p_inspection_id;
  elsif p_decision='request_changes' then
    if v_note is null then raise exception 'Explain exactly what Field Operations must correct'; end if;
    update public.inspection_requests
    set status='in_progress',field_evidence_review_status='changes_requested',
        field_evidence_reviewed_by=v_actor.user_id,field_evidence_reviewed_at=now(),
        field_evidence_review_note=v_note,rejection_reason=v_note,updated_at=now()
    where id=p_inspection_id;
    if v_request.assigned_field_officer_id is not null then
      insert into public.notifications(
        recipient_id,type,title,message,related_id,source_type,source_id,
        destination_route,destination_params,event_key
      ) values(
        v_request.assigned_field_officer_id,'field_evidence_changes_requested',
        'Field evidence needs correction',v_note,v_request.id::text,
        'inspection_request',v_request.id::text,'field_inspections',
        jsonb_build_object('inspection_id',v_request.id),
        'field-evidence-correction:'||v_request.id::text||':'||extract(epoch from now())::bigint::text
      ) on conflict do nothing;
    end if;
  else
    raise exception 'Decision must be accept or request_changes';
  end if;
  return true;
end;
$$;


--
-- Name: review_my_staff_listing(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_my_staff_listing(p_listing_id uuid, p_decision text, p_reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_actor record; v_listing record; BEGIN SELECT user_id,role,assigned_state,assigned_lga,deleted,suspended,banned INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1; IF v_actor IS NULL OR COALESCE(v_actor.deleted,false) OR COALESCE(v_actor.suspended,false) OR COALESCE(v_actor.banned,false) THEN RAISE EXCEPTION 'Active staff account required'; END IF; IF v_actor.role='staff' AND NOT public.current_staff_has_permission('operations') THEN RAISE EXCEPTION 'Operations permission required'; END IF; IF v_actor.role NOT IN('staff','admin','creator') THEN RAISE EXCEPTION 'Staff access required'; END IF; SELECT * INTO v_listing FROM public.listings WHERE id=p_listing_id AND deleted_at IS NULL FOR UPDATE; IF v_listing IS NULL THEN RAISE EXCEPTION 'Listing not found'; END IF; IF v_actor.role='staff' AND NOT(v_actor.assigned_state IS NOT NULL AND lower(v_listing.state)=lower(v_actor.assigned_state) AND (v_actor.assigned_lga IS NULL OR lower(v_listing.city)=lower(v_actor.assigned_lga))) THEN RAISE EXCEPTION 'Listing is outside your assigned branch'; END IF; IF v_listing.status<>'pending_approval' THEN RAISE EXCEPTION 'Only pending listings can be reviewed'; END IF; IF p_decision='approve' THEN UPDATE public.listings SET status='available',availability_status='available',approved_by=v_actor.user_id,approved_at=now(),rejection_reason=NULL,updated_at=now() WHERE id=p_listing_id; ELSIF p_decision='reject' THEN IF NULLIF(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Rejection reason required'; END IF; UPDATE public.listings SET status='rejected',rejection_reason=btrim(p_reason),approved_by=NULL,approved_at=NULL,updated_at=now() WHERE id=p_listing_id; ELSE RAISE EXCEPTION 'Invalid review decision'; END IF; RETURN true; END; $$;


--
-- Name: review_my_staff_worker_v2(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_my_staff_worker_v2(p_worker_id text, p_status text, p_reason text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_worker public.profiles;
  v_ver public.worker_verifications;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_actor IS NULL OR v_actor.role<>'staff' OR COALESCE(v_actor.deleted,false) OR COALESCE(v_actor.suspended,false) OR COALESCE(v_actor.banned,false) THEN
    RAISE EXCEPTION 'Active Staff account required';
  END IF;
  IF NOT public.current_staff_has_permission('verification') THEN RAISE EXCEPTION 'Verification Staff permission required'; END IF;
  IF p_status NOT IN ('verified','rejected') THEN RAISE EXCEPTION 'Invalid review outcome'; END IF;
  IF p_status='rejected' AND NULLIF(BTRIM(COALESCE(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Rejection reason is required'; END IF;

  SELECT * INTO v_worker FROM public.profiles WHERE user_id=p_worker_id AND public.user_has_active_workspace(user_id,'worker') FOR UPDATE;
  IF v_worker IS NULL THEN RAISE EXCEPTION 'Worker not found'; END IF;
  IF v_actor.assigned_state IS NULL
     OR lower(COALESCE(v_worker.state,''))<>lower(v_actor.assigned_state)
     OR v_actor.assigned_lga IS NULL
     OR lower(COALESCE(v_worker.local_government,v_worker.city,''))<>lower(v_actor.assigned_lga) THEN
    RAISE EXCEPTION 'Worker is outside your assigned branch';
  END IF;

  SELECT * INTO v_ver FROM public.worker_verifications WHERE worker_id=p_worker_id LIMIT 1;
  IF p_status='verified' THEN
    IF v_worker.worker_status<>'profile_under_review' THEN RAISE EXCEPTION 'Worker is not in the review queue'; END IF;
    IF NOT public.worker_identity_is_current(p_worker_id) THEN RAISE EXCEPTION 'The current private face check has not passed'; END IF;
    IF v_ver IS NULL OR NULLIF(BTRIM(COALESCE(v_ver.verification_video_url,'')),'') IS NULL THEN
      RAISE EXCEPTION 'Professional work evidence is incomplete';
    END IF;
  END IF;

  UPDATE public.profiles
  SET worker_status=p_status,worker_verified=(p_status='verified'),available=(p_status='verified'),updated_at=now(),updated_by=v_actor.user_id
  WHERE user_id=p_worker_id;
  UPDATE public.worker_verifications
  SET status=p_status,reviewed_by=v_actor.user_id,
      review_notes=COALESCE(NULLIF(BTRIM(p_notes),''),NULLIF(BTRIM(p_reason),'')),
      reviewed_at=now(),updated_at=now()
  WHERE id=v_ver.id;
  INSERT INTO public.worker_verification_reviews(worker_id,reviewer_id,reviewer_role,action,rejection_reason,notes,created_at)
  VALUES(p_worker_id,v_actor.user_id,v_actor.role,p_status,
    CASE WHEN p_status='rejected' THEN BTRIM(p_reason) ELSE NULL END,
    NULLIF(BTRIM(COALESCE(p_notes,'')),''),now());
  RETURN true;
END;
$$;


--
-- Name: review_new_device_login(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_new_device_login(p_session_id uuid, p_was_me boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_auth_id text := (select auth.uid())::text;
  v_user_id text := public.current_profile_user_id();
  v_current_auth_session_id text := nullif((select auth.jwt() ->> 'session_id'), '');
  v_current public.user_sessions%rowtype;
  v_target public.user_sessions%rowtype;
begin
  if v_auth_id is null or v_user_id is null or v_current_auth_session_id is null then
    raise exception 'Authentication session is required';
  end if;

  select * into v_current
  from public.user_sessions
  where user_id = v_user_id
    and auth_id = v_auth_id
    and auth_session_id = v_current_auth_session_id
    and is_active = true
    and trust_status = 'trusted'
  limit 1;
  if not found then raise exception 'An active signed-in device is required'; end if;

  select * into v_target
  from public.user_sessions
  where id = p_session_id
    and user_id = v_user_id
    and auth_id = v_auth_id
  for update;
  if not found then raise exception 'Login session not found'; end if;
  if v_target.id = v_current.id or v_target.auth_session_id = v_current_auth_session_id then
    raise exception 'Review this notice from another signed-in device';
  end if;

  if not p_was_me then
    update public.user_sessions
    set trust_status = 'rejected',
        trust_reviewed_at = now(),
        trust_reviewed_by_session_id = v_current.id,
        is_active = false,
        is_current = false,
        logout_time = coalesce(logout_time, now())
    where id = v_target.id;
  end if;

  update public.notifications
  set title = case when p_was_me then 'Login recognized' else 'Unrecognized login ended' end,
      read = true,
      read_at = coalesce(read_at, now()),
      destination_params = coalesce(destination_params, '{}'::jsonb) || jsonb_build_object(
        'decision', case when p_was_me then 'recognized' else 'terminated' end
      )
  where recipient_id = v_user_id
    and type = 'new_device_login'
    and source_id = v_target.id::text;

  return jsonb_build_object(
    'session_id', v_target.id,
    'decision', case when p_was_me then 'recognized' else 'terminated' end
  );
end;
$$;


--
-- Name: review_property_access_evidence(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_property_access_evidence(p_request_id uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
  v_status text;
  v_override boolean;
begin
  select * into v_actor
  from public.profiles
  where auth_id=auth.uid()::text
    and role in ('staff','admin','creator')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;

  if v_actor is null or (v_actor.role='staff' and not public.current_staff_has_permission('operations')) then
    raise exception 'Operations Staff, Admin or Creator access required';
  end if;

  select * into v_request from public.inspection_requests where id=p_request_id for update;
  if v_request.id is null then raise exception 'Property request not found'; end if;
  if v_actor.role<>'creator' and not public.current_actor_in_scope(v_request.property_state,v_request.property_city) then
    raise exception 'Property is outside your assigned area';
  end if;
  if v_request.access_evidence_video_path is null then raise exception 'No private access recording to review'; end if;
  if p_decision not in ('accept','reject') then raise exception 'Choose accept or reject'; end if;
  if p_decision='reject' and nullif(btrim(coalesce(p_note,'')),'') is null then
    raise exception 'Explain what the Property Partner must record again';
  end if;

  v_override := v_request.access_evidence_status in ('verified','rejected');
  if v_override and coalesce(v_request.assigned_field_officer_id,v_request.field_officer_id,v_request.assigned_to) is not null then
    raise exception 'Access evidence cannot be overridden after a Field Officer has been assigned';
  end if;
  if v_actor.role='staff' and v_request.access_evidence_status<>'submitted' then
    raise exception 'Admin or Creator authority is required to override an evidence decision';
  end if;
  if v_actor.role in ('admin','creator') and v_request.access_evidence_status not in ('submitted','verified','rejected') then
    raise exception 'No submitted evidence decision is available';
  end if;

  v_status:=case when p_decision='accept' then 'verified' else 'rejected' end;
  update public.inspection_requests
  set access_evidence_status=v_status,
      access_evidence_verified_at=case when v_status='verified' then now() else null end,
      access_evidence_verified_by=case when v_status='verified' then v_actor.user_id else null end,
      rejection_reason=case when v_status='rejected' then btrim(p_note) else null end,
      updated_at=now()
  where id=p_request_id;

  insert into public.audit_logs(action,target_type,target_id,details,admin_id,admin_email)
  values(
    case when v_override then 'PROPERTY_ACCESS_EVIDENCE_OVERRIDDEN'
         when v_status='verified' then 'PROPERTY_ACCESS_EVIDENCE_ACCEPTED'
         else 'PROPERTY_ACCESS_EVIDENCE_REJECTED' end,
    'inspection_requests',p_request_id::text,
    jsonb_build_object(
      'decision',p_decision,
      'note',nullif(btrim(coalesce(p_note,'')),''),
      'previous_status',v_request.access_evidence_status,
      'reviewer_role',v_actor.role
    )::text,
    v_actor.user_id,v_actor.email
  );
  return jsonb_build_object('success',true,'status',v_status,'override',v_override);
end;
$$;


--
-- Name: save_my_hotel(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_my_hotel(p_hotel_id integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_user_id text := public.current_profile_user_id();
begin
  if v_user_id is null then raise exception 'Authenticated profile required'; end if;
  if not exists(
    select 1 from public.hotels h
    where h.hotel_id = p_hotel_id and h.status = 'active' and h.approved_at is not null and h.published_at is not null
  ) then raise exception 'This hotel is not available to save'; end if;
  insert into public.saved_hotels(user_id, hotel_id) values(v_user_id, p_hotel_id)
  on conflict(user_id, hotel_id) do nothing;
  return true;
end;
$$;


--
-- Name: save_my_property_search(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_my_property_search(p_name text, p_search_kind text, p_criteria jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_result uuid;
  v_criteria jsonb:=public.canonical_saved_search_criteria(coalesce(p_criteria,'{}'::jsonb));
  v_key text;
begin
  if v_actor is null then raise exception 'Authenticated profile required'; end if;
  if p_search_kind not in ('homes','hotels') then raise exception 'Unsupported saved search'; end if;
  if nullif(btrim(p_name),'') is null then raise exception 'Saved search name is required'; end if;
  v_key:=md5(v_criteria::text);
  insert into public.saved_searches(
    user_id,name,search_kind,criteria,criteria_key,notifications_enabled
  ) values(
    v_actor,btrim(p_name),p_search_kind,v_criteria,v_key,true
  )
  on conflict(user_id,search_kind,criteria_key) do update
  set name=excluded.name,criteria=excluded.criteria,
      notifications_enabled=true,updated_at=now()
  returning id into v_result;
  return v_result;
end;
$$;


--
-- Name: save_my_roommate_preferences(text, text, integer, integer, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_my_roommate_preferences(p_gender text, p_gender_preference text, p_budget_min integer, p_budget_max integer, p_cleanliness text, p_noise_level text, p_sleep_time text, p_visitors text, p_stay_duration text, p_area_preference text DEFAULT NULL::text, p_bio text DEFAULT NULL::text, p_school_name text DEFAULT NULL::text, p_campus text DEFAULT NULL::text, p_level text DEFAULT NULL::text, p_department text DEFAULT NULL::text) RETURNS public.roommate_preferences
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_row public.roommate_preferences; v_allowed boolean;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_actor IS NULL OR not public.current_actor_has_personal_workspace() THEN RAISE EXCEPTION 'Roommate matching is available to regular users only'; END IF;
  IF COALESCE(v_actor.deleted,false) OR COALESCE(v_actor.suspended,false) OR COALESCE(v_actor.banned,false) THEN RAISE EXCEPTION 'Account is not active'; END IF;
  IF NOT COALESCE(v_actor.profile_complete,false) THEN RAISE EXCEPTION 'Complete your profile first'; END IF;
  IF NULLIF(BTRIM(COALESCE(p_gender,'')),'') IS NULL THEN RAISE EXCEPTION 'Gender is required'; END IF;
  IF NULLIF(BTRIM(COALESCE(v_actor.state,'')),'') IS NULL THEN RAISE EXCEPTION 'Add your State first'; END IF;
  IF p_gender_preference NOT IN ('male','female','no_preference') THEN RAISE EXCEPTION 'Invalid roommate gender preference'; END IF;
  IF p_budget_min < 180000 THEN RAISE EXCEPTION 'Minimum roommate budget is NGN 180,000'; END IF;
  IF p_budget_max < p_budget_min THEN RAISE EXCEPTION 'Maximum budget must be at least the minimum budget'; END IF;
  v_allowed := COALESCE(v_actor.privacy_search_visible,true) AND COALESCE(v_actor.privacy_profile_visible,true);
  INSERT INTO public.roommate_preferences(user_id,auth_id,gender,gender_preference,budget_min,budget_max,cleanliness,noise_level,sleep_time,visitors,stay_duration,area_preference,bio,school_name,campus,level,department,active,search_status,search_started_at,search_expires_at,created_at,updated_at)
  VALUES(v_actor.user_id,v_actor.auth_id,BTRIM(p_gender),p_gender_preference,p_budget_min,p_budget_max,p_cleanliness,p_noise_level,p_sleep_time,p_visitors,p_stay_duration,NULLIF(BTRIM(COALESCE(p_area_preference,'')),''),NULLIF(BTRIM(COALESCE(p_bio,'')),''),NULLIF(BTRIM(COALESCE(p_school_name,'')),''),NULLIF(BTRIM(COALESCE(p_campus,'')),''),NULLIF(BTRIM(COALESCE(p_level,'')),''),NULLIF(BTRIM(COALESCE(p_department,'')),''),v_allowed,CASE WHEN v_allowed THEN 'active' ELSE 'stopped' END,CASE WHEN v_allowed THEN now() ELSE NULL END,NULL,now(),now())
  ON CONFLICT(user_id) DO UPDATE SET gender=EXCLUDED.gender,gender_preference=EXCLUDED.gender_preference,budget_min=EXCLUDED.budget_min,budget_max=EXCLUDED.budget_max,cleanliness=EXCLUDED.cleanliness,noise_level=EXCLUDED.noise_level,sleep_time=EXCLUDED.sleep_time,visitors=EXCLUDED.visitors,stay_duration=EXCLUDED.stay_duration,area_preference=EXCLUDED.area_preference,bio=EXCLUDED.bio,school_name=EXCLUDED.school_name,campus=EXCLUDED.campus,level=EXCLUDED.level,department=EXCLUDED.department,active=CASE WHEN public.roommate_preferences.search_status='stopped' THEN false ELSE v_allowed END,search_status=CASE WHEN public.roommate_preferences.search_status='stopped' THEN 'stopped' WHEN v_allowed THEN 'active' ELSE 'stopped' END,search_started_at=CASE WHEN public.roommate_preferences.search_status='stopped' OR NOT v_allowed THEN public.roommate_preferences.search_started_at ELSE COALESCE(public.roommate_preferences.search_started_at,now()) END,search_expires_at=NULL,updated_at=now()
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


--
-- Name: save_my_worker_professional_evidence(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_my_worker_professional_evidence(p_certificate_path text, p_video_path text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_profile public.profiles;
  v_identity_required boolean:=false;
  v_id uuid;
begin
  select * into v_profile
  from public.profiles
  where auth_id=(select auth.uid())::text
    and public.user_has_active_workspace(user_id,'worker')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_profile is null then raise exception 'Active Worker account required'; end if;
  if v_profile.worker_status='verified' then raise exception 'Live Worker evidence changes require a new review process'; end if;
  if not public.worker_professional_profile_ready(v_profile.user_id) then
    raise exception 'Complete your professional profile and service coverage first';
  end if;
  select coalesce(lower(btrim(value)) in ('true','1','yes','on'),false)
    into v_identity_required
  from public.platform_settings
  where key='worker_identity_checks_enabled' and coalesce(is_active,true)
  limit 1;
  if coalesce(v_identity_required,false) and not public.worker_identity_is_current(v_profile.user_id) then
    raise exception 'Complete the approved private identity check first';
  end if;
  if nullif(btrim(coalesce(p_video_path,'')),'') is null then raise exception 'Skill demonstration video is required'; end if;
  if split_part(p_video_path,'/',1)<>v_profile.user_id then raise exception 'Invalid Worker video path'; end if;
  if nullif(btrim(coalesce(p_certificate_path,'')),'') is not null
     and split_part(p_certificate_path,'/',1)<>v_profile.user_id then
    raise exception 'Invalid Worker certificate path';
  end if;

  insert into public.worker_verifications(
    worker_id,certificate_path,verification_video_url,status,submitted_at,created_at,updated_at
  ) values(
    v_profile.user_id,nullif(btrim(coalesce(p_certificate_path,'')),''),btrim(p_video_path),
    'evidence_ready',null,now(),now()
  )
  on conflict(worker_id) do update set
    certificate_path=excluded.certificate_path,
    verification_video_url=excluded.verification_video_url,
    status='evidence_ready',
    submitted_at=null,
    reviewed_by=null,
    review_notes=null,
    reviewed_at=null,
    updated_at=now()
  returning id into v_id;

  update public.profiles
  set worker_status='pending',worker_verified=false,available=false,
      worker_cert_url=nullif(btrim(coalesce(p_certificate_path,'')),''),
      worker_video_url=btrim(p_video_path),updated_at=now()
  where user_id=v_profile.user_id;
  return v_id;
end;
$$;


--
-- Name: save_my_worker_work_document(uuid, uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_my_worker_work_document(p_document_id uuid, p_booking_id uuid, p_document_type text, p_title text, p_items jsonb, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_worker text;
  v_booking public.worker_bookings;
  v_existing public.worker_work_documents;
  v_kind text:=lower(btrim(coalesce(p_document_type,'')));
  v_title text:=btrim(coalesce(p_title,''));
  v_note text:=nullif(btrim(coalesce(p_note,'')),'');
  v_item jsonb;
  v_description text;
  v_quantity numeric;
  v_unit_price numeric;
  v_items jsonb:='[]'::jsonb;
  v_total numeric:=0;
  v_id uuid;
  v_number text;
begin
  select profile.user_id into v_worker from public.profiles profile
  where profile.auth_id=(select auth.uid())::text
    and public.user_has_active_workspace(profile.user_id,'worker')
    and not coalesce(profile.deleted,false)
    and not coalesce(profile.suspended,false)
    and not coalesce(profile.banned,false) limit 1;
  if v_worker is null then raise exception 'Active Worker workspace required'; end if;
  if not public.worker_pro_is_active(v_worker) then
    raise exception 'An active paid Worker plan is required to create or edit documents';
  end if;
  if v_kind not in('quote','invoice') then raise exception 'Choose quote or invoice'; end if;
  if length(v_title)<2 or length(v_title)>120 then raise exception 'Document title must be between 2 and 120 characters'; end if;
  if v_note is not null and length(v_note)>1200 then raise exception 'Document note is too long'; end if;
  if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 20 then
    raise exception 'Add between 1 and 20 line items';
  end if;
  select * into v_booking from public.worker_bookings
  where id=p_booking_id and worker_id=v_worker limit 1;
  if v_booking.id is null then raise exception 'Choose one of your WeHouse jobs'; end if;
  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_description:=btrim(coalesce(v_item->>'description',''));
    if length(v_description)<2 or length(v_description)>160 then
      raise exception 'Each line needs a description between 2 and 160 characters';
    end if;
    begin
      v_quantity:=coalesce(nullif(v_item->>'quantity','')::numeric,1);
      v_unit_price:=coalesce(nullif(v_item->>'unit_price','')::numeric,0);
    exception when invalid_text_representation or numeric_value_out_of_range then
      raise exception 'Line quantity and price must be valid numbers';
    end;
    if v_quantity<=0 or v_quantity>10000 or v_unit_price<0 or v_unit_price>10000000 then
      raise exception 'Line quantity or price is outside the allowed range';
    end if;
    v_quantity:=round(v_quantity,2);
    v_unit_price:=round(v_unit_price,2);
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'description',v_description,'quantity',v_quantity,
      'unit_price',v_unit_price,'line_total',round(v_quantity*v_unit_price,2)
    ));
    v_total:=v_total+round(v_quantity*v_unit_price,2);
  end loop;
  if v_total>100000000 then raise exception 'Document total is too large'; end if;

  if p_document_id is null then
    v_number:=case when v_kind='quote' then 'WHQ-' else 'WHI-' end
      ||upper(substring(replace(gen_random_uuid()::text,'-','') from 1 for 10));
    insert into public.worker_work_documents(
      document_number,worker_id,customer_id,booking_id,document_type,title,
      items,subtotal,total,payment_status,note,created_at,updated_at
    ) values(
      v_number,v_worker,v_booking.user_id,v_booking.id,v_kind,v_title,
      v_items,v_total,v_total,case when v_kind='invoice' then 'unpaid'
        else 'not_applicable' end,v_note,now(),now()
    ) returning id into v_id;
  else
    select * into v_existing from public.worker_work_documents
    where id=p_document_id and worker_id=v_worker for update;
    if v_existing.id is null then raise exception 'Document not found'; end if;
    if v_existing.document_status<>'draft' then
      raise exception 'Only a draft document can be edited';
    end if;
    update public.worker_work_documents set
      customer_id=v_booking.user_id,booking_id=v_booking.id,
      document_type=v_kind,title=v_title,items=v_items,subtotal=v_total,
      total=v_total,payment_status=case when v_kind='invoice' then 'unpaid'
        else 'not_applicable' end,note=v_note,updated_at=now()
    where id=v_existing.id returning id into v_id;
  end if;
  return v_id;
end;
$$;


--
-- Name: save_verified_payout_account(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_verified_payout_account(p_user_id text, p_bank_code text, p_bank_name text, p_account_number text, p_account_name text, p_recipient_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_claim_role text:=coalesce(current_setting('request.jwt.claim.role',true),'');
  v_profile public.profiles;
  v_owner_type text;
  v_account public.bank_accounts;
  v_existing_count integer:=0;
  v_profile_tokens text[];
  v_account_tokens text[];
  v_match_count integer:=0;
  v_is_first boolean:=false;
begin
  if v_claim_role<>'service_role' then raise exception 'Service role required'; end if;
  select * into v_profile
  from public.profiles
  where user_id=p_user_id
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  for update;
  if v_profile is null then raise exception 'Active professional account required'; end if;
  v_owner_type:=case
    when v_profile.role in ('worker','property_partner') then v_profile.role
    when public.user_has_active_workspace(p_user_id,'worker') then 'worker'
    when public.user_has_active_workspace(p_user_id,'property_partner')
      then 'property_partner'
    else null
  end;
  if v_owner_type is null then
    raise exception 'Worker or Property Partner workspace required';
  end if;
  if coalesce(btrim(p_bank_code),'')=''
     or coalesce(btrim(p_bank_name),'')='' then
    raise exception 'Verified bank is required';
  end if;
  if coalesce(btrim(p_account_number),'') !~ '^[0-9]{10}$' then
    raise exception 'Bank account number must contain 10 digits';
  end if;
  if coalesce(btrim(p_account_name),'')='' then
    raise exception 'Verified account name is required';
  end if;
  select * into v_account
  from public.bank_accounts
  where user_id=p_user_id
    and bank_code=btrim(p_bank_code)
    and account_number=btrim(p_account_number)
  limit 1;
  if v_account is not null then
    update public.bank_accounts
    set bank_name=btrim(p_bank_name),
        account_name=btrim(p_account_name),
        paystack_recipient_code=coalesce(
          nullif(btrim(coalesce(p_recipient_code,'')),''),
          paystack_recipient_code
        ),
        verified_at=coalesce(verified_at,now())
    where id=v_account.id
    returning * into v_account;
    return jsonb_build_object(
      'success',true,'already_saved',true,
      'first_account',coalesce(v_account.is_default,false),
      'additional_account',not coalesce(v_account.is_default,false),
      'name_match_count',null,
      'account',jsonb_build_object(
        'id',v_account.id,'bank_name',v_account.bank_name,
        'bank_code',v_account.bank_code,
        'account_number',v_account.account_number,
        'account_name',v_account.account_name,
        'is_default',coalesce(v_account.is_default,false),
        'verified_at',v_account.verified_at
      )
    );
  end if;
  select count(*)::integer into v_existing_count
  from public.bank_accounts where user_id=p_user_id;
  v_is_first:=v_existing_count=0;
  if not v_is_first then
    if coalesce(btrim(v_profile.full_name),'')='' then
      raise exception 'Complete your WeHouse full name before adding another payout account';
    end if;
    select array(
      select distinct token
      from unnest(regexp_split_to_array(
        lower(regexp_replace(v_profile.full_name,'[^a-zA-Z0-9 ]',' ','g')),
        '\s+'
      )) token
      where length(token)>1
        and token not in (
          'mr','mrs','miss','ms','dr','chief','alhaji','hajiya','hon',
          'prof','sir','madam'
        )
    ) into v_profile_tokens;
    select array(
      select distinct token
      from unnest(regexp_split_to_array(
        lower(regexp_replace(p_account_name,'[^a-zA-Z0-9 ]',' ','g')),
        '\s+'
      )) token
      where length(token)>1
        and token not in (
          'mr','mrs','miss','ms','dr','chief','alhaji','hajiya','hon',
          'prof','sir','madam'
        )
    ) into v_account_tokens;
    if coalesce(cardinality(v_profile_tokens),0)<2 then
      raise exception 'Your WeHouse full name must contain at least two names before adding another payout account';
    end if;
    select count(distinct token)::integer into v_match_count
    from unnest(v_profile_tokens) token
    where token=any(v_account_tokens);
    if v_match_count<2 then
      raise exception 'The verified bank account name must match at least two names from your WeHouse full name';
    end if;
  end if;
  insert into public.bank_accounts(
    user_id,account_number,bank_code,bank_name,account_name,
    paystack_recipient_code,is_default,verified_at,created_at
  ) values(
    p_user_id,btrim(p_account_number),btrim(p_bank_code),btrim(p_bank_name),
    btrim(p_account_name),nullif(btrim(coalesce(p_recipient_code,'')),''),
    v_is_first,now(),now()
  ) returning * into v_account;
  if v_is_first then
    update public.wallets
    set bank_name=v_account.bank_name,
        bank_account_number=v_account.account_number,
        bank_account_name=v_account.account_name,
        paystack_recipient_code=v_account.paystack_recipient_code,
        updated_at=now()
    where owner_id=p_user_id and owner_type=v_owner_type;
  end if;
  insert into public.bank_account_history(
    user_id,bank_name,bank_code,bank_account_number,bank_account_name,
    verified_account_name,is_verified,changed_at,changed_by
  ) values(
    p_user_id,v_account.bank_name,v_account.bank_code,
    v_account.account_number,v_account.account_name,v_account.account_name,
    true,now(),p_user_id
  );
  insert into public.financial_audit_logs(
    event_type,user_id,target_user_id,reference_id,reference_type,
    description,metadata,created_at
  ) values(
    'bank_account_change',p_user_id,p_user_id,v_account.id::text,
    'bank_account',case when v_is_first
      then 'First verified payout account added'
      else 'Additional verified payout account added' end,
    jsonb_build_object(
      'bank_name',v_account.bank_name,
      'account_last4',right(v_account.account_number,4),
      'account_name',v_account.account_name,
      'first_account',v_is_first,
      'matching_name_tokens',case when v_is_first then null
        else v_match_count end,
      'workspace',v_owner_type
    ),now()
  );
  return jsonb_build_object(
    'success',true,'already_saved',false,'first_account',v_is_first,
    'additional_account',not v_is_first,'name_match_count',v_match_count,
    'account',jsonb_build_object(
      'id',v_account.id,'bank_name',v_account.bank_name,
      'bank_code',v_account.bank_code,
      'account_number',v_account.account_number,
      'account_name',v_account.account_name,
      'is_default',v_account.is_default,
      'verified_at',v_account.verified_at
    )
  );
end
$_$;


--
-- Name: send_booking_message(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_booking_message(p_conversation_id uuid, p_content text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_sender_id text;
  v_peer_id text;
  v_booking_id uuid;
  v_booking_status text;
  v_msg_id uuid;
begin
  select user_id into v_sender_id
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_sender_id is null then raise exception 'Sender profile not found'; end if;

  select c.booking_id,case when c.user_id=v_sender_id then c.worker_id else c.user_id end,b.status
  into v_booking_id,v_peer_id,v_booking_status
  from public.booking_conversations c
  join public.worker_bookings b on b.id=c.booking_id
  where c.id=p_conversation_id and v_sender_id in(c.user_id,c.worker_id)
  limit 1;
  if v_booking_id is null then raise exception 'Conversation not found'; end if;
  if v_booking_status in('approved_released','cancelled','refunded') then raise exception 'This job conversation is closed'; end if;
  if exists(
    select 1 from public.worker_user_blocks block_row
    where (block_row.blocker_user_id=v_sender_id and block_row.blocked_user_id=v_peer_id)
       or (block_row.blocker_user_id=v_peer_id and block_row.blocked_user_id=v_sender_id)
  ) then raise exception 'This service conversation is blocked'; end if;
  insert into public.booking_messages(conversation_id,sender_id,content,created_at)
  values(p_conversation_id,v_sender_id,p_content,now()) returning id into v_msg_id;
  update public.booking_conversations set updated_at=now() where id=p_conversation_id;
  return v_msg_id;
end;
$$;


--
-- Name: send_booking_message_v2(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_booking_message_v2(p_conversation_id uuid, p_content text DEFAULT ''::text, p_attachments text[] DEFAULT '{}'::text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles;v_conv public.booking_conversations;v_booking public.worker_bookings;v_msg_id uuid;v_path text;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND coalesce(deleted,false)=false AND coalesce(suspended,false)=false AND coalesce(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO v_conv FROM public.booking_conversations WHERE id=p_conversation_id;
  IF v_conv IS NULL THEN RAISE EXCEPTION 'Conversation not found'; END IF;
  IF v_actor.user_id NOT IN (v_conv.user_id,v_conv.worker_id) THEN RAISE EXCEPTION 'Not authorized to send messages in this conversation'; END IF;
  SELECT * INTO v_booking FROM public.worker_bookings WHERE id=v_conv.booking_id FOR UPDATE;
  IF v_booking IS NULL THEN RAISE EXCEPTION 'Booking not found'; END IF;
  IF v_booking.status IN ('approved_released','cancelled','refunded') THEN RAISE EXCEPTION 'This job conversation is closed'; END IF;
  IF nullif(btrim(coalesce(p_content,'')),'') IS NULL AND coalesce(cardinality(p_attachments),0)=0 THEN RAISE EXCEPTION 'Message or attachment is required'; END IF;
  IF coalesce(cardinality(p_attachments),0)>6 THEN RAISE EXCEPTION 'A maximum of 6 attachments can be sent at once'; END IF;
  FOREACH v_path IN ARRAY coalesce(p_attachments,'{}'::text[]) LOOP IF position(p_conversation_id::text||'/' IN coalesce(v_path,''))<>1 THEN RAISE EXCEPTION 'Invalid attachment path'; END IF; END LOOP;
  INSERT INTO public.booking_messages(conversation_id,sender_id,content,attachments,created_at) VALUES(p_conversation_id,v_actor.user_id,coalesce(btrim(p_content),''),coalesce(p_attachments,'{}'::text[]),now()) RETURNING id INTO v_msg_id;
  IF v_actor.user_id=v_conv.worker_id AND v_booking.status='booking_requested' THEN UPDATE public.worker_bookings SET status='negotiating',updated_at=now() WHERE id=v_booking.id; END IF;
  UPDATE public.booking_conversations SET updated_at=now() WHERE id=p_conversation_id;
  RETURN v_msg_id;
END;
$$;


--
-- Name: send_canonical_thread_message(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_canonical_thread_message(p_thread_id uuid, p_body text, p_client_message_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user text:=public.current_profile_user_id();
  v_thread public.canonical_threads;
  v_id uuid;
begin
  select * into v_thread from public.canonical_threads
  where thread_id=p_thread_id and state='open';
  if not exists(
    select 1 from public.canonical_thread_participants p
    where p.thread_id=p_thread_id and p.user_id=v_user
      and p.left_at is null and p.can_message
  ) then raise exception 'Messaging is not available in this thread'; end if;
  if exists(
    select 1
    from public.canonical_thread_participants mine
    join public.canonical_thread_participants peer
      on peer.thread_id=mine.thread_id and peer.user_id<>mine.user_id
    where mine.thread_id=p_thread_id and mine.user_id=v_user
      and (
        exists(select 1 from public.roommate_user_blocks b
          where (b.blocker_user_id=mine.user_id and b.blocked_user_id=peer.user_id)
             or (b.blocker_user_id=peer.user_id and b.blocked_user_id=mine.user_id))
        or exists(select 1 from public.worker_user_blocks b
          where (b.blocker_user_id=mine.user_id and b.blocked_user_id=peer.user_id)
             or (b.blocker_user_id=peer.user_id and b.blocked_user_id=mine.user_id))
      )
  ) then raise exception 'Communication is blocked'; end if;
  insert into public.canonical_thread_items(
    thread_id,item_type,sender_user_id,body,event_key
  ) values(
    p_thread_id,'message',v_user,btrim(p_body),
    'client_message:'||v_user||':'||p_client_message_id
  ) on conflict(event_key) do update set event_key=excluded.event_key
  returning thread_item_id into v_id;
  return v_id;
end
$$;


--
-- Name: send_hotel_booking_message(uuid, text, text[], text[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_hotel_booking_message(p_conversation_id uuid, p_content text DEFAULT ''::text, p_attachments text[] DEFAULT '{}'::text[], p_attachment_types text[] DEFAULT '{}'::text[], p_reply_to_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text;
  v_message_id uuid;
  v_booking public.hotel_bookings;
begin
  select profile.user_id into v_actor from public.profiles profile
  where profile.auth_id=(select auth.uid())::text
    and not coalesce(profile.deleted,false)
    and not coalesce(profile.suspended,false)
    and not coalesce(profile.banned,false)
  limit 1;
  if v_actor is null
     or not public.can_access_hotel_booking_conversation(p_conversation_id) then
    raise exception 'Hotel conversation access denied';
  end if;
  select booking.* into v_booking
  from public.hotel_booking_conversations conversation
  join public.hotel_bookings booking on booking.booking_id=conversation.booking_id
  where conversation.id=p_conversation_id
  for share of booking;
  if v_booking.payment_status<>'paid'
     or v_booking.status not in ('confirmed','checked_in') then
    raise exception 'This stay conversation closed at checkout';
  end if;
  if nullif(btrim(coalesce(p_content,'')),'') is null
     and cardinality(coalesce(p_attachments,'{}'))=0 then
    raise exception 'Write a message or attach a file';
  end if;
  if cardinality(coalesce(p_attachments,'{}'))
       <>cardinality(coalesce(p_attachment_types,'{}'))
     or cardinality(coalesce(p_attachments,'{}'))>6 then
    raise exception 'Invalid attachments';
  end if;
  if exists(
    select 1 from unnest(coalesce(p_attachments,'{}')) path
    where split_part(path,'/',1)<>p_conversation_id::text
       or split_part(path,'/',2)<>v_actor
  ) then raise exception 'Invalid private hotel attachment path'; end if;
  if p_reply_to_id is not null and not exists(
    select 1 from public.hotel_booking_messages message
    where message.id=p_reply_to_id and message.conversation_id=p_conversation_id
      and not v_actor=any(coalesce(message.hidden_for,'{}'::text[]))
  ) then raise exception 'Reply target is not in this conversation'; end if;
  insert into public.hotel_booking_messages(
    conversation_id,sender_id,content,attachments,attachment_types,reply_to_id
  ) values(
    p_conversation_id,v_actor,btrim(coalesce(p_content,'')),
    coalesce(p_attachments,'{}'),coalesce(p_attachment_types,'{}'),p_reply_to_id
  ) returning id into v_message_id;
  update public.hotel_booking_conversations set updated_at=now()
  where id=p_conversation_id;
  return v_message_id;
end;
$$;


--
-- Name: messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    conversation_id uuid NOT NULL,
    sender_id text NOT NULL,
    content text NOT NULL,
    seen boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT now(),
    edited_at timestamp with time zone,
    file_url text,
    file_name text,
    file_type text,
    attachments text[] DEFAULT '{}'::text[] NOT NULL,
    attachment_types text[] DEFAULT '{}'::text[] NOT NULL,
    hidden_for text[] DEFAULT '{}'::text[] NOT NULL,
    ciphertext text,
    encryption_iv text,
    encryption_version integer,
    encrypted_attachments jsonb,
    reply_to_id uuid,
    reactions jsonb DEFAULT '{}'::jsonb NOT NULL,
    item_type text DEFAULT 'message'::text NOT NULL,
    item_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT messages_item_type_check CHECK ((item_type = ANY (ARRAY['message'::text, 'property_share'::text])))
);


--
-- Name: send_my_roommate_message(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_my_roommate_message(p_conversation_id uuid, p_content text) RETURNS public.messages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a public.profiles; m public.messages;
begin
  select * into a from public.profiles where auth_id=auth.uid()::text limit 1;
  if a is null or not public.current_actor_has_personal_workspace() then raise exception 'Regular user account required'; end if;
  if not public._can_access_conversation(p_conversation_id) then raise exception 'Roommate conversation unavailable'; end if;
  if nullif(btrim(p_content),'') is null then raise exception 'Message is required'; end if;
  insert into public.messages(conversation_id,sender_id,content,seen,created_at)
  values(p_conversation_id,a.user_id,btrim(p_content),false,now()) returning * into m;
  return m;
end $$;


--
-- Name: send_my_roommate_message_v2(uuid, text, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_my_roommate_message_v2(p_conversation_id uuid, p_content text DEFAULT ''::text, p_attachments text[] DEFAULT '{}'::text[], p_attachment_types text[] DEFAULT '{}'::text[]) RETURNS public.messages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  actor public.profiles;
  conv public.conversations;
  outgoing public.messages;
  peer_id text;
  attachment_path text;
  attachment_type text;
  i integer;
begin
  actor := public._current_comm_actor();
  if actor is null or not public.current_actor_has_personal_workspace() then raise exception 'Regular user account required'; end if;
  select * into conv from public.conversations where id = p_conversation_id;
  if conv is null or conv.conversation_type <> 'roommate'
     or actor.user_id not in (conv.participant_a, conv.participant_b)
     or not public._can_access_conversation(p_conversation_id) then
    raise exception 'Roommate conversation unavailable';
  end if;
  peer_id := case when conv.participant_a = actor.user_id then conv.participant_b else conv.participant_a end;
  if exists (
    select 1 from public.roommate_user_blocks b
    where (b.blocker_user_id = actor.user_id and b.blocked_user_id = peer_id)
       or (b.blocker_user_id = peer_id and b.blocked_user_id = actor.user_id)
  ) then
    raise exception 'Messages are blocked in this conversation';
  end if;
  if nullif(btrim(coalesce(p_content, '')), '') is null and coalesce(cardinality(p_attachments), 0) = 0 then
    raise exception 'Message, photo or voice note is required';
  end if;
  if coalesce(cardinality(p_attachments), 0) > 6 then raise exception 'A maximum of 6 attachments can be sent at once'; end if;
  if coalesce(cardinality(p_attachments), 0) <> coalesce(cardinality(p_attachment_types), 0) then raise exception 'Attachment metadata mismatch'; end if;
  if coalesce(cardinality(p_attachments), 0) > 0 then
    for i in 1..cardinality(p_attachments) loop
      attachment_path := p_attachments[i]; attachment_type := coalesce(p_attachment_types[i], '');
      if attachment_path is null or attachment_path not like p_conversation_id::text || '/%' then raise exception 'Invalid attachment path'; end if;
      if attachment_type not like 'image/%' and attachment_type not like 'audio/%' then raise exception 'Roommate chat supports photos and voice notes only'; end if;
    end loop;
  end if;
  insert into public.messages(conversation_id, sender_id, content, seen, created_at, attachments, attachment_types)
  values(p_conversation_id, actor.user_id, coalesce(btrim(p_content), ''), false, now(), coalesce(p_attachments, '{}'::text[]), coalesce(p_attachment_types, '{}'::text[]))
  returning * into outgoing;
  return outgoing;
end;
$$;


--
-- Name: send_my_worker_work_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_my_worker_work_document(p_document_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_worker text;
begin
  select profile.user_id into v_worker from public.profiles profile
  where profile.auth_id=(select auth.uid())::text
    and public.user_has_active_workspace(profile.user_id,'worker') limit 1;
  if v_worker is null or not public.worker_pro_is_active(v_worker) then
    raise exception 'An active paid Worker plan is required to send documents';
  end if;
  update public.worker_work_documents set document_status='sent',sent_at=now(),updated_at=now()
  where id=p_document_id and worker_id=v_worker and document_status='draft';
  return found;
end;
$$;


--
-- Name: send_private_encrypted_message(text, uuid, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_private_encrypted_message(p_conversation_kind text, p_conversation_id uuid, p_ciphertext text, p_encryption_iv text, p_encrypted_attachments jsonb DEFAULT '[]'::jsonb, p_reply_to_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor text:=public.current_profile_user_id();
  peer text;
  message_id uuid;
begin
  if actor is null then raise exception 'Active WeHouse profile required'; end if;
  if nullif(p_ciphertext,'') is null or nullif(p_encryption_iv,'') is null then raise exception 'Encrypted payload is required'; end if;

  if p_conversation_kind='roommate' then
    select case when c.participant_a=actor then c.participant_b else c.participant_a end
    into peer
    from public.conversations c
    where c.id=p_conversation_id
      and actor in(c.participant_a,c.participant_b)
      and c.conversation_type='roommate'
      and coalesce(c.status,'active')='active'
    limit 1;
    if peer is null then raise exception 'Conversation access denied'; end if;
    if exists(
      select 1 from public.roommate_user_blocks block_row
      where (block_row.blocker_user_id=actor and block_row.blocked_user_id=peer)
         or (block_row.blocker_user_id=peer and block_row.blocked_user_id=actor)
    ) then raise exception 'This roommate connection is blocked'; end if;
    if p_reply_to_id is not null and not exists(
      select 1 from public.messages where id=p_reply_to_id and conversation_id=p_conversation_id
    ) then raise exception 'Reply target is not in this conversation'; end if;
    insert into public.messages(conversation_id,sender_id,content,ciphertext,encryption_iv,encryption_version,encrypted_attachments,reply_to_id)
    values(p_conversation_id,actor,'[Encrypted message]',p_ciphertext,p_encryption_iv,1,coalesce(p_encrypted_attachments,'[]'::jsonb),p_reply_to_id)
    returning id into message_id;
    update public.conversations
    set last_message='Encrypted message',last_message_at=now(),
      unread_a=case when participant_a=actor then unread_a else coalesce(unread_a,0)+1 end,
      unread_b=case when participant_b=actor then unread_b else coalesce(unread_b,0)+1 end
    where id=p_conversation_id;

  elsif p_conversation_kind='worker' then
    select case when c.user_id=actor then c.worker_id else c.user_id end
    into peer
    from public.booking_conversations c
    join public.worker_bookings b on b.id=c.booking_id
    where c.id=p_conversation_id
      and actor in(c.user_id,c.worker_id)
      and b.status not in('approved_released','cancelled','refunded')
    limit 1;
    if peer is null then raise exception 'This job conversation is closed'; end if;
    if exists(
      select 1 from public.worker_user_blocks block_row
      where (block_row.blocker_user_id=actor and block_row.blocked_user_id=peer)
         or (block_row.blocker_user_id=peer and block_row.blocked_user_id=actor)
    ) then raise exception 'This service conversation is blocked'; end if;
    if p_reply_to_id is not null and not exists(
      select 1 from public.booking_messages where id=p_reply_to_id and conversation_id=p_conversation_id
    ) then raise exception 'Reply target is not in this conversation'; end if;
    insert into public.booking_messages(conversation_id,sender_id,content,ciphertext,encryption_iv,encryption_version,encrypted_attachments,reply_to_id)
    values(p_conversation_id,actor,'[Encrypted message]',p_ciphertext,p_encryption_iv,1,coalesce(p_encrypted_attachments,'[]'::jsonb),p_reply_to_id)
    returning id into message_id;
    update public.booking_conversations set updated_at=now() where id=p_conversation_id;
  else
    raise exception 'Unsupported private conversation kind';
  end if;
  return message_id;
end;
$$;


--
-- Name: send_support_message(uuid, text, text[], text[], text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_support_message(p_conversation_id uuid, p_content text DEFAULT ''::text, p_attachments text[] DEFAULT '{}'::text[], p_attachment_types text[] DEFAULT '{}'::text[], p_action_type text DEFAULT NULL::text, p_action_metadata jsonb DEFAULT '{}'::jsonb, p_visibility text DEFAULT 'customer'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conversation public.partner_support_conversations;
  v_id uuid;
  v_is_requester boolean;
  v_has_case boolean;
  v_sender_role text;
  v_snapshot jsonb;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then raise exception 'Authentication required'; end if;
  select * into v_conversation from public.partner_support_conversations
  where id=p_conversation_id for update;
  if v_conversation.id is null then raise exception 'Conversation not found'; end if;

  v_is_requester:=v_actor.user_id=v_conversation.partner_id;
  if v_is_requester then
    if not public.current_actor_can_access_operational_conversation(
      p_conversation_id,false
    ) then raise exception 'Not authorised'; end if;
  elsif not public.current_actor_can_access_operational_conversation(
    p_conversation_id,true
  ) then
    raise exception 'Claim this work before replying';
  end if;
  if p_visibility not in('customer','internal') then raise exception 'Invalid message visibility'; end if;
  if p_visibility='internal' and v_is_requester then
    raise exception 'Only the assigned WeHouse team can add internal work notes';
  end if;
  if nullif(btrim(coalesce(p_content,'')),'') is null
     and coalesce(cardinality(p_attachments),0)=0 then
    raise exception 'Message or attachment is required';
  end if;
  if coalesce(cardinality(p_attachments),0)
     <>coalesce(cardinality(p_attachment_types),0) then
    raise exception 'Attachment metadata mismatch';
  end if;

  v_has_case:=v_conversation.operational_case_id is not null
    or v_conversation.channel_kind in('support','support_case');
  if v_has_case and v_conversation.status in('resolved','closed') then
    if v_is_requester then
      raise exception 'Choose I still need help before sending another message';
    end if;
    raise exception 'Reopen the request before sending another reply';
  end if;

  v_sender_role:=case
    when v_is_requester then coalesce(v_conversation.requester_role,v_actor.role)
    when v_actor.role='creator' then 'creator'
    when v_actor.role='admin' then 'admin'
    else 'staff'
  end;
  insert into public.partner_support_messages(
    conversation_id,sender_id,sender_role,content,attachments,attachment_types,
    action_type,action_metadata,visibility,created_at
  ) values(
    p_conversation_id,v_actor.user_id,v_sender_role,btrim(coalesce(p_content,'')),
    coalesce(p_attachments,'{}'),coalesce(p_attachment_types,'{}'),
    case when p_action_type='message' then 'message' else null end,
    coalesce(p_action_metadata,'{}'::jsonb)
      -'booking_code'-'check_in_code'-'access_code'-'verification_code'
      -'handover_code'-'recovery_code',
    p_visibility,now()
  ) returning partner_support_messages.id into v_id;

  if v_has_case and p_visibility='customer' then
    if v_is_requester and v_conversation.status='waiting_for_user' then
      update public.partner_support_conversations
      set status='in_progress',updated_at=now() where id=p_conversation_id;
      update public.operational_cases set status='investigating',updated_at=now()
      where operational_case_id=v_conversation.operational_case_id;
      insert into public.support_case_events(
        conversation_id,event_type,actor_id,from_status,to_status,note
      ) values(p_conversation_id,'requester_replied',v_actor.user_id,
        'waiting_for_user','in_progress','The requester supplied more information.');
    elsif not v_is_requester and v_conversation.status in('open','assigned') then
      update public.partner_support_conversations
      set status='in_progress',updated_at=now() where id=p_conversation_id;
      update public.operational_cases set status='investigating',updated_at=now()
      where operational_case_id=v_conversation.operational_case_id;
      insert into public.support_case_events(
        conversation_id,event_type,actor_id,from_status,to_status,note
      ) values(p_conversation_id,'work_started',v_actor.user_id,
        v_conversation.status,'in_progress','WeHouse started reviewing this request.');
    else
      update public.partner_support_conversations set updated_at=now()
      where id=p_conversation_id;
    end if;
  elsif v_is_requester and p_visibility='customer' then
    v_snapshot:=coalesce(p_action_metadata->'context_snapshot','{}'::jsonb)
      -'booking_code'-'check_in_code'-'access_code'-'verification_code'
      -'handover_code'-'recovery_code';
    update public.partner_support_conversations set
      context_snapshot=case when v_snapshot<>'{}'::jsonb
        then context_snapshot||v_snapshot else context_snapshot end,
      updated_at=now()
    where id=p_conversation_id;
  else
    update public.partner_support_conversations set updated_at=now()
    where id=p_conversation_id;
  end if;
  return v_id;
end
$$;


--
-- Name: set_apartment_commission_on_reservation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_apartment_commission_on_reservation(p_reservation_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE v_rate NUMERIC;
BEGIN
  SELECT COALESCE(NULLIF(value, '')::NUMERIC, 10) INTO v_rate FROM platform_settings WHERE key = 'commission_apartment';
  UPDATE reservations SET commission_rate = v_rate WHERE id = p_reservation_id;
  RETURN TRUE;
END;
$$;


--
-- Name: set_default_payout_account_for_user(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_default_payout_account_for_user(p_user_id text, p_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_account public.bank_accounts%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service role required';
  end if;

  if nullif(btrim(coalesce(p_user_id,'')),'') is null then
    raise exception 'payout account owner is required';
  end if;

  -- This also serializes the zero/one-row edge before the row-level lock below.
  perform pg_advisory_xact_lock(hashtextextended(p_user_id,0));

  -- Serialize default-account changes for this user so two requests cannot leave
  -- competing defaults or a momentarily missing default.
  perform 1
  from public.bank_accounts
  where user_id = p_user_id and is_active = true
  for update;

  select * into v_account
  from public.bank_accounts
  where id = p_account_id
    and user_id = p_user_id
    and is_active = true
    and verified_at is not null
    and nullif(btrim(coalesce(recipient_code,'')),'') is not null;

  if not found then
    raise exception 'verified payout account not found';
  end if;

  update public.bank_accounts
  set is_default = (id = p_account_id),
      updated_at = now()
  where user_id = p_user_id
    and is_active = true
    and is_default is distinct from (id = p_account_id);

  -- Keep the compatibility wallet mirror aligned until the legacy fields are
  -- formally retired. Withdrawals themselves read bank_accounts.
  update public.wallets
  set bank_name = v_account.bank_name,
      bank_account_number = v_account.account_number,
      bank_account_name = v_account.account_name,
      paystack_recipient_code = v_account.recipient_code,
      updated_at = now()
  where owner_id = p_user_id;

  return jsonb_build_object(
    'id', v_account.id,
    'user_id', v_account.user_id,
    'bank_code', v_account.bank_code,
    'bank_name', v_account.bank_name,
    'account_number', v_account.account_number,
    'account_name', v_account.account_name,
    'recipient_code', v_account.recipient_code,
    'verified_at', v_account.verified_at,
    'is_default', true,
    'is_active', v_account.is_active
  );
end;
$$;


--
-- Name: set_hotel_arrival_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_hotel_arrival_deadline() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.checked_in_at is not null
     and (old.checked_in_at is null or new.checked_in_at is distinct from old.checked_in_at) then
    if new.arrival_issue_policy_version_id is null
       or new.arrival_issue_window_hours not between 2 and 4 then
      raise exception 'Hotel arrival policy snapshot required before check-in';
    end if;
    new.arrival_issue_deadline_at:=new.checked_in_at
      +make_interval(hours=>new.arrival_issue_window_hours);
  end if;
  return new;
end
$$;


--
-- Name: set_hotel_booking_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_hotel_booking_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_lga text;
  v_paid boolean;
  v_codeable boolean;
begin
  if tg_op = 'UPDATE' and nullif(btrim(coalesce(old.booking_code, '')), '') is not null then
    new.booking_code := old.booking_code;
    return new;
  end if;

  v_paid := new.paid_at is not null and new.payment_status in ('paid', 'refunded');
  v_codeable := new.status in ('confirmed', 'checked_in', 'checked_out', 'completed', 'refunded');

  if not (v_paid and v_codeable) then
    new.booking_code := null;
    return new;
  end if;

  select coalesce(nullif(btrim(h.city), ''), nullif(btrim(h.state), ''), 'General')
  into v_lga
  from public.hotels h
  where h.hotel_id = new.hotel_id
  limit 1;

  new.booking_code := public.reserve_lga_booking_code(coalesce(v_lga, 'General'));
  return new;
end;
$$;


--
-- Name: set_hotel_booking_message_reaction(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_hotel_booking_message_reaction(p_conversation_id uuid, p_message_id uuid, p_emoji text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor_id text;result jsonb;
begin
  select user_id into actor_id from public.profiles where auth_id=(select auth.uid())::text limit 1;
  if actor_id is null or not public.can_access_hotel_booking_conversation(p_conversation_id) then raise exception 'Hotel conversation access denied'; end if;
  if nullif(btrim(coalesce(p_emoji,'')),'') is not null and not public._valid_reaction(p_emoji) then raise exception 'Choose a valid emoji reaction'; end if;
  update public.hotel_booking_messages
  set reactions=case when nullif(btrim(coalesce(p_emoji,'')),'') is null then coalesce(reactions,'{}'::jsonb)-actor_id else jsonb_set(coalesce(reactions,'{}'::jsonb),array[actor_id],to_jsonb(btrim(p_emoji)),true) end
  where id=p_message_id and conversation_id=p_conversation_id returning reactions into result;
  if result is null then raise exception 'Message not found'; end if;
  return result;
end;
$$;


--
-- Name: set_hotel_team_default_capabilities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_hotel_team_default_capabilities() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  new.hotel_role:=case when new.hotel_role='staff' then 'front_desk' else new.hotel_role end;
  if (tg_op='INSERT' and cardinality(coalesce(new.capabilities,array[]::text[]))=0)
     or (tg_op='UPDATE' and new.hotel_role is distinct from old.hotel_role
         and new.capabilities is not distinct from old.capabilities) then
    new.capabilities:=public.hotel_default_capabilities(new.hotel_role);
  end if;
  return new;
end;
$$;


--
-- Name: set_listing_status_internal(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_listing_status_internal(p_listing_id text, p_status text) RETURNS public.listings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_listing public.listings;
BEGIN
  SELECT * INTO v_actor FROM public.profiles
  WHERE auth_id=auth.uid()::text AND role IN ('staff','admin','creator')
    AND NOT COALESCE(deleted,false) AND NOT COALESCE(suspended,false) AND NOT COALESCE(banned,false)
  LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Listing operations access required'; END IF;
  IF v_actor.role='staff' AND NOT public.current_staff_has_permission('operations') THEN RAISE EXCEPTION 'Operations Staff permission required'; END IF;
  IF p_status NOT IN ('available','maintenance','closed') THEN
    RAISE EXCEPTION 'Reserved and occupied states are controlled by reservation/tenancy workflows';
  END IF;
  SELECT * INTO v_listing FROM public.listings
  WHERE (listing_id=p_listing_id OR id::text=p_listing_id) AND deleted_at IS NULL FOR UPDATE;
  IF v_listing IS NULL THEN RAISE EXCEPTION 'Listing not found'; END IF;
  IF v_actor.role<>'creator' AND NOT public.current_actor_in_scope(v_listing.state,v_listing.city) THEN RAISE EXCEPTION 'Listing is outside your assigned State/LGA'; END IF;
  IF v_listing.status IN ('pending_approval','rejected') THEN RAISE EXCEPTION 'Approval state must be resolved first'; END IF;
  IF v_listing.status IN ('reserved','occupied') OR v_listing.current_reservation_id IS NOT NULL THEN
    RAISE EXCEPTION 'Resolve the active reservation/tenancy instead of manually changing this property';
  END IF;
  UPDATE public.listings SET status=p_status,availability_status=p_status,updated_at=now() WHERE id=v_listing.id RETURNING * INTO v_listing;
  RETURN v_listing;
END;
$$;


--
-- Name: set_my_listing_future_installments(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_listing_future_installments(p_listing_id uuid, p_allowed boolean) RETURNS public.listings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id(); v_listing public.listings;
begin
  if v_actor is null or not public.current_actor_has_workspace('property_partner') then
    raise exception 'Property Partner workspace required';
  end if;
  select * into v_listing from public.listings where id=p_listing_id
    and deleted_at is null for update;
  if v_listing.id is null then raise exception 'Listing not found'; end if;
  if coalesce(v_listing.partner_id,v_listing.owner_id)<>v_actor then
    raise exception 'Only the Property Partner can change this listing';
  end if;
  if coalesce(v_listing.sub_type,'')<>'long_stay' then
    raise exception 'Installments apply only to Long Let';
  end if;
  update public.listings set future_installments_allowed=coalesce(p_allowed,false),
    updated_at=now() where id=v_listing.id returning * into v_listing;
  insert into public.audit_logs(action,target_type,target_id,details,admin_id)
  values('PARTNER_INSTALLMENT_OPTION_CHANGED','listings',v_listing.id::text,
    jsonb_build_object('allowed',v_listing.future_installments_allowed)::text,v_actor);
  return v_listing;
end
$$;


--
-- Name: set_my_private_call_preferences(boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_private_call_preferences(p_allow_audio boolean, p_allow_video boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_me text:=public.current_profile_user_id(); v_role text:=public.current_profile_role();
begin
 if v_me is null or v_role not in ('user','worker') then raise exception 'Calls are available to Users and Workers'; end if;
 insert into public.private_call_preferences(user_id,allow_audio_calls,allow_video_calls,updated_at) values(v_me,coalesce(p_allow_audio,true),coalesce(p_allow_video,false),now()) on conflict(user_id) do update set allow_audio_calls=excluded.allow_audio_calls,allow_video_calls=excluded.allow_video_calls,updated_at=now();
 return public.get_my_private_call_preferences();
end; $$;


--
-- Name: set_my_roommate_block(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_roommate_block(p_user_id text, p_blocked boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor public.profiles;
begin
  actor := public._current_comm_actor();
  if actor is null or not public.current_actor_has_personal_workspace() or actor.user_id=p_user_id then
    raise exception 'Invalid roommate block request';
  end if;
  if not exists(select 1 from public.conversations c where c.conversation_type='roommate'
    and actor.user_id in(c.participant_a,c.participant_b) and p_user_id in(c.participant_a,c.participant_b)) then
    raise exception 'Roommate connection unavailable';
  end if;
  if p_blocked then
    insert into public.roommate_user_blocks(blocker_user_id,blocked_user_id)
    values(actor.user_id,p_user_id) on conflict do nothing;
    delete from public.roommate_search_results
      where (searcher_id=actor.user_id and matched_user_id=p_user_id)
         or (searcher_id=p_user_id and matched_user_id=actor.user_id);
    update public.private_calls set status=case when status='ringing' then 'declined' else 'ended' end,
      ended_at=coalesce(ended_at,now())
      where context_type='roommate' and status in('ringing','accepted')
        and ((caller_id=actor.user_id and callee_id=p_user_id) or (caller_id=p_user_id and callee_id=actor.user_id));
  else
    delete from public.roommate_user_blocks where blocker_user_id=actor.user_id and blocked_user_id=p_user_id;
  end if;
  return p_blocked;
end $$;


--
-- Name: set_my_roommate_block_v2(text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_roommate_block_v2(p_user_id text, p_blocked boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  actor public.profiles;
  conversation_id uuid;
  group_row public.shared_housing_groups;
  cancellation_state text:='none';
  has_paid_member boolean:=false;
begin
  actor:=public._current_comm_actor();
  if actor is null or not public.current_actor_has_personal_workspace() or actor.user_id=p_user_id then
    raise exception 'Invalid roommate block request';
  end if;
  select c.id into conversation_id
  from public.conversations c
  where c.conversation_type='roommate' and actor.user_id in(c.participant_a,c.participant_b) and p_user_id in(c.participant_a,c.participant_b)
  order by c.created_at desc limit 1;
  if conversation_id is null then raise exception 'Roommate connection unavailable'; end if;

  if p_blocked then
    insert into public.roommate_user_blocks(blocker_user_id,blocked_user_id,reason,created_at,updated_at)
    values(actor.user_id,p_user_id,nullif(left(btrim(coalesce(p_reason,'')),500),''),now(),now())
    on conflict(blocker_user_id,blocked_user_id) do update
      set reason=excluded.reason,updated_at=now();
    delete from public.roommate_search_results
    where (searcher_id=actor.user_id and matched_user_id=p_user_id) or (searcher_id=p_user_id and matched_user_id=actor.user_id);
    update public.private_calls
    set status=case when status='ringing' then 'declined' else 'ended' end,ended_at=coalesce(ended_at,now())
    where context_type='roommate' and status in('ringing','accepted')
      and ((caller_id=actor.user_id and callee_id=p_user_id) or (caller_id=p_user_id and callee_id=actor.user_id));

    for group_row in
      select g.* from public.shared_housing_groups g
      where g.conversation_id=conversation_id and g.status in('inviting','ready','payment_pending','paid')
      for update
    loop
      select exists(select 1 from public.shared_housing_members m where m.group_id=group_row.id and m.payment_status='paid') into has_paid_member;
      if has_paid_member or group_row.reservation_id is not null then
        cancellation_state:='review';
        insert into public.notifications(
          recipient_id,type,title,message,related_id,source_type,source_id,destination_route,destination_params,event_key,workspace_scope,read,created_at
        )
        select p.user_id,'roommate_shared_booking_cancellation','Shared booking cancellation needs review',
          'A roommate was blocked after payment. Review cancellation and any refund before releasing the property.',
          coalesce(group_row.reservation_id,group_row.id::text),'shared_housing',group_row.id::text,'operations_bookings',
          jsonb_build_object('shared_group_id',group_row.id::text,'reservation_id',group_row.reservation_id,'conversation_id',conversation_id::text),
          'roommate_block_cancellation:'||group_row.id::text,'creator',false,now()
        from public.profiles p
        where p.role='creator' and not coalesce(p.deleted,false) and not coalesce(p.suspended,false) and not coalesce(p.banned,false)
          and not exists(select 1 from public.notifications n where n.recipient_id=p.user_id and n.event_key='roommate_block_cancellation:'||group_row.id::text);
        insert into public.notifications(
          recipient_id,type,title,message,related_id,source_type,source_id,destination_route,destination_params,event_key,workspace_scope,read,created_at
        ) values(
          actor.user_id,'roommate_shared_booking_cancellation','Shared booking cancellation sent to WeHouse',
          'Your block is active. WeHouse must review the paid shared booking before money or property status changes.',
          coalesce(group_row.reservation_id,group_row.id::text),'shared_housing',group_row.id::text,'my_reservations',
          jsonb_build_object('shared_group_id',group_row.id::text,'reservation_id',group_row.reservation_id),
          'my_roommate_block_cancellation:'||group_row.id::text,'personal',false,now())
        on conflict do nothing;
      else
        cancellation_state:='cancelled';
        update public.shared_housing_groups set status='cancelled',updated_at=now() where id=group_row.id;
        update public.shared_housing_members set payment_status=case when payment_status='pending' then 'failed' else payment_status end,updated_at=now() where group_id=group_row.id;
        update public.booking_payments set status='cancelled',updated_at=now()
        where purpose='shared_housing_share' and status='pending' and metadata->>'shared_group_id'=group_row.id::text;
      end if;
    end loop;
  else
    delete from public.roommate_user_blocks where blocker_user_id=actor.user_id and blocked_user_id=p_user_id;
  end if;
  return jsonb_build_object('blocked',p_blocked,'cancellation_state',cancellation_state);
end;
$$;


--
-- Name: set_my_roommate_school_filter(boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_roommate_school_filter(p_school_match boolean, p_school_name text DEFAULT NULL::text, p_campus text DEFAULT NULL::text) RETURNS public.roommate_preferences
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_row public.roommate_preferences;
  v_school text;
BEGIN
  SELECT * INTO v_actor
  FROM public.profiles
  WHERE auth_id=auth.uid()::text
  LIMIT 1;

  IF v_actor IS NULL OR not public.current_actor_has_personal_workspace() THEN
    RAISE EXCEPTION 'Roommate matching is available to regular users only';
  END IF;
  IF COALESCE(v_actor.deleted,false) OR COALESCE(v_actor.suspended,false) OR COALESCE(v_actor.banned,false) THEN
    RAISE EXCEPTION 'Account is not active';
  END IF;

  SELECT * INTO v_row
  FROM public.roommate_preferences
  WHERE user_id=v_actor.user_id
  FOR UPDATE;

  IF v_row IS NULL THEN
    RAISE EXCEPTION 'Save roommate preferences first';
  END IF;

  v_school := NULLIF(BTRIM(COALESCE(p_school_name,v_row.school_name,v_actor.school,'')),'');
  IF COALESCE(p_school_match,false) AND v_school IS NULL THEN
    RAISE EXCEPTION 'Enter your school before enabling same-school matching';
  END IF;

  UPDATE public.roommate_preferences
  SET school_name=v_school,
      campus=NULLIF(BTRIM(COALESCE(p_campus,campus,'')),''),
      school_match=COALESCE(p_school_match,false),
      updated_at=now()
  WHERE user_id=v_actor.user_id
  RETURNING * INTO v_row;

  DELETE FROM public.roommate_search_results r
  WHERE r.searcher_id=v_actor.user_id
    AND r.status IN ('new','viewed')
    AND (
      COALESCE(v_row.school_match,false)
      AND NOT EXISTS (
        SELECT 1
        FROM public.profiles candidate
        LEFT JOIN public.roommate_preferences candidate_prefs ON candidate_prefs.user_id=candidate.user_id
        WHERE candidate.user_id=r.matched_user_id
          AND lower(regexp_replace(BTRIM(COALESCE(candidate_prefs.school_name,candidate.school,'')), '\s+', ' ', 'g'))
              = lower(regexp_replace(BTRIM(v_row.school_name), '\s+', ' ', 'g'))
      )
    );

  RETURN v_row;
END
$$;


--
-- Name: set_my_worker_availability(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_worker_availability(p_is_available boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_worker public.profiles;
begin
  select * into v_worker
  from public.profiles
  where auth_id=(select auth.uid())::text
  for update;
  if v_worker is null or not public.current_actor_has_workspace('worker',null) then
    raise exception 'Worker workspace required';
  end if;
  if coalesce(v_worker.deleted,false)
     or coalesce(v_worker.suspended,false)
     or coalesce(v_worker.banned,false) then
    raise exception 'Worker account is not active';
  end if;
  if p_is_available
     and (v_worker.worker_status<>'verified'
       or v_worker.worker_verified is distinct from true) then
    raise exception 'Only verified Workers can become available';
  end if;
  if p_is_available
     and not public.worker_identity_is_current(v_worker.user_id) then
    raise exception 'Repeat your WeHouse identity check before going available';
  end if;
  update public.profiles
  set available=p_is_available,updated_at=now()
  where id=v_worker.id;
end
$$;


--
-- Name: set_my_worker_block(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_worker_block(p_conversation_id uuid, p_blocked boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_me text:=public.current_profile_user_id();
  v_peer text;
begin
  if v_me is null then raise exception 'Authenticated profile required'; end if;
  select case when conversation.user_id=v_me then conversation.worker_id else conversation.user_id end
  into v_peer
  from public.booking_conversations conversation
  where conversation.id=p_conversation_id
    and v_me in (conversation.user_id,conversation.worker_id)
  limit 1;
  if v_peer is null or v_peer=v_me then raise exception 'Worker conversation unavailable'; end if;
  perform public.set_my_worker_block(v_peer,coalesce(p_blocked,false),null);
  return coalesce(p_blocked,false);
end;
$$;


--
-- Name: set_my_worker_block(text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_worker_block(p_user_id text, p_blocked boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_peer public.profiles;
  v_booking record;
  v_actor_side text;
  v_cancelled integer:=0;
  v_review integer:=0;
  v_case_id uuid;
  v_case_ids jsonb:='[]'::jsonb;
  v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then raise exception 'Authentication required'; end if;
  select * into v_peer from public.profiles
  where user_id=p_user_id and not coalesce(deleted,false) limit 1;
  if v_peer.user_id is null then raise exception 'Person not found'; end if;
  if not exists(
    select 1 from public.worker_bookings booking
    where (booking.user_id=v_actor.user_id and booking.worker_id=v_peer.user_id)
       or (booking.user_id=v_peer.user_id and booking.worker_id=v_actor.user_id)
  ) then raise exception 'Worker booking relationship required'; end if;

  if not coalesce(p_blocked,false) then
    delete from public.worker_user_blocks
    where blocker_user_id=v_actor.user_id and blocked_user_id=v_peer.user_id;
    return jsonb_build_object(
      'blocked',false,'booking_action','none',
      'cancelled_bookings',0,'review_bookings',0
    );
  end if;

  insert into public.worker_user_blocks(blocker_user_id,blocked_user_id,reason)
  values(v_actor.user_id,v_peer.user_id,v_reason)
  on conflict(blocker_user_id,blocked_user_id) do update
  set reason=excluded.reason,created_at=now();

  update public.private_calls call
  set status=case when call.status='ringing' then 'declined' else 'ended' end,
      ended_at=coalesce(call.ended_at,now())
  where call.context_type='worker_booking'
    and call.status in ('ringing','accepted')
    and ((call.caller_id=v_actor.user_id and call.callee_id=v_peer.user_id)
      or (call.caller_id=v_peer.user_id and call.callee_id=v_actor.user_id));

  for v_booking in
    select booking.*,
      exists(
        select 1 from public.booking_payments payment
        where payment.worker_booking_id=booking.id
          and (payment.status in ('paid','completed','review_required')
            or payment.verified_at is not null)
      ) or exists(
        select 1 from public.payment_protection_transactions protection
        where protection.booking_id=booking.id
          and protection.booking_type='worker_booking'
          and protection.status not in ('released','refunded','reversed')
      ) as has_secured_money
    from public.worker_bookings booking
    where (booking.user_id=v_actor.user_id and booking.worker_id=v_peer.user_id)
       or (booking.user_id=v_peer.user_id and booking.worker_id=v_actor.user_id)
    for update
  loop
    v_actor_side:=case when v_booking.user_id=v_actor.user_id
      then 'user' else 'worker' end;
    if v_booking.status in ('approved_released','refunded') then continue; end if;
    if v_booking.has_secured_money
       or v_booking.status in (
         'confirmed','payment_protected','in_progress',
         'completed_pending_approval','disputed'
       ) then
      update public.booking_payments payment
      set status='review_required',updated_at=now()
      where payment.worker_booking_id=v_booking.id
        and (payment.status in ('paid','completed','review_required')
          or payment.verified_at is not null);
      update public.worker_bookings
      set status='disputed',
          dispute_reason=concat_ws(
            E'\n',nullif(dispute_reason,''),
            'Communication blocked; WeHouse payment review required.'
          ),
          updated_at=now()
      where id=v_booking.id;
      v_review:=v_review+1;
      select conversation.id into v_case_id
      from public.partner_support_conversations conversation
      where conversation.partner_id=v_actor.user_id
        and conversation.context_type='worker_booking'
        and conversation.context_id=v_booking.id::text
      order by conversation.created_at desc limit 1;
      if v_case_id is null then
        insert into public.partner_support_conversations(
          partner_id,requester_role,subject,status,category,context_type,
          context_id,context_snapshot,priority,channel_kind,created_at,updated_at
        ) values(
          v_actor.user_id,v_actor_side,
          'Service booking safety review · '
            ||coalesce(v_booking.booking_code,'Booking'),
          'open','safety','worker_booking',v_booking.id::text,
          jsonb_build_object(
            'source_type','worker_booking','booking_id',v_booking.id,
            'booking_code',v_booking.booking_code,
            'service_type',v_booking.service_type,
            'status','disputed','payment_status','review_required',
            'requester_relationship',v_actor_side
          ),
          'urgent','support_case',now(),now()
        ) returning id into v_case_id;
      else
        update public.partner_support_conversations
        set status=case when status in ('resolved','closed')
              then 'open' else status end,
            priority='urgent',
            context_snapshot=context_snapshot||jsonb_build_object(
              'status','disputed','payment_status','review_required',
              'requester_relationship',v_actor_side
            ),
            updated_at=now()
        where id=v_case_id;
      end if;
      insert into public.partner_support_messages(
        conversation_id,sender_id,sender_role,content,action_type,
        action_metadata,created_at
      ) values(
        v_case_id,v_actor.user_id,v_actor_side,
        'I blocked this booking participant. Please review the job and its protected payment.',
        'status_change',
        jsonb_build_object(
          'context_id',v_booking.id,'reason',v_reason,
          'requester_relationship',v_actor_side
        ),now()
      );
      v_case_ids:=v_case_ids||jsonb_build_array(v_case_id);
    elsif v_booking.status in (
      'booking_requested','negotiating','waiting_payment'
    ) then
      update public.worker_bookings
      set status='cancelled',cancelled_by=v_actor.user_id,
          cancellation_reason=coalesce(v_reason,'Participant blocked'),
          updated_at=now()
      where id=v_booking.id;
      update public.booking_payments
      set status='cancelled',updated_at=now()
      where worker_booking_id=v_booking.id and status='pending';
      v_cancelled:=v_cancelled+1;
    end if;
  end loop;
  return jsonb_build_object(
    'blocked',true,'cancelled_bookings',v_cancelled,
    'review_bookings',v_review,
    'booking_action',case
      when v_review>0 then 'review_required'
      when v_cancelled>0 then 'cancelled'
      else 'none' end,
    'support_conversation_id',v_case_id,
    'support_conversation_ids',v_case_ids
  );
end
$$;


--
-- Name: set_my_worker_showcase_reaction(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_worker_showcase_reaction(p_post_id uuid, p_emoji text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor public.profiles;
begin
  select * into actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if actor.user_id is null or not public.current_actor_has_personal_workspace() then
    raise exception 'Active Personal account required';
  end if;
  if not exists(
    select 1 from public.worker_showcase_posts
    where id=p_post_id and deleted_at is null and hidden_at is null
  ) then raise exception 'Work Post not found'; end if;
  if nullif(btrim(coalesce(p_emoji,'')),'') is null then
    delete from public.worker_showcase_reactions
    where post_id=p_post_id and user_id=actor.user_id;
  elsif public._valid_reaction(p_emoji) then
    insert into public.worker_showcase_reactions(post_id,user_id,emoji)
    values(p_post_id,actor.user_id,btrim(p_emoji))
    on conflict(post_id,user_id) do update
    set emoji=excluded.emoji,updated_at=now();
  else
    raise exception 'Choose a valid emoji reaction';
  end if;
  return coalesce((
    select jsonb_object_agg(emoji,reaction_count)
    from (
      select emoji,count(*)::integer reaction_count
      from public.worker_showcase_reactions
      where post_id=p_post_id group by emoji
    ) totals
  ),'{}'::jsonb);
end
$$;


--
-- Name: set_my_worker_work_post_hidden(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_worker_work_post_hidden(p_post_id uuid, p_hidden boolean) RETURNS public.worker_showcase_posts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_worker text:=public.current_profile_user_id();
  v_post public.worker_showcase_posts;
begin
  if v_worker is null or not public.current_actor_has_workspace('worker',null) then
    raise exception 'Worker workspace required';
  end if;
  update public.worker_showcase_posts
  set hidden_at=case when p_hidden then coalesce(hidden_at,now()) else null end
  where id=p_post_id and worker_id=v_worker and deleted_at is null
  returning * into v_post;
  if v_post is null then raise exception 'Work Post not found'; end if;
  return v_post;
end
$$;


--
-- Name: set_notification_workspace_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_notification_workspace_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  new.workspace_scope:=coalesce(
    nullif(btrim(new.workspace_scope),''),
    public.infer_notification_workspace_scope(
      new.recipient_id,new.type,new.source_type,new.destination_route,new.title
    )
  );
  if new.workspace_scope='property_partner' then
    new.workspace_scope:='partner';
  end if;
  if new.workspace_scope not in(
    'personal','account','worker','partner','hotel','staff','admin','creator',
    'property_operations','field_operations','worker_operations',
    'finance_operations','security_operations','support'
  ) then raise exception 'Unsupported notification workspace scope'; end if;
  return new;
end
$$;


--
-- Name: set_private_message_reaction(text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_private_message_reaction(p_conversation_kind text, p_conversation_id uuid, p_message_id uuid, p_emoji text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor text:=public.current_profile_user_id();
  peer text;
  result jsonb;
begin
  if actor is null then raise exception 'Active WeHouse profile required'; end if;
  if nullif(btrim(coalesce(p_emoji,'')),'') is not null and not public._valid_reaction(p_emoji) then raise exception 'Choose a valid emoji reaction'; end if;

  if p_conversation_kind='roommate' then
    select case when c.participant_a=actor then c.participant_b else c.participant_a end into peer
    from public.conversations c
    where c.id=p_conversation_id and actor in(c.participant_a,c.participant_b)
      and c.conversation_type='roommate' and coalesce(c.status,'active')='active'
    limit 1;
    if peer is null then raise exception 'Conversation access denied'; end if;
    if exists(
      select 1 from public.roommate_user_blocks block_row
      where (block_row.blocker_user_id=actor and block_row.blocked_user_id=peer)
         or (block_row.blocker_user_id=peer and block_row.blocked_user_id=actor)
    ) then raise exception 'This roommate connection is blocked'; end if;
    update public.messages
    set reactions=case when nullif(btrim(coalesce(p_emoji,'')),'') is null
      then coalesce(reactions,'{}'::jsonb)-actor
      else jsonb_set(coalesce(reactions,'{}'::jsonb),array[actor],to_jsonb(btrim(p_emoji)),true) end
    where id=p_message_id and conversation_id=p_conversation_id
    returning reactions into result;

  elsif p_conversation_kind='worker' then
    select case when c.user_id=actor then c.worker_id else c.user_id end into peer
    from public.booking_conversations c
    where c.id=p_conversation_id and actor in(c.user_id,c.worker_id)
    limit 1;
    if peer is null then raise exception 'Conversation access denied'; end if;
    if exists(
      select 1 from public.worker_user_blocks block_row
      where (block_row.blocker_user_id=actor and block_row.blocked_user_id=peer)
         or (block_row.blocker_user_id=peer and block_row.blocked_user_id=actor)
    ) then raise exception 'This service conversation is blocked'; end if;
    update public.booking_messages
    set reactions=case when nullif(btrim(coalesce(p_emoji,'')),'') is null
      then coalesce(reactions,'{}'::jsonb)-actor
      else jsonb_set(coalesce(reactions,'{}'::jsonb),array[actor],to_jsonb(btrim(p_emoji)),true) end
    where id=p_message_id and conversation_id=p_conversation_id
    returning reactions into result;
  else
    raise exception 'Unsupported private conversation kind';
  end if;
  if result is null then raise exception 'Message was not found'; end if;
  return result;
end;
$$;


--
-- Name: set_property_inspection_stay_type(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_property_inspection_stay_type(p_inspection_id uuid, p_sub_type text, p_security_deposit_amount numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_ir public.inspection_requests;
  v_amenities text[];
BEGIN
  SELECT * INTO v_actor FROM public.profiles
  WHERE auth_id=auth.uid()::text
    AND role IN ('staff','admin','creator')
    AND COALESCE(deleted,false)=false
    AND COALESCE(suspended,false)=false
    AND COALESCE(banned,false)=false
  LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'WeHouse operations access required'; END IF;
  IF v_actor.role='staff' AND NOT public.current_staff_has_permission('operations') THEN
    RAISE EXCEPTION 'Operations permission required';
  END IF;
  IF p_sub_type NOT IN ('short_let','long_stay') THEN RAISE EXCEPTION 'Choose Short Stay or Long Stay'; END IF;

  SELECT * INTO v_ir FROM public.inspection_requests WHERE id=p_inspection_id FOR UPDATE;
  IF v_ir IS NULL THEN RAISE EXCEPTION 'Property request not found'; END IF;
  IF v_ir.property_type<>'apartment' THEN RAISE EXCEPTION 'Stay type applies to apartments only'; END IF;
  IF v_ir.published_at IS NOT NULL THEN RAISE EXCEPTION 'Published property classification cannot be changed here'; END IF;
  IF v_actor.role<>'creator' AND NOT public.current_actor_in_scope(v_ir.property_state,v_ir.property_city) THEN
    RAISE EXCEPTION 'Property is outside your assigned State/LGA';
  END IF;
  IF p_sub_type='short_let' AND COALESCE(p_security_deposit_amount,0)<=0 THEN
    RAISE EXCEPTION 'Short Stay requires a refundable security deposit';
  END IF;

  v_amenities := COALESCE(v_ir.amenities,ARRAY[]::text[]);
  IF p_sub_type='short_let' AND NOT ('Furnished'=ANY(v_amenities)) THEN
    v_amenities := array_append(v_amenities,'Furnished');
  END IF;

  UPDATE public.inspection_requests
  SET sub_type=p_sub_type,
      security_deposit_amount=CASE WHEN p_sub_type='short_let' THEN p_security_deposit_amount ELSE NULL END,
      amenities=v_amenities,
      updated_at=now()
  WHERE id=p_inspection_id;

  RETURN jsonb_build_object(
    'success',true,
    'sub_type',p_sub_type,
    'security_deposit_amount',CASE WHEN p_sub_type='short_let' THEN p_security_deposit_amount ELSE NULL END
  );
END;
$$;


--
-- Name: set_reservation_booking_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_reservation_booking_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lga text;
  v_can_issue boolean;
begin
  v_can_issue :=
    new.status in ('ready_for_move_in', 'occupied', 'completed')
    and coalesce(new.manual_payment_status, 'unpaid') in ('paid', 'completed')
    and new.paid_at is not null
    and coalesce(new.rent_payment_status, 'not_started') in ('paid', 'upfront_paid')
    and new.rent_paid_at is not null;

  if not v_can_issue then
    new.booking_code := null;
    return new;
  end if;

  -- The reservation hold ends when verified rent makes the booking eligible
  -- for move-in. Keeping its old deadline visible after this point is false.
  new.hold_expires_at := null;

  if tg_op = 'UPDATE'
     and nullif(btrim(coalesce(old.booking_code, '')), '') is not null then
    new.booking_code := old.booking_code;
    return new;
  end if;

  if nullif(btrim(coalesce(new.booking_code, '')), '') is not null then
    insert into public.booking_code_registry(code)
    values (upper(btrim(new.booking_code)))
    on conflict do nothing;
    new.booking_code := upper(btrim(new.booking_code));
    return new;
  end if;

  select coalesce(nullif(btrim(l.city), ''), nullif(btrim(l.state), ''), 'General')
  into v_lga
  from public.listings l
  where l.id::text = new.listing_id or l.listing_id = new.listing_id
  limit 1;

  new.booking_code := public.reserve_lga_booking_code(coalesce(v_lga, 'General'));
  return new;
end;
$$;


--
-- Name: set_reservation_expiry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_reservation_expiry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE v_hold_days INTEGER;
BEGIN
  IF NEW.status = 'active' AND OLD.status != 'active' THEN
    SELECT COALESCE(NULLIF(value, '')::INTEGER, 3) INTO v_hold_days FROM platform_settings WHERE key = 'apartment_reservation_hold_days';
    IF v_hold_days IS NULL THEN v_hold_days := 3; END IF;
    NEW.hold_expires_at := NOW() + (v_hold_days || ' days')::INTERVAL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: set_saved_search_criteria_key(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_saved_search_criteria_key() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  new.criteria:=public.canonical_saved_search_criteria(coalesce(new.criteria,'{}'::jsonb));
  new.criteria_key:=md5(new.criteria::text);
  return new;
end;
$$;


--
-- Name: set_secret_v2(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_secret_v2(p_key text, p_value text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ begin
  if not public.is_current_creator() then raise exception 'Creator account required'; end if;
  if nullif(btrim(coalesce(p_key,'')),'') is null then raise exception 'Secret key is required'; end if;
  insert into public.secrets(key,value,updated_at,updated_by)
  values(btrim(p_key),coalesce(p_value,''),now(),auth.uid()::text)
  on conflict(key) do update set value=excluded.value,updated_at=now(),updated_by=auth.uid()::text;
  return true;
end $$;


--
-- Name: set_setting_v2(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_setting_v2(p_key text, p_value text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
                                        DECLARE
                                          v_role TEXT;
                                          BEGIN
                                            -- Validate caller is creator
                                              SELECT role INTO v_role FROM profiles WHERE user_id = auth.uid()::text;
                                                IF v_role NOT IN ('creator') THEN
                                                    RAISE EXCEPTION 'Only Creator can modify settings';
                                                      END IF;
                                                        
                                                          INSERT INTO platform_settings (key, value, updated_at)
                                                            VALUES (p_key, p_value, NOW())
                                                              ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();
                                                                RETURN TRUE;
                                                                END;
                                                                $$;


--
-- Name: set_short_stay_arrival_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_short_stay_arrival_deadline() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.stay_type='short_let' and new.checked_in_at is not null
     and (old.checked_in_at is null or new.checked_in_at is distinct from old.checked_in_at) then
    if new.arrival_issue_policy_version_id is null
       or new.arrival_issue_window_hours not between 2 and 4 then
      raise exception 'Short Let arrival policy snapshot required before check-in';
    end if;
    new.arrival_issue_deadline_at:=new.checked_in_at
      +make_interval(hours=>new.arrival_issue_window_hours);
  end if;
  return new;
end
$$;


--
-- Name: set_staff_trust_status(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_staff_trust_status(p_staff_id text, p_status text, p_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_target public.profiles; v_trust public.staff_trust_profiles; v_previous text;
BEGIN
  IF p_status NOT IN('probation','trusted','restricted','revoked') THEN RAISE EXCEPTION 'Invalid Staff trust status'; END IF;
  SELECT * INTO v_actor FROM public.profiles
  WHERE auth_id=auth.uid()::text AND role IN('admin','creator')
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Admin or Creator access required'; END IF;
  SELECT * INTO v_target FROM public.profiles WHERE user_id=p_staff_id AND role='staff' AND COALESCE(deleted,false)=false LIMIT 1;
  IF v_target IS NULL THEN RAISE EXCEPTION 'Staff profile not found'; END IF;
  IF v_actor.role='admin' AND (v_actor.assigned_state IS DISTINCT FROM v_target.assigned_state OR v_actor.assigned_lga IS DISTINCT FROM v_target.assigned_lga) THEN
    RAISE EXCEPTION 'Admin can review only Staff in the same assigned branch';
  END IF;
  SELECT * INTO v_trust FROM public.staff_trust_profiles WHERE staff_id=p_staff_id; v_previous:=v_trust.status;
  IF p_status='trusted' THEN
    IF v_trust IS NULL THEN RAISE EXCEPTION 'Complete the Staff trust checklist first'; END IF;
    IF NOT(v_trust.supervisor_confirmed AND v_trust.orientation_completed AND v_trust.role_training_completed AND v_trust.code_of_conduct_confirmed AND v_trust.probation_observation_completed) THEN
      RAISE EXCEPTION 'Complete every WeHouse Staff trust check before marking this Staff member trusted';
    END IF;
  END IF;
  UPDATE public.staff_trust_profiles SET
    status=p_status,
    trusted_by=CASE WHEN p_status='trusted' THEN v_actor.user_id ELSE trusted_by END,
    trusted_at=CASE WHEN p_status='trusted' THEN now() ELSE trusted_at END,
    notes=COALESCE(NULLIF(BTRIM(COALESCE(p_notes,'')),''),notes),updated_at=now()
  WHERE staff_id=p_staff_id;
  IF NOT FOUND THEN
    INSERT INTO public.staff_trust_profiles(staff_id,status,appointed_by,appointed_at,notes,updated_at)
    VALUES(p_staff_id,p_status,v_actor.user_id,now(),NULLIF(BTRIM(COALESCE(p_notes,'')),''),now());
  END IF;
  INSERT INTO public.audit_logs(action,target_type,target_id,details,admin_id,admin_email)
  VALUES('STAFF_TRUST_CHANGE','profiles',p_staff_id,jsonb_build_object('previous_status',COALESCE(v_previous,'none'),'new_status',p_status,'notes',NULLIF(BTRIM(COALESCE(p_notes,'')),''),'state',v_target.assigned_state,'lga',v_target.assigned_lga)::text,v_actor.user_id,v_actor.email);
  RETURN true;
END;
$$;


--
-- Name: settle_verified_property_partner_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_verified_property_partner_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_partner_id text;
  v_partner_role text;
  v_commission_key text;
  v_commission_rate numeric;
  v_verified_total numeric;
  v_eligible_gross numeric;
  v_security_deposit numeric:=0;
  v_commission numeric;
  v_partner_net numeric;
  v_wallet record;
  v_new_pending numeric;
  v_payment_component text;
BEGIN
  IF NEW.status NOT IN ('paid','completed') OR OLD.status IN ('paid','completed') THEN RETURN NEW; END IF;
  IF NEW.purpose IN ('apartment_reservation','hotel_reservation') THEN RETURN NEW; END IF;
  IF NEW.purpose NOT IN ('apartment_rent','rent_plan_contribution','hotel_booking') THEN RETURN NEW; END IF;
  IF NEW.paystack_reference IS NULL THEN RAISE EXCEPTION 'Verified property payment requires a Paystack reference'; END IF;
  IF EXISTS (SELECT 1 FROM public.commission_ledger WHERE paystack_reference=NEW.paystack_reference) THEN RETURN NEW; END IF;

  IF NEW.purpose='hotel_booking' AND NOT EXISTS (
    SELECT 1 FROM public.hotel_bookings hb
    WHERE hb.booking_id=NEW.hotel_booking_id AND hb.status='confirmed' AND hb.payment_status='paid'
  ) THEN
    INSERT INTO public.financial_audit_logs(event_type,user_id,amount,reference_id,reference_type,description,metadata)
    VALUES('hotel_payment_fulfillment_review',NEW.user_id,COALESCE(NEW.verified_amount,NEW.amount_total,NEW.amount,0),NEW.id::text,'booking_payment',
      'Verified hotel payment withheld from partner settlement until booking fulfillment is confirmed',
      jsonb_build_object('hotel_booking_id',NEW.hotel_booking_id,'paystack_reference',NEW.paystack_reference));
    RETURN NEW;
  END IF;

  v_verified_total:=round(COALESCE(NEW.verified_amount,NEW.amount_total,NEW.amount,0)::numeric,2);
  IF v_verified_total<=0 THEN RAISE EXCEPTION 'Verified property payment amount must be greater than zero'; END IF;

  IF NEW.purpose IN ('apartment_rent','rent_plan_contribution') THEN
    SELECT COALESCE(l.partner_id,l.owner_id) INTO v_partner_id
    FROM public.listings l
    WHERE l.id::text=NEW.listing_id OR l.listing_id=NEW.listing_id
    LIMIT 1;
    v_commission_key:='commission_apartment';
    v_payment_component:=COALESCE(NEW.metadata->>'payment_component',CASE WHEN NEW.purpose='rent_plan_contribution' THEN 'rent_plan_contribution' ELSE NULL END);
    IF v_payment_component IS NULL OR v_payment_component NOT IN ('long_stay_rent','short_stay_rent','rent_plan_contribution') THEN RAISE EXCEPTION 'Apartment payment must identify a supported payment component'; END IF;
    v_security_deposit:=round(COALESCE(NULLIF(NEW.metadata->>'security_deposit_amount','')::numeric,0),2);
    IF v_security_deposit<0 OR v_security_deposit>v_verified_total THEN RAISE EXCEPTION 'Invalid security deposit amount'; END IF;
    IF v_payment_component='short_stay_rent' AND NOT (NEW.metadata ? 'security_deposit_amount') THEN RAISE EXCEPTION 'Short Stay payment must store security_deposit_amount separately'; END IF;
    v_eligible_gross:=round(COALESCE(NULLIF(NEW.metadata->>'eligible_partner_amount','')::numeric,v_verified_total-v_security_deposit),2);
  ELSE
    SELECT h.owner_id INTO v_partner_id
    FROM public.hotel_bookings hb
    JOIN public.hotels h ON h.hotel_id=hb.hotel_id
    WHERE hb.booking_id=NEW.hotel_booking_id
    LIMIT 1;
    v_commission_key:='commission_hotel';
    v_payment_component:='hotel_payment';
    v_eligible_gross:=v_verified_total;
  END IF;

  IF v_partner_id IS NULL THEN RETURN NEW; END IF;
  SELECT role INTO v_partner_role
  FROM public.profiles
  WHERE user_id=v_partner_id
    AND COALESCE(deleted,false)=false
    AND COALESCE(suspended,false)=false
    AND COALESCE(banned,false)=false
  LIMIT 1;
  IF v_partner_role IS DISTINCT FROM 'property_partner' THEN RETURN NEW; END IF;

  IF v_eligible_gross<=0 OR v_eligible_gross>v_verified_total THEN RAISE EXCEPTION 'Invalid eligible Property Partner amount'; END IF;
  SELECT NULLIF(value,'')::numeric INTO v_commission_rate
  FROM public.platform_settings
  WHERE key=v_commission_key AND COALESCE(is_active,true)=true
  LIMIT 1;
  IF v_commission_rate IS NULL OR v_commission_rate<0 OR v_commission_rate>50 THEN RAISE EXCEPTION 'Creator commission setting is missing or invalid'; END IF;

  v_commission:=round(v_eligible_gross*v_commission_rate/100,2);
  v_partner_net:=round(v_eligible_gross-v_commission,2);
  INSERT INTO public.wallets(owner_id,owner_type,available_balance,pending_balance,frozen_balance,total_withdrawn)
  VALUES(v_partner_id,'property_partner',0,0,0,0)
  ON CONFLICT(owner_id,owner_type) DO NOTHING;
  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE owner_id=v_partner_id AND owner_type='property_partner'
  FOR UPDATE;
  IF COALESCE(v_wallet.is_frozen,false) THEN RAISE EXCEPTION 'Property Partner wallet is frozen'; END IF;

  v_new_pending:=COALESCE(v_wallet.pending_balance,0)+v_partner_net;
  UPDATE public.wallets SET pending_balance=v_new_pending,updated_at=now() WHERE id=v_wallet.id;
  UPDATE public.booking_payments
  SET payee_user_id=v_partner_id,commission_rate=v_commission_rate,amount_commission=v_commission,net_amount=v_partner_net,updated_at=now()
  WHERE id=NEW.id;

  INSERT INTO public.commission_ledger(payment_id,booking_type,source_user_id,commission_amount,commission_rate,gross_amount,description,paystack_reference,status,created_at,updated_at)
  VALUES(NEW.id,CASE WHEN NEW.purpose='hotel_booking' THEN 'hotel' ELSE 'apartment' END,v_partner_id,v_commission,v_commission_rate,v_eligible_gross,
    format('%s commission from verified %s payment',CASE WHEN NEW.purpose='hotel_booking' THEN 'Hotel' ELSE 'Apartment' END,v_payment_component),NEW.paystack_reference,'collected',now(),now());
  INSERT INTO public.wallet_transactions(user_id,transaction_type,amount,balance_after,reference_id,reference_type,description,metadata,created_at)
  VALUES(v_partner_id,'property_earning_pending',v_partner_net,v_new_pending,NEW.id::text,'booking_payment',format('Pending net earnings from %s',replace(v_payment_component,'_',' ')),
    jsonb_build_object('paystack_reference',NEW.paystack_reference,'purpose',NEW.purpose,'gross_eligible_amount',v_eligible_gross,'security_deposit_amount',v_security_deposit,'commission_rate',v_commission_rate,'commission_amount',v_commission,'net_amount',v_partner_net,'wallet_bucket','pending'),now());
  INSERT INTO public.financial_audit_logs(event_type,user_id,target_user_id,amount,reference_id,reference_type,description,metadata)
  VALUES('commission_deducted',NEW.user_id,v_partner_id,v_partner_net,NEW.id::text,'booking_payment','Verified property payment recorded as pending partner earnings',jsonb_build_object('purpose',NEW.purpose,'commission_key',v_commission_key,'commission_amount',v_commission));
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  BEGIN
    INSERT INTO public.financial_audit_logs(event_type,user_id,amount,reference_id,reference_type,description,metadata)
    VALUES('property_settlement_review',NEW.user_id,COALESCE(NEW.verified_amount,NEW.amount_total,NEW.amount,0),NEW.id::text,'booking_payment',
      'Verified property payment requires Finance settlement review',
      jsonb_build_object('purpose',NEW.purpose,'paystack_reference',NEW.paystack_reference,'reason',SQLERRM));
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN NEW;
END;
$$;


--
-- Name: settle_verified_unprotected_installment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_verified_unprotected_installment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_payment public.booking_payments;
  v_listing public.listings;
  v_policy public.creator_policy_versions;
  v_payee text;
  v_gross numeric(12,2);
  v_rate numeric(5,2);
  v_commission numeric(12,2);
  v_net numeric(12,2);
  v_ledger uuid;
  v_wallet public.wallets;
  v_balance numeric(12,2);
  v_wallet_tx uuid;
begin
  if new.processing_status<>'processed' or old.processing_status='processed' then return new; end if;
  if (select auth.role())<>'service_role' then
    raise exception 'Unprotected installment settlement requires service role';
  end if;
  select * into v_payment from public.booking_payments
  where paystack_reference=new.provider_reference for update;
  if v_payment.id is null or v_payment.purpose<>'rent_plan_contribution' then return new; end if;
  if exists(select 1 from public.canonical_unprotected_settlement_receipts
    where booking_payment_id=v_payment.id) then return new; end if;
  select * into v_listing from public.listings
  where id::text=v_payment.listing_id for share;
  if v_listing.id is null or not coalesce(v_listing.future_installments_allowed,false) then
    raise exception 'Verified installment no longer has Partner authorization';
  end if;
  v_payee:=coalesce(v_listing.partner_id,v_listing.owner_id);
  if v_payee is null then raise exception 'Installment Property Partner is missing'; end if;
  select * into v_policy from public.creator_policy_versions
  where policy_key='commission_long_let' and scope_type='global' and scope_key='*'
    and status='active' and effective_from<=now()
    and (effective_until is null or effective_until>now())
  order by effective_from desc limit 1;
  v_rate:=(v_policy.value->>'percent')::numeric;
  if v_policy.policy_version_id is null or v_rate<0 or v_rate>50 then
    raise exception 'Active Creator Long Let commission is required';
  end if;
  v_gross:=round(coalesce(v_payment.verified_amount,v_payment.amount_total,v_payment.amount,0),2);
  if v_gross<=0 then raise exception 'Verified installment amount is invalid'; end if;
  v_commission:=round(v_gross*v_rate/100,2); v_net:=v_gross-v_commission;
  v_ledger:=public.post_ledger_transaction(
    'unprotected-installment:'||v_payment.id,'unprotected_partner_settlement','NGN',
    'booking_payment',v_payment.id::text,new.provider_event_id,
    jsonb_build_object('purpose','rent_plan_contribution','partner_opt_in',true,
      'payment_protection_hold',false,'payee_user_id',v_payee,
      'policy_version_id',v_policy.policy_version_id,'commission',v_commission,
      'payee_amount',v_net),
    jsonb_build_array(
      jsonb_build_object('account_key','liability:partner_payable:'||v_payee,
        'account_class','liability','owner_type','property_partner','owner_id',v_payee,
        'amount',v_gross,'memo','Verified installment payable cleared'),
      jsonb_build_object('account_key','liability:payee_available:'||v_payee,
        'account_class','liability','owner_type','profile','owner_id',v_payee,
        'amount',-v_net,'memo','Installment available for withdrawal'),
      jsonb_build_object('account_key','revenue:wehouse_commission:long_let_installment',
        'account_class','revenue','owner_type','wehouse','owner_id','platform',
        'amount',-v_commission,'memo','Long Let commission recognized')
    )
  );
  update public.booking_payments set payee_user_id=v_payee,commission_rate=v_rate,
    amount_commission=v_commission,net_amount=v_net,updated_at=now()
  where id=v_payment.id;
  insert into public.wallets(
    owner_id,owner_type,available_balance,pending_balance,frozen_balance,total_withdrawn
  ) values(v_payee,'property_partner',0,0,0,0)
  on conflict(owner_id,owner_type) do nothing;
  select * into v_wallet from public.wallets
  where owner_id=v_payee and owner_type='property_partner' for update;
  update public.wallets set available_balance=coalesce(available_balance,0)+v_net,
    updated_at=now() where id=v_wallet.id returning available_balance into v_balance;
  insert into public.wallet_transactions(
    user_id,transaction_type,amount,balance_after,reference_id,reference_type,
    description,metadata,created_at
  ) values(v_payee,'canonical_installment_settlement',v_net,v_balance,v_payment.id::text,
    'booking_payment','Verified future-year Long Let installment',
    jsonb_build_object('wallet_bucket','available','ledger_transaction_id',v_ledger,
      'commission_rate',v_rate,'commission_amount',v_commission),now())
  returning id into v_wallet_tx;
  insert into public.commission_ledger(
    payment_id,booking_type,source_user_id,commission_amount,commission_rate,
    gross_amount,description,paystack_reference,status,created_at,updated_at
  ) values(v_payment.id,'apartment',v_payee,v_commission,v_rate,v_gross,
    'Long Let installment commission from canonical ledger settlement',
    v_payment.paystack_reference,'collected',now(),now())
  on conflict(paystack_reference) where paystack_reference is not null do nothing;
  insert into public.property_partner_earning_releases(
    payment_id,partner_id,earning_type,status,net_amount,release_event,
    released_by,released_at,created_at,updated_at
  ) values(v_payment.id,v_payee,'rent_plan_contribution','available',v_net,
    'verified_normal_settlement','paystack',now(),now(),now())
  on conflict(payment_id) do update set status='available',net_amount=excluded.net_amount,
    release_event=excluded.release_event,released_by=excluded.released_by,
    released_at=excluded.released_at,updated_at=now();
  insert into public.canonical_unprotected_settlement_receipts(
    booking_payment_id,provider_event_id,ledger_transaction_id,payee_user_id,
    wallet_id,wallet_transaction_id,gross_amount,commission_amount,payee_amount,
    policy_version_id
  ) values(v_payment.id,new.provider_event_id,v_ledger,v_payee,v_wallet.id,v_wallet_tx,
    v_gross,v_commission,v_net,v_policy.policy_version_id);
  insert into public.financial_audit_logs(
    event_type,user_id,target_user_id,amount,reference_id,reference_type,
    description,metadata
  ) values('canonical_installment_settled',v_payment.user_id,v_payee,v_net,
    v_payment.id::text,'booking_payment',
    'Verified Partner-approved Long Let installment settled without a long hold',
    jsonb_build_object('gross',v_gross,'commission',v_commission,
      'policy_version_id',v_policy.policy_version_id,'ledger_transaction_id',v_ledger));
  return new;
end
$$;


--
-- Name: settle_withdrawal_transfer_event(text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_withdrawal_transfer_event(p_reference text, p_transfer_code text, p_paystack_status text, p_reason text, p_event_key text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_withdrawal public.withdrawals;
  v_wallet public.wallets;
  v_status text:=lower(btrim(coalesce(p_paystack_status,'')));
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then raise exception 'Service role required'; end if;
  if v_status not in ('success','failed','reversed') then raise exception 'Unsupported Paystack transfer status'; end if;
  select * into v_withdrawal from public.withdrawals
  where paystack_transfer_reference=p_reference for update;
  if v_withdrawal.id is null then return jsonb_build_object('success',false,'error','Withdrawal not found'); end if;
  if v_withdrawal.status='paid' and v_status='reversed' then
    return public.return_reserved_withdrawal(v_withdrawal.id,'reversed',p_reason,p_event_key);
  end if;
  if v_withdrawal.status in ('paid','rejected','failed','reversed') then
    return jsonb_build_object('success',true,'already_finalized',true,'status',v_withdrawal.status);
  end if;
  if v_withdrawal.status<>'processing' then raise exception 'Withdrawal is not processing'; end if;
  update public.withdrawals set
    paystack_transfer_code=coalesce(nullif(btrim(coalesce(p_transfer_code,'')),''),paystack_transfer_code),
    paystack_status=v_status,transfer_response=coalesce(p_payload,'{}'::jsonb),updated_at=now()
  where id=v_withdrawal.id;
  if v_status in ('failed','reversed') then
    return public.return_reserved_withdrawal(v_withdrawal.id,v_status,p_reason,p_event_key);
  end if;
  select * into v_wallet from public.wallets where id=v_withdrawal.wallet_id for update;
  if v_wallet.id is null or coalesce(v_wallet.frozen_balance,0)<v_withdrawal.amount then
    raise exception 'Reserved wallet balance is incomplete';
  end if;
  update public.wallets set
    frozen_balance=frozen_balance-v_withdrawal.amount,
    total_withdrawn=coalesce(total_withdrawn,0)+v_withdrawal.amount,updated_at=now()
  where id=v_wallet.id;
  update public.withdrawals set
    status='paid',processed_at=now(),finalized_at=now(),
    settlement_event_key=p_event_key,updated_at=now()
  where id=v_withdrawal.id;
  insert into public.financial_audit_logs(
    event_type,user_id,target_user_id,amount,reference_id,reference_type,description,metadata
  ) values(
    'withdrawal_paid',v_withdrawal.reviewed_by,v_wallet.owner_id,v_withdrawal.amount,
    v_withdrawal.id::text,'withdrawal','Paystack confirmed the withdrawal transfer',
    jsonb_build_object('paystack_reference',p_reference,'transfer_code',p_transfer_code,'event_key',p_event_key)
  );
  insert into public.notifications(
    recipient_id,type,title,message,related_id,source_type,source_id,destination_route,destination_params,event_key,workspace_scope
  ) values(
    v_wallet.owner_id,'withdrawal_paid','Withdrawal paid','Paystack confirmed that your withdrawal was paid.',
    v_withdrawal.id::text,'withdrawal',v_withdrawal.id::text,
    case when v_wallet.owner_type='worker' then 'worker_wallet' else 'partner_finance' end,
    jsonb_build_object('withdrawal_id',v_withdrawal.id),
    'withdrawal-final:'||v_withdrawal.id::text||':paid',
    case when v_wallet.owner_type='worker' then 'worker' else 'property_partner' end
  ) on conflict do nothing;
  return jsonb_build_object('success',true,'status','paid','amount',v_withdrawal.amount);
end;
$$;


--
-- Name: share_property_to_roommate(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.share_property_to_roommate(p_conversation_id uuid, p_listing_id text, p_client_event_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conversation public.conversations;
  v_peer text;
  v_listing public.listings;
  v_thread_id uuid;
  v_item_id uuid;
  v_message_id uuid;
  v_event_key text;
  v_payload jsonb;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null or not public.current_actor_has_personal_workspace() then
    raise exception 'An active Personal account is required';
  end if;

  select * into v_conversation from public.conversations
  where id=p_conversation_id
    and conversation_type='roommate'
    and coalesce(status,'active') in('active','accepted')
    and v_actor.user_id in(participant_a,participant_b)
  for update;
  if v_conversation.id is null then
    raise exception 'Choose an accepted roommate conversation';
  end if;
  v_peer:=case when v_conversation.participant_a=v_actor.user_id
    then v_conversation.participant_b else v_conversation.participant_a end;
  if exists(
    select 1 from public.roommate_user_blocks block_row
    where (block_row.blocker_user_id=v_actor.user_id and block_row.blocked_user_id=v_peer)
       or (block_row.blocker_user_id=v_peer and block_row.blocked_user_id=v_actor.user_id)
  ) then raise exception 'This roommate connection is blocked'; end if;

  select * into v_listing from public.listings
  where (id::text=p_listing_id or listing_id=p_listing_id)
    and deleted_at is null
    and status='available' and availability_status='available'
    and property_type='apartment'
  limit 1;
  if v_listing.id is null then raise exception 'This property is unavailable'; end if;

  if nullif(btrim(coalesce(p_client_event_id,'')),'') is null
    or length(p_client_event_id)>100 then
    raise exception 'A valid client event ID is required';
  end if;
  v_event_key:='roommate-property-share:'||v_actor.user_id||':'||p_client_event_id;
  v_payload:=jsonb_strip_nulls(jsonb_build_object(
    'listing_id',v_listing.id::text,
    'listing_public_id',v_listing.listing_id,
    'title',v_listing.title,
    'image',v_listing.images[1],
    'city',v_listing.city,
    'state',v_listing.state,
    'price',v_listing.price,
    'currency','NGN',
    'product_type',case when v_listing.sub_type='short_let'
      then 'short_let' else 'long_let' end
  ));

  insert into public.canonical_threads(
    thread_type,subject_type,subject_id,state,created_at,updated_at
  ) values(
    'direct','roommate_conversation',v_conversation.id::text,'open',now(),now()
  ) on conflict(thread_type,subject_type,subject_id) do update
    set state=case when canonical_threads.state='closed' then 'read_only'
      else canonical_threads.state end,
      updated_at=now()
  returning thread_id into v_thread_id;

  insert into public.canonical_thread_participants(
    thread_id,user_id,participant_role,can_message,can_view_obligation
  ) values
    (v_thread_id,v_actor.user_id,'roommate',true,true),
    (v_thread_id,v_peer,'roommate',true,true)
  on conflict(thread_id,user_id) do update set
    left_at=null,can_message=true,can_view_obligation=true;

  insert into public.canonical_thread_items(
    thread_id,item_type,sender_user_id,body,payload,event_key
  ) values(
    v_thread_id,'property_share',v_actor.user_id,null,v_payload,v_event_key
  ) on conflict(event_key) do update set event_key=excluded.event_key
  returning thread_item_id into v_item_id;

  select id into v_message_id from public.messages
  where conversation_id=v_conversation.id and item_type='property_share'
    and item_payload->>'canonical_thread_item_id'=v_item_id::text
  limit 1;
  if v_message_id is not null then return v_message_id; end if;

  insert into public.messages(
    conversation_id,sender_id,content,seen,item_type,item_payload,created_at
  ) values(
    v_conversation.id,v_actor.user_id,'Shared a property',false,
    'property_share',v_payload||jsonb_build_object(
      'canonical_thread_id',v_thread_id,
      'canonical_thread_item_id',v_item_id
    ),now()
  ) returning id into v_message_id;

  update public.conversations set
    last_message='Shared a property',last_message_at=now(),
    unread_a=case when participant_a=v_actor.user_id
      then coalesce(unread_a,0) else coalesce(unread_a,0)+1 end,
    unread_b=case when participant_b=v_actor.user_id
      then coalesce(unread_b,0) else coalesce(unread_b,0)+1 end
  where id=v_conversation.id;
  return v_message_id;
end
$$;


--
-- Name: snapshot_hotel_arrival_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_hotel_arrival_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_policy record;
  v_hours integer;
begin
  if tg_op='UPDATE'
     and old.arrival_issue_policy_version_id is not null
     and new.arrival_issue_policy_version_id is distinct from old.arrival_issue_policy_version_id then
    raise exception 'A booked arrival policy snapshot is immutable';
  end if;
  if new.arrival_issue_policy_version_id is not null then return new; end if;
  select * into v_policy from public.current_accommodation_arrival_policy();
  if v_policy.policy_version_id is null then
    raise exception 'Active accommodation arrival-issue policy required';
  end if;
  select coalesce(plan.arrival_issue_window_hours,hotel.arrival_issue_window_hours)
  into v_hours
  from public.hotels hotel
  left join public.hotel_rate_plans plan on plan.rate_plan_id=new.rate_plan_id
    and plan.hotel_id=hotel.hotel_id
  where hotel.hotel_id=new.hotel_id;
  v_hours:=coalesce(v_hours,v_policy.default_hours);
  if v_hours<v_policy.minimum_hours or v_hours>v_policy.maximum_hours then
    raise exception 'Hotel arrival-issue window must be between % and % hours',
      v_policy.minimum_hours,v_policy.maximum_hours;
  end if;
  new.arrival_issue_policy_version_id:=v_policy.policy_version_id;
  new.arrival_issue_window_hours:=v_hours;
  return new;
end
$$;


--
-- Name: snapshot_hotel_arrival_policy_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_hotel_arrival_policy_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.checked_in_at is not null and old.checked_in_at is null then
    insert into public.obligation_policy_snapshots(
      subject_type,subject_id,policy_version_id,calculated_value
    ) values(
      'hotel',new.booking_id::text,new.arrival_issue_policy_version_id,
      jsonb_build_object('arrival_issue_window_hours',new.arrival_issue_window_hours,
        'arrival_issue_deadline_at',new.arrival_issue_deadline_at,
        'authorized_check_in_at',new.checked_in_at)
    ) on conflict(subject_type,subject_id,policy_version_id) do nothing;
  end if;
  return new;
end
$$;


--
-- Name: snapshot_short_stay_arrival_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.snapshot_short_stay_arrival_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_policy record;
  v_hours integer;
begin
  if new.stay_type is distinct from 'short_let' then return new; end if;
  if tg_op='UPDATE'
     and old.arrival_issue_policy_version_id is not null
     and new.arrival_issue_policy_version_id is distinct from old.arrival_issue_policy_version_id then
    raise exception 'A booked arrival policy snapshot is immutable';
  end if;
  if new.arrival_issue_policy_version_id is not null then return new; end if;
  select * into v_policy from public.current_accommodation_arrival_policy();
  if v_policy.policy_version_id is null then
    raise exception 'Active accommodation arrival-issue policy required';
  end if;
  select listing.arrival_issue_window_hours into v_hours
  from public.listings listing
  where listing.listing_id=new.listing_id or listing.id::text=new.listing_id
  limit 1;
  v_hours:=coalesce(v_hours,v_policy.default_hours);
  if v_hours<v_policy.minimum_hours or v_hours>v_policy.maximum_hours then
    raise exception 'Short Let arrival-issue window must be between % and % hours',
      v_policy.minimum_hours,v_policy.maximum_hours;
  end if;
  new.arrival_issue_policy_version_id:=v_policy.policy_version_id;
  new.arrival_issue_window_hours:=v_hours;
  return new;
end
$$;


--
-- Name: soft_delete_listing_internal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.soft_delete_listing_internal(p_listing_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor public.profiles; v_listing public.listings;
BEGIN
  SELECT * INTO v_actor FROM public.profiles
  WHERE auth_id=auth.uid()::text AND role IN ('staff','admin','creator')
    AND NOT COALESCE(deleted,false) AND NOT COALESCE(suspended,false) AND NOT COALESCE(banned,false)
  LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'WeHouse operations access required'; END IF;
  IF v_actor.role='staff' AND NOT EXISTS(
    SELECT 1 FROM public.staff_permissions sp WHERE sp.staff_id=v_actor.user_id AND sp.permission='operations' AND sp.is_active=true
  ) THEN RAISE EXCEPTION 'Operations Staff permission required'; END IF;
  SELECT * INTO v_listing FROM public.listings WHERE id=p_listing_id AND deleted_at IS NULL FOR UPDATE;
  IF v_listing IS NULL THEN RETURN false; END IF;
  IF v_actor.role<>'creator' AND NOT public.current_actor_in_scope(v_listing.state,v_listing.city) THEN
    RAISE EXCEPTION 'Listing is outside your assigned State/LGA';
  END IF;
  UPDATE public.listings SET status='closed',availability_status='closed',deleted_at=now() WHERE id=p_listing_id;
  RETURN true;
END; $$;


--
-- Name: split_shared_short_let_protection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_shared_short_let_protection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_payment public.booking_payments;
  v_group_id uuid;
  v_member_id uuid;
  v_stay numeric(12,2);
  v_caution numeric(12,2);
  v_rate numeric;
  v_stay_protection uuid;
  v_caution_protection uuid;
begin
  if new.subject_type<>'shared_housing_share' then return new; end if;
  select * into v_payment from public.booking_payments
  where paystack_reference=new.paystack_reference and purpose='shared_housing_share';
  if v_payment.id is null
    or v_payment.metadata->>'canonical_product_type'<>'short_let' then return new; end if;
  v_group_id:=(v_payment.metadata->>'canonical_shared_payment_group_id')::uuid;
  v_member_id:=(v_payment.metadata->>'canonical_shared_payment_member_id')::uuid;
  v_stay:=round(coalesce((v_payment.metadata->>'eligible_partner_amount')::numeric,0),2);
  v_caution:=round(coalesce((v_payment.metadata->>'refundable_amount')::numeric,0),2);
  if v_stay<=0 or v_stay+v_caution<>new.amount_total then
    raise exception 'Shared Short Let Stay and Caution allocation is invalid'; end if;
  select (p.value->>'percent')::numeric into v_rate
  from public.creator_policy_versions p
  where p.policy_key='commission_short_let' and p.scope_type='global'
    and p.scope_key='*' and p.status='active' and p.effective_from<=now()
    and (p.effective_until is null or p.effective_until>now())
  order by p.effective_from desc limit 1;
  if v_rate is null or v_rate<0 or v_rate>50 then
    raise exception 'Active Creator Short Let commission is required'; end if;
  insert into public.payment_protection_transactions(
    booking_id,booking_type,payer_user_id,payee_user_id,amount_total,
    amount_commission,amount_payee,commission_rate,status,paystack_reference,
    protection_state,subject_type,subject_id
  ) values(
    null,'short_let_stay',new.payer_user_id,new.payee_user_id,v_stay,
    round(v_stay*v_rate/100,2),v_stay-round(v_stay*v_rate/100,2),v_rate,
    'protected',new.paystack_reference,'awaiting_funds','short_let_stay',
    'shared:'||v_member_id::text||':stay:'||(v_payment.metadata->>'checkout_attempt')
  ) on conflict(subject_type,subject_id) do update
    set paystack_reference=excluded.paystack_reference,updated_at=now()
  returning id into v_stay_protection;
  insert into public.shared_payment_protection_components(
    shared_payment_group_id,shared_payment_member_id,payment_protection_id,
    component_type,amount,provider_reference
  ) values(v_group_id,v_member_id,v_stay_protection,'short_let_stay',v_stay,new.paystack_reference)
  on conflict(payment_protection_id) do nothing;
  if v_caution>0 then
    insert into public.payment_protection_transactions(
      booking_id,booking_type,payer_user_id,payee_user_id,amount_total,
      amount_commission,amount_payee,commission_rate,status,paystack_reference,
      protection_state,subject_type,subject_id
    ) values(
      null,'short_let_caution',new.payer_user_id,new.payee_user_id,v_caution,
      0,v_caution,0,'protected',new.paystack_reference,'awaiting_funds',
      'short_let_caution','shared:'||v_member_id::text||':caution:'||
        (v_payment.metadata->>'checkout_attempt')
    ) on conflict(subject_type,subject_id) do update
      set paystack_reference=excluded.paystack_reference,updated_at=now()
    returning id into v_caution_protection;
    insert into public.shared_payment_protection_components(
      shared_payment_group_id,shared_payment_member_id,payment_protection_id,
      component_type,amount,provider_reference
    ) values(v_group_id,v_member_id,v_caution_protection,'short_let_caution',v_caution,new.paystack_reference)
    on conflict(payment_protection_id) do nothing;
  end if;
  return null;
end
$$;


--
-- Name: staff_assign_customer_inspection(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_assign_customer_inspection(p_inspection_id uuid, p_field_officer_id text, p_scheduled_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.user_inspection_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor public.profiles; v_req public.user_inspection_requests; v_listing public.listings; v_officer public.profiles;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND role IN ('admin','creator')
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Admin or Creator access required'; END IF;
  SELECT * INTO v_req FROM public.user_inspection_requests WHERE id=p_inspection_id AND status='pending' FOR UPDATE;
  IF v_req IS NULL THEN RAISE EXCEPTION 'Pending inspection request not found'; END IF;
  SELECT * INTO v_listing FROM public.listings WHERE id::text=v_req.listing_id OR listing_id=v_req.listing_id LIMIT 1;
  IF v_listing IS NULL THEN RAISE EXCEPTION 'Inspection listing not found'; END IF;
  IF v_actor.role='admin' AND NOT public.current_actor_in_scope(v_listing.state,v_listing.city) THEN RAISE EXCEPTION 'Inspection is outside your assigned branch'; END IF;
  SELECT * INTO v_officer FROM public.profiles WHERE user_id=p_field_officer_id AND role='staff'
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_officer IS NULL OR lower(COALESCE(v_officer.assigned_state,''))<>lower(COALESCE(v_listing.state,''))
    OR lower(COALESCE(v_officer.assigned_lga,''))<>lower(COALESCE(v_listing.city,''))
    OR NOT EXISTS(SELECT 1 FROM public.staff_permissions sp WHERE sp.staff_id=v_officer.user_id AND sp.permission='field_officer' AND sp.is_active=true)
  THEN RAISE EXCEPTION 'Eligible Field Officer in the listing branch is required'; END IF;
  UPDATE public.user_inspection_requests SET field_officer_id=v_officer.user_id,status='scheduled',scheduled_date=p_scheduled_date,updated_at=now()
  WHERE id=p_inspection_id RETURNING * INTO v_req;
  RETURN v_req;
END;
$$;


--
-- Name: staff_branch_analytics(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_branch_analytics(p_staff_user_id text) RETURNS TABLE(metric text, value integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_staff record; v_permission text; v_actor text;
begin
  select user_id into v_actor from public.profiles where auth_id=auth.uid()::text and role='staff' and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor is null or v_actor<>p_staff_user_id then raise exception 'Staff account required'; end if;
  select assigned_state,assigned_lga,scope into v_staff from public.profiles where user_id=p_staff_user_id and role='staff';
  if v_staff.assigned_state is null or v_staff.assigned_lga is null then metric:='unassigned'; value:=1; return next; return; end if;
  select permission into v_permission from public.staff_permissions where staff_id=p_staff_user_id and is_active=true limit 1;
  if v_permission='field_officer' then metric:='inspections'; select count(*)::integer into value from public.user_inspection_requests uir join public.listings l on l.id=uir.listing_id where l.state=v_staff.assigned_state and coalesce(l.city,l.local_government)=v_staff.assigned_lga and uir.field_officer_id=p_staff_user_id and uir.status in ('scheduled','in_progress'); return next; end if;
  if v_permission='support' then metric:='open_conversations'; select count(*)::integer into value from public.partner_support_conversations c join public.profiles p on p.user_id=c.partner_id where c.status not in ('resolved','closed') and p.state=v_staff.assigned_state and coalesce(nullif(p.local_government,''),p.city)=v_staff.assigned_lga; return next; end if;
  if v_permission='operations' then metric:='pending_listings'; select count(*)::integer into value from public.listings where status='pending_approval' and state=v_staff.assigned_state and coalesce(city,local_government)=v_staff.assigned_lga; return next; end if;
  if v_permission='verification' then metric:='pending_workers'; select count(*)::integer into value from public.profiles where role='worker' and worker_status='pending' and state=v_staff.assigned_state and coalesce(local_government,city)=v_staff.assigned_lga; return next; end if;
  if v_permission='finance' then metric:='pending_withdrawals'; select count(*)::integer into value from public.withdrawals w join public.wallets wl on wl.id=w.wallet_id join public.profiles p on p.user_id=wl.owner_id where w.status='pending' and p.state=v_staff.assigned_state and coalesce(p.local_government,p.city)=v_staff.assigned_lga; return next; end if;
end $$;


--
-- Name: staff_complete_customer_inspection(uuid, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_complete_customer_inspection(p_inspection_id uuid, p_report text, p_condition text, p_photo_urls text[] DEFAULT ARRAY[]::text[]) RETURNS public.user_inspection_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor public.profiles; v_req public.user_inspection_requests;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND role IN ('staff','admin','creator')
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Field operations access required'; END IF;
  IF NULLIF(BTRIM(COALESCE(p_report,'')),'') IS NULL OR NULLIF(BTRIM(COALESCE(p_condition,'')),'') IS NULL THEN RAISE EXCEPTION 'Inspection report and condition are required'; END IF;
  SELECT * INTO v_req FROM public.user_inspection_requests WHERE id=p_inspection_id AND status='in_progress' FOR UPDATE;
  IF v_req IS NULL THEN RAISE EXCEPTION 'Active inspection not found'; END IF;
  IF v_actor.role='staff' THEN
    IF v_req.field_officer_id<>v_actor.user_id OR NOT public.current_staff_has_permission('field_officer') THEN RAISE EXCEPTION 'Inspection is not assigned to this Field Officer'; END IF;
  ELSIF v_actor.role='admin' AND NOT public.current_actor_can_access_listing_ref(v_req.listing_id) THEN RAISE EXCEPTION 'Inspection is outside your assigned branch'; END IF;
  UPDATE public.user_inspection_requests SET status='completed',report=BTRIM(p_report),condition=BTRIM(p_condition),photo_urls=COALESCE(p_photo_urls,ARRAY[]::text[]),updated_at=now()
  WHERE id=p_inspection_id RETURNING * INTO v_req;
  UPDATE public.reservations SET inspection_completed=true,inspection_completed_at=now(),updated_at=now() WHERE id=v_req.reservation_id;
  RETURN v_req;
END;
$$;


--
-- Name: staff_start_customer_inspection(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_start_customer_inspection(p_inspection_id uuid) RETURNS public.user_inspection_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_actor public.profiles; v_req public.user_inspection_requests;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text AND role IN ('staff','admin','creator')
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Field operations access required'; END IF;
  SELECT * INTO v_req FROM public.user_inspection_requests WHERE id=p_inspection_id AND status='scheduled' FOR UPDATE;
  IF v_req IS NULL THEN RAISE EXCEPTION 'Scheduled inspection not found'; END IF;
  IF v_actor.role='staff' THEN
    IF v_req.field_officer_id<>v_actor.user_id OR NOT public.current_staff_has_permission('field_officer') THEN RAISE EXCEPTION 'Inspection is not assigned to this Field Officer'; END IF;
  ELSIF v_actor.role='admin' AND NOT public.current_actor_can_access_listing_ref(v_req.listing_id) THEN RAISE EXCEPTION 'Inspection is outside your assigned branch'; END IF;
  UPDATE public.user_inspection_requests SET status='in_progress',updated_at=now() WHERE id=p_inspection_id RETURNING * INTO v_req;
  RETURN v_req;
END;
$$;


--
-- Name: start_my_roommate_search(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_my_roommate_search() RETURNS public.roommate_preferences
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_row public.roommate_preferences;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_actor IS NULL OR not public.current_actor_has_personal_workspace() THEN RAISE EXCEPTION 'Roommate matching is available to regular users only'; END IF;
  IF COALESCE(v_actor.deleted,false) OR COALESCE(v_actor.suspended,false) OR COALESCE(v_actor.banned,false) THEN RAISE EXCEPTION 'Account is not active'; END IF;
  IF NOT COALESCE(v_actor.profile_complete,false) THEN RAISE EXCEPTION 'Complete your profile first'; END IF;
  IF COALESCE(v_actor.privacy_search_visible,true)=false OR COALESCE(v_actor.privacy_profile_visible,true)=false THEN RAISE EXCEPTION 'Enable Roommate discovery and profile visibility first'; END IF;
  IF NULLIF(BTRIM(COALESCE(v_actor.gender,'')),'') IS NULL THEN RAISE EXCEPTION 'Add your gender first'; END IF;
  IF NULLIF(BTRIM(COALESCE(v_actor.state,'')),'') IS NULL THEN RAISE EXCEPTION 'Add your State first'; END IF;
  SELECT * INTO v_row FROM public.roommate_preferences WHERE user_id=v_actor.user_id FOR UPDATE;
  IF v_row IS NULL THEN RAISE EXCEPTION 'Save roommate preferences first'; END IF;
  IF COALESCE(v_row.school_match,false) AND NULLIF(BTRIM(COALESCE(v_row.school_name,v_actor.school,'')),'') IS NULL THEN RAISE EXCEPTION 'Enter your school before using same-school matching'; END IF;
  UPDATE public.roommate_preferences SET active=true,search_status='active',search_started_at=COALESCE(search_started_at,now()),search_expires_at=NULL,updated_at=now() WHERE user_id=v_actor.user_id RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


--
-- Name: start_my_shared_contract_split(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_my_shared_contract_split(p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_group public.shared_housing_groups;
  v_listing public.listings;
  v_count integer;
  v_total numeric(12,2);
  v_eligible numeric(12,2);
  v_refundable numeric(12,2);
  v_index integer:=0;
  v_assigned numeric(12,2):=0;
  v_eligible_assigned numeric(12,2):=0;
  v_refundable_assigned numeric(12,2):=0;
  v_member public.shared_housing_members;
  v_share numeric(12,2);
  v_eligible_share numeric(12,2);
  v_refundable_share numeric(12,2);
begin
  select * into v_group from public.shared_housing_groups where id=p_group_id for update;
  if v_group.id is null or v_group.created_by<>v_actor then
    raise exception 'Only the group creator can start the Long Let payment'; end if;
  if v_group.product_type<>'long_let' then raise exception 'This is not a Long Let'; end if;
  if v_group.reservation_id is null or not exists(
    select 1 from public.reservations where id=v_group.reservation_id and inspection_result='passed'
  ) then raise exception 'Property inspection must pass first'; end if;
  if v_group.status not in('paid','refunded') then
    raise exception 'The earlier shared checkout must be complete'; end if;
  select * into v_listing from public.listings where id=v_group.listing_id;
  v_eligible:=round(v_listing.price,2);
  v_refundable:=round(coalesce(v_listing.security_deposit_amount,0),2);
  v_total:=v_eligible+v_refundable;
  select count(*) into v_count from public.shared_housing_members
  where group_id=p_group_id and invitation_status='accepted';
  if v_count<2 or v_count>coalesce(v_listing.max_occupants,1) then
    raise exception 'Accepted occupants exceed this Long Let capacity'; end if;
  update public.shared_housing_groups set
    status='payment_pending',payment_phase='contract_rent',total_amount=v_total,
    contract_total=v_total,expires_at=now()+interval '30 minutes',
    checkout_attempt=checkout_attempt+1,updated_at=now()
  where id=p_group_id returning * into v_group;
  update public.shared_payment_groups set
    status='checkout_open',payment_phase='contract_rent',total_amount=v_total,
    checkout_expires_at=v_group.expires_at,checkout_attempt=v_group.checkout_attempt,
    updated_at=now()
  where shared_payment_group_id=v_group.canonical_group_id;
  for v_member in select * from public.shared_housing_members
    where group_id=p_group_id and invitation_status='accepted' order by created_at,id
  loop
    v_index:=v_index+1;
    v_share:=case when v_index=v_count then v_total-v_assigned else round(v_total/v_count,2) end;
    v_eligible_share:=case when v_index=v_count then v_eligible-v_eligible_assigned else round(v_eligible/v_count,2) end;
    v_refundable_share:=case when v_index=v_count then v_refundable-v_refundable_assigned else round(v_refundable/v_count,2) end;
    update public.shared_housing_members set share_amount=v_share,
      eligible_partner_share=v_eligible_share,refundable_share=v_refundable_share,
      payment_status='not_started',payment_reference=null,paid_at=null,updated_at=now()
    where id=v_member.id;
    update public.shared_payment_members set share_amount=v_share,
      eligible_partner_share=v_eligible_share,refundable_share=v_refundable_share,
      payment_state='not_started',provider_reference=null,paid_at=null,updated_at=now()
    where shared_payment_member_id=v_member.canonical_member_id;
    v_assigned:=v_assigned+v_share;
    v_eligible_assigned:=v_eligible_assigned+v_eligible_share;
    v_refundable_assigned:=v_refundable_assigned+v_refundable_share;
  end loop;
  update public.reservations set rent_payment_status='payment_pending',updated_at=now()
  where id=v_group.reservation_id;
  return public.get_my_shared_housing_group(p_group_id);
end
$$;


--
-- Name: start_my_worker_test(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_my_worker_test() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_profile public.profiles; v_paid boolean; v_attempt public.worker_test_attempts; v_ids uuid[]; v_questions jsonb; v_recent_failed integer;
BEGIN
  SELECT * INTO v_profile FROM public.profiles WHERE auth_id=auth.uid()::text AND public.user_has_active_workspace(user_id,'worker') AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'Active Worker account required'; END IF;
  SELECT EXISTS(SELECT 1 FROM public.booking_payments WHERE user_id=v_profile.user_id AND purpose='worker_verification' AND status IN ('paid','completed')) INTO v_paid;
  IF NOT v_paid THEN RAISE EXCEPTION 'Verified Paystack payment is required before the Worker test'; END IF;
  IF public.worker_test_passed(v_profile.user_id) THEN
    SELECT * INTO v_attempt FROM public.worker_test_attempts WHERE worker_id=v_profile.user_id AND passed=true ORDER BY submitted_at DESC LIMIT 1;
    RETURN jsonb_build_object('already_passed',true,'passed',true,'score',v_attempt.score,'total',v_attempt.total_questions,'percent',v_attempt.percent,'pass_percent',80);
  END IF;
  UPDATE public.worker_test_attempts SET submitted_at=now(),score=0,percent=0,passed=false,answers='{}'::jsonb WHERE worker_id=v_profile.user_id AND submitted_at IS NULL AND started_at < now()-interval '45 minutes';
  SELECT count(*) INTO v_recent_failed FROM public.worker_test_attempts WHERE worker_id=v_profile.user_id AND submitted_at IS NOT NULL AND submitted_at >= now()-interval '24 hours' AND passed=false;
  IF v_recent_failed>=5 THEN RAISE EXCEPTION 'Daily Worker test attempt limit reached. Try again after 24 hours'; END IF;
  SELECT * INTO v_attempt FROM public.worker_test_attempts WHERE worker_id=v_profile.user_id AND submitted_at IS NULL ORDER BY started_at DESC LIMIT 1;
  IF v_attempt IS NULL THEN
    SELECT array_agg(id) INTO v_ids FROM (SELECT id FROM public.worker_test_questions WHERE is_active=true AND (category IS NULL OR lower(category)=lower(COALESCE(v_profile.worker_occupation,''))) ORDER BY CASE WHEN category IS NULL THEN 1 ELSE 0 END, random() LIMIT 8) q;
    IF COALESCE(array_length(v_ids,1),0)<5 THEN RAISE EXCEPTION 'Worker test question bank is not configured'; END IF;
    INSERT INTO public.worker_test_attempts(worker_id,question_ids,total_questions) VALUES(v_profile.user_id,v_ids,array_length(v_ids,1)) RETURNING * INTO v_attempt;
  ELSE v_ids:=v_attempt.question_ids; END IF;
  SELECT jsonb_agg(jsonb_build_object('id',q.id,'question',q.question,'options',q.options) ORDER BY u.ord) INTO v_questions FROM unnest(v_ids) WITH ORDINALITY AS u(id,ord) JOIN public.worker_test_questions q ON q.id=u.id;
  RETURN jsonb_build_object('already_passed',false,'attempt_id',v_attempt.id,'questions',COALESCE(v_questions,'[]'::jsonb),'pass_percent',80,'expires_at',v_attempt.started_at+interval '45 minutes');
END; $$;


--
-- Name: start_private_call(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_private_call(p_context_type text, p_context_id uuid, p_call_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_me text := public.current_profile_user_id();
  v_cap jsonb;
  v_peer text;
  v_call public.private_calls;
begin
  if v_me is null then raise exception 'Authenticated profile required'; end if;
  if p_call_type not in ('audio', 'video') then raise exception 'Invalid call type'; end if;
  v_cap := public.get_private_call_capabilities(p_context_type, p_context_id);
  v_peer := v_cap ->> 'peer_id';
  if p_call_type = 'audio' and not coalesce((v_cap ->> 'allow_audio_calls')::boolean, false) then
    raise exception 'This person is not accepting audio calls';
  end if;
  if p_call_type = 'video' and not coalesce((v_cap ->> 'allow_video_calls')::boolean, false) then
    raise exception 'This person is not accepting video calls';
  end if;
  if exists (
    select 1 from public.private_calls c
    where c.status in ('ringing', 'accepted')
      and (v_me in (c.caller_id, c.callee_id) or v_peer in (c.caller_id, c.callee_id))
  ) then raise exception 'One of you is already in a call'; end if;
  insert into public.private_calls(context_type, context_id, caller_id, callee_id, call_type, status)
  values (p_context_type, p_context_id, v_me, v_peer, p_call_type, 'ringing')
  returning * into v_call;
  return to_jsonb(v_call) || jsonb_build_object(
    'peer_name', v_cap ->> 'peer_name',
    'peer_avatar', v_cap ->> 'peer_avatar'
  );
end;
$$;


--
-- Name: stop_my_roommate_search(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stop_my_roommate_search() RETURNS public.roommate_preferences
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id text; v_row public.roommate_preferences;
BEGIN
  SELECT user_id INTO v_id FROM public.profiles WHERE auth_id=auth.uid()::text AND account_kind='consumer' AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_id IS NULL THEN RAISE EXCEPTION 'Regular user account required'; END IF;
  UPDATE public.roommate_preferences SET active=false,search_status='stopped',search_expires_at=NULL,updated_at=now() WHERE user_id=v_id RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;


--
-- Name: submit_my_property_access_challenge(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_my_property_access_challenge(p_challenge_id uuid, p_video_path text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'storage'
    AS $_$
declare
  v_actor public.profiles;
  v_row public.property_access_challenges;
  v_duration integer;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null
     or not public.current_actor_has_workspace('property_partner',null) then
    raise exception 'Property Partner workspace required';
  end if;
  select * into v_row
  from public.property_access_challenges
  where id=p_challenge_id and partner_id=v_actor.user_id
  for update;
  if v_row.id is null then raise exception 'Property access challenge not found'; end if;
  if v_row.status='submitted' and v_row.video_path is not null then
    return jsonb_build_object(
      'success',true,'status','submitted','already_submitted',true,
      'video_path',v_row.video_path,
      'duration_seconds',v_row.duration_seconds
    );
  end if;
  if v_row.status='consumed' then
    raise exception 'This property was already submitted';
  end if;
  if v_row.status<>'prepared' then
    raise exception 'Create a new one-use recording code';
  end if;
  if v_row.expires_at<=now() then
    update public.property_access_challenges
    set status='expired' where id=v_row.id;
    raise exception 'The one-use code expired. Create a new code and record again';
  end if;
  if split_part(p_video_path,'/',1)<>v_actor.user_id
     or split_part(p_video_path,'/',2)<>p_challenge_id::text then
    raise exception 'Invalid private property access path';
  end if;
  v_duration:=nullif((regexp_match(
    p_video_path,'-([0-9]+)s[.][a-z0-9]+$'
  ))[1],'')::integer;
  if coalesce(v_duration,0)<20 then
    raise exception 'Record at least 20 seconds of continuous entrance-to-interior access evidence';
  end if;
  if not exists(
    select 1 from storage.objects object
    where object.bucket_id='property-access-private'
      and object.name=p_video_path
  ) then raise exception 'Private property access recording was not found'; end if;
  update public.property_access_challenges
  set video_path=p_video_path,duration_seconds=v_duration,
      status='submitted',submitted_at=now()
  where id=v_row.id;
  return jsonb_build_object(
    'success',true,'status','submitted','already_submitted',false,
    'video_path',p_video_path,'duration_seconds',v_duration
  );
end
$_$;


--
-- Name: submit_my_property_access_correction(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_my_property_access_correction(p_request_id uuid, p_challenge_id uuid, p_video_path text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'storage'
    AS $_$
declare
  v_actor public.profiles;
  v_request public.inspection_requests;
  v_challenge public.property_access_challenges;
  v_previous_path text;
  v_duration integer;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null
     or not public.current_actor_has_workspace('property_partner',null) then
    raise exception 'Property Partner workspace required';
  end if;
  select * into v_request
  from public.inspection_requests
  where id=p_request_id and owner_id=v_actor.user_id
  for update;
  if v_request.id is null then raise exception 'Property submission not found'; end if;
  if v_request.access_evidence_status<>'rejected'
     or v_request.lifecycle_stage<>'changes_requested' then
    raise exception 'Replacement evidence is not currently requested';
  end if;
  select * into v_challenge
  from public.property_access_challenges
  where id=p_challenge_id and partner_id=v_actor.user_id
    and request_id=p_request_id
  for update;
  if v_challenge.id is null or v_challenge.status<>'prepared' then
    raise exception 'This one-use correction code is unavailable';
  end if;
  if v_challenge.expires_at<=now() then
    update public.property_access_challenges
    set status='expired' where id=p_challenge_id;
    raise exception 'The one-use code expired. Create a new code and record again';
  end if;
  if split_part(p_video_path,'/',1)<>v_actor.user_id
     or split_part(p_video_path,'/',2)<>p_challenge_id::text then
    raise exception 'Invalid private property access path';
  end if;
  v_duration:=nullif((regexp_match(
    p_video_path,'-([0-9]+)s[.][a-z0-9]+$'
  ))[1],'')::integer;
  if coalesce(v_duration,0)<20 then
    raise exception 'Record at least 20 seconds of continuous entrance-to-interior access evidence';
  end if;
  if not exists(
    select 1 from storage.objects object
    where object.bucket_id='property-access-private'
      and object.name=p_video_path
  ) then raise exception 'Private property access recording was not found'; end if;
  v_previous_path:=v_request.access_evidence_video_path;
  update public.property_access_challenges
  set video_path=p_video_path,duration_seconds=v_duration,status='consumed',
      submitted_at=now(),consumed_at=now()
  where id=p_challenge_id;
  update public.inspection_requests
  set access_evidence_video_path=p_video_path,
      access_evidence_duration_seconds=v_duration,
      access_evidence_status='submitted',updated_at=now()
  where id=p_request_id;
  if v_previous_path is not null and v_previous_path<>p_video_path then
    delete from storage.objects
    where bucket_id='property-access-private' and name=v_previous_path;
  end if;
  return jsonb_build_object(
    'success',true,'status','submitted','duration_seconds',v_duration
  );
end
$_$;


--
-- Name: submit_my_property_access_evidence(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_my_property_access_evidence(p_request_id uuid, p_video_path text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'storage'
    AS $$
declare v_actor public.profiles; v_request public.inspection_requests;
begin
  select * into v_actor from public.profiles where auth_id=auth.uid()::text and public.user_has_active_workspace(user_id,'property_partner')
    and not coalesce(deleted,false) and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor is null then raise exception 'Active Property Partner account required'; end if;
  if not public.account_identity_is_current(v_actor.user_id) then raise exception 'Complete the private identity check before submitting access evidence'; end if;
  select * into v_request from public.inspection_requests where id=p_request_id and owner_id=v_actor.user_id for update;
  if v_request.id is null then raise exception 'Property request not found'; end if;
  if v_request.access_challenge_expires_at<=now() then raise exception 'This temporary code expired. Request a new code'; end if;
  if split_part(p_video_path,'/',1)<>v_actor.user_id or split_part(p_video_path,'/',2)<>p_request_id::text then raise exception 'Invalid private access evidence path'; end if;
  if not exists(select 1 from storage.objects where bucket_id='property-access-private' and name=p_video_path) then raise exception 'Private access evidence upload was not found'; end if;
  update public.inspection_requests set access_evidence_video_path=p_video_path,access_evidence_status='submitted',
    access_evidence_submitted_at=now(),updated_at=now() where id=p_request_id;
  insert into public.audit_logs(action,target_type,target_id,details,admin_id,admin_email)
  values('PROPERTY_ACCESS_EVIDENCE_SUBMITTED','inspection_requests',p_request_id::text,
    jsonb_build_object('request_code',v_request.request_code,'relationship',v_request.authority_relationship)::text,v_actor.user_id,v_actor.email);
  return jsonb_build_object('success',true,'status','submitted');
end $$;


--
-- Name: submit_my_worker_booking_review(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_my_worker_booking_review(p_booking_id uuid, p_rating integer, p_comment text DEFAULT NULL::text) RETURNS public.worker_booking_reviews
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor public.profiles;booking public.worker_bookings;result public.worker_booking_reviews;
begin
  select * into actor from public.profiles where auth_id=auth.uid()::text limit 1;
  if actor is null or not public.current_actor_has_personal_workspace() then raise exception 'Personal workspace required';end if;
  if p_rating not between 1 and 5 then raise exception 'Choose a rating from 1 to 5';end if;
  select * into booking from public.worker_bookings where id=p_booking_id and user_id=actor.user_id for update;
  if booking is null then raise exception 'Completed booking not found';end if;
  if booking.status<>'approved_released' then raise exception 'Review becomes available after the job is completed';end if;
  insert into public.worker_booking_reviews(booking_id,user_id,worker_id,rating,comment)
  values(booking.id,actor.user_id,booking.worker_id,p_rating,nullif(btrim(coalesce(p_comment,'')),''))
  on conflict(booking_id) do update set rating=excluded.rating,comment=excluded.comment,updated_at=now()
  where worker_booking_reviews.user_id=actor.user_id
  returning * into result;
  update public.profiles p set rating=summary.average,review_count=summary.total,updated_at=now()
  from(select round(avg(r.rating)::numeric,2) average,count(*)::int total from public.worker_booking_reviews r where r.worker_id=booking.worker_id)summary
  where p.user_id=booking.worker_id;
  return result;
end $$;


--
-- Name: submit_my_worker_test(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_my_worker_test(p_attempt_id uuid, p_answers jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_profile public.profiles; v_attempt public.worker_test_attempts; v_total integer; v_answered integer; v_score integer; v_percent integer; v_passed boolean;
BEGIN
  SELECT * INTO v_profile FROM public.profiles WHERE auth_id=auth.uid()::text AND public.user_has_active_workspace(user_id,'worker') AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'Active Worker account required'; END IF;
  IF jsonb_typeof(COALESCE(p_answers,'{}'::jsonb))<>'object' THEN RAISE EXCEPTION 'Invalid answers'; END IF;
  SELECT * INTO v_attempt FROM public.worker_test_attempts WHERE id=p_attempt_id AND worker_id=v_profile.user_id FOR UPDATE;
  IF v_attempt IS NULL THEN RAISE EXCEPTION 'Worker test attempt not found'; END IF;
  IF v_attempt.submitted_at IS NOT NULL THEN RETURN jsonb_build_object('score',v_attempt.score,'total',v_attempt.total_questions,'percent',v_attempt.percent,'passed',v_attempt.passed,'already_submitted',true); END IF;
  IF v_attempt.started_at < now()-interval '45 minutes' THEN RAISE EXCEPTION 'Worker test attempt expired'; END IF;
  SELECT count(*),count(*) FILTER (WHERE p_answers ? q.id::text),count(*) FILTER (WHERE p_answers ? q.id::text AND (p_answers->>q.id::text) ~ '^[0-9]+$' AND (p_answers->>q.id::text)::integer=q.correct_index)
  INTO v_total,v_answered,v_score FROM unnest(v_attempt.question_ids) AS ids(id) JOIN public.worker_test_questions q ON q.id=ids.id;
  IF v_answered<>v_total THEN RAISE EXCEPTION 'Answer every Worker test question before submitting'; END IF;
  v_percent:=CASE WHEN v_total>0 THEN floor((v_score::numeric*100)/v_total)::integer ELSE 0 END; v_passed:=v_percent>=80;
  UPDATE public.worker_test_attempts SET answers=p_answers,score=v_score,total_questions=v_total,percent=v_percent,passed=v_passed,submitted_at=now() WHERE id=v_attempt.id;
  RETURN jsonb_build_object('score',v_score,'total',v_total,'percent',v_percent,'passed',v_passed,'pass_percent',80,'already_submitted',false);
END; $_$;


--
-- Name: submit_my_worker_verification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_my_worker_verification() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_profile public.profiles;
  v_ver public.worker_verifications;
  v_identity_required boolean:=false;
begin
  select * into v_profile
  from public.profiles
  where auth_id=(select auth.uid())::text
    and public.user_has_active_workspace(user_id,'worker')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_profile is null then raise exception 'Active Worker account required'; end if;
  if not public.worker_professional_profile_ready(v_profile.user_id) then
    raise exception 'Complete your professional profile and service coverage first';
  end if;
  select coalesce(lower(btrim(value)) in ('true','1','yes','on'),false)
    into v_identity_required
  from public.platform_settings
  where key='worker_identity_checks_enabled' and coalesce(is_active,true)
  limit 1;
  if coalesce(v_identity_required,false) and not public.worker_identity_is_current(v_profile.user_id) then
    raise exception 'Complete the approved private identity check before submission';
  end if;
  select * into v_ver from public.worker_verifications
  where worker_id=v_profile.user_id limit 1;
  if v_ver is null or nullif(btrim(coalesce(v_ver.verification_video_url,'')),'') is null then
    raise exception 'A work demonstration video is required before review';
  end if;
  update public.worker_verifications
  set status='profile_under_review',submitted_at=now(),updated_at=now()
  where id=v_ver.id;
  update public.profiles
  set worker_status='profile_under_review',worker_verified=false,available=false,updated_at=now()
  where user_id=v_profile.user_id;
end;
$$;


--
-- Name: support_inbox(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_inbox(p_queue text DEFAULT 'support'::text) RETURNS TABLE(conversation_id uuid, requester_id text, requester_role text, requester_name text, requester_email text, requester_state text, requester_lga text, subject text, status text, category text, context_type text, context_id text, context_snapshot jsonb, priority text, assigned_staff_id text, assigned_staff_name text, last_message text, last_message_time timestamp with time zone, unread_count bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare actor public.profiles; v_queue text;
begin
  if p_queue not in(
    'all','operations','property_operations','reservation_operations',
    'field_operations','worker_operations','finance_operations',
    'security_operations','support'
  ) then raise exception 'Invalid communication context'; end if;
  select * into actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if actor.user_id is null then raise exception 'Authentication required'; end if;
  v_queue:=case when p_queue in(
    'operations','property_operations','reservation_operations'
  ) then 'property_operations' else p_queue end;
  if p_queue='all' and actor.role not in('creator','admin') then
    raise exception 'Creator or Admin access required'; end if;
  if p_queue<>'all' and actor.role not in('creator','admin')
    and not public.current_actor_has_workspace(v_queue,null) then
    raise exception 'This communication context is outside your work area';
  end if;

  return query
  select c.id,c.partner_id,coalesce(c.requester_role,p.role),
    coalesce(p.full_name,p.username,p.email),p.email,p.state,
    coalesce(nullif(p.local_government,''),p.city),c.subject,c.status,
    c.category,c.context_type,c.context_id,c.context_snapshot,c.priority,
    case when c.channel_kind='field_operations'
      then c.assigned_field_officer_id else c.assigned_staff_id end,
    coalesce(s.full_name,s.username),
    (select case when nullif(btrim(m.content),'') is not null then m.content
      when cardinality(m.attachments)>0 then 'Attachment' else '' end
      from public.partner_support_messages m where m.conversation_id=c.id
      and coalesce(m.visibility,'customer')<>'internal'
      order by m.created_at desc limit 1),
    (select m.created_at from public.partner_support_messages m
      where m.conversation_id=c.id and coalesce(m.visibility,'customer')<>'internal'
      order by m.created_at desc limit 1),
    (select count(*) from public.partner_support_messages m
      where m.conversation_id=c.id and not coalesce(m.is_read,false)
        and m.sender_id<>actor.user_id),c.created_at
  from public.partner_support_conversations c
  join public.profiles p on p.user_id=c.partner_id
  left join public.operational_cases oc
    on oc.operational_case_id=c.operational_case_id
  left join public.profiles s on s.user_id=case
    when c.channel_kind='field_operations' then c.assigned_field_officer_id
    else c.assigned_staff_id end
  where exists(select 1 from public.partner_support_messages m
    where m.conversation_id=c.id)
    and (
      p_queue='all' or
      case
        when c.channel_kind in('reservation_operations','property_operations')
          then 'property_operations'
        when c.channel_kind='support_case' then 'support'
        else c.channel_kind
      end=v_queue
    )
    and (
      actor.role='creator'
      or lower(btrim(coalesce(oc.state_scope,p.state,'')))
        =lower(btrim(coalesce(actor.assigned_state,actor.state,'')))
    )
  order by
    case when c.assigned_field_officer_id=actor.user_id
      or c.assigned_staff_id=actor.user_id then 0
      when c.assigned_staff_id is null then 1 else 2 end,
    c.updated_at desc;
end
$$;


--
-- Name: sweep_expired_shared_payment_checkouts(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_expired_shared_payment_checkouts(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_group record; v_count integer:=0;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  for v_group in select id from public.shared_housing_groups
    where status in('payment_pending','refunding') and expires_at<=now()
    order by expires_at for update skip locked limit least(greatest(p_limit,1),500)
  loop
    perform public.expire_shared_payment_checkout_from_service(v_group.id);
    v_count:=v_count+1;
  end loop;
  return v_count;
end
$$;


--
-- Name: sync_creator_commission_compatibility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_creator_commission_compatibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.policy_key='commission_worker' and new.scope_type='global'
    and new.scope_key='*' and new.status='active' then
    if (new.value->>'percent')::numeric<0
      or (new.value->>'percent')::numeric>50 then
      raise exception 'Invalid Creator Worker commission';
    end if;
    insert into public.platform_settings(
      key,value,category,label,description,data_type,editable,is_active,
      created_at,updated_at
    ) values(
      'worker_commission_rate',new.value->>'percent','payments',
      'Worker commission rate',
      'Compatibility read model. Creator policy registry is authoritative.',
      'number',false,true,now(),now()
    ) on conflict(key) do update set
      value=excluded.value,description=excluded.description,
      editable=false,is_active=true,updated_at=now();
  end if;
  return new;
end
$$;


--
-- Name: sync_device_activity_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_device_activity_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.notifications
  set title = case new.trust_status
        when 'pending' then 'New device needs verification'
        when 'trusted' then 'New device verified'
        else 'Device sign-in blocked'
      end,
      destination_route = 'security',
      destination_params = coalesce(destination_params, '{}'::jsonb) || jsonb_build_object(
        'decision', case new.trust_status when 'pending' then 'pending' when 'trusted' then 'approved' else 'blocked' end
      ),
      read = case when new.trust_status = 'pending' then read else true end,
      read_at = case when new.trust_status = 'pending' then read_at else coalesce(read_at, now()) end
  where recipient_id = new.user_id
    and type = 'new_device_login'
    and source_id = new.id::text;
  return new;
end;
$$;


--
-- Name: sync_hotel_inspection_canonical_media(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_hotel_inspection_canonical_media() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.inspection_request_id is not null then
    update public.inspection_requests
       set photo_urls = coalesce(new.images, array[]::text[]),
           updated_at = now()
     where id = new.inspection_request_id
       and photo_urls is distinct from coalesce(new.images, array[]::text[]);
  end if;
  return new;
end;
$$;


--
-- Name: sync_hotel_room_units(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_hotel_room_units() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  unit_count integer;
  remove_count integer;
  removed_count integer;
  candidate_number integer:=1;
  inserted_count integer;
begin
  select count(*) into unit_count
  from public.hotel_room_units
  where room_id=new.room_id;

  if unit_count>new.total_rooms then
    remove_count:=unit_count-new.total_rooms;
    with removable as (
      select unit_id
      from public.hotel_room_units
      where room_id=new.room_id and current_booking_id is null
      order by
        case status
          when 'out_of_service' then 1
          when 'maintenance' then 2
          when 'cleaning' then 3
          else 4
        end,
        unit_id desc
      limit remove_count
    ), deleted as (
      delete from public.hotel_room_units target
      using removable
      where target.unit_id=removable.unit_id
      returning target.unit_id
    )
    select count(*) into removed_count from deleted;

    if removed_count<remove_count then
      raise exception 'Room count cannot be lower than the number of occupied rooms';
    end if;
    unit_count:=new.total_rooms;
  end if;

  while unit_count<new.total_rooms loop
    insert into public.hotel_room_units(hotel_id,room_id,unit_label,status)
    values (new.hotel_id,new.room_id,new.room_type||' '||candidate_number,'ready')
    on conflict do nothing;
    get diagnostics inserted_count=row_count;
    unit_count:=unit_count+inserted_count;
    candidate_number:=candidate_number+1;
    if candidate_number>new.total_rooms+10000 then
      raise exception 'Physical room labels could not be generated';
    end if;
  end loop;

  return new;
end;
$$;


--
-- Name: sync_inspection_request_canonical_media(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_inspection_request_canonical_media() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.inspection_request_id is not null then
    update public.inspection_requests
       set photo_urls = coalesce(new.images, array[]::text[]),
           video_urls = coalesce(new.videos, array[]::text[]),
           updated_at = now()
     where id = new.inspection_request_id
       and (
         photo_urls is distinct from coalesce(new.images, array[]::text[])
         or video_urls is distinct from coalesce(new.videos, array[]::text[])
       );
  end if;
  return new;
end;
$$;


--
-- Name: sync_legacy_profile_role_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_legacy_profile_role_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.role in('staff','admin','creator') and (tg_op='INSERT' or old.role is distinct from new.role or old.assigned_state is distinct from new.assigned_state or old.assigned_lga is distinct from new.assigned_lga) then
    update public.workspace_role_assignments set status='revoked',revoked_by=new.updated_by,revoked_at=now(),updated_at=now()
      where user_id=new.user_id and workspace_role in('staff','admin') and workspace_role<>new.role and status='active';
    insert into public.workspace_role_assignments(user_id,workspace_role,scope_type,scope_state,scope_lga,granted_by)
      values(new.user_id,new.role,case when new.role='creator' then 'global' else 'branch' end,new.assigned_state,new.assigned_lga,new.updated_by)
    on conflict(user_id,workspace_role) where status='active' do update
      set scope_type=excluded.scope_type,scope_state=excluded.scope_state,scope_lga=excluded.scope_lga,updated_at=now();
  elsif tg_op='UPDATE' and old.role in('staff','admin') and new.role not in('staff','admin') then
    update public.workspace_role_assignments set status='revoked',revoked_by=new.updated_by,revoked_at=now(),updated_at=now()
      where user_id=new.user_id and workspace_role=old.role and status='active';
  end if;
  return new;
end $$;


--
-- Name: sync_listing_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_listing_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(new.sub_type,'')='short_let' then
    if tg_op='INSERT' then
      new.status:=coalesce(new.status,new.availability_status,'pending_approval');
      if new.status in ('reserved','occupied') then new.status:='available'; end if;
      new.availability_status:=new.status;
    elsif new.status is distinct from old.status then
      if new.status in ('reserved','occupied') then raise exception 'Short Let occupancy is date-based and cannot change the listing-wide status'; end if;
      new.availability_status:=new.status;
    elsif new.availability_status is distinct from old.availability_status then
      if new.availability_status in ('reserved','occupied') then raise exception 'Short Let occupancy is date-based and cannot change the listing-wide availability status'; end if;
      new.status:=new.availability_status;
    end if;
  else
    if tg_op='INSERT' then
      new.status:=coalesce(new.status,new.availability_status,'pending_approval');
      new.availability_status:=new.status;
    elsif new.status is distinct from old.status then
      new.availability_status:=new.status;
    elsif new.availability_status is distinct from old.availability_status then
      new.status:=new.availability_status;
    end if;
  end if;
  new.updated_at:=now();
  return new;
end;
$$;


--
-- Name: sync_marketplace_role_projection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_marketplace_role_projection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id text:=case when tg_op='DELETE' then old.user_id else new.user_id end;
  v_workspace text;
  v_count integer;
begin
  select count(*)::integer,min(workspace_role)
  into v_count,v_workspace
  from public.workspace_role_assignments
  where user_id=v_user_id
    and workspace_role in ('worker','property_partner')
    and status='active';
  if v_count=1 then
    update public.profiles
    set role=v_workspace,account_kind='consumer',updated_at=now()
    where user_id=v_user_id
      and role in ('user','worker','property_partner')
      and role is distinct from v_workspace;
  elsif v_count=0 then
    update public.profiles
    set role='user',account_kind='consumer',updated_at=now()
    where user_id=v_user_id and role in ('worker','property_partner');
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$$;


--
-- Name: sync_property_submission_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_property_submission_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.published_at is null
     and lower(coalesce(new.status,'')) in ('completed','approved')
     and new.field_evidence_review_status='not_submitted' then
    new.field_evidence_review_status:='pending';
  end if;
  new.lifecycle_stage:=case
    when new.published_at is not null then 'live'
    when lower(coalesce(new.status,''))='rejected' then 'rejected'
    when new.access_evidence_status='rejected' then 'changes_requested'
    when new.field_evidence_review_status='changes_requested' then 'changes_requested'
    when new.access_evidence_status is null or new.access_evidence_status='required' then 'access_required'
    when new.access_evidence_status='submitted' then 'access_review'
    when new.draft_listing_id is not null or new.draft_hotel_id is not null then 'listing_prepared'
    when new.field_evidence_review_status='accepted' then 'ready_to_prepare'
    when new.field_evidence_review_status='pending'
      or new.completed_at is not null
      or lower(coalesce(new.status,'')) in ('completed','approved') then 'awaiting_review'
    when coalesce(new.assigned_field_officer_id,new.field_officer_id,new.assigned_to) is not null
      or new.scheduled_date is not null
      or lower(coalesce(new.status,'')) in ('scheduled','in_progress') then 'inspection'
    when new.access_evidence_status='verified' then 'inspection_ready'
    else 'access_required'
  end;
  new.access_challenge_code:=null;
  new.access_challenge_expires_at:=null;
  return new;
end;
$$;


--
-- Name: sync_refunded_shared_payment_member(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_refunded_shared_payment_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_component public.shared_payment_protection_components; v_group uuid;
begin
  if new.protection_state<>'refunded' or old.protection_state='refunded' then return new; end if;
  select * into v_component from public.shared_payment_protection_components
  where payment_protection_id=new.id;
  if v_component.component_id is not null then
    if not exists(select 1 from public.shared_payment_protection_components c
      join public.payment_protection_transactions p on p.id=c.payment_protection_id
      where c.shared_payment_member_id=v_component.shared_payment_member_id
        and c.provider_reference=v_component.provider_reference
        and p.protection_state<>'refunded') then
      update public.shared_payment_members set payment_state='refunded',updated_at=now()
      where shared_payment_member_id=v_component.shared_payment_member_id;
      update public.shared_housing_members set payment_status='refunded',updated_at=now()
      where canonical_member_id=v_component.shared_payment_member_id;
    end if;
    v_group:=v_component.shared_payment_group_id;
  else
    select (payment.metadata->>'canonical_shared_payment_group_id')::uuid
    into v_group from public.booking_payments payment
    where payment.paystack_reference=new.paystack_reference
      and payment.purpose='shared_housing_share' limit 1;
    update public.shared_payment_members set payment_state='refunded',updated_at=now()
    where shared_payment_member_id=(select
      (payment.metadata->>'canonical_shared_payment_member_id')::uuid
      from public.booking_payments payment
      where payment.paystack_reference=new.paystack_reference
        and payment.purpose='shared_housing_share' limit 1);
    update public.shared_housing_members set payment_status='refunded',updated_at=now()
    where canonical_member_id=(select
      (payment.metadata->>'canonical_shared_payment_member_id')::uuid
      from public.booking_payments payment
      where payment.paystack_reference=new.paystack_reference
        and payment.purpose='shared_housing_share' limit 1);
  end if;
  if v_group is not null and not exists(
    select 1 from public.shared_payment_members
    where shared_payment_group_id=v_group and payment_state in('paid','provider_pending')
  ) then
    update public.shared_payment_groups set status='refunded',updated_at=now()
    where shared_payment_group_id=v_group;
    update public.shared_housing_groups set status='refunded',updated_at=now()
    where canonical_group_id=v_group;
    update public.reservations set status='refunded',canonical_state='refunded',updated_at=now()
    where shared_payment_group_id=v_group and status in('payment_pending','payment_conflict');
  end if;
  return new;
end
$$;


--
-- Name: sync_reservation_conversation_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_reservation_conversation_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  update public.partner_support_conversations c
  set context_snapshot = coalesce(c.context_snapshot, '{}'::jsonb)
    || jsonb_build_object(
      'reservation_id', new.id,
      'status', new.status,
      'stay_type', coalesce(new.stay_type, 'long_stay'),
      'booking_code', new.booking_code,
      'rent_payment_status', new.rent_payment_status,
      'rent_paid_at', new.rent_paid_at,
      'requested_move_in_at', new.requested_move_in_at,
      'hold_expires_at', new.hold_expires_at,
      'tenancy_start_date', new.tenancy_start_date,
      'tenancy_end_date', new.tenancy_end_date,
      'check_in', new.stay_check_in,
      'check_out', new.stay_check_out
    )
  where c.context_type in (
      'apartment_reservation',
      'apartment_payment',
      'reservation'
    )
    and c.context_id = new.id::text;

  return new;
end;
$$;


--
-- Name: sync_staff_trust_on_role_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_staff_trust_on_role_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE v_actor text; v_needs_review boolean:=false;
BEGIN
  IF TG_OP='INSERT' THEN
    v_actor:=NEW.updated_by;
    v_needs_review:=(NEW.role='staff');
  ELSE
    v_actor:=COALESCE(NEW.updated_by,OLD.updated_by);
    v_needs_review:=(NEW.role='staff' AND (OLD.role IS DISTINCT FROM 'staff' OR OLD.assigned_state IS DISTINCT FROM NEW.assigned_state OR OLD.assigned_lga IS DISTINCT FROM NEW.assigned_lga));
  END IF;
  IF v_needs_review THEN
    INSERT INTO public.staff_trust_profiles(
      staff_id,status,appointed_by,appointed_at,trusted_by,trusted_at,
      supervisor_confirmed,orientation_completed,role_training_completed,code_of_conduct_confirmed,probation_observation_completed,
      notes,updated_at
    ) VALUES(NEW.user_id,'probation',v_actor,now(),NULL,NULL,false,false,false,false,false,'Staff role or branch assignment changed; WeHouse trust review required',now())
    ON CONFLICT(staff_id) DO UPDATE SET
      status='probation',appointed_by=COALESCE(v_actor,staff_trust_profiles.appointed_by),appointed_at=now(),trusted_by=NULL,trusted_at=NULL,
      supervisor_confirmed=false,orientation_completed=false,role_training_completed=false,code_of_conduct_confirmed=false,probation_observation_completed=false,
      notes='Staff role or branch assignment changed; WeHouse trust review required',updated_at=now();
  ELSIF TG_OP='UPDATE' AND OLD.role='staff' AND NEW.role<>'staff' THEN
    UPDATE public.staff_trust_profiles SET status='revoked',notes='Staff role removed',updated_at=now() WHERE staff_id=NEW.user_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_worker_protected_payment_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_worker_protected_payment_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_booking public.worker_bookings; v_from text;
begin
  if new.subject_type<>'worker_booking' or new.protection_state<>'protected'
    or old.protection_state='protected' then return new; end if;
  select * into v_booking from public.worker_bookings
  where id=new.subject_id::uuid for update;
  if v_booking.id is null then raise exception 'Protected Worker job is missing'; end if;
  v_from:=coalesce(v_booking.canonical_job_state,'awaiting_payment');
  if v_from in('requested','negotiating') then v_from:='awaiting_payment'; end if;
  if v_booking.canonical_job_state is distinct from 'confirmed' then
    update public.worker_bookings set canonical_job_state='confirmed',
      payment_protection_id=new.id,updated_at=now() where id=v_booking.id;
    insert into public.worker_job_transitions(
      worker_booking_id,from_state,to_state,event_type,event_key,actor_type,
      policy_version_id,metadata
    ) values(v_booking.id,v_from,'confirmed','payment_protection_confirmed',
      'worker-payment-protected:'||new.id,'paystack',v_booking.policy_version_id,
      jsonb_build_object('payment_protection_id',new.id))
    on conflict(event_key) do nothing;
  end if;
  return new;
end
$$;


--
-- Name: sync_worker_release_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_worker_release_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_protection public.payment_protection_transactions;
begin
  select * into v_protection from public.payment_protection_transactions
  where id=new.payment_protection_id;
  if v_protection.subject_type='worker_booking' then
    update public.worker_bookings set status='approved_released',
      canonical_job_state='completed',completed_at=coalesce(completed_at,now()),
      review_edit_until=coalesce(review_edit_until,now()+interval '48 hours'),
      help_until=coalesce(help_until,now()+interval '3 days'),updated_at=now()
    where id=v_protection.subject_id::uuid;
    -- Legacy record is a compatibility projection and changes only after the
    -- canonical ledger release and wallet projection both succeeded.
    update public.escrow_transactions set status='released',released_at=now(),
      released_by='finance_processor',updated_at=now()
    where booking_id=v_protection.subject_id::uuid
      and booking_type='worker_booking'
      and status not in('released','refunded','disputed');
  end if;
  return new;
end
$$;


--
-- Name: sync_worker_review_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_worker_review_summary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_table_name = 'worker_booking_reviews' then
    if tg_op <> 'INSERT' then perform public.refresh_worker_review_summary(old.worker_id); end if;
    if tg_op <> 'DELETE' then perform public.refresh_worker_review_summary(new.worker_id); end if;
  else
    if tg_op <> 'INSERT' then perform public.refresh_worker_review_summary(old.worker_id); end if;
    if tg_op <> 'DELETE' then perform public.refresh_worker_review_summary(new.worker_id); end if;
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: terminate_my_device_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.terminate_my_device_session(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_auth_id text := (select auth.uid())::text;
  v_user_id text := public.current_profile_user_id();
  v_current_auth_session_id text := nullif((select auth.jwt() ->> 'session_id'), '');
  v_current public.user_sessions%rowtype;
  v_target public.user_sessions%rowtype;
begin
  if v_auth_id is null or v_user_id is null or v_current_auth_session_id is null then
    raise exception 'Authentication session is required';
  end if;

  select * into v_current
  from public.user_sessions
  where user_id = v_user_id
    and auth_id = v_auth_id
    and auth_session_id = v_current_auth_session_id
    and is_active = true
    and trust_status = 'trusted'
  limit 1;
  if not found then raise exception 'An active signed-in device is required'; end if;

  select * into v_target
  from public.user_sessions
  where id = p_session_id
    and user_id = v_user_id
    and auth_id = v_auth_id
  for update;
  if not found then raise exception 'Device session not found'; end if;
  if v_target.id = v_current.id or v_target.auth_session_id = v_current_auth_session_id then
    raise exception 'Use Log out to end this device session';
  end if;

  update public.user_sessions
  set is_active = false,
      is_current = false,
      logout_time = coalesce(logout_time, now()),
      trust_reviewed_at = now(),
      trust_reviewed_by_session_id = v_current.id
  where id = v_target.id;

  update public.notifications
  set read = true,
      read_at = coalesce(read_at, now()),
      destination_params = coalesce(destination_params, '{}'::jsonb) || jsonb_build_object('decision', 'signed_out')
  where recipient_id = v_user_id
    and type = 'new_device_login'
    and source_id = v_target.id::text;

  return jsonb_build_object('session_id', v_target.id, 'decision', 'signed_out');
end;
$$;


--
-- Name: touch_my_presence(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_my_presence(p_online boolean DEFAULT true) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor public.profiles;
  v_now timestamptz:=now();
BEGIN
  SELECT * INTO v_actor
  FROM public.profiles
  WHERE auth_id=auth.uid()::text
    AND COALESCE(deleted,false)=false
    AND COALESCE(suspended,false)=false
    AND COALESCE(banned,false)=false
  LIMIT 1;

  IF v_actor IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  UPDATE public.profiles
  SET is_online=COALESCE(p_online,true),last_seen=v_now,updated_at=now()
  WHERE user_id=v_actor.user_id;

  RETURN v_now;
END;
$$;


--
-- Name: transition_hotel_stay(integer, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_hotel_stay(p_hotel_booking_id integer, p_to_state text, p_event_type text, p_event_key text, p_actor_user_id text, p_actor_type text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS public.hotel_bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_booking public.hotel_bookings; v_from text;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  select * into v_booking from public.hotel_bookings
  where booking_id=p_hotel_booking_id for update;
  if v_booking.booking_id is null then raise exception 'Hotel booking not found'; end if;
  v_from:=coalesce(v_booking.canonical_state,'checkout_pending');
  if exists(select 1 from public.hotel_stay_transitions where event_key=p_event_key)
    then return v_booking; end if;
  if not public.canonical_product_transition_allowed('hotel',v_from,p_to_state)
    then raise exception 'Illegal Hotel transition: % -> %',v_from,p_to_state; end if;
  if p_to_state='confirmed' and v_booking.payment_status<>'paid' then
    raise exception 'Verified Hotel payment required'; end if;
  update public.hotel_bookings set
    canonical_state=p_to_state,
    checked_in_at=case when p_to_state='checked_in' then now() else checked_in_at end,
    checked_out_at=case when p_to_state='checked_out' then now() else checked_out_at end,
    updated_at=now()
  where booking_id=p_hotel_booking_id returning * into v_booking;
  insert into public.hotel_stay_transitions(
    hotel_booking_id,from_state,to_state,event_type,event_key,actor_user_id,
    actor_type,policy_version_id,metadata
  ) values(
    p_hotel_booking_id,v_from,p_to_state,p_event_type,p_event_key,p_actor_user_id,
    p_actor_type,v_booking.policy_version_id,coalesce(p_metadata,'{}'::jsonb)
  );
  return v_booking;
end
$$;


--
-- Name: transition_inspection_status(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_inspection_status(p_inspection_id uuid, p_new_status text, p_changed_by text, p_changed_by_role text, p_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_current_status TEXT; v_valid BOOLEAN := FALSE;
BEGIN
  SELECT status INTO v_current_status FROM inspection_requests WHERE id = p_inspection_id;
  IF NOT FOUND THEN RETURN FALSE; END IF;
  v_valid := CASE
    WHEN v_current_status = 'inspection_requested' AND p_new_status = 'inspection_assigned' THEN TRUE
    WHEN v_current_status = 'inspection_assigned' AND p_new_status = 'inspection_in_progress' THEN TRUE
    WHEN v_current_status = 'inspection_in_progress' AND p_new_status = 'inspection_completed' THEN TRUE
    WHEN v_current_status = 'inspection_completed' AND p_new_status = 'draft' THEN TRUE
    WHEN v_current_status = 'draft' AND p_new_status = 'pending_approval' THEN TRUE
    WHEN v_current_status = 'pending_approval' AND p_new_status = 'approved' THEN TRUE
    WHEN v_current_status = 'approved' AND p_new_status = 'published' THEN TRUE
    WHEN v_current_status IN ('inspection_requested','inspection_assigned','inspection_in_progress','inspection_completed','draft','pending_approval') AND p_new_status = 'rejected' THEN TRUE
    WHEN p_new_status IN ('suspended','archived') THEN TRUE
    ELSE FALSE
  END;
  IF NOT v_valid THEN RETURN FALSE; END IF;
  INSERT INTO inspection_status_history (inspection_request_id, old_status, new_status, changed_by, changed_by_role, notes)
  VALUES (p_inspection_id, v_current_status, p_new_status, p_changed_by, p_changed_by_role, p_notes);
  UPDATE inspection_requests SET status = p_new_status, updated_at = NOW()
  WHERE id = p_inspection_id;
  RETURN TRUE;
END;
$$;


--
-- Name: transition_long_let_reservation(text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_long_let_reservation(p_reservation_id text, p_to_state text, p_event_type text, p_event_key text, p_actor_user_id text, p_actor_type text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_res public.reservations; v_from text; v_material boolean;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  select * into v_res from public.reservations where id=p_reservation_id for update;
  if v_res.id is null then raise exception 'Reservation not found'; end if;
  v_from:=coalesce(v_res.canonical_state,'reservation_fee_pending');
  if exists(select 1 from public.long_let_reservation_transitions where event_key=p_event_key)
    then return v_res; end if;
  if not public.canonical_product_transition_allowed('long_let',v_from,p_to_state)
    then raise exception 'Illegal Long Let transition: % -> %',v_from,p_to_state; end if;
  v_material:=p_to_state in (
    'inspection_requested','inspection_completed','rent_pending','rent_protected',
    'handover_pending','handover_verified','active'
  );
  if p_to_state not in ('cancelled','expired') and v_res.hold_expires_at<=now()
    and v_from in ('hold_active','inspection_requested','inspection_completed') then
    raise exception 'Long Let hold expired'; end if;
  update public.reservations set
    canonical_state=p_to_state,
    material_process_started_at=case when v_material then
      coalesce(material_process_started_at,now()) else material_process_started_at end,
    verified_handover_at=case when p_to_state='handover_verified' then now()
      else verified_handover_at end,
    updated_at=now()
  where id=p_reservation_id returning * into v_res;
  insert into public.long_let_reservation_transitions(
    reservation_id,from_state,to_state,event_type,event_key,actor_user_id,
    actor_type,material_process,policy_version_id,metadata
  ) values(
    p_reservation_id,v_from,p_to_state,p_event_type,p_event_key,p_actor_user_id,
    p_actor_type,v_material,v_res.reservation_policy_version_id,
    coalesce(p_metadata,'{}'::jsonb)
  );
  return v_res;
end
$$;


--
-- Name: transition_my_support_case(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_my_support_case(p_conversation_id uuid, p_action text, p_note text DEFAULT NULL::text) RETURNS public.partner_support_conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_conversation public.partner_support_conversations;
  v_result public.partner_support_conversations;
  v_next_status text;
  v_case_status text;
  v_event text;
  v_public_message text;
  v_clean_note text:=nullif(btrim(coalesce(p_note,'')),'');
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor.user_id is null then raise exception 'Active WeHouse team account required'; end if;
  select * into v_conversation from public.partner_support_conversations
  where id=p_conversation_id for update;
  if v_conversation.id is null then raise exception 'Request not found'; end if;
  if v_conversation.operational_case_id is null
     and v_conversation.channel_kind not in('support','support_case') then
    raise exception 'This is a record conversation, not a case';
  end if;
  if not public.current_actor_can_access_operational_conversation(
    p_conversation_id,true
  ) then raise exception 'Only the assigned team member can update this request'; end if;

  if p_action='start' then
    if v_conversation.status not in('open','assigned') then raise exception 'This request cannot be started from its current state'; end if;
    v_next_status:='in_progress'; v_case_status:='investigating';
    v_event:='work_started'; v_public_message:='WeHouse has started reviewing your request.';
  elsif p_action='request_info' then
    if v_conversation.status not in('assigned','in_progress','escalated') then raise exception 'Information can only be requested while work is active'; end if;
    if v_clean_note is null then raise exception 'Say exactly what information is needed'; end if;
    v_next_status:='waiting_for_user'; v_case_status:='waiting_customer';
    v_event:='information_requested';
    v_public_message:='WeHouse needs information from you:'||E'\n\n'||v_clean_note;
  elsif p_action='escalate' then
    if v_conversation.status not in('assigned','in_progress','waiting_for_user') then raise exception 'This request cannot be escalated from its current state'; end if;
    if v_clean_note is null then raise exception 'An escalation reason is required'; end if;
    v_next_status:='escalated'; v_case_status:='investigating';
    v_event:='escalated';
    v_public_message:='WeHouse escalated your request for additional review:'||E'\n\n'||v_clean_note;
  elsif p_action='resolve' then
    if v_conversation.status not in('assigned','in_progress','waiting_for_user','escalated') then raise exception 'Only active work can be resolved'; end if;
    if v_clean_note is null then raise exception 'Explain the outcome before resolving this request'; end if;
    v_next_status:='resolved'; v_case_status:='resolved';
    v_event:='resolved';
    v_public_message:='WeHouse marked your request as resolved:'||E'\n\n'||v_clean_note;
  elsif p_action='close' then
    if v_conversation.status<>'resolved' then raise exception 'Resolve the request before closing it'; end if;
    v_next_status:='closed'; v_case_status:='closed';
    v_event:='closed'; v_public_message:='WeHouse closed this request after resolution.';
  else
    raise exception 'Unsupported request action';
  end if;

  update public.partner_support_conversations set
    status=v_next_status,
    priority=case when p_action='escalate' then 'high' else priority end,
    resolved_at=case when p_action='resolve' then now()
      when v_next_status not in('resolved','closed') then null else resolved_at end,
    closed_at=case when p_action='close' then now()
      when v_next_status<>'closed' then null else closed_at end,
    updated_at=now()
  where id=p_conversation_id returning * into v_result;

  update public.operational_cases set
    status=v_case_status,
    priority=case when p_action='escalate' then 'high' else priority end,
    resolution_summary=case when p_action='resolve' then v_clean_note else resolution_summary end,
    resolved_at=case when p_action='resolve' then now()
      when v_case_status not in('resolved','closed') then null else resolved_at end,
    closed_at=case when p_action='close' then now()
      when v_case_status<>'closed' then null else closed_at end,
    updated_at=now()
  where operational_case_id=v_conversation.operational_case_id;

  insert into public.support_case_events(
    conversation_id,event_type,actor_id,from_status,to_status,note,metadata
  ) values(p_conversation_id,v_event,v_actor.user_id,v_conversation.status,
    v_next_status,v_clean_note,jsonb_build_object('actor_role',v_actor.role));
  if v_conversation.operational_case_id is not null then
    insert into public.operational_case_events(
      operational_case_id,event_key,event_type,from_status,to_status,
      actor_user_id,public_note,metadata
    ) values(
      v_conversation.operational_case_id,
      'case_transition:'||v_conversation.operational_case_id||':'||v_event||':'
        ||extract(epoch from clock_timestamp())::text,
      v_event,null,v_case_status,v_actor.user_id,v_clean_note,
      jsonb_build_object('legacy_from_status',v_conversation.status,
        'legacy_to_status',v_next_status)
    );
  end if;
  insert into public.partner_support_messages(
    conversation_id,sender_id,sender_role,content,action_type,
    action_metadata,visibility,created_at
  ) values(
    p_conversation_id,v_actor.user_id,
    case when v_actor.role in('admin','creator') then v_actor.role else 'staff' end,
    v_public_message,'status_change',jsonb_build_object(
      'event_type',v_event,'from_status',v_conversation.status,
      'to_status',v_next_status,'note',v_clean_note
    ),'customer',now()
  );
  if v_next_status='closed' and v_conversation.canonical_thread_id is not null then
    update public.canonical_threads set state='closed',closed_at=now(),updated_at=now()
    where thread_id=v_conversation.canonical_thread_id;
  end if;
  return v_result;
end
$$;


--
-- Name: payment_protection_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payment_protection_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    booking_id uuid,
    booking_type text DEFAULT 'worker'::text NOT NULL,
    payer_user_id text NOT NULL,
    payee_user_id text NOT NULL,
    amount_total numeric(12,2) NOT NULL,
    amount_commission numeric(12,2) NOT NULL,
    amount_payee numeric(12,2) NOT NULL,
    commission_rate numeric(5,2) NOT NULL,
    status text DEFAULT 'protected'::text NOT NULL,
    released_at timestamp with time zone,
    released_by text,
    paystack_reference text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    protection_state text DEFAULT 'awaiting_funds'::text NOT NULL,
    subject_type text,
    subject_id text,
    protected_ledger_transaction_id uuid,
    release_ledger_transaction_id uuid,
    refund_ledger_transaction_id uuid,
    release_eligible_at timestamp with time zone,
    risk_held_at timestamp with time zone,
    dispute_case_id uuid,
    released_amount numeric(12,2) DEFAULT 0 NOT NULL,
    refunded_amount numeric(12,2) DEFAULT 0 NOT NULL,
    commission_recognized_amount numeric(12,2) DEFAULT 0 NOT NULL,
    CONSTRAINT payment_protection_allocated_amount_check CHECK (((released_amount >= (0)::numeric) AND (refunded_amount >= (0)::numeric) AND (commission_recognized_amount >= (0)::numeric) AND ((released_amount + refunded_amount) <= amount_total) AND (commission_recognized_amount <= amount_commission))),
    CONSTRAINT payment_protection_state_check CHECK ((protection_state = ANY (ARRAY['awaiting_funds'::text, 'protected'::text, 'release_eligible'::text, 'release_pending'::text, 'released'::text, 'disputed'::text, 'risk_held'::text, 'reversal_pending'::text, 'refunded'::text, 'partially_released'::text, 'reversed'::text]))),
    CONSTRAINT payment_protection_subject_required CHECK (((NULLIF(btrim(subject_type), ''::text) IS NOT NULL) AND (NULLIF(btrim(subject_id), ''::text) IS NOT NULL)))
);


--
-- Name: transition_payment_protection(uuid, text, text, text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_payment_protection(p_payment_protection_id uuid, p_to_state text, p_event_type text, p_event_key text, p_actor_user_id text, p_actor_type text, p_reason text DEFAULT NULL::text, p_ledger_transaction_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS public.payment_protection_transactions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_row public.payment_protection_transactions;
  v_allowed boolean:=false;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  select * into v_row from public.payment_protection_transactions
  where id=p_payment_protection_id for update;
  if v_row.id is null then raise exception 'Payment Protection record not found'; end if;
  if exists(select 1 from public.payment_protection_transitions where event_key=p_event_key)
    then return v_row; end if;
  v_allowed:=case v_row.protection_state
    when 'awaiting_funds' then p_to_state in('protected','refunded')
    when 'protected' then p_to_state in(
      'release_eligible','disputed','risk_held','reversal_pending',
      'refunded','partially_released'
    )
    when 'release_eligible' then p_to_state in(
      'release_pending','disputed','risk_held','reversal_pending',
      'released','partially_released','refunded'
    )
    when 'release_pending' then p_to_state in(
      'released','partially_released','risk_held'
    )
    when 'disputed' then p_to_state in(
      'protected','released','partially_released','refunded','risk_held'
    )
    when 'risk_held' then p_to_state in(
      'protected','disputed','refunded','reversal_pending','partially_released'
    )
    when 'reversal_pending' then p_to_state in(
      'reversed','protected','refunded','partially_released'
    )
    when 'partially_released' then p_to_state in(
      'partially_released','released','refunded','disputed','risk_held'
    )
    else false
  end;
  if not v_allowed then
    raise exception 'Illegal Payment Protection transition: % -> %',
      v_row.protection_state,p_to_state;
  end if;
  insert into public.payment_protection_transitions(
    payment_protection_id,from_state,to_state,event_type,event_key,
    actor_user_id,actor_type,reason,ledger_transaction_id,metadata
  ) values(
    v_row.id,v_row.protection_state,p_to_state,p_event_type,p_event_key,
    p_actor_user_id,p_actor_type,p_reason,p_ledger_transaction_id,
    coalesce(p_metadata,'{}'::jsonb)
  );
  update public.payment_protection_transactions set
    protection_state=p_to_state,status=p_to_state,
    release_eligible_at=case when p_to_state='release_eligible'
      then now() else release_eligible_at end,
    risk_held_at=case when p_to_state='risk_held' then now() else risk_held_at end,
    released_at=case when p_to_state='released' then now() else released_at end,
    updated_at=now()
  where id=v_row.id returning * into v_row;
  return v_row;
end
$$;


--
-- Name: transition_short_let_booking(text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_short_let_booking(p_reservation_id text, p_to_state text, p_event_type text, p_event_key text, p_actor_user_id text, p_actor_type text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_res public.reservations; v_from text; v_listing public.listings;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  select * into v_res from public.reservations
  where id=p_reservation_id and stay_type='short_let' for update;
  if v_res.id is null then raise exception 'Short Let booking not found'; end if;
  v_from:=coalesce(v_res.canonical_state,'checkout_pending');
  if exists(select 1 from public.short_let_booking_transitions where event_key=p_event_key)
    then return v_res; end if;
  if not public.canonical_product_transition_allowed('short_let',v_from,p_to_state)
    then raise exception 'Illegal Short Let transition: % -> %',v_from,p_to_state; end if;
  select * into v_listing from public.listings
  where listing_id=v_res.listing_id or id::text=v_res.listing_id for update;
  if v_res.guest_count>coalesce(v_listing.max_guests,1) then
    raise exception 'Guest capacity exceeded';
  end if;
  if p_to_state='confirmed' and v_res.rent_payment_status<>'paid' then
    raise exception 'Verified full checkout required';
  end if;
  update public.reservations set
    canonical_state=p_to_state,
    occupancy_started_at=case when p_to_state='checked_in' then now()
      else occupancy_started_at end,
    checked_in_at=case when p_to_state='checked_in' then now()
      else checked_in_at end,
    checked_out_at=case when p_to_state='checked_out' then now()
      else checked_out_at end,
    completed_at=case when p_to_state in ('checked_out','completed') then now()
      else completed_at end,
    updated_at=now()
  where id=p_reservation_id returning * into v_res;
  insert into public.short_let_booking_transitions(
    reservation_id,from_state,to_state,event_type,event_key,actor_user_id,
    actor_type,policy_version_id,metadata
  ) values(
    p_reservation_id,v_from,p_to_state,p_event_type,p_event_key,p_actor_user_id,
    p_actor_type,v_res.reservation_policy_version_id,coalesce(p_metadata,'{}'::jsonb)
  );
  return v_res;
end
$$;


--
-- Name: worker_bookings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.worker_bookings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    booking_code text,
    user_id text NOT NULL,
    worker_id text NOT NULL,
    service_type text,
    description text,
    address text,
    scheduled_date date,
    agreed_amount numeric(12,2) DEFAULT 0,
    wehouse_fee numeric(12,2) DEFAULT 300,
    worker_commission numeric(12,2) DEFAULT 0,
    worker_receives numeric(12,2) DEFAULT 0,
    negotiated_amount numeric(12,2),
    status text DEFAULT 'booking_requested'::text,
    customer_message text,
    worker_message text,
    worker_approved boolean DEFAULT false,
    user_approved boolean DEFAULT false,
    paystack_reference text,
    paystack_transaction_id text,
    dispute_reason text,
    dispute_resolution text,
    cancellation_reason text,
    refund_reason text,
    refund_amount numeric(12,2),
    booking_conversation_id uuid,
    started_at timestamp with time zone,
    marked_complete_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    cancelled_by text,
    request_attachments text[] DEFAULT ARRAY[]::text[] NOT NULL,
    service_subcategory_id uuid,
    service_latitude numeric,
    service_longitude numeric,
    service_location_accuracy_m numeric,
    service_location_source text DEFAULT 'manual'::text NOT NULL,
    canonical_job_state text,
    payment_protection_id uuid,
    completion_reminder_sent_at timestamp with time zone,
    release_eligible_at timestamp with time zone,
    help_until timestamp with time zone,
    risk_flag boolean DEFAULT false NOT NULL,
    payment_conflict boolean DEFAULT false NOT NULL,
    chargeback_open boolean DEFAULT false NOT NULL,
    review_edit_until timestamp with time zone,
    policy_version_id uuid,
    CONSTRAINT worker_bookings_coordinate_source_check CHECK (((service_location_source = 'manual'::text) OR ((service_latitude IS NOT NULL) AND (service_longitude IS NOT NULL)))),
    CONSTRAINT worker_bookings_location_accuracy_check CHECK (((service_location_accuracy_m IS NULL) OR (service_location_accuracy_m >= (0)::numeric))),
    CONSTRAINT worker_bookings_location_pair_check CHECK ((((service_latitude IS NULL) AND (service_longitude IS NULL)) OR (((service_latitude >= ('-90'::integer)::numeric) AND (service_latitude <= (90)::numeric)) AND ((service_longitude >= ('-180'::integer)::numeric) AND (service_longitude <= (180)::numeric))))),
    CONSTRAINT worker_bookings_location_source_check CHECK ((service_location_source = ANY (ARRAY['manual'::text, 'current'::text, 'saved'::text])))
);


--
-- Name: transition_worker_job(uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_worker_job(p_worker_booking_id uuid, p_to_state text, p_event_type text, p_event_key text, p_actor_user_id text, p_actor_type text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS public.worker_bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_booking public.worker_bookings; v_from text;
begin
  if (select auth.role())<>'service_role' then raise exception 'service role required'; end if;
  select * into v_booking from public.worker_bookings
  where id=p_worker_booking_id for update;
  if v_booking.id is null then raise exception 'Worker job not found'; end if;
  v_from:=coalesce(v_booking.canonical_job_state,'requested');
  if exists(select 1 from public.worker_job_transitions where event_key=p_event_key)
    then return v_booking; end if;
  if not public.canonical_product_transition_allowed('worker',v_from,p_to_state)
    then raise exception 'Illegal Worker transition: % -> %',v_from,p_to_state; end if;
  if p_to_state='confirmed' and not exists(
    select 1 from public.payment_protection_transactions pt
    where pt.id=v_booking.payment_protection_id
      and pt.protection_state in ('protected','release_eligible')
  ) then raise exception 'Payment Protection required before confirming job'; end if;
  if p_to_state='completed' and (
    v_booking.risk_flag or v_booking.payment_conflict
    or v_booking.chargeback_open
    or exists(select 1 from public.worker_user_blocks b
      where (b.blocker_user_id=v_booking.user_id and b.blocked_user_id=v_booking.worker_id)
         or (b.blocker_user_id=v_booking.worker_id and b.blocked_user_id=v_booking.user_id))
  ) then raise exception 'Worker release requires operations review'; end if;
  update public.worker_bookings set
    canonical_job_state=p_to_state,
    marked_complete_at=case when p_to_state='completion_marked' then now()
      else marked_complete_at end,
    release_eligible_at=case when p_to_state='completion_marked'
      then now()+interval '24 hours' else release_eligible_at end,
    help_until=case when p_to_state in ('completion_marked','completed')
      then coalesce(help_until,now()+interval '3 days') else help_until end,
    review_edit_until=case when p_to_state='completed'
      then now()+interval '48 hours' else review_edit_until end,
    completed_at=case when p_to_state='completed' then now() else completed_at end,
    updated_at=now()
  where id=p_worker_booking_id returning * into v_booking;
  insert into public.worker_job_transitions(
    worker_booking_id,from_state,to_state,event_type,event_key,actor_user_id,
    actor_type,policy_version_id,metadata
  ) values(
    p_worker_booking_id,v_from,p_to_state,p_event_type,p_event_key,p_actor_user_id,
    p_actor_type,v_booking.policy_version_id,coalesce(p_metadata,'{}'::jsonb)
  );
  return v_booking;
end
$$;


--
-- Name: unblock_my_contact(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unblock_my_contact(p_context text, p_other_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor text:=public.current_profile_user_id();
  v_still_blocked boolean;
begin
  if v_actor is null then raise exception 'Authentication required'; end if;
  if p_context='worker' then
    delete from public.worker_user_blocks
    where blocker_user_id=v_actor and blocked_user_id=p_other_user_id;
  elsif p_context='roommate' then
    delete from public.roommate_user_blocks
    where blocker_user_id=v_actor and blocked_user_id=p_other_user_id;
  else
    raise exception 'Context must be worker or roommate';
  end if;

  select exists(
    select 1 from public.worker_user_blocks b
    where (b.blocker_user_id=v_actor and b.blocked_user_id=p_other_user_id)
       or (b.blocker_user_id=p_other_user_id and b.blocked_user_id=v_actor)
    union all
    select 1 from public.roommate_user_blocks b
    where (b.blocker_user_id=v_actor and b.blocked_user_id=p_other_user_id)
       or (b.blocker_user_id=p_other_user_id and b.blocked_user_id=v_actor)
  ) into v_still_blocked;

  if not v_still_blocked then
    update public.canonical_thread_participants participant
    set can_message=true
    where participant.user_id in (v_actor,p_other_user_id)
      and exists(
        select 1 from public.canonical_thread_participants mine
        join public.canonical_thread_participants peer on peer.thread_id=mine.thread_id
        where mine.thread_id=participant.thread_id and mine.user_id=v_actor
          and peer.user_id=p_other_user_id
      );
  end if;
  return jsonb_build_object(
    'unblocked',true,
    'communication_restored',not v_still_blocked,
    'active_obligations',public.active_obligation_visibility(v_actor,p_other_user_id)
  );
end
$$;


--
-- Name: unfreeze_wallet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unfreeze_wallet(p_wallet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_wallet RECORD;
  v_caller TEXT;
  v_caller_role TEXT;
BEGIN
  -- ── AUTH: Identify caller ──
  SELECT user_id, role INTO v_caller, v_caller_role
  FROM profiles WHERE auth_id = auth.uid()::text;

  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
  END IF;

  -- ── AUTHORIZATION: staff/admin/creator only ──
  IF v_caller_role NOT IN ('staff','admin','creator') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  UPDATE wallets SET
    is_frozen = FALSE,
    frozen_reason = NULL,
    frozen_by = NULL,
    frozen_at = NULL,
    updated_at = NOW()
  WHERE id = p_wallet_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: unsave_my_hotel(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unsave_my_hotel(p_hotel_id integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_user_id text := public.current_profile_user_id();
begin
  if v_user_id is null then raise exception 'Authenticated profile required'; end if;
  delete from public.saved_hotels where user_id = v_user_id and hotel_id = p_hotel_id;
  return found;
end;
$$;


--
-- Name: update_inspection_status(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_inspection_status(p_inspection_id uuid, p_new_status text, p_source text DEFAULT 'user'::text, p_report text DEFAULT NULL::text, p_condition text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_updated boolean:=false;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false) and not coalesce(suspended,false)
    and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null then raise exception 'Active WeHouse account required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('field_officer') then
    raise exception 'Field Officer permission required';
  end if;
  if v_actor.role not in ('staff','admin','creator') then raise exception 'Field Officer access required'; end if;
  if p_source not in ('user','partner') then raise exception 'Invalid inspection source'; end if;
  if p_new_status not in ('in_progress','completed') then raise exception 'Field Officer can only start or submit an inspection'; end if;
  if p_new_status='completed' and nullif(btrim(coalesce(p_report,'')),'') is null then
    raise exception 'Inspection report is required before submission';
  end if;

  if p_source='partner' then
    update public.inspection_requests
    set status=p_new_status,
        completed_at=case when p_new_status='completed' then now() else completed_at end,
        inspection_completed_at=case when p_new_status='completed' then now() else inspection_completed_at end,
        notes=case when p_new_status='completed' then btrim(p_report) else notes end,
        field_evidence_review_status=case when p_new_status='completed' then 'pending' else field_evidence_review_status end,
        field_evidence_reviewed_by=case when p_new_status='completed' then null else field_evidence_reviewed_by end,
        field_evidence_reviewed_at=case when p_new_status='completed' then null else field_evidence_reviewed_at end,
        field_evidence_review_note=case when p_new_status='completed' then null else field_evidence_review_note end,
        rejection_reason=case when p_new_status='completed' then null else rejection_reason end,
        updated_at=now()
    where id=p_inspection_id and (
      v_actor.role in ('admin','creator')
      or coalesce(assigned_field_officer_id,field_officer_id,assigned_to)=v_actor.user_id
    );
    v_updated:=found;
  else
    update public.user_inspection_requests
    set status=p_new_status,
        completed_at=case when p_new_status='completed' then now() else completed_at end,
        report=case when p_new_status='completed' then btrim(p_report) else report end,
        condition=case when p_new_status='completed' then nullif(btrim(coalesce(p_condition,'')),'') else condition end,
        updated_at=now()
    where id=p_inspection_id and (
      v_actor.role in ('admin','creator') or field_officer_id=v_actor.user_id
    );
    v_updated:=found;
  end if;
  if not v_updated then raise exception 'Inspection not found or not assigned to this account'; end if;
  return true;
end;
$$;


--
-- Name: update_my_field_location(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_field_location(p_latitude numeric, p_longitude numeric, p_accuracy_m numeric DEFAULT NULL::numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles;
BEGIN
  SELECT * INTO v_actor FROM public.profiles WHERE auth_id=auth.uid()::text LIMIT 1;
  IF v_actor IS NULL OR v_actor.role<>'staff' OR NOT public.current_staff_has_permission('field_officer') THEN RAISE EXCEPTION 'Field Officer permission required'; END IF;
  IF p_latitude NOT BETWEEN -90 AND 90 OR p_longitude NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Invalid coordinates'; END IF;
  INSERT INTO public.staff_location_presence(staff_id,latitude,longitude,accuracy_m,captured_at)
  VALUES(v_actor.user_id,p_latitude,p_longitude,p_accuracy_m,NOW())
  ON CONFLICT(staff_id) DO UPDATE SET latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,accuracy_m=EXCLUDED.accuracy_m,captured_at=NOW();
END $$;


--
-- Name: update_my_field_officer_location(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_field_officer_location(p_latitude numeric, p_longitude numeric, p_accuracy_m numeric DEFAULT NULL::numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_actor record;
begin
 select user_id,role,deleted,suspended,banned into v_actor from public.profiles where auth_id=auth.uid()::text limit 1;
 if v_actor is null or v_actor.role<>'staff' or coalesce(v_actor.deleted,false) or coalesce(v_actor.suspended,false) or coalesce(v_actor.banned,false) then raise exception 'Active Staff account required'; end if;
 if not exists(select 1 from public.staff_permissions where staff_id=v_actor.user_id and permission='field_officer' and is_active=true) then raise exception 'Field Officer permission required'; end if;
 if p_latitude not between -90 and 90 or p_longitude not between -180 and 180 then raise exception 'Invalid coordinates'; end if;
 update public.profiles set operational_latitude=p_latitude,operational_longitude=p_longitude,operational_location_accuracy_m=case when p_accuracy_m is null or p_accuracy_m<0 then null else p_accuracy_m end,operational_location_updated_at=now(),updated_at=now() where user_id=v_actor.user_id;
 return true;
end $$;


--
-- Name: update_my_precise_location(numeric, numeric, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_precise_location(p_latitude numeric, p_longitude numeric, p_address text DEFAULT NULL::text, p_accuracy_m numeric DEFAULT NULL::numeric) RETURNS public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_profile public.profiles;
  v_address text := nullif(btrim(coalesce(p_address, '')), '');
begin
  if (p_latitude is null) <> (p_longitude is null) then
    raise exception 'Latitude and longitude must be saved together';
  end if;
  if p_latitude is not null
     and (p_latitude not between -90 and 90
          or p_longitude not between -180 and 180) then
    raise exception 'Invalid coordinates';
  end if;
  if p_accuracy_m is not null and p_accuracy_m < 0 then
    raise exception 'Invalid location accuracy';
  end if;
  if length(coalesce(p_address, '')) > 500 then
    raise exception 'Address is too long';
  end if;

  update public.profiles
  set precise_latitude = p_latitude,
      precise_longitude = p_longitude,
      precise_address = v_address,
      precise_location_accuracy_m = case
        when p_latitude is null then null
        else p_accuracy_m
      end,
      precise_location_updated_at = case
        when p_latitude is null and v_address is null then null
        else now()
      end,
      updated_at = now()
  where auth_id = auth.uid()::text
    and not coalesce(deleted, false)
    and not coalesce(suspended, false)
    and not coalesce(banned, false)
  returning * into v_profile;

  if v_profile is null then raise exception 'Active profile not found'; end if;
  return v_profile;
end;
$$;


--
-- Name: update_my_privacy(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_privacy(p_updates jsonb) RETURNS public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_profile public.profiles; v_unknown text[]; BEGIN SELECT array_agg(k) INTO v_unknown FROM jsonb_object_keys(p_updates) AS k WHERE k NOT IN ('privacy_profile_visible','privacy_search_visible','privacy_activity_visible','privacy_email_visible','privacy_phone_visible'); IF v_unknown IS NOT NULL THEN RAISE EXCEPTION 'Unsupported privacy fields'; END IF; UPDATE public.profiles SET privacy_profile_visible=CASE WHEN p_updates?'privacy_profile_visible' THEN (p_updates->>'privacy_profile_visible')::boolean ELSE privacy_profile_visible END,privacy_search_visible=CASE WHEN p_updates?'privacy_search_visible' THEN (p_updates->>'privacy_search_visible')::boolean ELSE privacy_search_visible END,privacy_activity_visible=CASE WHEN p_updates?'privacy_activity_visible' THEN (p_updates->>'privacy_activity_visible')::boolean ELSE privacy_activity_visible END,privacy_email_visible=CASE WHEN p_updates?'privacy_email_visible' THEN (p_updates->>'privacy_email_visible')::boolean ELSE privacy_email_visible END,privacy_phone_visible=CASE WHEN p_updates?'privacy_phone_visible' THEN (p_updates->>'privacy_phone_visible')::boolean ELSE privacy_phone_visible END,updated_at=now() WHERE auth_id=auth.uid()::text AND deleted=false AND suspended=false AND banned=false RETURNING * INTO v_profile; IF v_profile IS NULL THEN RAISE EXCEPTION 'Active profile not found'; END IF; RETURN v_profile; END; $$;


--
-- Name: update_my_profile(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_profile(p_updates jsonb) RETURNS public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $_$
DECLARE v_profile public.profiles; v_username text; v_state text; v_lga text; v_country text; v_unknown text[]; v_complete boolean; v_area text;
BEGIN
  IF p_updates IS NULL OR jsonb_typeof(p_updates)<>'object' THEN RAISE EXCEPTION 'Profile updates must be an object'; END IF;
  SELECT array_agg(k) INTO v_unknown FROM jsonb_object_keys(p_updates) AS k WHERE k NOT IN ('username','full_name','avatar_url','bio','phone','occupation','gender','is_student','school','country','state','local_government','city','area','profile_complete','worker_occupation','worker_skills','worker_price','worker_bio','worker_experience');
  IF v_unknown IS NOT NULL THEN RAISE EXCEPTION 'Unsupported profile fields: %',array_to_string(v_unknown,', '); END IF;
  SELECT * INTO v_profile FROM public.profiles WHERE auth_id=auth.uid()::text AND deleted=false AND suspended=false AND banned=false;
  IF v_profile IS NULL THEN RAISE EXCEPTION 'Active profile not found'; END IF;
  IF not public.user_has_active_workspace(v_profile.user_id,'worker') AND (p_updates ? 'worker_occupation' OR p_updates ? 'worker_skills' OR p_updates ? 'worker_price' OR p_updates ? 'worker_bio' OR p_updates ? 'worker_experience') THEN RAISE EXCEPTION 'Worker professional fields require a Worker account'; END IF;
  v_username:=lower(trim(CASE WHEN p_updates ? 'username' THEN p_updates->>'username' ELSE v_profile.username END));
  IF v_username IS NULL OR length(v_username)<3 OR length(v_username)>20 THEN RAISE EXCEPTION 'Username must contain 3 to 20 characters'; END IF;
  IF v_username !~ '^[a-z0-9_]+$' THEN RAISE EXCEPTION 'Username may contain only letters, numbers and underscores'; END IF;
  IF v_username IN ('admin','creator','support','system','api','wehouse','mod','moderator','owner','staff','help','info','null','undefined') THEN RAISE EXCEPTION 'This username is reserved'; END IF;
  IF EXISTS(SELECT 1 FROM public.profiles p WHERE lower(p.username)=v_username AND p.user_id<>v_profile.user_id) THEN RAISE EXCEPTION 'Username is already taken'; END IF;
  v_country:=CASE WHEN p_updates ? 'country' THEN nullif(trim(p_updates->>'country'),'') ELSE v_profile.country END;
  v_state:=CASE WHEN p_updates ? 'state' THEN nullif(trim(p_updates->>'state'),'') ELSE v_profile.state END;
  v_lga:=CASE WHEN p_updates ? 'local_government' THEN nullif(trim(p_updates->>'local_government'),'') WHEN p_updates ? 'city' THEN nullif(trim(p_updates->>'city'),'') ELSE COALESCE(v_profile.local_government,v_profile.city) END;
  v_area:=CASE WHEN p_updates ? 'area' THEN nullif(trim(p_updates->>'area'),'') ELSE v_profile.area END;
  v_complete:=v_profile.profile_complete OR COALESCE((p_updates->>'profile_complete')::boolean,false);
  IF v_complete AND (v_state IS NULL OR v_lga IS NULL) THEN RAISE EXCEPTION 'State and Local Government are required'; END IF;
  UPDATE public.profiles SET username=v_username,full_name=CASE WHEN p_updates ? 'full_name' THEN nullif(trim(p_updates->>'full_name'),'') ELSE full_name END,avatar_url=CASE WHEN p_updates ? 'avatar_url' THEN nullif(trim(p_updates->>'avatar_url'),'') ELSE avatar_url END,bio=CASE WHEN p_updates ? 'bio' THEN nullif(trim(p_updates->>'bio'),'') ELSE bio END,phone=CASE WHEN p_updates ? 'phone' THEN nullif(trim(p_updates->>'phone'),'') ELSE phone END,occupation=CASE WHEN p_updates ? 'worker_occupation' THEN nullif(trim(p_updates->>'worker_occupation'),'') WHEN p_updates ? 'occupation' THEN nullif(trim(p_updates->>'occupation'),'') ELSE occupation END,gender=CASE WHEN p_updates ? 'gender' THEN nullif(trim(p_updates->>'gender'),'') ELSE gender END,is_student=CASE WHEN p_updates ? 'is_student' THEN (p_updates->>'is_student')::boolean ELSE is_student END,school=CASE WHEN p_updates ? 'school' THEN nullif(trim(p_updates->>'school'),'') ELSE school END,country=v_country,state=v_state,local_government=v_lga,city=v_lga,area=v_area,worker_occupation=CASE WHEN p_updates ? 'worker_occupation' THEN nullif(trim(p_updates->>'worker_occupation'),'') ELSE worker_occupation END,worker_skills=CASE WHEN p_updates ? 'worker_skills' THEN p_updates->'worker_skills' ELSE worker_skills END,worker_price=CASE WHEN p_updates ? 'worker_price' THEN NULLIF(p_updates->>'worker_price','')::integer ELSE worker_price END,worker_bio=CASE WHEN p_updates ? 'worker_bio' THEN nullif(trim(p_updates->>'worker_bio'),'') ELSE worker_bio END,worker_experience=CASE WHEN p_updates ? 'worker_experience' THEN nullif(trim(p_updates->>'worker_experience'),'') ELSE worker_experience END,profile_complete=v_complete,updated_at=now() WHERE user_id=v_profile.user_id RETURNING * INTO v_profile;
  IF public.user_has_active_workspace(v_profile.user_id,'worker') AND v_complete THEN
    IF NULLIF(BTRIM(COALESCE(v_profile.worker_occupation,'')),'') IS NULL THEN RAISE EXCEPTION 'Worker service category is required'; END IF;
    IF jsonb_typeof(COALESCE(v_profile.worker_skills,'[]'::jsonb))<>'array' OR jsonb_array_length(COALESCE(v_profile.worker_skills,'[]'::jsonb))=0 THEN RAISE EXCEPTION 'At least one Worker specialty is required'; END IF;
    INSERT INTO public.worker_service_coverage(worker_id,state,lga,areas,updated_at) VALUES(v_profile.user_id,v_state,v_lga,CASE WHEN v_area IS NULL THEN '{}'::text[] ELSE ARRAY[v_area] END,now()) ON CONFLICT(worker_id) DO UPDATE SET state=EXCLUDED.state,lga=EXCLUDED.lga,areas=EXCLUDED.areas,updated_at=now();
  END IF;
  RETURN v_profile;
END;
$_$;


--
-- Name: update_my_reservation_plan(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_reservation_plan(p_reservation_id text, p_plan_years integer) RETURNS public.reservations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_user_id text; v_res public.reservations; v_listing public.listings;
  v_annual numeric; v_total numeric; v_upfront numeric; v_balance numeric;
  v_count integer; v_policy public.creator_policy_versions;
begin
  select user_id into v_user_id from public.profiles
  where auth_id=(select auth.uid())::text and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if p_plan_years<1 or p_plan_years>5 then raise exception 'Choose a supported 1 to 5 year tenure'; end if;
  select * into v_res from public.reservations
  where id=p_reservation_id and user_id=v_user_id
    and status=any(array['payment_pending','reserved','inspection_pending','ready_for_move_in']::text[])
  for update;
  if v_res.id is null then raise exception 'Active reservation not found'; end if;
  if v_res.rent_payment_status not in ('not_started','payment_pending') then
    raise exception 'Tenure cannot change after Year 1 rent has been paid';
  end if;
  if v_res.rent_payment_status='payment_pending' and exists(
    select 1 from public.booking_payments where paystack_reference=v_res.rent_payment_reference
      and status='pending'
  ) then raise exception 'Complete the current rent checkout before changing tenure'; end if;
  select * into v_listing from public.listings where id::text=v_res.listing_id for share;
  if v_listing.id is null or coalesce(v_listing.sub_type,'long_stay')<>'long_stay' then
    raise exception 'Yearly tenure plans apply only to Long Let';
  end if;
  if coalesce(v_listing.price,0)<=0 then raise exception 'Listing rent is invalid'; end if;
  if p_plan_years>1 then
    if not coalesce(v_listing.future_installments_allowed,false) then
      raise exception 'This Property Partner has not enabled future-year installments';
    end if;
    select * into v_policy from public.creator_policy_versions
    where policy_key='future_long_let_installments' and scope_type='global'
      and scope_key='*' and status='active' and effective_from<=now()
      and (effective_until is null or effective_until>now())
    order by effective_from desc limit 1;
    if v_policy.policy_version_id is null or coalesce((v_policy.value->>'enabled')::boolean,false)=false
      or coalesce((v_policy.value->>'partner_opt_in')::boolean,false)=false
      or coalesce((v_policy.value->>'payment_protection_hold')::boolean,true)=true then
      raise exception 'Future-year installment policy is unavailable';
    end if;
  end if;
  v_annual:=round(v_listing.price,2); v_total:=round(v_annual*p_plan_years,2);
  v_upfront:=v_annual; v_balance:=round(v_annual*greatest(p_plan_years-1,0),2);
  v_count:=8*greatest(p_plan_years-1,0);
  update public.reservations set rental_plan_years=p_plan_years,
    rental_plan_selected_at=now(),annual_rent_snapshot=v_annual,
    contract_rent_total=v_total,upfront_rent_required=v_upfront,
    installment_balance=v_balance,installment_count=v_count,
    rent_payment_status='not_started',rent_payment_reference=null,updated_at=now()
  where id=v_res.id returning * into v_res;
  if p_plan_years>1 then
    insert into public.obligation_policy_snapshots(
      subject_type,subject_id,policy_version_id,calculated_value
    ) values('long_let_installment_plan',v_res.id,v_policy.policy_version_id,
      jsonb_build_object('listing_id',v_listing.id,'partner_opt_in',true,
        'years',p_plan_years,'year_one_due',v_upfront,'future_balance',v_balance,
        'installment_count',v_count,'payment_protection_hold',false))
    on conflict(subject_type,subject_id,policy_version_id) do nothing;
  end if;
  return v_res;
end
$$;


--
-- Name: update_my_roommate_match_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_roommate_match_status(p_match_id uuid, p_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor public.profiles;
  v_match public.roommate_search_results;
  v_reverse public.roommate_search_results;
  v_conversation_id uuid;
begin
  if p_status not in ('new', 'viewed', 'accepted', 'declined') then raise exception 'Invalid match status'; end if;
  select * into v_actor from public.profiles where auth_id = auth.uid()::text limit 1;
  if v_actor is null or v_actor.role <> 'user' or coalesce(v_actor.deleted, false)
     or coalesce(v_actor.suspended, false) or coalesce(v_actor.banned, false) then
    raise exception 'Active regular user required';
  end if;
  select * into v_match from public.roommate_search_results
  where id = p_match_id and searcher_id = v_actor.user_id for update;
  if v_match is null then raise exception 'Match not found'; end if;

  update public.roommate_search_results
  set status = p_status, updated_at = now()
  where id = p_match_id;

  if p_status = 'accepted' then
    if v_match.status is distinct from 'accepted' then
      insert into public.notifications(recipient_id, type, title, message, related_id, read)
      select v_match.matched_user_id, 'roommate_interest', 'New roommate interest',
        coalesce(nullif(v_actor.full_name, ''), nullif(v_actor.username, ''), 'Someone') || ' is interested in being roommates with you.',
        v_match.id::text, false
      where not exists (
        select 1 from public.notifications notification
        where notification.recipient_id = v_match.matched_user_id
          and notification.type = 'roommate_interest'
          and notification.related_id = v_match.id::text
          and not notification.read
      );
    end if;

    select * into v_reverse from public.roommate_search_results
    where searcher_id = v_match.matched_user_id
      and matched_user_id = v_actor.user_id
      and status = 'accepted'
    limit 1;

    if v_reverse is not null then
      select conversation.id into v_conversation_id
      from public.conversations conversation
      where conversation.conversation_type = 'roommate'
        and ((conversation.participant_a = v_actor.user_id and conversation.participant_b = v_match.matched_user_id)
          or (conversation.participant_b = v_actor.user_id and conversation.participant_a = v_match.matched_user_id))
      order by (conversation.status = 'active') desc, conversation.created_at
      limit 1;

      update public.notifications set read = true
      where recipient_id = v_match.matched_user_id
        and type = 'roommate_interest'
        and related_id = v_match.id::text;

      insert into public.notifications(recipient_id, type, title, message, related_id, read, destination_route)
      select v_match.matched_user_id, 'roommate_match', 'You have a roommate match',
        'You both expressed interest. Open Roommates when you want to start a conversation.',
        coalesce(v_conversation_id::text, v_match.id::text), false, 'roommate'
      where not exists (
        select 1 from public.notifications notification
        where notification.recipient_id = v_match.matched_user_id
          and notification.type = 'roommate_match'
          and notification.related_id = coalesce(v_conversation_id::text, v_match.id::text)
      );
    end if;
  end if;
  return v_conversation_id;
end;
$$;


--
-- Name: update_platform_setting(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_platform_setting(p_key text, p_value text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare v_actor public.profiles;
begin
 select * into v_actor from public.profiles where auth_id=auth.uid()::text and deleted_at is null limit 1;
 if v_actor is null or v_actor.role<>'creator' then raise exception 'Only Creator can update global platform settings'; end if;
 update public.platform_settings set value=p_value,updated_at=now() where key=p_key and editable=true;
 if found then insert into public.audit_logs(action,target_type,target_id,details,admin_id,admin_email) values('PLATFORM_SETTING_UPDATED','platform_settings',p_key,jsonb_build_object('key',p_key)::text,v_actor.user_id,v_actor.email); end if;
 return found;
end;
$$;


--
-- Name: update_staff_trust_checklist(text, boolean, boolean, boolean, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_staff_trust_checklist(p_staff_id text, p_supervisor_confirmed boolean, p_orientation_completed boolean, p_role_training_completed boolean, p_code_of_conduct_confirmed boolean, p_probation_observation_completed boolean, p_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor public.profiles; v_target public.profiles;
BEGIN
  SELECT * INTO v_actor FROM public.profiles
  WHERE auth_id=auth.uid()::text AND role IN('admin','creator')
    AND COALESCE(deleted,false)=false AND COALESCE(suspended,false)=false AND COALESCE(banned,false)=false LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Admin or Creator access required'; END IF;
  SELECT * INTO v_target FROM public.profiles WHERE user_id=p_staff_id AND role='staff' AND COALESCE(deleted,false)=false LIMIT 1;
  IF v_target IS NULL THEN RAISE EXCEPTION 'Staff profile not found'; END IF;
  IF v_actor.role='admin' AND (v_actor.assigned_state IS DISTINCT FROM v_target.assigned_state OR v_actor.assigned_lga IS DISTINCT FROM v_target.assigned_lga) THEN
    RAISE EXCEPTION 'Admin can review only Staff in the same assigned branch';
  END IF;
  INSERT INTO public.staff_trust_profiles(
    staff_id,status,appointed_by,appointed_at,supervisor_confirmed,orientation_completed,role_training_completed,code_of_conduct_confirmed,probation_observation_completed,notes,updated_at
  ) VALUES(
    p_staff_id,'probation',v_actor.user_id,now(),p_supervisor_confirmed,p_orientation_completed,p_role_training_completed,p_code_of_conduct_confirmed,p_probation_observation_completed,NULLIF(BTRIM(COALESCE(p_notes,'')),''),now()
  ) ON CONFLICT(staff_id) DO UPDATE SET
    supervisor_confirmed=EXCLUDED.supervisor_confirmed,orientation_completed=EXCLUDED.orientation_completed,role_training_completed=EXCLUDED.role_training_completed,
    code_of_conduct_confirmed=EXCLUDED.code_of_conduct_confirmed,probation_observation_completed=EXCLUDED.probation_observation_completed,notes=EXCLUDED.notes,updated_at=now();
  INSERT INTO public.audit_logs(action,target_type,target_id,details,admin_id,admin_email)
  VALUES('STAFF_TRUST_CHECKLIST','profiles',p_staff_id,jsonb_build_object(
    'supervisor_confirmed',p_supervisor_confirmed,'orientation_completed',p_orientation_completed,'role_training_completed',p_role_training_completed,
    'code_of_conduct_confirmed',p_code_of_conduct_confirmed,'probation_observation_completed',p_probation_observation_completed,
    'state',v_target.assigned_state,'lga',v_target.assigned_lga
  )::text,v_actor.user_id,v_actor.email);
  RETURN true;
END;
$$;


--
-- Name: bank_accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id text NOT NULL,
    account_number text NOT NULL,
    bank_code text NOT NULL,
    bank_name text NOT NULL,
    account_name text,
    paystack_recipient_code text,
    is_default boolean DEFAULT false,
    verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    is_active boolean DEFAULT true NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    activated_at timestamp with time zone,
    deactivated_at timestamp with time zone
);


--
-- Name: upsert_my_bank_account(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_my_bank_account(p_bank_name text, p_account_number text, p_account_name text) RETURNS public.bank_accounts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$ DECLARE v_user_id text; v_account public.bank_accounts; BEGIN SELECT user_id INTO v_user_id FROM public.profiles WHERE auth_id=auth.uid()::text AND role IN ('worker','property_partner') AND deleted=false AND suspended=false AND banned=false; IF v_user_id IS NULL THEN RAISE EXCEPTION 'Payout account is available only to active workers and property partners'; END IF; IF p_account_number !~ '^[0-9]{10}$' THEN RAISE EXCEPTION 'Bank account number must contain 10 digits'; END IF; UPDATE public.bank_accounts SET is_default=false WHERE user_id=v_user_id; INSERT INTO public.bank_accounts(user_id,bank_name,account_number,account_name,is_default) VALUES(v_user_id,trim(p_bank_name),p_account_number,trim(p_account_name),true) RETURNING * INTO v_account; RETURN v_account; END; $_$;


--
-- Name: user_has_active_workspace(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_active_workspace(p_user_id text, p_workspace_role text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1
    from public.profiles profile
    where profile.user_id=p_user_id
      and not coalesce(profile.deleted,false)
      and not coalesce(profile.suspended,false)
      and not coalesce(profile.banned,false)
      and (
        profile.role=p_workspace_role
        or exists(
          select 1
          from public.workspace_role_assignments assignment
          where assignment.user_id=profile.user_id
            and assignment.workspace_role=p_workspace_role
            and assignment.status='active'
        )
      )
  );
$$;


--
-- Name: validate_hotel_timezone(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_hotel_timezone() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if nullif(btrim(coalesce(new.timezone,'')),'') is null
     or not exists(select 1 from pg_catalog.pg_timezone_names where name=new.timezone) then
    raise exception 'Choose a valid IANA hotel timezone';
  end if;
  return new;
end;
$$;


--
-- Name: validate_my_property_access_challenge(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_my_property_access_challenge(p_challenge_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.profiles;
  v_row public.property_access_challenges;
  v_valid boolean;
begin
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null
     or not public.current_actor_has_workspace('property_partner',null) then
    raise exception 'Property Partner workspace required';
  end if;
  select * into v_row
  from public.property_access_challenges
  where id=p_challenge_id and partner_id=v_actor.user_id
  for update;
  if v_row.id is null then raise exception 'Property access challenge not found'; end if;
  v_valid:=v_row.status in ('prepared','submitted') and v_row.expires_at>now();
  if not v_valid and v_row.status='prepared' then
    update public.property_access_challenges
    set status='expired' where id=v_row.id;
  end if;
  return jsonb_build_object(
    'valid',v_valid,
    'status',case when v_valid then v_row.status else 'expired' end,
    'expires_at',v_row.expires_at
  );
end
$$;


--
-- Name: verify_branch_booking_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_branch_booking_code(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_actor public.profiles;
  v_code text:=upper(btrim(coalesce(p_code,'')));
  v_result jsonb;
  v_state text;
  v_lga text;
begin
  if v_code !~ '^[A-Z]{3}WH[0-9]{5}$' then raise exception 'Enter a valid WeHouse booking code'; end if;
  select * into v_actor
  from public.profiles
  where auth_id=(select auth.uid())::text
    and role in ('staff','admin','creator')
    and not coalesce(deleted,false)
    and not coalesce(suspended,false)
    and not coalesce(banned,false)
  limit 1;
  if v_actor is null then raise exception 'Operations access required'; end if;
  if v_actor.role='staff' and not public.current_staff_has_permission('operations') then
    raise exception 'Operations module required';
  end if;

  select jsonb_build_object(
    'kind','housing','code',r.booking_code,'status',r.status,'payment_status',r.rent_payment_status,
    'reservation_fee_status',r.manual_payment_status,'stay_type',coalesce(r.stay_type,'long_stay'),
    'customer_name',coalesce(p.full_name,p.username,r.user_email),'customer_phone',coalesce(p.phone,r.user_phone),
    'property_name',coalesce(l.title,r.listing_title),'state',l.state,'lga',l.city,'reservation_id',r.id,
    'listing_id',r.listing_id,'check_in',r.stay_check_in,'check_out',r.stay_check_out,
    'guest_count',coalesce(r.guest_count,1),'requested_move_in_at',r.requested_move_in_at,
    'tenancy_start_date',r.tenancy_start_date,'tenancy_end_date',r.tenancy_end_date,
    'valid',(r.manual_payment_status in ('paid','completed') and r.paid_at is not null
      and r.rent_payment_status in ('paid','upfront_paid') and r.rent_paid_at is not null),
    'can_handover',(coalesce(r.stay_type,'long_stay')='long_stay' and r.status='ready_for_move_in'
      and r.manual_payment_status in ('paid','completed') and r.paid_at is not null
      and r.rent_payment_status in ('paid','upfront_paid') and r.rent_paid_at is not null
      and r.requested_move_in_at is not null),
    'can_check_in',(r.stay_type='short_let' and r.status='ready_for_move_in'
      and r.manual_payment_status in ('paid','completed') and r.paid_at is not null
      and r.rent_payment_status='paid' and r.rent_paid_at is not null
      and current_date>=r.stay_check_in and current_date<r.stay_check_out)
  ),l.state,l.city
  into v_result,v_state,v_lga
  from public.reservations r
  join public.listings l on l.id::text=r.listing_id or l.listing_id=r.listing_id
  left join public.profiles p on p.user_id=r.user_id
  where r.booking_code=v_code
  limit 1;

  if v_result is null then
    select jsonb_build_object(
      'kind','hotel','code',hb.booking_code,'status',hb.status,'payment_status',hb.payment_status,
      'customer_name',coalesce(p.full_name,p.username,hb.guest_name),'customer_phone',coalesce(p.phone,hb.guest_phone),
      'property_name',h.name,'state',h.state,'lga',h.city,'booking_id',hb.booking_id,'hotel_id',hb.hotel_id,
      'check_in',hb.check_in,'check_out',hb.check_out,'guest_count',hb.guest_count,
      'valid',(hb.payment_status='paid' and hb.status not in ('cancelled','refunded')),
      'can_check_in',(hb.payment_status='paid' and hb.status in ('confirmed','paid')
        and current_date>=hb.check_in and current_date<hb.check_out)
    ),h.state,h.city
    into v_result,v_state,v_lga
    from public.hotel_bookings hb
    join public.hotels h on h.hotel_id=hb.hotel_id
    left join public.profiles p on p.user_id=hb.user_id
    where hb.booking_code=v_code
    limit 1;
  end if;
  if v_result is null then return null; end if;
  if v_actor.role<>'creator' and not public.current_actor_in_scope(v_state,v_lga) then
    raise exception 'This booking belongs to another WeHouse branch';
  end if;
  return v_result;
end;
$_$;


--
-- Name: verify_google_password_recovery(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_google_password_recovery() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_auth_id text := (select auth.uid())::text;
  v_email text := lower(nullif(btrim((select auth.jwt() ->> 'email')), ''));
  v_google_verified boolean := false;
begin
  select exists(
    select 1
    from jsonb_array_elements(coalesce((select auth.jwt() -> 'amr'), '[]'::jsonb)) as method
    where method ->> 'method' = 'oauth'
  ) into v_google_verified;

  if v_auth_id is null or v_email is null or not v_google_verified then
    raise exception 'Continue with Google is required';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.auth_id = v_auth_id
      and lower(p.email) = v_email
      and not coalesce(p.deleted, false)
  ) then
    raise exception 'Matching WeHouse account not found';
  end if;

  return jsonb_build_object('success', true, 'email', v_email);
end;
$$;


--
-- Name: wehouse_lga_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wehouse_lga_key(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  select regexp_replace(
    regexp_replace(lower(btrim(coalesce(p_value,''))), '[^a-z0-9]+', '', 'g'),
    '(localgovernmentarea|lga)$',
    ''
  );
$_$;


--
-- Name: wehouse_state_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wehouse_state_key(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  select regexp_replace(
    regexp_replace(lower(btrim(coalesce(p_value,''))), '[^a-z0-9]+', '', 'g'),
    'state$',
    ''
  );
$_$;


--
-- Name: worker_accept_booking(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_accept_booking(p_booking_id uuid, p_negotiated_amount numeric, p_scheduled_date text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare w public.profiles;b public.worker_bookings;v_date date;
begin
  select * into w from public.profiles where auth_id=auth.uid()::text for update;
  if w is null or not public.user_has_active_workspace(w.user_id,'worker') then raise exception 'Worker account required'; end if;
  if w.worker_status<>'verified' or w.worker_verified is distinct from true then raise exception 'Verified Worker account required'; end if;
  if not public.worker_identity_is_current(w.user_id) then raise exception 'Repeat your WeHouse identity check before accepting new work'; end if;
  if coalesce(w.deleted,false) or coalesce(w.suspended,false) or coalesce(w.banned,false) then raise exception 'Worker account is not active'; end if;
  if p_negotiated_amount is null or p_negotiated_amount<=0 then raise exception 'Agreed amount must be positive'; end if;
  if nullif(trim(coalesce(p_scheduled_date,'')),'') is not null then v_date:=p_scheduled_date::date; if v_date<current_date then raise exception 'Schedule date cannot be in the past'; end if; end if;
  select * into b from public.worker_bookings where id=p_booking_id for update;
  if b is null then raise exception 'Booking not found'; end if;
  if b.worker_id<>w.user_id then raise exception 'Not authorized'; end if;
  if b.status not in ('booking_requested','negotiating') then raise exception 'Booking cannot be accepted in current status: %',b.status; end if;
  update public.worker_bookings set status='waiting_payment',negotiated_amount=round(p_negotiated_amount,2),agreed_amount=round(p_negotiated_amount,2),scheduled_date=coalesce(v_date,scheduled_date),updated_at=now() where id=p_booking_id;
  return true;
end;
$$;


--
-- Name: worker_booking_money_state(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_booking_money_state(p_payment_status text, p_protection_status text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case
    when lower(coalesce(p_protection_status,'')) in ('refunded','reversed') then 'refunded'
    when lower(coalesce(p_protection_status,'')) in ('released','paid_out') then 'released'
    when lower(coalesce(p_protection_status,'')) in ('release_pending','releasing') then 'release_pending'
    when lower(coalesce(p_protection_status,'')) in ('review','under_review','frozen','disputed') then 'review'
    when lower(coalesce(p_protection_status,'')) in ('protected','payment_protected','secured','held','holding') then 'protected'
    when lower(coalesce(p_payment_status,'')) in ('refunded','reversed') then 'refunded'
    when lower(coalesce(p_payment_status,'')) in ('review_required') then 'review'
    -- Verified money without the required protection record is an invariant
    -- failure which must be reviewed, never silently presented as protected.
    when lower(coalesce(p_payment_status,'')) in ('paid','completed') then 'review'
    when lower(coalesce(p_payment_status,'')) in ('pending','payment_pending','processing') then 'payment_pending'
    else 'unpaid'
  end
$$;


--
-- Name: worker_identity_is_current(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_identity_is_current(p_worker_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists(
    select 1 from public.worker_identity_checks wic
    where wic.worker_id=p_worker_id
      and wic.status='passed'
      and wic.captured_at is not null
      and wic.captured_at + make_interval(days=>public.worker_identity_recheck_days()) > now()
  );
$$;


--
-- Name: worker_identity_recheck_days(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_identity_recheck_days() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$ select public.account_identity_recheck_days() $$;


--
-- Name: worker_mark_complete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_mark_complete(p_booking_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_booking public.worker_bookings; v_from text;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null or not public.current_actor_has_workspace('worker') then
    raise exception 'Active Worker workspace required';
  end if;
  select * into v_booking from public.worker_bookings where id=p_booking_id for update;
  if v_booking.id is null or v_booking.worker_id<>v_actor.user_id then
    raise exception 'Job not found';
  end if;
  if v_booking.status='completed_pending_approval'
    and v_booking.canonical_job_state='completion_marked' then return true; end if;
  if v_booking.status<>'in_progress' then raise exception 'Job is not in progress'; end if;
  v_from:=coalesce(v_booking.canonical_job_state,'in_progress');
  if v_from<>'in_progress' then raise exception 'Canonical job is not in progress'; end if;
  update public.worker_bookings set
    status='completed_pending_approval',canonical_job_state='completion_marked',
    worker_approved=true,marked_complete_at=coalesce(marked_complete_at,now()),
    release_eligible_at=now()+interval '24 hours',
    help_until=coalesce(help_until,now()+interval '3 days'),updated_at=now()
  where id=p_booking_id;
  insert into public.worker_job_transitions(
    worker_booking_id,from_state,to_state,event_type,event_key,actor_user_id,
    actor_type,policy_version_id,metadata
  ) values(p_booking_id,v_from,'completion_marked','worker_marked_complete',
    'worker-completion-marked:'||p_booking_id,v_actor.user_id,'worker',
    v_booking.policy_version_id,jsonb_build_object(
      'release_eligible_after_hours',24,'reminder_available_after_hours',12,
      'help_window_days',3)) on conflict(event_key) do nothing;
  return true;
end
$$;


--
-- Name: worker_pro_billing_period_for_product(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_pro_billing_period_for_product(p_provider text, p_product_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case
    when nullif(btrim(coalesce(p_product_id,'')),'') is null then null
    when p_provider='paystack' and p_product_id=(
      select value from public.platform_settings
      where key='worker_pro_web_paystack_yearly_plan_code' and is_active=true
    ) then 'yearly'
    when p_provider='apple' and p_product_id=(
      select value from public.platform_settings
      where key='worker_pro_apple_yearly_product_id' and is_active=true
    ) then 'yearly'
    when p_provider='google' and p_product_id=(
      select value from public.platform_settings
      where key='worker_pro_google_yearly_product_id' and is_active=true
    ) then 'yearly'
    when p_provider='paystack' and p_product_id=(
      select value from public.platform_settings
      where key='worker_pro_web_paystack_plan_code' and is_active=true
    ) then 'monthly'
    when p_provider='apple' and p_product_id=(
      select value from public.platform_settings
      where key='worker_pro_apple_product_id' and is_active=true
    ) then 'monthly'
    when p_provider='google' and p_product_id=(
      select value from public.platform_settings
      where key='worker_pro_google_product_id' and is_active=true
    ) then 'monthly'
    else null
  end;
$$;


--
-- Name: worker_pro_is_active(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_pro_is_active(p_worker_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1 from public.worker_pro_subscriptions subscription
    where subscription.worker_id=p_worker_id
      and subscription.status in ('active','grace_period')
      and subscription.current_period_end>now()
  );
$$;


--
-- Name: worker_professional_profile_ready(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_professional_profile_ready(p_worker_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(
    select 1 from public.profiles profile
    where profile.user_id=p_worker_id
      and public.user_has_active_workspace(profile.user_id,'worker')
      and coalesce(profile.profile_complete,false)=true
      and nullif(btrim(coalesce(profile.full_name,'')),'') is not null
      and nullif(btrim(coalesce(profile.worker_occupation,'')),'') is not null
      and jsonb_typeof(coalesce(profile.worker_skills,'[]'::jsonb))='array'
      and jsonb_array_length(coalesce(profile.worker_skills,'[]'::jsonb))>0
      and nullif(btrim(coalesce(profile.state,'')),'') is not null
      and nullif(btrim(coalesce(profile.local_government,profile.city,'')),'') is not null
      and not coalesce(profile.deleted,false)
      and not coalesce(profile.suspended,false)
      and not coalesce(profile.banned,false)
      and exists(
        select 1 from public.worker_service_coverage coverage
        where coverage.worker_id=profile.user_id
          and nullif(btrim(coalesce(coverage.state,'')),'') is not null
          and nullif(btrim(coalesce(coverage.lga,'')),'') is not null
      )
  );
$$;


--
-- Name: worker_request_completion_reminder(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_request_completion_reminder(p_worker_booking_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor text:=public.current_profile_user_id(); v_booking public.worker_bookings; v_id uuid;
begin
  select * into v_booking from public.worker_bookings
  where id=p_worker_booking_id and worker_id=v_actor for update;
  if v_booking.id is null then raise exception 'Worker job not found'; end if;
  if coalesce(v_booking.canonical_job_state,'')<>'completion_marked'
    or v_booking.marked_complete_at+interval '12 hours'>now() then
    raise exception 'The completion reminder becomes available after 12 hours'; end if;
  if v_booking.risk_flag or v_booking.payment_conflict or v_booking.chargeback_open then
    raise exception 'This job is already in controlled review'; end if;
  insert into public.worker_completion_reminder_requests(worker_booking_id,requested_by)
  values(v_booking.id,v_actor)
  on conflict(worker_booking_id) do update set requested_by=excluded.requested_by
  returning reminder_request_id into v_id;
  update public.worker_bookings set completion_reminder_sent_at=coalesce(
    completion_reminder_sent_at,now()
  ),updated_at=now() where id=v_booking.id;
  return v_id;
end
$$;


--
-- Name: worker_start_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.worker_start_job(p_booking_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_actor public.profiles; v_booking public.worker_bookings; v_from text;
begin
  select * into v_actor from public.profiles
  where auth_id=(select auth.uid())::text and not coalesce(deleted,false)
    and not coalesce(suspended,false) and not coalesce(banned,false) limit 1;
  if v_actor.user_id is null or not public.current_actor_has_workspace('worker')
    or v_actor.worker_status<>'verified' or v_actor.worker_verified is distinct from true then
    raise exception 'Active verified Worker workspace required';
  end if;
  if not public.worker_identity_is_current(v_actor.user_id) then
    raise exception 'Repeat your WeHouse identity check before starting new work';
  end if;
  select * into v_booking from public.worker_bookings where id=p_booking_id for update;
  if v_booking.id is null or v_booking.worker_id<>v_actor.user_id
    or v_booking.status<>'confirmed' then raise exception 'Job is not ready to start'; end if;
  if v_booking.payment_protection_id is null or not exists(
    select 1 from public.payment_protection_transactions p
    where p.id=v_booking.payment_protection_id and p.protection_state='protected'
  ) then raise exception 'Payment Protection must be confirmed before work starts'; end if;
  v_from:=coalesce(v_booking.canonical_job_state,'confirmed');
  if v_from<>'confirmed' then raise exception 'Canonical job is not ready to start'; end if;
  update public.worker_bookings set status='in_progress',canonical_job_state='in_progress',
    started_at=coalesce(started_at,now()),updated_at=now() where id=p_booking_id;
  insert into public.worker_job_transitions(
    worker_booking_id,from_state,to_state,event_type,event_key,actor_user_id,
    actor_type,policy_version_id,metadata
  ) values(p_booking_id,v_from,'in_progress','worker_started',
    'worker-started:'||p_booking_id,v_actor.user_id,'worker',v_booking.policy_version_id,
    '{}'::jsonb) on conflict(event_key) do nothing;
  return true;
end
$$;


